window.KURAN_MEALS=window.KURAN_MEALS||{};window.KURAN_MEALS["ates"]=[[{"n":1,"t":"Rahmân ve Rahim Allâh’ın adıyla"},{"n":2,"t":"Âlemlerin Rabbi (sâhibi, yetiştiricisi) Allah’a hamdolsun."},{"n":3,"t":"(O) Rahmân’dır, Rahim’dir."},{"n":4,"t":"Din (cezâ ve mükâfât) gününün sâhibidir."},{"n":5,"t":"(Ya Rabbi) Ancak sana kulluk eder, ancak Senden yardım isteriz!"},{"n":6,"t":"Bizi doğru yola ilet!"},{"n":7,"t":"ni’met verdiğin kimselerin yoluna. Kendilerine gazabedilmiş olanların ve sapmışların yoluna değil. (ya Rabbi)!"}],[{"n":1,"t":"Elif lâm mim."},{"n":2,"t":"İşte o Kitap; kendisinde hiç şüphe yoktur; müttakiler için yol göstericidir."},{"n":3,"t":"Onlar ki gaybde (gizlide, içtenlikle) inanıp namazlarını kılarlar ve kendilerine verdiğimiz rızıktan (Allâh rızâsı için) harcarlar."},{"n":4,"t":"Sana indirilene ve senden önce indirilene inanırlar; âhirete de kesinlikle iman ederler."},{"n":5,"t":"İşte onlar, Rablerinden bir hidâyet üzeredirler ve umduklarına erenler, işte onlardır!"},{"n":6,"t":"İnkâr edenlere gelince, onları uyarsan da, uyarmasan da, onlar için birdir; inanmazlar."},{"n":7,"t":"Allâh, onların kalblerini ve kulaklarını mühürlemiştir, gözlerine de perde inmiştir. Onlar için büyük bir azâb vardır."},{"n":8,"t":"İnsanlardan öyleleri de vardır ki, inanmadıkları halde \"Allah’a ve âhiret gününe inandık\" derler."},{"n":9,"t":"Allâh’ı ve mü’minleri aldatmağa çalışırlar, halbuki yalnız kendilerini aldatırlar da farkında olmazlar."},{"n":10,"t":"Onların kablerinde hastalık vardır. Allâh da hastalıklarını artırmıştır. Yalan söylemelerinden ötürü onlara acı bir azâb vardır."},{"n":11,"t":"Onlara: \"Yeryüzünde bozgunculuk yapmayın,\" dendiği zaman: \"Biz sadece düzelticileriz,\" derler."},{"n":12,"t":"İyi bilin ki, onlar bozgunculardır; fakat anlamazlar."},{"n":13,"t":"Onlara: \"İnsanların inandıkları gibi siz de inanın\" dense, \"O beyinsizlerin inandığı gibi inanır mıyız?\" derler. İyi bilin ki, asıl beyinsizler kendileridir; fakat bilmezler."},{"n":14,"t":"İnanmış olanlara rastladıkları zaman; \"İnandık,\" derler. Fakat şeytânlarıyla yalnız kaldıkları zaman; \"Biz sizinle beraberiz, biz sadece (onlarla) alay ediyoruz,\" derler."},{"n":15,"t":"Allâh da kendileriyle alay eder ve onları bırakır; taşkınları içinde bocalayıp dururlar."},{"n":16,"t":"İşte onlar o kimselerdir ki, hidâyet karşılığında sapıklığı satın aldılar da ticaretleri kar etmedi, doğru yolu da bulamadılar."},{"n":17,"t":"Onların durumu, tıpkı şuna benzer ki, (aydınlanmak için) bir ateş yakmak istedi. (Ateş) çevresini aydınlatır aydınlatmaz, Allâh onların nurunu giderdi ve onları karanlıklar içinde bıraktı, artık görmezler."},{"n":18,"t":"(Onlar) sağırdırlar, dilsizdirler, kördürler. Onlar (Hakk’a) dönmezler."},{"n":19,"t":"Ya da (onlar), gökten boşanan, içinde karanlıklar, gök gürlemesi ve şimşek (ler) bulunan bir yağmur(a tutulmuş) gibi(dirler). Yıldırım seslerinden ölüm korkusuyla parmaklarını kulaklarına tıkarlar; oysa Allâh, inkârcıları tamamen kuşatmıştır."},{"n":20,"t":"Neredeyse gözlerini kapıverecek olan şimşek önlerini aydınlattı mı o(nun ışığı)nda yürürler, üzerlerine karanlık çökünce dikilip kalırlar. Allâh dileseydi elbette işitmelerini ve görmelerini de götürürdü. Şüphesiz Allâh’ın her şeyi yapmaya gücü yeter."},{"n":21,"t":"Ey insanlar, sizi ve sizden öncekileri yaratan Rabbinize kulluk edin ki, (azaptan) korunasınız."},{"n":22,"t":"O (Rabb) ki yeri, sizin için döşek, göğü de bina yaptı. Gökten su indirdi, onunla size rızık olarak çeşitli ürünler çıkardı. Öyleyse siz de, bile bile Allah’a eşler koşmayın."},{"n":23,"t":"Eğer kulumuz (Muhammed)e indirdiğimizden şüphe içinde iseniz, haydi onun gibi bir sûre getirin. Allah’tan başka bütün şâhid (yardımcı)larınızı da çağırın; eğer doğru iseniz (bunu yapın)."},{"n":24,"t":"Yok eğer yapamadınızsa, ki asla yapamayacaksınız, o halde yakıtı insanlar ve taşlar olan, inkârcılar için hazırlanmış ateşten sakının."},{"n":25,"t":"İnanıp yararlı işler yapanlara, altlarından ırmaklar akan cennetlerin kendilerine âit olduğunu müjdele! Onlardaki herhangi bir meyveden rızıklandırıldıkça: \"Bu, daha önce de rızıklandığımız şeydir, (dünyâda iken de bu rızıktan yemiştik)\" derler. (Cennetteki bu rızık), onlara, o(dedikleri)ne benzer verilmiştir. Onlar için orada tertemiz eşler de vardır ve onlar orada ebedi kalacaklardır."},{"n":26,"t":"Allâh, bir sivrisineği hattâ onun da üstünde olan(ondan daha zayıf bir varlığ)ı misal vermekten utanmaz. İnananlar onun, Rablerinden (gelen) bir gerçek olduğunu bilirler. İnkâr edenler ise: \"Allâh, bu misalle ne demek istedi?\" derler. (Allâh), onunla birçoğunu saptırır ve yine onunla birçoğunu yola getirir. Onunla sadece fâsıkları saptırır."},{"n":27,"t":"Onlar ki, söz verip bağlandıktan sonra Allah’a verdikleri sözü bozarlar, Allâh’ın, birleştirmesini emrettiği şeyi (iman ve akrabâlık bağlarını) keserler ve yeryüzünde bozgunculuk yaparlar; işte ziyana uğrayanlar onlardır."},{"n":28,"t":"Allah’a nasıl nankörlük edersiniz ki, siz ölüler idiniz, O sizi diriltti; yine öldürecek, yine diriltecek; sonra O’na döndürüleceksiniz."},{"n":29,"t":"O ki, yeryüzünde ne varsa hepsini sizin için yarattı; sonra göğe yöneldi, onları yedi gök olarak düzenledi. O, herşeyi bilir."},{"n":30,"t":"Bir zamanlar Rabbin meleklere: \"Ben yeryüzünde bir halife yapacağım,\" demişti. (Melekler): \"Orada bozgunculuk yapan, kan döken birisini mi halife yapacaksın? Oysa biz seni överek tesbih ediyor ve seni takdis ediyoruz?\" dediler. (Rabbin): Ben sizin bilmediklerinizi bilirim,\" dedi."},{"n":31,"t":"Âdem’e isimlerin tümünü öğretti, sonra onları meleklere sunup: \"Haydi, doğru iseniz onların isimlerini bana söyleyin,\" dedi."},{"n":32,"t":"Dediler ki: \"Sen yücesin (ya Rab); bizim senin bize öğrettiğinden başka bilgimiz yoktur. Şüphesiz sen bilensin, hakimsin (her şeyin içyüzünü bilen, her şeyi yerli yerince yapansın.)"},{"n":33,"t":"(Allâh) dedi ki: \"Ey Âdem, bunlara onların isimlerini haber ver.\" (Âdem), bunlara onların isimlerini haber verince (Allâh): \"Ben size, ben göklerin ve yerin gayblarını bilirim, sizin açıkladığınızı ve içinizde gizlemekte olduğunuz şeyleri bilirim, dememiş miydim? dedi"},{"n":34,"t":"Meleklere: \"Âdem’e secde edin\" demiştik, hemen secde ettiler: Yalnız İblis diretti, böbürlendi, nankörlerden oldu."},{"n":35,"t":"Dedik ki: \"Ey Âdem, sen ve eşin cennette oturun, ondan dilediğiniz yerde bol bol yeyin, ama şu ağaca yaklaşmayın, yoksa zâlimlerden olursunuz!\""},{"n":36,"t":"Derken şeytân onlar(ın ayağın)ı oradan kaydırdı, içinde bulundukları (ni’met yurdu)ndan çıkardı. (Biz de) dedik ki: \"Birbirinize düşman olarak inin. Sizin, yeryüzünde kalıp bir süre yaşamanız lâzımdır.\""},{"n":37,"t":"Âdem, Rabbinden birtakım kelimeler aldı (onlarla amel edip Rabbine yalvardı, O da) bunun üzerine onun tevbesini kabul etti. Şüphesiz O, tevbeyi çok kabul eden (kulunun günâhından geçen) dir, çok esirgeyendir."},{"n":38,"t":"\"Hepiniz oradan inin,\" dedik, \"Yalnız (iyi bilin ki) size benden bir hidâyet geldiği zaman, kimler benim hidâyetime uyarsa artık onlara bir korku yoktur ve onlar üzülmeyeceklerdir."},{"n":39,"t":"\"İnkâr edip âyetlerimizi yalanlayanlar ise ateş halkıdır, onlar orada ebedi kalacaklardır.\""},{"n":40,"t":"Ey İsrâil oğulları, size verdiğim ni’metleri hatırlayın, bana verdiğiniz sözü tutun ki, ben de size verdiğim sözü tutayım ve sadece benden korkun!"},{"n":41,"t":"Sizin yanınızda bulunanı doğrulayıcı olarak indirmiş bulunduğum (Kur’ân)a inanın ve onu ilk inkâr eden, siz olmayın; benim âyetlerimi birkaç paraya satmayın ve benden sakının."},{"n":42,"t":"Bile bile gerçeği bâtılla bulayıp hakkı gizlemeyin."},{"n":43,"t":"Namazı kılın, zekâtı verin, rükû edenlerle (Allâh’ın huzûrunda eğilenlerle) beraber eğilin."},{"n":44,"t":"Siz Kitabı okuduğunuz halde, insanlara iyiliği emredip kendinizi unutuyor musunuz? Aklınızı kullanmıyor musunuz?"},{"n":45,"t":"Sabırla, namazla Allah’tan yardım dileyin, şüphesiz bu, (Allah’a) saygı gösterenlerden başkasına ağır gelir."},{"n":46,"t":"O(saygılı insa)nlar, Rablerine kavuşacaklarını (gözetir) ve gerçekten O’na döneceklerini bilirler."},{"n":47,"t":"Ey İsrâil oğulları, size verdiğim ni’meti ve sizi âlemlere üstün kıldığımı hatırlayın."},{"n":48,"t":"Ve öyle bir günden sakının ki, o gün hiç kimse, kimsenin cezâsını çekmez (borcunu ödemez); kimseden şefâat (aracılık, iltimas) da kabul edilmez; kimseden fidye de alınmaz ve onlara hiçbir yardım yapılmaz."},{"n":49,"t":"Sizi Fir’avn âilesinden de kurtarmıştık. Hani (onlar), size azâbın en kötüsünü reva görüyor, oğullarınızı boğazlayıp, kadınlarınızı sağ bırakıyorlardı ve bunda sizin için Rabbinizden büyük bir imtihan vardı."},{"n":50,"t":"Sizin için denizi yarmıştık, sizi kurtarmış ve Fir’avn âilesini boğmuştuk; siz de bunu görüyordunuz."},{"n":51,"t":"Mûsâ ile kırk gece için sözleşmiştik, sonra siz onun ardından buzağıyı (tanrı) edinmiştiniz, (kendinize böylece) zulmediyordunuz."},{"n":52,"t":"Bundan sonra da yine belki şükredersiniz diye sizi affetmiştik."},{"n":53,"t":"Yola gelesiniz diye Mûsâ’ya Kitap ve furkan (gerçekle bâtılı birbirinden ayıran ölçü) vermiştik."},{"n":54,"t":"Mûsâ kavmine demişti ki: \"Ey kavmim, sizler, buzağıyı (tanrı) edinmekle kendinize zulmettiniz; gelin Yaratıcınıza tevbe edin de nefislerinizi öldürün. Bu, Yaratıcınız katında sizin için daha iyidir. (Bu sûretle O), sizin tevbenizi kabul buyurmuş olur. Çünkü O, öyle bağışlayıcı, öyle merhametlidir."},{"n":55,"t":"Bir zaman da: \"Ey Mûsâ, biz Allâh’ı açıkça görmedikçe sana inanmayız,\" demiştiniz de derhal sizi yıldırım gürültüsü yakalamıştı; siz de bunu görüyordunuz."},{"n":56,"t":"Sonra belki şükredersiniz diye sizi ölümünüzün ardından tekrar diriltmiştik."},{"n":57,"t":"bulutu üstünüze gölgelik çektik, size kudret helvası ve bıldırcın indirdik: \"Size verdiğimiz güzel rızıklardan yeyin,\" (dedik). Ama onlar bize değil, kendi kendilerine zulmediyorlardı."},{"n":58,"t":"Demiştik ki: \"Şu kente girin, oradan dilediğiniz yerde bol bol yeyin; secde ederek kapıdan girin ve \"hitta (ya Rabbi, bizi affet)\" deyin ki, biz de sizin hatâlarınızı bağışlayalım, güzel davrananlara daha fazlasını da veririz."},{"n":59,"t":"Derken o zâlimler, onu, kendilerine söylenenden başka bir sözle değiştirdiler. Biz de yaptıkları kötülüklerden dolayı o zulmedenlerin üzerine gökten bir azâb indirdik."},{"n":60,"t":"Bir zaman da Mûsâ, kavmi için su istemişti; \"Asanla taşa vur,\" demiştik. Bunun üzerine taştan on iki göze fışkırmıştı. Her bölük, kendi içecekleri pınarı bilmişti: \"Allâh’ın rızkından yeyin, için ve yeryüzünde bozgunculuk yaparak (başkalarına) saldırmayın.\" (demiştik.)"},{"n":61,"t":"Hani siz demiştiniz ki: \"Ey Mûsâ, biz bir yemeğe dayanamayız, bizim için Rabbine du’â et de bize yerin bitirdiği sebzesinden, acurundan, sarımsağından, mercimeğinden, soğanından çıkarsın.\" (Mûsâ): \"İyi olanı, daha aşağı olanla mı değiştirmek istiyorsunuz? Bir şehre inin, orada size istediğiniz var,\" demişti. Üzerlerine alçaklık ve yoksulluk damgası vuruldu; Allâh’ın gazabına uğradılar. Öyle oldu, çünkü onlar, Allâh’ın âyetlerini inkâr ediyorlar ve haksız yere peygamberleri öldürüyorlardı. İsyana daldıkları, sınırı aştıkları için bunu hak ettiler."},{"n":62,"t":"Şüphesiz inananlar; yahûdiler, hıristiyanlar ve sâbiiler(den) Allah’a ve âhiret gününe inanan ve iyi iş(ler) yapanlara, Rableri katında mükâfât vardır; onlara korku yoktur ve onlar üzülmeyeceklerdir."},{"n":63,"t":"Bir zaman da sizin sözünüzü almış, üzerinize dağı kaldırmıştık: \"Size verdiğimizi kuvvetle tutun, içinde olanı hatırlayın ki (azâbımızdan) korunasınız,\" (demiştik)."},{"n":64,"t":"Ardından yine dönmüştünüz; eğer Allâh’ın size iyiliği ve merhameti olmasaydı, elbette ziyana uğrayanlardan olurdunuz."},{"n":65,"t":"İçinizden, Cumartesi günü (avlanma yasağı)nı çiğneyenleri elbette bilmişsinizdir; işte onlara: \"Aşağılık maymunlar olun!\" dedik."},{"n":66,"t":"Ve bunu, önündekilere ve ardından geleceklere ibret bir cezâ, (Allâh’ın azâbından) korunanlara da bir öğüt yaptık."},{"n":67,"t":"Mûsâ, kavmine: \"Allâh size bir inek kesmenizi emrediyor.\" demişti. \"Bizimle alay mı ediyorsun?\" dediler. \"câhillerden olmaktan Allah’a sığınırım!\" dedi."},{"n":68,"t":"\"Bizim için Rabbine du’â et, onun ne olduğunu bize açıklasın.\" dediler. Dedi ki: \"O diyor ki: O (inek) ne yaşlı, ne körpe, ikisinin ortasında (bir inek)tir! Haydi, size emredileni yapın.\""},{"n":69,"t":"Dediler ki: \"Bizim için Rabbine du’â et, renginin nasıl olduğunu açıklasın.\" Dedi: \"O diyor ki: \"Rengi parlak, sarı bir inektir, bakanlara sevinç verir.\""},{"n":70,"t":"\"Bizim için Rabbine du’â et, onun nasıl bir şey olduğunu bize açıklasın. Zira o inek bize (başka ineklere) benzer geldi. Ama Allâh dilerse mutlaka (emredileni yapmağa) yol buluruz.\" dediler."},{"n":71,"t":"Dedi: \"O şöyle diyor: O, henüz boyundurluk altına alınmamış bir inektir. Yeri sürmez, ekin sulamaz. Salma, (çifte koşulmamış) hiç alacası yok.\" \"İşte şimdi gerçeği getirdin\" deyip ineği boğazladılar; az daha yapmayacaklardı."},{"n":72,"t":"Hani siz bir adam öldürmüştünüz de onun (katili) hakkında birbirinizle atışmıştınız; oysa Allâh, gizlediğinizi ortaya çıkaracaktı."},{"n":73,"t":"Onun için \"(ineğin) bir parçasıyla o (öldürülene) vurun.\" demiştik. İşte Allâh böylece ölüleri diriltir, size âyetlerini gösterir ki düşünesiniz."},{"n":74,"t":"Sonra bunun ardından yine kalbleriniz katılaştı; şimdi onlar, taş gibi, hattâ daha da katıdır. Çünkü öyle taş var ki, içinden ırmaklar fışkırır; öylesi var ki, çatlar da bağrından su kaynar, öylesi de var ki, Allâh korkusundan aşağı düşer. Allâh, yaptıklarınızı bilmez değildir."},{"n":75,"t":"Şimdi (ey mü’minler) siz, bunların size inanmalarını mı umuyorsunuz? Oysa bunlardan bir grup vardı ki, Allâh’ın sözünü işitirlerdi de düşünüp akıl erdirdikten sonra, bile bile onu değiştirirlerdi."},{"n":76,"t":"İnananlara rastladıkları zaman: \"İnandık\" derler; birbirleriyle yalnız kaldıkları zaman: \"Allâh’ın size açtığını onlara söylüyorsunuz ki, onu Rabbiniz katında sizin aleyhinizde delil olarak mı kullansınlar? Aklınızı kullanmıyor musunuz?\" derler."},{"n":77,"t":"Bilmiyorlar mı ki, Allâh onların gizlediklerini ve açığa vurduklarını biliyor?"},{"n":78,"t":"Onların içinde bir de ümmiler var ki, Kitabı bilmezler, bütün bildikleri birtakım kuruntular(yahut kulaktan dolma şeyler)dir; onlar sadece zannediyorlar."},{"n":79,"t":"Vay haline o kimselerin ki, Kitabı elleriyle yazıp, az bir paraya satmak için, \"Bu Allâh katındandır,\" derler! Ellerinin yazdığından ötürü vay haline onların! Kazandıklarından ötürü vay haline onların!"},{"n":80,"t":"Bir de dediler ki: \"Sayılı birkaç gün dışında bize ateş dokunmayacaktır.\" De ki: \"Allah’tan (bu hususta) bir söz mü aldınız. şâyet öyle ise Allâh verdiği sözden dönmez-yoksa Allâh hakkında bilmediğiniz bir şey mi söylüyorsunuz?"},{"n":81,"t":"Evet kim bir günâh kazanır da suçu kendisini kuşatmış olursa işte onlar, ateş halkıdır, orada sürekli kalacaklardır."},{"n":82,"t":"İnanıp yararlı işler yapanlara gelince, onlar da cennet halkıdır, orada sürekli kalacaklardır."},{"n":83,"t":"Biz İsrâil oğullarından şöyle söz almıştık: \"Allah’tan başkasına kulluk etmeyeceksiniz, anaya-babaya, yakınlara, yetimlere, yoksullara iyilik edeceksiniz. İnsanlara güzel söz söyleyin, namazı kılın, zekâtı verin!\" Sonra siz, pek azınız hariç, döndünüz; hâlâ da yüz çevirip duruyorsunuz."},{"n":84,"t":"\"Birbirinizin kanını dökmeyeceksiniz, birbirinizi yurtlarınızdan çıkarmayacaksınız?\" diye sizden kesin söz almıştık; göre göre bunu kabul etmiştiniz."},{"n":85,"t":"Ama siz yine birbirinizi öldürüyorsunuz, sizden bir grubu yurtlarından çıkarıyorsunuz; onlara karşı günâh ve düşmanlık yapmakta birleşiyorsunuz, onları çıkarmak size yasaklanmış iken (çıkarıyorsunuz, sonra da) esir olarak geldiklerinde fidyelerini veriyor (kurtarıyor)sunuz. Yoksa siz Kitabın bir kısmına inanıp bir kısmını inkâr mı ediyorsunuz? Sizden bunu yapanın cezâsı, dünyâ hayâtında rezil olmaktan başka nedir? Kıyâmet gününde de (onlar) azâbın en şiddetlisine itilirler. Allâh yaptıklarınızı bilmez değildir."},{"n":86,"t":"İşte onlar, âhireti verip dünyâ hayâtını satın alan kimselerdir. Onlardan azâb hiç hafifletilmez ve onlara hiç yardım edilmez."},{"n":87,"t":"Andolsun, Mûsâ’ya Kitabı verdik, arkasından peygamberler gönderdik. Meryem oğlu Îsâ’ya da açık deliller verdik ve onu Ruh’ül-Kudüs (Cebrâil) ile destekledik. Ne zaman ki, bir peygamber, size canınızın istemediği bir şey getirdiyse büyüklük taslamadınız mı? Kimini yalanladınız, kimini de öldürüyordunuz?"},{"n":88,"t":"\"Kalblerimiz, perdelidir,\" dediler. Hayır, ama inkârlarından dolayı Allâh onları la’netlemiştir, artık çok az inanırlar."},{"n":89,"t":"Ne zaman ki, onlara Allâh katından, yanlarında bulunan (Tevrat)ı doğrulayıcı bir Kitap (Kur’ân) geldi, daha önce inkâr edenlere karşı yardım isteyip dururlarken o bildikleri (Kur’ân) kendilerine gelince onu inkâr ettiler; artık Allâh’ın la’neti, inkârcıların üzerine olsun!"},{"n":90,"t":"Allâh’ın, kullarından dilediğine lutfuyla (vahiy) indirmesini çekemeyerek, Allâh’ın indirdiğini inkâr etmek için kendilerini ne alçak şeye sattılar da gazab üstüne gazaba uğradılar. İnkâr edenler için alçaltıcı bir azâb vardır."},{"n":91,"t":"Onlara: \"Allâh’ın indirdiğine inanın!\" denilse, \"Bize indirilene inanırız.\" derler, ötesini kabul etmezler. Halbuki o, kendi yanlarında bulunanı doğrulayıcı bir gerçektir. De ki: \"Gerçekten inanıyor idiyseniz neden daha önce Allâh’ın peygamberlerini öldürüyordunuz?\""},{"n":92,"t":"\"Andolsun Mûsâ, size açık deliller getirmişti, sonra onun ardından tuttunuz buzağıya taptınız; siz öyle zâlimlersiniz işte!\""},{"n":93,"t":"Bir zaman üzerinize Tur(dağın)ı kaldırıp sizden kesin söz almıştık: \"Size verdiğimiz şeyi kuvvetle tutun, dinleyin!\" (demiştik). \"Dinledik ve isyân ettik.\" dediler. İnkârlarıyla kalblerine buzağı sevgisi içirildi. De ki: \"Eğer inanan kimseler iseniz, imanınız size ne kötü şey emrediyor.\""},{"n":94,"t":"De ki: \"Eğer (dilediğiniz gibi) gerçekten Allâh katında âhiret yurdu kimsenin değil, yalnız sizin ise, sözünüzde doğru iseniz, haydi ölümü temenni edin!\""},{"n":95,"t":"Fakat ellerinin yapıp öne sürdüğü işlerden dolayı ölümü asla istemezler, Allâh zâlimleri bilir."},{"n":96,"t":"Onları, insanların hayâta en düşkünü, ortak koşanlardan daha tutkunu bulursun; her biri, bin yıl yaşatılmasını ister. Oysa yaşatılması, onu azâbdan uzaklaştıracak değildir. Allâh ne yaptıklarını görüyor."},{"n":97,"t":"De ki: \"Allâh’ın izniyle Kur’ân’ı kendinden öncekini doğrulayıcı ve inananlara yol gösterici ve müjdeci olarak senin kalbine indirdiği için, kim Cebrâil’e düşman olursa,"},{"n":98,"t":"\"(Evet) kim Allah’a, meleklerine, elçilere, Cebrâil’e ve Mikâil’e düşman olursa bilsin ki, Allâh da inkâr edenlerin düşmanıdır."},{"n":99,"t":"Andolsun, sana apaçık âyetler indirdik, onları yoldan çıkmışlardan başkası inkâr etmez."},{"n":100,"t":"Ne zaman bir ahit (andlaşma) yaptılarsa, onlardan bir grup o ahdi bozup atmadı mı? Zaten çokları inanmazlar."},{"n":101,"t":"Allâh tarafından kendilerine, yanlarında bulunanı doğrulayıcı bir elçi gelince, Kitap verilmiş olanlardan bir grup, Allâh’ın Kitabını sanki bilmiyorlarmış gibi, sırtlarının arkasına attılar."},{"n":102,"t":"Süleymân’ın hükümdarlığı hakkında onlar, şeytânların uydurdukları sözlere uydular (Süleymân’ın, büyü yaparak saltanatını kazandığını söyleyen şeytân ruhlu insanlara uyup, Süleymân’ın büyücü olduğuna inandılar). Oysa Süleymân (büyü yaparak) küfre gitmemişti. Fakat o şeytânlar küfre gittiler: İnsanlara büyü ve Bâbil’de Hârût ve Mârût adlı melekler(den ilham alan iki kişiy)e indirileni öğretiyorlar. Halbuki onlar: \"Biz bir fitneyiz (sizin için bir sınavız), sakın, küfre gitme(yin)!\" demedikçe kimseye bir şey öğretmiyorlardı. Fakat bunlar, onlardan, erkekle karısının arasını açacak şeyler öğreniyorlardı. Ama, onlar, Allâh’ın izni olmadan onunla hiç kimseye zarar veremezler. Onlar, kendilerine yarar vereni değil, zarar vereni öğreniyorlardı. Andolsun, onu sat(ıp onunla çıkar sağlay) anın, âhirette bir nasibi olmadığını gâyet iyi biliyorlardı. Vicdanlarını sattıkları şey ne kötüdür, keşke (bunu) bilselerdi!"},{"n":103,"t":"Eğer onlar inanıp (Allâh’ın azâbından) korunmuş olsalardı, elbette Allâh katından (verilecek) sevâp, (kendileri için) daha hayırlı olurdu. Keşke bilselerdi!"},{"n":104,"t":"Ey inananlar, \"Râ’inâ (bizi gözet, yahut: kaba söz)\" demeyin, \"unzurna (bize bak)\" deyin ve dinleyin. Kâfirler için acı bir azâb vardır."},{"n":105,"t":"Nankör olan bazı Kitap ehli kimseler de, müşrikler de size Rabbinizden bir hayır indirilmesini istemezler. Oysa Allâh, rahmetini dilediğine tahsis eder, Allâh, büyük lutuf sâhibidir."},{"n":106,"t":"Biz bir âyeti siler veya unutturursak ondan daha iyisini, ya da benzerini getiririz. Allâh’ın her şeye gücü yeter olduğunu bilmedin mi?"},{"n":107,"t":"Bilmedin mi ki, göklerin ve yerin mülkü (hükümranlığı, yönetimi, mülkiyeti) yalnız Allâh’ındır. Sizin için Allah’tan başka ne bir koruyucu, ne de bir yardımcı yoktur."},{"n":108,"t":"Yoksa siz de Elçinizden, daha önce Mûsâ’dan istendiği gibi bir takım isteklerde bulunmak mı istiyorsunuz? Kim imanı küfürle değiştirirse, şüphesiz (o), dümdüz yolu sapıtmıştır."},{"n":109,"t":"Kitap sâhiplerinden çoğu, gerçek kendilerine besbelli olduktan sonra, sırf içlerindeki kıskançlıktan ötürü sizi imanınızdan sonra küfre döndürmek isterler. Allâh emrini getirinceye kadar affedin, hoş görün. Şüphesiz Allâh, her şeye gücü yetendir."},{"n":110,"t":"Namazı kılın, zekâtı verin; kendiniz için yapıp gönderdiğiniz her hayrı, Allâh’ın yanında bulursunuz, Allâh yaptıklarınızı görür."},{"n":111,"t":"\"Yahûdi yahut hıristiyan olandan başkası cennete girmeyecek,\" dediler. Bu, onların kuruntusudur. De ki: \"Doğru iseniz, delilinizi getirin.\""},{"n":112,"t":"Hayır, kim işini güzel yaparak özünü Allah’a teslim ederse, onun mükâfâtı, Rabbinin yanındadır. Onlara korku yoktur ve onlar üzülmeyeceklerdir."},{"n":113,"t":"Yahûdiler: \"Hıristiyanlar, bir temel üzerinde değiller,\" dediler. Hıristiyanlar da: \"Yahûdiler bir temel üzerinde değiller,\" dediler. Oysa hepsi de Kitabı okuyorlar. Bilmeyenler de tıpkı onların dedikleri gibi demişlerdi. Artık Allâh, ayrılığa düştükleri şey hakkında, kıyâmet günü aralarında hüküm verecektir."},{"n":114,"t":"Allâh’ın mescidlerinde, Allâh’ın adının anılmasına engel olan ve onların harâbolmasına çalışandan daha zâlim kim vardır? Bunların, oralara korka korka girmeleri gerekir (başka türlü girmeğe hakları yoktur). Bunlar için dünyâda rezillik, âhirette de büyük azâb vardır."},{"n":115,"t":"Doğu da, batı da Allâh’ındır. Nereye dönerseniz Allâh’ın yüzü (zâtı) oradadır. Şüphesiz Allâh’(ın rahmeti ve ni’meti) boldur. O (her şeyi) bilendir."},{"n":116,"t":"\"Allâh, çocuk edindi,\" dediler. Hâşâ, O, yücedir. Göklerde ve yerde olanların hepsi O’nundur, hepsi O’na boyun eğmiştir."},{"n":117,"t":"(O), göklerin ve yerin yaratıcısıdır. Bir şeyi yaratmak istedi mi, ona sadece \"ol\" der, o da hemen oluverir."},{"n":118,"t":"Bilmeyenler dediler ki: \"Allâh bizimle konuşmalı, ya da bize bir âyet (mu’cize) gelmeli değil miydi?\" Onlardan öncekiler de onların dedikleri gibi demişlerdi. Kalbleri birbirine benzedi. Gerçekleri iyice bilmek isteyenlere âyetleri açıkladık."},{"n":119,"t":"Doğrusu biz seni, gerçekle, müjdeleyici ve uyarıcı olarak gönderdik. Cehennem halkından sen sorumlu değilsin."},{"n":120,"t":"Sen onların, kendi dinlerine uymadıkça ne yahûdiler, ne de hıristiyanlar senden râzı olmazlar. \"Asıl doğru yol, Allâh’ın yoludur\" de. Sana gelen ilimden sonra eğer onların arzularına uyarsan, andolsun ki, Allah’tan sana ne bir dost, ne de bir yardımcı olmaz."},{"n":121,"t":"Kendilerine verdiğimiz Kitabı, gereğince okuyanlar var ya, işte onlar, ona inanırlar. Onu inkâr edenler ise ziyana uğrarlar."},{"n":122,"t":"Ey İsrâil oğulları, size verdiğim ni’meti ve sizi âlemlere üstün kılmış olduğumu hatırlayın."},{"n":123,"t":"Ve şu günden sakının ki, kimse kimsenin cezâsını çekmez (borcunu ödemez), kimseden fidye kabul edilmez, hiç kimseye şefâat (aracılık, iltimas) fayda vermez, bir taraftan yardım da görmezler."},{"n":124,"t":"Bir zaman Rabbi İbrâhim’i birtakım kelimelerle sınamış, o da onları tamamlayınca: \"Ben seni insanlara önder yapacağım\" demişti. \"Soyumdan da (önderler yap, ya Rabbi!)\" dedi. (Rabbi): \"zâlimlere ahdim ermez (onlar için söz vermem!)\" buyurdu."},{"n":125,"t":"Biz Beyt’i (Ka’be’yi) insanlara sevâp kazanılacak bir toplantı ve güven yeri yaptık. Siz de İbrâhim’in makamından bir namaz yeri edinin (orada namaz kılın). İbrâhim ve İsmâ’il’e: \"Tavaf edenler, ibâdete kapananlar, rükû ve secde edenler için Ev’imi temizleyin!\" diye emretmiştik."},{"n":126,"t":"İbrâhim demişti ki: \"Rabbim, bu şehri güvenli bir şehir yap, halkından Allah’a ve âhiret gününe inananları çeşitli ürünlerle besle!\" (Rabbi) buyurdu: \"İnkâr edeni dahi az bir süre geçindirir, sonra onu cehennem azâbına (girmeğe) zorlarım, ne kötü varılacak yerdir orası!\""},{"n":127,"t":"İbrâhim, İsmâ’il’le beraber Ev’in temellerini yükseltiyor: \"Rabbi’imiz, bizden kabul buyur, kuşkusuz sen işitensin, bilensin.\""},{"n":128,"t":"\"Rabbimiz, bizi sana teslim olanlar yap, neslimizden de sana teslim olan bir ümmet çıkar; bize ibâdet yerlerimizi göster, tevbemizi kabul et; zira, tevbeleri kabul eden, çok merhametli olan ancak sensin. Sen!\""},{"n":129,"t":"\"Rabbimiz, onlara kendi içlerinden, senin âyetlerini kendilerine okuyacak, onlara Kitabı ve hikmeti öğretecek, onları temizleyecek bir elçi gönder. Her zaman üstün gelen, her şeyi yerli yerince yapan yalnız sensin, sen!\""},{"n":130,"t":"Nefsini aşağılık yapan (beyinsiz)den başka, kim İbrâhim dininden yüz çevirir? Andolsun ki, biz onu dünyâda beğenip seçmiştik, âhirette de, o iyilerdendir."},{"n":131,"t":"Rabbi ona: \"İslâm ol!\" demişti, \"Âlemlerin Rabbine teslim oldum.\" dedi."},{"n":132,"t":"İbrâhim de bunu kendi oğullarına vasiyyet etti, Ya’kub da: \"Oğullarım, Allâh, sizin için o dini seçti, bundan dolayı sadece müslümanlar olarak ölünüz.\" (dedi)."},{"n":133,"t":"Yoksa siz, Ya’kub’a ölüm (hali) geldiği zaman orada mı idiniz? O zaman (Ya’kub), oğullarına: \"Benden sonra neye kulluk edeceksiniz?\" demişti. \"Senin tanrın ve ataların İbrâhim, İsmâ’il ve İshak’ın tanrısı olan tek Tanrı’ya kulluk edeceğiz, biz O’na teslim olanlarız.\" dediler."},{"n":134,"t":"Onlar bir ümmetti, gelip geçti. Onların kazandıkları kendilerine, sizin kazandıklarınız size âittir. Siz onların yaptıklarından sorulmazsınız."},{"n":135,"t":"\"Yahûdi veya hıristiyan olun ki, doğru yolu bulasınız.\" dediler. De ki: \"Hayır, biz dosdoğru İbrâhim dinine (uyarız). O, (Allah’a) ortak koşanlardan değildi.\""},{"n":136,"t":"\"Allah’a, bize indirilene, İbrâhim’e, İsmâ’il’e, İshak’a, Ya’kub’a ve sıbt(torun kabile)lere indirilene, Mûsâ ve Îsâ’ya verilene ve (diğer) peygamberlere Rabbleri tarafından verilene inandık, onlar arasında bir ayırım yapmayız, biz Allah’a teslim olanlarız.\" deyin."},{"n":137,"t":"Eğer onlar da sizin inandığınız gibi inanırlarsa doğru yolu bulmuş olurlar; ama dönerlerse mutlaka anlaşmazlık içine düşerler. Onlara karşı Allâh sana yeter. O, işitendir, bilendir."},{"n":138,"t":"Allâh’ın boyası (ile boyan). Allâh’ın boyasından daha güzel boyası olan kimdir? Biz ancak O’na kulluk ederiz."},{"n":139,"t":"Söyle (onlara): \"Allâh, bizim de Rabbimiz, sizin de Rabbiniz iken, O’nun hakkında bizimle tartışıyor musunuz? Bizim yaptıklarımız bize, sizin yaptıklarınız size âittir. Biz O’na gönülden bağlananlarız.\""},{"n":140,"t":"\"Yoksa siz, İbrâhim, İsmâ’il, İshak, Ya’kub ve sıbt(torun kabile)lerin, yahûdi, yahut hıristiyan olduklarını mı söylüyorsunuz?\" De ki: \"Siz mi daha iyi bilirsiniz, yoksa Allâh mı?\" Allâh tarafından bildiği bir (gerçeğin) tanıklığını gizleyenden daha zâlim kim olabilir? Allâh yaptıklarınızdan gâfil değildir."},{"n":141,"t":"Onlar bir ümmetti, gelip geçti. Onların kazandıkları kendilerine, sizin kazandıklarınız size aittir. Siz onların yaptıklarından sorulmazsınız."},{"n":142,"t":"İnsanlardan bazı beyinsizler: \"Onları, üzerinde bulundukları kıbleden çeviren nedir?\" diyecekler. De ki: \"Doğu da batı da Allâh’ındır. O, dilediğini doğru yola iletir.\""},{"n":143,"t":"Böylece sizi orta bir ümmet yaptık ki, insanlara şâhid olasınız. Elçi de size şâhid olsun. Biz, Elçi’ye uyanı, ökçesi üzerinde geriye dönenden ayıralım diye, eskiden yöneldiğin Ka’be’yi kıble yaptık. Bu, Allâh’ın yol gösterdiği kimselerden başkasına elbette ağır gelir. Allâh sizin imanınızı zayi edecek değildir. Şüphesiz Allâh, insanlara şefkatli, merhametlidir."},{"n":144,"t":"(Ey Muhammed), biz senin yüzünün göğe doğru çevrilip durduğunu (gökten haber beklediğini) görüyoruz. (Merak etme) elbette seni, hoşlanacağın bir kıbleye döndüreceğiz. (Bundan böyle) yüzünü Mescid-i Harâm tarafına çevir. Nerede olursanız, yüzlerinizi o yöne çevirin. Kitap verilenler, bunun Rableri tarafından bir gerçek olduğunu bilirler. Allâh onların yaptıklarından habersiz değildir."},{"n":145,"t":"Sen Kitap verilenlere her türlü âyeti getirsen yine onlar senin kıblene uymazlar; sen de onların kıblesine uyacak değilsin. Onlar birbirlerinin kıblesine de uymazlar. Sana gelen ilimden sonra onların keyiflerine uyarsan, o takdirde sen, mutlaka zâlimlerden olursun."},{"n":146,"t":"Kendilerine Kitap verdiklerimiz, onu, oğullarını tanıdıkları gibi tanırlar, ama yine de onlardan bir grup, bile bile gerçeği gizlerler."},{"n":147,"t":"Gerçek, Rabbinden gelendir, artık kuşkulananlardan olma."},{"n":148,"t":"Her ümmetin yöneldiği bir yönü vardır. O halde hayır işlerine koşun; nerede olsanız, Allâh sizi bir araya getirir, kuşkusuz Allâh, her şeyi yapabilir."},{"n":149,"t":"Nereden (yola) çıkarsan, yüzünü Mescid-i Harâm’a doğru çevir. Bu elbette Rabbinden gelen gerçektir. Allâh, yaptıklarınızdan habersiz değildir."},{"n":150,"t":"Nereden (yola) çıkarsan yüzünü Mescid-i Harâm’a doğru çevir, nerede olursanız, yüzünüzü o yana çevirin ki, haksızlardan başka hiç kimsenin, aleyhinizde bir delili olmasın. Onlardan da çekinmeyin, benden çekinin ve (o yana dönün ki) size olan ni’metimi tamamlayayım, böylece yolu bulmuş olasınız."},{"n":151,"t":"Nitekim kendi içinizden, size âyetlerimizi okuyan, sizi temizleyen, size Kitabı, hikmeti ve bilmediklerinizi öğreten bir Elçi gönderdik."},{"n":152,"t":"Öyle ise beni anın ki, ben de sizi anayım; bana şükredin, nankörlük etmeyin."},{"n":153,"t":"Ey inananlar, sabır ve namazla (Allah’tan) yardım isteyin, muhakkak ki Allah, sabredenlerle beraberdir."},{"n":154,"t":"Allâh yolunda öldürülenlere, \"ölüler\" demeyin; hayır, onlar diridirler, ama siz farkında olmazsınız."},{"n":155,"t":"Andolsun, sizi korku, açlık, mallar(ınız)dan canlar(ınız)dan ve ürünler(iniz)den eksiltmek gibi şeylerle deneriz; sabredenleri müjdele."},{"n":156,"t":"Ki onlara bir belâ eriştiği zaman: \"Biz Allâh içiniz ve biz O’na döneceğiz,\" derler."},{"n":157,"t":"İşte Rablerinden bağışlamalar ve rahmet hep onlaradır ve doğru yolu bulanlar da onlardır."},{"n":158,"t":"Safâ ile Merve Allâh’ın nişanlarındandır. Kim Ev’i hacceder, ya da umre yaparsa onları tavaf etmesinde kendisine bir günâh yoktur. Kim kendiliğinden bir iyilik yaparsa bilsin ki, Allâh karşılığını verir, (yaptığını) bilir."},{"n":159,"t":"İndirdiğimiz açık delilleri ve hidâyeti biz Kitapta insanlara açıkça belirttikten sonra gizleyenler (var ya), işte onlara hem Allâh la’net eder, hem bütün la’net edebilenler la’net eder."},{"n":160,"t":"Ancak tevbe edip uslananlar ve (gerçeği) açıklayanlar başka. Onları bağışlarım. Çünkü ben tevbeyi çok kabul edenim, çok esirgeyenim."},{"n":161,"t":"Ama âyetlerimizi inkâr etmiş ve kâfir olarak ölmüş olanlar, işte Allâh’ın, meleklerin ve tüm insanların la’neti onların üstünedir."},{"n":162,"t":"Ebedi la’net içinde kalırlar. Ne kendilerinden azâb hafifletilir, ne de onlara fırsat verilir."},{"n":163,"t":"Tanrınız bir tek Tanrı’dır, O’ndan başka tanrı yoktur, O Rahmân’dır, Rahim’dir."},{"n":164,"t":"Şüphesiz göklerin ve yerin yaratılışında, gece ve gündüzün değişmesinde, insanların faydasına olan şeyleri denizde taşıyıp giden gemilerde, Allâh’ın gökten su indirip onunla ölmüş olan yeri dirilterek üzerine her çeşit canlıyı yaymasında, rüzgârları ve yer ile gök arasında emre hazır bekleyen bulutları evirip çevirmesinde elbette düşünen bir topluluk için (Allâh’ın varlığına ve birliğine) deliller vardır."},{"n":165,"t":"İnsanlardan kimi, Allah’tan başka eşler tutar, Allâh’ı sever gibi onları severler. İnananlar ise en çok Allâh’ı severler. Zulmedenler, azâbı gördükleri zaman bütün kuvvetin Allah’a âid olduğunu ve Allâh’ın azâbının çetin olduğunu anlayacaklarını keşke bilselerdi!"},{"n":166,"t":"İşte uyulanlar, uyanlardan uzak durdular; azâbı gördüler, aralarındaki bağlar kesildi."},{"n":167,"t":"Uyanlar, şöyle dediler; \"Âh keşke bir daha dünyâya gitmemiz mümkün olsaydı da şimdi onların bizden uzak durdukları gibi biz de onlardan uzak dursaydık!\" Böylece Allâh, onlara işledikleri bütün fiilleri hasretler (pişmanlık kaynağı olarak) gösterir. Ve onlar, ateşten çıkamazlar."},{"n":168,"t":"Ey insanlar, yeryüzünde bulunan helâl ve temiz şeylerden yeyin, şeytânın adımlarını izlemeyin; çünkü o, sizin apaçık düşmanınızdır."},{"n":169,"t":"O size dâimâ kötülük ve çirkin iş (yapmanızı), Allâh hakkında bilmediğiniz şeyler söylemenizi emreder."},{"n":170,"t":"Onlara: \"Allâh’ın indirdiğine uyun!\" dense, \"Hayır, biz atalarımızı üzerinde bulduğumuz(yol)a uyarız!\" derler. Peki ama, ataları bir şey düşünmeyen, doğru yolu bulamayan kimseler olsalar da mı (atalarının yoluna uyacaklar)?"},{"n":171,"t":"O inkâr edenler(i Hakk’a çağıran)ın durumu, tıpkı bağırıp çağırmadan başka bir şey işitmeyen (işittiği sesin mânâsını anlamayan hayvanlar)a haykıran kimsenin durumu gibidir. (Onlar), sağır, dilsiz ve kördürler, onun için düşünmezler."},{"n":172,"t":"Ey inananlar, size verdiğimiz rızıkların iyilerinden yeyin, Allah’a tapıyorsanız, O’na şükredin."},{"n":173,"t":"Allâh size leş, kan, domuz eti ve Allah’tan başkası adına kesileni harâm kıldı. Ama kim mecbur kalırsa, (başkasına) saldırmadan ve sınırı aşmadan (bunlardan) yemesinde bir günâh yoktur. Muhakkak ki Allâh çok bağışlayandır, çok esirgeyendir."},{"n":174,"t":"Allâh’ın indirdiği Kitaptan bir şey gizleyip, onu birkaç paraya satanlar var ya, işte onlar karınlarına ateşten başka bir şey koymuyorlar. Kıyâmet günü Allâh ne onlara konuşacak ve ne de onları temizleyecektir. Onlar için acı bir azâb vardır."},{"n":175,"t":"Onlar hidâyet karşılığında sapıklık, mağfiret karşılığında azâb satın almışlardır. Onlar ateşe, karşı ne kadar da dayanıklıdırlar(!)"},{"n":176,"t":"(Onlara) böyle(azâb edilecek)dir. Çünkü Allâh, Kitabı gerçekle indirmiştir. Kitapta ayrılığa düşenler, elbette derin bir anlaşmazlık içindedirler."},{"n":177,"t":"Yüzlerinizi doğu ve batı tarafına çevirmeniz iyilik değildir. Asıl iyilik, o(kimsenin iyiliği)dir ki, Allah’a, âhiret gününe, meleklere, Kitaba ve peygamberlere inandı; sevdiği malını yakınlara, yetimlere, yoksullara, yolda kalmışlara, dilencilere ve boyunduruk altında bulunan(köle ve esir)lere verdi; namazı kıldı, zekâtı verdi. Andlaşma yaptıkları zaman andlaşmalarını yerine getirenler; sıkıntı, hastalık ve savaş zamanlarında sabredenler, işte doğru olanlar onlardır, (Allâh’ın azâbından) korunanlar da onlardır."},{"n":178,"t":"Ey inananlar, öldürmelerde kısâs size farz kılındı. (Kâtilin de öldürülmesi gerekir). Hüre hür, köleye köle, kadına kadın. Kardeşi tarafından kısmen affedilen kimse, örfe uyup o(affeden kardeşi)ne güzelce (diyeti) ödemelidir! Bu, Rabbiniz tarafından bir hafifletme ve acımadır. Kim bundan sonra da saldırıya kalkarsa artık onun için acı bir azâb vardır."},{"n":179,"t":"Ey akıl sâhipleri, kısâsta sizin için hayât vardır, böylece korunursunuz."},{"n":180,"t":"Birinize ölüm geldiği zaman, eğer bir hayır (mal) bırakacaksa, anaya, babaya, yakınlara uygun bir biçimde vasiyyet etmek, korunanlar üzerine bir borçtur."},{"n":181,"t":"Kim işittikten sonra vasiyyeti değiştirirse, günâhı, onu değiştirenlerin boynunadır. Şüphesiz Allâh işitendir, bilendir."},{"n":182,"t":"Kim de vasiyyet edenin bir hatâ veya günâh işlemesinden korkar da (tarafların) aralarını düzeltirse, ona günâh yoktur, Allâh bağışlayandır, esirgeyendir."},{"n":183,"t":"Ey inananlar, sizden öncekilere yazıldığı gibi (günâhlardan) korunmanız için sizin üzerinize de oruç yazıldı;"},{"n":184,"t":"Sayılı günler olarak. Sizden kim hasta veya seferde olursa tutamadığı günler sayısınca başka günlerde (tutar). Oruca (güç) dayananların fidye vermesi, bir yoksulu doyurması lâzımdır. Bununla beraber gönül isteğiyle kim bir iyilik yapar(oruç tutar)sa o, kendisi için iyidir. Bilirseniz oruç tutmanız, sizin için daha hayırlıdır."},{"n":185,"t":"Ramazan ayı, insanlara yol gösteren, hidâyeti, doğruyu ve yanlışı ayırdedip açıklayan Kur’ân’ın indirildiği aydır. İçinizden kim o aya yetişir(ayı görür)se oruç tutsun. Kim hasta olur, yahut seferde bulunursa tutamadığı günler sayısınca başka günlerde oruç tutsun. Allâh sizin için kolaylık ister, güçlük istemez. Sayıyı tamamlamanızı, size doğru yolu gösterdiğinden dolayı Allâh’ı tekbir etmenizi ister. Şükredesiniz diye (size bu kolaylığı gösterir)."},{"n":186,"t":"Kullarım, sana benden sorar(lar)sa (söyle): Ben (onlara) yakınım. du’â eden, bana du’â ettiği zaman onun du’âsına karşılık veririm. O halde onlar da bana karşılık versin(benim çağrıma uysun)lar, bana inansınlar ki, doğru yolu bulmuş olalar."},{"n":187,"t":"Oruç gecesi, kadınlarınıza yaklaşmak, size helâl kılındı. Onlar sizin elbisenizdir, siz de onların elbisesisiniz. Allâh, sizin kendinize yazık etmekte olduğunuzu bildi de tevbenizi kabul edip sizi affetti. Artık şimdi onlara yaklaşın ve Allâh’ın sizin için yaz(ıp takdir etmiş ol)duğunu arayın; şafağın beyaz ipliği siyah iplikten ayırdelinceye kadar yeyin, için; sonra tâ gece oluncaya dek orucu tamamlayın; mescidlerde ibâdete çekilmiş iken kadınlara yaklaşmayın. Bunlar, Allâh’ın (yasak) sınırlarıdır, bunlara yaklaşmayın. Allâh, insanlara âyetlerini böyle açıklar ki korunup sakınsınlar."},{"n":188,"t":"Mallarınızı, aranızda bâtıl (sebepler) ile yemeyin; bile bile insanların mallarından bir kısmını günâh bir biçimde yemeniz için onları hakimler(in önün)e atmayın (hakimlere götürmeyin veya onlara rüşvet vermeyin)."},{"n":189,"t":"Sana doğan aylardan soruyorlar. De ki: \"Onlar, insanlar ve hac için vakit ölçüleridir.\" Evlere arkalarından girmek iyilik değildir. İyilik, Allah’tan korkanın iyiliğidir. Evlere kapılarından girin ve Allah’tan korkun ki, başarıya eresiniz, umduğunuzu bulasınız."},{"n":190,"t":"Sizinle savaşanlarla Allâh yolunda savaşın; fakat haksız yere saldırmayın, çünkü Allâh, saldırganları sevmez."},{"n":191,"t":"Onları nerede yakalarsanız öldürün, onların sizi çıkardıkları yer(Mekke)den siz de onları çıkarın! Fitne (baskı yapmak), adam öldürmekten daha kötüdür. Mescid-i Harâm’da onlarla savaşmayın ki, onlar da sizinle orada savaşmasınlar. Fakat onlar sizinle savaşırlarsa, hemen onları öldürün; kâfirlerin cezâsı böyledir."},{"n":192,"t":"Eğer onlar (saldırılarına) son verirlerse, Allâh bağışlayandır, esirgeyendir."},{"n":193,"t":"Onlarla savaşın ki, fitne (baskı) ortadan kalksın, din yalnız Allâh’ın dini olsun. (Yalnız O’na tapılsın) Eğer (saldırılarına) son verirlerse artık zâlimlerden başkasına düşmanlık olmaz."},{"n":194,"t":"Harâm ayı, harâm aya karşılıktır. Hürmetler, karşılıklıdır. Kim size saldırırsa, onun size saldırdığı kadar siz de ona saldırın; Allah’tan korkun, bilin ki Allâh (günâhlardan) korunanlarla beraberdir."},{"n":195,"t":"(Mallarınızı) Allâh yolunda harcayın, kendi ellerinizle kendinizi tehlikeye atmayın, iyilik edin, doğrusu Allâh iyilik edenleri sever."},{"n":196,"t":"Allâh için haccı ve ömreyi tamamlayın. Eğer (engellenmiş olursanız kolayınıza gelen kurbanı (gönderin); kurban yerine varıncaya kadar başlarınızı tıraş etmeyin. İçinizden hasta olan, ya da başından bir rahatsızlığı bulunan (bundan ötürü tıraş olmak zorunda kalan) kimse, oruçtan, sadakadan veya kurbandan (biriyle) fidye (versin). Güvene kavuştuğunuzda, hac (zamanın)a kadar ömre ile faydalanmak isteyen kimse, kolayına gelen kurbanı keser. (Kurban) Bulamayan kimse üç gün hacda, yedi gün de döndüğünüz zaman (olmak üzere) tam on gün oruç tutar. Bu, âilesi Mescid-i Harâm (civarın)da oturmayanlar içindir. Allah’tan korkun ve Allâh’ın cezâsının çetin olduğunu bilin."},{"n":197,"t":"Hac, bilinen aylardadır. Kim o aylarda (ihrâma girerek) haccı (kendisine) gerekli kılarsa bilsin ki, hacda kadına yaklaşmak, günâha sapmak, kavga etmek yoktur. Allah, yaptığınız her iyiliği bilir. Yanınıza azık alın (da açlıktan korunun), azığın en iyisi korunmadır. Ey akıl sâhipleri benden korunun!"},{"n":198,"t":"Rabbinizin lutuf ve keremini aramanızda sizin için bir günâh yoktur. Arafat(taki duruş)tan ayrılıp (Müzdelife’ye) akın edince Meş’ar-i harâm’da Allâh’ı anın, O’nun size gösterdiği biçimde O’nu anın. O’nun yol göstermesinden önce siz, sapıklardan idiniz."},{"n":199,"t":"Sonra insanların akın akın döndüğü yerden siz de akın edin ve Allah’tan mağfiret dileyin, şüphesiz Allâh bağışlayandır, esirgeyendir."},{"n":200,"t":"Hac ibâdetlerinizi bitirince atalarınızı andığınız gibi hattâ, daha kuvvetli bir anışla Allâh’ı anın. İnsanlardan kimi \"Rabbimiz bize dünyâda ver!\" der; onun âhirette bir payı yoktur."},{"n":201,"t":"Onlardan kimi de: \"Rabbimiz, bize dünyâda da güzellik ver, âhirette de güzellik ver, bizi ateş azâbından koru!\" der."},{"n":202,"t":"İşte onlara, kazandıklarından bir pay vardır. Allâh, hesabı çabuk görendir."},{"n":203,"t":"Sayılı günlerde Allâh’ı anın (tekbir alın). Kim hemen iki gün içinde (Mina’dan Mekke’ye) dönerse ona günâh yoktur. Kim geri kalırsa korunduğu takdirde ona da günâh yoktur. Allah’tan korkun ve O’nun huzûruna toplanacağınızı bilin."},{"n":204,"t":"İnsanlardan öylesi var ki, dünyâ hayâtına dair sözü, senin hoşuna gider. Kalbinde olan (samimi düşüncelerini söylediğin)e Allâh’ı şâhid tutar. Oysa o, hasımların en yamanıdır."},{"n":205,"t":"Dönüp gitti mi (veya iş başına geçti mi) yeryüzünde bozgunculuk yapmağa, ekin ve nesli yok etmeğe çalışır; Allâh da bozgunculuğu sevmez."},{"n":206,"t":"Ona: \"Allah’tan kork!\" dense gururu, kendisini günâha sürükler. Artık ona cehennem yetişir; ne kötü bir yataktır o!.."},{"n":207,"t":"İnsanlardan öylesi var ki, kendisini Allâh’ın rızâsın(ı kazanmay)a satar. Allâh da kullar(ın)a çok şefkatlidir."},{"n":208,"t":"Ey inananlar, hepiniz birlikte islâma (veya barışa) girin, şeytânın adımlarını izlemeyin, çünkü o size apaçık düşmandır."},{"n":209,"t":"Size açık açık deliller geldikten sonra yine (hak yoldan) kayarsanız, bilin ki Allâh dâimâ üstündür, hüküm ve hikmet sâhibidir."},{"n":210,"t":"Onlar, ille buluttan gölgeler içinde Allâh’ın ve meleklerin gelmesini ve işin bitirilmesini mi bekliyorlar? Halbuki bütün işler tekrar Allah’a döndürülüp götürülecektir."},{"n":211,"t":"İsrâil oğullarına sor; onlara nice açık âyetler verdik. Kim, Allâh’ın kendisine gelen ni’metini değiştirirse bilsin ki, Allâh’ın cezâsı çetindir."},{"n":212,"t":"İnkâr edenlere dünyâ hayâtı süslü gösterildi; (onlar) inananlarla alay ederler. Oysa korunanlar, kıyâmet gününde onlardan üstündürler. Allâh, dilediğine hesapsız rızık verir."},{"n":213,"t":"İnsanlar bir tek ümmet idi. Sonra Allâh, peygamberleri, müjdeciler ve uyarıcılar olarak gönderdi; onlarla beraber, anlaşmazlığa düştükleri konularda insanlar arasında hükmetmek üzere, içinde gerçekleri taşıyan Kitabı indirdi. Kendilerine Kitap verilmiş olanlar, kendilerine açık deliller geldikten sonra, sırf aralarındaki kıskançlıktan ötürü o(Kitap hakkı)nda anlaşmazlığa düştü(ler). Bunun üzerine Allâh, kendi izniyle inananları, onların üzerinde ayrılığa düştükleri gerçeğe iletti. Allâh, dilediğini doğru yola iletir."},{"n":214,"t":"Yoksa siz, sizden önce geçenlerin durumu başınıza gelmeden cennete gireceğinizi mi sandınız? Onlara öyle yoksulluk ve sıkıntı dokunmuştu, öyle sarsılmışlardı ki, nihâyet peygamber ve onunla birlikte inananlar: \"Allâh’ın yardımı ne zaman?\" diyecek olmuşlardı. İyi bilin ki, Allâh’ın yardımı yakındır."},{"n":215,"t":"Sana (Allâh yolunda) ne harcayacaklarını soruyorlar. De ki: \"Verdiğiniz hayır (mal), ana-baba, yakınlar, öksüzler, yoksullar ve yolda kalmış(lar) içindir. Yaptığınız her hayrı muhakkak Allâh bilir."},{"n":216,"t":"Hoşunuza gitmese de size savaş yazıldı (farz kılındı). Bazen hoşlanmadığınız bir şey, hakkınızda iyi olabilir ve hoşlandığınız bir şey de hakkınızda kötü olabilir. Allâh bilir, siz bilmezsiniz."},{"n":217,"t":"Sana harâm ayında savaşmaktan soruyorlar. De ki: \"Onda savaş, büyük bir günâhtır. Fakat Allâh yoluna engel olmak, Allah’a ve Mescid-i Harâm’a karşı nankörlük etmek, halkını ondan (Mekke’den) sürüp çıkarmak, Allâh yanında daha büyük bir günâhtır. Fitne (baskı yapmak, adam) öldürmekten daha büyük(bir günâh)tır\". Onlar yapabilseler sizi dininizden döndürünceye kadar sizinle savaşmaya devam ederler. Sizden kim dininden döner ve kâfir olarak ölürse, işte onların bütün yaptıkları dünyâda da, âhirette de boşa çıkmıştır ve onlar, ateş halkıdır, orada sürekli kalacaklardır."},{"n":218,"t":"Onlar ki inandılar, göç ettiler, Allâh yolunda savaştılar; işte onlar, Allâh’ın rahmetini umarlar. Allâh, çok bağışlayan, çok merhamet edendir."},{"n":219,"t":"Sana şaraptan ve kumardan soruyorlar. De ki; \"O ikisinde büyük günâh ve insanlara bazı yararlar vardır. Fakat onların günâhı yararından büyüktür.\" Ve sana Allâh yolunda ne vereceklerini soruyorlar. De ki; \"Af (yani ihtiyaçlarınızdan fazlasını veya helâl ve güzel olan şeyleri verin!)\" Allâh size âyetleri böyle açıklıyor ki düşünesiniz."},{"n":220,"t":"Dünyâ ve âhiret hakkında(ki işleri düşünesiniz). Ve sana öksüzlerden soruyarlar. De ki: \"Onları(n durumlarını) düzeltmek hayırlıdır. Eğer onlara karışır(onlarla bir arada yaşar)sanız (onlar) sizin kardeşlerinizdir. Allâh, bozanı düzeltenden ayırır. Allâh dileseydi sizi zora sokardı. Şüphesiz Allâh dâimâ üstündür, hüküm ve hikmet sâhibidir."},{"n":221,"t":"Allah’a ortak koşan kadınlarla, onlar inanıncaya kadar, evlenmeyin. (Allah’a ortak koşan hür kadın), hoşunuza gitse dahi, inanan bir cariye, ortak koşan (hür) kadından iyidir. Ortak koşan erkekler de inanıncaya kadar, onları (kadınlarınızla) evlendirmeyin. (Allah’a ortak koşan hür erkek) hoşunuza gitse dahi, inanan bir köle, ortak koşan (hür) adamdan iyidir. (Zira) onlar ateşe çağırıyorlar. Allâh ise izniyle cennete ve mağfirete çağırıyor. İnsanlara âyetlerini açıklıyor ki öğüt alsınlar."},{"n":222,"t":"Sana âdet görmeden soruyorlar. De ki: \"O eziyettir.\" Âdet halinde kadınlardan çekilin, temizleninceye kadar onlara yaklaşmayın. Temizlendikleri zaman Allâh’ın emrettiği yerden onlara varın. Allâh tevbe edenleri sever, temizlenenleri sever."},{"n":223,"t":"Kadınlarınız sizin tarlanızdır. Tarlanıza dilediğiniz biçimde varın. Kendiniz için ileriye hazırlık yapın ve mutlaka Allah’a kavuşacağınızı bilin. İnananları müjdele."},{"n":224,"t":"Allâh’ı, yemin(ettiğiniz iş)lerinize (yani) iyilik etmenize, (kötülüklerden) korunmanıza ve insanların arasını düzeltmenize engel yapmayın. Allâh, işitendir, bilendir."},{"n":225,"t":"Allâh sizi, yaptığınız kasıtsız yeminlerinizden sorumlu tutmaz; fakat kalblerinizin kazandığı (bile bile yaptığınız) yeminlerden sorumlu tutar. Allâh bağışlayandır, halimdir."},{"n":226,"t":"Kadınlarına yaklaşmamağa yemin edenler için ancak dört ay bekleme (hakkı) vardır. Eğer (o süre) içinde dönerlerse Allâh bağışlayan, merhamet edendir."},{"n":227,"t":"Eğer boşamağa kesin karar verirlerse, şüphesiz Allâh işitendir, bilendir."},{"n":228,"t":"Boşanmış kadınlar, üç kur’(üç âdet veya üç temizlik süresi bekleyip) kendilerini gözetlerler (hâmile olup olmadıklarına bakarlar). Eğer Allah’a ve âhiret gününe inanıyorlarsa, Allâh’ın kendi rahimlerinde yarattığını gizlemeleri (karınlardında çocuk bulunduğunu saklamaları) kendilerine helâl olmaz. Kocaları da bu arada barışmak isterlerse, onları geri almağa daha çok hak sahibidirler. Erkeklerin kadınlar üzerinde bulunan hakları gibi, kadınların da erkekler üzerinde hakları vardır. Erkeklerin, kadınlar üzerinde(ki hakları), bir derece fazladır. Allâh azizdir, hakimdir."},{"n":229,"t":"Boşama iki defadır. (Bundan sonra kadını) ya iyilikle tutmak, ya da güzelce salıvermek (lâzım)dır. Onlara verdiklerinizden bir şey geri almanız, size helâl değildir. Şâyet erkek ve kadın, Allâh’ın sınırlarında duramayacaklarından korkarlarsa başka. Eğer erkek ve kadının, Allâh’ın sınırlarında duramayacaklarından korkarsanız, o zaman kadının (ayrılmak için) verdiği fidye(hakkından vazgeçmesin)de ikisine de bir günâh yoktur. İşte bunlar Allâh’ın sınırlarıdır, sakın bunları aşmayın. Kim(ler) Allâh’ın sınırlarını aşarsa işte onlar zâlimlerdir."},{"n":230,"t":"Erkek yine boşarsa, artık bundan sonra kadın, başka bir kocaya varmadan kendisine helâl olmaz. O (vardığı adam) da bunu boşarsa, Allâh’ın sınırları içinde duracaklarına inandıkları takdirde (eski karı kocanın) tekrar birbirlerine dönmelerinde kendilerine bir günâh yoktur. İşte bunlar Allâh’ın sınırlarıdır. (Allâh) bunları, bilen bir toplum için açıklamaktadır."},{"n":231,"t":"Kadınları boşadığınız zaman, bekleme sürelerini bitirdiler mi, ya onları iyilikle tutun, ya da iyilikle bırakın; haklarına tecâvüz edip zarar vermek için onları (yanınızda) tutmayın. Kim bunu yaparsa kendine yazık etmiş olur. Allâh’ın âyetlerini eğlence yerine koymayın; Allâh’ın size olan ni’metini ve size öğüt vermek için Kitap ve Hikmet’ten size indirdiklerini düşünün, Allah’tan korkun ve bilin ki, Allâh her şeyi bilir."},{"n":232,"t":"Kadınları boşadığınız zaman bekleme sürelerini bitirdiler mi, kendi aralarında güzelce anlaştıkları takdirde, (eski) kocalarıyle evlenmelerine engel olmayın. Bu, içinizden Allah’a ve âhiret gününe inanan kimseye verilen öğüttür. Bu, sizin için daha iyi ve daha temizdir. Allâh bilir, siz bilmezsiniz."},{"n":233,"t":"Anneler, çocuklarını -emzirmeyi tamamlamak isteyen kimse için- tam iki yıl emzirirler. Onların uygun biçimde yiyeceğini ve giyeceğini sağlamak, çocuğun babasına aittir. Herkes ancak gücü ölçüsünde bir şeyle yükümlü tutulur. Ne anne çocuğu yüzünden, ne de çocuğun aidolduğu baba, çocuğu yüzünden zarara sokulmasın. Mirasçının da aynı şeyi yapması gerekir. Eğer (ana-baba), anlaşıp danışarak (çocuğu) sütten kesmek isterlerse, kendilerine günâh yoktur. Çocuklarınızı (sütannesi tutup) emzirtmek isterseniz, verdiğiniz(ücret)i güzelce verdikten sonra yine üzerinize bir günâh yoktur. Allah’tan korkun ve bilin ki, Allâh, yaptığınız her şeyi görmektedir."},{"n":234,"t":"İçinizden ölenlerin, geriye bıraktıkları eşleri, dört ay on gün (bekleyip) kendilerini gözetlerler. Sürelerini bitirince artık kendileri için uygun olanı yapmalarında size bir günâh yoktur. Allâh yaptıklarınızı haber alır."},{"n":235,"t":"Böyle (iddetini bekleyen) kadınlara evlenme isteğinizi üstü kapalı biçimde bildirmenizden, yahut içinizde tutmanızdan dolayı size bir günâh yoktur. (Çünkü) Allâh, sizin onları anacağınızı bilmektedir. Sakın (kapalı evlenme teklifi sırasında), iyi söz söylemeniz dışında, onlarla bir gizli(buluşma)ya sözleşmeyin ve farz olan bekleme süresi dolmadan nikâh bağını bağlamağa kalkmayın ve bilin ki, Allâh içinizden geçeni bilir. O’ndan sakının ve yine bilin ki, Allâh bağışlayandır, halimdir (cezâ vermekte aceleci değildir)."},{"n":236,"t":"Henüz dokunmadan, ya da mehir kesmeden kadınları boşarsanız size bir günâh yoktur. Ancak onları faydalandırın (bir miktar bir şey verin). Eli geniş olan, kendi gücü nisbetinde, eli dar olan da kendi kaderince güzel bir şekilde faydalandırmalı (herkes gücü ölçüsünde bir şey vermeli) dir. Bu, iyilik edenlerin üzerine bir borçtur."},{"n":237,"t":"Bir mehir kestiğiniz takdirde, henüz dokunmadan onları boşamışsanız, kestiğinizin yarısını (verin). Ancak kadınlar vazgeçer, yahut nikâh bağı elinde bulunan (erkek) vazgeçerse başka. (Erkekler,) Sizin affetmeniz (müsâmaha gösterip mehrin tümünü vermeniz) takvâya daha yakındır. Aranızda birbirinize iyilik etmeyi unutmayın. Şüphesiz Allâh, yaptıklarınızı görür."},{"n":238,"t":"Namazları ve orta namazı koruyun, gönülden bağlılık ve saygı ile Allâh’ın huzûruna durun."},{"n":239,"t":"Eğer (bir tehlikeden) korkarsanız, yaya, yahut binmiş olarak kılın; güvene kavuştuğunuz zaman, bilmediğiniz şeyleri size öğrettiği şekilde Allâh’ı anın."},{"n":240,"t":"İçinizden ölüp geriye eşler bırakan(erkek)ler eşlerinin, (evlerinden) çıkarılmadan bir yıla kadar geçimlerinin sağlanmasını vasiyyet etsinler. Şâyet kendileri çıkarlarsa, onların, kendileri hakkında uygun olanı yapmalarında sizin için bir günâh yoktur. Allâh dâimâ üstündür, hüküm ve hikmet sâhibidir."},{"n":241,"t":"Boşanmış kadınların uygun olan geçimlerini sağlamak, (Allâh’ın azâbından) korunanlar üzerine bir borçtur."},{"n":242,"t":"Düşünesiniz diye Allâh size âyetlerini böyle açıklamaktadır."},{"n":243,"t":"Şu, binlerce kişi iken ölüm korkusuyla yurtlarından çıkanları görmedin mi? Allâh onlara, \"Ölün!\" demişti de sonra kendilerini diriltmişti. Şüphesiz Allâh, insanlara karşı ikram sâhibidir. Ama insanların çoğu şükretmezler."},{"n":244,"t":"Allâh yolunda savaşın ve bilin ki Allâh, işitendir, bilendir."},{"n":245,"t":"Kimdir o adam ki, Allah’a güzel bir borç versin de, Allâh da ona kat kat fazlasıyla (verdiğini) ödesin! Allâh (rızkı) kısar da, açar da. Hep O’na döndürüleceksiniz."},{"n":246,"t":"Mûsâ’dan sonra İsrâil oğullarının ileri gelenlerini görmedin mi? Peygamberlerine: \"Bize bir hükümdar gönder, (onun önderliğinde) Allâh yolunda savaşalım.\" demişlerdi. \"Ya size savaş yazılınca savaşmazsanız?\" dedi. Dediler: \"Bizler neden Allâh yolunda savaşmayalım ki; oysa biz yurtlarımızdan ve oğullarımızın arasından çıkarılıp sürüldük?\" Fakat kendilerine savaş yazılınca, içlerinden pek azı hariç, yüz çevirdiler. Allâh zâlimleri bilir."},{"n":247,"t":"Peygamberleri onlara dedi ki: \"Allâh Talût’u size hükümdar gönderdi.\" Dediler ki: \"O bizim üzerimize nasıl hükümdar olabilir? Biz hükümdarlığa ondan daha lâyıkız, ona bol mal da verilmemiştir.\" Dedi: \"Allâh onu sizin üzerinize (hükümdar) seçti, onun bilgisini ve gücünü artırdı.\" Allâh mülkünü dilediğine verir. Allâh(ın lutfu) geniştir, (O, herşeyi) bilendir."},{"n":248,"t":"Ve peygamberleri onlara dedi ki; \"Onun hükümdarlığının alâmeti, içinde Rabbinizden bir huzûr ve Mûsâ âilesinin, Hârûn âilesinin geriye bıraktığından bir kalıntı bulunan, meleklerin taşıdığı (Allâh’ın Ahid sandığı) Tâbut’un size gelmesidir. Eğer inanıyorsanız bunda sizin için (Tâlût’un hükümdarlığına) kesin bir alâmet vardır.\""},{"n":249,"t":"Tâlût, askerleri(ni) yürütüp (ordugâhtan) çıkarınca dedi ki: \"Allâh sizi bir ırmakla deneyecektir. Kim ondan içerse benden değildir. Ondan (kana kana) tadmayıp sadece eliyle bir avuç alan bendendir.\" İçlerinden pek azı hariç, hepsi ondan içtiler. Nihâyet Tâlût ve kendisiyle beraber inananlar, ırmağı geçince: \"Bugün Câlût’a ve askerlerine karşı bizim gücümüz yok.\" dediler. Allah’a kavuşacaklarına kanâat getirenler ise: \"Nice az bir topluluk var ki, Allâh’ın izniyle çok topluluğa gâlib gelmiştir. Allâh, sabredenlerle beraberdir.\" dediler."},{"n":250,"t":"(Tâlût’un askerleri) Câlût ve askerlerinin karşısına çıktıklarında şöyle dediler: \"Rabbimiz, üzerimize sabır dök! ayaklarımızı sağlam tut ve o kâfir millete karşı bize yardım et!\""},{"n":251,"t":"Derken, Allâh’ın izniyle onları bozdular, Dâvûd Câlût’u öldürdü; Allâh ona (Dâvûd’a) hükümdarlık ve hikmet verdi ve ona dilediğini öğretti. Eğer Allâh, insanların bir kısmıyle diğerlerini savmasaydı, dünyâ bozulurdu. Fakat Allâh, bütün âlemlere karşı lutuf sâhibidir."},{"n":252,"t":"Bunlar, Allâh’ın âyetleridir; bunları sana gerçek ile okuyoruz (bunlarla sana gerçekleri açıklıyoruz). Elbette sen gönderilen elçilerdensin."},{"n":253,"t":"İşte o elçilerden kimini kiminden üstün kıldık. Allâh onlardan kimine konuştu, kimini de derecelerle yükseltti. Meryem oğlu Îsâ’ya da açık deliller verdik ve onu Ruh’ül-Kudüs ile destekledik. Allâh dileseydi onların arkasından gelen milletler, kendilerine açık deliller gelmiş olduktan sonra birbirlerini öldürmezlerdi. Fakat anlaşmazlığa düştüler, onlardan kimi inandı, kimi de inkâr etti. Allâh dileseydi, birbirlerini öldürmezlerdi. Ama Allâh dilediğini yapar."},{"n":254,"t":"Ey inananlar, ne alışverişin, ne dostluğun ve ne de şefâatin olmadığı gün gelmezden önce, size verdiğimiz rızıktan (Allâh için) harcayın. Kâfirler, zâlimlerin tâ kendileridir."},{"n":255,"t":"Allâh, ki O’ndan başka tanrı yoktur, dâimâ diri ve yaratıklarını koruyup yöneticidir. Kendisini ne bir uyuklama, ne de uyku tutmaz. Göklerde ve yerde olanların hepsi O’nundur. O’nun izni olmadan kendisinin katında kim şefâat edebilir? Onların önlerinde ve arkalarında olanı bilir. O’nun ilminden, ancak kendisinin dilediği kadarından başka bir şey kavrayamazlar. O’nun Kürsüsü, gökleri ve yeri kaplamıştır (O yüce padişah, göklere, yere, bütün kâinâta hükmetmektedir). Onları koru(yup gözet)mek, kendisine ağır gelmez. O yücedir, büyüktür."},{"n":256,"t":"Dinde zorlama yoktur. Doğruluk, sapıklıktan seçilip belli olmuştur. Kim tâğût (şeytân)ı inkâr edip Allah’a inanırsa, muhakkak ki o, kopmayan, sağlam bir kulpa yapışmıştır. Allâh işitendir, bilendir."},{"n":257,"t":"Allâh, inananların dostudur. Onları karanlıklardan aydınlığa çıkarır. kâfirlerin dostları da tâğûttur. (O da) onları aydınlıktan karanlıklara çıkarır. Onlar ateş halkıdır, orada ebedi kalacaklardır."},{"n":258,"t":"Allâh, kendisine hükümdarlık verdi diye (şımararak) Rabbi hakkında İbrâhim’le tartışanı görmedin mi? İbrâhim: \"Benim Rabbim O’dur ki yaşatır, öldürür\" demişti. \"Ben de yaşatır, öldürürüm\" dedi. İbrâhim: \"Allâh, güneşi doğudan getirir, sen de onu batıdan getir!\" deyince inkâr eden o adam şaşırıp kaldı. Allâh, zâlim toplumu doğru yola iletmez."},{"n":259,"t":"Yahut şu kimse gibisini (görmedin mi) ki, duvarları, çatıları üstüne yığılmış (alt üst olmuş) ıssız bir kasabaya uğramıştı; \"Allâh, bunu böyle öldükten sonra nasıl diriltecek?\" demişti. Allâh da kendisini yüz sene öldürüp sonra diriltti. \"Ne kadar kaldın?\" dedi. \"Bir gün, ya da bir günün birazı kadar kaldım\" dedi. (Allâh) \"Hayır, dedi, yüz yıl kaldın. Yiyecek ve içeceğine bak, bozulmamış. Eşeğine bak, seni insanlar için bir ibret kılalım diye (böyle yaptık). Kemiklere bak, nasıl onları birbiri üstüne koyuyor, sonra onlara et giydiriyoruz!\" Bu işler ona açıkça belli olunca: \"Allâh’ın herşeye kâdir olduğunu biliyorum.\" dedi."},{"n":260,"t":"İbrâhim de bir zaman: \"Rabbim, ölüleri nasıl dirilttiğini bana göster!\" demişti. (Allâh); \"İnanmadın mı?\" dedi, (İbrâhim): \"Hayır (inandım), fakat kalbim kuvvet bulsun diye (görmek istiyorum) dedi. \"O halde kuşlardan dördünü tut, onları kendine çek (kendine alıştır), sonra her dağın başına onlardan bir parça koy. Sonra onları kendine çağır; koşarak sana gelecekler. Bil ki, Allâh dâimâ üstün, hüküm ve hikmet sâhibidir\" dedi."},{"n":261,"t":"Mallarını Allâh yolunda harcayanların durumu, her başağında yüz dâne olmak üzere yedi başak veren bir dânenin durumu gibidir. Allâh dilediğine kat kat verir. Allâh(ın lutfu) geniştir, (O) bilendir."},{"n":262,"t":"Mallarını Allâh yolunda verip de sonra verdiklerinin ardından başa kakmayan ve eziyet etmeyenlerin, Rableri katında ödülleri vardır. Onlara korku yoktur ve onlar üzülmeyeceklerdir."},{"n":263,"t":"Güzel bir söz (söylemek) ve affetmek, peşinden eziyet gelen sadakadan iyidir. Allâh, zengindir, halimdir."},{"n":264,"t":"Ey inananlar, insanlara gösteriş için malını verip Allah’a ve âhiret gününe inanmayan adam gibi, başa kakmak ve eziyet etmekle sadakalarınızı boşa çıkarmayın. Öylesinin durumu, üzerinde biraz toprak bulunan şu kayaya benzer ki, bir sağnak indi de (üstündeki toprağı silip süpürerek) onu sert bir taş halinde bıraktı. (Böyleleri), kazandıklarından bir şey elde edemezler. Allâh, kâfir toplumu doğru yola iletmez."},{"n":265,"t":"Allâh’ın rızâsını kazanmak ve ruhlarındaki(imâ)nı kökleştirmek için mallarını harcayanların durumu da tepe üzerinde bulunan bir bahçeye benzer ki, bol yağmur değince ürününü iki kat verdi. Yağmur değmeseydi bile çisinti olurdu. Allâh yaptıklarınızı görmektedir."},{"n":266,"t":"Biriniz ister mi ki, kendisinin altından ırmaklar akan, içinde her çeşit meyvası bulunan, hurmalardan ve üzümlerden oluşmuş bir bahçesi olsun; kendisinin üstüne tam ihtiyarlığın çöktüğü, âciz çocuklarının da bulunduğu bir sırada birden ateşli bir kasırga gelsin de bahçeyi yakıp kül etsin? Allâh, düşünesiniz diye size âyetleri böyle açıklıyor."},{"n":267,"t":"Ey inananlar, kazandıklarınızın ve yerden sizin için çıkardığımız ni’metlerin iyilerinden (Allâh için) verin, kendiniz (utandığınızdan ve iğrendiğinizden dolayı) göz yummadan alamayacağınız kötü şeyleri sadaka vermeye kalkmayın. Bilin ki Allâh zengindir, övülmüştür."},{"n":268,"t":"Şeytân sizi fakirlikle korkutur, (fakir düşeceğinizi söyleyerek sadaka vermekten geri kalmanızı ister) ve size çirkin şeyleri yapmayı emreder. Allâh ise size kendi tarafından bağışlama ve lutuf va’adediyor. Şüphesiz Allâh(ın lutfu) geniştir, (O) bilendir."},{"n":269,"t":"Hikmeti dilediğine verir. Hikmet verilen kimseye çok hayır verilmiştir. Bunu ancak sağduyu sâhipleri düşünüp anlar(lar)."},{"n":270,"t":"(Allâh için) yaptığınız her harcamayı yahut adadığınız her adağı Allâh bilir. Zâlimlerin yardımcısı yoktur."},{"n":271,"t":"Sadakaları açıktan verirseniz ne güzel! Eğer onları gizleyerek fakirlere verirseniz bu, sizin için daha iyidir ve sizin günâhlarınızdan bir kısmını kapatır. Allâh yaptıklarınızı duyar."},{"n":272,"t":"(Ey Muhammed) Onları yola iletmek sana düşmez, dilediğini doğru yola ileten Allah’tır. Verdiğiniz her hayır, kendiniz içindir. Çünkü yalnız Allâh’ın rızâsını kazanmak için veriyorsunuz. Verdiğiniz her hayır, size tastamam verilir ve hiç hakkınız yenmez."},{"n":273,"t":"(Sadakalar) şu fakirlere mahsustur ki, Allâh yolunda kapanıp kalmışlardır. Yeryüzünde gezip dolaşamazlar. Bilmeyen, utangaçlıklarından dolayı onları zengin sanır. Onları simâlarından (yüzlerinden) tanırsın. Yüzsüzlük edip insanlardan istemezler. Yaptığınız her hayrı Allâh bilir."},{"n":274,"t":"Mallarını gece gündüz, gizli ve açık Allâh yolunda verenlerin ödülü Rableri yanındadır. Onlara korku yoktur ve onlar üzülmeyeceklerdir."},{"n":275,"t":"Ribâ yiyenler, ancak şeytânın dokunup çarptığı kimsenin kalktığı gibi kalkarlar. Bu, onların: \"Alışveriş de ribâ gibidir.\" demelerinden ötürüdür. Oysa Allâh, alış-verişi helâl, ribâyı harâm kılmıştır. Kime Rabbi’nden bir öğüt gelir de (o öğüte uyarak ribâdan) vazgeçerse, geçmişte olan kendisinindir ve işi de Allah’a kalmıştır. (Allâh onu affeder). Kim tekrar (ribâya) dönerse onlar ateş halkıdır, orada ebedi kalacaklardır."},{"n":276,"t":"Allâh, ribâyı mahveder, sadakaları artırır. Allâh, hiçbir günâhkâr nankörü sevmez."},{"n":277,"t":"Onlar ki, inandılar, güzel işler yaptılar, namazı kıldılar, zekâtı verdiler; işte onların ödülleri, Rableri yanındadır. Onlara korku yoktur ve onlar üzülmeyeceklerdir."},{"n":278,"t":"Ey inananlar, Allah’tan korkun, eğer inanıyorsanız ribâdan (henüz alınmayıp) geri kalan kısmı bırakın (almayın)."},{"n":279,"t":"Eğer böyle yapmazsanız, Allâh ve Elçisiyle savaşa girdiğinizi bilin. Tevbe ederseniz, ana malınız sizindir. Ne haksızlık edersiniz, ne de haksızlığa uğratılırsınız."},{"n":280,"t":"Eğer (borçlu) darlık içinde ise, bir kolaylığa çıkıncaya kadar beklemek (lâzımdır). Eğer bilirseniz (verdiğiniz borcu, eli darda olan borçluya) sadaka olarak bağışlamanız sizin için daha hayırlıdır."},{"n":281,"t":"Şu günden sakının ki, o gün Allah’a döndürüleceksiniz, sonra herkese kazandığı tastamam verilecek ve onlara haksızlık edilmeyecektir."},{"n":282,"t":"Ey inananlar, belirli bir süreye kadar birbirinize borç verdiğiniz zaman onu yazın. Aranızda bir yazıcı, adâletle yazsın. Yazıcı, Allâh’ın kendisine öğrettiği şekilde yazmaktan kaçınmasın, yazsın; borçlu olan da yazdırsın, Rabbi olan Allah’tan korksun, borcundan hiçbir şeyi eksik etmesin. Eğer borçlu olan kimse aklı ermez, yahut zayıf, ya da kendisi yazdıramayacak durumda ise velisi onu adâletle yazdırsın. Erkeklerinizden iki kişiyi de şâhid tutun. Eğer iki erkek yoksa râzı olduğunuz şâhidlerden bir erkek, iki kadın (şâhidlik etsin). Tâ ki kadınlardan biri şaşırırsa diğeri ona hatırlatsın. Şâhidler çağrıldıkları zaman (gelmekten) kaçınmasınlar. Az olsun, çok olsun, onu süresine kadar yazmaktan üşenmeyin. Bu, Allâh katında daha adâletli, şâhidlik için daha sağlam, kuşkulanmamanız için daha elverişlidir. Yalnız aranızda hemen alıp vereceğiniz peşin ticaret olursa onu yazmamanızdan ötürü üzerinize bir günâh yoktur. Alışveriş yaptığınız zaman da şâhid tutun. Yazana da, şâhide de asla zarar verilmesin. Eğer bunu yaparsanız (zarar verirseniz) şüphe yok ki bu, sizin yoldan çıkmanız demektir. Allah’tan korkun. Allah size gerekli olanı öğretiyor. Allah her şeyi bilmektedir."},{"n":283,"t":"Ve eğer seferde olur da yazacak birini bulamazsanız, alınan rehinler (yeter). Birbirinize güvenirseniz, kendisine güvenilen kimse emânetini ödesin, Rabbi olan Allah’tan korksun. Şâhidliği gizlemeyin, onu gizleyenin kalbi günâhkârdır. Allâh, yaptıklarınızı bilir."},{"n":284,"t":"Göklerdekilerin ve yerdekilerin hepsi Allâh’ındır. İçlerinizdekini açıklasanız da gizleseniz de Allâh sizi onunla hesaba çeker; dilediğini bağışlar, dilediğine azâbeder. Allâh, herşeye kâdirdir."},{"n":285,"t":"Elçi, Rabbinden, kendisine indirilene inandı, mü’minler de. Hepsi Allah’a, meleklerine, Kitaplarına ve peygamberlerine inandı. \"O’nun elçilerinden hiçbirini diğerinden ayırdetmeyiz\" (dediler). Ve dediler ki: \"İşittik, itâ’at ettik! Rabbimiz, (bizi) bağışlamanı dileriz. Dönüş(ümüz) sanadır!\""},{"n":286,"t":"Allâh, kimseye gücünün üstünde bir şey teklif etmez. Herkesin kazandığı iyilik kendi yararına, kötülük de kendi zararınadır. \"Rabbimiz, unutur, ya da yanılırsak bizi sorumlu tutma! Rabbimiz, bize, bizden öncekilere yüklediğin gibi ağır yük yükleme! Rabbimiz, bize gücümüzün yetmediği şeyleri yükleme! Bizi affet, bizi bağışla, bize acı! Sen bizim mevlâmız(sâhibimiz, efendimiz)sin! kâfirler toplumuna karşı bize yardım eyle!\""}],[{"n":1,"t":"Elif lam mim."},{"n":2,"t":"Allâh ki, O’ndan başka tanrı yoktur, dâimâ diri ve (yaratıklarını) koruyup yöneticidir."},{"n":3,"t":"Sana Kitabı gerçek ile ve kendinden öncekini doğrulayıcı olarak indirdi, Tevrât ve İncil’i de indirmişti."},{"n":4,"t":"Daha önce, insanlara yol gösterici olarak, Furkan(doğruyu ve eğriyi birbirinden ayırdeden Kitap)ı da indirdi, Muhakkak ki Allâh’ın âyetlerini tanımayanlar için çetin bir azâb vardır. Allâh dâimâ üstündür ve öc alandır."},{"n":5,"t":"Ne yerde, ne de gökte hiçbir şey Allah’a gizli kalmaz."},{"n":6,"t":"Rahimlerde sizi dilediği gibi şekillendiren O’dur. O’ndan başka tanrı yoktur. O azizdir, hüküm ve hikmet sâhibidir."},{"n":7,"t":"Kitabı sana O indirdi. Onun bazı âyetleri muhkemdir (ki) onlar Kitabın anasıdır. Diğerleri de müteşâbih(birbirine benzeyen, sonucu tam bilinmeyen)dir. Kalblerinde eğrilik olanlar, fitne çıkarmak, uyardığı sonuca uğra(yıp belâlarını bul)mak için onun müteşâbih âyetlerinin ardına düşerler. Oysa onun te’vili(uyardığı sonucun ne zaman gerçekleşeceği)ni Allah’tan başka kimse bilmez. İlimde ileri gidenler: \"Ona inandık, hepsi Rabbimiz katındandır\" derler. Sağduyu sâhiplerinden başkası düşünüp öğüt almaz."},{"n":8,"t":"(Onlar derler ki): \"Rabbimiz, bizi doğru yola ilettikten sonra kalblerimizi eğriltme, bize katından bir rahmet ver, kuşkusuz sen çok bağış yapansın.\""},{"n":9,"t":"\"Rabbimiz, sen mutlaka insanları, asla şüphe olmayan bir günde toplayacaksın.\" Allâh sözünden dönmez."},{"n":10,"t":"İnkâr edenler var ya, ne malları, ne de çocukları onlara, Allah’a karşı hiçbir yarar sağlamaz. Onlar ateşin yakıtıdırlar;"},{"n":11,"t":"Fir’avn âilesinin ve onlardan öncekilerin durumu gibi. Onlar da âyetlerimizi yalanladılar. Allâh da onları günâhlarıyla yakaladı. Allâh’ın cezâsı çetindir."},{"n":12,"t":"İnkâr edenlere söyle: \"Yenileceksiniz ve cehenneme sürüleceksiniz. Orası ne kötü bir döşektir!\""},{"n":13,"t":"Karşılaşan şu iki toplulukta sizin için bir ibret vardır: Bir topluluk Allâh yolunda çarpışıyordu, öteki de nankördü, onları, gözleriyle kendilerinin iki katı görüyorlardı. Allâh dilediğini yardımıyle destekler. Elbette (bunda) gözleri olanlar için bir ibret vardı."},{"n":14,"t":"Kadınlardan, oğullardan, kantarlarca yığılmış altın ve gümüşten, salma atlardan, davarlardan ve ekinlerden gelen zevklere aşırı düşkünlük, insanlara süslü (câzip) gösterildi. Bunlar, sadece dünyâ hayâtının geçimidir. Asıl varılacak güzel yer, Allâh’ın yanındadır."},{"n":15,"t":"De ki: \"Bunlardan daha iyisini size söyleyeyim mi? Korunanlar için Rableri katında altlarından ırmaklar akan, içinde sürekli kalacakları cennetler, tertemiz eşler ve Allâh’ın rızâsı vardır.\" Allâh, kulları görür:"},{"n":16,"t":"\"Rabbimiz, biz inandık, bizim günâhlarımızı bağışla, bizi ateş azâbından koru!\" diyenleri,"},{"n":17,"t":"Sabredenleri, doğru olanları, huzûrunda gönülden boyun büküp divan duranları, Allâh için (mal) harcayanları ve seherlerde istiğfar edenleri (Allah’tan bağışlanmalarını dileyenleri Allâh) görmektedir."},{"n":18,"t":"Allâh, kendisinden başka tanrı olmadığına şâhiddir. Melekler ve ilim sâhipleri de adâletle şâhiddir (ki O’ndan başka tanrı yoktur. O), azizdir, hakimdir."},{"n":19,"t":"Allâh katında din, İslâmdır. Kitap verilmiş olanlar, kendilerine ilim geldikten sonra sırf aralarındaki aşırılık yüzünden ayrılığa düştüler. Kim Allâh’ın âyetlerini inkâr ederse, bilsin ki Allâh, hesabı çabuk görendir."},{"n":20,"t":"Seninle tartışmaya girişirlerse, de ki: \"Ben de özümü Allah’a teslim ettim bana uyanlar da.\" Kendilerine Kitap verilenlere ve ümmilere de ki: \"Siz de İslâm oldunuz mu?\" Eğer İslâm olurlarsa doğru yolu bulmuşlardır. Yok eğer dönerlerse, sana düşen, sadece duyurmaktır. Allâh kulları(nın yaptıklarını) görmektedir."},{"n":21,"t":"Allâh’ın âyetlerini inkâr edenler, haksız yere peygamberleri öldürenler, insanlar arasında adâleti emredenleri öldürenler (var ya), onlara, acı bir azâbı müjdele!"},{"n":22,"t":"Onların yaptıkları, dünyâda da, âhirette de boşa çıkmıştır ve onların hiçbir yardımcıları da yoktur."},{"n":23,"t":"Baksana Kitaptan kendilerine bir pay verilmiş olanlar, aralarında hüküm versin diye Allâh’ın Kitabına çağırılıyorlar da sonra onlardan bir topluluk yüz çevirerek dönüyorlar."},{"n":24,"t":"Bu hareketleri, onların: \"Bize, ateş sayılı birkaç günden başka dokunmayacak.\" demelerinden ileri gelmektedir. Uydurdukları şeyler, onları dinlerinde yanıltmıştır..."},{"n":25,"t":"Peki, ya kendilerini, hiç şüphe olmayan bir gün için topladığımız ve herkesin kazandığı, kendisine tastamam verilip hiç kimseye haksızlık edilmediği zaman (durumları) nasıl (olacak)?"},{"n":26,"t":"De ki: \"Allâh’ım, (ey) mülkün sâhibi, sen dilediğine mülkü verirsin, dilediğinden mülkü alırsın; dilediğini yükseltirsin, dilediğini alçaltırsın. Hayır (mal), senin elindedir. Sen her şeye kâdirsin!\""},{"n":27,"t":"\"Geceyi gündüze sokarsın, gündüzü geceye sokarsın; ölüden diri çıkarırsın, diriden ölü çıkarırsın, dilediğini hesapsız rızıklandırırsın!\""},{"n":28,"t":"Mü’minler, inananları bırakıp, kâfirleri dost edinmesin. Kim böyle yaparsa Allâh ile bir dostluğu kalmaz. Ancak onlardan (gelebilecek tehlikeden) korunmanız başka. (Şerlerinden korunmak için dost gözükebilirsiniz). Allâh sizi kendisin(in emirlerine karşı gelmek)den sakındırır. (Sakın hükümlerine aykırı davranarak, düşmanlarını dost tutarak O’nun gazabına uğramayın. Çünkü) dönüş Allah’adır."},{"n":29,"t":"De ki: \"Göğüslerinizde olanı gizleseniz de, açığa vursanız da Allâh onu bilir; göklerde ve yerde olanları da bilir. Allâh her şeye kâdirdir."},{"n":30,"t":"O gün her nefis, yaptığı her hayrı hazır bulacaktır; işlediği her kötülüğü de. O kötülükle kendisi arasında uzak bir mesafe bulunmasını ister. Allâh sizi kendisin(in emirlerine karşı gelmek)den sakındırıyor. Allâh, kulllarına şefkatlidir."},{"n":31,"t":"De ki: \"Eğer Allâh’ı seviyorsanız bana uyun ki Allâh da sizi sevsin ve günâhlarınızı bağışlasın. Allâh bağışlayandır, esirgeyendir.\""},{"n":32,"t":"De ki: \"Allah’a ve Elçiye itâ’at edin!\" Eğer dönerlerse muhakkak ki Allâh, kâfirleri sevmez."},{"n":33,"t":"Allâh Âdem’i, Nûh’u, İbrâhim âilesini ve İmrân âilesini seçip âlemlere üstün kıldı."},{"n":34,"t":"(Bunlar) Birbirinden türeyen nesil(ler)dir. Allâh işitendir, bilendir."},{"n":35,"t":"İmrân’ın karısı demişti ki: \"Rabbim, karnımda olanı tam hür olarak sana adadım, benden kabul buyur; şüphesiz sen işitensin, bilensin.\""},{"n":36,"t":"Onu doğurunca Allâh onun ne doğurduğunu bilirken yine şöyle söyledi: \"Rabbim, onu kız doğurdum, erkek, kız gibi değildir. Ona Meryem adını verdim. Onu ve soyunu kovulmuş şeytânın şerrinden sana ısmarlıyorum.\""},{"n":37,"t":"Rabbi onu güzel bir şekilde kabul buyurdu; onu güzel bir bitki gibi yetiştirdi ve Zekeriyyâ da onun bakımını üstlendi. Zekeriyyâ, onun yanına, mihrâba her girdiğinde yanında bir rızık bulurdu. \"Ey Meryem, bu sana nereden?\" derdi. (O da) \"Bu, Allâh katından\" derdi. \"Allâh, dilediğine hesapsız rızık verir.\""},{"n":38,"t":"Orada Zekeriyyâ, Rabbine du’â etmiş: \"Rabbim, demişti, bana katından temiz bir nesil ver. Sen du’âyı işitensin!\""},{"n":39,"t":"Zekeriyyâ, mabedde durmuş namaz kılarken, melekler ona: \"Allâh sana, Allah’tan bir kelimeyi doğrulayıcı, efendi, nefsine hakim ve iyilerden bir peygamber olacak Yahya’yı müjdeler,\" diye ünlediler."},{"n":40,"t":"Dedi ki: \"Rabbim, bana ihtiyarlık gelip çatmış, karım da kısırken benim nasıl oğlum olur?\" (Allâh): \"Öyle (ama) Allâh, dilediğini yapar.\" dedi."},{"n":41,"t":"\"Rabbim, o halde bana (oğlum olacağına dair) bir alâmet ver!\" dedi. (Allâh) buyurdu ki: \"Senin alâmetin üç gün insanlarla işâretten başka türlü konuşamamandır; Rabbini çok an, akşam sabah (O’nu) tesbih et!\""},{"n":42,"t":"Melekler demişti ki: \"Ey Meryem, Allâh seni seçti, temizledi ve seni dünyâların kadınlarına üstün kıldı.\""},{"n":43,"t":"\"Ey Meryem, Rabbine divân dur, secde et ve (O’nun huzûrunda) eğilenlerle beraber eğil!\""},{"n":44,"t":"(Ey Muhammed) Bunlar sana vahyettiğimiz, görünmez âlemin haberlerindendir. Meryem’e hangisi kefil olacak diye (kur’a) oklarını atarlarken sen onların yanında değildin; birbirleriyle çekiştikleri zaman da sen yanlarında değildin."},{"n":45,"t":"Melekler demişti ki: \"Ey Meryem, Allâh seni, kendisinden bir kelime ile müjdeliyor: Adı Meryem oğlu Îsâ Mesih’dir; dünyâda da, âhirette de gözde (şerefli) ve (Allah’a) yakın olanlardandır.\""},{"n":46,"t":"\"Beşikte ve yetişkinlikte insanlara konuşacak ve iyilerden olacaktır.\""},{"n":47,"t":"Dedi ki: \"Rabbim, bana bir beşer dokunmamışken benim nasıl çocuğum olur?\" \"Allâh, böylece dilediğini yaratır, dedi, bir şey(in olmasını) istedi mi ona ’ol’ der, o da oluverir.\""},{"n":48,"t":"\"Ona Kitabı, Hikmeti, Tevrât’ı ve İncil’i öğretecek.\""},{"n":49,"t":"\"Onu İsrâil oğullarına (şöyle diyen) bir elçi yapacak: \"Ben size Rabbinizden bir mu’cize getirdim: Ben çamurdan kuş şeklinde bir şey yaratır, ona üflerim, Allâh’ın izniyle hemen kuş oluverir; körü ve alacalıyı iyileştiririm; Allâh’ın izniyle ölüleri diriltirim; evlerinizde ne yeyip, ne biriktirdiğinizi size haber veririm. Eğer inanıcı iseniz elbette bunda sizin için bir ibret vardır.\""},{"n":50,"t":"\"(Ben), Benden önce gelen Tevrât’ı doğrulayıcı olarak ve size harâm kılınan bazı şeyleri size helâl yapayım diye gönderildim. Size Rabbinizden bir mu’cize getirdim, Allah’tan korkun, bana itâ’at edin!\""},{"n":51,"t":"\"Allâh benim de Rabbim, sizin de Rabbinizdir; O’na kulluk edin, doğru yol budur.\""},{"n":52,"t":"Îsâ onlardan inkârı sezince: \"Allâh yolunda kimler bana yardımcı olacak?\" dedi. Havariler: \"Biz, Allâh(yolun)un yardımcılarıyız; Allah’a inandık, şâhid ol, biz müslümanlarız.\" dediler."},{"n":53,"t":"\"Rabbimiz, senin indirdiğine inandık, elçiye uyduk; bizi şâhidlerle beraber yaz!\""},{"n":54,"t":"Tuzak kurdular, Allâh da onların tuzaklarına karşılık verdi; çünkü Allâh, en iyi tuzak kurandır."},{"n":55,"t":"Allâh demişti ki: \"Ey Îsâ, ben senin canını alacağım, seni bana yükselteceğim, seni inkâr edenlerden temizleyeceğim ve sana uyanları kıyâmet gününe kadar inkâr edenlerin üstünde tutacağım. Sonra dönüşünüz bana olacaktır. Ayrılığa düştüğünüz şeyler hakkında aranızda ben hükmedeceğim.\""},{"n":56,"t":"\"İnkâr edenlere gelince, onlara dünyâda da, âhirette de şiddetle azâbedeceğim, onların yardımcıları da olmayacaktır.\""},{"n":57,"t":"İnanıp iyi şeyler yapanlara da (Allâh) mükâfâtlarını tam olarak verecektir. Allâh zâlimleri sevmez."},{"n":58,"t":"İşte bu sana okuduğumuz, o âyetlerden ve o hikmetli Zikir(Kitap)dandır."},{"n":59,"t":"Allah’a göre Îsâ’nın durumu, Âdem’in durumu gibidir: Onu, topraktan yarattı, sonra ona \"Ol!\" dedi, artık olur..."},{"n":60,"t":"(Bu,) Rabbinden gelen gerçektir. Öyle ise kuşkulananlardan olma."},{"n":61,"t":"Kim sana gelen ilimden sonra seninle tartışmaya kalkarsa, de ki: \"Gelin oğullarımızı ve oğullarınızı, kadınlarımızı ve kadınlarınızı, kendimizi ve kendinizi çağıralım, sonra gönülden la’netle du’â edelim de, Allâh’ın la’netini yalancıların üstüne atalım!\""},{"n":62,"t":"İşte (Îsâ hakkındaki) gerçek kıssa (öykü) budur. Allah’tan başka tanrı yoktur. Allâh, elbette aziz (kesin gâlib), hüküm ve hikmet sâhibidir."},{"n":63,"t":"Eğer dönerlerse, muhakkak ki Allâh, bozguncuları bilir."},{"n":64,"t":"De ki: \"Ey Kitap ehli, bizim ve sizin aranızda eşit olan bir kelimeye gelin: \"Yalnız Allah’a tapalım. O’na hiçbir şeyi ortak koşmayalım; birbirimizi Allah’tan başka tanrılar edinmeyelim.\" Eğer yüz çevirirlerse; \"Şâhid olun, biz müslümanlarız!\" deyin."},{"n":65,"t":"Ey Kitap ehli, neden İbrâhim hakkında tartışıyorsunuz? Oysa Tevrât da, İncil de ondan sonra indirilmiştir. Düşünmüyor musunuz?"},{"n":66,"t":"Haydi siz, biraz bilginiz olan şey hakkında tartıştınız; ama hiç bilginiz olmayan şey hakkında neden tartışıyorsunuz? Allâh bilir, siz bilmezsiniz."},{"n":67,"t":"İbrâhim ne yahûdi, ne de hıristiyandı; dosdoğru bir müslümandı. Müşriklerden de değildi."},{"n":68,"t":"Doğrusu, insanların İbrâhim’e en yakın olanı, ona uyanlar, bu peygamber ve mü’minlerdir. Allâh da mü’minlerin dostudur."},{"n":69,"t":"Kitap ehlinden bir grup istedi ki sizi saptırsınlar. Oysa sadece kendilerini saptırıyorlar; fakat farkında değiller."},{"n":70,"t":"Ey Kitap ehli, (gerçeği) gördüğünüz halde, niçin Allâh’ın âyetlerini inkâr ediyorsunuz?"},{"n":71,"t":"Ey Kitap ehli, niçin hakkı bâtıla karıştırıyor ve bile bile gerçeği gizliyorsunuz?"},{"n":72,"t":"Kitap ehlinden bir grup dedi ki: \"İnananlara indirilmiş olana, günün önünde inanın, sonunda inkâr edin; belki (size bakarak onlar da) dönerler;\""},{"n":73,"t":"\"Sizin dininize uyandan başkasına güvenmeyin!\" (dediler.) De ki: \"Hidâyet Allâh’ın hidâyetidir. Birine, size verilenin benzerinin verilmesinden veya Rabbinizin huzûrunda aleyhinize deliller getireceklerinden ötürü mü (böyle söylüyorsunuz)?, De ki: \"Lutuf Allâh’ın elindedir, onu dilediğine verir, Allâh(ın lutfu) geniştir, (O her şeyi) bilendir."},{"n":74,"t":"Rahmetini dilediğine has kılar. Allâh, büyük lutuf ve ikram sâhibidir."},{"n":75,"t":"Kitap ehlinden öylesi vardır ki, ona yüklerle emânet bıraksan, onu sana öder. Onlardan öylesi de vardır ki, ona bir dinar versen, devamlı olarak başına dikilmeden onu sana ödemez. Onlar \"Ümmilere karşı bize bir sorumluluk yoktur.\" dedikleri için böyle yapıyorlar ve Allah’a karşı bile bile yalan söylüyorlar."},{"n":76,"t":"Hayır, kim sözünü yerine getirir ve (günâhtan) korunursa, şüphesiz Allâh da korunanları sever."},{"n":77,"t":"Fakat Allah’a verdikleri sözü ve yeminlerini az bir paraya satanlar var ya, işte onların âhirette bir payı yoktur; Allâh kıyâmet günü onlara konuşmayacak, onlara bakmayacak ve onları yüceltmeyecektir. Onlar için acı bir azâb vardır."},{"n":78,"t":"Onlardan bir grup var ki, Kitapta olmayan bir şeyi, siz Kitaptan sanasınız diye dillerini Kitapla eğip büker (sözlerini, Kitabın sözü imiş gibi göstermek için kelimeleri dillerinde bükerek okur, onları, Kitabın sözlerine benzetmeğe çalışır)lar ve: \"O, Allâh katındandır.\" derler. Oysa o, Allâh katından değildir. Bile bile Allah’a karşı yalan söylerler."},{"n":79,"t":"Hiçbir insana yakışmaz ki, Allâh ona Kitap, hüküm (hikmet) ve peygamberlik versin de, sonra (o kalksın) insanlara: \"Allâh’ı bırakıp bana kullar olun\", desin; fakat: \"Öğrettiğiniz Kitap ve okuduğunuz şeyler gereğince Rabba halis kullar olun!\" der."},{"n":80,"t":"Ve size: \"Melekleri ve peygamberleri tanrılar edinin!\" diye de emretmez. Siz müslüman olduktan sonra, size inkârı emreder mi?"},{"n":81,"t":"Allâh, peygamberlerden şöyle söz almıştı: \"Bakın, size Kitap ve hikmet verdim; imdi yanınızda bulunan(Kitap)ı doğrulayıcı bir peygamber geldiğinde, ona mutlaka inanacak ve ona mutlaka yardım edeceksiniz! Bunu kabul ettiniz mi? Ve bu hususta ağır ahdimi üzerinize aldınız mı?\" demişti. \"Kabul ettik!\" dediler. \"O halde tanık olun, ben de sizinle beraber tanık olanlardanım.\" dedi."},{"n":82,"t":"Artık kim bundan sonra dönerse, işte onlar fâsıklardır."},{"n":83,"t":"Allâh’ın dininden başkasını mı arıyorlar? Oysa göklerde ve yerde olanların hepsi, ister istemez, O’na teslim olmuştur ve O’na döndürüleceklerdir."},{"n":84,"t":"De ki: \"Allah’a, bize indirilene, İbrâhim’e, İsmâ’il’e, İshak’a, Ya’kûb’a ve sıbtlara (Ya’kûb oğullarından türeyen kabilelere) indirilene; Mûsâ’ya, Îsâ’ya ve peygamberlere Rableri tarafından verilene inandık; onlar arasında bir ayırım yapmayız, biz O’na teslim olanlarız.\""},{"n":85,"t":"Kim İslâm’dan başka bir din ararsa, bilsin ki, (o din) ondan kabul edilmeyecek ve o, âhirette kaybedenlerden olacaktır."},{"n":86,"t":"İman ettikten, Resul’ün hak olduğunu gördükten ve kendilerine açık deliller geldikten sonra, inkâr eden bir topluma Allâh nasıl yol gösterir? Allâh, zâlim toplumu doğru yola iletmez."},{"n":87,"t":"İşte onların cezâsı: Allâh’ın, meleklerin ve bütün insanların la’neti onların üzerinedir!"},{"n":88,"t":"O(la’net)in içinde ebedi kalacaklardır. Onlardan azâb hafifletilmeyecek ve onlara asla fırsat verilmeyecektir."},{"n":89,"t":"Ancak ondan sonra, tevbe edip uslananlar başka. Çünkü Allâh, çok bağışlayan, çok esirgeyendir."},{"n":90,"t":"Onlar ki, inandıktan sonra inkâr ettiler, sonra inkârları arttı; onların tevbeleri kabul edilmeyecektir. Onlar sapıkların tâ kendileridir."},{"n":91,"t":"İnkâr edip kâfir olarak ölenler, dünyâ dolusu altın fidye vermiş olsa dahi hiçbirinden kabul edilmeyecektir. Onlar için acı bir azâb vardır ve onların hiçbir yardımcıları yoktur!"},{"n":92,"t":"Sevdiğiniz şeylerden (Allâh için) harcamadıkça asla iyiliğe eremezsiniz. Ne harcarsanız Allâh onu bilir."},{"n":93,"t":"Tevrât indirilmeden önce, İsrâil’in kendisine harâm kıldığı şeyler dışında, İsrâil oğullarına bütün yiyecekler helâldi. De ki: \"Doğru iseniz, Tevrât’ı getirip okuyun.\""},{"n":94,"t":"Artık bundan sonra da kim Allah’a yalan uydurursa, işte onlar zâlimlerdir."},{"n":95,"t":"De ki: \"Allâh doğru söyledi, öyle ise dosdoğru, Allâh’ı birleyici olarak İbrâhim dinine uyun. O, ortak koşanlardan değildi.\""},{"n":96,"t":"Doğrusu insanlara (ma’bed olarak) ilk kurulan ev, Mekke’de olandır. Âlemlere uğur, bereket ve hidâyet kaynağı olarak kurulmuştur."},{"n":97,"t":"Onda açık açık deliller, İbrâhim’in Makâmı vardır. Ona giren, güvene erer. Yoluna gücü yeten herkesin, o Ev’e gi(dip haccet)mesi, insanlar üzerinde Allâh’ın bir hakkıdır. Kim nankörlük ederse şüphesiz Allâh, bütün âlemlerden zengindir."},{"n":98,"t":"De ki: \"Ey Kitap ehli, Allâh yaptıklarınıza tanık iken neden Allâh’ın âyetlerini inkâr ediyorsunuz?\""},{"n":99,"t":"De ki: \"Ey Kitap ehli, gerçeğe tanık olduğunuz halde, niçin Allâh’ın yolunu eğri göstermeğe yeltenerek, inanmak isteyenleri Allâh yolundan çevirmeğe çalışıyorsunuz? Allâh yaptıklarınızdan habersiz değildir.\""},{"n":100,"t":"Ey inananlar, Kitap verilenlerden herhangi bir gruba uyarsanız imanınızdan sonra, (onlar) sizi döndürüp kâfir yaparlar."},{"n":101,"t":"Size Allâh’ın âyetleri okunmakta ve O’nun Elçisi de aranızda iken nasıl inkâr edersiniz? Kim Allah’a sarılırsa muhakkak ki o, doğru yola iletilmiştir."},{"n":102,"t":"Ey inananlar, Allah’tan, O’na yaraşır biçimde korkun ve ancak müslümanlar olarak ölün."},{"n":103,"t":"Ve topluca Allâh’ın ipine yapışın, ayrılmayın; Allâh’ın size olan ni’metini hatırlayın: Hani siz birbirinize düşman idiniz, (Allâh) kalblerinizi uzlaştırdı. O’nun ni’metiyle kardeşler haline geldiniz. Siz ateşten bir çukurun kenarında bulunuyordunuz, (Allâh) sizi ondan kurtardı. Allâh size âyetlerini böyle açıklıyor ki, yola gelesiniz."},{"n":104,"t":"İçinizden hayra çağıran, iyiliği emredip kötülükten men’eden bir topluluk olsun; işte onlar kurtuluşa erenlerdir."},{"n":105,"t":"Kendilerine açık deliller geldikten sonra bölünüp ihtilâf edenler gibi olmayın. İşte onlar (evet) onlar için büyük bir azâb vardır."},{"n":106,"t":"O gün bazı yüzler ağarır, bazı yüzler kararır. Yüzleri kararanlara: \"İnanmanızdan sonra inkâr ettiniz ha? Öyle ise inkâr etmenize karşılık azâbı tadın!\" (denilir)."},{"n":107,"t":"Yüzleri ağaranlar ise Allâh’ın rahmeti içindedirler, orada sürekli kalacaklardır."},{"n":108,"t":"İşte onlar Allâh’ın âyetleridir. Onları sana gerçek ile okuyoruz. Allâh, âlemlere zulmetmek istemez."},{"n":109,"t":"Göklerde ve yerde olanların hepsi Allâh’ındır. Bütün işler Allah’a döndürülür."},{"n":110,"t":"Siz, insanlar için çıkarılmış en hayırlı bir ümmet oldunuz. İyiliği emreder, kötülükten men edersiniz ve Allah’a inanırsınız. Eğer Kitap ehli, inanmış olsaydı, elbette kendileri için iyi olurdu. Onlardan inananlar da var, ama çokları yoldan çıkmışlardır."},{"n":111,"t":"Size eziyetten başka bir zarar veremezler. Sizinle savaşsalar bile, size arkalarını dönüp kaçarlar, sonra onlara yardım da edilmez."},{"n":112,"t":"Nerede olsalar, onlara alçaklık (damgası) vurulmuştur (ezilmeğe mahkûmdurlar). Meğer ki Allâh’ın ahdine ve (inanan) insanların ahdine sığınmış olsunlar. Allâh’ın gazabına uğradılar ve üzerlerine miskinlik damgası vuruldu (yoksulluk içinde ezildiler). Böyle oldu, çünkü onlar Allâh’ın âyetlerini inkâr ediyorlar, haksız yere peygamberleri öldürüyorlardı ve çünkü isyân etmişlerdi, haddi aşıyorlardı."},{"n":113,"t":"Ama hepsi bir değildir. Kitap ehli içinde, gece sâatlerinde ayakta durup Allâh’ın âyetlerini okuyarak secdeye kapanan bir topluluk da vardır."},{"n":114,"t":"Onlar, Allah’a ve âhiret gününe inanırlar, iyiliği emreder, kötülükten men ederler; hayır işlerine koşarlar. İşte onlar iyilerdendir."},{"n":115,"t":"Yapacakları hiçbir iyilik inkâr edilmeyecektir. Şüphesiz Allâh, (günâhlardan) korunanları bilmektedir."},{"n":116,"t":"Nankörlere gelince, ne malları, ne de evlâdları onlara, Allah’a karşı hiçbir yarar sağlamayacaktır. Onlar ateş halkıdır; onlar orada sürekli kalacaklardır."},{"n":117,"t":"Onların bu dünyâ hayâtında harcadıkları malların durumu, nefislerine zulmeden bir topluluğun ekinine vurup onu mahveden dondurucu bir rüzgâr(ın tahribatın)a benzer. Allâh onlara zulmetmedi; fakat onlar, kendi kendilerine zulmediyorlardı."},{"n":118,"t":"Ey inananlar, kendinizden başkasını kendinize dost edinmeyin; onlar sizi bozmaktan geri durmazlar. Size sıkıntı verecek şeyleri isterler. Onların ağızlarından öfke taşmaktadır. Göğüslerinde gizledikleri (kin) ise daha büyüktür. Düşünürseniz, size âyetleri açıkladık."},{"n":119,"t":"İşte, siz öyle kimselersiniz ki, onları seversiniz, halbuki onlar sizi sevmezler. Kitabın hepsine inanırsınız. Onlar sizinle karşılaştıkları zaman \"İnandık\" derler. Ama kendi başlarına kaldıklarında, size karşı öfkeden parmak uçlarını ısırırlar. De ki: \"Öfkenizden ölün! Şüphesiz Allâh, göğüslerin özünü bilir.\""},{"n":120,"t":"Size bir iyilik dokunsa (bu,) onları tasalandırır; size bir kötülük dokunsa, ona sevinirler. Eğer sabreder, korunursanız, onların tuzağı size hiçbir zarar vermez. Şüphesiz Allâh, onların yaptıklarını kuşatmıştır."},{"n":121,"t":"Hani sen, erkenden âilenden ayrılmıştın, (Uhud’da) mü’minleri savaş üslerine yerleştiriyordun. Allâh da işitendi, bilendi."},{"n":122,"t":"Sizden iki takım, korkup bozulmaya yüz tutmuştu. Halbuki Allâh, kendilerinin dostu idi. İnananlar, Allah’a dayansınlar."},{"n":123,"t":"(Allâh mü’minlere yardım eder). Nitekim Allâh, zayıf durumda bulunduğunuz Bedir’de de size yardım etmişti. O halde Allah’tan korkun ki, şükredesiniz."},{"n":124,"t":"O zaman sen mü’minlere: \"Rabbinizin, size, indirilmiş üç bin melek ile yardım etmesi, size yetmez mi?\" diyordun."},{"n":125,"t":"Evet, sabreder, korunursanız; onlar hemen şu dakikada üzerinize gelseler, Rabbiniz size nişanlı beşbin melekle yardım eder."},{"n":126,"t":"Allâh bu(yardım va’di)ni sırf size müjde olsun ve kalbleriniz bununla güven bulsun diye yaptı. Yardım, yalnız, dâimâ gâlib, hüküm ve hikmet sâhibi Allâh katındandır."},{"n":127,"t":"İnkâr edenlerden bir kısmını kessin ve perişan etsin de umutsuz olarak dönüp gitsinler diye (size yardım eder)."},{"n":128,"t":"O konuda senin yapacağın bir şey yoktur. Allâh, ya tevbelerini kabul edip onları affeder, ya da zâlim olduklarından dolayı onlara azâb eder."},{"n":129,"t":"Göklerde ve yerde olanların hepsi Allâh’ındır. (O), dilediğini bağışlar, dilediğine azâbeder, Allâh, çok bağışlayan, çok esirgeyendir."},{"n":130,"t":"Ey inananlar, kat kat ribâ yemeyin, Allah’tan korkun ki, kurtuluşa eresiniz."},{"n":131,"t":"Kâfirler için hazırlanmış ateşten sakının!"},{"n":132,"t":"Allah’a ve Elçiye itâ’at edin ki, size merhamet edilsin."},{"n":133,"t":"Rabbinizden bir bağışlanmaya ve genişliği göklerle yer arası kadar olan, korunanlar için hazırlanmış cennete koşun!"},{"n":134,"t":"O(koruna)nlar bollukta ve darlıkta Allâh için harcarlar, öfke(lerin)i yutkunurlar, insanları affederler. Allâh da güzel davrananları sever."},{"n":135,"t":"Ve onlar bir kötülük yaptıkları, ya da nefislerine zulmettikleri zaman, Allâh’ı hatırlayarak hemen günâhlarının bağışlanmasını dilerler; günâhları da Allah’tan başka kim bağışlayabilir? Ve onlar, hatâlarında bile bile, ısrar etmezler."},{"n":136,"t":"İşte onların mükâfâtı Rableri tarafından bağışlanma ve altlarından ırmaklar akan, içinde sürekli kalacakları cennetlerdir. Çalışanların ücreti ne güzeldir!"},{"n":137,"t":"Sizden önce de yasalar uygulanmıştır. Yeryüzünde dolaşın da yalanlayıcıların sonunun nasıl olduğunu görün."},{"n":138,"t":"Bu, insanlara bir açıklama, korunanlara yol gösterme ve öğüttür."},{"n":139,"t":"Gevşemeyin, üzülmeyin, eğer inanıyorsanız, mutlaka siz üstün geleceksiniz."},{"n":140,"t":"Eğer size bir yara dokunduysa, o topluluğa da benzeri bir yara dokunmuştu. O günler... onları biz insanlar arasında çevirip dururuz (kâh bir kavme, kâh ötekine gâlibiyet veririz; bazen bir topluma iyi veya kötü günler gösteririz, bazan ötekine). Allâh inananları ortaya çıkarmak, sizden şehidler edinmek için (zamanı kâh lehinize, kâh aleyhinize çevirmektedir). Allâh, zâlimleri sevmez."},{"n":141,"t":"Ve inananları iyice özleştirmek, kâfirleri de mahvetmek için (günleri insanlar arasında böyle çevirmektedir)."},{"n":142,"t":"Yoksa siz, Allâh, içinizden cihâd edenleri (sınayıp) bilmeden, sabredenleri (sınayıp) bilmeden cennete gireceğinizi mi sandınız?"},{"n":143,"t":"Andolsun ki, siz ölümle karşılaşmadan önce onu arzuluyordunuz. İşte onu gördünüz, ama bakıp duruyorsunuz."},{"n":144,"t":"Muhammed, sadece bir elçidir. Ondan önce de elçiler gelip geçmiştir. Şimdi o ölür veya öldürülürse siz ökçelerinizin üzerinde geriye mi döneceksiniz? Kim ökçesi üzerinde geriye dönerse, Allah’a hiçbir ziyan veremez. Allâh, şükredenleri mükâfâtlandıracaktır."},{"n":145,"t":"Allâh’ın izni olmadan hiçbir kişi ölmez. (Ölüm) Belirli bir süreye göre yazılmıştır. Kim dünyâ sevâbını (menfaatini) isterse, kendisine ondan veririz; kim âhiret sevâbını isterse, kendisine ondan veririz, şükredenleri mükâfâtlandıracağız."},{"n":146,"t":"Nice peygamber var ki, kendileriyle beraber birçok erenler çarpıştılar; Allâh yolunda başlarına gelenlerden yılmadılar, zayıflık göstermediler, boyun eğmediler. Allâh sabredenleri sever."},{"n":147,"t":"Sadece şöyle diyorlardı: \"Rabbimiz, bizim günâhlarımızı ve işimizde taşkınlığımızı bağışla, ayaklarımızı (yolunda) sağlam tut, kâfir topluma karşı bize yardım eyle!\""},{"n":148,"t":"Allâh da onlara hem dünyâ karşılığını, hem âhiret karşılığının en güzelini verdi. Çünkü Allâh, güzel davrananları sever."},{"n":149,"t":"Ey inananlar, eğer inkâr edenlere itâ’at ederseniz, sizi arkanıza (küfre) çevirirler, o zaman büsbütün kaybedersiniz."},{"n":150,"t":"Hayır, Mevlânız Allah’a (itâ’at edin), yardımcıların en iyisi O’dur."},{"n":151,"t":"Allâh’ın, kendilerine hiçbir güç (vermediği, haklarında hiçbir delil) indirmediği şeyleri, Allah’a ortak koştuklarından dolayı inkâr edenlerin kalblerine korku salacağız; gidecekleri yer de cehennemdir! Zâlimlerin varacağı yer, ne kötüdür!"},{"n":152,"t":"Kendi izniyle onları öldürdüğünüz sürece Allâh, size (yardım) va’dini doğruladı: Nihâyet siz korktunuz, Allâh size sevdiğiniz(gâlibiyet)i gösterdikten sonra (verilen) emir hakkında (birbirinizle) çekişip isyân ettiniz: Kiminiz dünyâyı istiyordu, kiminiz âhireti istiyordu. Sonra Allâh sizi denemek için onlardan geri çevirdi (yenilgiye uğrattı. Buna rağmen) sizi bağışladı. Allâh mü’minlere karşı çok lutufkârdır."},{"n":153,"t":"Elçi, aranızdan sizi çağırırken siz, boyuna uzaklaşıyor, hiç kimseye dönüp bakmıyordunuz. Bundan dolayı Allâh, size gam üstüne gam verdi ki ne elinizden gidene, ne de başınıza gelene üzülmeyesiniz. Allâh, yaptıklarınızı duymaktadır."},{"n":154,"t":"Sonra o üzüntünün ardından (Allâh) size bir güven, bir kısmınızı bürüyen bir uyku indirdi; bir kısmınız da kendi canlarının kaygısına düşmüştü. Allah’a karşı câhiliyye zannı gibi haksız bir zanda bulunuyorlar: \"Bu işten bize bir şey var mı?\" diyorlardı. De ki: \"Bütün iş, Allah’a aittir.\" Onlar sana açıklayamadıklarını içlerinde gizliyorlar. Diyorlar ki: \"Bu işten bize bir fayda olsaydı, burada öldürülmezdik.\" De ki: \"Evlerinizde dahi olsaydınız, yine üzerine öldürülme(si) yazılmış olanlar, mutlaka (vurulup) yatacakları yeri boylardı. Allâh göğüslerinizdekini denemek, kalblerinizdekini açığa çıkarmak için (bunları başınıza getirdi)\". Allâh göğüslerin özünü bilir."},{"n":155,"t":"İki topluluğun karşılaştığı gün, içinizden yüz çevirip gidenleri, yaptıkları bazı işlerden dolayı şeytân, (yoldan) kaydırmak istemişti. Ama yine de Allâh, onları affetti. Şüphesiz Allâh, çok bağışlayandır, halimdir."},{"n":156,"t":"Ey inananlar, siz inkâr edenler ve yeryüzünde sefere, ya da savaşa çıkan gazi kardeşleri için: \"Eğer bizim yanımızda olsalardı ölmezlerdi ve vurulmazlardı.\" diyenler gibi olmayın. Allâh, onların bu düşünce ve sözlerini, kalblerinde dert yapar. Yaşatan da, öldüren de Allahtır. Allâh, yaptıklarınızı görmektedir."},{"n":157,"t":"Eğer Allâh yolunda öldürülür, ya da ölürseniz, Allâh’ın bağışlaması ve rahmeti, onların topladıkları(dünyâ malı)ndan daha hayırlıdır."},{"n":158,"t":"Ölür veya öldürülürseniz, elbette Allah’a götürüleceksiniz!"},{"n":159,"t":"Allâh’ın rahmeti sebebiyledir ki, sen onlara yumuşak davrandın. Eğer kaba, katı yürekli olsaydın, çevrenden dağılır, giderlerdi. Öyleyse onlar(ın kusurların)dan geç, onlar için mağfiret dile. İşini onlara danış, karar verince de Allah’a dayan; çünkü Allâh kendine dayanıp güvenenleri sever."},{"n":160,"t":"Eğer Allâh size yardım ederse, artık sizi yenecek yoktur. Ve eğer sizi yüz üstü bırakırsa, O’ndan sonra size kim yardım edebilir? Mü’minler, Allah’a dayansınlar."},{"n":161,"t":"Bir peygamberin aşırması, hiyanet etmesi, olur şey değildir. Kim (emânete hıyanet eder), aşırırsa kıyâmet günü aşırdığını boynuna yüklenip getirir. Sonra herkese kazandığı tastamam verilir, hiçbir haksızlığa uğratılmazlar."},{"n":162,"t":"Hiç Allâh’ın rızâsına uyan kimse; Allâh’ın hışmına uğrayan, yeri de cehennem olan adam gibi olur mu? Ne kötü sonuçtur orası!"},{"n":163,"t":"O(insa)nlar, Allâh katında derece derecedirler. Allâh, onların yaptıklarını görmektedir."},{"n":164,"t":"Andolsun ki, Allâh, mü’minlere büyük lutufta bulundu: Zira daha önce açık bir sapıklık içinde bulunuyorlarken onlara, kendi içlerinden, kendilerine Allâh’ın âyetlerini okuyan, kendilerini yücelten ve kendilerine Kitap ve hikmeti öğreten bir elçi gönderdi."},{"n":165,"t":"Başınıza bir belâ gelince -siz, onun iki katını onların başlarına getirmiş olduğunuz halde yine- Bu nereden başımıza geldi?\" dediniz. De ki: \"O (belâ), kendinizdendir.\" Allâh, herşeye kâdirdir."},{"n":166,"t":"İki topluluğun karşılaştığı gün, sizin başınıza gelen, ancak Allâh’ın izniyle olmuştur ki (O), inananları bilsin (deneyip ortaya çıkarsın)."},{"n":167,"t":"Ve iki yüzlülük edenleri bilsin (ortaya çıkarsın). Onlara: \"Gelin, Allâh yolunda savaşın, ya da savunun.\" dendiği halde: \"Eğer savaş (olacağını) bilseydik, sizinle gelirdik.\" dediler. Onlar, o gün, imandan çok küfre yakın idiler. Ağızlarıyla, kalblerinde olmayanı söylüyorlar. Halbuki Allâh, içlerinde sakladıkları şeyi çok iyi bilmektedir."},{"n":168,"t":"(Savaştan geri kalıp) Oturarak, kardeşleri için \"Bizim sözümüzü tutsalardı, öldürülmezlerdi.\" diyenlere söyle: \"Eğer doğru iseniz, kendinizden ölümü savınız!\""},{"n":169,"t":"Allâh yolunda öldürülenleri ölüler sanma; hayır, (onlar) diridirler, Rableri katında rızıklanmaktadırlar."},{"n":170,"t":"Allâh’ın, keremiyle kendilerine verdiklerinden sevinçli olarak, arkalarından henüz kendilerine yetişemeyenlere de korku olmadığına, onların da üzüntüye uğramayacaklarına sevinirler."},{"n":171,"t":"Allâh’ın ni’metine, lutfuna ve Allâh’ın mü’minlerin ecrini zayi etmeyeceğine sevinirler."},{"n":172,"t":"O(mü’mi)nler ki yaralandıkları halde yine Allâh’ın ve Elçinin çağrısına uydular; onlardan güzel davrananlar ve (günâhlardan) korunanlar için pek büyük ecir vardır."},{"n":173,"t":"Onlar ki, halk kendilerine: \"(Düşman) İnsanlar size karşı ordu toplamışlar, onlardan korkun!\" deyince, (bu söz,) onların imanını artırdı. Ve: \"Allâh bize yeter, O, ne güzel vekildir.\" dediler."},{"n":174,"t":"Bundan dolayı Allah’tan bir ni’met ve bollukla geri döndüler, kendilerine hiçbir kötülük dokunmadı. Ve Allâh’ın rızâsına uydular. Allâh büyük lutuf sâhibidir."},{"n":175,"t":"O şeytân sizi kendi dostlarından korkutuyor, eğer inanmış iseniz, onlardan korkmayın, benden korkun!"},{"n":176,"t":"İnkâra koşanlar seni üzmesin, onlar Allah’a hiçbir zarar veremezler. Allâh onlara âhirette hiçbir nasip koymamak istiyor. Onlar için büyük bir azâb vardır."},{"n":177,"t":"İman karşılığında inkârı satın alanlar, Allah’a hiçbir zarar vermezler. Onlar için acı bir azâb vardır."},{"n":178,"t":"İnkâr edenler sanmasınlar ki, kendilerine süre vermemiz, kendileri için hayırlıdır. Biz onlara süre veriyoruz ki günâhı artırsınlar. Onlar için alçaltıcı bir azâb vardır."},{"n":179,"t":"Allâh mü’minleri, (şu) üzerinde bulunduğunuz halde bırakacak değildir, temizi pisten ayıracaktır. Ve Allâh sizi gaybe vakıf kılacak değildir. Fakat Allâh, elçilerinden dilediğini seçer (onu gaybe vakıf kılar). O halde Allah’a ve elçilerine inanın; eğer inanır ve (günâhlardan) korunursanız sizin için büyük mükâfât vardır."},{"n":180,"t":"Allâh’ın kereminden kendilerine verdiğine cimrilik edenler, onu kendileri için hayırlı sanmasınlar. Hayır, o, kendileri için şerlidir. Cimrilik ettikleri şeyler, kıyâmet günü boyunlarına dolandırılacaktır. Göklerin ve yerin mirâsı Allâh’ındır (bütün mülk O’na aittir ve O’na kalacaktır). Allâh yaptıklarınızı haber alandır."},{"n":181,"t":"Allâh: \"Allâh fakirdir, biz zenginiz.\" diyenlerin sözünü işitti. Onların dediklerini ve haksız yere peygamberleri öldürmelerini yazacağız ve: \"Yangın azâbını tadın!\" diyeceğiz."},{"n":182,"t":"\"Bu, sizin ellerinizin yapıp öne sürdürdüğünün karşılığıdır.\" Allâh, kullara asla zulmedici değildir."},{"n":183,"t":"Onlar: \"Allâh bize, and verdi ki, bize ateşin yiyeceği bir kurban getirmedikçe hiçbir elçiye inanmayalım.\" dediler. De ki: \"Size benden önce açık deliller ve bu dediğinizi de getiren elçiler gelmişti. Eğer doğru idiyseniz niçin onları öldürdünüz?\""},{"n":184,"t":"Eğer seni yalanladılarsa, senden önce açık deliller, hikmetli sahifeler ve aydınlatıcı Kitabı getiren peygamberler de yalanlanmıştı."},{"n":185,"t":"Her can ölümü tadacaktır. Kıyâmet günü ecirleriniz size eksiksiz verilecektir. Kim ki hemen ateşin elinden çekilip kurtarılır da cennete sokulursa, işte o, kurtuluşa ermiştir. Dünyâ hayâtı, aldatıcı zevkten başka bir şey değildir."},{"n":186,"t":"Mallarınız ve canlarınız hususunda deneneceksiniz; sizden önce kendilerine Kitap verilenlerden ve ortak koşanlardan çok incitici (sözler) duyacaksınız. Ama sabreder, korunursanız; işte bunlar, yapmağa değer işlerdendir."},{"n":187,"t":"Allâh, kendilerine Kitap verilenlerden: \"Onu mutlaka insanlara açıklayacaksınız, gizlemeyeceksiniz!\" diye söz almıştı. Fakat onlar, verdikleri sözü sırtlarının ardına attılar ve karşılığında birkaç para aldılar. Ne kötü şey satın alıyorlar."},{"n":188,"t":"O ettiklerine sevinen, yapmadıkları şeylerle övülmeyi sevenlerin, azâbdan kurtulacaklarını sanma. Onlar için acı bir azâb vardır."},{"n":189,"t":"Göklerin ve yerin mülkü Allâh’ındır. Allâh herşeye kâdirdir."},{"n":190,"t":"Göklerin ve yerin yaratılışında, gecenin ve gündüzün gidip gelişinde elbette sağduyu sâhipleri için ibretler vardır."},{"n":191,"t":"Onlar ayakta, oturarak ve yanları üzerine yatarken Allâh’ı anarlar, göklerin ve yerin yaratılışı üzerinde düşünürler: \"Rabbimiz (derler), bunu boş yere yaratmadın, sen yücesin, bizi ateş azâbından koru!\""},{"n":192,"t":"\"Rabbimiz, sen birini ateşe soktun mu, onu perişan etmişsindir. zâlimlerin yardımcıları yoktur.\""},{"n":193,"t":"\"Rabbimiz, biz, ’Rabbinize inanın’ diye imânâ çağıran bir davetçi işittik, hemen inandık. Rabbimiz, bizim günâhlarımızı bağışla, kötülüklerimizi ört, canımızı iyilerle beraber al (bizi ma’nada onlarla beraber eyle)!\""},{"n":194,"t":"\"Rabbimiz bize, elçilerine va’dettiğini ver, kıyâmet günü bizi rezil, perişan etme. Zira sen verdiğin sözden caymazsın!\""},{"n":195,"t":"Rableri onlara karşılık verdi: \"Ben, sizden erkek kadın, hiçbir çalışanın işini zayi etmeyeceğim. Hep birbirinizdensiniz. Göç edenler, yurtlarından çıkarılanlar, yolumda işkence edilenler, vuruşanlar ve öldürülenler... Elbette onların kötülüklerini örteceğim ve onları, altlarından ırmaklar akan cennetlere sokacağım. (Yaptıklarına), Allâh katından bir karşılık olarak (onlara bu ni’metleri vereceğim). Karşılıkların en güzeli Allâh katındadır.\""},{"n":196,"t":"İnkâr edenlerin, öyle şehirlerde gezip dolaşması seni aldatmasın."},{"n":197,"t":"Bu, az bir geçimdir. Sonra gidecekleri yer, cehennemdir. Ne kötü bir yataktır orası!"},{"n":198,"t":"Fakat Rablerinden korkanlar için, altlarından ırmaklar akan cennetler var. Orada ebedi kalacaklar, Allâh tarafından ağırlanacaklardır. İyiler için Allâh yanında bulunan ödüller ise (dünyâ varlığından) daha hayırlıdır."},{"n":199,"t":"Kitap ehlinden öyleleri var ki, Allah’a inanırlar, size indirilene ve kendilerine indirilene inanırlar; Allah’a karşı saygılıdırlar; Allâh’ın âyetlerini birkaç paraya satmazlar. Onların da Rableri katında ödülleri vardır! Şüphesiz Allâh, hesabı çabuk görendir."},{"n":200,"t":"Ey inananlar, sabredin, direnin. Savaşa hazırlıklı, uyanık bulunun ve Allah’tan korkun ki, başarıya eresiniz."}],[{"n":1,"t":"Ey insanlar, sizi bir tek nefisten (nefes alan candan) yaratan ve ondan eşini yaratıp ikisinden birçok erkekler ve kadınlar üreten Rabbinizden korkun; adına birbirinizden dilekte bulunduğunuz Allah’tan ve akrabâlık(bağlarını kırmak)tan sakının. Şüphesiz Allâh, sizin üzerinizde gözetleyicidir."},{"n":2,"t":"Öksüzlere mallarını verin, temizi pis olanla değiştirmeyin, onların mallarını sizin mallarınıza katarak (helâl, temiz malınızı kirletip) yemeyin; çünkü bu, büyük bir günâhtır."},{"n":3,"t":"Şâyet öksüz(kızlarla evlendiğiniz takdirde on)lar hakkında adâleti yerine getiremeyeceğinizden korkarsanız, size helâl olan kadınlardan ikişer, üçer, dörder alın. O(kadı)nlar arasında da adâlet yapamayacağınızdan korkarsanız bir tane alın; yahut ellerinizin altında bulunan(câriye)lerle yetinin. Cevr (ve haksızlık) etmemeniz için en uygun olan budur."},{"n":4,"t":"Kadınlara mehirlerini bir hak olarak (gönül hoşluğuyla) verin; eğer kendi istekleriyle o mehrin bir kısmını size bağışlarlarsa, onu da âfiyetle yeyin."},{"n":5,"t":"Allâh’ın, sizin için geçim kaynağı yaptığı mallarınızı aklı ermezlere vermeyin; o mallarla onları besleyin, giydirin ve onlara güzel söz söyleyin."},{"n":6,"t":"Nikâh çağına varıncaya kadar öksüzleri deneyin, eğer onlarda bir olgunluk görürseniz, mallarını kendilerine verin. Büyüsünler diye alıkoyup israf ile tez elden onların mallarını yemeğe kalkmayın. Zengin olan, çekinsin; yoksul olan da (malın muhafazası için gösterdiği çabaya ve ihtiyacına) uygun şekilde yesin. Onlara mallarını geri verdiğiniz zaman da yanlarında şâhid bulundurun. Hesapçı olarak da Allâh yeter (O, her yaptığınızı hesâbetmektedir)."},{"n":7,"t":"Ana babanın ve akrabânın geriye bıraktıklarından erkeklere pay vardır; ana babanın ve akrabânın geriye bıraktıklarından kadınlara da pay vardır. Gerek azından gerek çoğundan (hem erkeğe, hem de kadına) bir hisse ayrılmıştır."},{"n":8,"t":"(Mirâs düşmeyen) Akrabâlar, öksüzler, yoksullar da (mirâs) taksim(in)de hazır bulunursa bir şeyler vererek onları da ondan rızıklandırın (gönüllerini hoş edin) ve onlara güzel söz söyleyin."},{"n":9,"t":"Kendileri, geriye zayıf çocuklar bıraktıkları takdirde onların durumundan endişe edecek olanlar, (öksüzlerin hakkına dokunmaktan) çekinsinler. Allah’tan korksunlar ve doğru söz söylesinler."},{"n":10,"t":"Zulüm ile öksüzlerin mallarını yiyenler, karınlarına sadece ateş koymaktadırlar ve çılgın bir ateşe gireceklerdir."},{"n":11,"t":"Allâh size, çocuklarınız(ın alacağı mirâs) hakkında, erkeğe kadının payının iki katını tavsiye eder. (Çocuklar) ikiden fazla kadın iseler, (ölenin geriye) bıraktığının üçte ikisi onlarındır. Eğer (çocuk) yalnız bir kadınsa (mirâsın) yarısı onundur. Ölenin çocuğu varsa, bıraktığı mirâsta ana babasından her birinin altıda bir hissesi vardır. Eğer çocuğu yok da ana babası ona varis oluyorsa, anasına üçte bir düşer. Eğer kardeşleri varsa, anasının payı altıda birdir. (Bu hükümler, ölenin) Yapacağı vasiyyetten, ya da borcundan sonradır. Babalarınız ve oğullarınızdan, hangisinin fayda bakımından size daha yakın olduğunu bilmezsiniz. Bunlar, Allâh’ın koyduğu haklardır. Şüphesiz Allâh bilendir, hikmet sâhibidir."},{"n":12,"t":"Eğer çocukları yoksa, eşlerinizin yapacakları vasiyyetten ve borçtan sonra bıraktıkları mirâsın yarısı sizindir. Çocukları varsa, bıraktıklarının dörtte biri sizindir. Sizin de çocuğunuz yoksa, yapacağınız vasiyyet ve borçtan sonra bıraktığınızın dörtte biri, onlarındır; çocuğunuz varsa bıraktığınızın sekizde biri onlarındır. Eğer mirâs bırakan erkek veya kadının evlâdı ve ana babası olmayıp bir erkek veya bir kızkardeşi varsa, her birine altıda bir düşer. Bundan fazla iseler, üçte bire ortaktırlar. (Bu taksim) Zarar verici olmayan vasiyyet ve borçtan sonra (uygulanır). Bunlar, Allah’tan (size) vasiyyettir. Allâh bilendir, halimdir."},{"n":13,"t":"Bunlar Allâh’ın sınırlarıdır. Kim Allah’a ve Elçisine itâ’at ederse Allâh onu, altlarından ırmaklar akan, içinde sürekli kalacakları cennetlere sokar. İşte büyük başarı budur."},{"n":14,"t":"Kim de Allah’a ve Elçisi’ne karşı gelir, O’nun sınırlarını aşarsa, Allâh onu, sürekli kalacağı ateşe sokar. Onun için alçaltıcı bir azâb vardır."},{"n":15,"t":"Kadınlarınızdan fuhuş yapanlara karşı içinizden dört şâhid getirin; eğer onlar şâhidlik ederlerse, o kadınları ölüm alıncaya, ya da Allâh onların yararına bir yol gösterinceye kadar evlerde tutun (dışarı çıkarmayın)."},{"n":16,"t":"İçinizden iki kişi, fuhuş yaparsa, onlara eziyet edin; eğer tevbe eder, uslanırlarsa artık onlardan vazgeçin. Çünkü Allâh, tevbeleri çok kabul edendir, çok esirgeyendir."},{"n":17,"t":"Allah’a göre, şu kimselerin tevbesi makbuldür ki, câhillikle bir kötülük yapıp hemen ardından dönerler. İşte Allâh onların tevbesini kabul eder. Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":18,"t":"Yoksa kötülükler yapıp yapıp da nihâyet kendilerine ölüm gelip çatınca: \"Ben şimdi tevbe ettim\" diyenlere ve kâfir olarak ölenlere tevbe (af) yoktur. Onlar için acı bir azâb hazırlamışızdır!"},{"n":19,"t":"Ey inananlar, kadınları mirâs yoluyla zorla almanız size helâl değildir. Onlara verdiklerinizin bir kısmını alıp götürmek için onları sıkıştırmayın. Şâyet açık bir edepsizlik yaparlarsa başka. Onlarla iyi geçinin. Eğer onlardan hoşlanmazsanız, bilin ki sizin hoşlanmadığınız bir şeye Allâh çok hayır koymuş olabilir."},{"n":20,"t":"Bir eşin yerine başka bir eş almak istediğiniz takdirde, onlardan birine (evvelki eşinize) kantarlarca mal vermiş olsanız dahi verdiğinizden hiçbir şeyi geri almayın. İftira ederek ve açık günâha girerek verdiğinizi alacak mısınız?"},{"n":21,"t":"Nasıl alırsınız ki, birbirinize geçmiş (içli dışlı olmuş) idiniz ve onlar, sizden sağlam te’minât almışlardı."},{"n":22,"t":"Geçmişte olanlar hariç, artık babalarınızın evlendiği kadınlarla evlenmeyin. Çünkü bu, edepsizliktir, (Allâh’ın) hışm(ı)dır ve iğrenç bir yoldur."},{"n":23,"t":"Size (şunlarla evlenmeniz) harâm kılındı: Analarınız, kızlarınız, kızkardeşleriniz, halalarınız, teyzeleriniz, kardeş kızları, kızkardeş kızları, sizi emziren analarınız, süt bacılarınız, karılarınızın anaları, birleştiğiniz karılarınızdan olup evlerinizde bulunan üvey kızlarınız -eğer onlarla henüz birleşmemişseniz, (kızlarını almaktan ötürü) üzerinize bir günâh yoktur-kendi sulbünüzden gelen oğullarınızın karıları ve iki kızkardeşi bir arada almanız. Ancak geçmişte olanlar hariç. Şüphesiz Allâh, çok bağışlayan, çok esirgeyendir."},{"n":24,"t":"(Savaşta tutsak olarak) ellerinize geçen(câriye)ler dışında, evli kadınlar(la evlenmeniz) de harâmdır. (İşte bunlar) size Allâh’ın yazdığı yasaklardır. Bunlardan ötesini, iffetli yaşamak, zinâ etmemek şartıyle mallarınızla istemeniz (evlenmeniz), size helâl kılındı. O halde onlardan yararlanmanıza karşılık, kesilen ücretlerini bir hak olarak onlara verin. Hakkın kesiminden sonra karşılıklı anlaşma(k sûretiyle kesilenden az veya çok vermeniz)de üzerinize bir günâh yoktur. Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":25,"t":"İçinizden inanmış hür kadınlarla evlenmeğe gücü yetmeyen kimse, elleriniz altında bulunan inanmış genç kızlarınız(olan câriyeleriniz)den alsın. Allâh sizin imanınızı daha iyi bilir. Hepiniz birbirinizdensiniz (hepiniz aynı kökten gelmekte, aynı toplumun bireylerisiniz; insanlık bakımından aranızda bir fark yoktur). Öyle ise iffetli yaşamaları, zinâ etmemeleri ve gizli dost da tutmamaları şartıyle, sâhiplerinin izniyle onlarla evlenin, ücretlerini (mehirlerini) de güzelce verin. Evlendikten sonra bir fuhuş yaparlarsa onlara, hür kadınlara yapılan işkencenin yarısı uygulanır. Bu (câriye ile evlenme), içinizden sakıntıya düşmekten korkanlar içindir. Sabretmeniz ise sizin için daha iyidir. Allâh bağışlayandır, esirgeyendir."},{"n":26,"t":"Allâh size (helâl ve harâm olanı) açıklamak ve sizi, sizden öncekilerin yasalarına iletmek ve günâhlarınızı bağışlamak istiyor. Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":27,"t":"Allâh, sizin tevbenizi kabul etmek istiyor; şehvetlerine uyanlar ise sizin büyük bir sapıklığa düşmenizi istiyorlar."},{"n":28,"t":"Allâh sizden (ağır teklifleri) hafifletmek istiyor. Çünkü insan zayıf yaratılmıştır."},{"n":29,"t":"Ey inananlar, mallarınızı aranızda bâtılla (doğru olmayan yollarla, haksız yere) yemeyin. Kendi rızânızla yaptığınız ticaret olursa başka. Canlarınızı da öldürmeyin. Doğrusu Allâh, size karşı çok merhametlidir."},{"n":30,"t":"Kim düşmanlık ve zulüm ile bunu yaparsa (bilsin ki) onu cehenneme sokacağız. Bu, Allah’a kolaydır."},{"n":31,"t":"Eğer size yasaklanan büyük günâhlardan kaçınırsanz, sizin küçük günâhlarınızı örteriz ve sizi güzel bir yere sokarız."},{"n":32,"t":"Allâh’ın sizi birbirinizden üstün kıldığı şeylere göz dikmeyin. Erkeklere de kazandıklarından bir pay var, kadınlara da kazandıklarından bir pay var. Allah’tan, O’nun lutfunu isteyin. Kuşkusuz Allâh, her şeyi bilendir."},{"n":33,"t":"Ana babanın ve akrabânın bıraktıklarından her birine vârisler kıldık. yeminlerinizin bağladığı kimselere de hisselerini verin. Allâh herşeyi görmektedir."},{"n":34,"t":"Allâh, insanları birbirinden üstün kıldığı ve mallarından harca(yıp kadınların geçmini sağla)dıkları için erkekler, kadınlar üzerinde yöneticidirler. Bundan dolayı iyi kadınlar itâ’atkâr olup, Allâh’ın kendilerini korumasına karşılık (Allâh’ın verdiği başarı ile) gizliyi korurlar (kocalarına aslâ ihânet etmezler). Hırçınlık, etmelerinden korktuğunuz kadınlara öğüt verin, yataklarda onlara sokulmayın, onları dövün. Eğer size itâ’at ederlerse artık onların aleyhine başka bir yol aramayın. Çünkü Allâh yücedir, büyüktür."},{"n":35,"t":"Eğer (karı-kocanın) aralarının açılmasından endişe duyarsanız, erkeğin âilesinden bir hakem ve kadının âilesinden bir hakem gönderin. Bunlar uzlaştırmak isterlerse, Allâh onların arasını bulur. Çünkü Allâh (herşeyi) bilendir, haber alandır."},{"n":36,"t":"Allah’a kulluk edin, O’na hiçbir şeyi ortak koşmayın, ana babaya, akrabâya, öksüzlere, yoksullara, yakın komşuya, uzak komşuya, yan(ınız)daki arkadaşa, yolcuya, ellerinizin altında bulunanlara iyilik edin. Allâh, kurumlu, böbürlenen insanları sevmez."},{"n":37,"t":"Bunlar öyle insanlardır ki, cimrilik ederler ve insanlara da cimriliği emrederler, Allâh’ın bol hazinesinden kendilerine verdiğini gizlerler. (Biz de) o nankörlere alçaltıcı bir azâb hazırlamışızdır."},{"n":38,"t":"Bunlar mallarını insanlara gösteriş için verirler, Allah’a, ve âhiret gününe inanmazlar. Kimin arkadaşı şeytân ise, o(nun) ne kötü bir arkadaş(ı var)dır!"},{"n":39,"t":"Onlara ne olurdu sanki Allah’a ve âhiret gününe inansalardı ve Allâh’ın kendilerine verdiği rızıktan Allâh yolunda harcasalardı! Allâh onları biliyordu."},{"n":40,"t":"Allâh zerre kadar haksızlık etmez, zerre miktarı bir iyilik olsa onu kat kat yapar ve kendi katından da büyük bir mükâfât verir."},{"n":41,"t":"Her ümmetten (inanç ve davranışlarının doğru olup olmadığına tanıklık edecek) bir şâhid, seni de bunlara şâhid getirdiğimiz zaman (halleri) nice olur?"},{"n":42,"t":"Nankörlük edip, (Allâh’ın) Elçi(sin)e karşı gelenler, o gün yerin dibine geçirilmeyi isterler ve Allah’tan hiçbir söz gizleyemezler."},{"n":43,"t":"Ey inananlar, sarhoşken namaza yaklaşmayın ki ne dediğinizi bilesiniz. Yoldan geçici olmanız dışında, cünüp iken de yıkanıncaya kadar (namaza yaklaşmayın). Eğer hasta, yahut yolculukta iseniz, yahut biriniz tuvaletten gelmişse, yahut da kadınlara dokunmuşsanız (bu durumlarda) su bulamadığınız takdirde temiz toprağa teyemmüm edin: (Toprağı) yüzlerinize ve ellerinize sürün. Şüphesiz Allâh, çok affeden, çok bağışlayandır."},{"n":44,"t":"Şu kendilerine Kitaptan bir pay verilenleri görmedin mi? (Baksana onlar,) sapıklığı satın alıyorlar, istiyorlar ki, siz de yolu sapıtasınız."},{"n":45,"t":"Allâh sizin düşmanlarınızı daha iyi bilir. Dost olarak Allâh yeter, yardımcı olarak da Allâh yeter."},{"n":46,"t":"Yahûdilerden öyleleri var ki, kelimeleri yerlerinden kaydırıyorlar. Dillerini eğip bükerek ve dini taşlayarak: \"İşittik ve isyân ettik\", \"dinle, dinlemez olası\" ve: \"râ’inâ\" diyorlar. Eğer onlar: \"İşittik ve itâ’at ettik\", \"Dinle ve bize bak!\" deselerdi, elbette kendileri için daha iyi olurdu. Fakat Allâh, inkârlarından dolayı onları la’netlemiştir, pek az inanırlar."},{"n":47,"t":"Ey Kitap verilenler, biz bazı yüzleri, silip arkalarına döndürmeden, ya da Cumartesi adamlarını la’netlediğimiz gibi onları da la’netlemeden önce, yanınızdakini doğrulayıcı olarak indirdiğimiz(Kur’ân)a inanın. Allâh’ın buyruğu yapılır."},{"n":48,"t":"Allâh, kendisine ortak koşulmasını bağışlamaz, bundan başkasını dilediğine bağışlar. Allah’a ortak koşan da gerçekten büyük bir günâh işlemiştir."},{"n":49,"t":"Şu kendilerini övüp yüceltenleri görmedin mi? Hayır, ancak Allâh dilediğini yüceltir, onlara kıl kadar zulmedilmez."},{"n":50,"t":"Bak nasıl Allah’a yalan uyduruyorlar. Apaçık bir günâh olarak bu (onlara) yeter."},{"n":51,"t":"Kendilerine Kitaptan bir pay verilenleri görmedin mi? (Baksana onlar) cibt ve tâğût’a inanıyorlar ve inkâr edenler için: \"Bunlar, inananlardan daha doğru yoldadır\" diyorlar."},{"n":52,"t":"İşte onlar, Allâh’ın la’netlediği insanlardır. Allâh, kimi la’netlerse artık onun için hiçbir yardımcı bulamazsın."},{"n":53,"t":"Yoksa onların mülkten bir payı mı var? Öyle olsaydı insanlara bir çekirdek zerresi bile vermezlerdi."},{"n":54,"t":"Yoksa Allâh’ın, lutfundan insanlara verdiği (vahiyler) yüzünden onları kıskanıyorlar mı? Oysa biz İbrâhim soyuna da Kitabı ve hikmeti vermiş ve onlara büyük bir mülk vermiştik."},{"n":55,"t":"Onlardan kimi O(Hak Kitabı)na inandı, kimi de ondan yüz çevirdi. Öylesine de çılgın alevli cehennem yetti."},{"n":56,"t":"O âyetlerimizi inkâr edenleri yakında bir ateşe sokacağız, derileri piştikçe azâbı tadsınlar diye onlara başka deriler vereceğiz! Şüphesiz Allâh dâimâ üstündür, hüküm ve hikmet sâhibidir."},{"n":57,"t":"İnanıp iyi işler yapanları da altlarından ırmaklar akan cennetlere sokacağız. Orada sürekli kalacaklardır. Orada kendilerine tertemiz eşler de vardır ve onları (hiç güneş sızmayan) eşsiz bir gölgeye sokacağız."},{"n":58,"t":"Allâh, size emânetleri ehline vermenizi, insanlar arasında hükmettiğiniz zaman adâletle hükmetmenizi emreder. Allâh size böylece ne güzel öğüt veriyor. Doğrusu, Allâh işiten, görendir."},{"n":59,"t":"Ey inananlar, Allah’a itâ’at edin, Elçiye ve sizden olan buyruk sâhibine itâ’at edin. Eğer herhangi bir şeyde anlaşmazlığa düşerseniz; -Allah’a ve âhiret gününe inanıyorsanız -onu Allah’a ve Elçiye götürün. Bu, daha iyidir ve sonuç bakımından da daha güzeldir."},{"n":60,"t":"Şunları görmedin mi, kendilerinin, sana indirilene ve senden önce indirilene inandıklarını sanıyorlar da hakem olarak tâğûta (o azgın şeytâna) başvurmak istiyorlar! Oysa kendilerine onu inkâr etmeleri emredilmişti. Şeytân da onları iyice saptırmak istiyor."},{"n":61,"t":"Kendilerine: \"Allâh’ın indirdiğine ve Elçiye gelin!\" denince, o ikiyüzlülerin, senden büsbütün uzaklaştıklarını görürsün."},{"n":62,"t":"Ya nasıl, elleriyle yaptıkları (kötülükler) yüzünden başlarına bir felâket gelince, hemen sana gelirler: \"Biz sadece iyilik etmek ve uzlaştırmak istedik.\" diye Allah’a yemin ederler?"},{"n":63,"t":"Allâh onların kalblerinde olanı bilir. Onlara aldırma, onlara öğüt ver ve onların içlerine işleyecek güzel söz söyle!"},{"n":64,"t":"Biz hiçbir elçiyi, Allâh’ın izniyle itâ’at edilmekten başka bir amaçla göndermedik. Eğer onlar, kendilerine zulmettikleri zaman sana gelseler, Allah’tan, günâhlarını bağışlamasını isteseler ve Elçi de onların bağışlanmasını dileseydi, elbette Allâh’ı affedici, merhametli bulurlardı."},{"n":65,"t":"Hayır, Rabbin hakkı için onlar aralarında çıkan çekişmeli işlerde seni hakem yapıp, sonra da senin verdiğin hükme, içlerinde bir burukluk duymadan tam anlamıyle teslim olmadıkça inanmış olmazlar."},{"n":66,"t":"Eğer onlara: \"Kendinizi öldürün, ya da yurtlarınızdan çıkın!\" diye yazmış olsaydık, içlerinden pek azı hariç, bunu yapmazlardı. Ama kendilerine öğütleneni yapsalardı, elbette kendileri için daha iyi ve daha sağlam olurdu."},{"n":67,"t":"O zaman kendilerine katımızdan büyük mükâfât verirdik."},{"n":68,"t":"Ve onları doğru bir yola iletirdik."},{"n":69,"t":"Kim Allah’a ve Elçi’ye itâ’at ederse işte onlar, Allâh’ın ni’met verdiği peygamberler, sıddiklar, şehidler ve sâlihlerle beraberdir. Onlar da ne güzel arkadaştır!"},{"n":70,"t":"Bu ni’met, Allah’tandır. Bilen olarak Allâh yeter."},{"n":71,"t":"Ey inananlar, (uyanık bulunup) korunma(tedbirleri)nizi alın, bölük bölük, ya da hep birlikte savaşa gidin."},{"n":72,"t":"İçinizden bir kısmı var ki, pek ağır davranır. Eğer size bir felâket erişirse: \"Allâh bana lutfetti de onlarla beraber bulunmadım.\" der."},{"n":73,"t":"Eğer Allah’tan size bir ni’met erişirse, sizinle kendisi arasında hiç sevgi yokmuş gibi: \"Keşke ben de onlarla beraber olsaydım da büyük bir başarı kazansaydım!\" der."},{"n":74,"t":"Dünyâ hayâtını âhiret hayâtı karşılığında satanlar, Allâh yolunda savaşsınlar. Kim Allâh yolunda savaşır da öldürülür veya gâlib gelirse, biz ona yakında büyük bir mükâfât vereceğiz."},{"n":75,"t":"Size ne oldu ki Allâh yolunda ve \"Rabbimiz bizi şu, halkı zâlim kentten çıkar, bize katından bir koruyucu ver, bize katından bir yardımcı ver!\" diyen zayıf erkek, kadın ve çocuklar uğrunda savaşmıyorsunuz?"},{"n":76,"t":"İnananlar Allâh yolunda savaşırlar, inkâr edenler de tâğût yolunda savaşırlar. O halde şeytânın dostlarıyla savaşın, çünkü şeytânın hilesi zayıftır."},{"n":77,"t":"Kendilerine: \"Ellerinizi (savaştan) çekin, namazı kılın, zekâtı verin!\" denilenleri görmedin mi? Kendilerine savaş yazılınca hemen içlerinden bir grup, insanlardan, Allah’tan korkar gibi hattâ daha fazla korkmaya başladılar: \"Rabbimiz, niçin bize savaş yazdın? Bizi yakın bir süreye kadar ertelesen (savaş emrini bir süre geciktirsen) olmaz mıydı?\" dediler. De ki: \"dünyâ geçimi azdır, korunan için âhiret daha iyidir. Size kıl kadar haksızlık edilmez.\""},{"n":78,"t":"Nerede olsanız, sağlam kaleler içinde de bulunsanız yine ölüm sizi bulur. Onlara bir iyilik erişirse: \"Bu, Allâh tarafındandır\" derler. Onlara bir kötülük erişirse: \"Bu, senin yüzündendir\" derler. De ki: \"Hepsi Allâh tarafındandır\". Bu topluma ne oluyor ki hemen hiç söz anlamıyorlar?"},{"n":79,"t":"Sana gelen her iyilik Allah’tandır, sana gelen her kötülük de kendi(günâhın yüzü)ndendir. Seni insanlara elçi gönderdik. (Buna) şâhid olarak Allâh yeter."},{"n":80,"t":"Kim Elçi’ye itâ’at ederse Allah’a itâ’at etmiş olur. Kim de yüz çevirirse (bil ki), biz seni onların üzerine bekçi göndermedik."},{"n":81,"t":"\"Peki\", derler, ama yanından çıkınca içlerinden birtakımı senin söylemiş olduğunun tersini kurar. Allâh, onların geceleyin ne düşünüp kurduklarını yazmaktadır. Sen onlara aldırma, Allah’a dayan. (Sana) vekil olarak Allâh yeter."},{"n":82,"t":"Kur’ân’ı düşünmüyorlar mı? Eğer Allah’tan başkası tarafından (indirilmiş) olsaydı, onda birbirini tutmaz çok şey bulurlardı."},{"n":83,"t":"Onlara güven veya korkuya dair bir haber gelse onu yayarlar. Halbuki onu Elçi’ye ve aralarında buyruk sâhiplerine götürselerdi, işin içyüzünü araştırıp çıkaranlar, onun ne olduğunu (haberin taşıdığı anlamı) bilirlerdi. Eğer size Allâh’ın lutfu ve rahmeti olmasaydı, birçok işinizde şeytâna uyardınız."},{"n":84,"t":"(Ey Muhammed), Allâh yolunda savaş; sen yalnız kendinden sorumlusun! İnananları da (savaşa) teşvik et. Umulur ki Allâh, kâfirlerin gücünü kırar. Allâh’ın baskını daha güçlü, cezâsı daha çetindir."},{"n":85,"t":"Kim güzel bir (işe) destek olursa, onun da o işten bir payı olur. Kim kötü bir (işe) destek olursa, onun da o işten bir payı olur. Allâh her şeyi gözetip karşılığını verendir."},{"n":86,"t":"Bir selâm ile selâmlandığınız zaman siz de ondan daha güzeliyle selâm verin; yahut verilen selâmı aynen iâde edin. Şüphesiz Allâh, her şeyi hesaplayandır."},{"n":87,"t":"Allâh -ki O’ndan başka tanrı yoktur- sizi, vukuunda asla şüphe olmayan kıyâmet (duruşma) gününde bir araya toplayacaktır. Allah’tan daha doğru sözlü kim olabilir?"},{"n":88,"t":"Size ne oldu ki, münafıklar hakkında iki gruba ayrıldınız? Oysa yaptıkları işlerden dolayı Allâh onları baş aşağı etmiştir. Allâh’ın saptırdığını doğru yola iletmek mi istiyorsunuz? Allâh birini saptırırsa artık onun için bir yol bulamazsınız!"},{"n":89,"t":"Sizin de kendileri gibi inkâr etmenizi istediler ki, onlarla bir olasınız. O halde onlar Allâh yolunda göç edinceye kadar onlardan dostlar edinmeyin. Eğer yüz çevirirlerse onları yakalayın, nerede bulursanız öldürün ve onlardan ne dost, ne de yardımcı tutmayın!"},{"n":90,"t":"Ancak sizinle kendileri arasında andlaşma bulunan bir topluma sığınanlar, yahut ne sizinle ne de kendi toplumlarıyle savaşmak(istemedikleri)nden yürekleri sıkılarak size gelenler hariç. Allâh dileseydi, onları sizin üstünüze salardı, sizinle savaşırlardı. O halde onlar, sizden uzak dururlar, sizinle savaşmazlar ve sizinle barış içinde yaşamak isterlerse, Allâh size, onlara saldırmak için bir yol vermemiştir."},{"n":91,"t":"Başka birtakım insanlar da bulacaksınız ki, hem sizden, hem de kendi toplumlarından emin olmak isterler. Ama ne zaman fitneye götürülseler, fitnenin içine başaşağı atılırlar. Eğer onlar sizden uzak durmazlar, sizinle barış içinde yaşamak istemezler, ellerini (saldırıdan) çekmezlerse onları yakalayın ve nerede bulursanız öldürün! İşte öylelerine karşı size açık bir yetki verdik."},{"n":92,"t":"Yanlışlık dışında bir mü’min, bir mü’mini öldüremez: Yanlışlıkla bir mü’mini öldüren kimsenin, mü’min bir köle âzâdetmesi ve ölenin âilesine de bir diyet vermesi gerekir. Eğer (ölenin âilesi), bağışlar(diyetten vazgeçer)lerse başka. (Öldürülen) mü’min, düşmanınız olan bir topluluktan ise mü’min bir köle âzâdetmek gerekir. Ve eğer sizinle kendileri arasında andlaşma bulunan bir topluluktan ise âilesine verilecek bir diyet ve mü’min bir köle âzâdetmek lâzımdır. Bunları bulamayan kimsenin, Allâh tarafından tevbesinin kabulü için iki ay ardı ardına oruç tutması gerekir. Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":93,"t":"Her kim bir mü’mini kasden öldürürse -onun cezâsı-, içinde sürekli kalacağı cehennemdir. Allâh ona gazabetmiş, la’net etmiş ve onun için büyük bir azâb hazırlamıştır!"},{"n":94,"t":"Ey inananlar, Allâh yolunda savaşa çıktığınız zaman iyi anlayın, dinleyin, size selâm verene, dünyâ hayâtının geçici menfaatini gözeterek: \"Sen mü’min değilsin!\" demeyin. Çünkü Allâh’ın yanında çok ganimetler vardır. Önceden siz de öyle idiniz, Allâh size lutfetti (imânâ geldiniz). O halde iyice anlayın (dinleyin, peşin hüküm vermeyin). Çünkü Allâh yaptıklarınızı haber almaktadır."},{"n":95,"t":"İnananlardan özürsüz olarak yerlerinde oturanlar ile, mallariyle canlariyle Allâh yolunda cihâdedenler bir olmaz. Allâh, mallariyle canlariyle cihâdedenleri, derece bakımından oturanlardan üstün kılmıştır. Gerçi Allâh hepsine de güzellik va’detmiştir ama mücâhidleri oturanlardan çok daha büyük ecirle üstün kılmıştır:"},{"n":96,"t":"Kendi katından yüksek dereceler, bağış ve rahmet. Allâh, bağışlayandır, esirgeyendir."},{"n":97,"t":"Nefislerine yazık eden kimselere, canlarını alırken melekler: \"Ne işte idiniz (dininiz için ne yapıyordunuz)?\" dediler. (Bunlar): \"Biz yeryüzünde âciz düşürülmüştük.\" diye cevap verdiler. Melekler dediler ki: \"Allâh’ın yeri geniş değil miydi ki onda göç ed(ip gönlünüzce yaşayabileceğiniz bir yere gid)eydiniz?\" İşte onların durağı cehennemdir, ne kötü bir gidiş yeridir orası!"},{"n":98,"t":"Yalnız hiçbir çareye gücü yetmeyen ve göç için yol bulamayan, gerçekten zayıf erkekler, kadınlar ve çocuklar hariç."},{"n":99,"t":"Çünkü Allâh’ın onları affetmesi umulur. Allâh, çok affeden, çok bağışlayandır."},{"n":100,"t":"Allâh yolunda göç eden kimse, yeryüzünde gidecek çok yer ve bolluk bulur. Kim Allâh ve Elçisi için göç etmek amacıyle evinden çıkar da kendisine ölüm yetişirse, onun mükâfâtı Allah’a düşer. Allâh, bağışlayandır, esirgeyendir."},{"n":101,"t":"Yeryüzünde sefere çıktığınız zaman inkâr edenlerin size bir kötülük yapmalarından korkarsanız, namazı kısaltmanızdan ötürü size bir günâh yoktur. Muhakkak ki kâfirler, sizin açık düşmanınızdır."},{"n":102,"t":"Sen de içlerinde bulunup onlara namazı başlattığın zaman onlardan bir bölük seninle beraber namaza dursun ve silâhlarını da yanlarına alsınlar. (Namazda olanlar), secde edince arkanıza geçsinler; bu kez namaz kılmayan öteki bölük gelsin, seninle beraber namaz kılsınlar, korunma(tedbir)lerini ve silâhlarını da alsınlar. İnkâr edenler istediler ki siz silâhlarınızdan ve eşyanızdan gaflet etseniz de birden üzerinize bir baskın yapsalar. Yağmurdan zahmet çekerseniz, ya da hasta olursanız, silâhlarınızı bırakmanızda size bir günâh yoktur. Ama korunma tedbirinizi alın (uyanık bulunun). Allâh, kâfirlere alçaltıcı bir azâb hazırlamıştır."},{"n":103,"t":"Namazı bitirdiğiniz zaman ayakta, oturarak ve yanlarınız üzerinde (uzanarak) Allâh’ı anın; güvene kavuştunuz mu namazı (tam) kılın. Çünkü namaz, mü’minlere vakitli olarak farz kılınmıştır."},{"n":104,"t":"O topluluğu takip etmekte gevşeklik göstermeyin. Eğer siz acı çekiyorsanız, onlar da sizin acı çektiğiniz gibi acı çekmektedirler. Üstelik siz Allah’tan, onların ummayacakları şeyleri, ummaktasınız. Alah bilendir, hüküm ve hikmet sâhibidir."},{"n":105,"t":"Biz sana Kitabı gerçek ile indirdik ki, insanlar arasında Allâh’ın sana gösterdiği biçimde hüküm veresin; hâinlerin savunucusu olma!"},{"n":106,"t":"Allah’tan mağfiret dile. Kuşkusuz Allâh bağışlayandır, esirgeyendir."},{"n":107,"t":"Kendilerine hâinlik edenleri savunma; zira Allâh, hâinlik yapıp günâh işleyen insanı sevmez!"},{"n":108,"t":"(Günâh işlerken) İnsanlardan gizleniyorlar da Allah’tan gizlenmiyorlar. Oysa geceleyin O’nun istemediği sözü söyle(yip plan kura)rlarken O, onlarla beraberdir. Allâh, onların yaptıkları herşeyi kuşatmıştır (hiçbir şeyi O’ndan gizleyemezler)."},{"n":109,"t":"Haydi siz, dünyâ hayâtında onları savundunuz; ya kıyâmet günü onları Allah’a karşı kim savunacak, ya da kim onlara vekil olacak?"},{"n":110,"t":"Kim bir kötülük yapar, yahut nefsine zulmeder de sonra Allah’tan mağfiret dilerse, Allâh’ı bağışlayıcı ve esirgeyici bulur."},{"n":111,"t":"Kim bir günâh işlerse onu kendi aleyhine kazanır. Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":112,"t":"Kim bir hatâ, ya da günâh işler de sonra onu bir suçsuzun üstüne atarsa, muhakkak ki büyük bir iftirâ ve açık bir günâh yüklenmiş olur."},{"n":113,"t":"Allâh’ın sana lutfu ve acıması olmasaydı, onlardan bir grup, seni saptırmağa yeltenmişti. Onlar sadece kendilerini saptırırlar, sana hiçbir zarar veremezler. Allâh, sana Kitabı ve hikmeti indirdi ve sana bilmediğin şeyleri öğretti. Allâh’ın sana lutfu, cidden büyüktür."},{"n":114,"t":"Onların aralarındaki gizli konuşmaların çoğunda hayır yoktur. Yalnız sadaka, yahut iyilik, ya da insanların arasını düzeltmeyi emreden(in konuşması) hariç. Kim Allâh’ın rızâsını kazanmak amacıyle bunu yaparsa, yakında ona büyük bir mükâfât vereceğiz."},{"n":115,"t":"Kim de kendisine doğru yol belli olduktan sonra Elçi’ye karşı gelir ve mü’minlerin yolundan başka bir yola uyarsa, onu döndüğü yola yöneltiriz ve cehenneme sokarız. Ne kötü bir gidiş yeridir orası!"},{"n":116,"t":"Allâh, kendisine ortak koşulmasını bağışlamaz, bundan başka herşeyi dilediğine bağışlar. Allah’a ortak koşan da uzak bir sapıklığa düşmüştür."},{"n":117,"t":"O(Allah’a ortak koşa)nlar, O’nu bırakıp birtakım dişilerden başkasına çağırmıyorlar ve onlar, (hayırsız) âsi şeytândan başkasına yalvarmıyorlar."},{"n":118,"t":"(O şeytân) Ki Allâh ona la’net etti ve o da, \"Elbette senin kullarından belirli bir pay alacağım\" dedi."},{"n":119,"t":"\"Onları mutlaka saptıracağım, mutlaka onları boş kuruntulara sokacağım ve onlara emredeceğim: hayvanların kulaklarını yaracaklar; onlara emredeceğim: Allâh’ın yaratışını değiştirecekler!\" kim Allâh’ın yerine şeytânı dost tutarsa, muhakkak ki açık bir ziyana uğramıştır."},{"n":120,"t":"(Şeytân) Onlara söz verir, umut verir, fakat şeytânın onlara sözü, aldatmadan başka bir şey değildir."},{"n":121,"t":"İşte onların varacağı yer cehennemdir. Asla ondan kaçmak (imkânı) bulamazlar."},{"n":122,"t":"İnanıp iyi işler yapanları da altlarından ırmaklar akan cennetlere sokacağız, orada ebedi kalacaklardır. Bu, Allâh’ın gerçek va’didir. Allah’tan daha doğru sözlü kim olabilir?"},{"n":123,"t":"(İş) Ne sizin kuruntularınızla, ne Kitap ehlinin kuruntularıyla olmaz. Kötülük yapan, onunla cezâlandırılır ve kendisine Allah’tan başka ne dost, ne de yardımcı bulamaz (Allâh’ın vereceği cezâyı hiç kimse ondan savamaz)."},{"n":124,"t":"Erkek veya kadından her kim inanarak güzel işler yaparsa, işte öyle kimseler cennete girerler ve zerre kadar haksızlığa uğratılmazlar."},{"n":125,"t":"Hangi insan, din yönünden, iyilik edici olarak yüzünü Allah’a teslim edip dosdoğru İbrâhim dinine tâbi olandan daha güzel olabilir? Allâh, İbrâhim’i dost edinmişti."},{"n":126,"t":"Göklerde ve yerde olanların hepsi Allâh’ındır. Allâh(ın bilgisi), herşeyi kuşatmıştır."},{"n":127,"t":"Senden, kadınlar hakkında fetvâ istiyorlar. De ki: \"Allâh, size onlar hakkında hükmünü açıklıyor: Kendilerine yazılmış olan(mirâs hakların)ı vermeyip kendileriyle evlenmek istediğiniz öksüz kadınlar, zavallı çocuklar ve öksüzlere karşı adâleti yerine getirmeniz hakkında Kitapta size okunan(âyet)ler (de Allâh’ın hükmünü açıklamaktadır)\". Yapacağınız her hayrı muhakkak ki Allâh bilir."},{"n":128,"t":"Ve eğer bir kadın, kocasının huysuzluğundan, yahut kendisinden yüz çevirmesinden korkarsa, anlaşma ile aralarını düzeltmelerinde ikisine de günâh yoktur. Barış dâimâ iyidir. Zaten nefisler cimriliğe hazır duruma getirilmiştir (insanın mayasında cimrilik vardır). Eğer güzel geçinir, (kötülükten) sakınırsanız, Allâh yaptıklarınızı haber alır (yaptığınız güzel işler boşa gitmez)."},{"n":129,"t":"Ne kadar isteseniz de kadınlar arasında (tam) adâlet yapamazsınız. Öyle ise (birine) tamamen yönelip ötekini askıda (kocasızmış) gibi bırakmayın. Eğer arayı düzeltir, sakınırsanız, Allâh bağışlayandır, esirgeyendir."},{"n":130,"t":"Eğer (eşler) ayrılırlarsa, Allâh bol ni’metiyle onların her birini zengin eder (diğerine muhtâceylemez). Allâh(ın ni’meti) geniştir, (O) hüküm ve hikmet sâhibidir."},{"n":131,"t":"Göklerde ve yerde olanların hepsi Allâh’ındır. Sizden önce Kitap verilenlere de, size de \"Allah’tan korkun!\" diye tavsiye ettik. Eğer inkâr ederseniz, (bilin ki) göklerde ve yerde olanların hepsi Allâh’ındır. Allâh, zengindir, övgüye lâyıktır."},{"n":132,"t":"Göklerde ve yerde olanların hepsi Allâh’ındır. Vekil olarak Allâh yeter."},{"n":133,"t":"Ey insanlar, (Allâh) dilerse sizi götürür ve başkalarını getirir. Allâh, bunu yapabilir."},{"n":134,"t":"Kim dünyâ sevâbını isterse (bilsin ki) dünyâ ve âhiret sevâbı Allâh katındadır. Allâh işitendir, görendir."},{"n":135,"t":"Ey inananlar, adâleti tam yerine getirerek Allâh için şâhidlik edenler olun, kendinizin, ana babanızın ve yakınlarınızın aleyhinde bile olsa, (şâhidlik ettiğiniz kimseler) zengin veya fakir de olsalar (adâletten ayrılmayın). Çünkü Allâh, ikisine de daha yakındır (onları sizden çok kayırır). Öyle ise keyfinize uyarak doğruluktan sapmayın. Eğer (şâhidlik ederken dilinizi) eğip bükerseniz, ya da doğruyu söylemezseniz, muhakkak ki Allâh yaptıklarınızı bilir."},{"n":136,"t":"Ey inananlar, Allah’a, Elçisine, Elçisine indirdiği kitaba ve daha önce indirmiş bulunduğu kitaba inanın. Kim Allâh’ı, meleklerini, kitaplarını, elçilerini ve âhiret gününü inkâr ederse o, uzak bir sapıklığa düşmüştür."},{"n":137,"t":"Onlar ki inandılar, sonra inkâr ettiler; daha sonra yine inandılar, yine inkâr ettiler, sonra inkârları arttı; işte Allâh onları ne bağışlayacak, ne de doğru yola iletecektir."},{"n":138,"t":"Münâfıklara, acı bir azâbın kendilerinin olacağını müjdele!"},{"n":139,"t":"Onlar mü’minleri bırakıp kâfirleri dost tutuyorlar. Onların yanında şeref mi arıyorlar? Bütün şeref, tamamen Allaha aittir."},{"n":140,"t":"(Allâh) Size Kitapta indirmişti ki: Allâh’ın âyetlerinin inkâr edildiğini ve onlarla alay edildiğini işittiğiniz zaman, onlar (bu sözü bırakıp) başka bir söze dalıncaya kadar onlarla beraber oturmayın; yoksa siz de onlar gibi olursunuz. Şüphesiz Allâh, bütün iki yüzlüleri ve kâfirleri cehennemde toplayacaktır."},{"n":141,"t":"Onlar sizi gözetleyip dururlar. Eğer size Allah’tan bir fetih nasibolursa: \"Biz de sizinle beraber değil miydik?\" derler. Ve eğer savaşta kâfirlerin bir payı olur(savaşı düşmanlarınız kazanır)sa, (bu kez onlara): \"Biz size üstünlük sağlayıp, sizi mü’minlerden korumadık mı?\" derler. Artık kıyâmet gününde Allâh, aranızda hükmedecek ve mü’minlere karşı kâfirlere asla yol vermeyecektir."},{"n":142,"t":"İki yüzlüler, Allâh’ı (gûyâ) aldatmağa çalışırlar. Oysa, O, onları aldatır. Namaza kalktıkları zaman da üşene üşene kalkarlar, insanlara gösteriş yaparlar, Allâh’ı pek az anarlar."},{"n":143,"t":"Arada yalpalayıp dururlar. Ne bunlara (bağlanırlar), ne de onlara. Allâh’ın şaşırttığı kimseye bir (çıkar) yol bulamazsın!"},{"n":144,"t":"Ey inananlar, mü’minleri bırakıp kâfirleri dost tutmayın! Allah’a, aleyhinizde olacak açık bir delil vermek mi istiyorsunuz?"},{"n":145,"t":"Doğrusu iki yüzlüler, ateşin en aşağı tabakasındadırlar. Onlar için hiçbir yardımcı bulamazsın."},{"n":146,"t":"Ancak tevbe edenler, uslananlar, Allah’a yapışanlar ve dinlerini sırf Allâh için yapanlar (yalnız O’na tapanlar), işte onlar mü’minlerle beraberdir; Allâh da yakında mü’minlere büyük bir mükâfât verecektir."},{"n":147,"t":"Siz şükreder, inanırsanız Allâh size azâbetmeyi ne yapacak? Allâh şükrün karşılığını veren, (herşeyi) bilendir."},{"n":148,"t":"Allâh, kendisine haksızlık edilen dışında (hiç kimse tarafından) açıkça kötü söz söylenmesini sevmez. Doğrusu Allâh, işitendir, bilendir."},{"n":149,"t":"Bir iyiliği, açığa vurur veya onu gizlerseniz yahut bir kötülüğü affederseniz (bilin ki) Allâh da affedicidir, güçlüdür."},{"n":150,"t":"Onlar ki Allâh’ı ve elçilerini inkâr ederler, Allâh ile elçilerinin arasını ayırmak isterler, \"Kimine inanırız, kimini inkâr ederiz!\" derler; bu ikisinin (inanmakla inkârın) arasında bir yol tutmak isterler."},{"n":151,"t":"İşte onlar gerçek kâfirlerdir. Biz de kâfirlere alçaltıcı bir azâb hazırlamışızdır!"},{"n":152,"t":"Ve onlar ki, Allah’a ve elçilerine inandılar, onlardan hiçbiri arasında ayırım yapmadılar; işte (Allâh), pek yakında onların da mükâfâtlarını verecektir. Allâh, çok bağışlayan, çok esirgeyendir."},{"n":153,"t":"Kitâp ehli, senden, kendilerine gökten bir Kitâp indirmeni istiyorlar. Mûsâ’dan bundan daha büyüğünü istemişler: \"Allâh’ı bize açıkça göster!\" demişlerdi. Haksızlıklarından dolayı derhal onları yıldırım gürültüsü yakalamıştı. Sonra kendilerine açık deliller gelmişken buzağıyı (tanrı) tutmuşlardı. Bundan da vazgeçtik ve Mûsâ’ya açık bir yetki verdik."},{"n":154,"t":"Söz vermeleri için Tûr’u üzerlerine kaldırdık ve onlara: \"Secde ederek kapıdan girin!\" dedik. Ve onlara: \"Cumartesi(yasakları)nı çiğnemeyin!\" dedik. Ve onlardan sağlam bir söz aldık."},{"n":155,"t":"Sözlerini bozmalarından, Allâh’ın âyetlerini inkâr etmelerinden, haksız yere peygamberleri öldürmelerinden ve \"Kalblerimiz kılıflı\" demelerinden ötürü (başlarına belâlar getirdik). Hayır, fakat inkârlarından ötürü Allâh o kalblerin üzerini mühürlemiştir. Artık pek az inanırlar."},{"n":156,"t":"Küfürlerinden ve Meryem’e büyük bir iftirâ atmalarından;"},{"n":157,"t":"\"Biz Allâh’ın elçisi, Meryem oğlu Îsâ Mesih’i öldürdük!\" demelerinden ötürü (belâlara uğradılar). Oysa onu öldürmediler ve asmadılar; fakat (bu iş) kendilerine, benzer gösterildi. Onun hakkında ayrılığa düşenler, ondan yana tam bir kuşku içindedirler. O hususta kesin bilgileri yoktur. Sadece zanna uyuyorlar. Onu yakinen öldürmediler (onu öldürdüklerini kesin biçimde bilemediler)."},{"n":158,"t":"Hayır, Allâh onu kendisine yükseltti. Allâh dâimâ üstündür, hüküm ve hikmet sâhibidir."},{"n":159,"t":"Andolsun, kitâp ehlinden hiç kimse yoktur ki, ölümünden önce ona inanacak olmasın. Kıyâmet günü de O, (Îsâ) onların aleyhine şâhid olacaktır."},{"n":160,"t":"Yahûdilerin yaptıkları zulümlerden, çok kimseyi Allâh yolundan çevirmelerinden dolayı kendilerine helâl kılınmış temiz ve hoş şeyleri onlara yasakladık."},{"n":161,"t":"Menedildikleri halde ribâ almalarından ve haksız yere insanların mallarını yemelerinden ötürü (böyle yaptık). İçlerinden inkâr edenlere de acı bir azâb hazırladık."},{"n":162,"t":"Fakat içlerinden ilimde derinleşmiş olanlar ve mü’minler, sana indiriline ve senden önce indirilene inanırlar. O namazı kılanlar, zekâtı verenler, Allah’a ve âhiret gününe inananlar var ya, işte onlara büyük bir mükâfât vereceğiz!"},{"n":163,"t":"Biz, Nûh’a ve ondan sonra gelen peygamberlere vahyettiğimiz gibi, sana da vahyettik. Nitekim İbrâhim’e, İsmâ’il’e, İshak’a, Ya’kûb’a, sıbtlara, Îsâ’ya, Eyyûb’a, Yûnus’a, Hârûn’a, Süleyman’a da vahyetmiş ve Dâvûd’a da Zebur’u vermiştik."},{"n":164,"t":"Daha önce sana anlattığımız elçilere ve sana anlatmadığımız elçilere de (vahyetmiştik). Ve Allâh Mûsâ’ya da konuşmuştu."},{"n":165,"t":"(Bunları) Müjdeleyici ve uyarıcı elçiler olarak (gönderdik) ki, elçiler geldikten sonra insanların Allah’a karşı bahaneleri kalmasın. Allâh üstündür, hüküm ve hikmet sâhibidir."},{"n":166,"t":"Allâh, sana indirdiğini kendi bilgisiyle indirmiş olduğuna şâhidlik eder. Melekler de (buna) şâhidlik ederler. Allâh’ın şâhidliği de (bir şeyin gerçekliği için) kâfidir."},{"n":167,"t":"(Sana gelenleri) İnkâr edip Allâh yolundan menedenler, hakikaten uzak bir sapıklığa düşmüşlerdir."},{"n":168,"t":"O inkâr edip zulmedenler var ya, Allâh onları ne bağışlayacak, ne de yola iletecektir."},{"n":169,"t":"Sadece cehennemin yoluna (iletecek ve) orada sürekli kalacaklardır. Bu da Allah’a çok kolaydır."},{"n":170,"t":"Ey İnsanlar, Elçi size, Rabbinizden gerçeği getirdi. Kendi yararınıza olarak (ona) inanın. Eğer inkâr ederseniz, bilin ki göklerde ve yerde olanlar Allâh’ındır. Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":171,"t":"Ey Kitap ehli, dininizde taşkınlık etmeyin ve Allâh hakkında gerçek olmayan şeyleri söylemeyin! Meryem oğlu Îsâ Mesih, sadece Allâh’ın elçisi, O’nun Meryem’e attığı kelimesi ve O’ndan bir ruhtur. Allah’a ve elçilerine inanın, (Allâh) \"Üçtür\" demeyin. Kendi yararınıza olarak buna son verin. Çünkü Allâh, yalnız bir tek tanrıdır. Hâşâ O, çocuk sâhibi olmaktan yücedir. Göklerde ve yerde olanların hepsi O’nundur. Vekil olarak Allâh yeter."},{"n":172,"t":"Ne Mesih, Allah’a kul olmaktan çekinir, ne de (Allah’a) yaklaştırılmış melekler. Kim O’na kulluktan çekinir ve büyüklük taslarsa bilsin ki O, onların hepsini kendi huzûruna toplayacaktır."},{"n":173,"t":"İnanıp iyi işler yapanların mükâfâtlarını eksiksiz ödeyecek ve lutfundan onlara daha fazlasını da verecektir. (Kulluktan) çekinip büyüklük taslayanlara da acı bir şekilde azâbedecek ve onlar kendilerine Allah’tan başka ne bir dost, ne de bir yardımcı bulacaklardır."},{"n":174,"t":"Ey insanlar, size Rabbinizden delil geldi ve size apaçık bir nur indirdik."},{"n":175,"t":"Alah’a inanıp O’na yapışanları (Allâh), kendinden bir rahmetin ve lutfun içine sokacak ve onları kendisine varan doğru bir yola iletecektir."},{"n":176,"t":"Senden fetvâ istiyorlar. De ki: Allâh size ana-babasız ve çocuksuz kişinin mirâsı hakkında hükmünü şöyle açıklıyor: Ölen kişinin çocuğu yok, bir kızkardeşi varsa, bıraktığı malın yarısı o(kızkardeşi)nindir. Fakat kendisi, (ölen) kızkardeşinin çocuğu yoksa, onun mirâsını (tamamen) alır. Eğer (ölenin) iki kızkardeşi varsa, bıraktığının üçte ikisi onlarındır. Ve eğer (vârisler) erkek kadın birçok kardeşler olursa, erkeğe, iki kadının payı kadar (pay) verilir. Şaşırırsınız diye Allâh size (hükmünü) açıklıyor. Allâh, herşeyi bilir."}],[{"n":1,"t":"Ey inananlar, akitleri(zi) yerine getirin. Size oku(nup açıkla)nacak olanların dışında kalan hayvanlar sizin için helâl kılındı. Yalnız ihrâmda iken avı helâl saymamak şartiyle. Allâh, istediği hükmü verir."},{"n":2,"t":"Ey inananlar, ne Allâh’ın işâretlerine, ne harâm aya, ne kurbana, ne gerdanlık(lı kurban)lara ve ne de Rablerinin lutuf ve rızâsını arzu ederek Beyt-i harâm’a doğru gelenlere saygısızlık etmeyin. İhrâmdan çıktığınız zaman avlanabilirsiniz. Sizi Mescid-i harâm’dan çevirdiklerinden dolayı bir topluma karşı beslediğiniz kin, sizi suç işlemeğe itmesin. İyilik ve takvâ üzerinde yardımlaşın, günâh ve düşmanlık üzerinde yardımlaşmayın, Allah’tan korkun. Çünkü Allâh’ın azâbı çetindir."},{"n":3,"t":"Leş, kan, domuz eti, Allah’tan başkası adına boğazlanan, boğulmuş, (tahta veya taşla) vurul(arak öldürül)müş, yukarıdan düşmüş, boynuzlanmış ve canavar parçalayarak ölmüş olan havyanlar -henüz canları çıkmadan kestikleriniz hariç- dikili taşlar (putlar) adına boğazlanan hayvanlar ve fal oklariyle kısmet (şans) aramanız size harâm kılındı. Bunlar fısktır (insanı yoldan çıkaran kötü şeylerdir). Bugün artık inkâr edenler, sizin dininiz(i yok etmek)den umudu kesmişlerdir. Onlardan korkmayın, benden korkun! Bugün sizin için dininizi olgunlaştırdım, size ni’metimi tamamladım ve size din olarak İslâm’a râzı oldum. Kim açlıktan daralır, günâha istekle yönelmeden bunlardan yemek zorunda kalırsa ona günâh yoktur. Doğrusu, Allâh bağışlayandır, esirgeyendir."},{"n":4,"t":"Sana, kendilerine neyin helâl kılındığını soruyarlar. De ki: \"Size iyi ve temiz şeyler helâl kılındı. Allâh’ın size öğrettiğinden öğreterek yetiştirdiğiniz avcı hayvanların, sizin için tuttuklarını yeyin ve üzerine Allâh’ın adını anın, Allah’tan korkun. Çünkü Allâh, hesabı çabuk görendir."},{"n":5,"t":"Bugün size iyi ve temiz şeyler helâl kılındı. Kendilerine kitap verilenlerin yemeği, size helâl, sizin yemeğiniz de onlara helâldir. İnanan, namuslu, hür kadınlar ve sizden önce kendilerine kitap verilenlerden namuslu hür kadınlar -zinâ etmeksizin, gizli dost tutmaksızın, namuslu bir biçimde (evlenmek üzere) mehirlerini verdiğiniz takdirde- size helâldir. Kim inanmayı kabul etmezse, onun ameli boşa çıkmıştır ve o, âhirette kaybedenlerdendir."},{"n":6,"t":"Ey inananlar, namaza dur(mak iste)diğiniz zaman yıkayın: yüzlerinizi ve dirseklere kadar ellerizi; meshedin: başlarınızı ve topuklara kadar ayaklarınızı. Eğer cünüp iseniz tam temizlenin. Hasta, yahut yolcu iseniz, yahut biriniz tuvaletten gelmişse, ya da kadınlara dokunmuş da su bulamamışsanız temiz toprağa teyemmüm edin; ondan yüzlerinize ve ellerinize sürün. Allâh size güçlük çıkarmak istemiyor, fakat sizi temizlemek ve size olan ni’metini tamamlamak istiyor ki, şükredesiniz."},{"n":7,"t":"Allâh’ın size olan ni’metini ve O’na verdiğiniz sözü hatırlayın: Hani \"İşittik ve itâ’at ettik!\" demiştiniz. Allah’tan korkun; çünkü Allâh, göğüslerin özünü bilir."},{"n":8,"t":"Ey inananlar, Allâh için adâletle şâhidlik edenler olun. Bir topluluğa karşı duyduğunuz kin, sizi adâletten saptırmasın. Âdil davranın, takvâya yakışan budur. Allah’tan korkun, kuşkusuz Allâh yaptıklarınızı haber almaktadır."},{"n":9,"t":"Allâh, inanıp iyi işler yapanlara va’detmiştir: Bağışlama ve büyük mükâfât onlarındır."},{"n":10,"t":"İnkâr edip âyetlerimizi yalanlayanlara gelince, onlar da cehennemin halkıdır."},{"n":11,"t":"Ey inananlar, Allâh’ın size olan ni’metini hatırlayın: Hani bir topluluk size ellerini uzatmağa (saldırmaya) yeltenmişti de (Allâh) Onların ellerini sizden çekmişti. Alah’tan korkun. Mü’minler Allah’a dayansınlar."},{"n":12,"t":"Allâh, İsrâil oğullarından söz almıştı ve içlerinden on iki başkan göndermiştik. Allâh demişti ki: \"Ben sizinle beraberim, eğer namazı kılar, zekâtı verirseniz; elçilerime inanır, onlara yardım eder ve Allah’a güzel borç verirseniz, elbette sizin günâhlarınızı örterim ve sizi altlarından ırmaklar akan cennetlere sokarım. Bundan sonra sizden kim nankörlük ederse, düz yoldan sapmış olur."},{"n":13,"t":"Sözlerini bozdukları için onları la’netledik ve kalblerini katılaştırdık. Kelimeleri yerlerinden kaydırıyorlar. Kendilerine öğütlenen şeyden pay almayı unuttular. İçlerinden pek azı hariç, dâimâ onlardan hâinlik görürsün. Yine de onları affet, aldırma, çünkü Allâh güzel davrananları sever."},{"n":14,"t":"\"Biz hıristiyanız\" diyenlerin de sözünü almıştık, ama kendilerine öğütlenen şeyden pay almayı unuttular. Bu yüzden kıyâmet gününe kadar aralarına düşmanlık ve kin saldık. Yakında Allâh, onlara, ne yaptıklarını haber verecektir."},{"n":15,"t":"Ey Kitap ehli, elçimiz size geldi, Kitaptan gizlediğiniz şeylerin çoğunu size açıklıyor, çoğundan da geçiyor. Gerçekten size Allah’tan bir nur ve açık bir Kitap gelmiştir."},{"n":16,"t":"Allâh, onunla rızâsına uyanları esenlik yollarına iletir ve onları kendi izniyle karanlıklardan aydınlığa çıkarıp dosdoğru bir yola iletir."},{"n":17,"t":"\"Allâh, Meryem oğlu Mesih’tir.\" diyenler küfre gitmişlerdir. De ki: \"Öyle ise Allâh, Meryem oğlu Mesih’i, annesini ve yeryüzünde olanların hepsini helâk etmek istese, Allah’a karşı kimin elinde bir şey var?\" Göklerde, yerde ve ikisinin arasında bulunan herşey O’nundur. O, dilediğini yaratır, Allâh, herşeyi yapabilendir."},{"n":18,"t":"Yahûdiler ve hıristiyanlar; \"Biz Allâh’ın oğulları ve sevgilileriyiz.\" dediler. De ki: \"O halde niçin günâhlarınızdan ötürü (Allâh) size azâbediyor?\" Hayır, siz de O’nun yaratıklarından birer insansınız. O dilediğini bağışlar, dilediğine azâbeder. Göklerin, yerin ve ikisi arasında bulunan herşeyin mülkü Allâh’ındır. Dönüş de O’nadır."},{"n":19,"t":"Ey Kitap ehli, elçilerin arasının kesildiği sırada size Elçimiz geldi, size gerçekleri açıklıyor ki, (yarın kıyâmette); \"Bize bir müjdeleyici ve uyarıcı gelmedi\" demeyesiniz. İşte size müjdeleyici ve uyarıcı geldi. Allâh, herşeyi yapabilendir."},{"n":20,"t":"Mûsâ, kavmine demişti ki: \"Ey kavmim, Allâh’ın size olan ni’metini hatırlayın; zira (O), aranızda peygamberler var etti, sizi krallar yaptı ve size dünyâlarda hiç kimseye vermediğini verdi.\""},{"n":21,"t":"\"Ey kavmim, Allâh’ın size yaz(ıp nasibet)diği Kutsal Toprağa girin, arkanıza dönmeyin, yoksa kaybedersiniz!\""},{"n":22,"t":"Dediler ki: \"Ey Mûsâ, orada zorba bir millet var. Onlar oradan çıkmadıkça biz oraya girmeyiz. Eğer çıkarlarsa, o zaman oraya gireriz.\""},{"n":23,"t":"(Allah’tan) korkanlardan Allâh’ın ni’met verdiği iki adam dedi ki; \"Onların üzerine kapıdan girin, eğer kapıdan girerseniz, muhakkak ki siz gâlib gelirsiniz. Haydi eğer inanıyorsanız Allah’a dayanın!\""},{"n":24,"t":"Dediler ki: \"Ey Mûsâ, onlar orada olduğu sürece biz oraya asla girmeyiz. Sen ve Rabbin, gidin, savaşın, biz burada oturuyoruz!\""},{"n":25,"t":"(Mûsâ), \"Ya Rabbi, dedi, ben kendimden ve kardeşimden başkasına mâlik değilim. Bizimle, o yoldan çıkmış toplumun arasını ayır.\""},{"n":26,"t":"(Allâh) buyurdu ki: \"Orası onlara kırk yıl yasaklandı. O yerde şaşkın şaşkın dolaşacaklar. Sen, yoldan çıkmış o toplum için üzülme.\""},{"n":27,"t":"Onlara iki Âdem oğlunun haberini gerçek olarak oku: Hani her biri birer kurban sunmuşlardı, (kurban) birinden kabul edilmiş, ötekinden kabul edilmemişti. (Kurbanı kabul edilmeyen, kabul edilene): \"Seni öldüreceğim\" demişti. (O da); \"Allâh, sadece korunanlardan kabul eder\" dedi."},{"n":28,"t":"\"Andolsun, eğer sen beni öldürmek için bana elini uzatırsan, ben seni öldürmek için sana elimi uzatmam. Çünkü ben âlemlerin Rabbinden korkarım!\""},{"n":29,"t":"\"Ben isterim ki sen, benim günâhımı da, senin günâhını da yüklenip ateş halkından olasın! zâlimlerin cezâsı budur.\""},{"n":30,"t":"Nefsi, onu kardeşini öldürmeye çağırdı, (o da nefsine uyarak) onu öldürdü, ziyana uğrayanlardan oldu."},{"n":31,"t":"Derken Allâh, ona kardeşinin cesedini nasıl gömeceğini göstermek için yeri eşeleyen bir karga gönderdi. (Karganın yaptığını görünce); \"Yazık bana, şu karga kadar olup da kardeşimin cesedini gömmekten âciz miyin (ben?)\" dedi ve pişman olanlardan oldu!"},{"n":32,"t":"Bundan dolayı İsrâil oğullarına şöyle yazdık: Kim, bir cana kıymamış, ya da yeryüzünde bozgunculuk yapmamış olan bir canı öldürürse, sanki bütün insanları öldürmüş gibidir. Kim de onu(n hayâtını kurtarmak sûretiyle) yaşatırsa, bütün insanları yaşatmış gibi olur. Andolsun elçilerimiz onlara açık deliller getirdiler, ama bundan sonra da onlardan çoğu, yine yeryüzünde israf etmekte(aşırı gitmekte)dirler."},{"n":33,"t":"Allâh ve elçisiyle savaşanların ve yeryüzünde bozgunculuk yapmağa çalışanların cezâsı: (ya) öldürülmeleri, ya asılmaları, ya ellerinin, ayaklarının çapraz kesilmesi veya bulundukları yerden sürülmeleridir. Bu, onların dünyâda çekecekleri rezilliktir. Âhirette ise onlara büyük bir azâb vardır."},{"n":34,"t":"Ancak sizin onları (yenip) ele geçirmenizden önce tevbe edenler olursa bilin ki Allâh, bağışlayandır, esirgeyendir (tevbe edenleri affeder)."},{"n":35,"t":"Ey inananlar, Allah’tan korkun, O’na (yaklaşmağa) yol arayın ve O’nun yolunda cihâdedin ki, kurtuluşa eresiniz."},{"n":36,"t":"O inkâr edenler var ya, eğer yeryüzünde olanların hepsi ve onun bir katı daha kendilerinin olsa da, kıyâmet gününün azâbından kurtulmak için (bunları) fidye verseler, kendilerinden kabul edilmez. Onlar için acı bir azâb vardır."},{"n":37,"t":"Ateşten çıkmak isterler ama oradan çıkacak değillerdir. Onlar için sürekli bir azâb vardır."},{"n":38,"t":"Hırsızlık eden erkek ve kadının, yaptıklarına karşılık Allah’tan bir cezâ olarak ellerini kesin! Allâh dâimâ üstündür, hüküm ve hikmet sâhibidir."},{"n":39,"t":"Kim yaptığı haksızlıktan sonra tevbe eder, uslanırsa, şüphesiz Allâh, onun tevbesini kabul eder. Çünkü Allâh bağışlayan, acıyandır."},{"n":40,"t":"Göklerin ve yerin mülkünün Allah’a âidolduğunu bilmedin mi? (O), dilediğine azâbeder, dilediğini bağışlar. Allâh herşeye kâdirdir."},{"n":41,"t":"Ey Elçi, ağızlariyle \"inandık\" dedikleri halde kalbleri inanmamış olanlar arasında küfürde yarış edenler seni üzmesin. yahûdiler arasında da yalana kulak veren, sana gelmemiş olan bir kavme kulak verenler vardır. Onlar kelimeleri yerlerinden kaydırırlar: \"Eğer size bu verilirse alın, bu verilmezse sakının!\" derler. Allâh birini şaşırtmak isterse, sen onun için Allah’a karşı hiçbir şey yapamazsın. Onlar, Allâh’ın, kalblerini temizlemek istemediği kimselerdir. Onlar için dünyâda rezillik var ve yine onlar için âhirette de büyük bir azâb vardır."},{"n":42,"t":"Yalana kulak verirler, harâm yerler. Sana gelirlerse, ister aralarında hüküm ver, ister onlardan yüz çevir; eğer onlardan yüz çevirirsen, sana hiçbir zarar veremezler. Ve eğer hüküm verirsen, aralarında adâletle hüküm ver. Çünkü Allâh, adâlet yapanları sever."},{"n":43,"t":"İçinde Allâh’ın hükmü bulunan Tevrât yanlarında dururken seni nasıl hakem yapıyorlar, ondan sonra da (verdiğin hükümden) dönüyorlar. Onlar inanıcı değillerdir."},{"n":44,"t":"Gerçekten Tevrât’ı biz indirdik, onda yol gösterme ve nur vardır. İslâm olmuş peygamberler, onunla yahûdilere hüküm verirlerdi, kendilerini Tanrıya vermiş zâhidler ve âlimler de \"Allâh’ın Kitabını korumakla görevlendirildiklerinden onunla (hüküm verirlerdi) ve onu gözetip kollarlardı. (Ey hakimler), insanlardan korkmayın, benden korkun ve benim âyetlerimi az bir paraya satmayın! Kim Allâh’ın indirdiği ile hükmetmezse işte kâfirler onlardır!"},{"n":45,"t":"O(Hak Kitabı)nda onlara, cana can, göze göz, buruna burun, kulağa kulak, dişe diş ve yaralara karşılıklı kısâs (ödeşme) yazdık. Kim bunu bağışlar(kısâs hakkından vazgeçer)se o, kendisi için keffâret olur. Ve kim Allâh’ın indirdiğiyle hükmetmezse, işte zâlimler onlardır."},{"n":46,"t":"Onların ardından, yanlarındaki Tevrât’ı doğrulayıcı olarak Meryem oğlu Îsâ’yı gönderdik ve ona, içinde yol gösterme ve nur bulunan, önündeki Tevrât’ı doğrulayan, korunanlar için yol gösterici ve öğüt olan İncil’i verdik."},{"n":47,"t":"İncil sâhipleri, Allâh’ın onda indirdiği ile hükmetsinler. Kim Allâh’ın indirdiğiyle hükmetmezse işte onlar, yoldan çıkmışlardır."},{"n":48,"t":"Sana da kendinden önceki Kitabı doğrulayıcı ve onu kollayıp koruyucu olarak Kitabı gerçekle indirdik. Artık onların aralarında Allâh’ın indirdiğiyle hükmet ve sana gelen gerçekten ayrılıp onların keyiflerine uyma! Sizden her biriniz için bir şeri’at ve bir yol belirledik. Allâh isteseydi, hepinizi bir tek ümmet yapardı, fakat size verdiğ(i ni’met)ler(i) içinde sizi sınamak istedi. Öyleyse hayır işlerine koşun, hepinizin dönüşü Allah’adır. O size ayrılığa düştüğünüz şeyler(in hakikatin)i haber verecektir."},{"n":49,"t":"Aralarında Allâh’ın indirdiğiyle hükmet, onların keyiflerine uyma ve onların, Allâh’ın indirdiği şeylerin bir kısmından seni şaşırtmalarından sakın! Eğer dönerlerse bil ki Allâh, bazı günâhları yüzünden onları felâkete uğratmak istiyordur. Zaten insanlardan çoğu, yoldan çıkmışlardır."},{"n":50,"t":"Yoksa câhiliyye hükmünü mü arıyorlar? İyi bilen bir toplum için Allah’tan daha güzel hüküm veren kim olabilir?"},{"n":51,"t":"Ey inananlar, yahûdileri ve hıristiyanları veliler edinmeyin! Onlar, birbirlerinin velileridir. Sizden kim onları kendine veli yaparsa, o onlardandır. Şüphesiz Allâh, zâlim toplumu doğru yola iletmez."},{"n":52,"t":"Kalblerinde hastalık bulunanların: \"Bize bir felâket gelmesinden korkuyoruz!\" diyerek onların arasına koştuklarını görürsün. Belki Allâh fetih ya da kendi katından bir iş getirir de onlar, içlerinde gizlediklerine pişman olurlar."},{"n":53,"t":"(O zaman) inananlar, \"Bunlar mı o, bütün güçleriyle sizinle beraber olduklarına yemin edenler?\" derler. Bütün çabaları boşa çıkmış, kaybedenlerden olmuşlardır."},{"n":54,"t":"Ey inananlar, sizden kim dininden dönerse (bilsin ki) Allâh, yakında öyle bir toplum getirecek ki (O) onları sever, onlar da O’nu severler. Mü’minlere karşı alçak gönüllü, kâfirlere karşı onurlu ve şiddetlidirler. Allâh yolunda cihâd ederler, hiçbir kınayıcının kınamasından korkmazlar. Bu, Allâh’ın bir lutfudur, onu dilediğine verir. Allâh’(ın lutfu) geniştir, (O), bilendir."},{"n":55,"t":"Sizin veliniz, ancak Allâh, Elçisi ve namazlarını kılan, zekâtlarını veren, rükû’a varan mü’minlerdir."},{"n":56,"t":"Kim Allâh’ı, Elçisini ve mü’minleri dost tutarsa (bilsin ki) gâlib gelecek olanlar, yalnız Allâh’ın taraftarlarıdır."},{"n":57,"t":"Ey inananlar, sizden önce Kitap verilmiş olanlardan ve kâfirlerden dininizi eğlence ve oyun yerine koyanları dost tutmayın; inanıyorsanız Allah’tan korkun."},{"n":58,"t":"Namaza çağırıldığınız zaman onu eğlence ve oyun yerine koydular. Düşüncesiz bir topluluk oldukları için böyle yaptılar."},{"n":59,"t":"De ki: \"Ey Kitap ehli, Allah’a, bize indirilene ve bizden önce indirilene inandığımız için mi bizden hoşlanmıyorsunuz? Oysa sizin çoğunuz yoldan çıkmıştır.\""},{"n":60,"t":"De ki: \"Allâh katında yeri bundan daha kötü olanı size söyleyeyim mi? Allâh kim(ler)e la’net ve gazab etmiş, kimlerden maymunlar, domuzlar ve şeytâna tapanlar yapmışsa, işte onların yeri daha kötüdür ve onlar düz yoldan daha çok sapmışlardır."},{"n":61,"t":"(Onlar) size geldiklerinde \"inandık\" derler. Oysa küfürle (yanınıza) girmişler, yine onunla (yanınızdan) çıkmışlardır. Allâh onların (içlerinde) gizlediklerini daha iyi bilir."},{"n":62,"t":"Onlardan çoğunun günâh, düşmanlık ve harâm yemede birbirleriyle yarıştıklarını görürsün. Yaptıkları şey ne kötüdür!"},{"n":63,"t":"Rabbânilerin ve hahamların, onları günâh söz söylemekten, harâm yemekten menetmeleri gerekmez miydi? Yaptıkları şey ne kötüdür!"},{"n":64,"t":"Yahûdiler \"Allâh’ın eli bağlıdır (Allâh cimridir)\". dediler. Kendi elleri bağlandı ve söyledikleri sözden ötürü la’netlendiler. Hayır, Allâh’ın iki eli de açıktır, dilediği gibi verir. Andolsun, Rabbinden sana indirilen, onların çoğunun azgınlığını ve küfrünü artıracaktır. Biz onların aralarına tâ kıyâmet gününe kadar düşmanlık ve kin atmışızdır. Ne zaman savaş için bir ateş yakmışlarsa Allâh onu söndürmüştür. (Onlar) yeryüzünde bozgunculuğa koşarlar. Allâh da bozguncuları sevmez."},{"n":65,"t":"Eğer Kitap ehli inanıp (Allâh’ın azâbından) korunsalardı, onların kötülüklerinden geçerdik ve onları ni’meti bol cennetlere sokardık."},{"n":66,"t":"Eğer onlar Tevrât’ı, İncil’i ve Rablerinden kendilerine indirileni gereğince uygulasalardı, muhakkak ki üstlerinde(ki ağaçların meyvelerinde)n ve ayaklarının altın(daki ürünler)den yerlerdi. İçlerinde tutumlu (ılımlı) bir ümmet var, ama onlardan çoğu, ne kötü işler yapıyorlar?"},{"n":67,"t":"Ey Elçi, Rabbinden sana indirileni duyur; eğer bunu yapmazsan, O’nun mesajını duyurmamış olursun. Allâh seni insanlardan korur. Doğrusu Allâh, kâfirler toplumunu yola iletmez."},{"n":68,"t":"De ki: Ey Kitap ehli, siz Tevrât’ı, İncil’i ve Rabbi’nizden size indirileni uygulamadıkça bir esas üzerinde değilsiniz. (Ey Muhammed), Rabbinden sana indirilen, onlardan çoğunun azgınlık ve inkârını artıracaktır. Sen o kâfirler toplumu için üzülme!"},{"n":69,"t":"İnananlar, yahûdiler, sâbiiler ve hıristiyanlar(dan) Allah’a ve âhiret gününe inanan ve iyi işler yapanlara korku yoktur ve onlar üzülmeyeceklerdir."},{"n":70,"t":"Andolsun, biz İsrâil oğullarından söz almış ve onlara elçiler göndermiştik. Ne zaman bir elçi onlara canlarının istemediği bir şey getirdiyse (gelen elçilerin) bir kısmını yalanladılar, bir kısmını da öldürüyorlardı."},{"n":71,"t":"Bir fitne kopmayacak sandılar, kör oldular, sağır kesildiler. Sonra Allâh onların tevbesini kabul etti. Sonra yine çokları kör, sağır kesildiler. Allâh yaptıklarını görüyor."},{"n":72,"t":"Andolsun, \"Allâh, ancak Meryem oğlu Mesih’tir.\" diyenler elbette kâfir olmuşlardır. Halbuki Mesih demişti ki: \"Ey İsrâil oğulları, benim Rabbim ve sizin Rabbiniz olan Allah’a kulluk edin. Zira kim Allah’a ortak koşarsa muhakkak ki, Allâh ona cenneti harâm etmiştir ve onun varacağı yer ateştir; zâlimlerin yardımcıları yoktur!\""},{"n":73,"t":"\"Allâh, üçün üçüncüsüdür\" diyenler elbette kâfir olmuşlardır. Oysa yalnız bir tek tanrı vardır, başka tanrı yoktur. Bu dediklerinden vazgeçmezlerse elbette onlardan inkâr edenlere acı bir azâb dokunacaktır."},{"n":74,"t":"Hâlâ Allah’a tevbe edip O’ndan af dilemiyorlar mı? Allâh bağışlayandır, esirgeyendir."},{"n":75,"t":"Meryem oğlu Mesih, bir elçiden başka bir şey değildir. Ondan önce de elçiler gelip geçmiştir. Annesi de dosdoğruydu. İkisi de yemek yerlerdi. (Yaşamak için yemeğe muhtaç olan nasıl tanrı olabilir?) Bak, onlara nasıl âyetleri açıklıyoruz, sonra bak nasıl (haktan) çevriliyorlar!?"},{"n":76,"t":"De ki: \"Allâh’ı bırakıp size ne zarar, ne de yarar vermeğe gücü yetmeyen şeylere mi tapıyorsunuz? Oysa Allâh, işiten, bilendir (O’na tapmanız gerekmez mi?).\""},{"n":77,"t":"De ki: \"Ey Kitap ehli, dininizde haksız yere aşırılığa dalmayın ve önceden sapmış, birçoğunu da saptırmış, düz yoldan şaşmış bir milletin keyiflerine uymayın!\""},{"n":78,"t":"İsrâil oğullarının nankörlerine, Dâvûd ve Meryem oğlu Îsâ diliyle la’net edilmiştir. Çünkü (onlar) isyân etmişlerdi ve saldırıyorlardı."},{"n":79,"t":"Yaptıkları kötülükten vazgeçmiyorlardı. Ne kötü işler yapıyorlardı!"},{"n":80,"t":"Onlardan çoğunun, inkâr edenlerle dostluk ettiklerini görürsün. Gerçekten nefislerinin, kendileri için yapıp gönderdiği ne kötüdür (ki o yüzden) Allâh onlara gazabetmiştir ve azâbda sürekli kalacaklardır."},{"n":81,"t":"Eğer Allah’a, Peygambere ve ona indirilene inansalardı, o(inkâr ede)nleri veli yapmazlardı. Ama onlardan çoğu yoldan çıkmış insanlardır."},{"n":82,"t":"İnsanlar içerisinde, inananlara en yaman düşman olarak yahûdileri ve (Allah’a) ortak koşanları bulursun. İnananlara sevgice en yakınları da \"Biz hıristiyanlarız.\" diyenleri bulursun. Çünkü onların içlerinde keşişler ve rahipler vardır ve onlar büyüklük taslamazlar."},{"n":83,"t":"Elçi’ye indirilen(Kur’ân)ı dinledikleri zaman, tanıdıkları gerçekten dolayı gözlerinin yaşla dolup taştığını görürsün. Derler ki: \"Rabbimiz, inandık, bizi şâhidlerle beraber yaz!\""},{"n":84,"t":"\"Biz, Rabbimizin bizi iyiler arasına katmasını umarken neden Allah’a ve bize gelen gerçeğe inanmayalım?\""},{"n":85,"t":"Bu sözlerinden dolayı Allâh onlara, altlarından ırmaklar akan, içinde ebedi kalacakları cennetler verdi. Güzel davrananların mükâfâtı işte budur!"},{"n":86,"t":"İnkâr edip âyetlerimizi yalanlayanlar da cehennem halkıdır."},{"n":87,"t":"Ey inananlar, Allâh’ın size helâl kıldığı güzel ve temiz şeyleri harâm etmeyin, sınırı aşmayın. Çünkü Allâh, sınırı aşanları sevmez."},{"n":88,"t":"Allâh’ın size verdiği rızıklardan helâl ve temiz olarak yeyin ve inandığınız Allah’tan korkun!"},{"n":89,"t":"Allâh sizi, yeminlerinizdeki lağv(kasıtsız olarak yaptığınız yeminler)den ötürü sorumlu tutmaz. Fakat bilerek yaptığınız yeminlerden ötürü sizi sorumlu tutar. Bu(geleceğe bağlı yemini bozma)nın keffâreti: âilenize yedirdiğinizin orta derecesinden on fakiri yedir(ip doyur)mak, yahut onları giydirmek, ya da bir boyun(köley)i hürriyete kavuşturmaktır. Bunu bulamayan kimse, üç gün oruç tutsun. İşte yemin ettiğiniz zaman, yeminleriniz(i bozman)ın keffâreti budur. yeminlerinizi koruyun. Allâh, âyetlerini size böyle açıklıyor ki, şükredesiniz."},{"n":90,"t":"Ey inananlar, şarap, kumar, dikili taşlar, şans okları şeytân işi birer pisliktir. Bunlardan kaçının ki kurtuluşa eresiniz."},{"n":91,"t":"Şeytân, şarap ve kumar ile aranıza düşmanlık ve kin sokmak, sizi Allâh’ı anmaktan ve namazdan alakoymak istiyor. Artık (bunlardan) vazgeçecek misiniz?"},{"n":92,"t":"Allah’a itâ’at edin, Elçi’ye itâ’at edin, (kötü şeylerden) sakının! Eğer (kabul etmez) dönerseniz, bilin ki elçimize düşen, açıkça duyurmaktır."},{"n":93,"t":"İnanıp iyi işler yapanlara -bundan böyle (kötülüklerden) korunup inandıkları ve iyi işler yaptıkları, sonra (yasaklardan) korunup (onların yasaklığına) inandıkları ve yine korunup iyilik ettikleri takdirde- (daha önce) yediklerinden ötürü bir günâh yoktur. Allâh güzel davrananları sever."},{"n":94,"t":"Ey inananlar, Allâh sizi, ellerinizin ve mızraklarınızın erişeceği bir avla dener ki, gizlide kendisinden kimin korktuğunu bilsin (görmeden Alah’a inanıp O’ndan korkanlar ortaya çıksın, bilinsin). Kim bundan sonra saldırıda bulunursa onun için acı bir azâb vardır."},{"n":95,"t":"Ey inananlar, ihrâmda iken av öldürmeyin. Sizden kim kasden onu öldürürse, öldürdüğünün dengi olan bir hayvan cezâsı vardır ki (bu, öldürülene denk olduğuna) içinizden iki âdil kişinin karar vereceği, Ka’be’ye varacak bir kurban; yahut yoksullara yedirme şeklinde keffâret; ya da buna denk oruçtur. Tâ ki böylece (o insan), yaptığı işin vebâlini tadsın. Allâh, geçmişi affetmiştir. Kim düşmanlık ederse Allâh ondan öc alır. Allâh, dâimâ gâliptir, öc alandır."},{"n":96,"t":"Hem kendinize, hem de yolculara bir geçimlik olmak üzere deniz avı ve yiyeceği, size helâl kılındı. İhrâmda olduğunuz sürece size kara avı yasaklandı. Huzûruna toplanacağınız Allah’tan korkun!"},{"n":97,"t":"Allâh Ka’be’yi, o saygıdeğer evi, insanlar için (hayât ve güven) durağı yaptı. O saygıdeğer ayı, kurbanı, tasmalı kurbanlıkları da (böyle yaptı) ki Allâh’ın göklerde ve yerde olanları bildiğini ve Allâh’ın herşeyi bilici olduğunu anlayasınız."},{"n":98,"t":"İyi bilin ki Allâh’ın cezâsı çetindir ve Allâh bağışlayandır, esirgeyendir."},{"n":99,"t":"Elçi’ye düşen, sadece duyurmaktır. Allâh, gizlediğiniz ve açığa vurduğunuz şeyleri bilir."},{"n":100,"t":"De ki: \"Murdarla temiz bir olmaz. Murdarın çokluğu hoşuna gitse de. O halde ey sağduyu sâhipleri, Allah’tan korkun ki kurtuluşa eresiniz!\""},{"n":101,"t":"Ey inananlar, açıklandığı zaman hoşunuza gitmeyecek şeyleri sormayın. Eğer Kur’ân indirilirken onları sorarsanız, size açıklanır. Halbuki Allâh onlardan geçmiştir. Allâh bağışlayandır, halimdir."},{"n":102,"t":"Sizden önce gelen bir toplum da onları sormuştu da sonra onları tanımaz olmuşlardı."},{"n":103,"t":"Allâh, bahire, sâibe, vasile ve hâm diye bir şey yapmamıştır. Fakat inkâr edenler, Allah’a yalan uyduruyorlar ve çokları da akıl erdiremiyorlar."},{"n":104,"t":"Onlara: \"Allâh’ın indirdiğine ve Elçi’ye gelin!\" dense, \"Babalarımızı üzerinde bulduğumuz şey bize yeter!\" derler. Babaları hiçbir şey bilmeyen, doğru yolu bulamayan kimseler olsa da mı?"},{"n":105,"t":"Ey inananlar, siz kendinize bakın, siz doğru yolda olduğunuz takdirde sapan kimse size zarar vermez. Hepinizin dönüşü Allah’adır. O size ne yaptığınızı haber verecektir."},{"n":106,"t":"Ey inananlar, birinize ölüm gelince vasiyyet sırasında içinizden iki âdil kişi, aranızda şâhidlik etsin. Ya da yeryüzünde yolculuk ederken başınıza ölüm musibeti gelmişse, sizden olmayan iki kişi (şâhidlik etsin). Kuşkulanırsanız, namazdan sonra onları tutar(yemin ettirir)siniz: \"Akrabâ da olsa yeminimizi hiçbir paraya satmayacağız, Allâh’ın (üzerimizde bir borç olarak bulunan) şâhidliğini gizlemeyeceğiz, yoksa biz, elbette günâhkârlardan oluruz, \"diye Allah’a yemin ederler."},{"n":107,"t":"Eğer onların bir günâh işledikleri (yalan söyleyip hakkı gizledikleri) anlaşılırsa; (o iki şâhidin), haklarına tecâvüz etmek istediği kimselerden (mirâsçılardan, ölüye yakınlıklarından ve durumu daha iyi bildiklerinden dolayı şâhidliğe) daha lâyık olan iki kişi, onların yerine geçer. Allah’a (şöyle) yemin ederler: \"Mutlaka bizim şâhidliğimiz, onların şâhidliğinden daha doğrudur, biz (hakka) tecâvüz etmedik, yoksa biz elbette zâlimlerden oluruz\" (derler)."},{"n":108,"t":"Şâhidliği gereği gibi yapmalarına, yâhut yemin(etme)lerinden sonra yeminlerin(in) reddedilmesinden korkmalarına en uygun olan budur. Allah’tan korkun ve iyi dinleyin: Allâh, yoldan çıkan topluluğu doğru yola iletmez."},{"n":109,"t":"Allâh, Elçileri toplayacağı gün: \"Size ne cevap verildi?\" der. \"Bizim bilgimiz yok, derler, gizlileri bilen yalnız sensin, sen!\""},{"n":110,"t":"Allâh demişti ki: \"Ey Meryem oğlu Îsâ, sana ve annene olan ni’metimi hatırla, hani seni Ruhu’l-Kudüs ile desteklemiştim; beşikte ve yetişkin iken insanlarla konuşuyordun; sana Kitabı, hikmeti, Tevrât’ı ve İncil’i öğrettim. Benim iznimle çamurdan kuş şeklinde bir şey yaratıyor, içine üflüyordun, benim iznimle kuş oluyordu; anadan doğma körü ve alacalıyı benim iznimle iyileştiriyordun; benim iznimle ölüleri (diriltip kabirlerden) çıkarıyordun ve İsrâil oğullarını da senden savmıştım; hani sen onlara açık deliller getirdiğin zaman, içlerinden inkâr edenler: \"Bu açık bir büyüden başka bir şey değil!\" demişti."},{"n":111,"t":"Havârilere: \"Bana ve elçime inanın!\" diye vahyetmiştim (kalblerine bu düşünceyi atmıştım); \"İnandık, bizim müslümanlar olduğumuza şâhidol!\" demişlerdi."},{"n":112,"t":"Havâriler demişlerdi ki: \"Ey Meryem oğlu Îsâ, Rabbin bize gökten bir sofra indirebilir mi? (Îsâ): \"İnanıyorsanız Allah’tan korkun!\" dedi."},{"n":113,"t":"\"İstiyoruz ki, ondan yiyelim, kalblerimiz iyice yatışsın, senin bize doğru söylediğini bilelim ve buna bizzat tanık olalım.\" dediler."},{"n":114,"t":"Meryem oğlu Îsâ da: \"Allâh’ım, Rabbimiz, bizim üzerimize gökten bir sofra indir ki bizim için, önce ve sonra gelenlerimiz için (o gün) bir bayram olsun ve (o olay) Senden de bir mu’cize olsun. Bizi rızıklandır, Sen rızık verenlerin en hayırlısısın!\" dedi."},{"n":115,"t":"Allâh buyurdu ki: \"Ben onu sizin üzerinize indireceğim, ama ondan sonra sizden kim inkâr ederse ben ona dünyâlarda hiç kimseye yapmayacağım azâbı yaparım!\""},{"n":116,"t":"Ve yine Allâh demişti ki: \"Ey Meryem oğlu Îsâ sen mi insanlara ’Beni ve annemi, Allah’tan başka iki tanrı edinin’ dedin?\". Hâşâ, dedi, Sen yücesin, benim için gerçek olmayan bir şeyi söylemek benim haddime değildir! Eğer demiş olsaydım, sen bunu bilirdin, sen benim nefsimde olanı bilirsin, ben senin nefsinde olanı bilmem, çünkü gizlileri bilen yalnız sensin, sen!\""},{"n":117,"t":"\"Ben onlara: Benim ve sizin Rabbiniz olan Allah’a kulluk edin, diye senin bana emretmiş olduğundan başka bir şey söylemedim. Ben onların içinde olduğum sürece onları kolladım, fakat sen beni vefat ettirince onları gözetleyen (yalnız) Sen oldun. Sen herşeyi görensin."},{"n":118,"t":"\"Eğer onlara azâbedersen, onlar senin kullarındır (dilediğini yaparsın); eğer onları bağışlarsan, şüphesiz sen dâimâ üstünsün, hüküm ve hikmet sâhibisin!\""},{"n":119,"t":"Allâh buyurdu: \"Bu, sâdıklara, doğruluklarının fayda sağlayacağı gündür. Onlar için altlarından ırmaklar akan, içinde ebedi kalacakları cennetler vardır.\" Allâh onlardan râzı olmuştur, onlar da O’ndan râzı olmuşlardır. İşte büyük başarı budur!"},{"n":120,"t":"Göklerin, yerin ve bunlarda bulunan herşeyin mülkü Allâh’ındır. O, herşeye kâdirdir!"}],[{"n":1,"t":"Hamdolsun o Allah’a ki, gökleri ve yeri yarattı, karanlıkları ve aydınlığı var etti. Yine de inkârcılar, Rablerine eşler tutuyorlar."},{"n":2,"t":"O, sizi çamurdan yaratıp, sonra (da hayâtınıza) bir süre koymuştur. (Kâfirlerin cezâlandırılması için) Belirli bir süre de kendi katındadır. Böyle iken, siz hâlâ kuşkulanıyorsunuz."},{"n":3,"t":"O, göklerde de, yerde de (tek) Allah’tır. Sizin gizlinizi, açığınızı ve ne kazandığınızı bilir."},{"n":4,"t":"Onlara Rablerinin âyetlerinden hiçbir âyet gelmez ki, ondan yüz çevirmesinler."},{"n":5,"t":"İşte, kendilerine gelen hakkı da yalanladılar. Fakat alay ettikleri şeyin haberleri, yakında kendilerine gelecek(uyarıldıkları azâb onları kuşatacak)tır."},{"n":6,"t":"Görmediler mi, onlardan önce nice nesiller yok ettik; hem onlara, yeryüzünde size vermediğimiz imkânları vermiştik ve göğü de üzerlerine bol bol boşaltmıştık ve ırmakları ayaklarının altından akar kılmıştık. Fakat günâhlarından ötürü onları helâk ettik ve onların ardından başka bir nesil yarattık."},{"n":7,"t":"Eğer sana kâğıt üzerine yazılı bir Kitap indirmiş olsaydık da onu elleriyle tutsalardı, yine inkâr edenler, \"Bu, apaçık bir büyüden başka bir şey değildir!\" derlerdi."},{"n":8,"t":"\"O’na bir melek indirilmeli değil miydi?\" dediler. Eğer bir melek indirseydik, iş bitirilmiş olurdu, artık kendilerine hiç göz açtırılmazdı."},{"n":9,"t":"Eğer O(Hak Elçisi)ni melek yapsaydık, yine bir adam (şeklinde) yapardık ve onları yine düştükleri kuşkuya düşürürdük."},{"n":10,"t":"Senden önce de peygamberlerle alay edilmişti. Fakat onlarla alay edenleri, alay ettikleri gerçek kuşatıverdi."},{"n":11,"t":"De ki: \"Yeryüzünde dolaşın da yalanlayanların sonu nasıl olmuş, görün!\""},{"n":12,"t":"De ki: \"Göklerde ve yerde olanlar kimindir?\" \"Allâh’ındır\" de. O, rahmet etmeyi kendi üstüne yazmış(acımayı kendisine prensip edinmiş)tir. Sizi elbette varlığında şüphe olmayan kıyâmet gününde toplayacaktır. Ama kendilerini ziyana sokanlar, inanmazlar."},{"n":13,"t":"Gece ve gündüzde barınan her şey O’nundur. O, işitendir, bilendir."},{"n":14,"t":"De ki: \"Gökleri ve yeri yoktan var eden, besleyen, fakat kendisi beslenmeyen Allah’tan başka dost mu tutayım?\" \"Bana, İslâm olanların ilki olmam emredildi de!\" ve sakın ortak koşanlardan olma!"},{"n":15,"t":"De ki: \"Eğer Rabbime isyân edersem, büyük bir günün azâbından korkarım!\""},{"n":16,"t":"(O öyle bir gündür ki) o gün kimden azâb çevrilip savılırsa gerçekten (Allâh) ona acımıştır. İşte apaçık başarı budur."},{"n":17,"t":"Allâh sana bir zarar dokundursa, onu yine kendisinden başka açacak yoktur ve eğer sana bir hayır dokundursa, kuşkusuz O, herşeyi yapabilendir."},{"n":18,"t":"O, kullarının üstünde tam hâkimdir (onları istediği gibi yönetir), O herşeyi yerli yerince yapan, (herşeyi) haber alandır."},{"n":19,"t":"De ki: \"Şâhidlik bakımından hangi şey daha büyüktür?\" De ki: \"Benimle sizin aranızda Allâh şâhiddir. Bu Kur’ân bana vahyolundu ki, onunla sizi ve ulaştığı herkesi uyarayım. Siz gerçekten Allâh ile beraber başka tanrılar olduğuna şâhidlik ediyor musunuz?\", \"Ben şâhidlik etmem!\" de: \"O, ancak tek bir Tanrıdır, ben sizin ortak koştuğunuz şeylerden uzağım\" de."},{"n":20,"t":"Kendilerine Kitap verdiklerimiz, oğullarını tanıdıkları gibi onu tanırlar (onun Allâh tarafından vahyedildiğini bilirler), ama kendilerini ziyana sokanlar inanmazlar."},{"n":21,"t":"Allah’a yalan uyduran, ya da O’nun âyetlerini yalanlayandan daha zâlim kim olabilir? zâlimler de kurtuluş yüzü görmezler."},{"n":22,"t":"Hepsini topladığımız, sonra ortak koşanlara; \"Hani (Allah’a) ortak sandığınız şeyler nerede?\" dediğimiz gün;"},{"n":23,"t":"Sonra onların: \"Rabbimiz Allah’a andolsun ki biz ortak koşanlar değildik.\" demelerinden başka çareleri kalmadığı (gün);"},{"n":24,"t":"Bak ki, nasıl kendilerine karşı yalan söylediler ve uydurdukları şeyler kendilerinden sapıp gitti."},{"n":25,"t":"İçlerinden seni dinleyenler vardır; fakat biz onu anlamalarına engel olmak için kalblerinin üstüne kılıflar, kulaklarının içine de ağırlık koyduk. (Onlar) her mu’cizeyi görseler de yine ona inanmazlar. Hattâ sana geldiklerinde seninle tartışırlar; o kâfirler: \"Bu, eskilerin masallarından başka bir şey değildir\" derler."},{"n":26,"t":"Onlar hem (insanları) ondan menederler, hem de kendileri ondan uzak dururlar. Böylece yalnız kendilerini mahvediyorlar ama farkında değiller!"},{"n":27,"t":"Onların, ateşin başında durdurulmuş iken: \"Âh ne olurdu keşke biz (dünyâya) geri döndürülseydik de Rabbimizin âyetlerini yalanlamasaydık, inananlardan olsaydık!\" dediklerini bir görsen!"},{"n":28,"t":"Hayır, daha önce gizlemekte oldukları, onlara göründü. Geri gönderilselerdi yine men’olundukları şeyi yapmağa dönerlerdi, çünkü onlar yalancılardır."},{"n":29,"t":"Dediler ki: \"dünyâ hayâtımızdan başka bir hayât yoktur. Biz diriltilecek değiliz.\""},{"n":30,"t":"Onları Rablerinin huzûrunda durdurulmuş iken bir görsen: (Allâh) \"Bu gerçek değil miymiş?\" dedi. Dediler ki, \"Evet Rabbimiz hakkı için gerçektir!\" \"Öyle ise inkâr ettiğinizden dolayı azâbı tadın!\" dedi."},{"n":31,"t":"Allâh’ın huzûruna çıkmayı yalanlayanlar, gerçekten ziyana uğradı(lar). Nihâyet kendilerine ansızın o sâ’at gelip çatınca, günâhlarını sırtlarına yüklenmiş olarak: \"Hayâtta (iyi işler yapmaktan) geri kalıp günâh işlememizden ötürü vah bize!\" dediler. Bakın, ne kötü şeyler yüklenip taşıyorlar!"},{"n":32,"t":"Dünyâ hayâtı sadece bir oyun ve eğlenceden başka bir şey değildir. Korunanlar için elbette âhiret yurdu daha iyidir. Düşünmüyor musunuz?"},{"n":33,"t":"Biliyoruz, onların dedikleri seni üzüyor, gerçekte onlar seni yalanlamıyorlar, fakat o zâlimler bile bile Allâh’ın âyetlerini inkâr ediyorlar."},{"n":34,"t":"Senden önce de elçiler yalanlanmıştı. Yalanlanmalarına ve eziyet edilmelerine sabrettiler, nihâyet onlara yardımımız yetişti. Allâh’ın kelimelerini değiştirebilecek kimse yoktur. Sana da elçilerin haberinden bir parça gelmiştir."},{"n":35,"t":"Eğer onların yüz çevirmesi sana ağır geldiyse, haydi (yapabilirsen) yerin içine (inebileceğin) bir delik, ya da göğe (çıkabileceğin) bir merdiven ara ki onlara bir mu’cize getiresin! Allâh, dileseydi, elbette onları hidâyet üzerinde toplardı, o halde câhillerden olma!"},{"n":36,"t":"Ancak işitenler (çağrıya) gelir, ölülere gelince Allâh onları diriltir, sonra O’na döndürülürler."},{"n":37,"t":"Dediler ki: \"Ona Rabbinden bir mu’cize indirilmeli değil miydi?\" De ki: \"Şüphesiz Allâh, bir mu’cize indirmeğe kâdirdir, fakat çokları bilmezler.\""},{"n":38,"t":"Yeryüzünde yürüyen hiçbir hayvan ve iki kanadiyle uçan hiçbir kuş yoktur ki, (onlar da) sizin gibi birer ümmet olmasınlar. Biz Kitapta hiçbir şeyi eksik bırakmamışızdır. Sonra (onlar), Rableri(nin huzûru)na toplanacaklardır."},{"n":39,"t":"Bizim âyetlerimizi yalanlayanlar, karanlıklar içinde kalmış sağır ve dilsizlerdir. Allâh dilediği kimseyi şaşırtır, dilediği kimseyi de doğru yola koyar."},{"n":40,"t":"De ki: \"Düşündünüz mü kendinizi hiç? Size Allâh’ın azâbı gelse, ya da o (Duruşma) sâ’at(i) gelse, Allah’tan başkasına mı yalvarırsınız? Doğru (sözlü) iseniz (söyleyin)."},{"n":41,"t":"\"Hayır, yalnız O’na yalvarırsınız; O da dilerse (kaldırmasını) istediğiniz belâyı kaldırır ve o zaman ortak koştuğunuz şeyleri unutursunuz.\""},{"n":42,"t":"Senden önce de ümmetlere elçiler gönderdik. (İnkârlarından dönüp bize) yalvarsınlar diye onları darlık ve sıkıntı ile yakalayıp cezâlandırmıştık."},{"n":43,"t":"Hiç olmazsa kendilerine böyle baskınımız geldiği zaman yalvarsalardı! Fakat kalbleri katılaştı ve şeytân da onlara yaptıklarını süslü gösterdi."},{"n":44,"t":"Kendileri yapılan uyarıları unutunca, üzerlerine her şeyin kapılarını açıverdik; kendilerine verilenle sevince daldıkları sırada da ansızın onları yakaladık, birden bire bütün umutlarını yitirdiler."},{"n":45,"t":"Böylece haksızlık eden milletin ardı kesildi. Âlemlerin Rabbi Allah’a hamdolsun!"},{"n":46,"t":"De ki: \"Söyleyin bana, eğer Allâh işitme(duyu)nuzu ve gözlerinizi alsa, kalblerinizin üstüne de mühür vursa, Allah’tan başka bun(lar)ı size getir(ip ver)ecek tanrı kimdir?\" Bak, nasıl âyetleri döndürüp türlü türlü açıklıyoruz, sonra yine onlar yüz çeviriyorlar?"},{"n":47,"t":"De ki: \"Düşündünüz mü kendinizi hiç? Size Allâh’ın azâbı ansızın, ya da açıkça gelse, zâlim toplumdan başkası mı helâk edilir?\""},{"n":48,"t":"Biz elçileri sadece müjdeciler ve uyarıcılar olarak göndeririz. Kim inanır ve uslanırsa onlara korku yoktur ve onlar üzülmeyeceklerdir."},{"n":49,"t":"Âyetlerimizi yalanlayanlara da yaptıkları fenalık yüzünden azâb dokunacaktır."},{"n":50,"t":"De ki: \"Ben size, Allâh’ın hazineleri yanımdadır, demiyorum. Gaybı da bilmem. Size ’Ben meleğim’ de demiyorum. Ben sadece bana vahyolunana uyuyorum.\" De ki: \"Körle, gören bir olur mu? Düşünmüyor musunuz?\""},{"n":51,"t":"Rablerin(in huzûru)na toplanacakların(a inanıp bu durum)dan korkanları onunla uyar ki; kendilerinin, O’ndan başka ne dostları, ne de destekçileri yoktur. (Onları uyar), belki korunurlar."},{"n":52,"t":"Sabah akşam Rablerinin rızâsını isteyerek, O’na yalvaranları kovma. Onların hesabından sana bir sorumluluk, senin hesabından da onlara bir sorumluluk yok ki, onları kovup da zâlimlerden olasın!"},{"n":53,"t":"Böylece biz onların kimini kimi ile denedik ki: \"Allâh, aramızdan şunlara mı lutfu lâyık gördü?\" desinler. Allâh, şükredenleri daha iyi bilmez mi?"},{"n":54,"t":"Âyetlerimize inananlar, sana geldikleri zaman: \"Size selâm olsun, de, Rabbiniz, kendi üzerine rahmeti yazmış(yaratıklarına acımayı prensip edinmiş)tir. Sizden kim, bilmeyerek bir kötülük yapar da sonra ardından tevbe eder, uslanırsa muhakkak ki O, bağışlayandır, esirgeyendir.\""},{"n":55,"t":"Böylece âyetleri (döne, döne) açıklıyoruz ki, suçluların yolu belli olsun."},{"n":56,"t":"De ki: \"Ben, Allah’tan başka yalvardıklarınıza tapmaktan men’olundum.\" De ki: \"Ben sizin keyiflerinize uymam, çünkü o takdirde sapıtmış ve yola gelenlerden olmamış olurum.\""},{"n":57,"t":"De ki: \"Ben, Rabbimden (gelen) açık bir delil üzerindeyim. Siz ise onu yalanladınız. Acele istediğiniz (azâb) da benim yanımda değildir. Hüküm vermek, yalnız Allah’a âittir. (O) gerçeği anlatır ve O, (dâvâyı çözüp) ayırdedenlerin en iyisidir.\""},{"n":58,"t":"De ki: \"Eğer acele istediğiniz şey benim yanımda olsaydı, elbette benimle sizin aranızda iş, şimdi (çoktan) bitirilmişti.\" Allâh zâlimleri daha iyi bilir."},{"n":59,"t":"Gayb’ın (görünmez bilginin) anahtarları, O’nun yanındadır, onları O’ndan başkası bilmez. (O) karada ve denizde olan herşeyi bilir. Düşen bir yaprak, ki mutlaka onu bilir, yerin karanlıkları içinde gömülen dâne, yaş ve kuru hiçbir şey yoktur ki, apaçık bir Kitapta olmasın."},{"n":60,"t":"O’dur ki, geceleyin sizi öldürür (gibi uyutur), gündüzün ne işlediğinizi bilir; sonra belirlenmiş süre geçirilip tamamlansın diye gündüzün sizi diriltir. Sonra dönüşünüz O’nadır; sonra (O, dünyâda) yaptıklarınızı size haber verecektir."},{"n":61,"t":"O, kulların üstünde tek hâkimdir. Size koruyucu(melek)ler gönderir, nihâyet birinize ölüm gelince elçilerimiz onun canını alırlar, onlar (bu hususta) hiç geri kalmazlar."},{"n":62,"t":"Sonra o(ca)nlar, gerçek Tanrıları olan Allah’a döndü(rülüp götü)rülürler. Doğrusu hüküm, yalnız O’nundur; O hesap görenlerin en çabuğudur."},{"n":63,"t":"De ki: \"Gizli ve açık olarak: ’Bizi bundan kurtarırsa elbette şükredenlerden olacağız!’ diye O’na yalvarıp yakardığınız zaman, karanın ve denizin karanlıklarından sizi kim kurtarıyor?\""},{"n":64,"t":"De ki: \"Ondan ve bütün sıkıntılardan sizi Allâh kurtarıyor, sonra siz yine O’na ortak koşuyorsunuz!?\""},{"n":65,"t":"De ki: \"O, sizin üzerinize üstünüzden, yahut ayaklarınızın altından bir azâb göndermeğe, ya da sizi parti parti birbirinize düşürüp kiminize kiminizin hıncını taddırmağa kâdirdir.\" Bak, anlasınlar diye âyetleri nasıl açıklıyoruz?!"},{"n":66,"t":"O, gerçek iken kavmin onu yalanladı. De ki: \"Ben size vekil değilim!\""},{"n":67,"t":"Her haberin gerçekleşeceği bir zaman vardır. Yakında bilirsiniz."},{"n":68,"t":"Âyetlerimiz hakkında (münasebetsizliğe) dalanları gördüğün zaman, onlar başka bir söze geçinceye kadar onlardan yüz çevir; eğer şeytân sana (bunu) unutturursa hatırladıktan sonra (hemen kalk), o zâlimler topluluğuyla beraber oturma!"},{"n":69,"t":"Korunanlara, o(inanmaya)nların hesabından bir sorumluluk yoktur, ama belki (inanıp) korunurlar diye bir hatırlatmak lâzımdır."},{"n":70,"t":"Bırak o dinlerini oyun, eğlence yerine koyan ve dünyâ hayâtının aldattığı kimseleri de, sen o (Kur’ân) ile (şunu) hatırlat ki, bir kişi, yaptığı işin eline teslim edilmeye görsün, (yoksa) Allah’tan başka onun ne bir dostu, ne de bir yardımcısı olmaz. (Amelinin elinden kurtulmak için) her türlü fidyeyi verse de ondan kabul edilmez. İşte onlar, kazandıklarının eline teslim edilmişlerdir. Onlar için kaynar sudan bir içki ve inkârlarından dolayı da acı bir azâb vardır!"},{"n":71,"t":"De ki: \"Allah’tan başka, bize ne yarar, ne zarar vermeyen şeylere mi yalvaralım? Ve Allâh bizi doğru yola ilettikten sonra, ökçelerimiz üzerinde (eski durumumuza) döndürülüp; şeytânların ayartarak şaşkın bir halde çölde bıraktıkları; arkadaşlarının ise \"Bize gel!\" diye doğru yola çağırdıkları kimse gibi (şaşkın bir duruma) mı düşelim?\" De ki: \"Yol gösterme, ancak Allâh’ın yol göstermesidir. Bize, âlemlerin Rabbine teslim olmamız emredilmiştir.\""},{"n":72,"t":"\"Namazı kılın ve O’ndan korkun (diye emredilmiştir)!\" Varıp huzûruna toplanacağınız O’dur."},{"n":73,"t":"Gökleri ve yeri hak (ve hikmet) ile yaratan O’dur. \"Ol!\" dediği gün, oluverir. Sözü haktır. Sûr’a üfleneceği gün de, mülk O’nundur. Gizliyi ve açığı bilendir. O, hükümdardır, herşeyi haber alandır."},{"n":74,"t":"İbrâhim, babası Âzer’e demişti ki: \"Sen putları tanrılar mı ediniyorsun? Doğrusu ben seni ve kavmini açık bir sapıklık içinde görüyorum.\""},{"n":75,"t":"Böylece biz İbrâhim’e göklerin ve yerin melekûtunu (büyük ve hârikulâde muhteşem varlıklarını) gösteriyorduk ki, kesin inananlardan olsun."},{"n":76,"t":"Üzerine gece basınca (İbrâhim) bir yıldız gördü; \"Budur Rabbim\" dedi. Yıldız batınca: \"Batanları sevmem\", dedi."},{"n":77,"t":"Ay’ı doğarken görünce: \"Budur Rabbim\" dedi. O da batınca: \"Rabbim bana doğru yolu göstermeseydi, elbette sapan topluluktan olurdum.\" dedi."},{"n":78,"t":"Güneşi doğarken görünce: \"Budur Rabbim, bu daha büyük!\" dedi. (O da) batınca dedi ki: \"Ey kavmim, ben sizin (Allah’a) ortak koştuğunuz şeylerden uzağım.\""},{"n":79,"t":"\"Ben yüzümü tamamen, gökleri ve yeri yoktan var edene çevirdim ve artık ben O(na) ortak koşanlardan değilim!\""},{"n":80,"t":"Kavmi onunla tartışmaya girişti. (O onlara) dedi ki: \"Beni doğru yola iletmiş iken Allâh hakkında benimle tartışıyor musunuz? Ben, sizin O’na ortak koştuğunuz şeylerden korkmam. Ancak Rabbimin dilediği olur! Rabbim, bilgice herşeyi kuşatmıştr. Hâlâ öğüt almıyor musunuz?"},{"n":81,"t":"Hem siz, Allâh’ın size, (tanrı oldukları) hakkında hiçbir delil indirmediği şeyleri, O’na ortak koşmaktan korkmuyorsunuz da ben nasıl sizin (O’na) ortak koştuğunuz şeylerden korkarım? Şimdi biliyorsanız (söyleyin), iki topluluktan hangisi (tek Allah’a inananlar mı, yoksa Allah’a ortak koşanlar mı) güvende olmağa daha lâyıktır?"},{"n":82,"t":"İnananlar ve imanlarını bir haksızlıkla bulamayanlar... İşte güven onlarındır ve doğru yolu bulanlar da onlardır."},{"n":83,"t":"İşte bunlar, kavmine karşı İbrâhim’e verdiğimiz hüccet(kanıt)lerimizdir. Dilediğimizi derecelerle yükseltiriz. Şüphesiz Rabbin hüküm ve hikmet sâhibidir, bilendir."},{"n":84,"t":"Biz ona İshak’ı ve (İshâk’ın oğlu) Ya’kûb’u da hediye ettik; hepsine de doğru yolu gösterdik. Nitekim daha önce Nûh’a ve onun soyundan Dâvûd’a, Süleyman’a, Eyyûb’a, Yûsuf’a, Mûsâ’ya ve Hârûn’a da yol göstermiştik. Biz güzel davrananları böyle ödüllendiririz."},{"n":85,"t":"Zekeriyyâ’ya, Yahyâ’ya, Îsâ ve İlyâs’a da (yol göstermiştik). Hepsi iyilerden idi."},{"n":86,"t":"İsmâ’il’e, el-Yesa’a, Yûnus’a ve Lût’a da (yol gösterdik), hepsini âlemlere üstün kıldık."},{"n":87,"t":"Babalarından, çocuklarından ve kardeşlerinden bazılarını da... Onları seçtik ve onları doğru yola ilettik."},{"n":88,"t":"İşte bu, Allâh’ın hidâyetidir, kullarından dilediğini bununla doğru yola iletir. Eğer (onlar Allah’a) ortak koşsalardı, yaptıkları (güzel) şeyler hiç olur, giderdi."},{"n":89,"t":"İşte onlar, kendilerine Kitap, hüküm ve peygamberlik verdiğimiz kimselerdir. Şimdi şunlar, (yani Kureyş kavmi), bunları inkâr ederse, (bilsinler ki) biz, bunları inkâr etmeyecek (koruyacak) bir toplumu, bunlara vekil bırakmışızdır."},{"n":90,"t":"İşte onlar, Allâh’ın hidâyet ettiği kimselerdir. Onların yoluna uy ve de ki: \"Ben ona karşılık sizden bir ücret istemiyorum. O, sadece âlemlere bir öğüttür.\""},{"n":91,"t":"Allâh’ı şânına yaraşır biçimde tanıyamadılar, zira \"Allâh, insana bir şey indirmedi\" dediler. De ki: \"Öyleyse Mûsâ’nın, insanlara nur ve yol gösterici olarak getirdiği, -ki siz onu parça parça kâğıtlar haline getirip gösteriyorsunuz, çoğunu da gizliyorsunuz- ve ne sizin, ne de babalarınızın bilmediği şeylerin size öğretildiği Kitabı kim indirdi?\" \"Alah\" de, sonra bırak onları, daldıkları bataklıkta oynayadursunlar."},{"n":92,"t":"Bu da Anakent(Mekke’y)i ve çevresindeki(kasaba)ları uyarman için sana indirdiğimiz feyz kaynağı ve kendinden önceki (Tanrı Kitabı)nı doğrulayıcı bir Kitaptır. Âhirete inananlar, buna inanırlar ve onlar, namazlarına devam ederler."},{"n":93,"t":"Allah’a karşı yalan uydurandan, ya da kendisine bir şey vahyedilmemiş iken \"Bana vahyolundu\" diyenden ve \"Ben de Allâh’ın indirdiği gibi indireceğim!\" diyenden daha zâlim kim olabilir? O zâlimler ölüm dalgaları içinde, melekler ellerini uzatmış: \"Haydi canlarınızı çıkarın, Allah’a gerçek olmayanı söylemenizden ve O’nun âyetlerine karşı büyüklük taslamanızdan ötürü, bugün alçaklık azâbıyla cezâlandırılacaksınız!\" (derken) onların halini bir görsen!"},{"n":94,"t":"\"Andolsun, sizi ilk kez yarattığımız gibi, yine tek olarak bize geldiniz ve (dünyâda) sizi hayâline daldırdığımız şeyleri arkanızda bıraktınız. Hani, siz(in yaratılışınızda ve ibâdetleriniz)de (bize) ortak olduklarını sandığınız şefâatçilerinizi de yanınızda görmüyoruz. Aranızdaki bağlar kesilmiş ve (şefâ’atçi) sandığınız şeyler sizden kaybolup gitmiştir!\""},{"n":95,"t":"Dâneyi ve çekirdeği yaran, şüphesiz Allah’tır. (O), ölüden diriyi çıkarır, diriden de ölüyü çıkarır. İşte Allâh budur. O halde nasıl (yalnız O’na tapmaktan) çevriliyorsunuz?"},{"n":96,"t":"Karanlığı yarıp sabahı ortaya çıkaran O’dur. Geceyi dinlenme zamanı, güneşi ve ayı (vakitlerin bilinmesi için) birer hesap (ölçüsü) yapmıştır. Bu, o üstün ve bilen(Allâh)ın takdiridir."},{"n":97,"t":"O’dur ki size, karanın ve denizin karanlıklarında, yıldızlardan yararlanıp yol bulma imkânı verdi. Gerçekten biz, bilen bir toplum için âyetleri geniş geniş açıkladık."},{"n":98,"t":"Odur ki sizi bir tek nefisten inşâ etti. Sizin için bir kalış ve bir emânet olarak konuluş yeri ve süresi vardır. Gerçekten biz, anlayan bir toplum için âyetleri geniş geniş açıkladık."},{"n":99,"t":"O’dur ki, size gökten su indirdi. Onunla her çeşit bitkiyi çıkardık, o bitkiden bir filiz çıkardık, ondan da birbiri üzerine binmiş dâneler; hurmanın tomurcuğundan sarkan salkımlar; üzüm bağları; zeytin ve nar (bahçeleri) çıkarıyoruz. (Bunların) kimi birbirine benzer, kimi benzemez. Her birinin meyvesine bakın: Meyve verirken ve olgunlaştığı zaman. Şüphesiz bu size gösterilenlerde, inananlar toplumu için elbette çok ibret vardır."},{"n":100,"t":"(Tuttular) cinleri Allah’a ortak yaptılar. Halbuki onları O yaratmıştır. Bilmeden O’na oğullar ve kızlar icâdettiler. Hâşâ O, onların ileri sürdüğü niteliklerden münezzehtir!"},{"n":101,"t":"(O) gökleri ve yeri yoktan var edendir. O’nun nasıl çocuğu olabilir ki? Kendisinin bir eşi yoktur, herşeyi O yaratmıştır ve O, herşeyi bilendir."},{"n":102,"t":"Rabbiniz Allâh, işte budur. O’ndan başka tanrı yoktur. (O), herşeyin yaratıcısıdır. O’na kulluk edin, O herşeye vekildir."},{"n":103,"t":"Gözler O’nu görmez, O gözleri görür; O latif (gözle görülmez veya lutuf sâhibi), herşeyi haber alandır."},{"n":104,"t":"Doğrusu size Rabbinizden basiretler geldi. Artık kim (gerçeği) görürse yararı kendisine, kim de (gerçeğe karşı) kör olursa zararı kendisinedir. Ben sizin üzerinize bekçi değilim."},{"n":105,"t":"İşte böylece âyetleri döne döne açıklıyoruz ki (onlar sana): \"Sen ders almışsın (bunları bir yerden okumuş, öğrenmişsin)\" desinler ve bilen bir toplum için de onu iyice açıklayalım."},{"n":106,"t":"Rabbinden sana vahyolunana uy; O’ndan başka tanrı yoktur. (O’na) ortak koşanlara da aldırma!"},{"n":107,"t":"Allâh isteseydi, ortak koşmazlardı. Biz seni onların üzerine bekçi yapmadık, sen onlara vekil de değilsin!"},{"n":108,"t":"(Onların) Allah’tan başka yalvardıklarına sövmeyin ki, onlar da bilmeyerek taşkınlıkla Allah’a sövmesinler! Biz, her ümmete yaptıkları işi böyle süslü gösterdik; sonunda dönüşleri Rablerinedir. O, onlara ne yaptıklarını haber verecektir."},{"n":109,"t":"Eğer kendilerine bir mu’cize gelirse ona mutlaka inanacaklarına olanca güçleriyle Allah’a yemin ettiler. De ki: \"Mu’cizeler ancak Allâh’ın yanındadır.\" Hem bilir misiniz o (mu’cize) gelmiş olsa da onlar yine inanmazlar?"},{"n":110,"t":"Gönüllerini ve gözlerini ters çeviririz, ilkin ona inanmadıkları gibi (mu’cizeyi gördükten sonra da inanmazlar) ve bırakırız onları, azgınlıkları içinde bocalayıp dururlar."},{"n":111,"t":"Biz onlara melekleri indirseydik, ölüler kendilerine konuşsaydı ve her şeyi toplayıp karşılarına getirseydik, Allâh dilemedikten sonra yine inanmazlardı; fakat çokları câhillik eder(kaprislerine uyar)lar."},{"n":112,"t":"Böylece biz, her peygambere insan ve cin şeytânlarını düşman yaptık. (Bunlar), aldatmak için birbirlerine yaldızlı sözler fısıldarlar. Rabbin dileseydi onu yapamazlardı. Artık onları, uydurdukları şeylerle baş başa bırak."},{"n":113,"t":"Ki âhirete inanmayanların kalbleri o(nların yaldızlı sözleri)ne kansın, ondan hoşlansınlar ve onlar, işledikleri suçları işlemeğe devam etsinler."},{"n":114,"t":"Allâh, size Kitabı açıklanmış olarak indirmiş iken O’ndan başka bir hakem mi arayayım? Kendilerine Kitap verdiklerimiz, O(Kur’a)nın, gerçekten Rabbin tarafından indirilmiş olduğunu bilirler, hiç kuşkulananlardan olma."},{"n":115,"t":"Rabbinin sözü hem doğruluk, hem de adâlet bakımından tamamlanmıştır. O’nun sözlerini değiştirebilecek hiç kimse yoktur. O, işitendir, bilendir."},{"n":116,"t":"Yeryüzünde bulunan(insan)ların çoğuna uysan, seni Allâh’ın yolundan saptırırlar. Onlar sadece zannediyorlar ve onlar sadece saçmalıyorlar."},{"n":117,"t":"Rabbin, (evet) O, yolundan sapan(lar)ı çok iyi bilir ve O, yolda olan(lar)ı çok iyi bilir."},{"n":118,"t":"O halde Allâh’ın âyetlerine inanıyorsanız, üzerine O’nun adı anılan(hayvan)lardan yeyiniz."},{"n":119,"t":"Üzerine Allâh’ın adı anılmış olanlardan niçin yemeyesiniz? Çaresiz yemek zorunda kaldıklarınız dışında, size harâm kıldığı şeyleri (Allâh) size açıklamıştır. Doğrusu birçokları, bilmeden keyiflerine uyarak halkı şaşırtıyorlar. Muhakkak ki Rabbin, (evet) O, sınırı aşanları çok iyi bilir."},{"n":120,"t":"Günâhın açığını da, gizlisini de bırakın! Günâh kazananlar, yaptıklarının cezâsını çekeceklerdir."},{"n":121,"t":"(Kesilirken) üzerine Allâh’ın adı anılmayan(hayvan)lardan yemeyiniz! Çünkü o(nu yemek), yoldan çıkmadır. Şeytânlar, dostlarına, sizinle mücâdele etmelerini fısıldarlar. Eğer onlara uyarsanız, şüphesiz siz de ortak koşanlar(gibi olur)sunuz."},{"n":122,"t":"Ölü iken kendisini dirilttiğimiz ve kendisine insanlar arasında yürüyebileceği bir ışık verdiğimiz kimse, karanlıklar içinde kalıp ondan hiç çıkamayan kimse gibi olur mu? İşte kâfirlere, yaptıkları (işler), öyle süslü gösterilmiştir."},{"n":123,"t":"Böylece her kentin büyüklerini, oranın suçluları yaptık ki, orada tuzak kursunlar (her kentin ileri gelenlerine, tuzak kurmaları için fırsat verdik). Onlar kendilerinden başkasına tuzak kurmuyorlar, ama farkında değiller."},{"n":124,"t":"Onlara bir âyet gelince: \"Allâh’ın elçilerine verilenin aynı bize de verilmedikçe kat’iyyen inanmayız!\" dediler. Allâh, mesajını koyacağı yeri (elçilik görevini kime vereceğini) bilir. Suç işleyenlere Allâh katında bir aşağılık ve yaptıkları hileye karşı çetin bir azâb erişecektir."},{"n":125,"t":"Allâh kimi doğru yola iletmek isterse onun göğsünü İslâm’a açar, kimi de saptırmak isterse onun göğsünü, (o kimse) göğe çıkıyormuş gibi dar ve tıkanık yapar. Allâh, inanmayanların üstüne işte böyle pislik (sıkıntı) çökertir."},{"n":126,"t":"İşte Rabbinin doğru yolu budur. Biz, öğüt alanlar için âyetleri geniş geniş açıkladık."},{"n":127,"t":"Rableri katında esenlik yurdu onlarındır. Yaptıkları (güzel) işlerden dolayı O, onların dostudur."},{"n":128,"t":"Hepsini bir araya toplayacağı gün: \"Ey cin(şeytân)lar topluluğu, (der), siz insanlarla çok uğraştınız.\" Onların, insan dostları derler ki: \"Rabbimiz, birbirimizden yararlandık ve bize verdiğin sürenin sonuna ulaştık.\" (Allâh da) buyurur ki \"Durağınız ateştir. Allâh’ın, dile(yip affet)mesi hariç, orada ebedi kalacaksınız.\" Şüphesiz Rabbin hüküm ve hikmet sâhibidir, bilendir."},{"n":129,"t":"İşte kazandıkları(günâhları)ndan ötürü zâlimlerin bir kısmını diğer bir kısmının peşine böyle takarız."},{"n":130,"t":"\"Ey cin ve insan topluluğu, içinizden, size âyetlerimi anlatan ve bugününüzle karşılaşacağınıza dair sizi uyaran elçiler gelmedi mi?\" \"Kendi aleyhimize şâhidiz.\" dediler. Dünyâ hayâtı onları aldattı ve kendilerinin kâfir olduklarına şâhidlik ettiler."},{"n":131,"t":"Bu böyledir, çünkü Rabbin, halkı habersiz iken ülkeleri zulüm ile helâk edici değildir."},{"n":132,"t":"Her birinin yaptıkları işlere göre dereceleri vardır. Rabbin, onların yaptıklarından habersiz değildir."},{"n":133,"t":"Rabbin zengin, rahmet sâhibidir. Dilerse sizi götürür, sizi nasıl başka bir topluluğun soyundan yarattı ise, sizden sonra da dilediğini (yaratıp) sizin yerinize getirir."},{"n":134,"t":"Size söylenen uyarı, muhakkak gelecektir, siz onu engelleyemezsiniz."},{"n":135,"t":"De ki: \"Ey kavmim, gücünüz yettiğince yapacağınızı yapın, ben de yapacağımı yapıyorum. Yakında (dünyâ) yurdu(nu)n sonunun kime âidolacağını bileceksiniz. Zâlimler, asla onmazlar!"},{"n":136,"t":"Allâh’ın yarattığı, ekin(ler)den ve hayvanlardan Allah’a pay ayırdılar. Zanlarınca: \"Bu Allah’a, bu da ortaklarımıza\" dediler. Ortakları için ayrılan Allah’a ulaşmıyor, fakat Allâh için ayrılan, ortaklarına ulaşıyor. Ne kötü hüküm veriyorlar!"},{"n":137,"t":"Yine ortakları, müşriklerden çoğuna evlâdlarını öldürmeyi süslü gösterdiler ki (böylece) hem onları mahvetsinler, hem de dinlerini karıştırıp bozsunlar. Allâh dileseydi bunu yapamazlardı. Öyleyse onları, uydurduklarıyle baş başa bırak!"},{"n":138,"t":"Zanlarınca dediler ki: \"Bunlar dokunulmaz hayvanlar ve ekinlerdir. Bunları bizim dilediğimizden başkası yiyemez. Bunlar da sırtı(na binilmesi) yasaklanmış hayvanlar.\" Bir kısım hayvanları da üzerlerine Allâh’ın adını anmaz(dan boğazlar)lar. (Bütün bunları) Allah’a iftirâ ederek (ortaya çıkardılar. Allâh) Onları iftirâlarıyle cezâlandıracaktır."},{"n":139,"t":"Dediler ki: \"Bu hayvanların karınlarında olanlar, yalnız erkeklerimize âittir, kadınlarımıza harâmdır\". Eğer (hayvanın karnındaki yavru) ölü doğarsa, o zaman hepsi onda ortaktır. Bu nitelendirmelerinden dolayı Allâh onların cezâsını verecektir. Çünkü O, hüküm ve hikmet sâhibidir, bilendir."},{"n":140,"t":"Bilgisizlik yüzünden beyinsizce, çocuklarını öldürenler ve Allâh’ın kendilerine verdiği rızkı, Allah’a iftirâ ederek harâm kılanlar muhakkak ki ziyana uğradılar, saptılar, yola gelici de değiller!"},{"n":141,"t":"Çardaklı ve çardaksız (üzüm) bahçeleri, ürünleri çeşit çeşit hurma(ları), ekin(ler)i, zeytinleri, narları -birbirine benzer, benzemez biçimde- yaratan hep O’dur. Her biri meyva verdiği zaman meyvasından yeyin, hasat günü hakkını (sadakasını) verin; fakat israf etmeyin; çünkü O, israf edenleri sevmez!"},{"n":142,"t":"Hayvanlardan da (çeşit çeşit yarattı,) Kimi yük taşır, kiminin tüyünden sergi yapılır. Allâh’ın size verdiği rızıktan yeyin, şeytânın adımlarını izlemeyin (onun peşinden gitmeyin). Zira o, sizin için apaçık bir düşmandır."},{"n":143,"t":"Sekiz çift (hayvan): Koyundan iki, keçiden iki. De ki: \"(Allâh), iki erkeği mi harâm etti, iki dişiyi mi, yoksa iki dişinin Rahimlerinde bulunan(yavru)ları mı? Eğer doğru iseniz bana bilgi ile haber verin.\""},{"n":144,"t":"Ve deveden iki, sığırdan iki. De ki: \"İki erkeği mi harâm etti, iki dişiyi mi, yoksa iki dişinin Rahimlerinde bulunan(yavru)ları mı? Yoksa Allâh’ın size böyle vasiyyet ettiğine şâhidler mi oldunuz?\" (Allâh, böyle tavsiye ederken siz O’nun yanında mıydınız?) Öyle bilmeden insanları saptırmak için Allah’a karşı yalan uydurandan daha zâlim kim olabilir? Allâh o zâlim topluluğu doğru yola iletmez."},{"n":145,"t":"De ki: Bana vahyolunanda, (bu harâm dediklerinizi) yiyen kimse için harâm edilmiş bir şey bulamıyorum. Ancak leş, yahut akıtılmış kan, yahut domuz eti -ki pistir- ya da Alah’tan başkası adına boğazlanmış bir fısk (murdar olmuş hayvan) olursa başka (bunlar harâmdır). Ama kim çaresiz kalırsa, (başkasının hakkına) saldırmamak ve (zorunluluk) sınırı(nı) aşmamak üzere (bunlardan yiyebilir). Çünkü Rabbin bağışlayandır, esirgeyendir."},{"n":146,"t":"yahûdilere bütün tırnaklı(hayvan)ları harâm ettik. Sığır ve koyunun da, yağlarını onlara harâm kıldık, yalnız (hayvanların) sırtlarının, yahut bağırsaklarının taşıdığı, ya da kemiğe karışan yağlarını harâm etmedik. Aşırılıkları yüzünden onları böyle cezâlandırdık. Biz elbette doğru söyleyenleriz."},{"n":147,"t":"Eğer seni yalanladılarsa, de ki: \"Rabbiniz bol rahmet sâhibidir. Fakat O’nun azâbı da suçlu toplumdan geri çevrilmez (gazabı suçluların üzerine bir indi mi, onu kimse geri çeviremez).\""},{"n":148,"t":"(Allah’a) Ortak koşanlar diyecekler ki: \"Allâh isteseydi ne biz ne de babalarımız ortak koşmazdık, hiçbir şeyi de harâm yapmazdık.\" Onlardan önce yalanlayanlar da öyle demişlerdi de nihâyet azâbımızı tadmışlardı. De ki: \"Yanınızda bize çıka(rıp gösterece)ğiniz bir bilgi (yazılı belge) var mı? Siz sadece zanna uyuyorsunuz ve siz sadece saçmalıyorsunuz.\""},{"n":149,"t":"De ki: \"Üstün delil, Allâh’ındır. Allâh dileseydi, elbette hepinizi doğru yola iletirdi.\""},{"n":150,"t":"De ki: \"Haydi Allâh’ın bunu yasakladığına şâhidlik edecek tanrılarınızı getirin.\" Eğer (onlar) şâhidlik ederlerse sen onlarla beraber şâhidlik etme; âyetlerimizi yalanlayanların ve âhirete inanmayanların keyiflerine uyma. (Nasıl uyarsın ki) onlar, Rablerine eş tutmaktadırlar."},{"n":151,"t":"De ki: \"Gelin, Rabbinizin size harâm kıldığı şeyleri okuyayım: O’na hiçbir şeyi ortak koşmayın, ana babaya iyilik edin, fakirlik korkusuyla çocuklarınızı öldürmeyin; sizi de onları da biz besliyoruz. Fuhuşların açığına da, kapalısına da yaklaşmayın ve haksız yere Allâh’ın yasakladığı cana kıymayın! Düşünesiniz diye Allâh size bunları tavsiye etti."},{"n":152,"t":"Yetimin malına yaklaşmayın: yalnız erginlik çağına erişinceye kadar (onun malına) en güzel biçimde (yaklaşabilir, onu uygun tarzda sarfedebilirsiniz); ölçü ve tartıyı tam adâletle (dengeli) yapın. Biz, kişiye gücünün yettiğinden fazlasını teklif etmeyiz. Söylediğiniz zaman da akrabânız da olsa adâlet yapın ve Allah’a verdiğiniz sözü tutun. Hatırlayıp öğüt alasınız diye (Allâh) size bunları tavsiye etti."},{"n":153,"t":"İşte benim doğru yolum budur, ona uyun, (başka) yollara uymayın ki, sizi O’nun yolundan ayırmasın! Korunmanız için (Allâh) size böyle tavsiye etti."},{"n":154,"t":"Sonra iyilik edenlere (ni’metimizi) tamamlamak, her şeyi açıklamak ve yola iletici ve rahmet olmak üzere Mûsâ’ya Kitabı verdik ki, Rablerinin huzûruna varacaklarına inansınlar."},{"n":155,"t":"İşte bu (Kur’ân) da indirdiğimiz mübârek Kitaptır. O’na uyun ve korunun ki size rahmet edilsin!"},{"n":156,"t":"(Onu size indirdik ki) \"Kitap, yalnız bizden önceki iki topluluğa (yahûdilere, hıristiyanlara) indirildi, biz ise onların okumasından habersizdik (o Kitâpları okuyamıyor, dillerini anlayamıyorduk)\" demeyesiniz."},{"n":157,"t":"Yahut: \"Eğer bize Kitap indirilseydi, biz onlardan daha çok doğru yolda olurduk.\" demeyesiniz. İşte size de Rabbinizden açık delil, hidâyet ve rahmet geldi. Allâh’ın âyetlerini yalanlayıp onlardan yüz çevirenden daha zâlim kim olabilir? Âyetlerimizden yüz çevirenleri, yüz çevirmelerinden ötürü, azâbın en kötüsüyle cezâlandıracağız."},{"n":158,"t":"(İnanmak için) ille meleklerin gelmesini, yahut Rabbinin gelmesini ya da Rabbinin bazı âyetlerinin gelmesini mi bekliyorlar? Ama Rabbinin bazı âyetleri geldiği gün, daha önce inanmamış, ya da imanında bir hayır kazanmamış olan kimseye, artık inanması, fayda sağlamaz. De ki: \"Bekleyin, biz de beklemekteyiz.\""},{"n":159,"t":"Dinlerini parça parça edip, grup grup olanlar var ya, senin onlarla hiçbir ilişkin yoktur. Onların işi Allah’a kalmıştır, sonra (Allâh) onlara yaptıklarını haber verecektir."},{"n":160,"t":"Kim iyilik getirirse, ona o(getirdiği)nin on katı vardır. Kim kötülük getirirse, sadece onun dengiyle cezâlandırılır, onlar haksızlığa uğratılmazlar."},{"n":161,"t":"De ki: \"Rabbim beni doğru yola iletti. Dosdoğru dine, Allâh’ı birleyen İbrâhim’in dinine. O, ortak koşanlardan değildi.\""},{"n":162,"t":"De ki: \"Benim namazım, ibâdetim, hayâtım ve ölümüm hep âlemlerin Rabbi Allâh içindir.\""},{"n":163,"t":"\"O’nun ortağı yoktur. Bana böyle emrolundu ve ben müslümanların ilkiyim.\""},{"n":164,"t":"De ki: \"Allâh, herşeyin Rabbi iken ben O’ndan başka Rab mı arayayım? Herkesin kazandığı yalnız kendisine âittir. Kendi (günâh) yükünü taşıyan hiç kimse, bir başkasının (günâh) yükünü taşımaz. Sonra dönüşünüz Rabbinizedir; (O) ayrılığa düştüğünüz gerçeği size haber verecektir.\""},{"n":165,"t":"Sizi yeryüzünün halifeleri yapan, size verdiği şeylerde, sizi denemek için, kiminizi kiminizden derecelerle üstün kılan O’dur. Doğrusu Rabbin, cezâsı çabuk olandır ve O, bağışlayandır, esirgeyendir."}],[{"n":1,"t":"Elif lâm mim sâd."},{"n":2,"t":"(Bu,) Sana indirilen bir Kitaptır. Onunla (insanları) uyarman ve insanlara öğüt (vermen) hususunda göğsünde bir sıkıntı olmasın (hiç kuşkulanma, tasalanma, bu tamamen Allâh tarafındandır. Sen hemen insanları uyar)."},{"n":3,"t":"(Ey insanlar), Rabbinizden size indirilene uyun ve O’ndan başka velilere uymayın. Ne kadar da az öğüt alıyorsunuz!"},{"n":4,"t":"Nice kent(ler)i helâk ettik; gece yatarlarken, yahut gündüz uyurlarken, azâbımız onlara geliverdi."},{"n":5,"t":"Azâbımız onlara geldiğinde \"Biz gerçekten zâlimlermişiz!\" demelerinden başka yalvarıları kalmadı."},{"n":6,"t":"Hem kendilerine elçi gönderilmiş olanlara soracağız, hem de gönderilen elçilere soracağız."},{"n":7,"t":"Ve elbette onlara, olan biten herşeyi bilgi ile anlatacağız, zira biz onlardan uzak değiliz."},{"n":8,"t":"O gün tartı tam doğrudur. Kimin (sevâp) tartıları ağır gelirse, işte onlar kurtulanlardır."},{"n":9,"t":"Kimin (sevâp) tartıları hafif gelirse, işte onlar da âyetlerimize haksızlık etmelerinden ötürü kendilerini ziyana sokanlardır."},{"n":10,"t":"Doğrusu biz sizi yeryüzünde yerleştirdik, orada size geçimlikler verdik; ne kadar da az şükrediyorsunuz!"},{"n":11,"t":"Sizi yarattık, sonra size biçim verdik, sonra da meleklere: \"Âdem’e secde edin!\" dedik; hepsi secde ettiler, yalnız İblis etmedi, o secde edenlerden olmadı."},{"n":12,"t":"(Allâh) buyurdu: \"Sana emrettiğim zaman seni secde etmekten alıkoyan nedir?\" (İblis): \"Ben, dedi, ondan hayırlıyım. Beni ateşten yarattın, onu çamurdan yarattın.\""},{"n":13,"t":"(Allâh) buyurdu: \"Öyle ise oradan in, orada büyüklük taslamak senin haddin değildir. Çık, çünkü sen aşağılıklardansın!\""},{"n":14,"t":"(İblis) dedi: \"(Bari) bana (insanların) tekrar dirilecekleri güne kadar süre ver.\""},{"n":15,"t":"(Allâh) buyurdu: \"Haydi sen süre verilmişlerdensin.\""},{"n":16,"t":"\"Öyle ise, dedi, beni azdırmana karşılık, and içerim ki, ben de onlar(ı saptırmak) için senin doğru yolunun üstüne oturacağım.\""},{"n":17,"t":"\"Sonra (onların) önlerinden, arkalarından, sağlarından, sollarından onlara sokulacağım ve çoklarını şükredenlerden bulmayacaksın!\""},{"n":18,"t":"(Allâh) buyurdu: \"Haydi, sen, yerilmiş ve kovulmuş olarak oradan çık. Andolsun ki onlardan sana kim uyarsa (bilin ki) sizin hepinizden (derleyip) cehennemi dolduracağım (azdıran sizler de, size uyup yoldan çıkan insanlar da cehenneme gireceksiniz)!\""},{"n":19,"t":"(Sonra Allâh, Âdem’e hitâbetti): \"Ey Âdem, sen ve eşin cennette durun, dilediğiniz yerden yeyin; fakat şu ağaca yaklaşmayın, yoksa zâlimlerden olursunuz.\""},{"n":20,"t":"Derken şeytân, onların, kendilerinden gizlenmiş olan çirkin yerlerini kendilerine göstermek için onlara fısıldadı: \"Rabbiniz, başka bir sebepten dolayı değil, sırf ikiniz de birer melek, ya da ebedi kalıcılardan olursunuz diye sizi şu ağaçtan men’etti\" dedi."},{"n":21,"t":"Ve onlara: \"Elbette ben size öğüt verenlerdenim.\" diye de yemin etti."},{"n":22,"t":"Böylece onları aldatarak aşağı sarkıttı, (önceki mevkilerinden indirdi). Ağac(ın meyvasın)ı tadınca çirkin yerleri kendilerine göründü ve cennet yapraklarını üst üste yamayıp üzerlerine örtmeğe başladılar. Rableri onlara ünledi: \"Ben sizi o ağaçtan men’etmedim mi ve şeytân size apaçık düşmandır, demedim mi?\""},{"n":23,"t":"Dediler: \"Rabbimiz, biz kendimize zulmettik, eğer bizi bağışlamaz ve bize acımazsan, muhakkak ziyana uğrayanlardan oluruz!\""},{"n":24,"t":"(Allâh) buyurdu: \"Birbirinize düşman olarak inin, sizin yeryüzünde bir süreye kadar kalıp geçinmeniz gerekmektedir.\""},{"n":25,"t":"\"Orada yaşayacaksınız, orada öleceksiniz ve yine oradan (diriltilip) çıkarılacaksınız!\" dedi."},{"n":26,"t":"Ey Âdem oğulları, size çirkin yerlerinizi örtecek giysi, süslenecek elbise indirdik. Korunma giysisi, en iyisidir. İşte bu(nlar), Allâh’ın âyetlerindendir, belki düşünüp öğüt alırlar."},{"n":27,"t":"Ey Âdem oğulları, şeytân, ana babanızı, çirkin yerlerini onlara göstermek için elbiselerini soyarak cennetten çıkardığı gibi, sizi de (şaşırtıp) bir belâya düşürmesin! Çünkü o ve kabilesi, sizin onları göremeyeceğiniz yerden sizi görürler. Biz şeytânları, inanmayanların dostları yaptık."},{"n":28,"t":"Onlar bir kötülük yaptıkları zaman: \"Babalarımızı bu yolda bulduk, bunu bize Allâh emretti.\" dediler. \"Allâh kötülüğü emretmez, de, Allah’a karşı bilmediğiniz şeyler mi söylüyorsunuz?\""},{"n":29,"t":"De ki: \"Rabbim adâleti emretti. Her mescidde yüzlerinizi O’na doğrultun ve dini yalnız kendisine has kılarak O’na yalvarın (Allah’a hiçbir benzer, eş, ortak koşmadan, gönlünüze başka tanrılar getirmeden sırf Allah’a yönelerek O’na kulluk edin). İlkin sizi yarattığı gibi yine O’na döneceksiniz.\""},{"n":30,"t":"(O) bir topluluğu doğru yola iletti, bir topluluğa da sapıklık hak oldu. Çünkü onlar, şeytânları Allah’tan başka dostlar tuttular ve kendilerinin de doğru yolda olduklarını sanıyorlar."},{"n":31,"t":"Ey Âdem oğulları, her mesci(de gidişiniz)de süs(lü, güzel giysiler)inizi alın; yeyin, için, fakat israf etmeyin; çünkü O, israf edenleri sevmez."},{"n":32,"t":"De ki: \"Allâh’ın, kulları için çıkardığı süsü ve güzel rızıkları kim harâm etti?\" De ki: \"O, dünyâ hayâtında inananlarındır, kıyâmet günü de yalnız onlarındır.\" İşte biz, bilen bir topluluk için âyetleri böyle açıklıyoruz."},{"n":33,"t":"De ki: \"Rabbim, fuhuşları, gerek açığını, gerek kapalısını; günâhı ve haksız yere saldırmayı; hakkında hiçbir delil indirmediği bir şeyi Allah’a ortak koşmayı ve Allâh hakkında bilmediğiniz şeyler söylemenizi kesinlikle harâm etmiştir.\""},{"n":34,"t":"Her ümmetin bir süresi vardır. Süreleri gelince (onlar), ne bir an geri kalırlar, ne de öne geçerler, (tam vaktinde batıp giderler)."},{"n":35,"t":"Ey Âdem oğulları, size kendi içinizden elçiler gelip size âyetlerimi anlattıkarı zaman korunup uslananlara korku yoktur ve onlar üzülmeyeceklerdir."},{"n":36,"t":"Âyetlerimizi yalanlayıp onları kabule tenezzül etmeyenlere gelince, onlar da ateş halkıdır; onlar orada sürekli kalacaklardır."},{"n":37,"t":"Allah’a yalan uyduran, ya da O’nun âyetlerini yalanlayandan daha zâlim kim olabilir? Onlara Kitaptan nasipleri erişir (ezelde kendileri için ne rızık takdir edilmişse onu alır ve kendilerine yazılmış süre kadar yaşarlar); nihâyet (ömürleri tükendiği zaman) melek elçilerimiz gelip canlarını alırken: \"Hani Alah’tan başka yalvardıklarınız nerede?\" dediklerinde: \"Bizden sapıp, kayboldular\" dediler ve kendi aleyhlerine, kendilerinin kâfir olduklarına şâhidlik ettiler."},{"n":38,"t":"(Allâh) buyurdu: \"Sizden önce geçen cin ve insan topluluklariyle beraber ateşin içine girin!\" Her ümmet girdikçe yoldaşına la’net etti. Hepsi birbiri ardından orada toplanınca sonrakiler, öncekiler için dediler ki: \"Rabbimiz, bunlar bizi saptırdılar. Bunlara ateşten bir kat daha azâb ver!\" (Allâh): \"Hepsi için bir kat fazla (azâb) vardır, ama siz bilmezsiniz.\" dedi."},{"n":39,"t":"Öncekiler de sonrakilere dediler ki: \"Sizin bize bir üstünlüğünüz yok. O halde siz de kazandıklarınıza karşılık azâbı tadın!\""},{"n":40,"t":"Bizim âyetlerimizi yalanlayan ve onlara inanmağa tenezzül etmeyenler var ya, işte onlara gök kapıları açılmayacak ve deve, iğne deliğinden geçinceye kadar onlar cennete giremeyeceklerdir! İşte suçluları böyle cezâlandırırız."},{"n":41,"t":"Onlar için cehennemden bir döşek ve üstlerinde de (yine ateşten) örtüler vardır. İşte zâlimleri böyle cezâlandırırız!"},{"n":42,"t":"İnanıp iyi işler yapanlar, -ki hiç kimseye gücünün üstünde bir şey yüklemeyiz- İşte onlar cennet halkıdır, onlar orada ebedi kalacaklardır."},{"n":43,"t":"Göğüslerinden kinden (tasadan) ne varsa hepsini çıkarıp atmışızdır. Altlarından ırmaklar akmaktadır. \"lutfedip bizi buraya getiren Allah’a hamdolsun, Allâh bizi getirmeseydi, biz bunu bulamazdık! Rabbimizin elçileri, gerçeği getirmişler (söyledikleri doğruymuş).\" dediler. Onlara: \"İşte size cennet; yaptıklarınıza karşılık o size mirâs verildi\" diye seslenildi."},{"n":44,"t":"Cennet halkı, ateş halkına seslendi: \"Rabbimizin bize va’dettiğini biz gerçek bulduk. Siz de Rabbinizin size va’dettiğini gerçek buldunuz mu?\" (Onlar da): \"Evet\", dediler ve aralarından bir ünleyici: \"Allâh’ın la’neti zâlimlerin üzerine olsun!\" diye ünledi."},{"n":45,"t":"Onlar ki Allâh’ın yolundan menedip, onu eğriltmek isterler, âhireti de inkâr ederlerdi."},{"n":46,"t":"İki taraf arasında bir perde ve A’raf üzerinde de hepsini (hem cennetlikleri hem de cehennemlikleri, yüzlerindeki) işâretleriyle tanıyan erkekler vardır. (Bunlar), henüz cennete girmemiş olan, fakat girmeyi bekleyen, cennet halkına: \"selâm size!\" diye seslendiler."},{"n":47,"t":"Gözleri ateş halkı tarafına çevrildiği zaman da; \"Rabbimiz, bizi şu zâlim toplulukla beraber bulundurma!\" dediler."},{"n":48,"t":"A’raf halkı, yüzlerindeki işâretleriyle tanıdıkları birtakım adamlara da ünleyerek dediler ki: \"Ne topluluğunuz, ne de büyüklük taslamanız, size hiçbir yarar sağlamadı.\""},{"n":49,"t":"\"Allâh onları hiçbir rahmete erdirmeyecek, diye yemin ettiğiniz kimseler bunlar mıydı?\" (Cennetliklere dönerek): \"Girin cennete, artık size ne korku vardır, ne de siz üzüleceksiniz!\" dediler."},{"n":50,"t":"Ateş halkı, cennet halkına: \"Suyunuzdan veya Allâh’ın size verdiği rızıktan biraz da bizim üzerimize akıtın (ne olur)!\" diye seslendiler. (Onlar da) dediler ki; \"Allâh, bu ikisini kâfirlere harâm etmiştir.\""},{"n":51,"t":"Onlar ki dinlerini bir eğlence ve oyun yerine koydular ve dünyâ hayâtı, kendilerini aldattı. Onlar, bu günleriyle karşılaşacaklarını nasıl unuttular ve âyetlerimizi bile bile nasıl inkâr ediyor idilerse, biz de bugün onları öyle unuturuz!."},{"n":52,"t":"Gerçekten onlara, bilgiye göre açıkladığımız, inanan bir toplum için yol gösterici ve rahmet olan bir kitap getirdik."},{"n":53,"t":"İlle onun te’vilini mi gözetiyorlar? Onun te’vili geldiği (haber verdiği şeyler ortaya çıktığı) gün, önceden onu unutmuş olanlar derler ki: \"Doğrusu Rabbimizin elçileri gerçeği getirmiş. Şimdi bizim şefâ’atçilerimiz var mı ki bize şefâ’at etsinler, yahut tekrar geri döndürül(üp dünyâya gönderil)memiz mümkün mü ki, (orada eski) yaptıklarımızdan başkasını yapalım?\" Onlar, kendilerini ziyana soktular ve uydurdukları şeyler, kendilerinden saptı (kaybolup gitti)."},{"n":54,"t":"Rabbiniz o Allah’tır ki; gökleri ve yeri altı günde yarattı, sonra Arşa istivâ etti (tahta kuruldu. O), geceyi, durmadan onu kovalayan gündüzün üzerine bürüyüp örter. Güneşi, ayı ve yıldızları buyruğuna boyun eğmiş vaziyette (yaratan O’dur). İyi bilin ki, yaratma ve emir O’nundur. Âlemlerin Rabbi Allâh, ne uludur!"},{"n":55,"t":"Rabbinize yalvararak ve gizlice du’â edin, çünkü O, haddi aşanları sevmez."},{"n":56,"t":"Yeryüzü düzeltildikten sonra onda bozgunculuk yapmayın, korkarak ve umarak O’na du’â edin. Muhakkak ki Allâh’ın rahmeti, iyilik edenlere yakındır."},{"n":57,"t":"O ki rüzgârları rahmetinin önünde müjdeci gönderir. Nihâyet onlar, ağır ağır bulutları yüklenince, onu ölü bir ülkeye yollarız; onunla su indirir ve türlü türlü meyvalar çıkarırız. İşte ölüleri de böyle çıkaracağız. Herhalde bundan ibret alırsınız."},{"n":58,"t":"Güzel olan ülkenin bitkisi, Rabbinin izniyle çıkar; kötü olandan ise yararsız bitkiden başka bir şey çıkmaz. İşte biz, şükreden bir toplum için âyetleri böyle döndürüp (tekrar tekrar) açıklarız."},{"n":59,"t":"Andolsun Nûh’u kavmine gönderdik: \"Ey kavmim, dedi, Allah’a kulluk edin, sizin O’ndan başka tanrınız yoktur. Doğrusu ben, size büyük bir günün azâbın(ın inmesin)den korkuyorum.\""},{"n":60,"t":"Kavminden ileri gelenler dediler ki: \"Biz seni açık bir sapıklık içinde görüyoruz!\""},{"n":61,"t":"Dedi ki: \"Ey kavmim, bende bir sapıklık yok, ben âlemlerin Rabbi tarafından gönderilmiş bir elçiyim.\""},{"n":62,"t":"\"Size Rabbimin mesajlarını duyuruyorum, size öğüt veriyorum ve Allâh tarafından, sizin bilmediğiniz şeyleri biliyorum.\""},{"n":63,"t":"\"Korunup da merhamete uğramanız için, içinizden sizi uyaracak bir adam aracılığı ile bir Zikir (sizi ikaz eden bir Kitap, size şan ve şeref verecek bir kanun) gelmesine şaştınız mı?\""},{"n":64,"t":"O’nu yalanladılar, biz de O’nunla berebar gemide bulunanları kurtardık, âyetlerimizi yalanlayanları boğduk! Çünkü onlar kör bir kavim idiler."},{"n":65,"t":"Âd(kavmin)e de kardeşleri Hûd’u (gönderdik): \"Ey kavmim, Allah’a kulluk edin, sizin O’dan başka tanrınız yoktur. (O’na karşı gelmekten) sakınmaz mısınız?\" dedi."},{"n":66,"t":"Kavminden ileri gelen inkârcılar dediler ki: \"Biz seni bir beyinsizlik içinde görüyoruz ve biz seni yalancılardan sanıyoruz!\""},{"n":67,"t":"\"Ey kavmim, bende beyinsizlik yok, ben âlemlerin Rabbi tarafından gönderilmiş bir elçiyim.\" dedi."},{"n":68,"t":"\"Size Rabbimin mesajlarını duyuruyorum ve ben sizin için güvenilir bir öğütçüyüm.\""},{"n":69,"t":"\"Sizi uyarması için içinizden bir adam aracılığı ile Rabbinizden size bir Zikir gelmesine şaştınız mı? Düşünün ki (Allâh) sizi, Nûh kavminden sonra, onların yerine hâkimler yaptı. Üstelik, yaratılışta, size irilik verdi (sizi daha iri yapılı yarattı). Allâh’ın ni’metlerini hatırlayın ki başarıya eresiniz.\""},{"n":70,"t":"Dediler ki; \"Ya, demek sen, tek Allah’a kulluk edelim ve atalarımızın taptıklarını bırakalım diye mi bize geldin? Eğer doğrulardan isen bizi tehdid ettiğin(o azâb)ı bize getir!\""},{"n":71,"t":"Dedi ki: \"Artık size Rabbinizden bir rics (pislik) ve gazab inmiştir. Allâh’ın, kendileri için hiçbir delil indirmediği (ve hiçbir güç vermediği), sadece sizin ve atalarınızın taktığı (boş) isimler hakkında mı benimle tartışıyorsunuz? Bekleyin öyle ise, ben de sizinle beraber bekleyenlerdenim!\""},{"n":72,"t":"O’nu ve O’nunla beraber olanları, bizden bir rahmetle kurtardık, âyetlerimizi yalanlayanların ve inanmayacak olanların ardını kestik."},{"n":73,"t":"Semûd(kavmin)e de kardeşleri Sâlih’i (gönderdik): \"Ey kavmim dedi, Allah’a kulluk edin, sizin O’ndan başka tanrınız yoktur. Size Rabbinizden açık delil geldi. İşte şu, Allâh’ın devesi, size bir mu’cizedir; bırakın onu Allâh’ın arzından yesin (içsin), sakın ona bir kötülük etmeyin, yoksa sizi acı bir azâb yakalar.\""},{"n":74,"t":"\"Düşünün ki (Allâh), Âd’dan sonra sizi hükümdarlar yaptı ve yeryüzünde sizi yerleştirdi: Onun düzlüklerinde saraylar ediniyorsunuz, dağlarını yontup evler yapıyorsunuz, artık Allâh’ın ni’metlerini hatırlayın da yeryüzünde bozgunculuk yapıp karışıklık çıkarmayın."},{"n":75,"t":"Kavminden büyüklük taslayan ileri gelenler, içlerinden zayıf görülen inananlara: \"Siz, dediler, Sâlih’in, gerçekten Rabbi tarafından gönderildiğini biliyor musunuz?\" (Onlar da): \"(Evet), doğrusu biz onunla gönderilene inananlarız!\" dediler."},{"n":76,"t":"Büyüklük taslayanlar: \"Biz, sizin inandığınızı inkâr edenleriz!\" dediler."},{"n":77,"t":"Derken dişi deveyi boğazladılar ve Rablerinin buyruğu dışına çıktılar; \"Ey Sâlih, eğer hakikaten elçilerdensen, bizi tehdid ettiğin (azâb)ı bize getir!\" dediler."},{"n":78,"t":"Bunun üzerine hemen onları, o sarsıntı yakaladı, yurtlarında diz üstü çökekaldılar."},{"n":79,"t":"(Sâlih), onlardan öteye döndü de: \"Ey kavmim, ben size Rabbimin mesajlarını duyurdum ve size öğüt verdim; fakat siz öğüt verenleri sevmiyorsunuz!\" dedi."},{"n":80,"t":"Lût’u da (gönderdik). Kavmine dedi ki: \"Siz, sizden önce dünyâlarda hiç kimsenin yapmadığı fuhşu mu yapıyorsunuz?\""},{"n":81,"t":"\"Siz, kadınları bırakıp şehvetle erkeklere gidiyorsunuz ha! Doğrusu siz, israfçı (aşırı) bir kavimsiniz!\""},{"n":82,"t":"Kavminin cevabı: \"Onları (şu Lût taraftarlarını) kentinizden çıkarın, çünkü onlar, fazla temizlenen insanlarmış!\" demelerinden başka olmadı."},{"n":83,"t":"Biz de onu ve âilesini kurtardık, yalnız karısı geride kalanlardan oldu."},{"n":84,"t":"Ve üzerlerine bir (taş) yağmur(u) yağdırdık; bak, işte suçluların sonu nasıl oldu!"},{"n":85,"t":"Medyen’e de kardeşleri Şuayb’i (gönderdik): \"Ey kavmim, dedi, Allah’a kulluk edin, sizin O’ndan başka tanrınız yoktur. Size Rabbinizden açık bir delil geldi. Ölçüyü ve tartıyı tam yapın, insanların eşyalarını eksik vermeyin, düzeltildikten sonra yeryüzünde bozgunculuk yapmayın; eğer inananlar iseniz, böylesi sizin için daha iyidir!\""},{"n":86,"t":"\"Ve her yolun başına oturup da tehdid ederek inananları Allâh yolundan çevirmeğe ve o(Hak yolu)nu eğriltmeğe çalışmayın; düşünün siz az idiniz, O sizi çoğalttı ve bakın, bozguncuların sonu nasıl oldu!\""},{"n":87,"t":"\"Eğer içinizden bir kısmı benimle gönderilene inanmış, bir kısmı da inanmamış ise, Allâh aramızda hükmedinceye kadar sabredin; O, hükmedenlerin en iyisidir!\""},{"n":88,"t":"Kavminden büyüklük taslayan ileri gelenler dediler ki: \"Ey Şu’ayb, mutlaka seni ve seninle beraber inananları kentimizden çıkarırız, ya da dinimize dönersiniz!\" Dedi ki: \"İstemesek de mi (bizi yurdumuzdan çıkaracak veya dinimizden döndüreceksiniz)?"},{"n":89,"t":"Allâh, bizi sizin dininizden kurtardıktan sonra eğer tekrar ona dönersek, Allâh’ın üzerine yalan atmış oluruz. Rabbimiz Allâh, dilemedikten sonra o(sizin dediğiniz di)ne dönmemiz, bizim için olur şey değildir. Rabbimiz, bilgice her şeyi kuşatmıştır. Biz Allah’a dayanmışız. (Ey) Rabbimiz, bizimle kavmimizin arasın(daki iş)i gerçekle aç(ığa çıkar). Muhakkak ki sen (gerçekleri) aç(ığa çıkar)anlanın en iyisisin!\""},{"n":90,"t":"Kavminden inkâr eden ileri gelenler dediler ki: \"Eğer Şu’ayb’e uyarsanız muhakkak siz ziyana uğrarsınız!\""},{"n":91,"t":"Derken o müthiş sarsıntı onları yakalayıverdi, yurtlarında diz üstü çökekaldılar."},{"n":92,"t":"Şu’ayb’i yalanlayanlar, sanki yurtlarında hiç oturmamış gibi oldular. Şu’ayb’i yalanlayanlar... işte ziyana uğrayanlar, onlar oldular."},{"n":93,"t":"(Şu’ayb), onlardan öteye döndü de: \"Ey kavmim dedi, ben size Rabbimin mesajlarını duyurdum ve size öğüt verdim, artık kâfir bir kavme nasıl acırım?\""},{"n":94,"t":"Biz hangi ülkeye bir peygamber gönderdiysek, onun halkını -yalvarıp yakarsınlar diye- mutlaka yoksulluk ve darlıkla sıkmışızdır."},{"n":95,"t":"Sonra kötülüğü değiştirip yerine iyilik getirdik de (insanlar) çoğaldılar ve: \"Atalarımıza da darlık ve sevinç dokunmuştu (onlar da üzüntülü ve sevinçli günler geçirmişlerdi).\" dediler (de olaylardan ibret alıp şükretmediler). Biz de onları, hiç farkında olmadıkları bir sırada ansızın yakaladık."},{"n":96,"t":"(O) ülkelerin halkı inanıp (kötülüklerden) korunsalardı, elbette üzerlerine gökten ve yerden bolluklar açardık; fakat yalanladılar, biz de onları kazandıklarıyle yakaladık."},{"n":97,"t":"Peki (o) ülkelerin halkı, geceleyin uyurlarken azâbımızın kendilerine gelmeyeceğinden emin midirler?"},{"n":98,"t":"Ya da (o) ülkelerin halkı, kuşluk vakti eğlenirlerken azâbımızın onlara gelmeyeceğinden emin midirler?"},{"n":99,"t":"Allâh’ın tuzağından (kurtulacaklarına) emin mi oldular? Ziyana uğrayan topluluktan başkası, Allâh’ın tuzağın(a yakalanmayacağın)dan emin olamaz."},{"n":100,"t":"(Geçmiştekilerin başlarına gelenler), sâhiplerinden sonra şu toprağa vâris olanları yola getirmedi mi (hâlâ anlamadılar mı) ki biz dilesek, kendilerini de günâhlarıyle cezâlandırırız ve kalblerini mühürleriz, artık hiç işitmezler."},{"n":101,"t":"İşte o ülkeler; sana onların haberlerinden bir kısmını anlatıyoruz. Andolsun, elçileri onlara açık deliller getirmişlerdi. Fakat önceden yalanladıklarından ötürü, inanmak istemediler. İşte Allâh, kâfirlerin kalblerini böyle mühürler."},{"n":102,"t":"Onların çoklarını yoldan çıkmış bulduk ama, çoklarında sözde durma diye bir şey bulmadık."},{"n":103,"t":"Onlardan sonra Mûsâ’yı âyetlerimizle Fir’avn’a ve onun ileri gelen adamlarına gönderdik, âyetlerimize haksızlık ettiler; fakat bak, bozguncuların sonu nasıl oldu!"},{"n":104,"t":"Mûsâ dedi ki: \"Ey Fir’avn, ben âlemlerin Rabbi tarafından gönderilmiş bir elçiyim.\""},{"n":105,"t":"\"Allah’a karşı gerçekten başkasını söylememek, benim üzerime borçtur. Size Rabbinizden açık bir delil getirdim, artık İsrâil oğullarını benimle gönder!\""},{"n":106,"t":"(Fir’avn) dedi. \"Eğer bir âyet (mu’cize) getirmiş isen, hakikaten doğru söylüyorsan göster onu bakalım!\""},{"n":107,"t":"Bunun üzerine (Mûsâ), asâsını attı, birden o, açıkça bir ejderha (oluverdi)."},{"n":108,"t":"Ve elini (böğründen) çıkardı, birden o, bakanlar için, bembeyaz parlayan bir şey oldu."},{"n":109,"t":"Fir’avn kavminden ileri gelen bir topluluk dediler ki: \"Bu, çok bilgili bir büyücüdür!\""},{"n":110,"t":"\"Sizi yurdunuzdan çıkarmak istiyor, ne buyurursunuz?\""},{"n":111,"t":"\"Onu da kardeşini de beklet, dediler, şehirlere toplayıcılar yolla.\""},{"n":112,"t":"\"Bütün bilgili büyücüleri (toplayıp) sana getirsinler.\""},{"n":113,"t":"Büyücüler Fir’avn’a gelip: \"Eğer üstün gelen biz olursak, elbet bize bir mükâfât var, değil mi?\" dediler."},{"n":114,"t":"(Fir’avn): \"Evet, dedi, hem de siz (benim) yakınlar(ım)dan(olacak)sınız!\""},{"n":115,"t":"Dediler ki \"Ey Mûsâ, sen mi (önce hünerini ortaya) atacaksın, yoksa (önce) atanlar biz mi olalım?\""},{"n":116,"t":"\"Siz atın\" dedi. (Hünerlerini ortaya) atınca, insanların gözlerini büyülediler, onları ürküttüler ve büyük bir büyü (ortaya) getirdiler."},{"n":117,"t":"Biz de Mûsâ’ya: \"Asânı at!\" diye vahyettik. Bir de baktılar ki o, onların uydurduklarını yakalayıp yutuyor. (Mûsâ’nın ejderha olan değneği, büyücülerin büyülerini yutup yok etmişti)."},{"n":118,"t":"Gerçek ortaya çıktı ve onların bütün yaptıkları bâtıl oldu."},{"n":119,"t":"Orada yenildiler, küçük düştüler."},{"n":120,"t":"Ve büyücüler secdeye kapandılar:"},{"n":121,"t":"\"Âlemlerin Rabbine inandık!\" dediler."},{"n":122,"t":"\"Mûsâ ve Hârûn’un Rabbine!\""},{"n":123,"t":"Fir’avn: \"Ben size izin vermeden ona inandınız mı?\" dedi. \"Bu, bir tuzaktır, şehirde bu tuzağı kurdunuz ki, halkını oradan çıkarasınız, ama yakında (başınıza gelecekleri) bileceksiniz!\""},{"n":124,"t":"\"Elbette ellerinizi ve ayaklarınızı çaprazlama keseceğim, sonra hepinizi (hurma dallarına) asacağım!\""},{"n":125,"t":"Dediler ki: \"Biz zaten Rabbimize döneceğiz!\""},{"n":126,"t":"\"Rabbimizin, bize gelmiş olan âyetlerine inandığımız için bizden öc alıyorsun. (Ey) Rabbimiz, üzerimize sabır boşalt ve bizi müslümanlar olarak öldür!\""},{"n":127,"t":"Fir’avn kavminden ileri gelen bir topluluk dedi ki: \"Mûsâ’yı ve kavmini bırakıyorsun ki, seni ve tanrılarını terk edip yeryüzünde bozgunculuk mu yapsınlar?\" (Fir’avn): \"Biz onların oğullarını öldüreceğiz, kadınlarını sağ bırakacağız. Biz dâimâ onların üstünde eziciler olacağız!\" dedi."},{"n":128,"t":"Mûsâ, kavmine; \"Allah’tan yardım isteyin, sabredin!\" dedi; yeryüzü Allâh’ındır, onu kullarından dilediğine verir. Sonuç, korunanlarındır!\""},{"n":129,"t":"\"(Ey Mûsâ), sen bize gelmezden önce de, sen bize geldikten sonra da bize işkence edildi.\" dediler. (Mûsâ) dedi: \"Umulur ki Rabbiniz düşmanınızı yok eder ve onların yerine sizi yeryüzüne hâkim kılar da nasıl hareket edeceğinize bakar.\""},{"n":130,"t":"Andolsun biz, Fir’avn âilesini tuttuk, öğüt alsınlar diye yıllarca kıtlıkla ve ürünleri azaltmakla sıktık."},{"n":131,"t":"Onlara bir iyilik geldiği zaman: \"Bu, bizimdir (kendi becerimizle bunu elde ettik)\" derler; kendilerine bir kötülük ulaşırsa, Mûsâ ve onunla beraber olanları uğursuz sayarlar(onların yüzünden belâya uğradıklarını sanırlar)dı. İyi bilinki, onların uğursuzluğu Allâh katındadır, fakat çokları bilmezler."},{"n":132,"t":"Ve dediler ki: \"bizi büyülemek için ne kadar mu’cize getirirsen getir, biz sana inanacak değiliz!\""},{"n":133,"t":"Biz de onların üzerine ayrı ayrı mu’cizeler olarak tûfân, çekirge, kımıl (haşerât), kurbağalar ve kan gönderdik; ama yine büyüklük tasladılar ve suçlu bir topluluk oldular."},{"n":134,"t":"Üzerlerine azâb çökünce: \"Ey Mûsâ, dediler, sana verdiği söz uyarınca bizim için Rabbine du’â et; eğer bizden azâbı kaldırırsan, muhakkak sana inanacağız ve mutlaka İsrâil oğullarını seninle beraber göndereceğiz!\""},{"n":135,"t":"Biz onlardan, geçirecekleri bir süreye kadar azâbı kaldırınca, hemen yeminlerini bozmağa başladılar."},{"n":136,"t":"Biz de onlardan öc aldık, onları yemm(su)da boğduk! Çünkü onlar, âyetlerimizi yalanlamışlardı ve onları umursamaz olmuşlardı."},{"n":137,"t":"Hor görülüp ezilmekte olan milleti de içini bereketlerle donattığımız yerin, doğularına ve batılarına mirâsçı kıldık. Rabbinin İsrâil oğullarına verdiği güzel söz, sabretmeleri yüzünden tam yerine geldi. Fir’avn’ın ve kavminin yapageldiği şeyleri ve yükseltmekte oldukları sarayları (ve bahçeleri) de yıktık."},{"n":138,"t":"İsrâil oğullarını denizden geçirdik, kendilerine mahsus birtakım putlara tapan bir kavme rastladılar: \"Ey Mûsâ, dediler, (bak) bunların nasıl tanrıları var, bize de öyle bir tanrı yap!\" (Mûsâ) dedi: \"Siz, gerçekten câhil bir toplumsunuz.\""},{"n":139,"t":"\"Şunların içinde bulundukları (din) yıkılmıştır ve yaptıkları şeyler boşa çıkmıştır.\""},{"n":140,"t":"\"Allâh, sizi âlemlere üstün yapmış iken size Allah’tan başka bir tanrı mı arayayım?\" dedi."},{"n":141,"t":"(Ey İsrâiloğulları), hatırlayın o zamanı ki biz sizi Fir’avn âilesinden kurtarmıştık. Onlar size azâbın en kötüsünü yapıyorlardı: \"Oğullarınızı öldürüyor, kadınlarınızı sağ bırakıyorlardı. Bunda, size Rabbiniz tarafından büyük bir imtihan vardı."},{"n":142,"t":"Mûsâ ile otuz gece (bana ibâdet etmesi için) sözleştik ve buna on gece daha kattık. Böylece Rabbinin tayin ettiği vakit, kırk geceye tamamlandı. Mûsâ, kardeşi Hârûn’a dedi ki: \"Kavmim içinde benim yerime geç, ıslah et, bozguncuların yoluna uyma.\""},{"n":143,"t":"Mûsâ, tayin ettiğimiz vakitte bizimle buluşmağa gelip de Rabbi ona konuşunca: \"Rabbim, bana görün, sana bakayım!\" dedi. (Rabbi) buyurdu ki: \"Sen beni göremezsin; fakat dağa bak, eğer o yerinde durursa, sen de beni göreceksin!\" Rabbi dağa görününce onu darmadağın etti ve Mûsâ da baygın düştü. Ayılınca: \"Sen yücesin, sana tevbe ettim, ben inananların ilkiyim!\" dedi."},{"n":144,"t":"(Allâh) buyurdu ki: \"Ey Mûsâ, Ben mesajlarımla ve konuşmamla seni insanların başına seçtim; sana verdiğimi al ve şükredenlerden ol!\""},{"n":145,"t":"Öğüte ve her şeyin açıklamasına dair ne varsa hepsini Mûsâ için levhalara yazdık: \"Bunları kuvvetle tut, kavmine de emret, bunların en güzelini tutsunlar (bu en güzel buyruklar gereğince amel etsinler); size, yoldan çıkmışların yurdunu (nasıl târumâr ettiğimi) göstereceğim!\""},{"n":146,"t":"Yeryüzünde haksız yere büyüklenenleri âyetlerimden uzaklaştıracağım. Onlar her âyeti görseler de yine ona inanmazlar. Doğru yolu görseler, onu yol edinmezler, ama azgınlık yolunu görseler, onu yol edinirler. Çünkü onlar, âyetlerimizi yalanladılar ve onları umursamaz oldular."},{"n":147,"t":"Âyetlerimizi ve âhirete kavuşmayı yalanlayanların eylemleri boşa çıkmıştır. Onlar, yalnız yaptıklarıyle cezâlanmıyorlar mı?"},{"n":148,"t":"Mûsâ kavmi, kendisin(in, Rabbi ile mülâkâta gitmesin)den sonra kendilerinin zinet takımlarından yapılmış, böğürmesi olan bir buzağı heykelini (tanrı diye) benimsediler. Görmediler mi ki o, ne kendilerine söz söylüyor, ne de onlara yol gösteriyor? Onu benimsediler ve zâlimler(den) oldular."},{"n":149,"t":"Ne zaman ki (pişmanlıklarından ötürü) başları elleri arasına düşürüldü ve kendilerinin gerçekten sapmış olduklarını gör(üp anla)dılar, dediler ki: \"Eğer Rabbimiz bize acımaz ve bizi bağışlamazsa, elbette ziyana uğrayanlardan oluruz!\""},{"n":150,"t":"Mûsâ, kavmine kızgın ve üzgün bir halde dönünce: \"Benden sonra arkamdan ne kötü işler yaptınız? Rabbinizin emrini (beklemeyip) acele mi ettiniz?\" dedi, levhaları yere attı ve kardeşinin başını tutup kendine doğru çekmeye başladı. (Kardeşi): \"Anamın oğlu, dedi, bu insanlar beni hırpaladılar, az daha beni öldürüyorlardı. (Ne olur) düşmanları üstüme güldürme, beni bu zâlim kavimle beraber tutma!\""},{"n":151,"t":"(Mûsâ): \"Rabbim, dedi, beni ve kardeşimi bağışla, bizi rahmetinin içine sok, merhametlilerin en merhametlisi sensin!\""},{"n":152,"t":"Buzağıyı (tanrı diye) benimseyenlere, muhakkak Rablerinden bir öfke ve dünyâ hayâtında bir alçaklık erişecektir! İşte biz iftirâcıları böyle cezâlandırırız."},{"n":153,"t":"Ama kötülükler yaptıktan sonra ardından tevbe edip inananlar(a karşı), muhakkak ki Rabbin, o(tevbe ve imâ)ndan sonra, elbette bağışlayandır, esirgeyendir."},{"n":154,"t":"Öfkesi dinince Mûsâ, levhaları aldı. Onlardaki yazıda Rablerinden korkanlar için yol gösterme ve rahmet vardı."},{"n":155,"t":"(Allâh, Mûsâ’ya kırk gece ibâdetten sonra buluşma va’detmiş ve kavminden yetmiş kişiyi de seçip o huzûra getirmesini emretmişti). Mûsâ, bizimle buluşma vakti için kavminden yetmiş adam seçti (huzûra getirdi. Gelenler, Mûsâ ile Allâh arasındaki o yüce konuşmayı işitmekle yetinmeyip Allâh’ı açıkça görmedikçe inanmayacaklarını söylediler. Bunun üzerine) onları sarsıntı yakalayınca (Mûsâ) dedi ki: \"Rabbim, dileseydin bunları da beni de daha önce helâk ederdin. İçimizden bazı beyinsizlerin yaptıklarından ötürü bizi helâk mı edeceksin? Bu (iş), senin imtihanından başka bir şey değildir. Onunla dilediğini şaşırtırsın, dilediğine yol gösterirsin. Sen bizim velimizsin, bizi bağışla, bize acı! Sen bağışlayanların en iyisisin!\""},{"n":156,"t":"\"Bize bu dünyâda da iyilik yaz, âhirette de. Biz sana yöneldik.\" (Alah) buyurdu ki: \"Azâbıma, dilediğimi uğratırım; rahmetim ise her şeyi kaplamıştır. Onu, korunanlara, zekâtı verenlere ve âyetlerimize inananlara yazacağım.\""},{"n":157,"t":"Onlar ki yanlarındaki Tevrât ve İncil’de yazılı buldukları o Elçi’ye, o ümmi Peygamber’e uyarlar. O (Peygamber) ki, kendilerine iyiliği emreder, kendilerini kötülükten meneder; onlara güzel şeyleri helâl, çirkin şeyleri harâm kılar, üzerlerindeki ağırlıkları, sırtlarındaki zincirleri kaldırıp atar. O’na inanan, destekleyerek O’na saygı gösteren, O’na yardım eden ve O’nunla beraber indirilen nura uyanlar, işte felâha erenler onlardır."},{"n":158,"t":"De ki: \"Ey insanlar, ben sizin hepinize, göklerin ve yerin sâhibi olan, kendisinden başka tanrı bulunmayan, yaşatan, öldüren Allâh’ın Elçisiyim. Gelin Allah’a ve O’nun ümmi peygamberi olan Elçisine inanın -ki o (peygamber) de Allah’a ve O’nun sözlerine inanmaktadır- O’na uyun ki doğru yolu bulasınız!\""},{"n":159,"t":"Mûsâ kavmi içinde doğrulukla hakka götüren ve hak ile adâlet yapan bir topluluk da vardır."},{"n":160,"t":"Biz onları (Ya’kûb’un oniki oğlundan gelen) oniki torun kabileye ayırdık. Kavmi kendisinden su isteyince, Mûsâ’ya: \"Asânla taşa vur!\" diye vahyettik. Taştan oniki göze fışkırdı. Her kabile içeceği yeri bildi. (Ayrıca) üzerlerine bulutla gölge yaptık ve onlara kudret helvasıyle bıldırcın eti indirdik: \"Size verdiğimiz güzel rızıklardan yeyin!\" (dedik). Ama onlar (saptılar, haksızlık ettiler. Böylece onlar) bize zulmetmediler, fakat kendi kendilerine zulmediyorlardı."},{"n":161,"t":"Onlara: \"Şu kentte oturun. Orada dilediğiniz yerden yeyin, (Allah’a niyaz edip bizi) affet deyin ve secde ederek kapıdan girin ki hatâlarınızı bağışlayalım; biz iyilik edenlere daha fazlasını da vereceğiz.\" denildi."},{"n":162,"t":"İçlerinden zulmedenler, (söylediğimiz) sözü, kendilerine söylenmeyen bir sözle değiştirdiler. Biz de haksızlık ettiklerinden dolayı üzerlerine gökten bir azâb gönderdik."},{"n":163,"t":"Onlara, deniz kıyısında bulunan kent(halkın)ın durumunu sor. Hani onlar Cumartesine saygısızlık edip haddi aşıyorlardı. Çünkü Cumartesi (tatil) yaptıkları gün, balıkları onlara akın akın gelirdi. Cumartesi (tatil) yapmadıkları gün balıkları gelmezlerdi. Biz onları yoldan çıkmalarından ötürü böyle sınıyorduk."},{"n":164,"t":"İçlerinden bir topluluk: \"Allâh’ın helâk edeceği, yahut şiddetli bir şekilde azâbedeceği bir kavme artık ne diye öğüt veriyorsunuz?\" dedi. Dediler ki: \"Rabbinize ma’zeret (beyan edebilmek) için, bir de belki korunurlar diye (öğüt veriyoruz).\""},{"n":165,"t":"Ne zaman ki onlar, kendilerine hatırlatılanı unuttular, biz de kötülükten menedenleri kurtardık; zulmedenleri de, yoldan çıkmaları yüzünden çetin bir azâb ile yakaladık."},{"n":166,"t":"Kibirlerinden dolayı kendilerine yasak kılınan şeylerden vazgeçmeyince onlara: \"Aşağılık maymunlar olun!\" dedik."},{"n":167,"t":"Rabbin, \"Elbette tâ kıyâmet gününe kadar onlara azâbın en kötüsünü yapacak kimseler gönderecektir!\" diye ilân etmişti. Doğrusu, Rabbin çabuk cezâ verendir ve O, çok bağışlayan, çok esirgeyendir."},{"n":168,"t":"Onları yeryüzünde topluluklara ayırdık. Onlardan kimi iyi kişilerdi, kimi de alçak! Belki dönerler diye onları iyiliklerle de, kötülüklerle de sınadık."},{"n":169,"t":"Onların ardından, yerlerine geçip Kitaba vâris olan birtakım insanlar geldi ki, onlar, şu alçak(dünyân)ın menfaatini alıyorlar: \"Biz nasıl olsa bağışlanacağız!\" diyorlar. Kendilerine, ona benzer bir menfaat daha gelse onu da alırlar. Peki \"Allâh hakkında, gerçekten başkasını, söylememeleri hususunda kendilerinden Kitap misâkı alınmamış mıydı? Ve onun içindekini okuyup öğrenmediler mi? Âhiret yurdu, korunanlar için daha hayırlıdır. Düşünmüyor musunuz?"},{"n":170,"t":"O(koruna)nlar ki Kitaba sımsıkı sarılırlar ve namazı kılarlar; elbette biz, iyiliğe çalışanların ecrini zayi etmeyiz."},{"n":171,"t":"Bir zaman da üzerlerine dağı, bir gölge gibi kaldırmıştık, üstlerine düşecek sanmışlardı: \"Size verdiğim(Kitap)ı kuvvetle tutun ve içinde olanı hatırlay(ıp yap)ın ki (azâbımızdan) korunasınız!\" (demiştik)."},{"n":172,"t":"Rabbin, Âdem oğullarından, onların bellerinden zürriyetlerini almış ve: \"Ben sizin Rabbiniz değil miyim?\" diye onları kendilerine şâhid tutmuştu. \"Evet, (buna) şâhidiz!\" dediler. kıyâmet günü \"Biz bundan habersizdik!\" demeyesiniz."},{"n":173,"t":"Yahut: \"(Ne yapalım) daha önce babalarımız (Allah’a) ortak koştu, biz de onlardan sonra gelen bir nesil old(uğumuz için öyle yapt)ık. (Gerçekleri) iptal edenlerin yaptıkları yüzünden bizi helâk mı ediyorsun?\" demeyesiniz diye (sizin Rabbiniz olduğum hakkında sizleri şâhid tutmuştuk)."},{"n":174,"t":"İşte biz, âyetleri böyle açıklıyoruz, artık herhalde döner(yola gelir)ler."},{"n":175,"t":"Onlara şu adamın haberini de oku: Kendisine âyetlerimizi verdik de onlardan sıyrıldı, çıktı, şeytân onu peşine taktı, böylece azgınlardan oldu."},{"n":176,"t":"Dileseydik elbette onu o âyetlerle yükseltirdik, fakat o, yere saplandı ve hevesinin peşine düştü. Onun durumu, tıpkı şu köpeğin durumuna benzer: Üstüne varsan da dilini sarkıtıp solur, onu bıraksan da dilini sarkıtıp solur. İşte âyetlerimizi yalanlayanların durumu budur. Bu kıssayı anlat, belki düşünür(öğüt alır)lar."},{"n":177,"t":"Âyetlerimizi yalanlayan ve kendilerine de zulmeden topluluğun durumu ne kötüdür!"},{"n":178,"t":"Allâh kime yol gösterirse, işte yolu bulan odur. Kimi de saptırırsa, işte ziyana uğrayanlar onlardır."},{"n":179,"t":"Andolsun, cehennem için de birçok cin ve insan yarattık ki kalbleri var, fakat onlarla anlamazlar; gözleri var, fakat onlarla görmezler; kulakları var, fakat onlarla işitmezler. İşte onlar hayvanlar gibidir, hattâ daha da sapık... Ve işte gâfiller onlardır!"},{"n":180,"t":"En güzel isimler Allâh’ındır. O halde O’na o (güzel isim)lerle du’â edin ve O’nun isimleri hakkında eğriliğe sapanları bırakın; onlar yaptıklarının cezâsını çekeceklerdir."},{"n":181,"t":"Yarattıklarımız içinde, doğrulukla hakka götüren ve hak ile adâlet yapan bir ümmet de vardır."},{"n":182,"t":"Âyetlerimizi yalanlayanları, hiç bilmeyecekleri yerden yavaş yavaş helâke yaklaştıracağız."},{"n":183,"t":"Onlara mühlet veriyorum, çünkü benim tuzağım sağlamdır."},{"n":184,"t":"Düşünmediler mi ki arkadaşlarında hiçbir delilik yoktur, o apaçık bir uyarıcıdır?"},{"n":185,"t":"Göklerin, yerin melekûtuna ve Allâh’ın yarattığı şeylere ve ecellerinin yaklaşmış olabileceğine bak(ıp ibret al)madılar mı? Peki bun(a inanmadık)dan sonra hangi söze inanacaklar?"},{"n":186,"t":"Allâh kimi saptırırsa, artık onun için yol gösteren olmaz. Ve bırakır onları, azgınlıkları içinde bocalayıp dururlar."},{"n":187,"t":"Sana (Duruşma) sâ’at(in)den soruyorlar: Gelip çatması ne zaman diye. De ki: \"Onun bilgisi, ancak Rabbimin yanındadır. Onu tam zamanında açığa çıkaracak olan, yalnız O’dur. O, göklere de, yere de ağır gelmiştir. O size ansızın gelecektir.\" Sanki sen, onu biliyormuşsun gibi, sana soruyorlar. De ki: \"Onun bilgisi, Allâh’ın yanındadır. Fakat insanların çoğu bilmezler.\""},{"n":188,"t":"De ki: \"Ben kendime, Allâh’ın dilediğinden başka ne bir fayda, ne de bir zarar verme gücüne sâhip değilim. Eğer gaybı bilseydim, elbete çok hayır (mal ve mülk) elde ederdim. Bana kötülük dokunmamış (beni cin çarpmamış)tır. Ben sadece inanan bir kavim için bir uyarıcı ve müjdeleyiciyim."},{"n":189,"t":"O’dur ki sizi bir tek nefisten yarattı, gönlü ısınsın diye ondan eşini var eti; eşini sarıp örtünce (eşiyle birleşince) eşi, hafif bir yük yüklendi, onu gezdirdi. (Yükü) ağırlaşınca ikisi beraber Rableri Allah’a du’â ettiler: \"Eğer bize iyi, güzel bir çocuk verirsen elbette şükredenlerden oluruz!\" (dediler)."},{"n":190,"t":"Fakat (Allâh) onlara iyi, güzel bir çocuk verince, kendilerine verdiği şeyde Allah’a ortaklar koşmağa başladılar. Allâh ise onların ortak koştukları şeylerden yücedir."},{"n":191,"t":"Hiçbir şey yaratmayan, kendileri yaratılan şeyleri (Allah’a) ortak mı koşuyorlar?"},{"n":192,"t":"(O putlar), ne onlara bir yardım edebilirler, ne de kendilerine yardım ederler?"},{"n":193,"t":"Onları doğru yola çağırsanız size uymazlar. Ha onları çağırmışsınız, ha susmuşsunuz, sizin için birdir."},{"n":194,"t":"Allah’tan başka yalvardıklarınız da sizler gibi kullardır, (onların tanrı olduğu hakkındaki iddiânızda) doğru iseniz, çağırın onları da size cevap versinler."},{"n":195,"t":"Onların yürüyecekleri ayakları mı var, yoksa tutacakları elleri mi var, yoksa görecekleri gözleri mi var, yahut işitecekleri kulaklarımı var? De ki: \"(Allah’a) ortak(koştuk)larınızı çağırın, sonra bana tuzak kurun, haydi (elinizden geliyorsa) hiç göz açtırmayın bana!\""},{"n":196,"t":"Benim velim, Kitabı indiren Allah’tır. O, iyileri yönetir (korur)."},{"n":197,"t":"O’ndan başka yalvardıklarınız ise, ne size yardım edebilirler, ne de kendilerine yardım ederler."},{"n":198,"t":"Onları hidâyete çağırırsanız, işitmezler. Onların sana baktıklarını sanırsın, oysa onlar görmezler."},{"n":199,"t":"Affı al, iyiliği emret, câhillere aldırış etme."},{"n":200,"t":"Ne zaman şeytândan bir kötü düşünce seni dürtüklerse, Allah’a sığın; çünkü O, işitendir, bilendir."},{"n":201,"t":"Allah’tan korkanlar, kendilerine şeytândan gelen bir vesvese dokunduğu zaman düşünür, (gerçeği) görürler."},{"n":202,"t":"Kardeşleri ise onları, azgınlığa çekerler, hiç yakalarını bırakmazlar."},{"n":203,"t":"Onlara bir âyet getirmediğin zaman: \"Bunu da derleseydin ya!\" derler. De ki: \"Ben, ancak Rabbimden bana vahyolunana uyuyorum. Bu (Kur’ân), Rabbinizden gelen basiretler(gönül gözlerini açan nurlar, gerçeğe ileten kanıtlar)dır ve inanan bir toplum için yol gösterici ve rahmettir!\""},{"n":204,"t":"Kur’ân okunduğu zaman onu dinleyin ve susun ki, size rahmet edilsin."},{"n":205,"t":"Rabbini, içinden, yalvararak ve korkarak, yüksek olmayan bir sesle sabah akşam an, gâfillerden olma!"},{"n":206,"t":"Rabbinin yanında olanlar, büyüklük taslayıp O’na kulluktan geri kalmazlar, (dâimâ) O’nu tesbih ederler ve O’na secde ederler."}],[{"n":1,"t":"Sana ganimetlerden sorarlar; de ki: \"Ganimetler, Allâh’ın ve Elçi(si)nindir. Siz, (gerçekten) inananlar iseniz, Allah’tan korkun, aranızı düzeltin, Allah’a ve Elçisine itâ’at edin!\""},{"n":2,"t":"Mü’minler o kimselerdir ki, Allâh anıldığı zaman yürekleri ürperir, O’nun âyetleri kendilerine okunduğu zaman imanlarını artırır ve Rablerine tevekkül ederler."},{"n":3,"t":"Namazlarını kılarlar ve kendilerine verdiğimiz rızıktan (Allâh için) harcarlar."},{"n":4,"t":"İşte gerçek mü’minler onlardır. Onlara Rablerinin katında dereceler, bağışlanma ve tükenmez rızık var."},{"n":5,"t":"(Ganimetlerin bölüştürülmesinde bazı kimselerin hoşnutsuzluk göstermesi, daha önce, Bedir Savaşı’na çıkmanı hoş görmeyenlerin durumuna benzer). Nitekim hak uğruna (savaşa gitmek için) Rabbin seni, evinden çıkardığı zaman, mü’minlerden birtakımı, bundan hoşlanmıyordu."},{"n":6,"t":"Hak ortaya çıkmış iken sanki gözleri göre göre ölüme sürülüyorlarmış gibi seninle tartışıyorlardı."},{"n":7,"t":"Allâh size, iki topluluktan birinin sizin olduğunu va’dediyordu; siz de kuvvetsiz olanın sizin olmasını istiyordunuz. Oysa Allâh, sözleriyle hakkı gerçekleştirmek ve (kuvvetli olan takımı yok ederek) kâfirlerin ardını kesmek istiyordu."},{"n":8,"t":"Ki suçlular istemese de hakkı gerçekleştirsin, bâtılı da ortadan kaldırsın."},{"n":9,"t":"Siz Rabbinizden yardım istiyordunuz, O da: \"Ben size birbiri ardınca bin melek ile yardım edeceğim,\" diye duânızı kabul buyurmuştu."},{"n":10,"t":"Allâh bunu ancak müjde olsun (sevinesiniz) ve kalbiniz bununla yatışsın (güvene ve huzûra kavuşsun) diye yapmıştı. Yardım, yalnız Allâh katındandır. Allâh dâimâ üstün, hüküm ve hikmet sâhibidir."},{"n":11,"t":"O zaman sizi, Allah’tan bir güven olmak üzere hafif bir uyku bürüyordu, üzerinize sizi temizlemek, şeytânın pisliğini (içinize attığı kötü düşünceleri) sizden gidermek, kalblerinizi (birbirine) bağlamak ve ayakları(nızı) pekiştirmek için üzerinize gökten bir su indiriyordu."},{"n":12,"t":"Rabbin meleklere vahyediyordu ki: \"Ben sizinle beraberim, siz inananları pekiştirin; ben inkâr edenlerin yüreklerine korku salacağım; vurun (onların) boyunların(ın) üstüne, vurun onların her parmağına!\""},{"n":13,"t":"Böyle (olacak), çünkü, onlar Allah’a ve Elçisine karşı geldiler. Kim Allah’a ve Elçisine karşı gelirse muhakkak ki, Allâh’ın cezâsı çetin olur."},{"n":14,"t":"\"İşte siz şimdi tadın onu; (ayrıca) kâfirler için ateş azâbı da vardır!\""},{"n":15,"t":"Ey inananlar, inkâr edenlerle toplu halde karşılaşırsanız, onlara arkalar(ınız)ı döndür(üp kaç)mayın."},{"n":16,"t":"Kim o gün savaşmak için bir tarafa çekilmek, ya da başka bir birliğe katılmak dışında arkasını döner(kaçar)sa o, Allah’tan bir gazaba uğrar, onun yeri cehennemdir, o ne kötü varılacak bir yerdir!"},{"n":17,"t":"(O gün) Onları siz öldürmediniz, fakat onları Allâh öldürdü; (ey Muhammed), attığın zaman sen atmadın, fakat Allâh attı. Mü’minleri güzel bir imtihanla sınamak için (bunu yaptı). Doğrusu Allâh işitendir, bilendir."},{"n":18,"t":"İşte size böyle yaptı. Çünkü Allâh, kâfirlerin tuzağını zayıflatır."},{"n":19,"t":"Eğer fetih istiyorsanız işte size fetih geldi. Eğer (eski yaptıklarınızdan) vazgeçerseniz, bu sizin için iyidir. Ama yine (eski yaptıklarınıza) dönerseniz, biz de döneriz (size yardım etmekten vazgeçeriz). O zaman topluluğunuz çok da olsa, size hiçbir yarar sağlayamaz. Allâh, inananlarla beraberdir."},{"n":20,"t":"Ey inananlar, Allah’a ve Elçisine itâ’at edin, işittiğiniz halde ondan dönmeyin."},{"n":21,"t":"İşitmedikleri halde \"İşittik\" diyenler gibi olmayın."},{"n":22,"t":"Allâh katında canlıların en kötüsü, düşünmeyen sağırlar ve dilsizlerdir."},{"n":23,"t":"Allâh onlarda bir iyilik olduğunu bilseydi, elbette onlara işittirirdi, onlara işittirseydi de yine aldırmayarak dönerlerdi."},{"n":24,"t":"Ey inananlar (elçi), sizi yaşatacak şeylere çağırdığı zaman Allâh’ın ve Elçisinin çağrısına koşun ve bilin ki, Allâh, kişi ile onun kalbi arasına girer ve siz, O’nun huzûruna toplanacaksınız."},{"n":25,"t":"(Öyle) Bir fitneden sakının ki, aranızdan yalnız haksızlık edenlere erişmekle kalmaz (hepinize erişir). Bilinki Allâh’ın azâbı çetindir."},{"n":26,"t":"Düşünün ki bir zaman siz az idiniz, yeryüzünde hırpalanıyordunuz. İnsanların sizi kapıp götürmesinden korkuyordunuz. Allâh, sizi barındırdı, sizi yardımıyle destekledi, sizi güzel şeylerle besledi ki, şükredesiniz."},{"n":27,"t":"Ey inananlar, bile bile emânetlerinize hiyânet etmek sûretiyle Allah’a ve Elçisine hiyânet etmeyin."},{"n":28,"t":"Bilin ki mallarınız ve çocuklarınız birer fitne(sınav)dır. Allah’a gelince büyük mükâfât, o’nun yanındadır."},{"n":29,"t":"Ey inananlar, Allah’tan korkarsanız O size iyi ile kötüyü ayırdedici bir anlayış verir, kötülüklerinizi örter ve sizi bağışlar. Allâh büyük lutuf sâhibidir."},{"n":30,"t":"İnkâr edenler seni tutup bağlamaları, öldürmeleri, ya da sürmeleri için sana tuzak kuruyorlardı. Onlar tuzak kurarlarken Allâh da tuzak kuruyordu. Allâh tuzak kuranların en iyisidir. (O, kendisine karşı tuzak kuranların tuzaklarını başlarına geçirir)."},{"n":31,"t":"Onlara âyetlerimiz okunduğu zaman \"İşittik\" dediler, \"İstesek, biz de bunun gibisini söyleriz. Bu, evvelkilerin masallarından başka bir şey değildir!\""},{"n":32,"t":"Ve: \"Allâh’ım, eğer bu, senin yanından gelmiş gerçekse başımıza gökten taş yağdır, yahut bize acı bir azâb getir!\" demişlerdi."},{"n":33,"t":"Oysa sen onların içinde bulundukça Allâh, onlara azâb edecek değildi ve onlar istiğfar ederlerken (içlerinde istiğfar edenler var iken) de Allâh, onlara azâb edecek değildi."},{"n":34,"t":"Onlar, (inananları) Mescid-i harâmdan geri çevirdikleri ve onun velisi, (bakıcısı, koruyucusu) olmadıkları halde neden Allâh onlara azâbetmesin? Onun velileri, (bakıcıları, koruyucuları) sadece (günâhlardan) korunanlardır. Fakat çokları bilmezler."},{"n":35,"t":"Onların Beyt(ullah) yanındaki namazları da, ıslık çalmadan ve el çırpmadan ibarettir. \"O halde inkârınızdan dolayı azâbı tadın!\""},{"n":36,"t":"İnkâr edenler, Allâh yoluna engel olmak için mallarını harcarlar ve harcayacaklar da. Sonra bu, kendilerine dert olacak, nihâyet yenilecekler ve inkâr edenler cehenneme sürüleceklerdir."},{"n":37,"t":"(Sürüleceklerdir) Ki, Allâh, murdarı temizden ayıklasın ve bütün murdarları birbiri üzerine koyup yığsın da hepsini cehenneme atsın. İşte ziyana uğrayanlar onlardır."},{"n":38,"t":"İnkâr edenlere söyle: \"Eğer vazgeçerlerse, geçmişteki (günâhları) kendilerine bağışlanır; yok yine (eski hallerine) dönerlerse, öncekilerin (başlarına gelen Allâh) kanunu geçmiştir (bunların da başına gelecektir. Onu beklesinler)."},{"n":39,"t":"Fitne (baskı) kalmayıncaya ve din tamamen Allâh’ın oluncaya kadar onlarla savaşın! Eğer (baskıya) son verirlerse muhakkak ki Allâh, ne yaptıklarını görmektedir."},{"n":40,"t":"Eğer dönerlerse, bilin ki Allâh sizin sâhibinizdir. O, ne güzel sâhip, ne güzel yardımcıdır!"},{"n":41,"t":"Eğer Allah’a ve (hak ile bâtılın) ayrılma gününde, o iki topluluğun karşılaştığı (Bedir) gün(ün)de kulumuz(Muhammed)e indirdiğimiz(âyetler)e inanmışsanız bilin ki aldığınız ganimetlerin beşte biri, Allah’a, Elçisine ve (Allâh’ın Elçisi ile) akrabâlığı bulunan(lar)a, yetimlere, yoksullara ve yolcu(lar)a âittir. Allâh her şeye kâdirdir."},{"n":42,"t":"O gün siz, vâdinin yakın kenarında idiniz, onlar da uzak kenarında idiler. Kervan da sizden daha aşağıda idi. Eğer sözleşmiş olsaydınız dahi, sözleştiğiniz vakitte öyle buluşamazdınız. Fakat Allâh, yapılması gereken bir işi yerine getirmek için (sizi böyle buluşturdu) ki helâk olan, açık delille helâk olsun; yaşayan da açık delille yaşasın. Çünkü Allâh, işitendir, bilendir."},{"n":43,"t":"Allâh, sana onları uykunda az gösteriyordu. Eğer sana onları çok gösterseydi, çekinirdiniz ve (savaş) iş(in)de çekişirdiniz. Fakat Allâh, (sizi bundan) kurtardı. Doğrusu O, göğüslerin özünü bilir."},{"n":44,"t":"Karşılaştığınız zaman onları sizin gözlerinize az gösteriyor, sizi de onların gözlerinde azaltıyordu ki yapılması gereken bir işi yerine getirsin. İşler, hep Allah’a döndürülecektir."},{"n":45,"t":"Ey inananlar, bir toplulukla karşılaştığınız zaman sebat edin ve Allâh’ı çok anın ki, başarıya erişesiniz."},{"n":46,"t":"Allah’a ve Elçisine itâ’at edin, birbirinizle çekişmeyin, yoksa korkuya kapılırsınız, devletiniz gider. Sabredin, çünkü Allâh sabredenlerle beraberdir."},{"n":47,"t":"Yurtlarından çalım satarak, insanlara gösteriş yaparak çıkan ve Allâh yolundan men’edenler gibi olmayın. Allâh, onların bütün yaptıklarını kuşatmıştır."},{"n":48,"t":"O zaman şeytân onlara yaptıkları işi süslemiş: \"Bugün insanlardan sizi yenecek kimse yoktur, (korkmayın), ben sizin yanınızdayım!\" demişti. Fakat iki topluluk birbirini görünce iki ökçesi üzerine (geriye) dönüp: \"Ben sizden uzağım, ben sizin görmediğinizi görüyorum, ben Allah’tan korkarım, zira Allâh’ın cezâsı çetindir!\" demişti."},{"n":49,"t":"Münâfıklar ve kalblerinde hastalık bulunanlar (sizin için): \"Bunları dinleri aldatmış, (baksana başa çıkamayacakları bir kuvvetle savaşmağa kalkıyorlar).\" diyorlardı. Oysa, kim Allah’a dayanırsa şüphesiz Allâh, dâimâ gâlib, hüküm ve hikmet sâhibidir."},{"n":50,"t":"Görseydin o inkâr edenleri: Melekler, onların canlarını alırken yüzlerine ve kıçlarına vuruyorlar: \"Haydi, yangın azâbını tadın!\" (diyorlardı)."},{"n":51,"t":"\"İşte bu, ellerinizin yapıp öne sürdüğü işler yüzündendir. Yoksa Allâh, kullara zulmedici değildir.\""},{"n":52,"t":"(Bunlar da) tıpkı Fir’avn âilesi ve onlardan öncekilerin gidişi gibi(davrandılar. Onlar da): Allâh’ın âyetlerini inkâr etmişlerdi; Allâh da onları, günâhlarıyla yakalamıştı. Şüphesiz Allâh güçlüdür, O’nun cezâsı çetindir."},{"n":53,"t":"Bu böyledir, çünkü bir millet kendilerinde bulunan(güzel meziyet)i değiştirmedikçe Allâh onlara verdiği ni’meti değiştirmez. Allâh işitendir, bilendir."},{"n":54,"t":"(Evet) Fir’avn âilesi ve onlardan öncekilerin gidişi gibi: Rablerinin âyetlerini yalanlamışlardı; biz de onları günâhlarıyle mahvetmiştik ve Fir’avn âilesini boğmuştuk. Hepsi de zulmedicilerdi."},{"n":55,"t":"Allah’a göre canlıların en kötüsü, kâfirlerdir; artık onlar inanmazlar."},{"n":56,"t":"Sen kendileriyle andlaşma yaptığın halde onlar, hiç çekinmeden, her defa andlaşmalarını bozarlar."},{"n":57,"t":"Savaşta onları yakalarsan, onlar(a vereceğin cezâ) ile arkalarında bulunan kimseleri de dağıt ki ibret alsınlar."},{"n":58,"t":"Bir kavmin, (andlaşmaya) hiyânet etmesinden korkarsan, sen de (onlarla yaptığın andlaşmayı) aynı şekilde onlara at; çünkü Allâh; hâinleri sevmez."},{"n":59,"t":"İnkâr edenler (bizim elimizden kurtulup) geçtiklerini sanmasınlar. Onlar (bizi) âciz bırakamazlar."},{"n":60,"t":"Onlara karşı gücünüz yettiği kadar kuvvet ve cihâd için bağlanıp beslenen atlar hazırlayın. Bununla Allâh’ın düşmanını, sizin düşmanınızı ve onlardan başka sizin bilmediğiniz, Allâh’ın bildiği (düşman) kimseleri korkutursunuz. Allâh yolunda ne harcarsanız tam olarak size ödenir, hiç haksızlığa uğratılmazsınız."},{"n":61,"t":"Eğer onlar barışa yanaşırlarsa sen de ona yanaş ve Allah’a dayan, çünkü O, işitendir, bilendir."},{"n":62,"t":"Eğer sana hile yapmak isterlerse (korkma) Allâh sana yeter. O ki, yardımıyle seni ve mü’minleri destekledi."},{"n":63,"t":"Ve onların kalblerinin arasını uzlaştırdı. Sen yeryüzünde bulunan herşeyi verseydin, yine onların kalblerinin arasını uzlaştıramazdın; fakat Allâh, onların arasını uzlaştırdı. Çünkü O, dâimâ üstündür, hüküm ve hikmet sâhibidir."},{"n":64,"t":"Ey peygamber, Allâh sana ve sana tâbi olan mü’minlere yeter."},{"n":65,"t":"Ey peygamber, mü’minleri savaşa teşvik et. Eğer sizden sabreden yirmi kişi olursa, iki yüz(kâfir)i yenerler. Sizden yüz kişi olursa, kâfirlerden bin kişiyi yenerler. Çünkü kâfirler, anlamaz bir topluluktur."},{"n":66,"t":"Şimdi Allâh sizden hafifletti, sizde zayıflık bulunduğunu bildi. Bundan böyle sizden sabreden yüz kişi olsa, iki yüz(kâfir)i yenerler. Ve eğer sizden bin kişi olsa Allâh’ın izniyle iki bin(kâfir)i yenerler. Allâh, sabredenlerle beraberdir."},{"n":67,"t":"Yeryüzünde ağır bas(ıp küfrün belini iyice kır)ıncaya kadar hiçbir peygambere esirler sâhibi olmak yakışmaz. Siz, geçici dünyâ malını istiyorsunuz, Allâh ise (sizin için) âhireti istiyor. Allâh dâimâ üstün, hüküm ve hikmet sâhibidir."},{"n":68,"t":"Eğer Allah’tan, (yanılma ile verilen hükümlerden ötürü azâbetmemek hakkında) bir yazı geçmemiş olsaydı, aldığınız fidyeden dolayı size mutlaka büyük bir azâb dokunurdu."},{"n":69,"t":"Artık aldığınız ganimetten helâl ve temiz olarak yeyin ve Allah’tan korkun. Şüphesiz Allâh, bağışlayandır, esirgeyendir."},{"n":70,"t":"Ey peygamber, ellerinizde bulunan esirlere söyle: \"Eğer Allâh, sizin kalblerinizde bir hayır olduğunu bilirse, size, sizden alınan(fidye)den daha hayırlısını verir ve sizi bağışlar. Allâh bağışlayandır, esirgeyendir."},{"n":71,"t":"Eğer sana hâinlik yapmak isterlerse, daha önce Allah’a da hâinlik yapmışlardı. Bu yüzden (Allâh) onlara karşı (sana) imkân verdi. Allâh (herşeyi) bilendir, yerli yerince yapandır."},{"n":72,"t":"Onlar ki inandılar, hicret ettiler, Allâh yolunda mallariyle, canlariyle savaştılar ve onlar ki (yurtlarına göçenleri) barındırdılar ve yardım ettiler; işte onlar, birbirlerinin velisi(dostu, koruyucusu)durlar. İnanıp da hicret etmeyenlere gelince, onlar hicret edinceye kadar, onların velâyetinden size bir şey yoktur (onları korumakla yükümlü değilsiniz). Fakat dinde yardım isterlerse (onlara) yardım etmeniz gerekir. Yalnız, aranızda andlaşma bulunan bir topluma karşı (yardım etmeniz) olmaz. Allâh, yaptıklarınızı görmektedir."},{"n":73,"t":"İnkâr edenler, birbirlerinin velisidirler. Eğer bunu yapmazsanız (mü’minleri bırakıp kâfirleri dost tutarsanız), yeryüzünde fitne ve büyük bir kargaşa olur."},{"n":74,"t":"Onlar ki, inandılar, hicret ettiler, Allâh yolunda savaştılar ve onlar ki, (göçmenleri) barındırdılar ve (onlara) yardım ettiler, işte gerçek mü’minler onlardır. Onlar için bağış ve bol rızık vardır."},{"n":75,"t":"Onlar ki sonradan inandılar, hicret ettiler, sizinle beraber savaştılar, işte onlar da sizdendir. Rahim sâhipleri (kan akrabâsı), Allâh’ın Kitabına göre birbirlerine daha yakın dostturlar. Allâh herşeyi bilir."}],[{"n":1,"t":"Allâh ve Elçisinden, andlaşma yaptığınız müşriklere ihtârdır."},{"n":2,"t":"Dört ay daha yeryüzünde dolaşın, bilin ki siz, Allâh’ı âciz bırakamazsınız ve Allâh, kâfirleri rezil, perişan edecektir!"},{"n":3,"t":"En büyük Hac günü, Allâh ve Elçisinden insanlara duyurudur: Allâh ve Elçisi puta tapanlardan uzaktır. Eğer tevbe ederseniz, bu sizin için daha iyidir. Ve eğer dönerseniz bilin ki siz Allâh’ı âciz bırakacak değilsiniz! (Ey Muhammed) kâfirlere acı bir azâbı müjdele."},{"n":4,"t":"Ancak andlaşma yaptığınız müşriklerden, (andlaşma şartlarından) hiçbir şeyi size eksik bırakmayan ve size karşı hiç kimseye arka çıkmayanların andlaşmalarını, kendilerine tanıdığınız süreye kadar tamamlayın. Çünkü Allâh korunanları sever."},{"n":5,"t":"Harâm aylar çıkınca (Allah’a) ortak koşanları nerede bulursanız öldürün; onları yakalayın, hapsedin ve her gözetleme yerinde otur(up) onları bekleyin. Eğer tevbe ederler, namazı kılarlar, zekâtı verirlerse yollarını serbest bırakın. Çünkü Allâh bağışlayandır, esirgeyendir."},{"n":6,"t":"Ve eğer ortak koşanlardan biri güvence dileyip yanına gelmek isterse, onu yanına al ki, Allâh’ın sözünü işitsin; sonra onu güven içinde bulunacağı yere ulaştır. Böyle (yap), çünkü onlar, bilmez bir topluluktur."},{"n":7,"t":"Ortak koşanların, Allâh’ın yanında ve Elçisinin yanında nasıl andlaşması olabilir? Ancak Mescid-i harâm’da andlaştıklarınız hariç. Onlar size dürüst davrandıkça siz de onlara dürüst davranın, çünkü Allâh, korunanları sever."},{"n":8,"t":"Evet (Allâh ve Elçisi yanında onların) nasıl (ahdi olabilir)? Eğer onlar size gâlib gelselerdi, sizin hakkınızda ne and ne de andlaşma gözetmezlerdi. Ağızlarıyla sizi râzı ederler, fakat kalbleri (sizi) istemez. Çokları da yoldan çıkmışlardır."},{"n":9,"t":"Allâh’ın âyetlerini az bir paraya sattılar da O’nun yoluna engel oldular. Onların yaptıkları, gerçekten ne kötüdür!"},{"n":10,"t":"Bir mü’mine karşı ne and, ne de andlaşma gözetmezler. İşte saldırganlar onlardır."},{"n":11,"t":"Eğer tevbe ederler, namazı kılarlar ve zekâtı verirlerse, dinde sizin kardeşlerinizdirler. Biz, bilen bir kavme âyetleri böyle uzun uzun açıklıyoruz."},{"n":12,"t":"Eğer andlaşma yaptıktan sonra andlarını bozarlar ve dininize dil uzatırlarsa, o küfür önderleriyle savaşın. Çünkü onların andları yoktur; belki (böylece küfürden) vazgeçerler."},{"n":13,"t":"Andlarını bozan, Elçiyi (Mekke’den) çıkarmağa yeltenen ve ilk önce kendileri siz(inle savaş)a başlamış olan bir kavimle savaşmayacak mısınız? Yoksa onlardan korkuyor musunuz? Eğer gerçekten inanan insanlar iseniz, kendisinden korkmanıza en lâyık olan Allah’tır."},{"n":14,"t":"Onlarla savaşın ki Allâh, sizin ellerinizle onlara azâbetsin, onları rezil etsin, sizi onlara üstün getirsin ve inananlar toplumunun göğüslerine şifa versin;"},{"n":15,"t":"Yüreklerinin öfkesini gidersin. Allâh, dilediğinin tevbesini kabul eder. Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":16,"t":"Yoksa siz, Allâh içinizden cihâd eden ve Allah’tan, Elçisinden ve mü’minlerden başkasını kendisine sırdaş edinmeyenleri bilmeden, bırakılacağınızı mı sandınız? Allâh yaptıklarınızı haber almaktadır."},{"n":17,"t":"(Allah’a) Ortak koşanlar nefislerinin küfrünü göre göre Allâh’ın mescidlerini şenlendiremezler. Onların yaptıkları işler, boşa çıkmıştır. Ve onlar, ateşte sürekli kalacaklardır."},{"n":18,"t":"Allâh’ın mescidlerini, ancak Allah’a ve âhiret gününe inanan, namazı kılan, zekâtı veren ve Allah’tan başka kimseden korkmayanlar şenlendirirler. Onların, doğru yolu bulanlardan olacakları umulur."},{"n":19,"t":"(Ey müşrikler siz), hacılara su verme ve Mescid-i harâm’ı şenlendirmeyi; Allah’a, âhiret gününe inanan ve Allâh yolunda cihâd eden(in eylemiy)le bir mi tuttunuz? Bunlar, Allâh katında bir olmazlar. Allâh, zâlimler topluluğuna yol göstermez."},{"n":20,"t":"İnanan, hicret eden ve Allâh yolunda mallarıyle, canlarıyle savaşanların, Allâh katında dereceleri daha büyüktür. İşte kurtuluşa erenler onlardır."},{"n":21,"t":"Rableri onlara, kendisinden bir rahmet, rızâ ve içinde sürekli kalacakları ni’meti bol cennetleri müjdeler."},{"n":22,"t":"Orada ebedi kalacaklardır. Şüphesiz büyük mükâfât Allâh katındandır!"},{"n":23,"t":"Ey inananlar, eğer imânâ karşı küfrü seviyorlarsa babalarınızı ve kardeşlerinizi veliler edinmeyin. Sizden kim onları veli tanır(dost tutar)sa işte zâlimler onlardır."},{"n":24,"t":"De ki: \"Eğer babalarınız, oğullarınız, kardeşleriniz, eşleriniz, hısım akrabânız, kazandığınız mallar, düşmesinden korktuğunuz ticaret(iniz), hoşlandığınız konutlar, size Allah’tan, Elçisinden ve O’nun yolunda cihâdetmekten daha sevgili ise o halde Allâh emrini getirinceye kadar gözetleyin (başınıza gelecekleri göreceksiniz)! Allâh, yoldan çıkmış topluluğu (doğru) yola iletmez."},{"n":25,"t":"Andolsun Allâh size birçok yerlerde, Huneyn gününde de yardım etmişti. Hani (o gün) çokluğunuz sizi böbürlendirmişti. Fakat size hiçbir yarar da sağlamamıştı. Bütün genişliğine rağmen yeryüzü başınıza dar gelmişti, nihâyet bozularak arkanızı dönmüş(kaçmağa başlamış)tınız."},{"n":26,"t":"Sonra Allâh, Elçisinin ve mü’minlerin üzerine sekinetini (güven veren rahmetini) indirdi, sizin görmediğiniz askerler indirdi ve kâfirlere azâb etti (onları bozguna uğrattı). İşte kâfirlerin cezâsı budur!"},{"n":27,"t":"Sonra Allâh, bunun ardından yine dilediğinin tevbesini kabul eder. Allâh bağışlayandır, esirgeyendir."},{"n":28,"t":"Ey inananlar, (Allah’a) ortak koşanlar pisliktir, artık bu yıllarından sonra Mescid-i Harâm’a yaklaşmasınlar. Eğer (onların hacca gelmemeleri sonucu ekonominiz bozulup) yoksulluğa düşmekten korkarsanız; biliniz ki Allâh dilerse yakında sizi kendi lutfundan zengin edecektir. Şüphesiz Allâh, bilendir, hikmet sâhibidir."},{"n":29,"t":"Kendilerine Kitap verilenlerden Allah’a ve âhiret gününe inanmayan, Allâh’ın ve Elçisinin harâm kıldığını harâm saymayan ve gerçek dini din edinmeyen kimselerle, küçül(üp boyun eğ)erek elleriyle cizye verecekleri zamana kadar savaşın."},{"n":30,"t":"Yahûdiler: \"Uzeyr, Allâh’ın oğludur.\" dediler. Hıristiyanlar da: \"Mesih Allâh’ın oğludur.\" dediler. Bu, onların ağızlariyle geveledikleri sözleridir. (Sözlerini), önceden inkâr etmiş(olan müşrik)lerin sözlerine benzetiyorlar. Allâh onları kahretsin, nasıl da (haktan bâtıla) çevriliyorlar!?"},{"n":31,"t":"Hahamlarını ve rahiplerini Allah’tan ayrı rabler edindiler, Meryem oğlu Mesih’i de öyle. Oysa kendilerine yalnız tek Tanrı olan Allah’a ibâdet etmeleri emredilmişti. O’ndan başka tanrı yoktur. O, onların ortak koştukları şeylerden münezzehtir."},{"n":32,"t":"Allâh’ın nurunu ağızlariyle söndürmek istiyorlar. Halbuki, kâfirler hoşlanmasa da Allâh, mutlaka nurunu tamamlamak ister, (bundan başka bir şeye râzı olmaz)."},{"n":33,"t":"O, Elçisini hidâyetle ve hak dinle gönderdi ki (Allah’a) ortak koşanlar hoşlanmasa da o (hak di)ni, bütün din(ler)in üstüne çıkarsın."},{"n":34,"t":"Ey inananlar, hahamlardan ve rahiplerden birçoğu, insanların mallarını haksızlıkla yerler ve (insanları) Allâh yolundan çevirirler. Altın ve gümüşü yığıp da onları Allâh yolunda harcamayanlar var ya, işte onlara acı bir azâbı müjdele!"},{"n":35,"t":"O gün cehennem ateşinde bunların üzeri ısıtılı(p pullanı)r; bunlarla, onların alınları, yanları ve sırtları dağlanır: \"İşte nefisleriniz için yığdıklarınız, yığdıklarınızı tadın!\" (denilir)."},{"n":36,"t":"Gökleri ve yeri yarattığı gündeki yazısına göre Allâh’ın katında ayların sayısı on ikidir. Bunlardan dördü harâm(ay)lardır. İşte doğru din budur. O aylar içinde (konulmuş yasağı çiğneyerek) kendinize zulmetmeyin ve (Allah’a) ortak koşanlar nasıl sizinle topyekûn savaşıyorlarsa, siz de onlarla topyekûn savaşın ve bilin ki Allâh korunanlarla beraberdir."},{"n":37,"t":"(Harâm ayını) ertelemek, küfürde daha ileri gitmektir. İnkâr edenler, onunla saptırılır. O(harâm ayı)nı bir yıl helâl sayarlar, bir yıl harâm sayarlar ki, Allâh’ın harâm kıldığının sayısını denk getirip, Allâh’ın harâm kıldığını helâl yapsınlar. Yaptıkları işin kötülüğü, kendilerine süslü gösterildi. Allâh, kâfirler toplumuna yol göstermez."},{"n":38,"t":"Ey inananlar, size ne oldu ki: \"Allâh yolunda topluca savaşa çıkın!\" dendiği zaman yere çakılıp kaldınız? âhirettense dünyâ hayâtına mı râzı oldunuz? Ama dünyâ hayâtının geçimi, âhiretin yanında pek azdır."},{"n":39,"t":"Eğer topluca (savaşa) çıkmazsanız, (Allâh) size acı (bir şekilde) azâbeder ve yerinize sizden başka bir topluluk getirir, O’na hiçbir zarar veremezsiniz, Allâh herşeyi yapabilendir."},{"n":40,"t":"Eğer siz o(Hak elçisi)ne yardım etmezseniz, iyi bilin ki, Allâh ona yardım etmişti: Hani yalnız iki kişiden biri olduğu halde, inkâr edenler kendisini (Mekke’den) çıkardıkları sırada ikisi mağarada iken arkadaşına \"Üzülme, Allâh bizimle beraberdir!\" diyordu. (İşte o zaman) Allâh (ona yardım etti) onun üzerine sekine(huzûr ve güven duygu)sunu indirdi ve onu, sizin görmediğiniz askerlerle destekledi; inanmayanların sözünü alçattı. Yüce olan, yalnız Allâh’ın sözüdür. Allâh dâimâ üstündür, hüküm ve hikmet sâhibidir."},{"n":41,"t":"Gerek hafif, gerek ağır olarak savaşa çıkın, mallarınızla ve canlarınızla Allâh yolunda cihâd edin. Eğer bilirseniz bu, sizin için daha hayırlıdır."},{"n":42,"t":"Yakın bir dünyâ menfaati ve orta bir yolculuk olsaydı (savaşa katılmayan o münafıklar), elbette sana tâbi olurlardı. Fakat güç aşılacak mesafe, kendilerine uzak geldi. Bir de \"Gücümüz yetseydi, sizinle beraber çıkardık!\" diye Allah’a yemin edecekler. Boşuna kendilerini mahvediyorlar. Allâh, onların yalancı olduklarını biliyor."},{"n":43,"t":"Allâh seni affetsin; doğru söyleyenler sana iyice belli olup, yalan söyleyenleri bilmezden önce niçin onlara izin verdin?"},{"n":44,"t":"Allah’a ve âhiret gününe inananlar; mallariyle, canlariyle, cihâd etmek(ten geri kalmaları) için senden izin istemezler. Allâh, korunanları bilir."},{"n":45,"t":"Ancak Allah’a ve âhiret gününe inanmayan, kalbleri kuşkuya düşmüş ve şüpheleri içinde bocalayıp duranlar, (geri kalmak için) senden izin isterler."},{"n":46,"t":"Eğer (cihâda) çıkmak isteselerdi, onun için bir hazırlık yaparladı. Fakat Allâh, onların davranışlarından hoşlanmadığı için onları durdurdu: \"Oturan(kadın ve çocuk)larla beraber oturun!\" denildi."},{"n":47,"t":"Sizin içinizde (sefere) çıkmış olsalardı, size bozgunculuktan başka bir katkıları olmazdı. Sizi birbirinize düşürmek için hemen aranıza sokulurlardı, içinizde de onlara kulak verenler vardı. Allâh zâlimleri bilir."},{"n":48,"t":"(Onlar) önceden de fitne çıkarmak istediler ve sana nice işleri ters çevirdiler. Nihâyet hak geldi, onlar istemedikleri halde Allâh’ın emri galebe çaldı."},{"n":49,"t":"İçlerinden öylesi var ki: \"Bana izin ver, beni fitneye düşürme\" der. İyi bilin ki, onlar zaten fitneye düşmüşlerdir. Cehennem de kâfirleri kuşatacaktır."},{"n":50,"t":"Sana bir iyilik ulaşsa (bu,) onların hoşuna gitmez ve eğer sana bir kötülük ulaşsa: \"Biz önceden (sefere katılmamakla) başımızın çaresine bakmışız\" derler, sevinerek döner(gider)ler."},{"n":51,"t":"De ki: \"Allâh, bizim için ne yazmış (ne takdir etmiş) ise ancak o, bize ulaşır, bizim sâhibimiz O’dur. İnananlar Allah’a dayansınlar.\""},{"n":52,"t":"De ki: \"Bize yalnız iki iyilikten (ya gâzilik veya şehidlikten) birini gözetmiyor musunuz? Ama biz, Allâh’ın size ya kendi tarafından veya bizim ellerimizle bir azâb ulaştırmasını gözetiyoruz. Haydi gözetin, biz de sizinle beraber gözetenleriz.\""},{"n":53,"t":"De ki: \"İster gönüllü, ister gönülsüz sadaka verin: sizden kabul edilmeyecektir. Çünkü siz yoldan çıkan bir kavimsiniz!\""},{"n":54,"t":"Sadakalarının kabul edilmesine engel olan sadece şudur: Onlar Allah’a ve elçisine karşı nankörlük ettiler; namaza da üşene üşene gelirler ve istemeye istemeye sadaka verirler."},{"n":55,"t":"Onların ne malları, ne de evlâdları seni imrendirmesin. Allâh bunlarla onlara dünyâ hayâtında azâbetmeyi ve kâfir olarak canlarının çıkmasını istiyor."},{"n":56,"t":"Sizden olduklarına Allah’a yemin ediyorlar. Oysa onlar sizden değiller, fakat onlar korkak bir topluluktur."},{"n":57,"t":"Eğer (sizden korunmak için) sığınacak bir yer, yahut (barınacak) mağaralar, ya da sokulacak bir delik bulsalardı, hemen oraya doğru koşarlardı."},{"n":58,"t":"Onlardan kimi de sadakalar(ın bölüştürülmesi hususun)da sana dil uzatır. Eğer o sadakalardan kendilerine pay verilse hoşlanırlar, onlardan kendilerine pay verilmezse hemen kızarlar."},{"n":59,"t":"(Ne olur) onlar, Allâh’ın ve Elçisinin kendilerine verdiğine râzı olup: \"Allâh bize yeter, yakında Allâh da bize bol lutfundan verecek, Elçisi de; biz sadece Allah’a rağbet ederiz (yalnız O’ndan umarız).\" deselerdi!"},{"n":60,"t":"Sadakalar, (zekâtlar) Allah’tan bir farz olarak ancak fakirlere, düşkünlere, onlar üzerinde çalışan (zekât toplayan) memurlara, kalbleri (İslâm’a) ısındırılacak olanlara, kölelik altında bulunanlara, borçlulara, Allâh yoluna ve yolcuya mahsustur (toplanan zekât, ancak bu sayılanlara verilir). Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":61,"t":"İçlerinden bazıları da Peygamberi incitirler: \"O, (her söyleneni dinleyen) bir kulaktır.\" derler. De ki: \"(O), sizin için hayır kulağıdır. Allah’a inanır, mü’minlere inanır. Sizden inananlar için de (O), bir rahmettir, Allâh’ın Elçisini incitenlere acı bir azâb vardır.\""},{"n":62,"t":"Gönlünüzü hoş etmek için size (gelip) Allah’a yemin ederler. Halbuki inanmış olsalardı, Allâh’ı ve Resulünü hoşnud etmeleri daha uygundu."},{"n":63,"t":"Bilmediler mi ki kim Allah’a ve Elçisine karşı koymağa kalkarsa onun için sürekli kalacağı cehennem ateşi vardır. İşte, büyük rezillik budur."},{"n":64,"t":"Münafıklar, kendileri hakkında, kalblerinde bulunanı kendilerine haber verecek bir sûrenin indirileceğinden çekiniyorlar. De ki; \"Siz alay edin, Allâh çekindiğiniz şeyi ortaya çıkaracaktır."},{"n":65,"t":"Eğer onlara sorsan: \"Biz sadece lafa dalmış, şakalaşıyorduk!\" derler. De ki: \"Allâh ile, O’nun âyetleriyle ve O’nun Elçisi ile mi alay ediyordunuz?\""},{"n":66,"t":"Hiç özür dilemeyin, siz inandıktan sonra inkâr ettiniz. Sizden bir kısmını affetsek bile suç işlediklerinden dolayı bir kısmına da azâb edeceğiz."},{"n":67,"t":"Münafık erkekler ve münafık kadınlar birbirlerindendir. Kötülüğü emrederler, iyilikten meneder ve ellerini sıkı tutarlar. Allâh’ı unuttular, O da onları unuttu. Münafıklar; işte yoldan çıkanlar onlardır."},{"n":68,"t":"Allâh münafık erkeklere ve münafık kadınlara ve kâfirlere içinde ebedi kalacakları cehennem ateşini va’detmiştir. O, onlara yeter. Allâh, onları la’netlemiştir. Onlar için sürekli bir azâb vardır."},{"n":69,"t":"(Siz de), sizden öncekiler gibi (yaptınız). Onlar kuvvetçe sizden daha yaman, mal ve evlâdça sizden daha çok idiler. Onlar, (dünyâ malından) kendi paylarına düşenle zevklerine baktılar, sizden öncekilerin, (dünyâdan) kendi paylarına düşenle zevklerine baktıkları gibi, siz de kendi payınıza düşenle zevkinize baktınız ve (bâtıla) dalanlar gibi siz de (bâtıla) daldınız. Onlar, eylemleri, dünyâ ve âhirette boşa gitmiş kimselerdir ve ziyana uğrayanlar da onlardır."},{"n":70,"t":"Onlara kendilerinden öncekilerin, Nûh, Âd, Semûd kavminin, İbrâhim kavminin, Medyen halkının ve başları üstüne ters dönen şehirlerin haberi gelmedi mi? Elçileri, onlara açık deliller getirmişti (Ama inanmadılar, bundan dolayı Allâh’ın gazabına uğradılar). Allâh onlara zulmediyor değildi, onlar kendi kendilerine zulmediyorlardı."},{"n":71,"t":"İnanan erkekler ve inanan kadınlar, birbirlerinin velisidirler. İyiliği emrederler, kötülükten men’ederler, namazı kılarlar, zekâtı verirler, Allah’a ve Elçisine itâ’at ederler. İşte onlara Allah rahmet edecektir. Allâh dâimâ üstündür, hüküm ve hikmet sâhibidir."},{"n":72,"t":"Allâh inanan erkeklere ve inanan kadınlara, altlarından ırmaklar akan, içinde ebedi kalacakları cennetler ve Adn cennetlerinde güzel meskenler va’detmiştir. Allâh’ın (onlardan) râzı olması ise hepsinden büyüktür. İşte büyük başarı budur."},{"n":73,"t":"Ey peygamber, kâfirlerle ve münafıklarla cihâd et, onlara sert davran; onların varacakları yer cehennemdir. Ne kötü bir gidiş yeridir o!"},{"n":74,"t":"(Senin aleyhinde söyledikleri yakışıksız sözleri) söylemediklerine Allah’a yemin ediyorlar. Halbuki o küfür sözünü söylediler, İslâm olduktan sonra inkâr ettiler, başaramadıkları bir şeye yeltendiler. Sırf Allâh ve Elçisi, Allâh’ın lutfiyle kendilerini zengin etti diye (şimdi) öc almağa kalktılar. (Allâh ve Elçisinin iyiliğine karşı böyle nankörlük ettiler.) Eğer tevbe ederlerse kendileri için daha iyi olur. Yok eğer (inkâr yoluna) dönerlerse Allâh onlara dünyâda da, âhirette de acı bir biçimde azâbedecektir. Yeryüzünde onların ne velisi, ne de yardımcısı vardır."},{"n":75,"t":"Kimileri de: \"Eğer Allâh, lutfundan bize verirse elbette sadaka vereceğiz ve yararlı insanlardan olacağız!\" diye Allah’a and içtiler."},{"n":76,"t":"Ne zaman ki Allâh lutfundan onlara verdi, O’n(un verdiğin)e cimrilik ettiler ve yüz çevirerek (sözlerinden) döndüler."},{"n":77,"t":"Kendisine verdikleri sözden döndüklerinden ve yalan söylediklerinden dolayı Allâh, kendisiyle karşılaşacakları güne kadar onların kalblerine iki yüzlülük sokmuştur."},{"n":78,"t":"Bilmediler mi ki Allâh, onların sırlarını ve gizli konuşmalarını bilir ve Allâh, gizlileri bilendir?"},{"n":79,"t":"Sadakalar hususunda gönülden veren mü’minleri çekiştiren ve güçlerinin yettiğinden başkasını bulamayanlarla alay edenler yok mu, Allâh onlarla alay etmiştir. Onlar için acı bir azâb vardır."},{"n":80,"t":"Onlar için ister af dile, ister dileme, onlar için yetmiş defa af dilesen, yine Allâh onları affetmez. Böyledir, çünkü onlar Allâh’ı ve Elçisini tanımadılar; Allâh, yoldan çıkan kavmi yola iletmez."},{"n":81,"t":"Allâh’ın Elçisinin arkasından oturmakla sevindiler, mallarıyle ve canlarıyle cihâdetmekten hoşlanmadılar: \"Sıcakta sefere çıkmayın.\" dediler. De ki: \"Cehennemin ateşi daha sıcaktır!\" Keşke anlasalardı!"},{"n":82,"t":"Artık kazandıkları işlere karşılık az gülsünler, çok ağlasınlar!"},{"n":83,"t":"Eğer Allâh, seni onlardan bir topluluğun yanına döndürür de (onlar savaşa) çıkmak için senden izin isterlerse \"Asla benimle çıkmayacaksınız, benimle beraber düşmanla savaşmayacaksınız. Siz ilk önce oturmağa râzı olmuştunuz. Öyle ise geri kalanlarla beraber oturun!\" de."},{"n":84,"t":"Ve Onlardan ölen birinin üzerine asla namaz kılma, onun kabri başında durma. Çünkü onlar Allâh’ı ve Elçisini tanımadılar ve yoldan çıkmış olarak öldüler."},{"n":85,"t":"Onların malları ve evlâdları seni imrendirmesin; Allâh onlara dünyâda, bunlarla azâbetmeyi ve kâfir olarak canlarının çıkmasını istiyor."},{"n":86,"t":"\"Allah’a inanın, Elçisiyle beraber cihâdedin!\" diye bir sûre indirildiği zaman içlerinden servet sâhibi olanlar, senden izin istediler: \"Bizi bırak, oturanlarla beraber oturalım.\" dediler."},{"n":87,"t":"Geride kalan kadınlarla beraber olmağa râzı oldular, kalbleri mühürlendi, artık onlar anlamazlar."},{"n":88,"t":"Fakat Elçi ve onunla beraber inananlar, mallariyle, canlariyle cihâdettiler. İşte bütün hayırlar onlarındır ve işte başarıya erenler onlardır."},{"n":89,"t":"Allâh, onlar için altlarından ırmaklar akan, içlerinde ebedi kalacakları cennetler hazırlamıştır. İşte büyük başarı budur."},{"n":90,"t":"Özür bahane eden bedevi Araplar, kendilerin(in savaşa katılmamasın)a izin verilmesi için geldiler; Allah’a ve Elçisine yalan söyleyenler oturdular. Onlardan inkâr edenlere, acı bir azâb erişecektir."},{"n":91,"t":"Zayıflara, hastalara, harcayacak bir şey bulamayanlara, Allâh ve Elçisi için öğüt verdikleri takdirde (sefere katılmamalarından ötürü) bir günâh yoktur. İyilik edenlerin aleyhine bir yol yoktur (onlar kınanmazlar). Allâh, bağışlayandır, esirgeyendir."},{"n":92,"t":"Kendilerini (binek sağlayıp) bindirmen için sana geldikleri zaman, sen: \"Sizi bindirecek bir şey bulamıyorum\" deyince harcayacak bir şey bulamadıklarından dolayı üzüntüden gözlerinden yaş akarak dönen kimselerin aleyhine de (yol yoktur, Onlar da kınanmazlar)."},{"n":93,"t":"Ancak şu kimselerin kınanmasına yol vardır ki, zengin oldukları halde (geri kalmak için) senden izin isterler. Geri kalan kadınlarla beraber olmağa râzı oldular. Allâh da onların kalblerini mühürledi; artık onlar bilmezler."},{"n":94,"t":"(Seferden) geri dönüp onların yanına geldiğiniz zaman sizden özür dilerler. De ki: \"Hiç özür dilemeyin, size inanmayız! Allâh bize sizin haberlerinizden (bize karşı çevirdiğiniz entrikalardan) bazılarını bildirdi. Yaptığınızı Allâh da görecek, Elçisi de. Sonra görülmeyeni ve görüleni bilenin huzûruna döndürüleceksiniz, O size yaptıklarınızı haber verecek.\""},{"n":95,"t":"Siz yanlarına geldiğiniz zaman kendilerinden vazgeçesiniz diye Allah’a yemin edecekler. Onlardan vazgeçin, çünkü onlar murdardır. Kazandıkları işlerin cezâsı olarak varacakları yer de cehennemdir."},{"n":96,"t":"Size yemin ediyorlar ki kendilerinden râzı olasınız. Siz onlardan râzı olsanız bile Allâh, yoldan çıkan topluluktan râzı olmaz."},{"n":97,"t":"Bedevi Araplar, küfür ve iki yüzlülükçe daha yaman ve Allâh’ın, Elçisine indirdiği şeylerin sınırlarını tanımamağa daha müsâittirler. Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":98,"t":"Bedevi Araplardan kimi var ki, verdiğini angarya sayar ve sizin başınıza belâlar gelmesini gözetler. Kötü belâ onların başına gelsin. Allâh işitendir, bilendir."},{"n":99,"t":"Bedevi Araplardan kimi de var ki Allah’a ve âhiret gününe inanır, verdiğini Allah’a yakın dereceler kazanmağa ve Elçinin du’âlarını almağa vesile sayar. Gerçekten o (verdikleri) kendileri için yakın dereceler(e vesile)dir. Allâh onları rahmetinin içine sokacaktır. Muhakkak ki Allâh bağışlayandır, esirgeyendir."},{"n":100,"t":"Muhâcirlerden ve Ensârdan (İslâm’a girmekte) ilk öne geçenler ile bunlara güzelce tabi olanlar... Allâh onlardan râzı olmuştur, onlar da O’ndan râzı olmuşlardır. (Allâh) onlara, altlarından ırmaklar akan, içinde ebedi kalacakları cennetler hazırlamıştır. İşte büyük kurtuluş budur."},{"n":101,"t":"Çevrenizdeki bedevi Araplardan ve Medine halkından iki yüzlülüğe iyice alışmış münâfıklar vardır. Sen onları bilmezsin, onları biz biliriz. Onlara iki kere azâb edeceğiz, sonra da onlar, büyük azâba itileceklerdir."},{"n":102,"t":"Başka bir kısmı da günâhlarını itiraf ettiler, iyi işle kötü işi birbirine karıştırdılar. Belki Allâh, onların tevbesini kabul eder. Çünkü Allâh bağışlayandır, esirgeyendir."},{"n":103,"t":"Onların mallarından, kendilerini temizleyeceğin, yücelteceğin bir sadaka al ve onlara du’â et; çünkü senin du’ân, onlara huzûr verir. Allâh işitendir, bilendir."},{"n":104,"t":"Bilmediler mi ki, kullarından tevbeyi kabul eden, sadakaları alan Allah’tır. Ve Allâh, tevbeyi çok kabul eden, çok esirgeyendir."},{"n":105,"t":"De ki: \"Yapın (yapacağınızı); yaptığınız işleri Allâh da görecek Elçisi de, mü’minler de. Sonra görülmeyeni ve görüleni bilen(Allâh)a döndürüleceksiniz. O size yaptıklarınızı bir bir haber verecek."},{"n":106,"t":"Başka bir takımları da var ki Allâh’ın emrine bırakılmışlardır. (Allâh) ya onlara azâbeder, ya da onları affeder. Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":107,"t":"(Seferden geri kalanlar arasında) Zarar vermek, nankörlük etmek, mü’minlerin arasını açmak ve önceden Allâh ve Elçisiyle savaşmış olan(adamın gelmesin)i gözetlemek için bir mescid yapanlar da var. \"İyilikten başka bir niyetimiz yoktu\" diye de yemin edecekler. Oysa Allâh onların yalan söylediklerine şâhittir."},{"n":108,"t":"Orada asla namaza durma, tâ ilk günden takvâ üzere kurulan mescid, elbette içinde namaza durmana daha uygundur. Onda temizlenmeyi seven erkekler vardır. Allâh da temizlenenleri sever."},{"n":109,"t":"Yapısını, Allah’tan korku ve rızâ üzerine kuran mı hayırlıdır, yoksa yapısını bir yarın kenarına kurup onunla birlikte cehennem ateşine yuvarlanan mı? Allâh zâlimler topluluğunu doğru yola iletmez."},{"n":110,"t":"Yaptıkları bina, kalbleri parçalanıncaya dek yüreklerinde bir kuşku olarak kalacaktır. Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":111,"t":"Allâh, mü’minlerden canlarını ve mallarını cennet kendilerinin olmak üzere satın almıştır. Allâh yolunda savaşırlar, öldürürler ve öldürülürler. Bu, Allâh’ın, Tevrât’ta, İncil’de ve Kur’ân’da üstlendiği gerçek bir sözdür! Kim Allah’tan daha çok sözünde durabilir? O halde O’nunla yaptığınız bu alışverişinizden ötürü sevinin. Gerçekten bu, büyük başarıdır."},{"n":112,"t":"Tevbe edenler, ibâdet edenler, hamdedenler, seyahat edenler, rükû edenler, secde edenler, iyiliği emredip kötülükten men’edenler ve Allâh’ın sınırlarını koruyanlar... İşte o mü’minleri müjdele (ne mutlu onlara)!"},{"n":113,"t":"Akrabâ bile olsalar, cehennem halkı oldukları belli olduktan sonra (Allah’a) ortak koşanlar için mağfiret dilemek; ne peygamberin, ne de inananların yapacağı bir iş değildir."},{"n":114,"t":"İbrâhim’in babası için mağfiret dilemesi, sadece ona verdiği bir sözden ötürü idi. Fakat onun, bir Allâh düşmanı olduğu, kendisine belli olunca ondan uzak durdu. Gerçekten İbrâhim, çok içli ve yumuşak huylu idi."},{"n":115,"t":"Allâh, bir kavmi doğru yola ilettikten sonra, sakınmaları gereken şeyleri kendilerine açıklamadıkça onları saptıracak değildir. Allâh herşeyi bilendir."},{"n":116,"t":"Göklerin ve yerin mülkü Allâh’ındır. Yaşatan, öldüren O’dur. Sizin Allah’tan başka bir dost ve yardımcınız yoktur."},{"n":117,"t":"Andolsun Allâh, Peygamberi ve o güçlük sâ’atinde ona uyan Muhâcirleri ve Ensârı affetti. O zaman içlerinden bir kısmının kalbleri kaymağa yüz tutmuş iken yine de onların tevbesini kabul buyurdu. Çünkü O, onlara karşı çok şefkatli, çok merhametlidir."},{"n":118,"t":"Ve (seferden) geri bırakılan o üç kişinin de tevbesini kabul buyurdu. Bütün genişliğiyle beraber dünyâ başlarına dar gelmiş ve canları sıkıldıkça sıkılmış ve Allah’tan, yine kendisine sığınmaktan başka çare olmadığını anlamışlardı. Allâh onların tevbesini kabul buyurdu ki tevbe etsinler. Çünkü Allâh, tevbeyi çok kabul eden, çok esirgeyendir."},{"n":119,"t":"Ey inananlar, Allah’tan korkun ve doğrularla beraber olun."},{"n":120,"t":"Ne Medine halkının, ne de onların çevresinde bulunan bedevi Arapların, Allâh’ın Elçisinden geri kalmaları ve onun canından önce kendi canlarının kaygısına düşmeleri, onlara yakışmaz. Böyledir, çünkü Allâh yolunda uğrayacakları hiçbir susuzluk, yorgunluk, açlık; kâfirleri öfkelendirecek bir yeri çiğne(yip zaptet)meleri ve düşmana karşı bir başarı kazanmaları yoktur ki mutlaka bunlarla kendilerine iyi bir amel yazılmış olmasın. Allâh güzel davrananların ecrini zayi etmez."},{"n":121,"t":"Küçük, büyük bir masraf yapmaları, bir vâdiyi geçmeleri, mutlaka onların lehine yazılır ki Allâh onları, yaptıklarının en güzeliyle mükâfâtlandırsın."},{"n":122,"t":"İnsanların hepsi toptan sefere çıkacak değillerdi. Ama her kabileden bir cemâatin dini iyice öğrenmeleri ve dönüp kavimlerine geldiklerinde, sakınmaları umuduyla onları uyarmaları için sefere çıkmaları gerekmez miydi?"},{"n":123,"t":"Ey inananlar, yakınınızda bulunan kâfirlerle savaşın, (onlar), sizde bir katılık bulsunlar. Bilin ki Allâh, korunanlarla beraberdir."},{"n":124,"t":"Ne zaman bir sûre indirilse onlardan kimi: \"Bu, hanginizin imanını artırdı?\" der. Bu, inananların imanını artırır, onlar sevinirler."},{"n":125,"t":"Fakat yüreklerinde hastalık olanlara gelince (bu), onların pisliklerine pislik katar. Ve onlar kâfir olarak ölürler."},{"n":126,"t":"Kendilerinin her yıl bir iki defa sınandıklarını görmüyorlar mı? Yine de tevbe etmiyor, öğüt almıyorlar."},{"n":127,"t":"Bir sûre indirildiği zaman: \"Sizi birisi görüyor mu?\" diye birbirine bakar, sonra sıvışırlar. Anlamaz bir topluluk oldukları için Allah onların kalblerini çevirmiştir."},{"n":128,"t":"Andolsun, içinizden size öyle bir Elçi geldi ki sıkıntıya uğramanız ona ağır gelir; size düşkün, mü’minlere şefkatli, merhametlidir."},{"n":129,"t":"Eğer yüz çevirirlerse de ki: \"Allâh bana yeter! O’ndan başka tanrı yoktur. O’na dayandım, O büyük Arş’ın sâhibidir!\""}],[{"n":1,"t":"Elif lâm râ. İşte şunlar, o hikmetli Kitâb’ın âyetleridir."},{"n":2,"t":"İçlerinden bir adama: \"İnsanları uyar ve inananlara, Rableri katında kendileri için bir doğruluk kademesi bulunduğunu müjdele!\" diye vahyettiğimiz, insanlara tuhaf mı geldi? kâfirler: \"Bu, apaçık bir büyücüdür.\" dediler."},{"n":3,"t":"Rabbiniz O Allah’tır ki, gökleri ve yeri altı günde yarattı, sonra Arş’a istivâ etti (kuruldu). Emri tebdir (buyruğunu) icra eder (yaratıklarını yönetir). O’nun izni olmadan hiç kimse şefâ’at edemez. İşte Rabbiniz Allâh budur. O’na kulluk edin, düşünmüyor musunuz?"},{"n":4,"t":"Hepinizin dönüşü, O’nadır. Bu, Allâh’ın gerçek olarak verdiği sözdür. O, yaratmağa başlar, sonra inanıp iyi işler yapanlara adâletle karşılık vermek için yeniden yaratır. İnkâr edenlere gelince, küfürlerinden dolayı onlara kaynar sudan bir içki ve acı bir azâb vardır."},{"n":5,"t":"Güneşi ziya, ay’ı nur yapan; yılların sayısını ve (vakitlerin) hesabı(nı) bilmeniz için aya (dolaşma) konaklar(ı) düzenleyen O’dur. Allâh, bunları (boş yere değil), gerçek ile (hikmeti uyarınca) yaratmıştır. Bilen bir kavim için âyetleri açıklamaktadır."},{"n":6,"t":"Gece ve gündüzün değişmesinde ve Allâh’ın göklerde ve yerde yarattığı şeylerde, korunan bir topluluk için nice ibretler vardır."},{"n":7,"t":"Bizimle buluşmayı ummayan, dünyâ hayâtına râzı olup onunla rahat edenler ve bizim âyetlerimizden gaflet edenler..."},{"n":8,"t":"İşte kazandıkları işlerden ötürü onların varacakları yer, ateştir!"},{"n":9,"t":"İnanıp iyi işler yapanlara gelince imanlarından dolayı Rableri, onları altlarından ırmaklar akan ni’met cennetlerine iletir."},{"n":10,"t":"Onların orada du’âsı: \"Allâh’ım Sen her türlü eksiklikten uzaksın!\", birbirlerine sağlık dilekleri: \"Selâm\", du’âlarının sonu da: \"Âlemlerin Rabbi Allah’a hamdolsun!\" sözleridir."},{"n":11,"t":"İnsanların, hayrı acele istemeleri gibi, Allâh da onlara şerri acele verseydi, süreleri hemen bitirilmiş olurdu. Ama biz, bizimle buluşmayı ummayanları bırakırız, azgınlıkları içinde bocalar, dururlar."},{"n":12,"t":"İnsana bir darlık dokunduğu zaman, yanı üzere yatarken, yahut otururken ya da ayakta bize yalvarır; ama biz onun darlığını aç(ıp kaldır)ınca sanki kendisine dokunan bir darlıktan ötürü bize hiç yalvarmamış gibi hareket eder. İşte aşırı gidenlere, yaptıkları iş böylesine süslü gösterilmiştir."},{"n":13,"t":"Sizden önce, zulmettikleri ve peygamberleri kendilerine açık kanıtlar getirdikleri halde inanmadıkları için nice nesilleri helâk etmişizdir. İşte suç işleyen kavmi böyle cezâlandırırız."},{"n":14,"t":"Sonra onların ardından, bu dünyâda onların yerine sizi geçirdik ki, sizin de nasıl davranacağınızı görelim."},{"n":15,"t":"Onlara açık açık âyetlerimiz okunduğu zaman, bizimle buluşmayı ummayanlar: \"Bundan başka bir Kur’ân getir veya bunu değiştir.\" derler. De ki: \"Onu kendi tarafımdan değiştiremem. Ben sadece bana vahyolunana uyarım. Şâyet ben Rabbime karşı gelirsem, büyük bir günün azâbından korkarım.\""},{"n":16,"t":"De ki: \"Eğer Allâh dileseydi, onu size okumazdım ve onu size hiç bildirmezdi. Ben ondan önce aranızda bir ömür boyu kalmıştım (böyle bir şey yapmamıştım), düşünmüyor musunuz?\""},{"n":17,"t":"Uydurduğu yalanı Allâh’ın üzerine atan, yahut O’nun âyetlerini yalanlayandan daha zâlim kim olabilir? Şüphesiz suçlular asla onmazlar."},{"n":18,"t":"Allâh’ı bırakıp kendilerine ne zarar, ne de yarar veremeyen şeylere tapıyorlar ve: \"Bunlar Allâh katında bizim şefâ’atçilerimizdir!\" diyorlar. De ki: \"Allâh’ın, göklerde ve yerde bilmediği bir şeyi mi Allah’a haber veriyorsunuz?\" O, onların koştukları ortaklardan uzak ve yücedir."},{"n":19,"t":"İnsanlar bir tek milletten başka bir şey değildi, ama ayrılığa düştüler. Eğer Rabbinden bir söz geçmemiş olsaydı, ayrılığa düştükleri konuda hemen aralarında hüküm verilir(işleri bitirilir)di."},{"n":20,"t":"\"Ona Rabbinden bir mu’cize indirilmeli değil mi?\" diyorlar. De ki: \"Gayb Allâh’ındır (görülmeyeni bilen O’dur). Bekleyin, ben de sizinle beraber bekleyenlerdenim.\""},{"n":21,"t":"Kendilerine dokunan bir darlıktan sonra insanlara bir rahmet (sağlık ve bolluk zevkini) taddırdığımız zaman bakarsın ki, yine onların, âyetlerimiz hakkında bir tuzakları vardır. De ki: \"Allâh daha çabuk tuzak kurar!\" Elçilerimiz, sizin kurduğunuz tuzakları yazıyorlar."},{"n":22,"t":"Sizi karada ve denizde yürüten O’dur. Gemide olduğunuz zaman(ı düşünün): Gemiler, içinde bulunanları hoş bir rüzgârla alıp götürdüğü, ve (yolcular) bununla sevindikleri sırada, birden gemiye, şiddetli bir kasırga gelip de, her yerden gelen dalgalar onları sardığı ve artık kendilerinin tamamen kuşatıldıklarını (bir daha kurtulamayacaklarını) sandıkları zaman, dini, yalnız Allah’a hâlis kılarak O’na şöyle yalvarmağa başlarlar: \"Andolsun, eğer bizi bundan kurtarırsan, şükredenlerden olacağız.\""},{"n":23,"t":"Ama (Allâh) onları kurtarınca hemen yeryüzünde haksız yere taşkınlık yaparlar. Ey insanlar, taşkınlığınız kendi aleyhinizedir. Sadece şu yakın (geçici) hayâtın zevkinden ibârettir. Sonra dönüşünüz bizedir; size bütün yaptıklarınızı haber veririz."},{"n":24,"t":"Şu yakın hayât, tıpkı gökten indirdiğimiz bir suya benzer: İnsanların ve hayvanların yediği arz bitkisi o su ile karıştı: nihâyet yer zinetini takınıp süslendiği ve halkı da on(un ürününü devşirmeğ)e kâdir olduklarını zannettikleri sırada birden buyruğumuz ona gece veya gündüz geldi; sanki dün o hiç (bitkisiyle süslenip) şenlenmemiş gibi, onu biçilmiş yaptık (süsünü, zenginliğini biçtik, yok ettik). İşte biz, düşünen bir toplum için âyetleri böyle geniş geniş açıklarız."},{"n":25,"t":"Allâh; esenlik yurduna çağırır ve dilediğini doğru bir yola iletir."},{"n":26,"t":"Güzel davrananlara daha güzel karşılık ve fazlası var. Onların yüzlerine ne bir kara bulaşır, ne de horluk. İşte onlar cennet halkıdır, orada ebedi kalacaklardır."},{"n":27,"t":"Kötü işler yapanlara da (yaptıkları) kötülüğün aynen cezâsı verilir. Ve onların yüzlerini bir horluk kaplar. Onları Allah’tan kurtaracak hiç kimse yoktur. Sanki yüzleri, karanlık geceden parçalara bürünmüştür. İşte onlar da ateş halkıdır, hep orada kalacaklardır."},{"n":28,"t":"O gün onları hep bir araya toplarız, sonra ortak koşanlara; \"Haydi siz ve koştuğunuz ortaklar yerlerinize!\" deriz. Artık (tanrılariyle) aralarını açmışızdır (dünyâdaki gibi aralarında bir bağ kalmamıştır). Koştukları ortaklar: \"Siz bize tapmıyordunuz?\" demektedirler."},{"n":29,"t":"\"Şimdi bizimle sizin aranızda Allâh’ın şâhid olması yeter; doğrusu biz sizin (bize) tapmanızdan tamamen habersizdik!\""},{"n":30,"t":"İşte orada her can, geçmişte yaptıklarını dener (yaptıklarının yararını ve zararını görür). Gerçek sâhipleri olan Allah’a döndürülürler ve uydurdukları şeyler, kendilerinden kaybolup gider."},{"n":31,"t":"De ki: \"Sizi gökten ve yerden kim rızıklandırıyor? Ya da o kulak(lar)ın ve gözlerin sâhibi kimdir? Ölüden diriyi, diriden ölüyü kim çıkarıyor? Kim buyruğu(nu) yürütüyor (kâinâtı yönetiyor)?\" \"Allâh.\" diyecekler. \"O halde, korunmuyor musunuz?\" de."},{"n":32,"t":"İşte sizin gerçek Rabbiniz Allâh budur. Gerçekten sonra sapıklıktan başka ne var? Öyleyse nasıl (hak’tan sapıklığa) çevriliyorsunuz?"},{"n":33,"t":"Böylece Rabbinin, yoldan çıkanlar için söylediği: \"Onlar inanmazlar.\" sözü, gerçekleşti."},{"n":34,"t":"De ki: \"Sizin koştuğunuz ortaklardan ilk defa yaratacak, sonra onu çevirip yeniden yaratacak olan var mı?\" De ki: \"Allâh ilk defa yaratır, sonra onu çevirip yeniden yaratır. Öyleyse nasıl (doğru yoldan) çevriliyorsunuz?\""},{"n":35,"t":"De ki: \"Sizin ortaklarınızdan hakka götürecek var mı?\" De ki: \"Allâh, hakka götürür. Hakka götüren mi uyulmağa daha lâyıktır, yoksa (tutulup) yola götürülmedikçe kendisi doğru yolu bulamayan mı? O halde neyiniz var? Nasıl hükmediyorsunuz?\""},{"n":36,"t":"Onların çoğu, zandan başka bir şeye uymuyorlar. Zan ise gerçekten hiçbir şey kazandırmaz. Muhakkak ki Allâh, onların ne yaptıklarını bilir."},{"n":37,"t":"Bu Kur’ân, Allah’tan başkası tarafından uydurulacak bir şey değildir. Ancak kendinden öncekinin doğrulaması ve Kitabın açıklamasıdır. Onda asla şüphe yoktur. Âlemlerin Rabbi tarafından(indirilmiş)dir."},{"n":38,"t":"Yoksa \"Onu uydurdu\" mu diyorlar? De ki: \"Eğer doğru iseniz haydi onun benzeri bir sûre getirin ve Allah’tan başka çağırabildiklerinizi de çağırın!\""},{"n":39,"t":"Hayır, bilgisini kavrayamadıkları, sonucu henüz başlarına gelmemiş olan bir şeyi yalanladılar. Onlardan öncekiler de böyle yalanlamışlardı. Bak, o zâlimlerin sonu nice oldu?"},{"n":40,"t":"Onlardan kimi, ona inanır, kimi de inanmaz. Rabbin bozguncuları çok iyi bilir."},{"n":41,"t":"Eğer onlar seni yalanladılarsa de ki: \"Benim yaptığım bana, sizin yaptığınız size. Siz benim yaptığımdan uzaksınız, ben de sizin yaptığınızdan uzağım!\""},{"n":42,"t":"İçlerinden sana kulak verip dinleyenler de vardır. Fakat sağırlara sen mi duyuracaksın? Hele akıllarını da kullanmıyorlarsa!"},{"n":43,"t":"İçlerinden sana bakanlar da var. Fakat körleri sen mi yola götüreceksin? Hele sezgileriyle de görmüyorlarsa?"},{"n":44,"t":"Allâh insanlara hiç zulmetmez, fakat insanlar kendi kendilerine zulmediyorlar."},{"n":45,"t":"Onları bir araya toplayacağı gün, sanki onlar sadece gündüzün, görüşüp, tanıştıkları bir sâ’ati kadar dünyâda kalmış olurlar. Allâh’ın huzûruna çıkmayı yalanlayıp, yola gelmemiş olanlar, en büyük ziyana uğramışlardır."},{"n":46,"t":"Ya onları uyardığımız şeylerin bir kısmını sana gösteririz. Ya da (bundan önce) seni vefat ettiririz (farketmez). Nasıl olsa dönüşleri bizedir. Sonra Allâh onların yaptıklarına da şâhiddir."},{"n":47,"t":"Her ümmetin bir elçisi vardır. Elçileri gel(ip de bunlar onu yalanlay)ınca aralarında adâletle hükmolunur, onlara hiç haksızlık edilmez."},{"n":48,"t":"\"Doğru iseniz bu bizi tehdid (ettiğiniz) azâb ne zaman?\" diyorlar."},{"n":49,"t":"De ki: \"Ben kendime dahi, Allâh’ın dilediğinden başka, ne zarar, ne de yarar verme gücüne sâhip değilim. Her ümmetin bir süresi vardır. Süreleri gelince ne bir an geri kalırlar, ne de ileri giderler.\""},{"n":50,"t":"De ki: \"Bakın, eğer O’nun azâbı size geceleyin, ya da gündüzün gelirse... Suçlular bun(lar)dan hangisini acele istiyor?\""},{"n":51,"t":"(Azâb) başınıza geldikten sonra mı ona inanacaksınız? Şimdi mi (inandınız)? Hani ya siz onu çabuk isteyip duruyordunuz (nasılmış)?"},{"n":52,"t":"Sonra zulmedenlere: \"Sürekli azâbı tadın!\" denilecek, \"Yalnız kazandığınız şeylerle cezâlandırılmıyor musunuz?\""},{"n":53,"t":"\"Sahiden o gerçek midir?\" diye senden soruyorlar. De ki: \"Evet, Rabbim hakkı için o gerçektir. Siz (onu) önleyemezsiniz!\""},{"n":54,"t":"(O zaman), kendisine zulmeden her kişi, yeryüzünde ne varsa hepsi kendisinin olsaydı (azâbdan kurtulmak için) onu fidye verirdi. Azâbı gördükleri zaman, içlerinde pişmanlık duyarlar, aralarında adâletle hükmedilir, asla haksızlığa uğratılmazlar."},{"n":55,"t":"İyi bil ki, göklerde ve yerde ne varsa hepsi Allâh’ındır. İyi bil ki Allâh’ın va’di gerçektir, fakat çokları bilmiyorlar."},{"n":56,"t":"O, yaşatır, öldürür ve siz O’na döndürülüp götürüleceksiniz."},{"n":57,"t":"Ey insanlar, size Rabbinizden bir öğüt, göğüslerde olan(sıkıntılar)a şifa ve inananlara bir yol gösterici ve rahmet gelmiştir."},{"n":58,"t":"De ki: \"Allâh’ın lutfiyle, rahmetiyle (evet) ancak onunla ferahlansınlar. O onların toplayıp yığdıklarından hayırlıdır.\""},{"n":59,"t":"De ki: \"Gördünüz mü, Allâh’ın size rızık olarak indirdiği şeylerin bir kısmını harâm ve bir kısmını helâl yaptınız.\" De ki: \"Allâh mı size böyle izin verdi, yoksa siz Allah’a iftirâ mı ediyorsunuz?\""},{"n":60,"t":"Allah’a yalan uyduranların kıyâmet günü hakkındaki zanları nedir? Muhakkak ki Allâh, insanlara karşı lutuf sâhibidir, ama çokları şükretmiyorlar."},{"n":61,"t":"Ne işte bulunsan, Kur’ân’dan ne okusan ve siz ne iş yapsanız mutlaka biz, içine daldığınız an üzerinizde şâhidiz (her yaptığınızı görürüz). Ne yerde, ne de gökte zerre ağırlığınca bir şey, Rabbin(in bilgisin)den kaçmaz. Ne bundan küçük, ne de büyük hiçbir şey yoktur ki, hepsi apaçık bir Kitapta olmasın."},{"n":62,"t":"İyi bil ki, Allâh’ın velilerine (sevdiklerine) korku yoktur ve onlar üzülmeyeceklerdir."},{"n":63,"t":"Onlar ki, inandılar ve korunurlardı."},{"n":64,"t":"Dünyâ hayâtında da, âhirette de müjde onlara! Allâh’ın kelimeleri değişmez (O’nun verdiği söz, mutlaka yerine getirilir). İşte bu, büyük kurtuluştur."},{"n":65,"t":"Onların sözü seni üzmesin, üstünlük tamamen Allâh’ındır. İşiten ve bilen O’dur."},{"n":66,"t":"İyi bilki, göklerde ve yerde kim varsa hepsi Allâh’ındır. Allah’tan başkasına yalvaranlar (gerçekte koştukları) ortaklara uymuyorlar, onlar sadece zanna uyuyorlar, (hayallerine kapılıyorlar) ve onlar sadece saçmalıyorlar."},{"n":67,"t":"Geceyi sizin istirahat etmenize elverişli, gündüzü de (geçiminizi sağlamanız için) aydınlık yapan O’dur. Şüphesiz, bunda işiten bir toplum için ibretler vardır."},{"n":68,"t":"\"Allâh, çocuk edindi,\" dediler. Hâşâ, Allâh bundan uzaktır, O zengindir (hiçbir şeye muhtaç değildir). Göklerde ve yerde ne varsa hepsi O’nundur. Bu hususta hiçbir deliliniz yok. Allâh hakkında bilmediğiniz şeyi mi söylüyorsunuz?"},{"n":69,"t":"De ki: \"Allâh hakkında yalan uyduranlar, iflâh olmazlar!\""},{"n":70,"t":"Dünyâda biraz geçinir, sonra bize dönerler. Sonra da biz, inkârlarından dolayı onlara şiddetli azâbı taddırırız."},{"n":71,"t":"Onlara Nûh’un haberini oku. Kavmine: \"Ey kavmim demişti, eğer benim kalkıp size Allâh’ın âyetlerini hatırlatmam, size ağır geldiyse, o halde ben Allah’a dayandım, siz de ortaklarınızla beraber toplanıp yapacağınız işi kararlaştırın da işiniz başınıza dert olmasın. Sonra hükmünüzü bana uygulayın, bana hiç fırsat da vermeyin!\""},{"n":72,"t":"\"Eğer yüz çevirdiyseniz (neden?), ben sizden bir ücret istemedim ki! Benim ücretim, ancak Allâh’ın üzerinedir. Bana müslümanlardan olmam emredilmiştir.\""},{"n":73,"t":"Yine de onu yalanladılar. Biz de onu ve gemide onunla beraber bulunanları kurtardık, onları egemen yaptık ve âyetlerimizi yalanlayanları da boğduk. Bak işte uyarıl(ıp da yola gelmey)enlerin sonu nice oldu!"},{"n":74,"t":"Sonra onun ardından bir çok elçileri kavimlerine gönderdik; onlara; belgeler getirdiler. (Fakat onlar) önce yalanlamış oldukları şeye bir türlü inanmıyorlardı. İşte haddi aşanların kalblerini böyle mühürleriz."},{"n":75,"t":"Sonra onların ardından Mûsâ ve Hârûn’u âyetlerimizle birlikte Fir’avn’a ve adamlarına gönderdik; böbürlendiler ve suç işleyen bir topluluk oldular."},{"n":76,"t":"Onlara katımızdan gerçek gelince: \"Bu, apaçık bir büyüdür.\" dediler."},{"n":77,"t":"Mûsâ: \"Size gelen gerçek için böyle mi diyorsunuz? Büyü müdür bu? Halbuki büyücüler, iflah olmazlar!\" dedi."},{"n":78,"t":"Dediler ki: \"Sen bizi, babalarımızı üzerinde bulduğumuz şeyden çeviresin de yeryüzünde büyüklük yalnız ikinize kalsın diye mi geldin? Biz size inanacak değiliz!\""},{"n":79,"t":"Fir’avn: \"Bana bütün bilgili büyücüleri getirin.\" dedi."},{"n":80,"t":"Büyücüler gelince Mûsâ onlara: \"Atacağınızı atın (hünerinizi gösterin).\" dedi."},{"n":81,"t":"Onlar (iplerini ve değneklerini atınca) Mûsâ; \"Sizin getirdiğiniz şey, büyüdür, dedi. Allâh, onu mutlaka boşa çıkaracaktır. Çünkü Allâh bozguncuların işini düzeltmez!\""},{"n":82,"t":"\"Ve suçlular istemese de Allâh, sözleriyle gerçeği ortaya çıkaracaktır!\""},{"n":83,"t":"Fir’avn’ın ve adamlarının, kendilerine kötülük yapmasından korktukları için kavminin içinde Mûsâ’ya, yalnız genç bir kuşaktan başkası inanmadı. Çünkü Fir’avn, yeryüzünde çok ululanan ve çok aşırı gidenlerden idi."},{"n":84,"t":"Mûsâ dedi ki: \"Ey kavmim, eğer Allâh’a inandıysanız, gerçekten müslüman insanlar iseniz o’na dayanın.\""},{"n":85,"t":"Dediler ki: \"Allâh’a dayandık, Rabbimiz bizi o zulmeden kavme fitne yapma (bizi onların işkencesiyle deneme)!"},{"n":86,"t":"\"Acımanla bizi o inkârcı toplumdan kurtar.\""},{"n":87,"t":"Mûsâ’ya ve kardeşine \"İkiniz kavminiz için Mısır’da evler hazırlayın (ey İsrâil oğulları) evlerinizi karşı karşıya kurun, namaz kılın ve (ey Mûsâ) mü’minleri müjdele\" diye vahyettik."},{"n":88,"t":"Mûsâ: \"Rabbimiz dedi, sen Fir’avn’a ve adamlarına yakın hayâtta süs ve nice mallar verdin. Rabbimiz, senin yolundan saptırsınlar diye mi? Rabbimiz, onların mallarını yok et, kalblerini sık ki, acı azâbı görünceye kadar inanmasınlar!\""},{"n":89,"t":"(Allâh): \"ikinizin du’âsı kabul olundu,\" dedi, \"doğru olun, bilmezlerin yoluna uymayın.\""},{"n":90,"t":"İsrâil oğullarını denizden geçirdik, Fir’avn ve askerleri de zulmetmek ve saldırmak için onların arkalarına düştü. Nihâyet boğulma kendisini yakalayınca (Fir’avn): \"Gerçekten İsrâil oğullarının inandığından başka tanrı olmadığına inandım, ben de müslümanlardanım!\" dedi."},{"n":91,"t":"\"Şimdi mi? Oysa daha önce isyân etmiş, bozgunculardan olmuştun?\" (denildi)."},{"n":92,"t":"\"Bugün senin (canından ayırdığımız) bedenini, (denizin dibinden) kurtarıp (sahilde) bir tepeye atacağız ki senden sonra gelenlere ibret olasın. Ama insanlardan çoğu bizim âyetlerimizden gâfildirler.\""},{"n":93,"t":"Andolsun biz, İsrâil oğullarını iyi bir yere yerleştirdik ve onlara güzel rızıklar verdik. Kendilerine ilim gelinceye kadar ayrılığa düşmediler (de bilgi geldikten sonra ayrılığa düştüler). Şüphesiz Rabbin, kıyâmet günü, anlaşmazlığa düştükleri şey hakkında aralarında hüküm verecektir."},{"n":94,"t":"Eğer sen, sana indirdiğimizden kuşkuda isen, senden önce Kitabı okuyanlara sor. Andolsun, sana Rabbinden hak geldi, sakın kuşkulananlardan olma!"},{"n":95,"t":"Ve sakın Allâh’ın âyetlerini yalanlayanlardan olma, yoksa ziyana uğrayanlardan olursun."},{"n":96,"t":"Üzerlerine Rabbinin (azâb) kelimesi hak olanlar inanmazlar."},{"n":97,"t":"Onlara bütün âyetler gelmiş olsa bile, acı azâbı görünceye kadar (inanmazlar)."},{"n":98,"t":"Keşke bir kasaba olsaydı da inansaydı ve inanması kendisine fayda verseydi! Yalnız Yûnus’un kavmi, inanınca, dünyâ hayatında onlardan rezillik azâbını kaldırmış ve onları bir süre daha yaşatmıştık."},{"n":99,"t":"Rabbin isteseydi, yeryüzündekilerin hepsi mutlaka inanırdı. O halde sen mi insanları inanmaları için zorlayacaksın?"},{"n":100,"t":"Allâh’ın izni olmadan hiç kimse inanmaz ve (Allâh) pisliği (huzursuzluğu, azâbı), akıllarını kullanmayanların üzerine kor."},{"n":101,"t":"\"Göklerde ve yerde olanlara bakın!\" de; ama o âyetler ve uyarılar, inanmayacak bir kavme yarar sağlamaz."},{"n":102,"t":"Onlar sadece kendilerinden önce gelip geçenlerin başlarına gelen günler gibisini bekliyorlar öyle mi? De ki: \"O halde bekleyin, ben de sizinle beraber bekleyenlerdenim!\""},{"n":103,"t":"Sonunda elçilerimizi ve inananları kurtarırız. İşte böyle, üzerimize bir borç olarak mü’minleri kurtarırız."},{"n":104,"t":"De ki: \"Ey insanlar, benim dinimden kuşkuda iseniz, ben sizin, Allah’tan başka taptıklarınıza tapmam; fakat sizi öldürecek olan Allah’a taparım. Bana mü’minlerden olmam emredilmiştir.\""},{"n":105,"t":"Ve: \"Yüzünü hanif (Allâh’ı birleyici) olarak dine çevir; sakın (Allah’a) ortak koşanlardan olma!\""},{"n":106,"t":"\"Allah’tan başka; sana ne fayda, ne de zarar veremeyecek olan şeylere yalvarma! Eğer böyle yaparsan, o takdirde sen muhakkak zâlimlerden olursun.\" (diye emredilmiştir)."},{"n":107,"t":"Eğer Allâh sana bir zarar dokundursa onu, yine O’ndan başka kaldıracak yoktur ve eğer sana bir hayır dilese, O’nun keremini de geri çevirecek yoktur. Hayrını, kullarından dilediğine verir. O, bağışlayandır, esirgeyendir."},{"n":108,"t":"De ki: \"Ey insanlar, işte size Rabbinizden gerçek geldi. Artık yola gelen, kendisi için gelir; sapan da kendi zararına sapar. Ben sizin üzerinize vekil değilim!\""},{"n":109,"t":"Sana vahyolunana uy ve Allâh hükmünü verinceye kadar sabret. O, hüküm verenlerin en iyisidir."}],[{"n":1,"t":"Elif lâm râ. (Bu,) bir Kitaptır ki, hikmet sâhibi, herşeyden haberi olan (Allâh) tarafından âyetleri sağlamlaştırılmış ve güzelce açıklanmıştır."},{"n":2,"t":"Tâ ki Allah’tan başkasına tapmayasınız. Ben de, O’ndan size (gönderilmiş) bir uyarıcı ve müjdeleyiciyim."},{"n":3,"t":"Ve Rabbinizden mağfiret dileyesiniz, sonra O’na tevbe edesiniz ki, sizi belirtilmiş bir süreye kadar güzelce yaşatsın ve her lutuf sâhibine lutfetsin. Ve eğer yüz çevirirseniz, ben sizin için büyük bir günün azâbından korkarım."},{"n":4,"t":"Dönüşünüz Allaha’dır. O, herşeyi yapacak güçtedir."},{"n":5,"t":"İyi bilin ki, onlar O’ndan gizlenmek için göğüslerini bükerler. Yine iyi bilin ki onlar, örtülerine büründükleri zaman dahi (Allâh onların) içlerinde gizlediklerini ve açığa vurduklarını bilir. Çünkü O, göğüslerin özünü bilendir."},{"n":6,"t":"Yeryüzünde hiçbir canlı yoktur ki, rızkı Allah’a âit olmasın. (Allâh) onun durduğu ve emânet bırakıldığı yeri bilir. Bunların hepsi apaçık bir kitaptadır."},{"n":7,"t":"Gökleri ve yeri altı günde yaradan O’dur. O zaman Arş’ı su üzerinde idi. (Bu kâinâtı yarattı) Ki, hanginizin daha güzel iş yaptığınızı denesin. Böyle iken yine sen: \"Öldükten sonra diriltileceksiniz\" desen, inkâr edenler, mutlaka: \"Bu, apaçık bir büyüden başka bir şey değildir.\" derler."},{"n":8,"t":"Andolsun onlardan azâbı sayılı bir ümmete (belli bir süreye) ertelesek, \"Onu tut(up bize gelmesine engel ol)an nedir?\" derler. İyi bilin ki, o (azâb) başlarına geldiği gün, bir daha onlardan geri çevrilmez ve alay ettikleri şey, kendilerini kuşatmış olur."},{"n":9,"t":"Eğer biz insana, bizden bir rahmet taddırsak da sonra onu kendisinden çekip alsak, hemen o, umutsuzluğa düşer, nankör olur."},{"n":10,"t":"Ve eğer kendisine dokunan bir zarardan sonra ona bir ni’met taddırsak, mutlaka: \"Kötülükler benden gitti\" der, sevinir, övünür."},{"n":11,"t":"Ancak sabredip iyi işler yapanlar böyle değildir. İşte onlar için mağfiret ve büyük mükâfât vardır."},{"n":12,"t":"Herhalde sen: \"Ona bir hazine indirilmeli veya beraberinde bir melek gelmeli değil miydi?\" demelerinden ötürü, sana vahyolunanın bir kısmını bırakacaksın ve bununla göğsün sıkılacak; ama sen sadece bir uyarıcısın (böyle sözlere aldırma), her şeye vekil olan Allah’tır."},{"n":13,"t":"Yoksa, \"O’nu uydurdu\" mu diyorlar? De ki: \"Öyleyse siz de onun benzeri on uydurulmuş sûre getirin; eğer doğru iseniz Allah’tan başka, çağırabildiklerinizi de (yardıma) çağırın (da bunu yapın)!\""},{"n":14,"t":"Eğer size cevap veremedilerse bilin ki (o) Allâh’ın bilgisiyle indirilmiştir ve O’ndan başka tanrı yoktur. Nasıl, artık müslüman oldunuz mu?"},{"n":15,"t":"Kimler dünyâ hayâtını ve süsünü isterse onlara oradaki amellerin(in karşılığın)ı tam veririz ve onlar orada hiçbir eksikliğe uğratılmazlar."},{"n":16,"t":"Ama onlar öyle kimselerdir ki âhirette onlar için ateşten başka bir şey yoktur ve yaptıklarının hepsi orada boşa çıkmıştır, amelleri hep bâtıl olmuştur!"},{"n":17,"t":"Hiç böyleleri, şu kimse gibi olur mu ki, o Rabbinden bir delil üzerinde bulunur, ayrıca O’ndan bir şâhid de onu takib eder. O(Hak şâhidi Kur’a)n’dan önce de bir önder ve rahmet olarak Mûsâ’nın Kitabı var. İşte onlar O(Kur’â)n’a inanırlar. Topluluklardan kim onu inkâr ederse, onun yeri ateştir! O(Kur’â)n’dan hiç kuşkun olmasın. Muhakkak o, Rabbinden gelen gerçektir. Fakat insanların çoğu inanmazlar."},{"n":18,"t":"Allah’a yalan uyduranlardan daha zâlim kim olabilir? Onlar Rablerine sunulacaklar. Şâhidler de: \"İşte Rablerine karşı yalan söyleyenler bunlardır!\" diyecekler. İyi bilin ki Allâh’ın la’neti zâlimlerin üzerinedir."},{"n":19,"t":"Onlar ki Allâh’ın yoluna engel olurlar ve onu eğriltmek isterler ve onlar, (evet) onlar, âhireti de tanımazlar."},{"n":20,"t":"Onlar dünyâda Allâh’ı âciz bırakacak değillerdir. Ve onların Allah’tan başka dostları da yoktur. Onlar için azâb kat kat yapılır. Çünkü (gerçeği) işitmeğe tahammül edemezlerdi ve (onu) görmezlerdi."},{"n":21,"t":"İşte onlar canlarını ziyana sokan kimselerdir. Ve uydurdukları şeyler, kendilerinden kaybolup gitmiştir."},{"n":22,"t":"Elbette âhirette en çok ziyana uğrayanlar onlardır."},{"n":23,"t":"İnanıp iyi işler yapan ve Rablerine gönülden boyun eğenlere gelince; işte onlar da cennet halkıdır, onlar orada ebedi kalacaklardır."},{"n":24,"t":"Bu iki zümrenin durumu, kör ve sağır ile gören ve işiten gibidir. Bunlar bir olur mu hiç? Hâlâ ibret almaz mısınız?"},{"n":25,"t":"Andolsun biz Nûh’u da kavmine gönderdik: \"Ben sizin için apaçık bir uyarıcıyım.\""},{"n":26,"t":"\"Allah’tan başkasına tapmayın. Gerçekten ben, sizin, acı bir günün azâbına uğramanızdan korkuyorum.\" (dedi)."},{"n":27,"t":"Kavminden ileri gelen inkârcı grup dedi ki: \"Biz seni de bizim gibi insan görüyoruz ve sana bizim basit görüşlü ayak takımlarımızdan başkasının uyduğunu görmüyoruz. Sizin bize karşı bir üstünlüğünüzü de görmüyoruz; tersine sizi yalancı sanıyoruz!\""},{"n":28,"t":"Dedi ki: \"Ey kavmim, bakın, ya ben Rabbimden bir delil üzerinde isem ve (O), kendi katından bana bir rahmet vermiş de, o (rahmet) sizin gözlerinizden gizli bırakılmış ise? Şimdi siz onu istemezken, biz sizi o(Tanrı rahmeti)ne zorla mı sokacağız?\""},{"n":29,"t":"\"Ey kavmim, buna karşı ben sizden bir mal istemiyorum, benim ücretim Allah’a âittir. Ve (siz istemiyor, hor görüyorsunuz diye) ben, inananları (yanımdan) kovacak değilim. Çünkü onlar Rablerinin huzûruna gidecek(yaptıklarının hesabını verecek)lerdir. (Herkes kendi amelinden sorumludur. Onları niçin kovayım?) Fakat ben sizi, câhillik eden bir kavim görüyorum.\""},{"n":30,"t":"\"Ey kavmim, ben onları kovarsam, Allah’a karşı beni kim savunur? Düşünmüyor musunuz?\""},{"n":31,"t":"Ben size: \"Allâh’ın hazineleri benim yanımdadır.\" demiyorum. Gaybı da bilmem. \"Ben meleğim,\" de demiyorum. Sizin gözlerinizin hor gördüğü kimseler için \"Allâh onlara bir hayır vermeyecek\" de demem. Allâh, onların içlerinde olanı daha iyi bilir. Böyle bir şey yaptığım takdirde ben, mutlaka zâlimlerden olurum.\""},{"n":32,"t":"Dediler ki: \"Ey Nûh, bizimle mücâdele ettin. Hem bizimle mücadelede çok ileri gittin. Eğer doğrulardan isen haydi bizi tehdit ettiğin şeyi bize getir!\""},{"n":33,"t":"Dedi: \"Onu, ancak Allâh dilerse size getirir; siz engel olamazsınız!\""},{"n":34,"t":"\"Eğer Allâh, sizi azdırmak diliyorsa, ben size öğüt de etmek istesem, öğütüm size yarar sağlamaz. Rabbiniz O’dur ve siz O’na döndürüleceksiniz.\""},{"n":35,"t":"Yoksa \"O(Kur’â)n’ı uydurdu\" mu diyorlar? De ki: \"Eğer O’nu uydurmuşsam, suçum banadır. Ama ben sizin işlediğiniz suçlardan uzağım.\""},{"n":36,"t":"Nûh’a vahyolundu ki: \"Kavminden, inanmış olanlardan başka kimse inanmayacak, onların yaptıklarından dolayı üzülme!\""},{"n":37,"t":"\"Gözlerimizin önünde ve vahyimiz gereğince gemiyi yap ve zulmedenler hakkında bana hitâbetme (onların kurtuluşu için bana yalvarma); onlar mutlaka boğulacaklardır!\""},{"n":38,"t":"Nûh gemiyi yapıyor, kavminden ileri gelenler yanından geçtikçe onunla alay ediyorlardı. \"Siz bizimle alay ederseniz, sizin alay ettiğiniz gibi biz de sizinle alay edeceğiz?\" dedi."},{"n":39,"t":"\"Yakında bileceksiniz: İnsanı rezil eden azâb kime geliyor, sürekli azâb kimin başına konuyor?\""},{"n":40,"t":"Nihâyet emrimiz gelip de tandır kaynayınca (iş ciddileşip sular kaynamağa başlayınca, Nûh’a) dedik ki: \"Her şeyden ikişer çifti ve aleyhlerinde hüküm verdiklerimiz hâric olmak üzere âileni ve inananları gemiye yükle!\" Zaten onunla beraber inanan pek azdı."},{"n":41,"t":"\"Haydi, gemiye binin, dedi. Onun akıp gitmesi de durması da Allâh’ın adıyledir. Rabbim, elbette bağışlayandır, esirgeyendir!\""},{"n":42,"t":"Gemi, onları dağlar gibi dalga(lar) arasından geçirirken Nûh, bir kenarda duran oğluna. \"Yavrum, bizimle beraber bin, kâfirlerle beraber olma!\" diye seslendi."},{"n":43,"t":"(Oğlu): \"Beni sudan koruyacak bir dağa sığınacağım,\" dedi. (Nûh): \"Bugün, Allâh’ın emrinden koruyacak hiçbir şey yoktur, ancak O’nun acıdığı (kurtulur).\" dedi. Ve aralarına dalga girdi, o da boğulanlardan oldu."},{"n":44,"t":"\"Ey yer, suyunu yut ve ey gök tut!\" denildi. Su azaldı, iş bitirildi. (Gemi) Cudi’ye oturdu. \"Haksızlık yapan kavim yok olsun!\" denildi."},{"n":45,"t":"Nûh Rabbine seslendi: \"Rabbim, dedi, oğlum benim âilemdendir. Senin sözün elbette haktır ve sen hâkimlerin hâkimisin!\""},{"n":46,"t":"(Rabbi): \"Ey Nûh, dedi, o senin âilenden değildir. O, yaramaz iş yaptı. Bilmediğin bir şeyi benden isteme. Sana câhillerden olmamanı öğütlerim!\""},{"n":47,"t":"(Nûh) dedi ki: \"Rabbim, bilmediğim bir şeyi senden istemekten sana sığınırım. Eğer beni bağışlamaz, bana acımazsan ziyana uğrayanlardan olurum!\""},{"n":48,"t":"\"Ey Nûh, denildi, sana ve seninle beraber bulunan ümmetlerden bir bölüme bizden selâmet ve bolluklarla (gemiden) in. Ama öyle ümmetler de var ki, onları bir süre yaşatacağız, sonra onlara bizden acı bir azâb dokunacaktır!\""},{"n":49,"t":"(Ey Muhammed), bunlar sana vahyettiğimiz gayb haberlerindendir. Ne sen, ne de kavmin, daha önce bunları bilmiyordunuz. O halde sabret, sonuç korunanlarındır."},{"n":50,"t":"Âd(kavmin)e de kardeşleri Hûd’u (gönderdik): \"Ey kavmim, dedi, Allah’a kulluk edin, O’ndan başka tanrınız yoktur. Siz sadece uyduruyorsunuz!\""},{"n":51,"t":"\"Ey kavmim, ben sizden bunun için bir ücret istemiyorum. Benim ücretim, beni yaratana düşer. Aklınızı kullanmıyor musunuz?\""},{"n":52,"t":"\"Ey kavmim, Rabbinizden mağfiret dileyin, sonra O’na tevbe edin (O’na yönelin) ki gökten üzerinize bol bol rahmet göndersin, kuvvetinize kuvvet katsın. Suç işleyerek (Allah’tan) yüz çevirmeyin!\""},{"n":53,"t":"Dediler ki: \"Ey Hûd, bize bir mu’cize getirmedin. Biz senin sözünle tanrılarımızı terk edecek değiliz ve biz sana inanacak değiliz!\""},{"n":54,"t":"\"(Senin hakkında)\" seni tanrılarımızdan biri fena çarpmış!\" demekten başka bir söz bulamıyoruz\" Dedi ki: \"Ben Allâh’ı şâhid tutuyorum, siz de şâhid olun ki, ben sizin (Allah’a) ortak koştuğunuz şeylerden uzağım.\""},{"n":55,"t":"O (Allâh)’dan başka (taptığınız tanrılardan). Haydi hepiniz bana tuzak kurun, sonra bana hiç göz açtırmayın (elinizden ne gelirse yapın)!\""},{"n":56,"t":"\"Ben, benim de Rabbim, sizin de Rabbiniz olan Allah’a dayandım. Hiçbir canlı yoktur ki O, onun perçeminden tutmuş olmasın (onu dilediği gibi yönetmesin). Gerçekten Rabbim, doğru bir yol üzerindedir (O âdildir, yanında kimse zulme uğramaz).\""},{"n":57,"t":"\"Eğer yüz çevirirseniz, artık ben size sunmakla görevlendirildiğim mesajı size duyurdum. Rabbim, sizin yerinize başka bir kavim de getirebilir. Siz O’na hiçbir zarar veremezsiniz. Şüphesiz Rabbim, herşeyi koruy(up gözet)endir.\""},{"n":58,"t":"Emrimiz gelince Hûd’u ve onunla beraber inanmış olanları bizden bir rahmetle kurtardık; onları katı bir azâbdan kurtardık."},{"n":59,"t":"İşte Âd (kavmi), Rablerinin âyetlerini inkâr ettiler, peygamberlerine karşı geldiler ve her inatçı zorbanın emrine uydular."},{"n":60,"t":"Böylece hem bu dünyâda, hem de kıyâmet gününde peşlerine la’net takıldı. İyi bilin, ’Âd (kavmi) Rablerini inkâr ettiler; iyi bilin Hûd’un kavmi ’Âd, (Allâh’ın rahmetinden) uzak olsun (yok olup gitsin)!"},{"n":61,"t":"Semûd(kavmin)e de kardeşleri Sâlih’i (gönderdik). Dedi ki: \"Ey kavmim, Allah’a kulluk edin, O’ndan başka tanrınız yoktur! Sizi yerden inşâ eden ve orada yaşatan O’dur; O’ndan mağfiret dileyin, sonra O’na tevbe edin! Çünkü Rabbim yakındır, (du’âları) kabul edendir.\""},{"n":62,"t":"Dediler ki: \"Ey Sâlih, sen bundan önce bizim aramızda ümit beslenen kişi idin. Şimdi atalarımızın taptıklarına tapmaktan bizi men mi ediyorsun? Biz senin bizi çağırdığın şeyden şüphe içindeyiz, kuşkulanıyoruz!\""},{"n":63,"t":"\"Ey kavmim, dedi, bakın ya ben Rabbimden bir kanıt üzerinde isem ve O, bana kendinden bir rahmet vermişse? Peki bu durumda O’na karşı gelirsem beni Allah’tan kim kurtarır? Sizin bana, ziyanımı artırmaktan başka bir katkınız olamaz!\""},{"n":64,"t":"\"Ey kavmim, işte şu, Allâh’ın devesi, size bir mu’cizedir. Bırakın onu, Allâh’ın arzında yesin, ona bir kötülük dokundurmayın, yoksa sizi yakın bir azâb yakalar!\""},{"n":65,"t":"Fakat onu kesip devirdiler. (Sâlih) dedi ki: \"Yurdunuzda üç gün yaşayın, (sonra mahvolacaksınız); bu, yalan olmayan bir uyarıdır!\""},{"n":66,"t":"Nihâyet emrimiz gelince Sâlih’i ve onunla beraber inanmış olanları, bizden bir rahmetle kurtardık, (onları) o günün zilletinden (kurtardık). İşte Rabbin öyle güçlü, öyle gâliptir."},{"n":67,"t":"Zulmedenleri de o korkunç ses yakaladı, yurtlarında çöküp kaldılar."},{"n":68,"t":"Orada hiç şenlik kurmamış gibi oldular. İyi bilin ki Semûd (kavmi), Rablerini inkâr ettiler ve iyi bilin ki Semûd (kavmi) def olup gittiler!"},{"n":69,"t":"Elçilerimiz, İbrâhim’e müjde getirip \"selâm!\" demişlerdi. O da \"selâm!\" dedi; çok durmadan hemen (elçilere) kızarmış bir buzağı getirdi."},{"n":70,"t":"Ellerinin buzağıya uzanmadığını görünce durumlarını beğenmedi ve onlardan ötürü içinde bir korku duydu. \"Korkma, dediler, biz Lût kavmine gönderildik.\""},{"n":71,"t":"Ayakta durmakta olan karısı, güldü. Biz de ona İshak’ı müjdeledik. İshak’ın ardından da Ya’kûb’u."},{"n":72,"t":"\"Vay, dedi, ben bir kocakarı, bu kocam da bir pir iken doğuracak mıyım? Bu, cidden şaşılacak bir şey!\""},{"n":73,"t":"Dediler ki: \"Allâh’ın işine mi şaşıyorsun? Allâh’ın rahmeti ve bereketleri sizin üzerinizdedir, ey ev halkı! O, övülmeğe lâyıktır, iyiliği boldur.\""},{"n":74,"t":"İbrâhim’den korku gidip kendisine sevinç gelince, Lût kavmi hakkında bizimle tartışmağa başladı (onlardan azâbı kaldırmamızı veya hafifletmemizi ricâ ediyordu)."},{"n":75,"t":"Çünkü İbrâhim, gerçekten halimdir, içlidir, (Allah’a) yüz tutup yalvarandır."},{"n":76,"t":"(Melekler): \"Ey İbrâhim, dediler, bundan vazgeç (boşuna uğraşma). Zira Rabbinin emri gelmiştir. Mutlaka onlara, geri çevrilmez azâb gelecektir!\""},{"n":77,"t":"Elçilerimiz Lût’a gelince onlar yüzünden kaygılandı. onlar için arşını daraldı (ne yapacağını şaşırdı): \"Bu, çetin bir gündür!\" dedi."},{"n":78,"t":"Daha önce de kötü işler yapmakta olan kavmi koşarak ona geldiler. (Lût): \"Ey kavmim, dedi, işte kızlarım, onlar sizin için daha (güzel, daha) temiz! Allah’tan korkun, konuklarımın içinde beni rezil etmeyin! İçinizde aklı başında bir adam yok mu sizin?\""},{"n":79,"t":"Dediler ki: \"Senin kızlarında bizim bir hakkımız olmadığını bilmişsindir. Ve sen bizim ne istediğimizi de pekâlâ bilirsin!\""},{"n":80,"t":"(Lût): \"Keşke sizi savacak gücüm olsaydı, yahut da çok sarp bir kaleye sığınabilseydim!\" dedi."},{"n":81,"t":"(Melekler) dediler ki: \"Ey Lût, biz senin Rabbinin elçileriyiz. Onlar sana asla dokunamazlar. Gecenin bir kısmında âileni yürüt; içinizden karından başka hiç kimse geri dönüp bakmasın. Çünkü ötekilerine erişen (azâb) ona da erişecektir. Başlarına gelecek azâb zamanı, sabah vaktidir. Sabah da yakın değil mi?\""},{"n":82,"t":"(Azâb) emrimiz gelince oranın üstünü altına getirdik, üzerine de taş yağdırdık: Çamurdan pişmiş, (azâb için) hazırlanmış, istif edilmiş."},{"n":83,"t":"Rabbinin katında işâretlenmiş (taşlar). O, zâlimlerden uzak değildir."},{"n":84,"t":"Medyen’e de kardeşleri Şu’ayb’i (gönderdik): \"Ey kavmim, dedi, Alah’a kulluk edin, sizin O’ndan başka tanrınız yoktur; ölçüyü ve tartıyı eksik yapmayın. Ben sizi bolluk içinde görüyorum ve ben sizin için kuşatıcı bir günün azâbından korkuyorum!\""},{"n":85,"t":"\"Ey kavmim, ölçüyü ve tartıyı tam dengeli yapın, insanların eşyasını eksik vermeyin ve yeryüzünde bozgunculuk yaparak kötülük etmeyin!\""},{"n":86,"t":"\"Eğer inanan insanlar iseniz, Allâh’ın bıraktığı (kâr), sizin için daha hayırlıdır. Fakat ben sizin üzerinize bekçi değilim!\""},{"n":87,"t":"\"Ey Şu’ayb, dediler, senin namazın mı sana, babalarımızın taptığı şeylerden, yahut mallarımız üzerinde dilediğimizi yapmaktan vazgeçmemizi emrediyor? Oysa sen, yumuşak huylu, akıllı(bir insan)sın!\""},{"n":88,"t":"\"Ey kavmim, dedi, bakın, ya ben Rabbimden bir kanıt üzerinde isem ve (O), bana kendinden güzel bir rızık vermişse? Ben size menettiğim şeylerde size aykırı davranmak istemiyorum. Sadece gücümün yettiği kadar düzeltmek istiyorum. Başarım ancak Allâh(ın yardımı) iledir. Yalnız O’na dayandım ve yalnız O’na yönelirim!\""},{"n":89,"t":"\"Ey kavmim, bana karşı gelmeniz, sakın sizi Nûh kavminin yahut Hûd kavminin veyahut Sâlih kavminin başlarına gelenler gibi bir felâkete uğratmasın! Lût kavmi henüz sizden uzak değildir.\""},{"n":90,"t":"\"Rabbinizden mağfiret dileyin, sonra O’na tevbe edin! Doğrusu Rabbim çok esirgeyen, çok sevendir.\""},{"n":91,"t":"Dediler ki: \"Ey Şu’ayb, senin söylediklerinden çoğunu anlamıyoruz, biz seni içimizde zayıf görüyoruz. Kabilen olmasaydı seni mutlaka taşla(yarak öldürü)rdük! Senin bizim yanımızda hiçbir değerin yoktur!\""},{"n":92,"t":"\"Ey kavmim, dedi, size göre kabilem Allah’tan daha mı değerli ki O’nu arkanıza at(ıp unut)tunuz? Şüphesiz Rabbim yaptıklarınızı kuşatıcıdır (herşeyinizi bilmektedir).\""},{"n":93,"t":"\"Ey kavmim, olduğunuz yerde (yaptığınızı) yapın, ben de yapıyorum. Yakında kime azâbın gelip kendisini rezil edeceğini ve kimin yalancı olduğunu bileceksiniz. Gözetin, ben de sizinle beraber gözetmekteyim!\""},{"n":94,"t":"Emrimiz gelince, Şu’ayb’i ve onunla beraber inanmış olanları bizden bir acıma ile kurtardık; zulmedenleri de o korkunç ses yakaladı, yurtlarında çöküp kaldılar."},{"n":95,"t":"Sanki orada hiç şenlik kurmamışlardı! İyi bilin ki, Semûd (kavmi) nasıl uzaklaşıp gittiyse Medyen halkı da öyle uzaklaşıp gitti."},{"n":96,"t":"Andolsun, Mûsâ’yı da âyetlerimizle ve açık bir delil ile gönderdik."},{"n":97,"t":"Fir’avn’a ve adamlarına. (Ama o insanlar), Fir’avn’ın buyruğuna uydular. Oysa, Fir’avn’ın buyruğu, doğruya iletici değildi."},{"n":98,"t":"(Fir’avn), kıyâmet günü kavminin önünde gidiyor. İşte onları ateşe getirdi. O varılan yer de ne fenâ bir yerdir!"},{"n":99,"t":"Bu dünyâda da (onların) ardına la’net takılmıştır, kıyâmet gününde de (burada da la’netle anılacaklardır, âhirette de)! Bu vergi, ne kötü bir vergidir!"},{"n":100,"t":"(Ey Muhammed), bu sana anlattıklarımız, o kentlerin haberlerinden(başlarına gelen olaylardan)dır. Onlardan kimi hâlâ ayakta, kimi de biçilmiştir."},{"n":101,"t":"Biz onlara zulmetmedik. Fakat onlar, kendi kendilerine zulmediyorlardı. Rabbinin emri geldiği zaman, Allah’tan başka yalvardıkları tanrıları, kendilerinden hiçbir şeyi savamadı ve onların ziyanlarını artırmaktan başka bir işe yaramadı!"},{"n":102,"t":"İşte Rabbin zulmeden kentleri yakaladığı zaman böyle yakalar. Doğrusu O’nun yakalaması, çok acı ve çok çetindir."},{"n":103,"t":"Şüphesiz âhiret azâbından korkanlar için, bunda elbette ibret vardır. O, bütün insanların toplandığı bir gündür ve o, görülecek bir gündür."},{"n":104,"t":"Biz onu, sadece sayılı bir süre için erteliyoruz."},{"n":105,"t":"O geldiği gün, hiç kimse O’nun izni olmadan konuşamaz. O(raya toplana)nlardan kimi şaki (bahtsız), kimi sa’id(mutlu)dur."},{"n":106,"t":"Bahtsızlar ateştedirler. Onların orada (o bunaltıcı ateş içinde) bir soluk alıp verişleri vardır ki!..."},{"n":107,"t":"Gökler ve yer durdukça orada sürekli kalacaklardır. Meğer Rabbin, çıkmalarını dilemiş olsun. Çünkü Rabbin, istediğini yapandır."},{"n":108,"t":"Mutlu kılınanlar ise cennettedirler. Gökler ve yer durdukça orada sürekli kalacaklardır. Meğer Rabbin, çıkmalarını dilemiş olsun. Bu, kesintisiz bir vergidir!."},{"n":109,"t":"Şunların taptıkları şeyler(in, yararsızlığın)dan hiç kuşkun olmasın. Onlar da önceden atalarının taptığı gibi tapıyorlar. Biz onların da paylarını eksiksiz vereceğiz!"},{"n":110,"t":"Andolsun, Mûsâ’ya Kitabı verdik, onda da ayrılığa düşüldü. Rabbin, (süre tanıyacağına) söz vermemiş olsaydı, derhal aralarında hüküm verilmiş, (hak eden, cezâsını bulmuş) olurdu. Onlar, bu(Kur’â)n’dan kuşkulu bir şüphe içindedirler."},{"n":111,"t":"Şüphesiz Rabbin, hepsinin işlerini(n karşılığını) tam verecektir. Çünkü Allâh, yaptıklarını bilmektedir."},{"n":112,"t":"Öyleyse emrolunduğun gibi doğru ol; seninle beraber tevbe edenler de (doğru olsunlar), aşırı gitmeyiniz! Zira O, yaptıklarınızı görmektedir."},{"n":113,"t":"Sakın zulmedenlere dayanmayın, sonra size ateş dokunur. Sizin Allah’tan başka dostlarınız yoktur. Sonra size yardım edilmez."},{"n":114,"t":"Gündüzün iki tarafında (sabah, akşam) ve geceye yakın sâ’atlerde namaz kıl; çünkü iyilikler, kötülükleri giderir. Bu, ibret alanlara bir öğüttür."},{"n":115,"t":"Sabret, çünkü Allâh güzel davrananların ecrini zayi etmez."},{"n":116,"t":"Sizden önceki nesillerden akıllı kimselerin, yeryüzünde bozgunculuk yapmaktan men’etmeleri gerekmez miydi? Fakat onlar arasından, ancak kendilerini kurtardığımız pek az kişi böyle yaptı. Zulmedenler ise kendilerine verilen refahın peşine düşüp şımardılar ve suç işleyenler olup çıktılar."},{"n":117,"t":"Halkı uslu kimseler olsaydı, Rabbin o kentleri, zulüm ile helâk edecek değildi."},{"n":118,"t":"Rabbin dileseydi, insanları bir tek ümmet yapardı. Ama ihtilâf edip durmaktadırlar."},{"n":119,"t":"Yalnız Rabbinin acıdıkları (bu ihtilâfın dışında kalmışlardır). Zaten (Allâh) onları bunun için yaratmıştır. Rabbinin: \"Andolsun, ben cehennemi hep cinlerden ve insanlardan bir kısmıyle dolduracağım!\" sözü tam yerine gelmiştir."},{"n":120,"t":"Peygamberlerin haberlerinden, senin kalbini sağlamlaştıracak her şeyi sana anlatıyoruz. Bunda da sana hak ve inananlar için bir öğüt ve ibret gelmiştir."},{"n":121,"t":"İnanmayanlara de: \"Olduğunuz yerde yapacağınızı yapın, biz de yapıyoruz!\""},{"n":122,"t":"\"Bekleyin, biz de bekliyoruz!\""},{"n":123,"t":"Göklerin ve yerin gaybı (görünmez bilgisi), Allah’a âittir. Bütün işler hep Allah’a döndürülüp götürülür. O’na kulluk et ve O’na dayan. Rabbin sizin yaptıklarınızdan gâfil değildir."}],[{"n":1,"t":"Elif lâm râ. Bunlar apaçık Kitabın âyetleridir."},{"n":2,"t":"Biz onu Arapça bir Kur’ân olarak indirdik ki anlayasınız."},{"n":3,"t":"Biz, bu Kur’ân’ı vahyetmekle sana kıssaların en güzelini anlatıyoruz. Sen ondan önce (bunları) bilmeyenlerden idin."},{"n":4,"t":"Hani bir zaman Yûsuf, babasına: \"Babacığım demişti, ben (rü’yâda) on bir yıldız, güneşi ve ayı gördüm, bunların bana secde ettiklerini gördüm.\" demişti."},{"n":5,"t":"(Babası Ya’kûb): \"Yavrum, dedi, rü’yânı kardeşlerine anlatma, sonra sana bir tuzak kurarlar. Çünkü şeytân, insanın apaçık düşmanıdır!"},{"n":6,"t":"Böylece Rabbin seni seçecek ve sana düşlerin yorumundan bir parça öğretecek, sana ve Ya’kûb soyuna ni’metini tamamlayacaktır; nasıl ki daha önce ataların İbrâhim’e ve İshak’a da ni’metini tamamlamıştı. Şüphesiz Rabbin, bilendir, hüküm ve hikmet sâhibidir.\""},{"n":7,"t":"Andolsun, Yûsuf ve kardeşlerin(in kıssaların)da, soranlar için ibretler vardır:"},{"n":8,"t":"(Kardeşleri) demişlerdi ki: \"Yûsuf ve (öz) kardeşi (Bünyamin), babamıza bizden daha sevgilidir. Oysa biz bir cemaatiz. Babamız açık bir yanlışlık içindedir!\""},{"n":9,"t":"\"Yûsuf’u öldürün, ya da onu bir yere bırakın da babanızın yüzü yalnız size kalsın (bundan böyle babanız yalnız sizi görsün ve sevsin)! Ondan sonra da (tevbe eder), iyi bir topluluk olursunuz!\""},{"n":10,"t":"İçlerinden bir sözcü: \"Yûsuf’u öldürmeyin, onu kuyunun dibine atın, kervanlardan biri onu (görüp) alsın; eğer yapacaksanız (böyle yapın),\" dedi."},{"n":11,"t":"(Bu fikirde karar kıldılar ve babalarına gelip) Dediler ki: \"Ey babamız, neden Yûsuf hakkında bize güvenmiyorsun, oysa biz ona öğüt verenler(onun iyiliğini isteyenler)iz?\""},{"n":12,"t":"\"Yarın onu da bizimle beraber (kıra) gönder, gezsin, oynasın; biz onu elbette koruruz.\""},{"n":13,"t":"(Ya’kûb) Dedi ki: \"Onu götürmeniz beni üzer; korkarım ki, sizin haberiniz yokken onu kurt yer!\""},{"n":14,"t":"Dediler ki: \"Biz bir topluluk olduğumuz halde onu kurt yerse, o zaman biz tamamen beceriksiz kimseleriz, demektir!\""},{"n":15,"t":"Nihâyet onu götürüp de kuyunun dibine atmağa topluca karar verdikleri zaman biz, Yûsuf’a: \"Andolsun sen onların bu işlerini, hiç farkında olmayacakları bir sırada kendilerine haber vereceksin!\" diye vahyettik."},{"n":16,"t":"Akşamleyin ağlayarak babalarına geldiler."},{"n":17,"t":"\"Ey babamız, dediler, biz gittik, yarışıyorduk; Yûsuf’u yiyeceğimizin yanında bırakmıştık. Onu kurt yemiş! Ama biz doğru söylesek de sen bize inanmazsın!\""},{"n":18,"t":"(Yûsuf’un) gömleğinin üstünde yalan kan getirdiler. (Ya’kûb): \"Herhalde, dedi, nefisleriniz sizi aldatıp bir işe sürükledi. Artık tek çarem güzelce sabretmektir. Dediğinize (dayanmak için) ancak Allan’tan yardım istenir!\""},{"n":19,"t":"Bir kervan geldi, sucularını gönderdiler,(o da gidip kuyuya) kovasını sarkıttı: \"Müjde, dedi, işte bir oğlan!\" Onu ticaret için sakladılar, halbuki Allâh, onların ne yaptıklarını biliyordu."},{"n":20,"t":"Nihâyet (Mısır’a varınca) onu düşük bir pahaya, birkaç paraya sattılar. Onlar, ona (Yûsuf’a) karşı isteksiz idiler. (Buluntu olduğu için ona değer vermediler, hemen onu ellerinden çıkarmak istediler.)"},{"n":21,"t":"Onu satın alan Mısır’lı (hazine bakanı Kıtfir), karısı(Zeliha’y)a: \"Ona iyi bak, belki bize yararı dokunur, ya da onu evlâd ediniriz!\" dedi. Böylece biz Yûsuf’a o yerde güzel bir imkân verdik ki ona düşlerin yorumunu öğretelim. Allâh, buyruğunu yerine getirendir, ama insanların çoğu bilmezler."},{"n":22,"t":"(Yûsuf), kuvvetli çağına erişince ona hüküm ve ilim verdik. İşte biz, güzel hareket edenleri böyle mükâfâtlandırırız."},{"n":23,"t":"Yûsuf’un, evinde kaldığı kadın, onun nefsinden murâd almak istedi ve kapıları kilitleyip: \"Haydi gelsene!\" dedi (Yûsuf): \"Allah’a sığınırım dedi, efendim bana güzel baktı. zâlimler iflâh olmazlar!\""},{"n":24,"t":"Andolsun, kadın onu arzu etmişti, eğer Rabbinin doğruyu gösteren delilini görmeseydi o da onu arzu etmişti. Böylece biz kötülüğü ve fuhşu ondan çevirmek istedik; çünkü o, ihlâsa erdirilmiş (temiz) kullarımızdandır."},{"n":25,"t":"Kapıya doğru koşuştular. Kadın, Yûsuf’un gömleğini arkadan yırttı. Kapının yanında kadının bey’ine rastladılar. Kadın: \"Senin âilene kötülük yapmak isteyenin cezâsı nedir? Zindana kapatılmak veya acı bir biçimde işkence edilmek değil midir?\" dedi."},{"n":26,"t":"(Yûsuf): \"O benden murâd almak istedi!\" dedi. Kadının âilesinden bir şâhid de şöyle şâhidlik etti: \"Eğer Yûsuf’un gömleği önden yırtılmışsa kadın doğrudur, o yalancılardandır.\""},{"n":27,"t":"\"Ve eğer onun gömleği arkadan yırtılmışsa kadın yalancıdır, o doğrulardandır!\""},{"n":28,"t":"(Kadının kocası, Yûsuf’un) gömleğinin arkadan yırtılmış olduğunu görünce (kadına): \"Bu, sizin düzeninizdendir, dedi, gerçekten sizin düzeniniz büyüktür!\""},{"n":29,"t":"\"Yûsuf, sen bundan vazgeç (bunu kimseye söyleme), (ey kadın), sen de günâhının bağışlanmasını dile! Çünkü sen, günâhkârlardan oldun!\""},{"n":30,"t":"Şehirde birtakım kadınlar: Vezir’in karısı, uşağının nefsinden murâd almak istemiş! Sevda, onun bağrını yakmış! Biz onu açık bir sapıklık içinde görüyoruz!\" dediler."},{"n":31,"t":"(Kadın), onların (dedikodu yaparak kendisini dile düşürme) düzenlerini işitince, onlara (adam) gönderdi (yemeğe davet etti). Onlar için dayanacak yastıklar hazırladı ve her birine de birer bıçak verdi. (Yûsuf’a): \"Çık karşılarına!\" dedi. Kadınlar, (önlerine konan meyveleri soyup yemekle meşgul iken) Yûsuf’u görünce onu (gözlerinde) büyüttüler, (ona hayranlıklarından ötürü) ellerini kestiler ve: \"Allâh için, hâşâ bu, insan değildir; bu ancak güzel bir melektir!\" dediler."},{"n":32,"t":"(Kadın) Dedi ki: \"İşte siz, beni bunun için kınamıştınız! Andolsun ben kendisinden murâd almak istedim de o, iffetinden ötürü reddetti. Ama kendisine emrettiğimi yapmazsa, elbette zindana atılacak ve alçalanlardan olacaktır!\""},{"n":33,"t":"(Yûsuf): \"Rabbim dedi, bana göre zindan, bunların beni çağırdığı şeyden iyidir. Eğer onların düzenini benden savmazsan onlara kayarım ve câhillerden olurum!\""},{"n":34,"t":"Rabbi onun du’âsını kabul buyurdu da onların düzenini ondan savdı. Şüphesiz O, işitendir, bilendir."},{"n":35,"t":"Sonra (aziz Kıtfir ve adamları, Yûsuf’un masumluğu hakkındaki) bu delilleri gördükleri halde yine onu bir süre zindana atmaları kendilerine uygun geldi."},{"n":36,"t":"Onunla beraber iki genç daha zindana girdi. Onlardan biri dedi ki: \"Ben düşümde şarap sıktığımı görüyorum.\" Öteki de: \"Ben de, görüyorum ki başımın üstünde ekmek taşıyorum, kuşlar ondan yiyor. Bunun yorumunu bize haber ver, zira biz seni güzel davranan(iyi rü’yâ yoran)lardan görüyoruz.\" dedi."},{"n":37,"t":"(Yûsuf) şöyle dedi: \"Size rızık olarak verilen yemek henüz size gelmezden önce bunun yorumunu size haber vermiş olurum. Bu (yorum) Rabbimin bana öğrettiği şeylerdendir (bu bilgileri Rabbim bana lutfetti). Ben, Allah’a inanmayan, âhireti de inkâr eden bir kavmin dinini terk ettim:"},{"n":38,"t":"\"Atalarım İbrâhim, İshak ve Ya’kûb’un dinine uydum. Bizim, herhangi bir şeyi Allah’a ortak koşmağa hakkımız yoktur. Bu (tevhid), bize ve bütün insanlara Allâh’ın bir lutfudur, ama insanların çoğu şükretmezler.\""},{"n":39,"t":"\"Ey benim zindan arkadaşlarım, çeşitli tanrılar mı iyi, yoksa herşeyi (hükmü altında tutan) kahredici tek Allâh mı?"},{"n":40,"t":"Siz, o’nu bırakıp ancak sizin ve atalarınızın taktığı birtakım (boş) isimlere tapıyorsunuz. Allâh onlar(ın gerçekliği) hakkında hiçbir delil indirmemiş(onlara hiçbir güç vermemiş)tir. Hüküm, yalnız Allâh’ındır. O, yalnız kendisine tapmanızı buyurmuştur. İşte doğru din budur. Ama insanların çoğu bilmezler.\""},{"n":41,"t":"\"Ey zindan arkadaşlarım, (rü’yânıza gelince) biriniz (eskisi gibi) yine efendisine şarap sunacak, diğeri ise asılacak, kuşlar onun başından yiyecek. Sorduğunuz iş (bu şekilde) kesinleşmiştir.\""},{"n":42,"t":"O iki kişiden kurtulacağını sandığı kimseye: \"Beni efendin(kralın)ın yanında an (benim suçsuz olduğumu krala hatırlat)\" dedi. Fakat şeytân o adama, (Yûsuf’un durumunu) efendisine söylemeyi unutturdu, (bundan ötürü Yûsuf), birkaç yıl zindanda kaldı."},{"n":43,"t":"(Bir gün) Kral dedi ki: \"Ben, düşümde yedi semiz inek görüyorum, bunları yedi zayıf inek yiyor. Ve yedi yeşil, yedi de kuru başak (görüyorum). Ey efendiler, eğer siz rü’yâ ta’bir ediyorsanız bu rü’yâmın ta’birini bana anlatın.\""},{"n":44,"t":"(Yorumcular) dediler ki: \"Bu, karışık düşlerden ibârettir. Biz, karışık düşlerin yorumunu bilmeyiz.\""},{"n":45,"t":"(Zindandaki) İki kişiden kurtulan (adam), uzun bir süre sonra (bu olay üzerine Yûsuf’u) hatırladı da dedi ki: \"Ben size onun yorumunu haber veririm, hemen beni (zindana) gönderin.\""},{"n":46,"t":"(Zindana, Yûsuf’un yanına geldi, dedi ki): \"Yûsuf, ey çok doğru söyleyen, bize şu rü’yâyı çöz: Yedi semiz ineği, yedi zayıf (inek) yiyor ve yedi yeşil, yedi de kuru başak (neyi gösterir)? Umarım ki senin yorumunla insanlara dönerim, onlar da bilirler.\""},{"n":47,"t":"(Yûsuf) Dedi ki: \"Siz, âdetiniz üzere yedi yıl (ürün) ekersiniz. Biçtiğinizi başağında bırakırsınız, ancak yiyeceğiniz az bir mikdar(ı alırsınız, gerisini depolarsınız).\""},{"n":48,"t":"\"Sonra onun ardından yedi kurak (yıl) gelir ki (tohumluk olarak) sakladığınız az miktar dışında, o yıllar için önceden biriktirdiklerinizi yeyip bitirir.\""},{"n":49,"t":"\"Sonra onun ardından bir yıl gelir ki, o yılda insanlara bol yağmur verilir ve insanlar o yıl (bol bol meyva) sıkarlar (hayvan sağarlar).\""},{"n":50,"t":"(Elçi bu yorumu getirince) Kral: \"Onu bana getirin.\" dedi. Elçi, Yûsuf’un yanına gelince (Yûsuf): \"Efendine dön de ona sor, ellerini kesen o kadınların maksadı neydi? (Bunu ortaya çıkarsın). Şüphesiz Rabbim, onların tuzaklarını biliyor\", dedi."},{"n":51,"t":"(Kral, kadınlara): \"Yûsuf’un nefsinden murad almak istediğiniz zaman durumunuz neydi?\" dedi. Dediler ki: \"Hâşâ, Allâh için (doğru söylemek lâzım), biz onda hiçbir kötülük görmedik!\" Aziz’in karısı da: \"İşte şimdi hak yerini buldu, ben onun nefsinden murâd almak istemiştim. O tamamen doğrulardandır!\" dedi."},{"n":52,"t":"(Gerçeği söyledim ki Yûsuf) Benim, arkadan kendisine hâinlik etmediğimi ve Allâh’ın, hâinlerin tuzağını başarıya ulaştırmayacağını bilsin.\""},{"n":53,"t":"\"Ben nefsimi temize çıkarmam. Çünkü nefis, dâimâ kötülüğü emredicidir. Meğer Rabbimin esirgediği bir nefis ola. Rabbim bağışlayandır, esirgeyendir.\""},{"n":54,"t":"Kral: \"Onu bana getirin, dedi, onu kendime özel (dost) yapayım!\" Kendisiyle konuş(up ondaki olgunluğu gör)ünce (Yûsuf’a): \"Sen, dedi, artık bugün yanımızda mevki sâhibi, güvenilir(bir kimse)sin.\""},{"n":55,"t":"(Yûsuf, krala): \"Beni ülkenin hazineleri üstüne bakan yap. Çünkü ben (onları) iyi korur, (yönetmesini) iyi bilirim.\" dedi."},{"n":56,"t":"Böylece biz Yûsuf’a o ülke’de iktidar verdik. Orada dilediği yerde konaklardı. Biz, dilediğimiz kimseye rahmetimizi ulaştırırız, güzel davrananların ecrini zayi etmeyiz."},{"n":57,"t":"İnananlar ve (kötülüklerden) korunanlar için elbette âhiret ödülü, daha hayırlıdır."},{"n":58,"t":"Yûsuf’un kardeşleri geldiler, onun yanına girdiler, o onları tanıdı; fakat onlar onu tanımıyorlardı."},{"n":59,"t":"(Yûsuf) Onların (zahire) yüklerini hazırlatınca dedi ki: \"Sizin baba bir kardeşinizi de bana getirin, görüyorsunuz ya ben, ölçüyü tam yapıyorum ve ben konukseverlerin en iyisiyim!\""},{"n":60,"t":"\"Eğer onu bana getirmezseniz artık benim yanımda size ölçü(lüp verilecek bir şey) yok. (Bir daha) bana yaklaşmayın!\""},{"n":61,"t":"Dediler ki: \"Onu babasından isteyip getirmeğe çalışacağız, (bunu) mutlaka yapacağız\""},{"n":62,"t":"(Yûsuf) Uşaklarına: \"Onların sermayelerini yüklerinin içine koyun, belki âilelerine döndükleri zaman bunun farkına varırlar da yine gelirler\" dedi."},{"n":63,"t":"Babalarına döndüklerinde dediler ki: \"Ey babamız, bizden ölçü men’edildi, kardeşimizi bizimle beraber gönder de (ihtiyacımız olanı) ölç(üp al)alım. Biz onu mutlaka koruruz.\""},{"n":64,"t":"(Yakup) dedi ki: \"Daha önce kardeşi için size güvendiğim gibi onun için de size güveneyim, öyle mi? En iyi koruyan Allah’tır ve O, merhametlilerin merhametlisidir!\""},{"n":65,"t":"Zahire yüklerini açtıklarında sermayelerinin kendilerine geri verilmiş olduğunu gördüler. Dediler ki: \"Ey babamız, daha ne istiyoruz? İşte sermayemiz de bize geri verilmiş! Yine âilemize yiyecek getiririz. Kardeşimizi koruruz, bir deve yükü de fazla (azık) alırız. (Çünkü) Bu, az bir ölçüdür (bize yetmez).\""},{"n":66,"t":"(Ya’kûb): \"Hepiniz kuşatılıp engellenmedikçe siz, onu bana getireceğinize dair Allâh adına bana sağlam söz vermeden onu asla sizinle göndermem!\" dedi. Ne zaman ki, sözlerini verdiler, (Ya’kûb): \"Söylediğimize Allâh, vekildir!\" dedi."},{"n":67,"t":"Ve dedi ki: \"Oğullarım, (Mısır’a) bir kapıdan girmeyin, ayrı ayrı kapılardan girin. Ben, Allah’tan gelecek hiçbir şeyi sizden savamam. Hüküm, yalnız Allâh’ındır. (O size ne takdir etmişse muhakkak olacaktır.) Ben O’na tevekkül ettim, tevekkül edenler de O’na tevekkül etsinler!\""},{"n":68,"t":"Babalarının emrettiği yerden (Mısır’a) girdiler; (gerçi) bu, Allah’tan gelecek hiçbir şeyi onlardan savamazdı. Ama sadece Ya’kûb, içindeki bir dileği söylemişti. O, kendisine öğrettiğimizden ötürü bilgi sâhibi idi (bundan dolayı ’Allâh’ın takdirinden hiçbir şeyi sizden savamam’ demişti). Fakat insanların çoğu bilmezler."},{"n":69,"t":"(Kardeşleri), Yûsuf’un yanına girince, (Yûsuf, öz) kardeşi(Bünyami)n’i yanına aldı ve: \"Ben senin kardeşinim, onların (bizim hakkımızda) yaptıklarına üzülme!\" dedi."},{"n":70,"t":"Onların yüklerini hazırlatırken su tasını (öz) kardeşinin yükünün içine koydu. (Kervan hareket ettikten) sonra bir ünleyici şöyle seslendi: \"Ey kervan, siz hırsızlarsınız!\""},{"n":71,"t":"Bunlara döndüler: \"Ne kaybettiniz, (ne arıyorsunuz)? dediler."},{"n":72,"t":"Dediler ki: \"Kralın su tasını kaybettik (onu arıyoruz). Onu getirene bir deve yükü (mükâfât) var. Ben buna kefilim\""},{"n":73,"t":"(Yûsuf’un kardeşleri): \"Allâh, Allâh! dediler, herhalde siz de bilmişsinizdir ki biz bu yere bozgunculuk yapmak için gelmedik. Ve biz hırsız değiliz!\""},{"n":74,"t":"(Yûsuf’un adamları): \"Peki, dediler, ya yalancı çıkarsanız o(hırsızlık ede)nin cezâsı nedir?\""},{"n":75,"t":"\"Cezâsı, (tas) kimin yükünde bulunursa işte o, onun karşılığıdır. (Hırsızlığına karşılık kendisine el konur). Biz haksızları böyle cezâlandırırız!\" dediler."},{"n":76,"t":"Bunun üzerine (Yûsuf), kardeşinin yükünden önce ötekilerin yüklerini aramağa başladı; sonra tası kardeşinin yükünden çıkardı. İşte Yûsuf’a böyle bir çare öğrettik. Yoksa kralın dini(kanunu)na göre (Yûsuf) kardeşini alamazdı. Meğer Allâh dilemiş olsun. (Biz) dilediğimizi derecelerle yükseltiriz. Her bilgi sâhibinin üstünde daha bir bilen vardır."},{"n":77,"t":"(Yûsuf’un kardeşleri) Dediler ki: \"(Bu) çaldıysa bundan önce kardeşi de çalmıştı.\" Yûsuf bunu içinde sakladı, onlara açmadı. (İçinden): \"Siz fenâ bir durumdasınız, Allâh, sizin anlattığınızın içyüzünü çok iyi biliyor!\" dedi."},{"n":78,"t":"Dediler ki: \"Ey vezir, onun büyük bir ihtiyar babası var! (Onun alıkonduğuna çok üzülür.) Onun yerine (bizden) birimizi al; doğrusu, biz seni iyilik edenlerden görüyoruz.\""},{"n":79,"t":"\"Eşyamızı yanında bulduğumuz kimseden başkasını almaktan Allah’a sığınırız, yoksa biz zulmedenler oluruz!\" dedi."},{"n":80,"t":"Ondan umudu kesince aralarında konuşmak üzere (bir kenara) çekildiler. Büyükleri dedi ki: \"Babanızın sizden Allâh adına kesin söz aldığını; daha önce de Yûsuf hakkında işlediğiniz kusuru bilmiyor musunuz? Babam bana izin verinceye, yahut Allâh benim için hükmedinceye kadar bu yerden ayrılmayacağım. O, hükmedenlerin en iyisidir.\""},{"n":81,"t":"\"Babanıza dönün, deyin ki: \"Ey babamız, oğlun hırsızlık etti! Biz ancak bildiğimize şâhidlik ettik (tasın, onun yükünden çıktığını gördük, ötesini bilmiyoruz), Biz gizliyi bilenler değiliz."},{"n":82,"t":"(İnanmazsan) İçinde bulunduğumuz kente ve beraber geldiğimiz kervana sor. Biz doğru söylüyoruz!\""},{"n":83,"t":"(Dönüp babalarına geldiler ve kardeşlerinin sözünü söylediler. Ya’kub): \"Herhalde, dedi, nefisleriniz size bir işi süs(leyerek sizi ona sürük)ledi. Artık (bana) güzelce sabretmek gerek. Belki de Allâh, onların hepsini bana getirir. Çünkü O, bilendir, herşeyi hikmetle (yerli yerince) yapandır."},{"n":84,"t":"Ve yüzünü onlardan öteye çevirdi de: \"Ey Yûsuf üzerindeki tasam (gel, gel, tam senin gelme zamanındır)!\" dedi ve tasadan gözleri ağardı. (Acısını) yutkunuyor(açığa vurmamağa çalışıyor)du."},{"n":85,"t":"Dediler ki: \"Vallahi sen, Yûsuf’u ana ana hasta olacaksın, yahut öleceksin!\""},{"n":86,"t":"\"Ben üzüntü ve tasamı yalnız Allah’a arz ederim ve Allâh tarafından, sizin bilmediğiniz şeyleri bilirim.\" dedi."},{"n":87,"t":"\"Ey oğullarım, gidin, Yûsuf’u ve kardeşini araştırın, Allâh’ın rahmetinden umut kesmeyin; zira kâfir kavimden başkası Allâh’ın rahmetinden umut kesmez!\""},{"n":88,"t":"(Ya’kub’un oğulları, tekrar Mısır’a) Yûsuf’un yanına döndüklerinde dediler ki: \"Ey vezir, bize ve çocuklarımıza darlık dokundu, değersiz de bir sermaye ile geldik, ama sen bizim için tam ölçü ver, bize tasadduk eyle; çünkü Allâh, tasadduk edenleri mükâfâtlandırır.\""},{"n":89,"t":"(Yûsuf) Dedi: \"Sizler câhil iken Yûsuf’a ve kardeşine neler yaptığınızı bildiniz mi?\""},{"n":90,"t":"\"A, yoksa sen, Yûsuf musun?\" dediler. \"Ben Yûsuf’um, bu da kardeşimdir, dedi. Allâh bize lutfetti (bizi korudu, yüceltti), doğrusu kim (Allah’tan) korkar ve sabrederse, Allâh iyilik edenlerin ecrini zayi etmez.\""},{"n":91,"t":"\"Vallahi dediler, Allâh seni bizden üstün kıldı. Doğrusu biz suç işlemiştik!\""},{"n":92,"t":"\"Bugün sizi kınama yok, Allâh sizi bağışlar; O merhametlilerin merhametlisidir!\" dedi."},{"n":93,"t":"\"Şimdi benim şu gömleğimi götürün, babamın yüzüne koyun da gözü açılsın. Ve bütün âilenizle birlikte bana gelin.\""},{"n":94,"t":"Kervan (Mısır’dan) ayrıl(ıp yola koyul)unca, babaları, (yanında bulunanlara): \"Eğer bana bunak demezseniz, ben Yûsuf’un kokusunu alıyorum.\" dedi."},{"n":95,"t":"\"Vallahi sen hâlâ eski şaşkınlığın içindesin!\" dediler."},{"n":96,"t":"Müjdeci gelip de (Yûsuf’un gömleği)ni (Ya’kub’un) yüzüne koyunca, derhal (gözü açıldı), görür oldu: \"Size demedim mi ben, Allah’tan sizin bilmediğiniz şeyleri bilirim?\" dedi."},{"n":97,"t":"(Oğulları): \"Ey babamız, bizim günâhlarımızın bağışlanmasını dile. Gerçekten biz günâh işledik.\" dediler."},{"n":98,"t":"\"Sizin için Rabbimden mağfiret dileyeceğim, dedi, şüphesiz O, bağışlayandır, esirgeyendir.\""},{"n":99,"t":"(Hep beraber Mısır’a hareket ettiler). Nihâyet Yûsuf’un yanına vardıklarında (Yûsuf) ana babasını kendine çekip kucakladı ve: \"Allâh’ın dileğiyle güven içinde Mısır’a girin!\" dedi."},{"n":100,"t":"Ana babasını tahtın üstüne çıkardı ve hepsi onun için secdeye kapandılar (önünde saygı ile eğildiler. Yûsuf): \"Babacığım, dedi, işte bu, önceden (gördüğüm) rü’yânın yorumudur. Rabbim onu gerçek yaptı, bana iyilik etti; zira şeytân, benimle kardeşlerim arasına fitne soktuktan sonra O, beni zindandan çıkardı, sizi de çölden getirdi. Gerçekten Rabbim dilediği şeyi çok ince düzenler. O, (her tedbiri) bilen, her şeyi yerli yerince yapandır.\""},{"n":101,"t":"\"Rabbim, bana bir parça mülk verdin ve bana düşlerin yorumunu öğrettin. Ey göklerin ve yerin yaratıcısı! dünyâda da, âhirette de benim yârim sensin! Beni müslüman olarak öldür ve beni iyilere kat!\""},{"n":102,"t":"(Ey Muhammed) bu (anlatılanlar), sana vahyettiğimiz gayb haberlerindendir. Onlar kararlarını verip tuzak kurarlarken sen yanlarında değildin."},{"n":103,"t":"Ama sen, ne kadar istesen de, yine insanların çoğu inanacak değillerdir."},{"n":104,"t":"Sen bu(okudukları)na karşılık onlardan bir ücret istemiyorsun. O, sadece bütün âlemler için bir öğüttür."},{"n":105,"t":"Göklerde ve yerde nice âyet(ler) var ki onların yanından yüzlerini çevirerek geçerler."},{"n":106,"t":"Onların çoğu, Allah’a ortak koşmadan inanmazlar."},{"n":107,"t":"Onlar, Alah’ın azâbından, sargın bir belânın, kendilerine gelmeyeceğinden veya hiç farkında değillerken ansızın O (Duruşma) sâ’atin(in) kendilerine gelmeyeceğinden emin midirler?"},{"n":108,"t":"De ki: \"İşte benim yolum budur: Allah’a basiretle da’vet ederim. Ben ve bana uyanlar... Allâh’ın şanı yücedir, ben ortak koşanlardan değilim.\""},{"n":109,"t":"Senden önce de kentler halkından, yalnız kendilerine vahyettiğimiz erkeklerden başka, (elçi) göndermedik. Yeryüzünde hiç gezmediler mi ki kendilerinden öncekilerin sonunun nasıl olduğunu görsünler? Korunanlar için âhiret yurdu daha iyidir. Aklınızı kullanmıyor musunuz?"},{"n":110,"t":"(Bir süre serbest bırakılmalarına aldanmasınlar. Kendilerinden önce gelenlere de öyle fırsat verilmişti. Fakat) Ne zaman ki, elçiler umutlarını kestiler ve kendilerinin yalana çıkarıldıklarını (kâfirlere karşı kendilerine yapılacağı va’dedilen yardımın yapılmayacağını) sandılar, işte o zaman onlara yardımımız geldi ve dilediğimiz kimseler kurtarıldı. Azâbımız suçlular topluluğundan asla geri çevrilmez."},{"n":111,"t":"Elbette onların hikâyelerinde akıl sâhipleri için ibret vardır. Bu (Kur’ân), uydurulacak bir söz değildir; ancak kendinden önceki(Hak Kitabı)nın doğrulanması, her şeyin açıklaması; inananlar için bir kılavuz ve rahmettir."}],[{"n":1,"t":"Elif lâm mim râ. Şunlar Kitabın âyetleridir; Rabbinden, sana indirilen haktır, fakat insanların çoğu inanmazlar."},{"n":2,"t":"Allâh odur ki gökleri, görebileceğiniz bir direk olmadan yükseltti, sonra Arş üzerine istivâ etti (mülkünün tahtına oturdu), güneşi ve ay’ı irâdesine boyun eğdirdi. Her biri, belli bir süre için akıp gitmektedir. (Yaratma) işi(ni) düzenler, âyetleri açıklar ki, Rabbinizle karşılaşacağınıza kesin olarak inanasınız."},{"n":3,"t":"O’dur ki arzı uzattı, orada sabit dağlar ve ırmaklar var etti, orada her meyvadan iki çift (erkek-dişi) yarattı. Geceyi gündüzün üzerine örter. Şüphesiz bunda düşünen bir toplum için âyetler vardır."},{"n":4,"t":"Arzda birbirine komşu kıt’alar, üzüm bağları, ekinler, çatallı ve çatalsız hurmalıklar vardır; bunların hepsi bir su ile sulanır ama ürünlerini birbirinden üstün yaparız. Şüphesiz bunda, aklını kullanan bir toplum için âyetler vardır."},{"n":5,"t":"Eğer şaşacaksan, onların şu sözlerine şaşmak lâzım: \"Biz toprak olduğumuz zaman mı, biz mi yeniden yaratılacağız?\" İşte onlar, Rablerine karşı nankörlük edenlerdir. Ve Onlar, boyunlarında halkalar bulunan kimselerdir, onlar ateş halkıdır. Onlar orada sürekli kalacaklardır."},{"n":6,"t":"Senden, iyilikten önce kötülüğü acele istiyorlar. Oysa onlardan önce benzerleri(ne nice cezâlar) gelip geçti. (Niçin onlardan ibret almazlar?) Şüphesiz Rabbin, o(insa)nların zulümlerine karşı mağfiret sâhibidir, fakat Rabbinin azâbı da pek çetindir."},{"n":7,"t":"İnkâr edenler diyorlar ki: \"Ona Rabbinden bir âyet indirmeli değil miydi?\" Sen, ancak bir uyarıcısın, her toplumun bir yol göstericisi vardır."},{"n":8,"t":"Allâh, her dişinin neyi yüklendiğini ve Rahimlerin neyi eksiltip artırdığını bilir. Onun yanında her şey, bir miktar iledir."},{"n":9,"t":"(O), gizliyi ve aşikâreyi bilendir, büyüktür, yücedir."},{"n":10,"t":"Aranızdan sözü gizleyen de, onu açık söyleyen de, geceleyin gizlenen de, gündüzün görünen de (O’nca) birdir. Hepsini bilir, görür. O’nun bilgisinden ve görmesinden hiçbir şey kaybolmaz."},{"n":11,"t":"O (insa)nın önünden ve arkasından izleyen(melek)ler vardır, onu Allâh’ın emriyle korurlar. Bir milet kendi durumlarını değiştirmedikçe Allâh onların durumlarını değiştirmez. Allâh da bir kavme kötülük istedi mi artık onu geri çevirecek yoktur. Zaten onların, O’ndan başka koruyucuları da yoktur."},{"n":12,"t":"O’dur ki size, korku ve umud içinde şimşeği gösterir. (Yağmurla yüklü) ağır, ağır bulutlar yapar."},{"n":13,"t":"Gök gürültüsü, övgüsüyle, melekler de korkusundan O’nu tesbih ederler. Yıldırımlar gönderir de onlarla dilediğini çarpar. Allâh’ın tuzağı (cezâsı) pek çetin olduğu halde, onlar hâlâ O’nun hakkında tartışmaktadırlar."},{"n":14,"t":"Gerçek du’â, ancak O’na yapılır. O’ndan başka du’â ettikleri ise, kendilerinin hiçbir isteklerini karşılayamazlar. (Onların durumu) tıpkı ağzına gelsin diye suya avuçlarını uzatan kimse gibidir. Oysa (uzanıp suyu avuçlamadıkça su) on(un ağzın)a gelmez. İşte kâfirlerin du’âsı, öyle boşa gider."},{"n":15,"t":"Göklerde ve yerde olanların hepsi, ister istemez Allah’a secde ederler. Gölgeleri de sabah akşam (uzanıp kısalarak O’na secde etmektedirler)."},{"n":16,"t":"De ki: \"Göklerin ve yerin Rabbi kimdir?\" De ki: \"Allâh!\", \"O halde, de, O’ndan başka kendilerine dahi bir fayda ve zarar veremeyen veliler mi edindiniz?\" De ki: \"Körle gören, yahut karanlıklarla aydınlık bir olur mu?\" Yoksa Allah’a, O’nun yarattığı gibi yaratan ortaklar mı buldular da, (ikisinin) yaratma(sı) onlara, benzer mi göründü? De ki: \"Her şeyin yaratıcısı Allah’tır. O, tektir, kahreden(herşeye üstün gelen)dir.\""},{"n":17,"t":"Gökten bir su indirdi de dereler kendi ölçüsünce (o su ile) çağlayıp aktı. Sel üste çıkan köpüğü taşıdı. Süs, yahut eşya yapmak için ateşte yak(ıp erit)tikleri madenlerden de bunun gibi bir köpük (posa) vardır. Allâh, hak ve bâtılı böyle benzetme ile anlatır. Köpük yok olup gider. İnsanlara yararlı olan ise yeryüzünde kalır. İşte Alllah, böyle güzel meseller verir."},{"n":18,"t":"Rablerinin buyruğuna uyanlara, en güzel karşılık vardır. Ona uymayanlar ise, yeryüzünde bulunan her şey ve bunun bir misli daha kendilerinin olsa, (Allâh’ın azâbından kurtulmak için) onu fidye verirlerdi. Onların hesâbı çok kötüdür. Varacakları yer de cehennemdir, ne kötü bir yataktır o!"},{"n":19,"t":"Rabbinden sana indirilenin hak olduğunu bilen kimse, (bunu kabul etmeyen) kör gibi olur mu? Ancak sağduyu sâhipleri öğüt alır."},{"n":20,"t":"Onlar, Allâh’ın ahdini yerine getirirler ve andlaşmayı bozmazlar."},{"n":21,"t":"Ve onlar Allâh’ın bitiştirilmesini istediği şeyi bitiştirirler. Rablerine karşı saygılı olur ve en kötü hesaptan korkarlar."},{"n":22,"t":"Ve onlar Rablerinin yüzünü (rızâsını) arzu ederek (nefsin gücüne giden şeylere) sabrederler; namazı kılarlar, kendilerine verdiğimiz rızıktan gizli ve açık olarak (hayır yoluna) harcarlar ve kötülüğü iyilikle savarlar. İşte şu yurdun sonucu onlarındır:"},{"n":23,"t":"(Onlar) Adn cennetlerine girerler. Babalarından, eşlerinden ve çocuklarından iyi olanlar da kendileriyle beraber olur. Melekler de her kapıdan yanlarına varırlar:"},{"n":24,"t":"\"Sabretmenize karşılık selâm size, yurdun sonu ne güzel!\" (derler)."},{"n":25,"t":"Ama Allah’a verdikleri sözü iyice pekiştirdikten sonra bozanlar ve Allâh’ın bitiştirilmesini istediği şeyi kesenler ve yeryüzünde bozgunculuk yapanlar... İşte la’net onlara, yurdun kötü sonucu da onlaradır.!"},{"n":26,"t":"Allâh, dilediğine rızkı açar da, kısar da. Dünyâ hayâtıyle sevindiler. Oysa âhiretin yanında dünyâ hayâtı, bir geçimden ibârettir."},{"n":27,"t":"İnkâr edenler: \"Ona Rabbinden bir âyet indirilmeli değil miydi?\" diyorlar. De ki: \"Allâh, dilediğini (bu tür sözlerle) saptırır. Yöneleni de kendisine iletir.\""},{"n":28,"t":"Onlar inanan ve Allâh’ı anmakla gönülleri huzur bulan kimselerdir. İyi bilin ki gönüller, ancak Allâh’ı anmakla huzur bulur."},{"n":29,"t":"İşte mutluluk ve güzel gelecek, o inanıp güzel işler yapanlarındır."},{"n":30,"t":"Seni de böylece, kendilerinden önce nice milletler geçmiş bulunan bir millete gönderdik ki, sana vahyettiğimizi onlara okuyasın. Oysa onlar Rahmân’a nankörlük ederler. De ki: \"O (Rahmân), benim Rabbimdir. O’ndan başka tanrı yoktur. O’na dayandım, tevbem yalnız O’nadır.\""},{"n":31,"t":"Eğer kendisiyle dağların yürütüldüğü, yahut arzın parçalandığı, yahut ölülerin konuşturulduğu bir Kur’ân olsaydı!.. Hayır, bütün işler Allah’a âittir. İnananlar hâlâ anlamadılar mı ki, Allâh dileseydi, bütün insanları yola iletirdi? Yaptıkları işler yüzünden inkâr edenlerin başlarına âni belâ(lar) gelmeğe devam edecek, yahut yurtlarının yakınına konacak (yahut sen onların yurtlarının yakınına konacaksın), Allâh’ın va’di gelinceye kadar bu böyle sürüp gidecektir. Allâh sözünden caymaz."},{"n":32,"t":"Senden önceki peygamberlerle alay edildi de inkâr edenlere bir süre meydan verdim, sonra onları yakaladım. Cezâm nasılmış, (gördüler)!"},{"n":33,"t":"Her nefsin yaptığı işin başında duran, (hiçbir şeyden haberi olmayanla bir olur) mu? Onlar Allah’a ortaklar koştular. De ki: \"Onları isimlendirin (nitelendirin bakalım tapılmağa değer bir yanları var mı?) Yoksa siz Allâh’ın, yeryüzünde bilmediği bir şeyi mi Kendisine haber veriyorsunuz? Yoksa boş söz mü söylüyorsunuz? Hayır, inkâr edenlere tuzakları süslü gösterildi. (Hak) yoldan çıkarıldılar. Allâh kimi şaşırtırsa artık ona yol gösteren olmaz!"},{"n":34,"t":"Dünyâ hayâtında onlar için azâb vardır, âhiret azâbı ise daha zordur. Onları Allâh(ın azâbın)dan koruyacak kimse de yoktur."},{"n":35,"t":"(Allâh’ın emirlerine karşı gelmekten) Korunanlara va’dedilen cennetin durumu şöyledir: Altından ırmaklar akar; yemişi de süreklidir, gölgesi de. İşte korunanların sonu budur. İnkâr edenlerin sonu da ateştir."},{"n":36,"t":"Kendilerine Kitap verdiğimiz kimseler, sana indirilene sevinirler. Fakat kabilelerden onun bir kısmını inkâr edenler vardır. De ki: \"Bana, yalnız Allah’a kulluk etmem ve O’na hiçbir şeyi ortak koşmamam emredildi. Ben (insanları) O’na da’vet ederim, dönüşüm de O’nadır.\""},{"n":37,"t":"Ve işte biz onu, Arapça bir hüküm (hikmet gereğince hükmeden bir Kitap) olarak indirdik. Eğer sana gelen bu ilimden sonra onların keyiflerine uyarsan, artık seni Allah’tan kurtaracak ne bir veli ne de koruyucu olmaz."},{"n":38,"t":"Andolsun, biz senden önce de elçiler gönderdik, onlara da eşler ve çocuklar verdik. Allâh’ın izni olmadan hiçbir elçi, bir âyet (mu’cize) getiremezdi. Her sürenin bir yazısı vardır (herşeyin zamanı yazılıp tesbit edilmiştir)."},{"n":39,"t":"Allâh, dilediğini siler, (dilediğini) bırakır. Ana Kitap O’nun yanındadır."},{"n":40,"t":"Ya onları uyardığımız şeylerin bir kısmını sana gösteririz, ya da (bundan önce) senin canını alırız (fark etmez). Sana düşen, sadece duyurmaktır. Hesap görmek bize düşer."},{"n":41,"t":"Bizim o toprağa gelip nasıl onu, uçlarından eksilttiğimizi görmediler mi? Hüküm veren Allah’tır. O’nun hükmünün ardına düşüp onu iptal edecek yoktur. O, hesabı çabuk görendir."},{"n":42,"t":"Onlardan öncekiler de tuzak kurmuştu. Fakat bütün tuzaklar, (tedbirler) Allâh’ındır. (Allâh’ın tedbiri, onların tuzaklarını bozar. O), her canın ne kazandığını (ne yaptığını) bilir. Kâfirler de, bu yurdun sonunun kimin olacağını bileceklerdir!"},{"n":43,"t":"İnkâr edenler: \"Sen gönderilmiş bir elçi değilsin!\" diyorlar. De ki: \"Benimle sizin aranızda Allâh’ın ve yanında Kitap bilgisi bulunanların şâhid olması yeter.\""}],[{"n":1,"t":"Elif lâm râ. (Bu,) Rablerinin izniyle insanları karanlıklardan aydınlığa çıkarıp o güçlü ve övgüye lâyık olan(Allâh)ın yoluna iletmen için sana indirdiğimiz Kitaptır."},{"n":2,"t":"O Allâh ki, göklerde ve yerde olanların hepsi O’nundur. Çetin azâbdan dolayı vay şu kâfirlerin haline!"},{"n":3,"t":"Ki onlar, dünyâ hayâtını âhirete tercih ederler, Allâh’ın yoluna engel olur ve onun eğrilmesini isterler. İşte onlar, derin bir sapıklık içindedirler."},{"n":4,"t":"Biz, her elçiyi kendi kavminin diliyle gönderdik ki onlara açıklasın. Allâh dilediğini şaşırtır, dilediğini yola iletir. O, azizdir, hüküm ve hikmet sâhibidir."},{"n":5,"t":"Andolsun biz, Mûsâ’yı da \"Kavmini karanlıklardan aydınlığa çıkar, onlara Allâh’ın günlerini (geçmiş milletlerin başlarına gelen olayları) hatırlat!\" diye âyetlerimizle birlikte göndermiştik. Şüphesiz bunda sabreden, şükreden herkes için âyetler (ibret verici işâretler) vardır."},{"n":6,"t":"Mûsâ, kavmine demişti ki: \"Allâh’ın üzerinizdeki ni’metini hatırlayın, O sizi Fir’avn soyundan kurtardı. Onlar sizi işkencenin en kötüsüne koşuyorlar, oğullarınızı kesiyorlar, kadınlarınızı sağ bırakıyorlardı. Bunda Rabbinizden size büyük bir imtihan vardı.\""},{"n":7,"t":"Ve Rabbiniz size şöyle bildirmişti: \"Andolsun şükrederseniz elbette size daha fazla veririm ve eğer nankörlük ederseniz azâbım pek çetindir.\""},{"n":8,"t":"Ve Mûsâ dedi ki: \"Siz ve yeryüzünde bulunanlar hep nankörlük etseniz, iyi bilin ki Allâh zengindir, övülmüştür (sizin şükrünüze muhtaç değildir)\"."},{"n":9,"t":"Sizden öncekilerin: Nûh, ’Âd ve Semûd kavimlerinin ve onlardan sonra gelenlerin -ki onları(n sayısını) Allah’tan başka kimse bilmez- haberi size gelmedi mi? Elçileri onlara kanıtlar getirdi de onlar, ellerini ağızlarına koydu (öfkelerinden parmaklarını ısırdı)lar (yahut: peygamberlerin ağızlarını tuttular): \"Biz sizinle gönderilen mesajı tanımadık ve biz sizin bizi çağırdığınız şeye karşı derin bir kuşku içindeyiz!\" dediler."},{"n":10,"t":"Elçileri: \"Gökleri ve yeri yaratan Allâh hakkında şüphe (edilir) mi? (O), sizin günâhlarınızdan bir kısmını bağışlamak ve sizi belirtilmiş bir süreye kadar ertelemek için sizi davet ediyor\" dediler. Onlar: \"Siz de bizim gibi bir insandan başka bir şey değilsiniz. Bizi, atalarımızın taptığından çevirmek istiyorsunuz. O halde bize açık bir delil getirin!\" dediler."},{"n":11,"t":"Elçileri onlara dediler ki: \"Evet biz de sizin gibi insandan başka bir şey değiliz. Fakat Allâh, kullarından dilediğine lutfeder. Allâh’ın izni olmadan biz size delil getiremeyiz. İnananlar, Allah’a dayansınlar.\""},{"n":12,"t":"\"Bize yollarımızı göstermişken neden biz Allah’a dayanmayalım? Sizin bize yaptığınız eziyetlere katlanacağız. Tevekkül edenler, Allah’a dayansınlar.\""},{"n":13,"t":"İnkâr edenler, elçilerine dediler ki: \"Ya sizi mutlaka yurdumuzdan çıkarırız, ya da bizim dinimize dönersiniz!\" Rableri de onlara şöyle vahyetti, \"zâlimleri mutlaka helâk edeceğiz!\""},{"n":14,"t":"\"Ve onların ardından sizi o yere yerleştireceğiz. Bu, makâmımdan korkan ve tehdidimden korkan için(verdiğim söz)dür.\""},{"n":15,"t":"(Elçiler, düşmanlarına karşı Allah’tan) fetih istediler ve her inatçı zorba perişan oldu."},{"n":16,"t":"Ardından da kendisine irin (gibi) bir suyun içirileceği cehennem vardır."},{"n":17,"t":"O suyu yutmağa çalışır, fakat boğazından geçiremez ve her yandan ona ölüm geldiği halde yine ölemez. Bunun ardından da kaba bir azâb!"},{"n":18,"t":"Rablerine karşı nankörlük edenlerin iyi işleri, tıpkı fırtınalı bir günde rüzgârın savurduğu küle benzer. Kazandıklarından hiçbir şeyi ele geçiremezler. İşte derin sapıklık budur!"},{"n":19,"t":"Allâh’ın, gökleri ve yeri hak(ve hikmet) ile yarattığını görmedin mi? Dilerse sizi götürür ve yepyeni bir halk getirir."},{"n":20,"t":"Bu, Allah’a güç değildir."},{"n":21,"t":"Hepsi Allâh’ın huzûrunda göründüler. Zayıflar, büyüklük taslayan(önder)ler(in)e: \"Biz size tâbi idik. Şimdi siz, bizden Allâh’ın azâbından (en ufak) bir şey savabilir misiniz?\" dediler. (Büyüklük taslayanlar kendilerini ma’zur göstermek için: \"Ne yapalım?\") dediler: \"Allâh bize yol gösterseydi, biz de size yol gösterirdik. Artık biz sızlansak da, sabretsek de birdir; kaçıp sığınacak bir yerimiz yoktur!\""},{"n":22,"t":"İş bitirildikten sonra şeytân (onlara) şöyle dedi: \"Allâh size gerçek va’detti, ben de size va’dettim ama ben sözümden caydım! Benim sizi zorlayacak bir gücüm yoktu. Sadece sizi (küfür ve isyâna) davet ettim. Siz de benim da’vetime koştunuz. O halde beni kınamayın, kendi kendinizi kınayın! Ne ben sizi kurtarabilirim, ne de siz beni kurtarabilirsiniz! Ben, önceden beni (Allah’a) ortak koşmanızı da tanımamıştım zaten. Doğrusu zâlimler için acı bir azâb vardır!\""},{"n":23,"t":"İnanıp iyi işler yapanlar da Rablerinin izniyle sürekli kalacakları, altlarından ırmaklar akan cennetlere sokuldular. Onların orada dirlik temennileri \"selâm\"dır."},{"n":24,"t":"Görmedin mi Allâh nasıl bir benzetme yaptı: Güzel söz, kökü (yerde) sabit, dalları gökte olan güzel bir ağaç gibidir."},{"n":25,"t":"(O ağaç), Rabbinin izniyle her zaman yemişini verir. Allâh, öğüt almaları için insanlara böyle benzetmeler yapar."},{"n":26,"t":"Kötü sözün durumu da gövdesi yerin üstünden koparılmış, sâbit olmayan kötü bir ağaca benzer."},{"n":27,"t":"Allâh, inananları, dünyâ hayâtında da, âhirette de sağlam sözle tesbit eder. Allâh, zâlimleri de şaşırtır ve Allâh, dilediğini yapar."},{"n":28,"t":"Baksana şunlara, Allâh’ın ni’metini nankörlüğe çevirdiler (O’nun verdiği ni’mete şükredecekleri yerde nankörlük edip inkâra saptılar), kavimlerini de helâk yurduna kondurdular."},{"n":29,"t":"Yaslanacakları cehenneme (götürdüler). Ne kötü bir duraktır o!"},{"n":30,"t":"Allâh’ın yolundan saptırmak için O’na eşler koştular. De ki: \"(Şimdilik) eğlenin, gideceğiniz yer ateştir!\""},{"n":31,"t":"İnanan kullarıma söyle: Namazı kılsınlar, ne alışverişin, ne de dostluğun olmadığı bir gün gelmeden önce, kendilerine verdiğimiz rızıktan gizli ve açık sarfetsinler."},{"n":32,"t":"Allâh O’dur ki, gökleri ve yeri yarattı, gökten su indirdi ve onunla size rızık olarak çeşitli meyvalar çıkardı. Buyruğuyla denizde akıp gitmesi için gemileri emrinize verdi, ırmakları emrinize verdi."},{"n":33,"t":"Sürekli olarak (seyir ve aydınlatma) görevlerini yapan güneşi ve ay’ı emrinize verdi, geceyi ve gündüzü de emrinize verdi."},{"n":34,"t":"Ve kendisinden istediğiniz herşeyden size bir parça verdi. Eğer Allâh’ın ni’metini saymak isteseniz sayamazsınız! (Doğrusu) insan çok haksızlık edendir, çok nankördür!"},{"n":35,"t":"Bir zaman İbrâhim, şöyle demişti: \"Rabbim, bu şehri güvenli kıl, beni ve oğullarımı putlara tapmaktan uzak tut!\""},{"n":36,"t":"\"Rabbim, onlar insanlardan birçoğunu şaşırttılar. Artık bundan böyle kim bana uyarsa o bendendir, kim bana karşı gelirse (o da senin merhametine kalmıştır), şüphesiz sen bağışlayan, esirgeyensin.\""},{"n":37,"t":"\"Rabbimiz, ben çocuklarımdan bazısını, senin Harâm Evinin yanında, ekinsiz bir vâdiye yerleştirdim. Rabbimiz, namazı kılsınlar diye (böyle yaptım). Artık sen de insanlardan birtakım gönüllüleri, onları sever yap ve onları çeşitli meyvalarla besle ki şükretsinler.\""},{"n":38,"t":"\"Rabbimiz, sen bizim gizlediğimizi ve açığa vurduğumuzu hep bilirsin. Ne yerde, ne de gökte hiçbir şey Allah’a gizli kalmaz.\""},{"n":39,"t":"\"İhtiyarlık çağımda bana İsmâ’il ve İshak’ı lutfeden Allah’a hamdolsun. Şüphesiz Rabbim du’âyı işiten(kabul buyuran)dır.\""},{"n":40,"t":"\"Rabbim, beni ve zürriyetimden bir kısmını namazı kılan yap; Rabbimiz, du’âmı kabul buyur!\""},{"n":41,"t":"\"Rabbimiz, hesabın görüleceği gün, beni, anamı babamı ve mü’minleri bağışla!\""},{"n":42,"t":"Zâlimlerin yaptığından Allâh’ı gâfil sanma, O, sadece onları, gözlerin dehşetten donup kalacağı bir güne ertelemektedir."},{"n":43,"t":"(O gün) başlarını dikerek koşarlar, bakışları kendilerine dönmez, (öyle donup kalmıştır sanki). Yüreklerinin içi de bomboş havadır. (Şaşkınlıktan, kafalarında düşünce adına bir şey kalmamıştır)."},{"n":44,"t":"İnsanları, kendilerine azâbın geleceği şu güne karşı uyar ki, zâlimler: \"Rabbimiz, derler, bizi yakın bir süreye kadar ertele de senin çağrına gelelim, elçilere uyalım!\" \"Peki, önceden sizin için hiç zeval olmadığına (sürekli yaşayacağınıza) yemin etmemiş miydiniz?\""},{"n":45,"t":"(Sizden önce ’Âd ve Semûd gibi) kendilerine yazık eden milletlerin yerlerinde oturmuştunuz, onlara nasıl yaptığımız, size belli olmuştu ve size benzetmeler de yapıp anlatmıştık (değil mi?)\""},{"n":46,"t":"Onlar tuzaklarını kurdular. Oysa tuzakları dağları yerinden kaldıracak (cinsten) olsa bile onların tuzakları, Allâh’ın yanındaydı (Allâh onların tuzaklarını bozar, cezâlarını verirdi)."},{"n":47,"t":"Sakın, Allâh’ı, elçilerine verdiği sözden cayar, sanma! Çünkü Allâh dâimâ üstündür, öç alandır!"},{"n":48,"t":"O gün yer başka yere, gökler de (başka göklere) değiştirilir. (Bütün) insanlar tek ve kahredici Allâh’ın huzûrunda görünürler."},{"n":49,"t":"Ve o gün suçluları, birbirine (veya elleri ayaklarına) yaklaştırılarak zincirlere vurulmuş görürsün!"},{"n":50,"t":"Gömlekleri katrandandır, yüzlerini de ateş kaplamaktadır."},{"n":51,"t":"Allâh, her canı kazandığiyle cezâlandırmak için (böyle yapar). Şüphesiz Allâh, hesabı çabuk görendir."},{"n":52,"t":"Bu (Kur’ân), insanlara bir tebliğdir. (İnsanlar), bununla uyarılsınlar; O’nun yalnız Tek tanrı olduğunu bilsinler ve sağduyu sahipleri öğüt alsınlar diye (gönderilmiştir)."}],[{"n":1,"t":"Elif lâm râ. Şunlar Kitabın ve apaçık Kur’an’ın âyetleridir."},{"n":2,"t":"Bir zaman gelir ki nankörlük edenler, \"Keşke müslüman olsaydılar\" diye arzu ederler."},{"n":3,"t":"Bırak onlar yesinler, eğlensinler; arzu onları oyalasın. Yakında (yaptıklarının kötü sonucunu) bileceklerdir."},{"n":4,"t":"Biz hiçbir kenti yok etmedik ki, onun mutlaka bilinen bir yazısı olmasın (helâk ettiğimiz her ülkenin yazılmış, tesbit edilmiş bir süresi vardır. O süre dolunca onları yok etmişizdir)."},{"n":5,"t":"Hiçbir millet ne süresini geçebilir, ne de (ondan) geri kalır (her kavim mutlaka, kendileri için belirtilmiş sürede helâk olur)."},{"n":6,"t":"Dediler ki: \"Ey kendisine Zikir (Kitap) indirilmiş olan, sen mutlaka cinlenmişsin!\""},{"n":7,"t":"\"Eğer doğrulardansan, bize melekleri getirsene!\""},{"n":8,"t":"Biz, melekleri ancak hak ile (hikmet gereğince) indiririz, o zaman da kendilerine asla göz açtırılmaz, (derhal işleri bitirilir, mahvolup giderler)."},{"n":9,"t":"O Zikri (Kitap)ı biz indirdik biz; ve O’nun koruyucusu da elbette biziz!"},{"n":10,"t":"Andolsun, senden önceki milletlerin kolları içine de elçiler gönderdik."},{"n":11,"t":"Onlara hiçbir elçi gelmezdi ki, onunla alay etmesinler."},{"n":12,"t":"İşte biz o(Tanrı Zikri)ni suçluların kalblerine böyle sokarız."},{"n":13,"t":"Kendilerinden öncekilerin sünneti (inkârcıların mahvedileceği yasası) geçtiği halde yine de ona inanmazlar."},{"n":14,"t":"Onlara gökten bir kapı açsak da oraya çıkacak olsalardı:"},{"n":15,"t":"\"Herhalde gözlerimiz döndürüldü, biz büyülenmiş bir topluluğuz,\" derlerdi."},{"n":16,"t":"Andolsun biz, gökte burçlar yaptık. Ve onu bakanlar için süsledik."},{"n":17,"t":"Ve onu, her recim (taşlanmış, kovulmuş uydurma sözler atan) şeytândan koruduk."},{"n":18,"t":"Ancak kulak hırsızlığı eden olursa, onu da parlak bir ışın kovalar."},{"n":19,"t":"Arzı da yaydık, oraya sağlam dağlar attık ve orada ölçülü mütenâsib şeyler bitirdik."},{"n":20,"t":"Orada sizin için ve (beslediğinizi sandığınız, fakat aslında) sizin beslemediğiniz kimseler için geçimlikler var ettik."},{"n":21,"t":"Hiçbir şey yoktur ki onun hazineleri, bizim yanımızda olmasın, ama biz onu, bilinen bir miktar ile indiririz."},{"n":22,"t":"Rüzgârları, aşılayıcı olarak gönderdik de gökten su indirdik, böylece sizi suladık. Onu depolayan siz değilsiniz."},{"n":23,"t":"Biziz, elbette biz ki, yaşatır, öldürürüz; gerçek vâris olan da biziz (her fâninin mülkü bize geçer. Ölmeyen, dâimâ kalan yalnız biziz)."},{"n":24,"t":"Andolsun, sizden önce geçenleri de bildik, sonra gelenleri de bildik."},{"n":25,"t":"Gerçekten onları toplayacak olan, Rabbindir. O hükümdardır, bilendir."},{"n":26,"t":"Andolsun biz insanı pişmemiş çamurdan, değişmiş cıvık balçıktan yarattık."},{"n":27,"t":"Cinne gelince onu da (insandan) daha önce, (vücudun gözeneklerine) nüfuz eden kavurucu ateşten yarattık."},{"n":28,"t":"Bir zaman Rabbin meleklere demişti ki: \"Ben kupkuru çamurdan, değişken balçıktan bir insan yaratacağım!\""},{"n":29,"t":"\"Onu düzenle(yip insan şekline koydu)ğum ve ona ruhumdan üflediğim zaman hemen ona secdeye kapanın!\""},{"n":30,"t":"Meleklerin hepsi topluca secde ettiler."},{"n":31,"t":"Yalnız İblis, secde edenlerle beraber olmayı kabul etmedi."},{"n":32,"t":"(Allâh): \"Ey İblis, nen var ki, sen secde edenlerle beraber olmadın?\" dedi."},{"n":33,"t":"(İblis): \"Ben bir çamurdan, değişken bir balçıktan yarattığın insana secde edemem!\" dedi."},{"n":34,"t":"(Allâh): \"Öyleyse çık oradan (meleklerin içinden çık), dedi, çünkü sen kovuldun!\""},{"n":35,"t":"\"Tâ cezâ gününe kadar üzerine lâ’net edilecektir!\""},{"n":36,"t":"(İblis): \"Rabbim,\" dedi \"bâri tekrar dirilecekleri güne kadar beni(m canımı almayı) ertele!\""},{"n":37,"t":"(Allâh): \"Haydi,\" dedi, \"sen ertelenmişlerdensin!\""},{"n":38,"t":"\"O bilinen vaktin gününe kadar!\""},{"n":39,"t":"(İblis): \"Rabbim, dedi, beni azdırmandan ötürü andolsun ki, ben de yer yüzünde onlara (günâhları) süsleyeceğim ve onların hepsini azdıracağım."},{"n":40,"t":"Ancak içlerinden kendilerine ihlas verilen kulların hâriç. (Benim azdırmam, onları etkilemez.)"},{"n":41,"t":"(Allâh) buyurdu ki: \"İşte bana varan doğru yol budur.\""},{"n":42,"t":"\"Benim hâlis kullarıma karşı senin bir gücün yoktur. Ancak sana uyan azgınlar(ı azdırabilirsin)\"."},{"n":43,"t":"Cehennem o (şeytâna uya)nların hepsinin buluşma yeridir."},{"n":44,"t":"Onun yedi kapısı vardır. Her kapıya, onlardan bir bölüm ayrılmıştır."},{"n":45,"t":"(Şeytâna uymaktan, küfür ve isyândan) korunanlar ise cennetlerde, pınar başlarındadırlar."},{"n":46,"t":"(Onlara): \"Oraya esenlikle, güven içinde girin!\" (denilir)."},{"n":47,"t":"Onların göğüslerindeki kini çıkarıp atmışızdır; (hepsi) kardeşler olarak divanlar üzerinde karşı karşıya oturur (sohbet eder)ler."},{"n":48,"t":"Orada onlara hiçbir yorgunluk dokunmaz ve onlar oradan çıkarılacak da değillerdir."},{"n":49,"t":"(Ey Muhammed), kullarıma haber ver: İşte ben öyle bağışlayan, öyle esirgeyenim."},{"n":50,"t":"Fakat benim azâbım da çok acı bir azâbdır."},{"n":51,"t":"Onlara İbrâhim’in konuklarından haber ver;"},{"n":52,"t":"Onun yanına girmişler: \"Selâm\" demişlerdi. O da: \"Biz sizden korkuyoruz.\" dedi."},{"n":53,"t":"\"Korkma dediler, biz sana bilgin bir çocuk(un olacağını) müjdeleriz!\""},{"n":54,"t":"\"Bana ihtiyarlık dokunduktan sonra mı beni müjdelediniz? Ne tuhaf bir şey ile müjdeliyorsunuz beni?\" dedi."},{"n":55,"t":"\"Sana gerçeği müjdeledik, umut kesenlerden olma!\" dediler."},{"n":56,"t":"\"Sapıklardan başka kim Rabbinin rahmetinden umut keser?\" dedi."},{"n":57,"t":"(İbrâhim gelenlerin Hak elçileri melekler olduklarını anlayınca): \"Ey elçiler, dedi, işiniz nedir?\""},{"n":58,"t":"\"Biz suç işleyen bir kavme gönderildik,\" dediler."},{"n":59,"t":"Yalnız Lût âilesi suçlu değildir. Biz onların hepsini kurtaracağız.\""},{"n":60,"t":"\"Ancak karısı hâriç. Onun da (suçlularla beraber) kalanlardan olmasını uygun gördük.\""},{"n":61,"t":"Elçiler Lût âilesine geldiklerinde:"},{"n":62,"t":"(Lût): \"Siz hiç tanınmamış kimselersiniz!\" dedi."},{"n":63,"t":"Dediler ki: \"Doğrusu, biz onların, hakkında şüphe ettikleri((tanrı azâbı)nı sana getirdik,\""},{"n":64,"t":"\"Sana gerçeği getirdik, biz elbette doğru söyleyenleriz!\""},{"n":65,"t":"\"Hemen gecenin bir parçasında âileni yürüt, sen de arkalarından git, içinizden hiç kimse ardına dönüp bakmasın. Emredildiğiniz yere gidin!\""},{"n":66,"t":"Ona: \"Şunlar sabaha girerlerken arkaları kesilecektir!\" buyruğunu bildirdik."},{"n":67,"t":"(Lût kavminin oturduğu Sodom) Kent (inin) halkı, (Lût’un genç konuklarını duyup) sevinerek geldiler."},{"n":68,"t":"(Lût onlara): \"Bunlar benim konuğumdur, dedi, beni mahcubetmeyin!\""},{"n":69,"t":"\"(Ne olur), Allah’tan korkun, beni rezil etmeyin!\""},{"n":70,"t":"\"Seni âlemlerden (başkalarının işine karışmaktan) menetmemiş miydik?\" dediler."},{"n":71,"t":"\"Eğer yapacaksanız, işte kızlarım.\" dedi."},{"n":72,"t":"Senin ömrüne andolsun ki, onlar, sarhoşlukları içinde bocalıyorlardı."},{"n":73,"t":"Güneşin doğma zamanına girerlerken korkunç ses onları yakaladı."},{"n":74,"t":"O kentin üstünü altına getirdik ve üzerlerine de çamurdan pişmiş taşlar yağdırdık."},{"n":75,"t":"Şüphesiz bunda işâretten anlayanlara (nice) ibretler vardır."},{"n":76,"t":"Ve o (kent, herkesin gelip geçtiği) bir yol üzerinde durmaktadır."},{"n":77,"t":"Elbette bunda inananlar için bir ibret vardır."},{"n":78,"t":"Gerçekten Eyke halkı da zâlim kimselerdi."},{"n":79,"t":"Onlardan da öcümüzü aldık, her ikisi de (Sodom da, Eyke de) hâlâ (yol üzerinde, gözler) ön(ün) de apaçık durmaktadır."},{"n":80,"t":"Andolsun Hicr halkı (Semûd kavmi) de peygamberleri yalanladılar."},{"n":81,"t":"Onlara âyetlerimizi verdik, ama onlardan yüz çeviriyorlardı."},{"n":82,"t":"Dağlardan güvenli evler yontuyorlardı."},{"n":83,"t":"Sabaha girerlerken onları da (o) korkunç ses yakaladı."},{"n":84,"t":"Kazandıkları, kendilerinden hiçbir şeyi savamadı."},{"n":85,"t":"Biz gökleri yeri ve bunlar arasında bulunanları hak ile yarattık; (gerçeğin ortaya çıkacağı) o sâ’at, mutlaka gelecektir! Şimdi sen güzel bir hoşgörü ile hareket et."},{"n":86,"t":"Yaratan, bilen ancak Rabbindir.."},{"n":87,"t":"Andolsun sana ikililerden yedi ve bu büyük Kur’ân’ı verdik."},{"n":88,"t":"Onlardan bazı çiftlere (sınıflara) verdiğimiz dünyâlığa gözlerini dikme ve (sana inanmadıkları için) onlara üzülme. Mü’minlere kanadını indir, (onlara karşı mütevâzi, şefkatli davran)."},{"n":89,"t":"Ve: \"Ben, ancak ben, apaçık bir uyarıcıyım!\" de."},{"n":90,"t":"(Siz bilirsiniz, inanmazsanız Allâh’ın azâbı başınıza inecektir.) Tıpkı o bölücülere (veya and içenlere) indirdiğimiz gibi (sizin başınıza da azâb indiririz)!"},{"n":91,"t":"Onlar ki Kur’ân’ı bölük bölük ettiler."},{"n":92,"t":"Senin Rabbin hakkı için biz onların hepsine mutlaka soracağız:"},{"n":93,"t":"Yaptıkları şeylerden."},{"n":94,"t":"Sen emrolunduğun şeyi açıkça söyle ve ortak koşanlara aldırma."},{"n":95,"t":"O alay edenlere karşı biz sana yeteriz."},{"n":96,"t":"O, Allâh ile beraber başka tanrı tutanlar, yakında (yaptıklarının sonucunu) bileceklerdir!"},{"n":97,"t":"Andolsun onların söylediklerine senin göğsünün daraldığını (canının sıkıldığını) biliyoruz."},{"n":98,"t":"Sen Rabbini hamd ile tesbih et (O’nu övecek sözlerle an, subhanallahi velhamdulillah de) ve secde edenlerden ol."},{"n":99,"t":"Ve Rabbine kulluk et ki sana yakin gelsin (kesin bilgiye eresin)!"}],[{"n":1,"t":"Allâh’ın emri geldi, artık onu acele istemeyin. Allâh, onların ortak koştukları şeylerden uzaktır, yücedir."},{"n":2,"t":"Melekleri, kullarından dilediğine, emrinden olan ruh (vahy) ile indirir: \"(İnsanları) Benden başka tanrı yoktur, benden korkun! diye uyarın!\" (der)."},{"n":3,"t":"(Allâh), gökleri ve yeri hak ile (hikmeti uyarınca) yarattı. (O), onların ortak koştuklarından yücedir."},{"n":4,"t":"İnsanı nutfe(sperm)den yarattı, birden o (insan) konuşkan bir karşı koyucu olup çıktı."},{"n":5,"t":"Hayvanları da yarattı. Onlarda sizin için ısınma(nızı sağlayan şeyler) ve daha birçok yararlar vardır. Ve onlardan kimini de yersiniz."},{"n":6,"t":"Ve akşamleyin mer’adan getirdiğiniz, sabahleyin mer’aya götürdüğünüz zaman onlarda sizin için bir güzellik de vardır. (Onların gidiş gelişleri size ayrı bir güzellik ve zevk verir.)"},{"n":7,"t":"Ağırlıklarınızı öyle (uzak) şehirlere taşırlar ki, (onlar olmasa) canlar(ınız), büyük zahmetler çekmeden oraya varamazdınız. Doğrusu Rabbiniz, çok şefkatli, çok acıyandır."},{"n":8,"t":"Binmeniz ve süs için atları, katırları ve merkepleri (yarattı) ve daha sizin bilmediğiniz nice şeyler yaratmaktadır."},{"n":9,"t":"Kısa ve doğru yolu Allâh gösterir. Ama o yoldan sapan da var. Allâh dileseydi, hepinizi doğru yola iletirdi."},{"n":10,"t":"O’dur ki, sizin için gökten bir su indirdi. İçeceğ(iniz) ondandır ve hayvanları otlattığınız ağaç(lar, bitkiler) ondan(sulanıp filizlenmekte)dir."},{"n":11,"t":"Onunla size ekin, zeytin, hurma, üzümler ve her çeşit meyvalardan bitirmektedir. Şüphesiz bunda düşünen bir toplum için ibret vardır."},{"n":12,"t":"Geceyi, gündüzü, güneşi ve ay’ı sizin hizmetinize verdi. Yıldızlar da O’nun emriyle (size) boyun eğdirilmiştir. Şüphesiz bunda aklını kullanan bir toplum için ibretler vardır."},{"n":13,"t":"Yeryüzünde yarattığı çeşitli renklerdeki (hayvanları, bitki)leri de (sizin hizmetinize verdi). Şüphesiz bunda öğüt alan bir toplum için ibret vardır."},{"n":14,"t":"O, denizi de (hizmetinize) verdi ki ondan taptaze et yiyesiniz ve ondan kuşanacağınız süsler çıkarasınız. Görüyorsun ki gemiler, denizi yara yara akıp gitmektedir. Allâh’ın lutfunu aramanız ve O’na şükretmeniz için."},{"n":15,"t":"Sizi sarsar diye arza ağır baskılar attı, ırmaklar ve yollar yaptı ki doğru yolu bulasınız (amaçlarınıza eresiniz)."},{"n":16,"t":"(Yol bulmak için yararlanılacak) işâretler de (yarattı). Onlar yıldız(lar)la da yol bulurlar."},{"n":17,"t":"Yaratan, yaratmayan gibi midir? Hiç düşünmüyor musunuz?"},{"n":18,"t":"Eğer Allâh’ın ni’metini saysanız, sayamazsınız. Doğrusu Allâh çok bağışlayan, çok esirgeyendir."},{"n":19,"t":"Allâh, gizlediğiniz ve açığa vurduğunuz her şeyi bilir."},{"n":20,"t":"Allah’tan başka yalvardıkları (tanrılar), hiçbir şey yaratamazlar, zaten kendileri yaratılmaktadırlar."},{"n":21,"t":"Onlar ölüdürler, diri değildirler. Ne zaman dirileceklerini de bilmezler."},{"n":22,"t":"Tanrınız bir tek Tanrıdır. Ama âhirete inanmayanların kalbleri inkârcıdır, onlar büyüklük taslarlar."},{"n":23,"t":"Gerçekten Allâh, onların gizlediklerini de bilir, açığa vurduklarını da. O, büyüklük taslayanları sevmez."},{"n":24,"t":"Onlara: \"Rabbiniz ne indirdi?\" dendiği zaman, \"Evvelkilerin masalları!\" derler."},{"n":25,"t":"Ki kıyâmet günü hem kendi vebâllerini tam olarak yüklensinler, hem de bilgisizce saptırdıkları kimselerin vebâllerinden bir kısmını. Bak, ne kötü şey yükleniyorlar!"},{"n":26,"t":"Onlardan öncekiler de tuzak kurmuşlardı da Allâh, binâlarına temellerinden gelmiş, üstlerindeki tavan, başlarına çökmüştü! Ve azâb onlara ummadıkları yerden gelmişti."},{"n":27,"t":"Sonra kıyâmet günü de, onları rezil eder ve \"Hani haklarında (mü’minlere) düşmanlık ettiğiniz ortaklarım nerede?\" der. Kendilerine ilim verilmiş olanlar: \"Bugün rezillik ve kötülük kâfirleredir!\" derler."},{"n":28,"t":"Nefislerine zulmederlerken meleklerin, canlarını aldığı kimseler; \"Biz hiçbir kötülük yapmıyorduk!\" diye teslim olurlar. \"Hayır, Allâh sizin yaptıklarınızı biliyor.\""},{"n":29,"t":"\"Onun için, içinde sürekli kalmak üzere cehennemin kapılarına girin. Kibirlenenlerin yeri ne kötüdür!\""},{"n":30,"t":"(Allâh’ın azâbından) korunanlara da: \"Rabbiniz ne indirdi?\" dendi. \"Hayır (indirdi).\" dediler. Bu dünyâda güzel iş yapanlara güzellik vardır, (onlar için) âhiret yurdu ise daha hayırlıdır. Korunanların yurdu ne güzeldir."},{"n":31,"t":"Altlarından ırmaklar akan adn cennetlerine girerler. Orada onlar için diledikleri her şey vardır. İşte Allâh, korunanları böyle mükâfâtlandırır."},{"n":32,"t":"Melekler, iyi insanlar olarak canlarını aldığı kimselere de: \"Selâm size, yaptıklarınıza karşılık cennete girin!\" derler."},{"n":33,"t":"(İnkâr edenler) İlle kendilerine meleklerin gelmesini, yahut Rabbinin (azâb) emrinin gelmesini mi bekliyorlar? Onlardan öncekiler de öyle yapmıştı. Allâh onlara zulmetmedi, fakat onlar kendi kendilerine zulmediyorlardı."},{"n":34,"t":"Nihâyet yaptıklarının kötülükleri onlara ulaştı ve alay ettikleri şey onları kuşattı."},{"n":35,"t":"(Allah’a) ortak koşanlar, \"Allâh dileseydi ne biz, ne de atalarımız O’ndan başka bir şeye tapmazdık ve O’nsuz hiçbir şeyi harâm kılmazdık!\" dediler. Onlardan öncekiler de böyle yapmıştı. Elçilere düşen, yalnız açıkça tebliğ etmek değil midir?"},{"n":36,"t":"Andolsun biz, her millet içinde: \"Allah’a kulluk edin, şeytân(a tapmak)dan kaçının\" diye bir elçi gönderdik. Onlardan kimine Allâh hidâyet etti, onlardan kimine de sapıklık gerekli oldu. İşte yeryüzünde gezin de bakın, yalanlayanların sonu nasıl olmuş!"},{"n":37,"t":"(Ey Muhammed) Sen onların yola gelmelerini ne kadar istesen de Allâh şaşırttığını yola getirmez ve onların yardımcıları da olmaz!"},{"n":38,"t":"(Onlar), yeminlerinin bütün şiddetiyle: \"Allâh ölen kimseyi diriltmez!\" diye Allah’a yemin ettiler. Hayır diriltecektir, bu, O’nun gerçek olarak verdiği sözdür. Ama insanların çoğu bilmezler."},{"n":39,"t":"(Diriltecektir ki) Hakkında ihtilâf ettikleri gerçeği onlara açıklasın ve inkâr edenler de yalancı olduklarını bilsinler."},{"n":40,"t":"Biz bir şeyi(n olmasını) istediğimiz zaman, söyleyeceğimiz söz, sadece ona \"ol\" dememizdir, derhal oluverir."},{"n":41,"t":"Kendilerine zulmedildikten sonra Allâh uğrunda göç edenleri, dünyâda güzelce yerleştireceğiz, (onlara vereceğimiz) âhiret mükâfâtı ise daha büyüktür. Keşke bilseler!"},{"n":42,"t":"Onlar ki sabrettiler ve Rablerine dayanmaktadırlar."},{"n":43,"t":"Biz senden önce de, kendilerine vahyettiğimiz erkeklerden başkasını elçi göndermedik. Sorun, Zikir ehline; eğer bilmiyorsanız:"},{"n":44,"t":"Açık kanıtları ve Kitapları. Sana da o Zikr’i indirdik ki, kendilerine indirileni insanlara açıklayasın, tâ ki düşünüp öğüt alsınlar."},{"n":45,"t":"Kötülükler yapmayı kuranlar, Allâh’ın, kendilerini yer(in dibin)e geçirmeyeceğinden, yahut hiç ummadıkları bir yerden kendilerine azâbın gelmeyeceğinden emin midirler?"},{"n":46,"t":"Yahut dönüp dolaşırlarken onun, kendilerini yakalamayacağından (emin midirler)? Kendileri buna engel olacak değillerdir!"},{"n":47,"t":"Yahut (azâbın) kendilerini bir korku üzerinde yakalamayacağından (emin midirler)? Doğrusu Rabbiniz, çok şefkatli, çok acıyandır!"},{"n":48,"t":"Allâh’ın yarattığı şeylerin gölgelerinin dahi nasıl sağdan, soldan sürünüp Allah’a secde ederek döndüğünü görmediler mi? (Her şeyin gölgesi yerde uzanıp kısalarak hep Allah’a secde etmektedir)."},{"n":49,"t":"Göklerde ve yerde bulunan canlıların, meleklerin hepsi Allah’a secde ederler, onlar asla büyüklük taslamazlar."},{"n":50,"t":"Üstlerindeki Rablerinden korkarlar ve emredildikleri şeyi yaparlar."},{"n":51,"t":"Allâh: \"İki tanrı tutmayın. O, ancak tek Tanrıdır. Yalnız benden korkun!\" dedi."},{"n":52,"t":"Göklerde ve yerde ne varsa hepsi O’nundur. Kulluğun da yalnız O’na yapılması lâzımdır. Siz, Allah’tan başkasından mı korkuyorsunuz?"},{"n":53,"t":"Size ulaşan her ni’met Allah’tandır. Sonra size bir sıkıntı dokunduğu zaman da yalnız O’na yalvarırsınız."},{"n":54,"t":"Sonra, sizden o sıkıntıyı kaldırdığı zaman içinizden bir grup, hemen Rablerine ortak koşarlar."},{"n":55,"t":"Ki kendilerine verdiğimiz (ni’metlere ve yaptığımız iyiliğ)e karşı nankörlük etsinler. Öyleyse eğlenin, yakında bileceksiniz!"},{"n":56,"t":"Kendilerine verdiğimiz rızıktan, (hiçbir şey) bilmeyen(tanrı)lar(ın)a pay ayırıyorlar. Allah’a andolsun ki siz, bu uydurduğunuz şeylerden mutlaka sorulacaksınız."},{"n":57,"t":"O şânı yüce Allah’a kızları veriyorlar (melekleri Allâh’ın kızları sanıyorlar) da kendilerine hoşlandıkları(erkek çocukları)nı (alıyorlar). (Kız çocuklarından arlanıyorlar. Peki ama neden arlandıkları şeyleri Allah’a lâyık görüyorlar?)"},{"n":58,"t":"Onlardan birine dişi (çocuğu olduğu) müjdelendiği zaman içi öfkeyle dolarak yüzü kapkara kesilir."},{"n":59,"t":"Kendisine verilen müjdenin kötülüğünden dolayı kavminden gizlenir. (Şimdi ne yapsın) onu, hakaretle tutsun mu yoksa onu toprağa mı gömsün! Bak, ne kötü hüküm veriyorlar!"},{"n":60,"t":"Âhirete inanmayanların durumu, kötüdür. En yüce durum, Allâh’ındır. O, üstün hüküm ve hikmet sâhibidir."},{"n":61,"t":"Eğer Allâh, insanları, yaptıkları (her) haksızlıkla cezâlandırsaydı, yeryüzünde tek canlı bırakmazdı. Fakat onları takdir edilen bir süreye kadar erteler. Süreleri geldiği zaman da bir sâ’at dahi ne geri kalırlar, ne de ileri geçerler (derhal mahvolup giderler)."},{"n":62,"t":"Kendilerinin hoşlanmadıkları şeyi Allah’a veriyorlar, üstelik de dilleri, \"En güzel sonuç, kendilerinin olacak\" diye yalan söylüyor. Onlara mutlaka ateş vardır ve onlar ona sürüleceklerdir!"},{"n":63,"t":"Allah’a andolsun ki senden önceki milletlere de elçi gönderdik; şeytân onlara yaptıkları işleri süsledi. (Bu yüzden peygamberleri yalanladılar). O, bugün de onların dostudur. Onlar için acı bir azâb vardır."},{"n":64,"t":"Biz sana Kitabı indirdik ki, hakkında ayrılığa düştükleri şeyi onlara açıklayasın ve (o Kitap), inanan bir kavim için yol gösterici ve rahmet olsun."},{"n":65,"t":"Allâh, gökten bir su indirdi, onunla yeri ölümünden sonra diriltti, şüphesiz bunda işiten bir millet için ibret vardır."},{"n":66,"t":"Hayvanlarda da sizin için ibret vardır. Size onların karınlarından, fışkı ile kan arasından (çıkardığımız) hâlis, içenlere (içimi) kolay süt içiriyoruz."},{"n":67,"t":"Hurma ağaçlarının meyvalarından ve üzümlerden de sarhoşluk ve güzel rızık elde edersiniz. Şüphesiz bunda aklını kullanan bir toplum için ibret vardır."},{"n":68,"t":"Rabbin, bal arısına şöyle vahyetti: \"Dağlardan, ağaçlardan ve kurdukları çardaklardan evler edin!\""},{"n":69,"t":"\"Sonra her çeşit meyvalardan ye de Rabbinin yollarında boyun eğerek yürü!\" Onun karınlarından, renkleri çeşit çeşit bir içecek çıkar ki onda insanlara şifa vardır. Şüphesiz bunda düşünen bir millet için ibret vardır."},{"n":70,"t":"Allâh sizi yarattı, sonra öldürür; içinizden kimi de ömrün en reziline (bebeklik çağı gibi güçsüz ihtiyarlık çağına) itilir ki, biraz bilgiden sonra hiçbir şeyi bilmez olsun! Doğrusu Allâh bilendir. (O, her şeye) kâdirdir."},{"n":71,"t":"Allâh, rızıkta kiminizi kiminizden üstün kıldı. (Rızıkça) üstün kılınanlar, ellerinin altında bulunanlara kendi rızıklarını verip de hepsi rızıkta eşit olmuyorlar. Allâh’ın ni’metini mi inkâr ediyorlar?"},{"n":72,"t":"Allâh size kendi nefislerinizden eşler yarattı ve eşlerinizden de size oğullar ve torunlar yarattı ve sizi güzel rızıklarla besledi. Böyle iken onlar, bâtıla inanıp da Allâh’ın ni’metine nankörlük mü ediyorlar?"},{"n":73,"t":"Allah’tan başka, göklerden ve yerden kendileri için hiçbir rızık veremeyecek ve bunu asla yapamayacak olan şeylere mi tapıyorlar?"},{"n":74,"t":"Allah’a meseller vermeğe (benzetmeler yapmağa) kalkmayın! Çünkü Allâh (benzetme yapmayı) bilir, siz ise bilmezsiniz!"},{"n":75,"t":"Allâh, hiçbir şeye gücü yetmeyen ve başkasının malı olan bir köle ile; kendisine güzel rızık verdiğimiz, o rızıktan gizli ve açık harcayan kimseyi misal olarak anlattı. Hiç bunlar bir olurlar mı? Hamd Allah’a mahsustur, fakat çokları bilmezler."},{"n":76,"t":"Ve Allâh şu iki adamı da misal olarak anlattı: Birisi dilsizdir, hiçbir şey yapamaz, efendisinin üzerine bir yüktür. (Efendisi) onu nereye gönderse bir hayır getirmez (bir iş beceremez). Şimdi bu (adam), doğru yolda giderek adâleti emreden kimse gibi olur mu?"},{"n":77,"t":"Göklerin ve yerin gaybı Allah’a aittir. O sâ’atin işi, bir göz açıp yumma gibi, yahut daha yakın(kısa)dır. Şüphesiz Allâh, her şeye gücü yetendir."},{"n":78,"t":"Allâh sizi, (hiçbir şey bilmediğiniz durumda) annelerinizin karınlarından çıkardı, size işitme (duyusu), gözler ve gönüller verdi ki şükredesiniz."},{"n":79,"t":"Göğün boşluğunda, O’nun emrine boyun eğdirilmiş olan kuşlara bakmadılar mı? Onları Allah’tan başka tutan yoktur. Şüphesiz bunda inanan bir kavim için âyetler (Allâh’ın büyüklüğüne işâretler) vardır."},{"n":80,"t":"Allâh size, evlerinizi oturma yeri yaptı ve size hayvan derilerinden, göç gününüzde (yolculukta) ve ikâmet gününüzde (oturma zamanlarınızda) kolayca kullanacağınız hafif evler (çadırlar, portatif evler) ve yünlerinden, yapağılarından ve kıllarından bir süreye kadar (kullanacağınız) giyilecek, döşenecek eşya ve geçimlik (ticaret malı) yaptı."},{"n":81,"t":"Allâh, yarattıklarından sizin için gölgeler yaptı ve sizin için dağlarda oturulacak barınaklar (mağaralar) var etti ve sizi sıcaktan koruyan elbiseler ve savaşta sizi koruyan elbiseler (zırhlar) var eyledi. Allâh size ni’metini böyle tamamlıyor ki siz müslüman olup esenliğe eresiniz."},{"n":82,"t":"Eğer yine yüz çevirirlerse, artık senin üzerine düşen sadece açık bir şekilde duyurmaktır."},{"n":83,"t":"Allâh’ın ni’metini bilirler (bu ni’metleri Allâh’ın yarattığını kabul ederler), sonra da (bunları kendilerine verenden başkasına taparak) bu ni’metleri inkâr ederler, çokları da (nankördürler)."},{"n":84,"t":"Her ümmetten bir şâhid getirdiğimiz gün, artık ne nankörler(in konuşmaların)a izin verilir, ne de onların özür dilemeleri istenir."},{"n":85,"t":"Zulmedenler azâbı gördükleri zaman artık azâb onlardan ne hafifletilir, ne de onlara fırsat verilir."},{"n":86,"t":"Ortak koşanlar, ortak koştukları şeyleri gördükleri zaman: \"Rabbimiz, işte senden başka yalvar(ıp tap)dığımız ortaklarımız!\" derler. (Onlar da bunlara): \"Siz tamamen yalancılarsınız!\" diye söz atarlar."},{"n":87,"t":"O gün (ortak koşanlar) Allah’a teslim olmuşlar ve uydurup durdukları şeyler kendilerinden sapıp gitmiştir."},{"n":88,"t":"Nankörlük edip Allâh’ın yoluna engel olan kimselerin, -bozgunculuklarından dolayı- azâplarının üstüne azâb katmışızdır!"},{"n":89,"t":"Her ümmet içinde, kendi aralarından, aleyhlerine bir şâhid getireceğimiz gün, seni de bunların aleyhine şâhid getirmiş olacağız. Sana bu Kitabı, her şeyi açıklayan ve müslümanlara yol gösterici, rahmet ve müjde olarak indirdik."},{"n":90,"t":"Allâh adâleti, ihsanı, akrabâya vermeyi emreder, fahşâ(edepsizlikten)dan, münker(fenâlık)den ve bağy(azgınlık)den meneder. Öğüt almanız için size böyle öğüt verir."},{"n":91,"t":"Andlaşma yaptığınız zaman Allâh’ın ahdini tam yerine getirin (verdiğiniz sözü tutun), pekiştirdikten sonra yeminleri bozmayın. Çünkü Allâh’ı üzerinize kefil (şâhid) yaptınız. Allâh yaptıklarınızı bilir."},{"n":92,"t":"Bir topluluk, diğer bir topluluktan (sayıca ve malca) daha çok olduğu için, yeminlerinizi aranızda bozucu bir vasıta yaparak, ipliğini kuvvetli büktükten sonra çözen kadın gibi olmayın! Çünkü Allâh, sizi bununla dener. Hakkında ayrılığa düştüğünüz şeyleri kıyâmet günü size açıklayacaktır."},{"n":93,"t":"Allâh dileseydi, hepinizi, bir tek ümmet yapardı, fakat (O), dilediğini şaşırtır, dilediğini doğru yola iletir. Ve siz, mutlaka yaptığınız şeylerden sorulacaksınız."},{"n":94,"t":"Yeminlerinizi aranızı bozan bir şey yapmayın, sonra sağlam basmış olan ayak, kayar ve Allâh’ın yoluna engel olduğunuzdan dolayı kötülüğü(n cezâsını) tadarsınız ve büyük bir azâba uğrarsınız."},{"n":95,"t":"Allah’a verdiğiniz sözü (peygambere yaptığınız bey’atı) az bir paraya satmayın. Zira bilirseniz Allâh’ın yanında olan, sizin için daha hayırlıdır."},{"n":96,"t":"Sizin yanınızda bulunan (dünyâ malı) tükenir. Allâh’ın yanında bulunan ise kalıcıdır. Biz sabredenlerin karşılığını yaptıklarının en güzeliyle vereceğiz."},{"n":97,"t":"Erkek ve kadından her kim inanmış olarak iyi bir iş yaparsa, onu (dünyâda) hoş bir hayâtla yaşatırız, onların ücretini yaptıklarının en güzeliyle veririz."},{"n":98,"t":"Kur’ân, oku(mak iste)diğin zaman kovulmuş şeytândan Allah’a sığın."},{"n":99,"t":"Çünkü inananlara ve Rablerine dayananlara o(şeytâ)nın bir gücü yoktur."},{"n":100,"t":"Onun gücü, sadece kendisini dost tutanlara ve Allah’a ortak koşanlaradır (o, sadece onları etkileyebilir)."},{"n":101,"t":"Biz bir âyetin yerine başka bir âyet getirdiğimiz zaman, -Allâh ne indirdiğini bilirken- \"Sen (Allah’a) iftirâ ediyorsun (bu sözleri kendin uydurup Allâh’ın üstüne atıyorsun)\" derler. Hayır, onların çokları bilmiyorlar."},{"n":102,"t":"De ki: \"İnananları sağlamlaştırmak ve müslümanlara yol gösterici ve müjde olmak üzere onu, Ruhu’l-Kudüs (Cebrâil) Rabbinden gerçek (bilgi) olarak indirdi.\""},{"n":103,"t":"Biz onların, \"Ona bir insan öğretiyor!\" dediklerini biliyoruz. Hak’tan saparak kendisine yöneldikleri adamın dili a’cemi (yabancıdır, açık değildir), bu ise apaçık Arapça bir dildir."},{"n":104,"t":"Allâh’ın âyetlerine inanmayanları Allâh doğru yola iletmez, onlar için acı bir azâb vardır."},{"n":105,"t":"Yalanı ancak Allâh’ın âyetlerine inanmayanlar uydurur; yalancılar, işte onlardır."},{"n":106,"t":"İnandıktan sonra Allah’a nankörlük eden, -kalbi imanla yatışmış olduğu halde (inkâra) zorlanan değil- fakat küfre göğüs açan, (küfürle sevinç duyan) kimselere Allah’tan bir gazab iner ve onlar için büyük bir azâb vardır."},{"n":107,"t":"Bu, onların dünyâ hayâtını âhirete tercih etmelerinden ve Allâh’ın, inkâr eden kavmi doğru yola iletmeyeceğinden ötürü böyledir."},{"n":108,"t":"Onlar, Allâh’ın kalblerini kulaklarını ve gözlerini mühürlediği kimselerdir. İşte gâfiller onlardır."},{"n":109,"t":"Elbette onlar, âhirette ziyana uğrayacaklardır."},{"n":110,"t":"Sonra Rabbin, şunların şu işkenceye uğratıldıktan sonra göç eden, sonra savaşan ve sabredenlerin yanındadır. Elbette (bütün) bun(lar)dan sonra Rabbin bağışlayan, esirgeyendir."},{"n":111,"t":"O gün herkes gelir, kendi canını kurtarmak için uğraşır ve herkese yaptığının tam karşılığı verilir, onlara asla haksızlık edilmez."},{"n":112,"t":"Allâh şöyle bir kenti misal olarak anlattı: Güven, huzûr içinde idi; her yerden rızkı bol bol kendisine geliyordu. Fakat Allâh’ın ni’metlerine nankörlük etti, bunun üzerine (halkının) yaptıklarından ötürü Allâh ona açlık ve korku elbisesi taddırdı."},{"n":113,"t":"Andolsun, onlara, kendilerinden bir elçi geldi, onu yalanladılar. Bunun üzerine onlar zulümlerine devam ederken azâb onları yakalayıverdi."},{"n":114,"t":"Allâh’ın size verdiği rızıktan helâl, hoş olarak yeyin de Allâh’ın ni’metine şükredin; eğer O’na kulluk ediyorsanız."},{"n":115,"t":"Allâh size ölüyü, kanı, domuz etini ve Allah’tan başkasının adı anılarak kesilen(hayvanlar)ı harâm kıldı. Kim mecbur kalırsa (başkasının hakkına) saldırmadan, sınırı da aşmadan (bunlardan) yiyebilir. Şüphesiz Allâh, bağışlayan, esirgeyendir."},{"n":116,"t":"Dillerinizin yalan yere nitelendirmesinden ötürü \"Şu helâldir, şu harâmdır,\" demeyin, sonra Allah’a karşı yalan uydurmuş olursunuz. Allah’a karşı yalan uyduranlar ise iflâh olmazlar."},{"n":117,"t":"Azıcık yaşama(nın ardından), onlara acı bir azâb gelecektir."},{"n":118,"t":"Yahûdi olanlara da, bundan önce sana anlattıklarımızı harâm kılmıştık. Biz onlara zulmetmedik, fakat onlar kendi kendilerine zulmediyorlardı!"},{"n":119,"t":"Sonra Rabbin şunlardan yanadır ki, cehâletle kötülük işlediler, sonra onun ardından tevbe ettiler, uslandılar. Bütün bunlardan sonra Rabbin, elbette bağışlayandır, esirgeyendir."},{"n":120,"t":"İbrâhim Allâh’ı birleyerek O’na itâ’at eden bir ümmet (her iyiliği kendinde toplayan bir önder) idi, ortak koşanlardan değildi."},{"n":121,"t":"O’nun ni’metlerine şükredici idi. (Allâh) onu seçmiş ve doğru yola iletmişti."},{"n":122,"t":"Ona dünyâda iyilik vermiştik. O, âhirette de iyilerdendir."},{"n":123,"t":"Sonra sana: \"Allâh’ı birleyerek İbrâhim’in yoluna uy; o, ortak koşanlardan değildi\" diye vahyettik."},{"n":124,"t":"Cumartesi (gününü ta’til ve ibâdet günü yapmak), onda ayrılığa düşen(yahûdi)lere (farz) kılındı. Rabbin, elbette ayrılığa düştükleri şey hakkında kıyâmet günü aralarında hükmünü verecektir."},{"n":125,"t":"Hikmetle ve güzel öğütle Rabbinin yoluna çağır ve onlarla en güzel biçimde mücâdele et. Kuşkusuz Rabbin, işte yolundan sapanları en iyi bilen O’dur ve O, yola gelenleri de en iyi bilendir."},{"n":126,"t":"Eğer azâb edecekseniz, size yapılan azâb kadar azâb edin. Ama sabrederseniz, andolsun ki o, sabredenler için daha iyidir. (Hz. peygamber, Uhud Savaşında, amcası Hamza’yı kâfirler tarafından burnu ve kulakları kesilmiş, ciğeri çıkartılmış bir durumda görünce; \"Allah’a andolsun ki, eğer Allah bana zafer verirse, senin yerine, onlardan yetmiş kişiyi böyle yapacağım!\" demişti. Fakat yemînine keffâret vererek bu sözünü uygulamamış, Mekke’nin Fethinde düşmanlarını affetmiştir.)"},{"n":127,"t":"Sabret, sabrın ancak Allâh(ın yardımı) iledir. Onlara üzülme, kurdukları tuzaklardan da sıkıntıya düşme."},{"n":128,"t":"Çünkü Allâh, korunanlarla ve iyilik edenlerle beraberdir."}],[{"n":1,"t":"Eksiklikten uzaktır O (Allâh) ki gecenin bir vaktinde kulunu, âyetlerimizden bir bölümünü, kendisine göstermemiz için, Mescid-i Harâm’dan, çevresini bereketli kıldığımız Mescid-i Aksâ’ya yürüttü. Gerçekten O, işitendir, görendir."},{"n":2,"t":"Biz Mûsâ’ya Kitabı verdik ve onu İsrâil oğullarına \"Benden başka bir vekil tutmayın!\" diye bir kılavuz yaptık."},{"n":3,"t":"Ey Nûh ile beraber (gemide) taşıdıklarımızın çocukları, doğrusu o (Nûh), çok şükreden bir kuldu. (Siz de atanız gibi olun.)"},{"n":4,"t":"Kitapta İsrâil oğullarına şu hükmü verdik: \"Siz o ülkede iki kez bozgunculuk yapacaksınız ve çok böbürleneceksiniz (zorbalık edeceksiniz)!"},{"n":5,"t":"Birincisinin zamanı gelince üzerinize çok güçlü kullarımızı gönderdik, evlerin aralarına girip (sizi) araştırdılar. Bu, yapılması gereken bir va’d idi."},{"n":6,"t":"Sonra tekrar size, onları yenme imkânı verdik ve sizi mallarla, oğullarla destekledik ve savaşçılarınızı çoğalttık."},{"n":7,"t":"İyilik ederseniz, kendinize iyilik etmiş olursunuz. Kötülük ederseniz, o da kendi aleyhinizedir. Son taşkınlığınızın zamanı gelince (yine öyle kullar göndeririz) ki, yüzlerinizi kötü duruma soksunlar (üzüntüden suratlarınızın asılmasına sebeb olsunlar) ve ilk kez girdikleri gibi yine Mescid’e (Kudüs’e) girsinler ve ele geçirdiklerini mahvetsinler."},{"n":8,"t":"(Bundan sonra) Belki Rabbiniz size acır, ama siz (bozgunculuk yapmaya) dönerseniz, biz de (sizi cezâlandırmağa) döneriz. Cehennemi, kâfirler için kuşatıcı (bir zindan) yapmışızdır!"},{"n":9,"t":"Gerçekten bu Kur’ân da en doğru yola iletir ve iyi işler yapan mü’minlere, kendileri için büyük bir ecir olduğunu müjdeler."},{"n":10,"t":"Âhirete inanmayanlara da acı bir azâb hazırlamışızdır."},{"n":11,"t":"İnsan, hayra du’â eder gibi, şerre du’â etmekte(hayrı ister gibi şerri istemekte)dir. İnsan pek acelecidir."},{"n":12,"t":"Biz gece ve gündüzü, (kudretimizi gösteren) iki âyet yaptık. Gece âyetini sildik, gündüz âyetini aydınlatıcı yaptık ki hem Rabbinizin lutfunu arayasınız ve hem de yılların sayısını ve hesabı bilesiniz. Biz her şeyi açık açık anlattık."},{"n":13,"t":"Her insanın tâir(kuş)ini boynuna bağladık, kıyâmet günü onun için, açılmış olarak bulacağı bir kitâp çıkarırız:"},{"n":14,"t":"\"Kitabını oku, bugün nefsin sana hesapçı olarak yeter!\" (deriz)."},{"n":15,"t":"Kim yola gelirse kendisi için yola gelmiş olur, kim de saparsa kendi aleyhine sapar. Hiçbir günâhkâr, başkasının günâh yükünü taşımaz. Biz elçi göndermedikçe azâb edecek değiliz."},{"n":16,"t":"Biz bir kenti helâk etmek istediğimiz zaman onun varlıklılarına emrederiz, orada kötü işler yaparlar, böylece o ülkeye (azâb) karâr(ı) gerekli olur, biz de orayı darmadağın ederiz."},{"n":17,"t":"Nitekim Nûh’dan sonra nice kuşakları helâk ettik. Kullarının günâhlarını haber alıcı, görücü olarak Rabbin yeter."},{"n":18,"t":"Kim bu aceleci(dünyâ)yı isterse, orada ona, (evet) istediğimiz kimseye hemen çabucak dilediğimiz kadar veririz; ama sonra yerini cehennem yaparız! Kınanmış ve kovulmuş olarak oraya girer."},{"n":19,"t":"Kim de âhireti ister ve inanarak ona yaraşır biçimde çalışırsa, öylelerinin çalışmalarının karşılığı verilir."},{"n":20,"t":"Hepsine onlara da, onlara da (dünyâyı isteyenlere de, âhireti isteyenlere de, mü’minlere de, kâfirlere de) Rabbinin vergisiden uzatırız. Rabbinin vergisi kesilmez."},{"n":21,"t":"Bak, (rızık bakımından) nasıl onların kimini kiminden üstün yaptık. Elbette âhiret, dereceler bakımından da daha büyük, üstünlük bakımından da daha büyüktür."},{"n":22,"t":"Allâh ile beraber başka bir tanrı edinme, sonra kınanmış ve yalnız başına bırakılmış olarak oturup kalırsın!"},{"n":23,"t":"Rabbin, yalnız kendisine tapmanızı ve anaya babaya, iyilik etmenizi emretti. İkisinden birisi, yahut her ikisi, senin yanında ihtiyarlık çağına ulaşır(ihtiyarlık zamanlarında senin yanında kalırlar)sa sakın onlara \"Öf!\" deme, onları azarlama! Onlara güzel söz söyle."},{"n":24,"t":"Onlara acımadan dolayı, küçülme kanadını indir, (onlara karşı alçak gönüllü ol) ve: \"Ey (her varlığı terbiye edip yetiştiren) Rabbim! Bunlar, beni küçükken nasıl (acıyıp) yetiştirdilerse sen de bunlara (öyle) acı!\" de."},{"n":25,"t":"Rabbiniz içlerinizdekini daha iyi bilir. Eğer siz iyi kişiler olursanız şüphesiz O, tevbe edenleri bağışlayandır."},{"n":26,"t":"Akrabâya, yoksula ve yolcuya hakkını ver, fakat saçıp savurma."},{"n":27,"t":"Çünkü savurganlar, şeytânların kardeşleri olmuşlardır. Şeytân ise Rabbine karşı çok nankördür!"},{"n":28,"t":"Eğer (elin dar olduğu için) Rabbinden umduğun bir rahmeti bekleyerek onlardan yüz çevirecek, (onlara birşey vermeyecek) olursan, bari onlara yumuşak söz söyle."},{"n":29,"t":"El(ler)ini boynuna bağlanmış yapma, tamamen de açma, sonra kınanır, hasret içinde kalırsın."},{"n":30,"t":"Rabbin dilediğine rızkı açar (bol bol verir, dilediğine) kısar. Çünkü O, kulları(nın hâli)ni bilir, görür."},{"n":31,"t":"Fakirlik korkusuyla çocuklarınızı öldürmeyin. Onları da sizi de biz besliyoruz. Onları öldürmek, büyük günâhtır."},{"n":32,"t":"Zinâya yaklaşmayın, çünkü o, açık bir kötülüktür, çok kötü bir yoldur!"},{"n":33,"t":"Allâh’ın harâm kıldığı canı haksız yere öldürmeyin. Kim haksızlıkla öldürülürse, onun velisi(olan mirâsçısı)na yetki vermişizdir (öldürülenin hakkını arar. Fakat o da) öldürmede aşırı gitmesin. Çünkü kendisine yardım edilmiş(yetki verilmiş)tir."},{"n":34,"t":"Yetimin malına yaklaşmayın, ancak erginlik çağına erişinceye kadar en güzel bir tarzda (onun malını kullanıp geliştirebilirsiniz). Ahdi de yerine getirin, çünkü ahd’den sorulacaktır."},{"n":35,"t":"Ölçtüğünüz zaman ölçüyü tam yapın, doğru terazi ile tartın. Bu daha iyidir, sonuç bakımından da daha güzeldir."},{"n":36,"t":"Bilmediğin bir şeyin ardına düşme, çünkü kulak, göz ve gönül, bunların hepsi o(yaptığı)ndan sorumludur."},{"n":37,"t":"Yeryüzünde kabara kabara yürüme. Çünkü sen yeri yırtamazsın, boyca da dağlara erişemezsin!"},{"n":38,"t":"Bunlar(\"Allâh ile beraber başka tanrı edinme!\" âyetinden itibaren sayılan fiiler)in hepsi, kötü olan, Rabbinin katında hoş görülmeyen şeylerdir."},{"n":39,"t":"Şunlar, Rabbinin, Hikmet’ten sana vahyettiği(emirleri)ndendir. Allâh ile berebar başka tanrı edinme, sonra kınanmış, (Allâh’ın rahmetinden) uzaklaştırılmış olarak cehenneme atılırsın."},{"n":40,"t":"Rabbiniz, oğulları size seçti de kendisine meleklerden kadınlar mı edindi? Gerçekten siz büyük (çok tehlikeli) bir söz söylüyorsunuz!"},{"n":41,"t":"Biz Kur’ân’da sözü türlü biçimlerde anlattık ki, düşünüp anlasınlar. Fakat bu, onların sadece kaçışlarını artırıyor."},{"n":42,"t":"De ki: \"Eğer dedikleri gibi O’nunla beraber (başka) tanrılar olsaydı o zaman onlar da Arşın sâhibine gitmenin yolunu ararlardı."},{"n":43,"t":"Hâşâ, O, onların dediklerinden çok yücedir, uludur."},{"n":44,"t":"Yedi gök, arz ve bunların içinde bulunanlar, O’nu tesbih ederler. O’nu övgü ile tesbih etmeyen hiçbir şey yoktur, ama siz onların tesbihlerini anlamazsınız. O, halimdir, çok bağışlayandır."},{"n":45,"t":"Kur’ân okuduğun zaman seninle, âhirete inanmayanların arasına gizli bir perde çekeriz."},{"n":46,"t":"Kablerine -onu anlamalarına engel olacak- kabuklar, kulaklarına da bir ağırlık koyarız. Kur’ân’da yalnız Rabbini andığın zaman (tek Tanrı inancından hoşlanmadıkları için) arkalarına dönüp kaçarlar."},{"n":47,"t":"Biz onların, seni dinlerken ne sebeple dinlediklerini, kendi aralarında gizli konuşurlarken de o zâlimlerin: \"Siz büyülenmiş bir adamdan başkasına uymuyorsunuz!\" dediklerini gâyet iyi biliyoruz."},{"n":48,"t":"Bak, nasıl misaller verdiler (seni şâ’ire, büyücüye, kâhine ve mecnuna benzettiler) de şaştılar. Artık bir daha yolu bulamazlar."},{"n":49,"t":"Dediler ki: \"Biz kemikler haline geldikten, ufalanıp toprak olduktan sonra mı sâhiden biz mi yeni bir yaratılışla diriltileceğiz?\""},{"n":50,"t":"De ki: \"İster taş olun, ister demir,\""},{"n":51,"t":"\"İster gönlünüzde büyüyen, (aklınıza tuhaf gelen) herhangi bir yaratık, (ne olursanız olun, Allâh sizi mutlaka diriltecektir). \"Bizi kim tekrar (hayâta) döndürebilir?\" diyecekler. \"Sizi ilk defa yaratan (döndürür)\" de. Sana alaylı alaylı başlarını sallayacaklar ve: \"Ne zaman o?\" diyecekler. \"Pek yakın olabilir\" de."},{"n":52,"t":"Sizi çağıracağı gün O’na hamdederek çağrısına uyarsınız (dirilip kalkarsınız) ve (dünyâda) pek az kaldığınızı sanırsınız."},{"n":53,"t":"Kullarıma söyle: En güzel sözü söylesinler (puta tapanlara sert davranmasınlar). Çünkü şeytân aralarına girer (onları tartışmaya ve kavgaya dürtükler). Doğrusu şeytân, insanın apaçık düşmanıdır."},{"n":54,"t":"Rabbiniz sizi daha iyi bilir. Dilerse size acır, dilerse size azâbeder. Biz seni, onların üzerine vekil göndermedik."},{"n":55,"t":"Rabbin, göklerde ve yerde olan kimseleri daha iyi bilir (O, peygamber olmağa kimi lâyık görürse onu seçer). Andolsun ki biz, peygamberlerin kimini kimine üstün kıldık, Dâvûd’a da Zebûr’u verdik."},{"n":56,"t":"De ki: \"O’ndan başka (tanrı olduğunu) sandığınız şeylere yalvarın; onlar ne sizden sıkıntıyı kaldırabilirler, ne de (onu) başka bir yana çevirebilirler."},{"n":57,"t":"O yalvardıkları da, onların (Allah’a) en yakın olan(lar)ı da Rablerine yaklaşmak için vesile ararlar; O’nun merhametini umarlar, azâbından korkarlar. Çünkü Rabbinin azâbı, cidden korkunçtur."},{"n":58,"t":"Hiçbir kent yoktur ki biz, kıyâmet gününden önce onu yok edecek, yahut ona şiddetli bir şekilde azâbedecek olmayalım. Bu, Kitapta yazılmıştır."},{"n":59,"t":"Bizi âyetler (mu’cizeler) göndermekten alıkoyan şey, evvelkilerin, (onları) yalanlamış olmasıdır. Semûd(kavmin)e açık bir mu’cize olarak dişi deveyi verdik, o zulmetmelerine sebeb oldu (deveyi boğazlayarak kedilerine yazık etmiş oldular). Biz mu’cizeleri, yalnız korkutmak için göndeririz."},{"n":60,"t":"Bir zaman sana: \"Rabbin insanları kuşatmıştır, (suçluları cezalandırmak üzeredir)\" demiştik. Sana gösterdiğimiz rü’yâyı ve Kur’ân’da la’netlenmiş ağacı, insanları(n imanını) sınama (aracı) yaptık. Biz onları (çeşitli biçimlerde) korkutuyoruz. Fakat korkutmamız onların azgınlıklarını daha da artırmaktan başka bir katkı yapmıyor."},{"n":61,"t":"Bir zaman meleklere: \"Âdem’e secde edin!\" demiştik. Secde ettiler, yalnız İblis etmedi: \"Ben çamur olarak yarattığın kimseye secde eder miyim? dedi."},{"n":62,"t":"\"Şu benden üstün yaptığını gördün mü (nesi var onun ki onu benden üstün kıldın)? Andolsun, eğer beni kıyâmet gününe kadar ertelersen, onun zürriyetini, pek azı hariç kökünden koparıp sürükleyeceğim!\" dedi."},{"n":63,"t":"(Allâh) \"(defol) git, dedi, onlardan kim sana uyarsa cezânız cehennemdir, mükemmel bir cezâ (size)!\""},{"n":64,"t":"\"Onlardan gücünün yettiğini sesinle yerinden oynat; atlıların ve yayalarınla onların üzerine yaygarayı bas; mallarda ve evlâdlarda onlara ortak ol; onlara (çeşitli) va’dler yap (va’dlerinle onları oyala)\"; şeytân, onlara aldatmadan başka bir şey va’detmez."},{"n":65,"t":"\"Benim (gerçek) kullarım(a gelince) senin onlar(ı kandırmağ)a gücün yetmez!\" vekil olarak Rabbin yeter."},{"n":66,"t":"(Ey insanlar), Rabbiniz O’dur ki lutfundan (payınızı) aramanız için size gemileri denizde yürütür. Doğrsu O, size çok acır."},{"n":67,"t":"Denizde size bir sıkıntı (boğulma korkusu) dokunduğu zaman O’ndan başka bütün yalvardıklarınız kaybolur (artık o zaman, Allah’tan başka kimseden yardım istemezsiniz. Çünkü O’ndan başka sizi kurtaracak kimse yoktur). Fakat (O) sizi kurtarıp karaya çıkarınca yine (Allâh’ı bir tanımaktan) yüz çevirirsiniz. Gerçekten insan nankördür."},{"n":68,"t":"(Allâh’ın) Karayı ters çevirip sizi batırmayacağından, yahut üzerinize taşlar savuran bir kasırga göndermeyeceğinden emin misiniz? (Ki bunlar olduktan) Sonra kendinize bir koruyucu bulamazsınız!"},{"n":69,"t":"Yoksa O’nun sizi bir kez daha denize gönderip, üstünüze, kırıp geçiren bir fırtına salarak inkâr ettiğinizden dolayı sizi boğmayacağından emin misiniz? O zaman bize karşı sizi izleyip koruyacak birini bulamazsınız!"},{"n":70,"t":"Andolsun biz, Âdem oğullarına çok ikrâm ettik: onları karada ve denizde (hayvanlar ve taşıtlar üzerinde) taşıdık. Onları güzel rızıklarla besledik ve onları yarattıklarımızın bir çoğundan üstün kıldık."},{"n":71,"t":"Her milleti, imâmıyla (eylemlerini saptayan defteriyle veya izlediği önderiyle) çağırdığımız gün, kimlerin Kitabı sağından verilirse işte onlar, Kitaplarını okurlar ve en ufak bir haksızlığa uğratılmazlar."},{"n":72,"t":"Şu dünyâda kör olan kimse, âhirette de kördür (dünyâda doğru yolu göremeyen, âhirette de kurtuluş yolunu göremeyecektir, hattâ onun) yolu daha da sapıktır."},{"n":73,"t":"Az daha onlar, baskı ile seni, sana vahyettiğimizden ayırarak ondan başkasını üstümüze atman için kandıracaklardı. İşte o zaman seni dost edinirlerdi."},{"n":74,"t":"Eğer biz seni sağlamlaştırmamış olsaydık, onlara bir parça yanaşacaktın."},{"n":75,"t":"O takdirde sana hayâtın da, ölümün de kat kat(azâb)ını taddırırdık. Sonra bize karşı bir yardımcı da bulamazdın."},{"n":76,"t":"Neredeyse seni yurdundan çıkarmak için tedirgin edeceklerdi. O takdirde kendileri de senin ardından pek az kalabilirler."},{"n":77,"t":"Senden önce gönderdiğimiz elçilerimizin de yasası (budur). Bizim yasamızda bir değişiklik bulamazsın."},{"n":78,"t":"Güneşin sarkmasından (aşağı kaymasından) gecenin kararmasına (yatsı vaktine) kadar namaz kıl ve sabahın Kur’ân’ın(ı, uzunca Kur’ân okunan sabah namazını) da (unutma). Çünkü sabah Kur’ân (okuması) görülecek şeydir."},{"n":79,"t":"Ayrıca sana özgü olarak gecenin bir kısmında da Kur’ân oku(yup namaz kıl)mak üzere uyan! Rabbinin seni güzel bir makama ulaştırması umulur."},{"n":80,"t":"De ki: \"Rabbim, beni doğruluk girdirişiyle girdir ve beni doğruluk çıkarışiyle çıkar. Bana katından yardımcı bir güç ver.\""},{"n":81,"t":"De ki: \"Hak geldi, bâtıl gitti; zaten bâtıl yok olmağa mahkûmdur.\""},{"n":82,"t":"Biz Kur’ân’dan mü’minlere şifâ ve rahmet olan şeyler indiriyoruz. Ama bu, zâlimlerin ziyanını artırmaktan başka bir katkıda bulunmaz."},{"n":83,"t":"İnsana ni’met verdiğimiz zaman, yüz çevirip yan çizer. Ona bir zarar dokununca da umutsuzluğa düşer."},{"n":84,"t":"De ki: \"Herkes kendi karakterine göre hareket eder. Rabbiniz kimin en doğru yolda olduğunu daha iyi bilir.\""},{"n":85,"t":"Sana ruhtan sorarlar. De ki: \"Ruh, Rabbimin emrindendir. Size ilimden pek az bir şey verilmiştir.\""},{"n":86,"t":"Andolsun, biz dilesek, sana vahyettiğimiz(âyetler)i tamamen gideririz; sonra onun (geri alınması) için bize karşı sana bir yardımcı bulamazsın."},{"n":87,"t":"Ancak Rabbin sana acıyarak âyetlerini geri almamaktadır. Çünkü O’nun sana olan lutfu cidden büyüktür."},{"n":88,"t":"De ki: \"Andolsun eğer insan(lar) ve cin(ler) bu Kur’ân’ın bir benzerini getirmek üzere toplansalar ve birbirlerine arka ol(up yardım et)seler yine onun benzerini getiremezler.\""},{"n":89,"t":"Andolsun biz bu Kur’ân’da insanlara her çeşit misali türlü biçimlerde anlattık, ama insanlardan çoğu inkârda direttiler."},{"n":90,"t":"Dediler ki: \"Yerden bize bir göze fışkırtmadıkça sana inanmayız!\""},{"n":91,"t":"\"Yahut senin hurmalardan ve üzümlerden oluşan bir bahçen olmalı, aralarından ırmaklar fışkırtmalısın!\""},{"n":92,"t":"\"Yahut zannettiğin gibi üzerimize gökten parçalar düşürmelisin, yahut Allâh’ı ve melekleri karşımıza getirmelisin (onlar senin doğru söylediğine şâhidlik etmelidirler)!\""},{"n":93,"t":"\"Yahut altundan bir evin olmalı, ya da göğe çıkmalısın. Ama, sen üzerimize, okuyacağımız bir Kitap indirmedikçe senin sadece göğe çıkmana da inanmayız!\" De ki: \"Rabbimin şânı yücedir. (Böyle şeyleri yapmak benim işim değildir). Ben, sadece elçi ol(arak gönderil)en bir insan değil miyim?\""},{"n":94,"t":"Zâten kendilerine hidâyet geldiği zaman insanları doğru yola gelmekten alıkoyan şey, hep: \"Allâh, bir insanı elçi mi gönderdi?\" demeleridir."},{"n":95,"t":"De ki: \"Eğer yer yüzünde uslu uslu yürüyen melekler olsaydı, elbette onlara gökten bir meleği elçi gönderirdik.\""},{"n":96,"t":"De ki: \"Benimle sizin aranızda şâhid olarak Allâh yeter. O, kulları(nın halleri)ni haber alır, görür.\""},{"n":97,"t":"Allâh kime hidâyet ederse, işte doğru yolu bulan odur. Kimi de sapıklıkta bırakırsa artık onlar için O’ndan başka veliler bulamazsın. Kıyâmet günü onları, yüzükoyun, kör, dilsiz ve sağır bir halde süreriz. Varacakları yer cehennemdir. Ateş her dindikçe, onlara çılgın alevi artırırız."},{"n":98,"t":"İşte cezâları budur. Çünkü onlar, âyetlerimizi inkâr ettiler ve: \"Biz kemikler ve ufalanmış toprak haline geldikten sonra mı, biz mi yeni bir yaratılışla diriltileceğiz?\" dediler."},{"n":99,"t":"Görmediler mi ki, gökleri ve yeri yaratan Allâh, kendilerinin benzerini yaratmağa da kâdirdir? Kendileri için, bir süre koymuştur, onda hiç şüphe yoktur. Ama zâlimler inkârdan başka bir şey yapmazlar."},{"n":100,"t":"De ki: \"Eğer Rabbimin rahmet hazinelerine siz sâhip olsaydınız, harcamaktan korkarak tutardınız.\" Gerçekten insan çok cimridir!"},{"n":101,"t":"Andolsun biz Mûsâ’ya açık açık dokuz mu’cize vermiştik. İşte İsrâil oğullarına sor: Mûsâ onlara gelmiş; Fir’avn ona: \"Ey Mûsâ, ben seni büyülenmiş sanıyorum\" demişti."},{"n":102,"t":"Mûsâ dedi ki: \"Bunları, ancak göklerin ve yerin Rabbinin, (benim doğruluğumu belgeleyen) kanıtlar olarak indirdiğini pekâlâ bildin. Ey Fir’avn, ben de seni mahvolmuş görüyorum.\""},{"n":103,"t":"Fir’avn onları o ülkeden sürüp çıkarmak istedi, biz de onu, yanındakilerle birlikte toptan boğduk."},{"n":104,"t":"Onun ardından İsrâil oğullarına: \"O ülkede oturun, âhiret zamanı gelince hepinizi toplayıp bir araya getireceğiz,\" dedik."},{"n":105,"t":"Biz o(Kur’â)nı hak olarak indirdik ve o, hak ile inmiştir. Seni de ancak bir müjdeleyici ve uyarıcı olarak gönderdik."},{"n":106,"t":"Onu, insanlara ağır ağır okuman için, okuma parçalarına ayırdık ve onu azar azar indirdik."},{"n":107,"t":"De ki: \"Siz ister ona inanın, ister inanmayın, O, daha önce kendilerine bilgi verilenlere okunduğu zaman onlar, derhal çeneleri üstüne secdeye kapanırlar.\""},{"n":108,"t":"\"Rabbimizin şânı yücedir, gerçekten Rabbimizin sözü mutlaka yerine getirilir!\" derler."},{"n":109,"t":"Ağlayarak çeneleri üstüne kapanırlar ve Kur’ân onların derin saygısını artırır."},{"n":110,"t":"De ki: \"İster Allâh diye çağırın, ister Rahmân diye çağırın. Hangisiyle çağırsanız en güzel isimler O’nundur.\" Namazında pek bağırma, pek de sesini gizleme, bu ikisinin arasında bir yol tut."},{"n":111,"t":"\"Çocuk edinmeyen, mülkte ortağı olmayan, acze düşüp de yardımcıya ihtiyacı bulunmayan Allah’a hamdolsun!\" de ve O’nu gereği gibi tekbir et (saygı ve tekbir ile an)."}],[{"n":1,"t":"Allah’a hamdolsun ki, kuluna Kitabı indirdi ve ona hiçbir eğrilik koymadı."},{"n":2,"t":"Onu dosdoğru (bir Kitâp) olarak indirdi ki katından gelecek şiddetli azâba karşı (insanları) uyarsın ve iyi işler yapan mü’minlere de kendileri için güzel mükâfât bulunduğunu müjdelesin."},{"n":3,"t":"Onlar sürekli olarak o mükâfât içinde bulunacaklardır."},{"n":4,"t":"Ve: \"Allâh çocuk edindi\" diyenleri de uyarsın."},{"n":5,"t":"Bu hususta ne kendilerinin, ne de atalarının hiçbir bilgisi yoktur. Ağızlarından ne büyük (küstahça) söz çıkıyor! Onlar, yalandan başka bir şey söylemiyorlar."},{"n":6,"t":"Herhalde sen, onlar bu söze inanmıyorlar diye, peşlerinde üzüntüden kendini helâk edeceksin!"},{"n":7,"t":"Biz yeryüzündeki şeyleri, kendisine süs olsun diye yarattık ki onların, hangisinin daha güzel iş yaptığını deneyelim."},{"n":8,"t":"Biz elbette (bir gün) yerin üzerindekileri kupkuru bir toprak yaparız."},{"n":9,"t":"Yoksa sen, sadece Kehf ve Rakim sâhiplerinin bizim şaşılacak âyetlerimizden olduklarını mı sandın? (onlardan başka çok daha acâip âyetlerimiz vardır. Arzı yeşertip sonra kurutmamız da şaşılacak âyetlerimizden değil midir?)"},{"n":10,"t":"O gençler mağaraya sığındılar: \"Rabbimiz, bize katından bir rahmet ver ve bize şu işimizden bir çıkış yolu hazırla!\" dediler."},{"n":11,"t":"Bunun üzerine mağarada nice yıllar onların kulaklarına ağırlık vurduk (onları derin bir uykuya daldırdık)"},{"n":12,"t":"Sonra onları uyandırdık ki, (onların uyuma müddetleri hakkında ihtilâf eden) iki zümreden hangisinin, (onların) kaldıkları süreyi daha iyi hesâb edeceğini bilelim."},{"n":13,"t":"Biz sana onların haberlerini gerçek olarak anlatıyoruz: Onlar Rablerine inanmış gençlerdi. Biz de onların hidâyetlerini artırmıştık."},{"n":14,"t":"Kalblerinin üstüne metânet bağlamıştık. Kalktılar, dediler ki: \"Rabbimiz göklerin ve yerin Rabbidir. Biz O’ndan başkasına Tanrı demeyiz. Yoksa saçma söylemiş oluruz.\""},{"n":15,"t":"\"Şunlar, şu kavmimiz O’ndan başka tanrılar edindiler. Onların tanrı olduğuna açık bir delil getirmeleri gerekmez miydi? Allah’a karşı yalan uydurandan daha zâlim kim olabilir?\""},{"n":16,"t":"(İçlerinden biri şöyle dedi): \"Mâdem ki siz onlardan ve Allah’tan başka taptıkları şeylerden ayrıldınız, o halde mağaraya sığının ki, Rabbiniz size rahmetinden bir parça yaysın (rızkınızı açıp bollaştırsın) ve (şu) işinizden size yararlı bir şey hazırlasın.\""},{"n":17,"t":"Güneşi görürsün, doğduğu zaman mağaralarından sağa doğru eğiliyor, battığı zaman da sola doğru onları makaslayıp geçiyor (hiçbir halde onların üzerine düşüp kendilerini rahatsız etmiyor) ve onlar, mağaranın geniş bir dehlizi içindedirler. Bu (durum), Allâh’ın âyetlerindendir. Allâh kimi doğru yola iletirse o, yolu bulmuştur; kimi de sapıklıkta bırakırsa, artık onun için yol gösteren bir dost bulamazsın."},{"n":18,"t":"Uykuda oldukları halde sen onları uyanıklar sanırsın onları (uykuda) sağa sola çeviririz. Köpekleri de girişte iki kolunu (ön ayaklarını) uzatmış vaziyettedir. Onların durumunu görseydin, mutlaka onlardan dönüp kaçardın. Ve onlardan içine korku dolardı."},{"n":19,"t":"Yine böyle onları dirilttik ki, kendi aralarında (birbirlerine) sorsunlar: İçlerinden biri: \"Ne kadar kaldınız?\" dedi. \"Bir gün, ya da günün bir parçası (kadar kaldık).\" dediler. (Fakat işin içyüzünü iyice bilmediklerinden herşeyi en iyi bilenin Allâh olduğunu ifade ettiler): \"Ne kadar kaldığınızı Rabbiniz daha iyi bilir, dediler, birinizi şu gümüş (para) ile şehre gönderin, baksın, hangi yiyecek daha temiz (ve nefis) ise ondan size bir azık getirsin; fakat çok dikkatli davransın, sakın sizi birisine sezdirmesin.\""},{"n":20,"t":"\"Çünkü onlar sizi ellerine geçirirlerse taşlayarak öldürürler, yahut kendi dinlerine döndürürler ki, o takdirde asla iflâh olamazsınız.\""},{"n":21,"t":"(Nasıl onları uyutup sonra uyandırdıksa yine) böylece onları (bazı insanlara) buldurduk ki, Allâh’ın (öldükten sonra diriltme) va’dinin gerçek olduğunu ve (Duruşma) saatin(in geleceğin)de asla şüphe olmadığını bilsinler. (Bulanlar), o sırada kendi aralarında onların durumlarını tartışıyorlardı: \"Onların üstüne bir binâ yapın!\" dediler. Rableri onları daha iyi bilir. Onların işine gaalip gelen(yetkili)ler: \"Mutlaka onların üstüne bir mescid yapacağız\" dediler."},{"n":22,"t":"Görülmeyene taş atar gibi: \"Onlar üçtür, dördüncüleri köpekleridir\" diyecekler; \"Beştir, altıncıları köpekleridir\" diyecekler. \"(Hayır,) Yedidir, sekizincileri köpekleridir.’ diyecekler. De ki: \"Onların sayısını Rabbim daha iyi bilir. Onları bilen azdır.\" Onun için onlar hakkında, sathi tartışma dışında, derin münakaşaya girme ve onlar hakkında bunlardan hiçbirine bir şey sorma."},{"n":23,"t":"Hiçbir şey için \"Bunu yarın yapacağım\" deme."},{"n":24,"t":"Ancak \"Allâh dilerse (yapacağım)\" (de). Unuttuğun zaman Rabbini an ve \"Rabbimin beni bundan daha doğru bir bilgiye ulaştırcağını umarım\" de."},{"n":25,"t":"\"Mağaralarında üçyüz yıl kaldılar. Dokuz (yıl) da ilâve ettiler.\""},{"n":26,"t":"De ki: \"Onların ne kadar kaldıklarını Allâh daha iyi bilir. Göklerin ve yerin gaybı O’nundur. O ne güzel görendir, ne güzel işitendir! Onların, O’ndan başka bir yardımcısı yoktur. Ve O, kendi hükmüne kimseyi ortak etmez.\""},{"n":27,"t":"Rabbinin Kitabı’ndan sana vahyedileni oku; O’nun sözlerini değiştirecek yoktur. O’ndan başka sığınılacak bir kimse de bulamazsın."},{"n":28,"t":"Nefsini, sabah akşam, rızâsını isteyerek Rablerine yalvaranlarla beraber tut (onlarla beraber bulunmağa candan sabret). Gözlerin, dünyâ hayâtının süsünü isteyerek onlardan başka yana sapmasın. Kalbini bizi anmaktan alıkoyduğumuz keyfine uyan ve işi, hep aşırılık olan kişiye itâat etme."},{"n":29,"t":"De ki: \"Bu gerçek, Rabbinizdendir. Artık dileyen inansın, dileyen inkâr etsin.\" Çünkü biz zâlimlere öyle bir ateş hazırladık ki, çadırı onları kuşatmıştır. Eğer (susuzluktan) feryâd edip yardım isteseler erimiş mâden gibi yüzleri haşlayan bir su ile kendilerine yardım edilir! O ne kötü bir içecektir ve ne kötü bir dayanacak(koltuk)dur!"},{"n":30,"t":"Onlar ki inandılar ve iyi işler yaptılar; elbette biz işi güzel yapanın ecrini zâyi etmeyiz."},{"n":31,"t":"Onlar öyle kimselerdir ki kendileri için Adn cennetleri vardır. Altlarından ırmaklar akar. Orada altın bileziklerle bezenirler; ince ipekten yeşil giysiler giyerek koltuklar üzerine yaslanırlar. Ne güzel sevâp ve ne güzel dayanacak (koltuk)!"},{"n":32,"t":"Onlara şu iki adamı misâl olarak anlat: İkisinden birine iki üzüm bağı vermiş, onların etrâfını hurmalarla çevirmiş, ortalarında da ekin bitirmiştik."},{"n":33,"t":"Her iki bağ da yemişini vermiş, ondan hiçbir şey eksik etmemişti. Aralarından bir de ırmak akıtmıştık."},{"n":34,"t":"O(adam)ın (başka) ürünü de vardı. Arkadaşiyle konuşurken ona; \"Ben malca senden zenginim, adamca da senden güçlüyüm.\" dedi."},{"n":35,"t":"(Böylece) kendisine yazık ederek bağına girdi: \"Bunun yok olacağını hiç sanmam\" dedi."},{"n":36,"t":"\"Kıyâmetin kopacağını da sanmıyorum. Şâyet Rabbime döndürülsem bile (orada) bundan daha güzel bir sonuç (daha güzel bir yer) bulurum.\""},{"n":37,"t":"Kendisiyle konuşan arkadaşı ona dedi ki: \"Seni topraktan, sonra nutfe (sperm)den yaratan, sonra da seni bir adam biçimine koyan Rabbine nankörlük mü ettin?\""},{"n":38,"t":"\"Fakat O Allâh benim Rabbimdir, ben Rabbime hiç kimseyi ortak koşmam!\""},{"n":39,"t":"\"Bağına girdiğin zaman: Mâşâallah (Allâh dilemiş de olmuş), kuvvet yalnız Allâh iledir! demen gerekmez miydi? Gerçi sen beni malca ve evlâtça senden az görüyorsun ama\""},{"n":40,"t":"\"Rabbim bana, senin bağından daha iyisini verebilir. Ve o(senin bağı)nın üzerine de gökten bir hesap görme âfeti gönderir de bağın kupkuru bir toprak kesilir.\""},{"n":41,"t":"\"Yahut suyu dibe çekilir de bir daha su arayamazsın.\""},{"n":42,"t":"Derken (o inkârcı kişinin) ürünü yok edildi, çardakları üzerine yıkılmış durumda olan(bağ)ın karşısında ona harcadıklarına acıyarak ellerini uğuşturmağa başladı: \"Âh nolaydı, ben Rabbime kimseyi ortak koşmamış olaydım!\" diyordu."},{"n":43,"t":"Allah’tan başka, kendisine yardım eden bir topluluğu da olmadı, kendi kendisini de kurtaramadı."},{"n":44,"t":"İşte o durumda velilik (koruyuculuk) yalnız hak olan Allah’a mahsustur. O’nun vereceği sevâp da daha hayırlıdır, sonuç da daha hayırlıdır."},{"n":45,"t":"Onlara dünyâ hayâtının, tıpkı şöyle olduğunu anlat: Gökten bir su indirdik, Yerin bitkisi onunla karıştı ve (sonunda bitkiler), rüzgârların savurduğu çöp kırıntıları haline geliverdi. Allâh, her şeye kâdirdir."},{"n":46,"t":"Mal ve oğullar dünyâ hayâtının süsüdür. Kalıcı olan güzel işler ise Rabbinin katında sevâpça da daha hayırlıdır, umutça da daha hayırlıdır."},{"n":47,"t":"(Yalnız kalıcı eylemlerin yarar sağlayacağı) O gün dağları yürütürüz; yeri alaçık (çırılçıplak) görürsün (dağlar savrulup dümdüz olmuş, engebeler kalkmıştır) onları (hep bir yere) toplamışız, hiçbirini bırakmamışızdır."},{"n":48,"t":"Ve hepsi sıra sıra senin Rabbine sunulmuşlardır: \"Andolsun, sizi ilk defa yarattığımız gibi (çırılçıplak, yalnız, malsız, mülksüz) bize geldiniz! Oysa siz, size (yaptıklarınızdan hesap sorulacak) bir zaman tayin etmeyeceğimizi sanmıştınız!\""},{"n":49,"t":"Kitap (ortaya) konulmuştur. Suçluların onun içindekilerden korkarak: \"Vah bize, bu Kitaba da ne oluyor, ne küçük ne de büyük hiçbir şey bırakmıyor, her (yaptığımız) şeyi sayıp döküyor!\" dediklerini görürsün. Yaptıklarını hazır bulmuşlardır. Rabbin kimseye zulmetmez."},{"n":50,"t":"Meleklere: \"Âdem’e secde edin!\" demiştik; secde ettiler, yalnız İblis etmedi. O cinlerdendi, Rabbinin buyruğu dışına çıktı. Şimdi siz, benden ayrı olarak onu ve onun neslini dostlar mı ediniyorsunuz? Oysa onlar, sizin düşmanınızdır. Zâlimler için ne kötü bir değiştirmedir (bu. Dost olan Allâh’ı bırakıp düşman olan şeytânı ve zürriyetini dost tutmak)!"},{"n":51,"t":"Ben onları ne göklerin, yerin, yaratılmasında ve ne de kendilerinin yaratılmasında hazır bulundurdum; yoldan şaşırtanları (kendime) yardımcı tutmuş da değilim."},{"n":52,"t":"O gün (Allâh, kâfirlere) der ki: \"Benim ortaklarım zannettiğiniz şeyleri çağırın (da sizi azâbımdan kurtarsınlar)! İşte çağırdılar ama (çağırdıkları), kendilerine cevap vermediler. Ve biz onların aralarına tehlikeli bir uçurum koyduk."},{"n":53,"t":"Suçlular ateşi gördüler, artık içine düşeceklerini iyice anladılar, fakat ondan kaçacak bir yer bulamadılar."},{"n":54,"t":"Andolsun biz bu Kur’an’da insanlara her çeşit misali türlü biçimlerde anlattık. Ama insan, tartışmaya her şeyden daha çok düşkündür."},{"n":55,"t":"Kendilerine hidâyet geldiği zaman insanları inanmaktan ve Rablerine istiğfar etmekten alıkoyan şey, ancak evvelkilerin yasasının kendilerine de gelmesi(ni) yahut azâbın açıkça karşılarına gelmesi(ni beklemeleri)dir."},{"n":56,"t":"Biz elçileri sadece müjdeleyiciler ve uyarıcılar olarak göndeririz. İnkâr edenler, hakkı bâtılla gidermek için mücâdele ediyorlar. (Onlar), âyetlerimle ve uyarıldıkları şeylerle alay ettiler."},{"n":57,"t":"Kendisine Rabbinin âyetleri hatırlatıldığı halde onlardan yüz çeviren ve ellerinin (yapıp) öne sürdüğü(günâhlarını, isyânları)nı unutandan daha zâlim kim olabilir? Biz onların kalbleri üzerine, onu anlamalarına engel olan örtüler, kulaklarının içine de ağırlık koymuşuz. Onları doğru yola çağırsan da bu halde asla doğru yola gelmezler (çünkü gerçeğe basiretlerini kapamışlardır)."},{"n":58,"t":"Ama çok bağışlayan, esirgeyen Rabbin eğer onları, yaptıklariyle hemen cezâlandıracak olsaydı, onların azâbını çabuklaştırırdı. Fakat onlar için va’dedilen bir zaman vardır ki, ondan (kaçıp) sığınacak bir yer bulamayacaklardır."},{"n":59,"t":"İşte şu kentler de zulmetmeğe başlayınca onları helâk ettik. Onları helâk etmek için de bir süre belirlemiştik."},{"n":60,"t":"Mûsâ uşağına demişti ki: \"Durmayıp ya iki denizin birleştiği yere varacağım veya uzun bir zaman yürüyeceğim.\""},{"n":61,"t":"İkisi (yürüdüler), iki denizin birleştiği yere varınca, balıklarını unuttular, (balık) sıyrılıp denizde yolunu tuttu."},{"n":62,"t":"Orayı geçip gittiklerinde (Mûsâ) uşağına: \"Kahvaltımızı bize getir (de yiyelim), andolsun ki, bu yolculuğumuzdan (epey) yorgunluk çektik.\" dedi."},{"n":63,"t":"(Uşağı): \"Gördün mü, dedi, kayaya sığındığımız vakit balığı unuttum. Onu söylememi, bana ancak şeytân unutturdu. (Balık), şaşılacak biçimde denizin içinde yolunu tuttu!"},{"n":64,"t":"(Mûsâ): \"İşte aradığımız o idi.\" dedi. Tekrar izlerini ta’kibederek geriye döndüler, (kayaya vardılar)."},{"n":65,"t":"(Orada) Kullarımızdan bir kul buldular ki, biz ona katımızdan bir rahmet vermiştik ve ona katımızdan bir ilim öğretmiştik."},{"n":66,"t":"Mûsâ ona: \"Sana öğretilenden, bana da bir bilgi öğretmen için sana tâbi olabilir miyim?\" dedi."},{"n":67,"t":"(O da): \"Sen benimle beraber bulunmağa dayanamazsın\" dedi."},{"n":68,"t":"\"Sana bildirilmeyen bir şeye nasıl dayanabilirsin?\""},{"n":69,"t":"(Mûsâ): \"İnşâallah, dedi, beni sabredici bulursun, senin emrine karşı gelmem.\""},{"n":70,"t":"(O kul): \"O halde, dedi, eğer bana tabi olursan ben sana anlatıncaya kadar (yaptığım) hiçbir şey hakkında bana soru sorma.\""},{"n":71,"t":"Bunun üzerine yürüdüler. Nihâyet gemiye bindikleri zaman gemiyi deliverdi. (Mûsâ): \"Halkını boğmak için mi gemiyi deldin? Gerçekten sen çok tehlikeli bir iş yaptın!\" dedi."},{"n":72,"t":"(O kul): \"Sen benimle beraber bulunmağa dayanamazsın demedim mi?\" dedi."},{"n":73,"t":"(Mûsâ): \"Unuttuğum şeyden ötürü beni kınama ve bana bu işimden dolayı bir güçlük çıkarma.\" dedi."},{"n":74,"t":"Yine yürüdüler. Nihâyet bir oğlana rastladılar. (O kul) hemen onu öldürdü. (Mûsâ): \"Bir can karşılığı olmadan temiz bir cana kıydın ha? Doğrusu sen, çirkin bir iş yaptın!\" dedi."},{"n":75,"t":"(O kul): \"Ben sana, sen benimle beraber bulunmağa dayanamazsın, dememiş miydim? dedi."},{"n":76,"t":"(Mûsâ) dedi ki: \"Eğer bundan sonra (bir daha) sana bir şey sorarsam, artık bana arkadaş olma. (O zaman) benim tarafımdan sana özür ulaşmıştır (artık benden ayrılmakta mazur sayılırsın)."},{"n":77,"t":"Yine yürüdüler. Nihâyet bir kent halkına varıp onlardan yemek istediler (kent halkı) onları konuklamaktan kaçındılar. Derken orada yıkılmağa yüz tutan bir duvar buldular; hemen onu doğrulttu. (Mûsâ): \"İsteseydin buna karşılık bir ücret alırdın,\" dedi."},{"n":78,"t":"\"İşte, dedi bu, benimle senin aramızın ayrılmasıdır. Şimdi sana sabredemeğin şeylerin içyüzünü haber vereceğim.\""},{"n":79,"t":"\"O (yaraladığım) gemi, denizde çalışan yoksullarındı. Onu kusurlu yapmak istedim, çünkü onların ilerisinde her (sağlam) gemiyi zorla alan bir kral vardı.\""},{"n":80,"t":"\"Oğlana gelince: Onun anası babası mü’min insanlardı. Bunun, onlara azgınlık ve küfür sarmasından korktuk.\""},{"n":81,"t":"\"İstedik ki Rableri onun yerine onlara ondan daha temiz, daha merhametli (ana babasına iyilik eden) birini versin.\""},{"n":82,"t":"\"Duvar ise şehirde iki yetim çocuğun idi. Altında onlara ait bir hazine vardı. Babaları da iyi bir kimse idi. Rabbin istedi ki onlar (büyüyüp) güçlü çağlarına ersinler ve Rabbinden bir rahmet olarak hazinelerini çıkarsınlar. Bunları, ben kendiliğimden yapmadım. İşte senin sabredemediğin şeylerin içyüzü budur.\""},{"n":83,"t":"(Ey Muhammed), sana Zu’l-Karneyn’den soruyorlar. De ki: \"Size ondan bir anı okuyacağım.\""},{"n":84,"t":"Biz onu yeryüzünde güçlü kıldık ve ona herşeyden bir sebep (istediği herşeye ulaşmanın yolunu, aracını) verdik."},{"n":85,"t":"O da (kendisini batı ülkelerine ulaştıracak) bir yol tuttu."},{"n":86,"t":"Nihâyet güneşin battığı yere ulaşınca onu, kara balçıklı bir gözede batar buldu. Onun yanında da bir kavim buldu. Dedik ki: \"Ey Zu’l-Karneyn, (onlara) ya azâb edersin veya kendilerine güzel davranırsın (onları güzellikle yola getirirsin. Nasıl istersen öyle yaparsın).\""},{"n":87,"t":"Dedi: \"Kim haksızlık ederse, ona azâb edeceğiz, sonra o, Rabbine döndürülecektir. O da ona görülmemiş bir azâb edecektir.\""},{"n":88,"t":"\"Fakat inanıp iyi iş yapan kimseye de en güzel mükâfât vardır. Ona buyruğumuzdan kolay olanı söyleyeceğiz (onu zor işlere koşmayacağız).\""},{"n":89,"t":"Sonra yine bir yol tuttu."},{"n":90,"t":"Nihâyet güneşin doğduğu yere ulaşınca onu, güneşe karşı kendilerine siper yapmadığımız bir kavim üzerine doğar buldu."},{"n":91,"t":"İşte (Zu’l-Karneyn) böyle (yüksek bir mevkie ve hükümranlığa sâhip) idi. Onun yanında (daha) nice bilgi ve yetki bulunduğunu biliyorduk."},{"n":92,"t":"Sonra yine bir yol tuttu."},{"n":93,"t":"Nihâyet iki sed arasına ulaşınca onların önünde hemen hiç söz anlamayan bir kavim buldu."},{"n":94,"t":"Dediler ki: \"Ey Zu’l-Karneyn, Ye’cûc ve Me’cûc, bu yerde bozgunculuk yapıyorlar. Bizimle onların arasına bir sed yapman için sana bir vergi verelim mi?\""},{"n":95,"t":"Dedi ki: \"Rabbimin, beni içinde bulundurduğu imkânlar, (sizin vereceğinizden) daha hayırlıdır. Siz bana (insan) güc(üy)le yardım edin de sizinle onlar arasına sağlam bir engel yapayım.\""},{"n":96,"t":"\"Bana demir kütleleri getirin.\" (Zu’l-Karneyn) iki dağın arasını (demir kütleleriyle doldurtup dağlarla) aynı seviyeye getirince: \"Üfleyin!\" dedi. Nihâyet o(demir kütleleri)ni bir ateş haline sokunca \"Getirin bana, üzerine erimiş katran dökeyim,\" dedi."},{"n":97,"t":"Artık (Ye’cûc Me’cûc) onu ne aşabildiler, ne de delebildiler."},{"n":98,"t":"(Zu’l-Karneyn) dedi: \"Bu, Rabbimin bir rahmetidir. Rabbimin va’di gel(ip Ye’cûc ve Me’cûc’un çıkması, yahut kıyâmetin kopması gerek)diği zaman onu yerle bir eder; şüphesiz Rabbimin va’di gerçektir.\""},{"n":99,"t":"Biz o gün (Ye’cûc ve Me’cûc’u) bırakmışızdır: Birbiri içinde dalgalanır(lar). Sûr’a da üflenmiştir ve onları hep bir araya toplamışızdır."},{"n":100,"t":"O gün cehennemi kâfirlere açıkça göstereceğiz."},{"n":101,"t":"Onlar ki beni anmağa karşı gözleri perde içinde idi ve (Kur’ân’ı) dinlemeğe tahammül edemezlerdi."},{"n":102,"t":"O nankörler benden ayrı olarak kullarımı kendilerine veliler yapacaklarını mı sandılar? Biz kâfirlere cehennemi konak olarak hazırladık."},{"n":103,"t":"De ki: \"Size işleri bakımından en çok ziyana uğrayacak olanları söyleyeyim mi?\""},{"n":104,"t":"Dünyâ hayâtında bütün çabaları boşa gitmiş olan ve kendileri de iyi iş yaptıklarını sanan kimseleri?"},{"n":105,"t":"İşte onlar, Rablerinin âyetlerini ve O’na kavuşmayı inkâr eden, bu yüzden eylemleri boşa çıkan kimselerdir. (Yaptıkları işler tamamen boşa çıktığından) kıyâmet günü onlar için bir terazi kurmayız (veya onlara hiçbir değer vermeyiz)."},{"n":106,"t":"İnkâr ettikleri, âyetlerimi ve elçilerimi eğlence yerine koydukları için onların cezâsı cehennemdir."},{"n":107,"t":"İnanıp iyi işler yapanlara gelince, onların konağı da Firdevs cennetleridir."},{"n":108,"t":"Orada sürekli kalacaklardır. Oradan hiç ayrılmak istemezler."},{"n":109,"t":"De ki: \"Rabbimin sözleri(ni yazmak) için deniz mürekkep olsa, Rabbimin sözleri tükenmeden önce deniz tükenir.\" Yardım için bir o kadarını daha getirsek (yine yetmez).\""},{"n":110,"t":"De ki: \"Ben de sizin gibi bir insanım; Tanrınızın bir tek Tanrı olduğu bana vahyolunuyor. Kim Rabbine kavuşmayı arzu ediyorsa iyi iş yapsın ve Rabbine (yaptığı) ibâdete hiç kimseyi ortak etmesin.\""}],[{"n":1,"t":"Kâf hâ yâ ’ayn sâd."},{"n":2,"t":"Bu, Rabbinin, kulu Zekeriyyâ’ya rahmetini anıştır."},{"n":3,"t":"O, Rabbine gizli bir seslenişle yalvarmıştı:"},{"n":4,"t":"\"Rabbim, demişti, ben, bende kemik gevşedi; baş, ihtiyarlk aleviyle tutuştu. Rabbim, sana du’â ile hiçbir zaman bahtsız olmadım (her du’â ettikçe kabul buyurdun, beni istediğimden mahrum etmedin).\""},{"n":5,"t":"\"Doğrusu ben arkamdan, yerime geçecek yakınlar(ımın iyi hareket etmeyecekler)inden korktum; karım da kısır. (Ne olur) katından bana yerime geçecek bir veli lutfet."},{"n":6,"t":"\"Ki, (o), bana ve Ya’kûb oğullarına mirâsçı olsun. Rabbim, onu beğendiğin bir insan yap.\""},{"n":7,"t":"(Allâh buyurdu): Ey Zekeriyyâ, biz sana bir oğul müjdeleriz, adı Yahyâ’dır. Daha önce ona hiç kimseyi adaş yapmadık (ondan önce kimseye bu adı vermedik.)\""},{"n":8,"t":"(Zekeriyyâ): \"Rabbim, dedi benim nasıl oğlum olur? Karım da kısırdır. Ben ise ihtiyarlığın son sınırına vardım.\""},{"n":9,"t":"Dedi: \"Öyledir, ama Rabbin: ’O bana kolaydır, daha önce sen de hiçbir şey değilken seni de yaratmıştım’ dedi.\""},{"n":10,"t":"\"Rabbim, dedi, (öyle ise) bana bir işâret ver\". \"Senin işâretin, sapasağlam olduğun halde tam üç gece (ve gündüz) insanlarla konuşamamandır.\" dedi."},{"n":11,"t":"(Zekeriyyâ), ma’bedden kavminin karşısına çıkıp onlara: \"Sabah akşam (Rabbinizi) tesbih edin!\" diye işâret etti."},{"n":12,"t":"\"Ey Yahyâ, Kitabı kuvvetle tut (Onun emirlerini uygula).\" (dedik) ve ona çocuk iken hikmet verdik."},{"n":13,"t":"Katımızdan bir rahmet (bir acıma duygusu) ve temizlik de (verdik; o günâhlardan) korunan oldu."},{"n":14,"t":"Ana babasına iyilik ediciydi, baş kaldıran bir zorba değildi."},{"n":15,"t":"Doğduğu gün, öleceği gün ve diri olarak kaldırılacağı gün ona selâm olsun!"},{"n":16,"t":"Kitapta Meryem’i de an. Bir zaman o âilesinden ayrılıp doğu yönünde bir yere çekilmişti."},{"n":17,"t":"Onlarla kendisi arasına bir perde çekmişti. Biz de ruhumuzu (Cebrâil’i) ona gönderdik. (O) ona düzgün bir insan şeklinde göründü."},{"n":18,"t":"(Meryem) dedi ki: \"Ben senden, çok esirgeyen (Allâh)’a sığınırım. Eğer (Allah’tan) korkuyorsan (bana dokunma).\""},{"n":19,"t":"(Ruh): \"Ben, dedi, sadece Rabbinin elçisiyim. Sana tertemiz bir erkek çocuğu hediye edeyim diye (geldim).\""},{"n":20,"t":"\"Benim nasıl oğlum olur, dedi, bana bir insan dokunmadı ve ben bir kahpe de değilim.\""},{"n":21,"t":"(Ruh): \"Öyledir, dedi, Rabbin: ’O bana kolaydır. Onu insanlara bir mu’cize ve bizden bir rahmet kılmak için (bunu yapacağız)’ dedi\" ve iş olup bitti."},{"n":22,"t":"(Meryem), ona gebe kaldı. Onunla uzak bir yere çekildi."},{"n":23,"t":"Doğum sancısı onu, bir hurma dalı(nın altı)na getirdi. \"Keşke dedi, bundan önce ölseydim, unutulup gitseydim!\""},{"n":24,"t":"Altından (Ruh) ona şöyle seslendi: \"Üzülme Rabbin alt tarafında bir su arkı var etti.\""},{"n":25,"t":"\"Hurma dalını sana doğru silkele, üzerine olmuş, taze hurma dökülsün.\""},{"n":26,"t":"\"Ye, iç, gözün aydın olsun! Eğer insanlardan birini görürsen: \"Ben Rahmân için (susma) oruc(u) adadım, bugün hiçbir insanla konuşmayacağım\" de.\""},{"n":27,"t":"(Meryem) onu taşıyarak kavmine getirdi: \"Ey Meryem, dediler, sen tuhaf bir iş yaptın.\""},{"n":28,"t":"\"Ey Hârûn’un kızkardeşi, baban kötü bir adam değildi, annen de fâhişe değildi (sen ne yaptın böyle)?\""},{"n":29,"t":"(Meryem), çocuğu gösterdi. Dediler ki: \"Beşikteki çocukla nasıl konuşuruz?\""},{"n":30,"t":"(Çocuk): \"Ben Allâh’ın kuluyum, dedi,(O) bana Kitabı verdi, beni peygamber yaptı.\""},{"n":31,"t":"\"Beni bulunduğum her yerde yararlı kıldı. Sağ olduğum sürece bana namaz kılmayı, zekât vermeyi emretti!\""},{"n":32,"t":"\"(Beni) anneme iyilik eder (kıldı), beni baş kaldıran bir zorba yapmadı.\""},{"n":33,"t":"\"Doğduğum gün de, öleceğim gün de ve diri olarak kaldırılacağım gün de bana esenlik verilmiştir."},{"n":34,"t":"İşte Meryem oğlu Îsâ. Şüphe edip ayrılığa düştükleri şey, \"gerçek söz\"e göre budur."},{"n":35,"t":"Çocuk edinmek, Allah’a yakışmaz. O’nun şânı yücedir. Bir işi yapmak istedi mi ona sadece \"ol\" der, (o da) olur."},{"n":36,"t":"\"Şüphesiz, Allâh benim de Rabbim, sizin de Rabbinizdir, O’na kulluk edin.\" İşte doğru yol budur."},{"n":37,"t":"Kendi aralarından hizipler, ayrılığa düştüler. Artık büyük bir günü görmekten ötürü vay kâfirlerin haline!"},{"n":38,"t":"Bize geldikleri gün ne güzel işitir, ne güzel görürler. Ama o zâlimler, bugün apaçık sapıklık içindedirler!"},{"n":39,"t":"Onları şu hasret gününe karşı uyar ki, o zaman kendileri gaflet içinde inanmamakta ısrar ederlerken iş bitirilmiş olur (yaptıklarına pişman olup hasret çeker dururlar, ama iş işten geçmiştir artık)."},{"n":40,"t":"Dünyâya ve üzerinde bulunanlara biz vâris oluruz biz, ve bize döndürülürler."},{"n":41,"t":"Kitapta İbrâhim’i de an; gerçekten o, çok doğru bir peygamberdi."},{"n":42,"t":"Babasına demişti ki: \"Babacığım, işitmeyen görmeyen ve sana hiçbir yararı olmayan şeylere niçin tapıyorsun?\""},{"n":43,"t":"\"Babacığım, bana, sana gelmeyen bir bilgi geldi; bana uy, seni düzgün bir yola ileteyim.\""},{"n":44,"t":"\"Babacığım, şeytâna tapma, çünkü şeytân, Rahmân’a isyân etmiştir.\""},{"n":45,"t":"\"Babacığım, ben sana Rahmân’dan bir azâbın dokunmasından korkuyorum. O zaman, şeytânın dostu olursun.\""},{"n":46,"t":"(Babası): \"Ey İbrâhim, dedi, sen benim tanrılarımdan yüz mü çeviriyorsun? Eğer (onlara dil uzatmaktan) vazgeçmezsen, andolsun seni taşlarım. Uzun süre benden ayrıl, git!\""},{"n":47,"t":"(İbrâhim): \"Selâm sana, (esenlik içinde kal), dedi, senin için Rabbimden mağfiret dileyeceğim. Çünkü O, bana çok lutufkârdır.\""},{"n":48,"t":"\"Sizden de, Allah’tan başka yalvardıklarınızdan da ayrılıyor ve yalnız Rabbime yalvarıyorum. Umarım ki Rabbime yalvarmakla bahtsız olmam (istediklerimden mahrum bırakılmam).\""},{"n":49,"t":"İşte onlardan ve onların Allah’tan başka taptıklarından ayrılınca biz ona İshak’ı ve (İshak’ın oğlu) Ya’kûb’u armağan ettik ve hepsini de peygamber yaptık."},{"n":50,"t":"Onlara rahmetimizden (mal ve çocuk) lutfettik ve onlar için yüce bir doğruluk dili verdik."},{"n":51,"t":"Kitapta Mûsâ’yı da an, çünkü o, içi temiz (bir insan)dı ve elçi bir peygamberdi."},{"n":52,"t":"Ona Tûr’un sağ tarafından seslendik ve onu, özel konuşmak için (kendimize) yaklaştırdık."},{"n":53,"t":"Ona, acıdığımızdan dolayı kardeşi Hârûn’u da peygamber olarak armağan ettik."},{"n":54,"t":"Kitapta İsmâ’il’i de an. Çünkü o sözünde duran, elçi bir peygamberdi."},{"n":55,"t":"Halkına namaz kılmayı, zekât vermeyi emrederdi. Rabbi yanında beğenilmişti."},{"n":56,"t":"Kitapta İdris’i de an: Çünkü o, çok doğru bir peygamberdi."},{"n":57,"t":"Onu yüce bir yere yükseltmiştik."},{"n":58,"t":"İşte bunlar; Allâh’ın ni’met verdiği peygamberlerden, Âdem neslinden, Nûh ile beraber gemide taşıdıklarımızın neslinden, İbrâhim ve İsrâil (Ya’kûb) neslinden, yol gösterdiğimiz ve seçtiğimiz kimselerdendir. Onlara Rahmân’ın âyetleri okunduğu zaman ağlayarak secdeye kapanırlardı."},{"n":59,"t":"Onlardan sonra yerlerine öyle bir nesil geldi ki, namazı zayi ettiler, şehvetlerine uydular. Onlar kötülük bulacaklardır."},{"n":60,"t":"Ancak tevbe eden, inanan ve iyi işler yapanlar, cennete girecekler ve hiç haksızlığa uğratılmayacaklardır."},{"n":61,"t":"Rahmân’ın kullarına gıyâben va’dettiği Adn cennetleri(ne gireceklerdir). Şüphesiz O’nun va’di yerine gelecektir."},{"n":62,"t":"Orada boş söz değil, yalnız selâm işitirler. Orada sabah akşam rızıkları da hazırdır."},{"n":63,"t":"İşte kullarımızdan, korunanlara vereceğimiz cennet budur."},{"n":64,"t":"Biz ancak Rabbinin emriyle ineriz. Önümüzde, arkamızda ve bunlar arasında olan herşey O’na âittir. Rabbin, asla unutkan değildir."},{"n":65,"t":"(O), göklerin, yerin ve bunlar arasında bulunan şeylerin Rabbidir. O’na kulluk et ve O’na kullukta sabret. Hiç O’nun adıyla anılan birini biliyor musun?"},{"n":66,"t":"İnsan: \"Ben öldükten sonra mı diri olarak çıkarılacağım?\" diyor."},{"n":67,"t":"İnsan önceden hiçbir şey değilken kendisini nasıl yarattığımızı düşünmüyor mu?"},{"n":68,"t":"Rabbine andolsun ki, onları ve şeytânları mutlaka toplayacağız, sonra onları diz çökmüş vaziyette cehennemin çevresinde bulunduracağız."},{"n":69,"t":"Sonra her milletten Rahmân’a en çok karşı geleni ayıracağız."},{"n":70,"t":"Sonra, elbette biz, kimlerin oraya girmeğe uygun olduğunu daha iyi biliriz."},{"n":71,"t":"İçinizden oraya gitmeyecek hiç kimse yoktur. Bu, Rabbinin üzerine aldığı kesin borçtur."},{"n":72,"t":"Sonra korunanları kurtarırız ve zâlimleri öyle diz üstü çökmüş olarak bırakırız."},{"n":73,"t":"Onlara açık açık âyetlerimiz okunduğu zaman, inkâr edenler, inananlar için \"İki topluluktan hangisinin makamı daha hayırlı, meclisi (mevkii) daha güzeldir?\" derler."},{"n":74,"t":"Onlardan önce nice nesiller helâk ettik ki onlar eşyaca ve gösterişce daha güzeldi."},{"n":75,"t":"De ki: \"Kim sapıklık içinde ise Rahmân ona süre versin (ne çıkar). Nihâyet va’dedildiklerini -azâbı veya (Duruşma) sâ’ati(ni)- gördükleri zaman, kimin yerce daha kötü ve adamca daha zayıf olduğunu bileceklerdir."},{"n":76,"t":"Allâh, yola gelenlerin hidâyetini artırır. Kalıcı olan yararlı işler, Rabbinin yanında hem mükâfât bakımından daha iyidir, hem varılacak yer bakımından daha iyidir!"},{"n":77,"t":"Âyetlerimizi inkâr edip: \"Bana mal ve evlâd verilecek\" diyen adamı gördün mü?"},{"n":78,"t":"Gaybe mi çık(ıp bak)tı, yoksa Rahmân’ın huzûrunda bir söz mü aldı (Allâh ile bir andlaşma mı yaptı)?"},{"n":79,"t":"Hayır (yanılıyor), biz onun dediğini yazacağız ve onun için azâbı uzattıkça uzatacağız."},{"n":80,"t":"O dediği(malı ve evlâdı)na biz vâris olacağız (nesi varsa hepsi bize kalacak) ve o, bize tek başına gelecek (yanında ne malı, ne de evlâdı olmayacak)."},{"n":81,"t":"Kendilerine destek olsunlar diye Allah’tan başka tanrılar edindiler."},{"n":82,"t":"Hayır, (yarın o taptıkları tanrılar), bunların tapmalarını inkâr edecekler ve bunlara zıd olacaklardır."},{"n":83,"t":"Görmedin mi biz kâfirlere şeytânları gönderdik, onları oynatıp duruyorlar."},{"n":84,"t":"Onlar hakkında acele etme, biz onlar(ın günlerini ve nefeslerini doldurmaları) için saydıkça sayıyoruz."},{"n":85,"t":"Korunanları, binek üzerinde ikram ile Rahmân’a götürdüğümüz gün,"},{"n":86,"t":"Suçluları da yaya ve susuz olarak cehenneme sürdüğümüz (gün),"},{"n":87,"t":"Yalnız Rahmân’ın huzûrunda söz almış olanlardan başkaları şefâ’at edemezler."},{"n":88,"t":"\"Rahmân çocuk edindi\" dediler."},{"n":89,"t":"Andolsun ki, \"Siz pek kötü bir cür’ette bulundunuz!\""},{"n":90,"t":"Neredeyse o(sözün dehşeti)nden gökler çatlayacak, yer yarılacak ve dağlar yıkılıp dağılacaktır!."},{"n":91,"t":"Rahmân için çocuk iddiâ ettiklerinden ötürü."},{"n":92,"t":"Çocuk edinmek Rahmân’a yakışmaz."},{"n":93,"t":"Göklerde ve yerde bulunan herkes Rahmân’a kul olarak gelecektir."},{"n":94,"t":"O, onların hepsini kuşatmış ve onları bir bir saymıştır."},{"n":95,"t":"Onların hepsi, kıyâmet günü O’na tek başına gelecektir."},{"n":96,"t":"İnanıp faydalı işler yapanlar için Rahmân, (gönüllerde) bir sevgi yaratacak(onları herkese sevdirecek)tir."},{"n":97,"t":"Biz o(Kur’â)n’ı senin diline kolaylaştırdık ki, onunla korunanları müjdeleyesin ve inatçı bir kavmi onunla uyarasın."},{"n":98,"t":"Biz onlardan önce nice nesilleri helâk ettik. Şimdi onlardan hiçbirini duyuyor musun, yahut onların gizli bir sesini işitiyor musun?"}],[{"n":1,"t":"Tâ, Hâ."},{"n":2,"t":"Biz bu Kur’ân’ı sana güçlük çekesin diye indirmedik."},{"n":3,"t":"Ancak (Allah’tan) korkanlara bir öğüt (olarak indirdik)."},{"n":4,"t":"(O) yeri ve yüce gökleri yaratan tarafından azar azar indirilmiştir."},{"n":5,"t":"Rahmân Arş’a istivâ etmiş(kurulmuş)tur."},{"n":6,"t":"Göklerde, yerde, ikisinin arasında ve toprağın altında bulunanlar hep O’nundur (ne kadar kapalı olursa olsun, O’ndan hiçbir şey gizli kalmaz)."},{"n":7,"t":"Sözü açık söylesen de (gizli söylesen de) muhakkak O, gizliyi de ondan daha gizlisini de bilir."},{"n":8,"t":"Allâh ki, O’ndan başka tanrı yoktur. En güzel isimler O’nundur."},{"n":9,"t":"Mûsâ’nın haberi sana geldi mi?"},{"n":10,"t":"Hani (o) bir ateş görmüştü de âilesine: \"Siz durun ben bir ateş gördüm, belki ondan size bir kor getiririm, yahut ateşin yanında bir yol gösteren bulurum\" demişti."},{"n":11,"t":"(Mûsâ), o(ateşin yanı)na gelince kendisine \"Ey Mûsâ!\" diye seslenildi."},{"n":12,"t":"\"Ben, (evet) ben senin Rabbinim! Pabuçlarını çıkar. Çünkü sen, kutsal vâdide, Tuvâ’dasın.\""},{"n":13,"t":"\"Ben seni seçtim, şimdi vahyolunanı dinle.\""},{"n":14,"t":"\"Muhakkak ben, (evet) ben Allâh’ım, benden başka tanrı yoktur.(Yalnız) bana kulluk et ve beni anmak için namaz kıl.\""},{"n":15,"t":"\"(Kıyâmet) Sâ’at(i) mutlaka gelecektir. Herkesin, peşinde koştuğu işlerle cezâlanması için, neredeyse onu gizleyeceğim.\""},{"n":16,"t":"\"Ona inanmayıp keyfine uyan kimse, seni on(a inanmak)dan alıkoymasın, sonra helâk olursun!\""},{"n":17,"t":"\"Sağ elindeki nedir ey Mûsâ?\""},{"n":18,"t":"(Mûsâ) dedi: \"O, asâ’mdır. Ona dayanıyorum ve onunla davarıma yaprak silkeliyorum ve onda benim daha birçok ihtiyaçlarım var (onunla birçok ihtiyacımı gideririm).\""},{"n":19,"t":"(Allâh) buyurdu; \"(Yere) at onu ey Mûsâ!\""},{"n":20,"t":"(Mûsâ) attı, bir de ne görsün o, koşan kocaman bir yılan!"},{"n":21,"t":"(Allâh): \"Al onu, dedi, korkma biz onu yine ilk durumuna sokacağız.\""},{"n":22,"t":"\"Elini böğrüne sok; bir hastalık olmadan, ayrı bir mu’cize olarak bembeyaz bir durumda çıksın.\""},{"n":23,"t":"\"Ki sana en büyük mu’cizelerimizden bazılarını göstermiş olalım\""},{"n":24,"t":"\"İmdi sen Fir’avn’e git: çünkü o azdı.\""},{"n":25,"t":"(Mûsâ) dedi ki: \"Rabbim, benim göğsümü aç (risalet görevini yüklenebilmesi için yüreğimi genişlet)\""},{"n":26,"t":"\"Bana işimi kolaylaştır.\""},{"n":27,"t":"\"Dilimin düğümünü çöz\"."},{"n":28,"t":"\"Ki sözümü anlasınlar\""},{"n":29,"t":"\"Bana âilemden bir vezir ver:\""},{"n":30,"t":"\"Kardeşim Hârûn’u.\""},{"n":31,"t":"\"Onunla arkamı kuvvetlendir.\""},{"n":32,"t":"\"Onu da işime ortak yap,\""},{"n":33,"t":"\"Ki seni çok tesbih edelim,\""},{"n":34,"t":"\"Ve seni çok analım,\""},{"n":35,"t":"\"Şüphesiz sen, bizi görmektesin.\""},{"n":36,"t":"(Allâh) buyurdu: \"Ey Mûsâ, istediğin sana verildi.\""},{"n":37,"t":"\"Zaten biz sana bir kez daha lutufta bulunmuştuk.\""},{"n":38,"t":"\"(Sen doğduğun zaman,) Annene vahyedileni vahyetmiştik:\""},{"n":39,"t":"\"Onu sandığa koy, suya at; su onu sahile bıraksın; onu benim de düşmanım onun da düşmanı olan biri alacaktır.\" \"Gözümün önünde yetiştirilmen için senin üzerine benden bir sevgi koydum (görenler senin üzerine koyduğum bu sevgiden ötürü sana meftun oldular).\""},{"n":40,"t":"\"Kızkardeşin ona bakacak birini size göstereyim mi? diyordu. Böylece seni annene geri verdik ki gözü aydın olsun, üzülmesin. Sen bir de adam öldürmüştün. O zaman da seni tasadan kurtarmış ve seni iyice denemiştik. Medyen halkı arasında yıllarca kaldın. Sonra belirlediğimiz bir vakitte bize geldin ey Mûsâ!\""},{"n":41,"t":"\"Seni kendim için yetiştirdim.\""},{"n":42,"t":"\"Sen ve kardeşin, âyetlerimi götürün, beni anmakta gevşeklik etmeyin.\""},{"n":43,"t":"\"Fir’avn’e gidin, çünkü o azdı.\""},{"n":44,"t":"\"Ona yumuşak söz söyleyin, belki öğüt alır veya korkar.\""},{"n":45,"t":"Dediler ki: \"Rabbimiz, onun bize taşkınlık etmesinden, yahut iyice azmasından korkuyoruz.\""},{"n":46,"t":"\"Korkmayın, dedi, ben sizinle beraberim, işitir ve görürüm.\""},{"n":47,"t":"\"Haydi, varın ona, deyin ki: Biz senin Rabbinin elçileriyiz; İsrâil oğullarını bizimle gönder, onlara azâb etme. Biz Rabbinden sana bir âyet getirdik. Esenlik, hidâyete uyanlaradır.\""},{"n":48,"t":"\"Bize, yalanlayıp yüz çevirenin, azâba uğrayacağı vahyolundu.\""},{"n":49,"t":"(Fir’avn): \"Rabbiniz kimdir ey Mûsâ?\" dedi."},{"n":50,"t":"(Mûsâ): \"Rabbimiz, her şeye yaratılışını (varlığını ve biçimini) verip sonra onu doğru yola ileten (yaratılış gâyesine uygun yola yönelten)dir.\" dedi."},{"n":51,"t":"(Fir’avn): \"Peki ya ilk nesillerin hali ne olacak?\" dedi."},{"n":52,"t":"Dedi ki: \"Onların bilgisi Rabbimin yanında bir Kitâptadır. Rabbim şaşmaz ve unutmaz.\""},{"n":53,"t":"O ki, yeri size beşik yaptı ve onda sizin için yollar açtı, gökten bir su indirdi. Onunla her çeşit bitkiden çiftler çıkardık."},{"n":54,"t":"Yeyin, hayvanlarınızı otlatın. Şüphesiz bunda, akıl sâhipleri için ibretler vardır."},{"n":55,"t":"Sizi topraktan yarattık, yine oraya döndürürüz ve sizi bir kez daha ondan çıkarırız."},{"n":56,"t":"Andolsun biz o(Fir’av)n’a âyetlerimizin hepsini gösterdik, yine de yalanladı ve dayattı."},{"n":57,"t":"Ve: \"Sen bizi büyünle yurdumuzdan çıkarasın diye mi geldin ey Mûsâ?\" dedi."},{"n":58,"t":"\"Biz de mutlaka sana o(se)nin (büyün) gibi bir büyü getireceğiz. Sen şimdi seninle bizim aramızda bir buluşma zamanı ve yeri tayin et; ne senin, ne de bizim caymayacağımız uygun bir yer olsun.\""},{"n":59,"t":"(Mûsâ): \"Buluşma zamanınız, Süs (bayram) günü ve insanların toplanacağı kuşluk vakti olsun\" dedi."},{"n":60,"t":"Fir’avn, dönüp gitti, hilesini (büyücüleri ve onların âletlerini) topladı, sonra (belirtilen yere) geldi."},{"n":61,"t":"Mûsâ onlara: \"Yazık size, dedi, Allah’a yalan uydurmayın, sonra (O), bir azâb ile kökünüzü keser, doğrusu iftirâ eden perişan olmuştur!\""},{"n":62,"t":"(Fir’avn’ın topladığı büyücüler), işlerini kendi aralarında tartıştılar ve gizli konuştular."},{"n":63,"t":"Dediler ki: \"Bunlar iki büyücü, başka bir şey değil. Büyüleriyle sizi yurdunuzdan çıkarmak ve sizin örnek yolunuzu, (üstün dininizi) gidermek istiyorlar.\""},{"n":64,"t":"Onun için siz hilenizi toplayın, sonra sıra halinde gelin. Bugün üstün gelen başarmıştır."},{"n":65,"t":"(Büyücüler önce Mûsâ’nın işe başlamasını istediler) Dediler ki: \"Ey Mûsâ, ya sen at, yahut önce atan biz olalım.\""},{"n":66,"t":"(Mûsâ): \"Hayır siz atın!\" dedi. (Attılar. Mûsâ) bir de ne görsün: Büyülerinden ötürü onların ipleri ve sopaları gerçekten koşuyor gibi görünüyor."},{"n":67,"t":"Bu yüzden Mûsâ, içinde bir korku duydu."},{"n":68,"t":"(Biz kendisine): \"Korkma, dedik, üstün gelecek sensin, sen!\""},{"n":69,"t":"\"Sağ elindekini at! Onların yaptıklarını yutsun. Çünkü onların yaptıkları, bir büyücünün hilesidir. Büyücü de nereye varsa iflâh olmaz!\""},{"n":70,"t":"Bunun üzerine büyücüler secdeye kapandılar: \"Hârûn’un ve Mûsâ’nın Rabbine inandık!\" dediler."},{"n":71,"t":"(Fir’avn): \"Ben size izin vermeden ona inandınız ha? O, size büyü öğreten büyüğünüzdür. Öyleyse ben de sizin ellerinizi ve ayaklarınızı çapraz keseceğim ve sizi hurma dallarına asacağım, hangimizin azâbı daha çetin ve sürekli imiş bileceksiniz!\" dedi."},{"n":72,"t":"Dediler ki: \"Biz, seni, bize gelen açık delillere ve bizi yaratana tercih edemeyiz. Yapacağını yap, sen ancak bu dünyâ hayâtında istediğini yapabilirsin.\""},{"n":73,"t":"\"Biz Rabbimize inandık ki (O) bizim günâhlarımızı ve senin bizi yapmaya zorladığın büyüyü bağışlasın. (Elbette) Allâh daha hayırlı ve (O’nun mükâfâtı ve cezâsı) daha süreklidir.\""},{"n":74,"t":"Kim Rabbine suçlu olarak gelirse onun için cehennem vardır; orada ne ölür ne de yaşar."},{"n":75,"t":"Kim de iyi işler yapmış bir mü’min olarak O’na gelirse, işte onlar için de yüksek dereceler vardır:"},{"n":76,"t":"Altlarından ırmaklar akan Adn cennetleri. Orada sürekli olarak kalırlar. İşte arınanların mükâfâtı budur!"},{"n":77,"t":"Andolsun biz Mûsâ’ya: \"Kullarımı geceleyin (Mısır’dan çıkarıp) yürüt; (asânla suya) vur, denizde onlar için kuru bir yol (aç). (Fir’avn’ın sana) yetişme(sin)den korkma, (boğulmaktan) endişe etme.\" diye vahyetmiştik."},{"n":78,"t":"Fir’avn, askerleriyle onların ardına düştü, denizden onları örten örttü (deniz onları örtüp boğdu)."},{"n":79,"t":"Fir’avn toplumunu saptırdı, doğru yola iletmedi."},{"n":80,"t":"Ey İsrâil oğulları, biz sizi düşmanınızdan kurtardık ve Tûr’un sağ yanında, (Mûsâ ile konuşmayı) size va’dettik; üzerinize kudret helvasıyle bıldırcın indirdik."},{"n":81,"t":"\"Size verdiğimiz rızkın temizlerinden yeyin, ama bu hususta taşkınlık etmeyin; sonra gazabım üzerinize iner, kimin üstüne gazabım inerse o, düşmüş(mahvolmuş)tur."},{"n":82,"t":"\"Ve Ben, tevbe eden, inanan ve yararlı iş yapan, sonra da yola gelen kimseye karşı çok bağışlayıcıyımdır.\""},{"n":83,"t":"\"Seni kavminden çabucak ayrıl(ıp gel)meğe sevk eden nedir? (Niçin onları hemen bırakıp geldin) ey Mûsâ?\" (dedik)."},{"n":84,"t":"Dedi: \"Onlar benim arkamdan geliyorlar, ya Rabbi râzı olman için sana çabuk geldim.\""},{"n":85,"t":"(Allâh): \"Ama biz senden sonra kavmini sınadık. Samiri onları saptırdı\" dedi."},{"n":86,"t":"Bunun üzerine Mûsâ, çok kızgın ve üzüntülü bir halde kavmine döndü: \"Ey Kavmim, dedi, Rabbiniz size güzel bir va’idde bulunmamış mıydı? Süre mi size uzun geldi (zamanla verdiğiniz sözü unuttunuz mu)? Yoksa Rabbinizden bir gazabın üstünüze inmesini mi istediniz ki, bana verdiğiniz sözden caydınız (beni izlemediniz)?\""},{"n":87,"t":"Dediler ki: \"Kendi malımızla senin sözünden çıkmadık\", fakat o milletin (yani Mısırlıların) süs(eşyas)ından bize yükler yükletilmişti. Onları (ateşe) attık. Aynı şekilde Samiri de attı.\""},{"n":88,"t":"Onlara, böğürmesi olan bir buzağı heykeli ortaya çıkardı. Dediler ki, \"Bu sizin de tanrınız, Mûsâ’nın da tanrısıdır, fakat o unuttu\"."},{"n":89,"t":"Onlar görmüyorlar mı ki o (buzağı) kendilerine bir söz söyleyemez; bir zarar, ve yarar veremez?"},{"n":90,"t":"Önceden Hârûn, kendilerine: \"Ey kavmim, andolsun siz bununla sınandınız. Rabbiniz, o çok esirgeyendir. Bana uyun, buyruğuma itâ’at edin!\" demişti."},{"n":91,"t":"Dediler: \"Mûsâ bize dönünceye kadar buna tapmaktan vazgeçmeyeceğiz!\""},{"n":92,"t":"(Mûsâ) \"Ey Hârûn, oların saptıklarını gördüğün zaman sana ne engel oldu (da önlemedin)? dedi."},{"n":93,"t":"\"Neden bana uymadın, buyruğuma karşı mı geldin?\" (Ve kardeşinin sakalından tutup çekmeğe başladı.)"},{"n":94,"t":"(Hârûn, kardeşini yumuşatabilmek için): \"Ey anamın oğlu, dedi, sakalımı, başımı tutma. Ben senin ’İsrâil oğulları arasında ayrılık çıkardın, sözümü tutmadın’ diyeceğinden korktum (da onun için idare yoluna gittim).\""},{"n":95,"t":"(Mûsâ, Samiri’ye döndü): \"Ey Sâmiri, ya senin amacın nedir?\" dedi."},{"n":96,"t":"(Sâmiri): \"Ben dedi, onların görmediklerini gördüm. Elçinin eserinden bir avuç aldım da attım; nefsim bana böyle (yapmayı) hoş gösterdi.\""},{"n":97,"t":"(Mûsâ): \"Git, dedi. Artık hayât boyunca sen: ’Bana dokunmayın!’ diyeceksin (toplumdan refüze edilip yalnız başına kalacaksın), sana va’dedilen bir cezâ var ki ondan asla şaşırılmayacaksın (mutlaka o cezânı tam zamanında bulacaksın). Şimdi durup taptığın tanrına bak. Biz onu yakacağız, sonra onu ufalayıp denize savuracağız.\""},{"n":98,"t":"\"Tanrınız ancak kendisinden başka tanrı olmayan Allah’tır. O’nun bilgisi her şeyi kuşatmıştır.\""},{"n":99,"t":"Böylece sana geçmişlerin haberlerinden bir miktar anlatıyoruz. Gerçekten sana katımızdan bir Zikir (geçmiş olaylardan bir anı) verdik."},{"n":100,"t":"Kim ondan yüz çevirirse o, kıyâmet günü (ağır) bir günâh yüklenecekdir."},{"n":101,"t":"Sürekli olarak o yükün altında kalacaklardır. Kıyâmet gününde bu, onlar için ne kötü bir yüktür!"},{"n":102,"t":"O gün Sûr’a üflenir ve o gün suçluları, gömgök (kör bir durumda) süreriz."},{"n":103,"t":"Kendi aralarında gizli gizli, \"(dünyâda) On günden fazla kalmadınız\" derler."},{"n":104,"t":"Onların dedikleri(kalış süresi)ni biz daha iyi biliriz. En akıllıları ise: \"Siz yalnız bir gün kaldınız,\" der."},{"n":105,"t":"Sana dağlardan soruyorlar. De ki: \"Rabbim onları ufalayıp savuracak!"},{"n":106,"t":"Yerlerini boş, dümdüz bırakacaktır."},{"n":107,"t":"Orada ne bir eğrilik, ne de bir tümsek görmeyeceksin."},{"n":108,"t":"O gün hiç pürüzü olmayan çağrıcıya uyarlar; (ondan sapma imkânı yoktur). Rahmân’ın huzurunda sesler kısılır, fısıltıdan başka bir şey işitemezsin."},{"n":109,"t":"O gün Rahmân’ın izin verip sözünden hoşlandığı kimseden başkasının şefâ’ati fayda vermez."},{"n":110,"t":"O, onların önlerindekini ve arkalarındakini (geçmişlerini ve geleceklerini) bilir; onlar ise bilgice O’nu kavrayamazlar."},{"n":111,"t":"Bütün yüzler, o diri ve yöneticiye boyun eğmiştir. Zulüm yüklenen perişan olmuştur."},{"n":112,"t":"Kim inanarak iyi olan işlerden yaparsa artık o, ne zulümden, ne de hakkının çiğnenmesinden korkar."},{"n":113,"t":"Biz sana onu böyle Arapça bir Kur’ân olarak indirdik ve onda tehditleri türlü biçimlere çevirip açıkladık ki korunsunlar. Yahut (Kur’ân,) onlara bir hatırlama yaptırsın."},{"n":114,"t":"Gerçek hükümdar olan Allâh, yücedir. Sana vahyedilmesi henüz tamamlanmadan Kur’ân’ı acele okumağa kalkma; \"Rabbim, ilmimi artır!\" de."},{"n":115,"t":"Andolsun biz, önceden Âdem’e (o ağaçtan yememesini) emretmiştik, unuttu. Biz onda bir azim (ve sebât) bulmadık."},{"n":116,"t":"Meleklere: \"Âdem’e secede edin,\" demiştik, secde ettiler, yalnız İblis diretti."},{"n":117,"t":"Dedik ki: \"Ey Âdem, bu, senin ve eşinin düşmanıdır. Sakın, sizi cennetten çıkarmasın, sonra yorulursun.\""},{"n":118,"t":"\"Şimdi burada acıkmayacaksın, çıplak kalmayacaksın.\""},{"n":119,"t":"\"Ve sen susamayacaksın, kuşluk vakti güneşi(nin ısısı)ndan etkilenmeyeceksin.\""},{"n":120,"t":"Nihâyet şeytân ona fısıldayıp: \"Ey Âdem, sana ebedilik ağacını ve yok olmayacak bir hükümranlığı göstereyim mi? dedi."},{"n":121,"t":"O ağaçtan yediler. Böylece kendilerine kötü yerleri göründü (üreme organları ortaya çıktı). Üstlerini cennet yaprağıyle örtmeğe başladılar. Âdem Rabbinin buyruğuna karşı geldi de şaşırdı."},{"n":122,"t":"Sonra Rabbi onu seçti, tevbesini kabul etti, doğru yola iletti."},{"n":123,"t":"Dedi ki: \"Hepiniz oradan inin, birbirinize düşmansınız. İmdi benden size bir hidâyet geldiği zaman kim benim hidâyetime uyarsa o, sapmaz ve sıkıntıya düşmez.\""},{"n":124,"t":"\"Ama kim beni anmaktan yüz çevirirse, onun için de dar bir geçim var. Kıyâmet günü onu kör olarak (yüce Divâna) süreriz.\""},{"n":125,"t":"\"Rabbim der, niçin beni kör sürdün, oysa ben görür idim?\""},{"n":126,"t":"(Allâh) buyurur ki: \"Nasıl sana âyetlerimiz geldiği zaman, sen onları unuttuysan, bugün de sen öyle unutulursun!\""},{"n":127,"t":"İşte isrâf eden ve Rabbinin âyetlerine inanmayanları böyle cezâlandırırız. Elbette âhiretin azâbı daha çetin ve daha süreklidir."},{"n":128,"t":"(Bugün) meskenlerinde dolaştıkları, kendilerinden önce yaşamış nice nesilleri yok edişimiz onları hâlâ yola getirmedi mi? Elbette bunda akıl sâhipleri için ibretler vardır."},{"n":129,"t":"Eğer Rabbin tarafından söylenmiş bir söz ve belirtilmiş bir süre olmasaydı. (bunların da hemen helâk edilmeleri) gerekli olurdu."},{"n":130,"t":"Onların dediklerine sabret, güneşin doğmasından ve batmasından önce Rabbini överek tesbih et; gece sâ’atlerinden bir kısmında ve gündüzün taraflarında da tesbih et ki memnun olasın!"},{"n":131,"t":"Onlardan bazı zümrelere kendilerini denemek için verdiğimiz dünyâ hayâtının süsüne gözlerini dikme. Rabbinin rızkı daha hayırlı ve daha süreklidir."},{"n":132,"t":"Âilene namazı emret, kendin de namaz kılmaya dayan. Biz senden rızık istemiyoruz. Seni biz besliyoruz. Sonuç takvâ(sâhipleri)nindir."},{"n":133,"t":"Dediler ki: \"Rabbinden bize bir âyet (mu’cize) getirmeli değil mi?\" Onlara, önceki Kitap’larda bulunan kanıt gelmedi mi?"},{"n":134,"t":"Şâyet onları, ondan önce bir azâb ile helâk etseydik: \"Rabbimiz, bize bir elçi gönderseydin de böyle alçak ve rezil olmadan önce senin âyetlerine uysaydık!\" derlerdi."},{"n":135,"t":"De ki: \"Herkes gözetlemektedir. Gözetleyin, düzgün yolun sâhipleri kimdir, doğru yolda olan kimdir, bileceksiniz!\""}],[{"n":1,"t":"İnsanların hesapları yaklaştı, fakat onlar hâlâ gaflet içinde yüz çevirmektedirler."},{"n":2,"t":"Kendilerine Rablerinden gelen her yeni ikazı mutlaka eğlenerek dinlerler."},{"n":3,"t":"Kalbleri eğlencededir. O zulmedenler, aralarında şu konuşmayı gizlediler: \"Bu (Muhammed) de sizin gibi bir insan değil mi? Şimdi siz, göre göre büyüye mi kapılacaksınız?\""},{"n":4,"t":"Dedi ki: \"Rabbim gökte ve yerde konuşulan her sözü bilir, (O’ndan gizli kalan hiçbir şey yoktur). O, işitendir, bilendir.\""},{"n":5,"t":"\"Hayır, dediler, (bu) karmakarışık hayallerdir; hayır onu uydurmuş; hayır o şâ’irdir. (Eğer gerçekten peygamberse) öncekilerin, (mu’cizelerle) gönderildikleri gibi o da bize bir mu’cize getirsin.\""},{"n":6,"t":"Bunlardan önce helâk ettiğimiz hiçbir kent (halkı) inanmamıştı, şimdi bunlar mı inanacaklar?"},{"n":7,"t":"Biz, senden önce yalnız kendilerine vahyedilen erkeklerden başkasını elçi göndermedik. Eğer bilmiyorsanız Zikir ehline (Kitap sâhiplerine) sorun."},{"n":8,"t":"Biz onları yemek yemeyen ceset(ler) yapmadık. (Onlar), ölümsüz de değillerdi."},{"n":9,"t":"Sonra onlara verdiğimiz sözü yerine getirdik, onları ve dilediklerimizi kurtardık, aşırı gidenleri helâk ettik."},{"n":10,"t":"Andolsun, size, içinde Zikr’iniz bulunan bir Kitap indirdik. Aklınızı kullanmıyor musunuz?"},{"n":11,"t":"(Halkı) zulmeden nice şehri kırıp geçirdik ve onlardan sonra başka bir topluluk getirdik."},{"n":12,"t":"Azâbımızı hissettikleri zaman onlar, derhal oradan (kaçmak için hayvanlarını) mahmuzluyorlardı."},{"n":13,"t":"(Boşuna) Kaçmayın, (bol bol verilip) içinde şımartıldığınız(ni’metler)e ve yurtlarınıza dönün, çünkü sorguya çekileceksiniz!"},{"n":14,"t":"\"Eyvah bize, dediler, gerçekten biz zâlimlermişiz!\""},{"n":15,"t":"Bu mırıldanmaları sürüp giderken biz onları, biçilmiş (ekin gibi) yaptık, sönüp gittiler."},{"n":16,"t":"Biz göğü, yeri ve bunlar arasında bulunanları, eğlence için yaratmadık."},{"n":17,"t":"Eğer bir eğlence edinmek isteseydik, kendi katımızdan edinirdik. Yapacak olsaydık, böyle yapardık."},{"n":18,"t":"Hayır, biz hakkı bâtılın üstüne atarız da o onun beynini parçalar, derhal (bâtılın) canı çıkar. Allah’a yakıştırdığınız niteliklerden ötürü de vay siz(in haliniz)e!"},{"n":19,"t":"Göklerde ve yerde kim varsa hep O’nundur. O’nun yanında bulunanlar, O’na kulluk etmekten büyüklenmez ve yorulmazlar."},{"n":20,"t":"Gece gündüz tesbih ederler, hiç ara vermezler."},{"n":21,"t":"Yoksa (o müşrikler), yerden birtakım tanrılar edindiler de (ölüleri) onlar mı diriltecek?"},{"n":22,"t":"Eğer yerde, gökte Allah’tan başka tanrılar olsaydı, ikisi de (yer de, gök de) bozulup gitmişti. Arş’ın sâhibi Allâh, onların nitelendirmelerinden yüce(münezzeh)dir."},{"n":23,"t":"O, yaptığından sorulmaz, ama onlar, sorulurlar."},{"n":24,"t":"Yoksa O’ndan başka tanrılar mı edindiler? De ki: \"(Bu hususta kesin) delilinizi getirin. İşte benimle beraber olanların da öğütü ve benden öncekilerin de öğütü budur.\" Ama çokları hakkı bilmezler, bundan dolayı onlar, (haktan) yüz çevirirler."},{"n":25,"t":"Senden önce hiçbir peygamber göndermedik ki ona: \"Benden başka tanrı yoktur, bana kulluk edin!\" diye vahyetmiş olmayalım."},{"n":26,"t":"\"Rahmân çocuk edindi.\" dediler. O, yücedir. Hayır (Rahmân’ın çocukları sanılan melekler, O’nun) değerli kullar(ı)dır."},{"n":27,"t":"O’ndan önce söz söylemezler ve onlar, O’nun buyruğunu yaparlar."},{"n":28,"t":"(Allâh) Onların önlerinde ve arkalarında olanı bilir. (Allâh’ın) râzı olduğundan başkasına şefâ’at edemezler ve onlar, O’nun korkusundan titrerler."},{"n":29,"t":"Onlardan her kim: \"Ben O’ndan başka bir tanrıyım!\" derse onu cehennemle cezâlandırırız. Biz zâlimleri böyle cezâlandırırız."},{"n":30,"t":"O nankörler görmediler mi ki göklerle yer bitişik idi, biz onları ayırdık ve her canlı şeyi sudan yarattık? Hâlâ inanmıyorlar mı?"},{"n":31,"t":"Yer, onları sarsar diye, onun üstünde yüksek dağlar yarattık. Ve istedikleri yere gidebilmeleri için orada geniş yollar açtık."},{"n":32,"t":"Göğü, korunmuş bir tavan yaptık; onlarsa hâlâ göğün, (Allâh’ın) âyetlerinden yüz çevirmektedirler."},{"n":33,"t":"Geceyi, gündüzü, güneşi, ayı yaratan O’dur. (Bunların) her biri bir yörüngede yüzmektedir."},{"n":34,"t":"Senden önce hiçbir insana ebedi yaşama vermedik. Şimdi sen ölürsen onlar ebedi mi kalacaklar?"},{"n":35,"t":"Her nefis, ölümü tadacaktır. Biz sizi sınamak için şerre de hayra da müptelâ kılıyoruz. Ve (sonunda) bize döndürüleceksiniz."},{"n":36,"t":"Kâfirler seni gördükleri zaman: \"Sizin tanrılarınızı diline dolayan bu mu?\" diye seninle alay ederler. Oysa kendileri Rahmân’ın Zikri(uyarısı)nı kabul etmiyorlar."},{"n":37,"t":"(İnsanın tabiatinde acelecilik vardır. Öye acelecidir ki, sanki) İnsan aceleden yaratılmıştır. (Durun,) Size âyetlerimi göstereceğim, benden acele istemeyin."},{"n":38,"t":"\"Doğru söyleyenler iseniz bu (bizi) tehdid (ettiğiniz azâb) ne zaman?\" diyorlar."},{"n":39,"t":"İnkâr edenler, ne yüzlerinden, ne de sırtlarından ateşi savamayacakları ve yardım da olunmayacakları zamanı bir bilselerdi (onu böyle acele istemezlerdi)!"},{"n":40,"t":"Doğrusu o, onlara ansızın gelecek, onları şaşırtacak, ne onu reddedebilecekler, ne de kendilerine süre verilecek."},{"n":41,"t":"Andolsun, senden önceki peygamberlerle de alay edildi, ama onlarla alay edenleri, o alay ettikleri şey kuşatıverdi."},{"n":42,"t":"De ki: \"Gece gündüz, sizi Rahmân’dan kim koruyacak?\" Hayır, onlar, Rablerinin Zikr’inden yüz çeviriyorlar."},{"n":43,"t":"Yoksa onları, bize karşı koruyacak tanrıları mı var? Onlar, ne kendilerine yardım edebilirler, ne de bizim tarafımızdan onlara sâhip çıkılır."},{"n":44,"t":"Biz onları ve atalarını yaşattık, nihâyet kendilerine ömür uzun geldi, (ebedi yaşayacaklarını sandılar). Bizim, yere gelip, onu uçlarından eksilttiğimizi görmüyorlar mı? Üstün gelen onlar mı (yoksa biz miyiz)?"},{"n":45,"t":"De ki: \"Ben ancak sizi vahiyle uyarıyorum. Ama sağır(lar) uyarıldıkları zaman çağırıyı işitmez(ler).\""},{"n":46,"t":"Andolsun, onlara Rabbinin azâbından bir esinti dokunsa, \"Eyvah bize, biz gerçekten zâlimlermişiz,\" derler."},{"n":47,"t":"Kıyâmet günü için adâlet terâzileri kurarız. Hiç kimseye bir haksızlık edilmez (insanın yaptığı iş), bir hardal dânesi ağırlığınca da olsa onu getiririz. Hesab gören olarak biz yeteriz."},{"n":48,"t":"Andolsun biz, Mûsâ’ya ve Hârûn’a hak ve bâtılı ayırdeden ve korunanlar için bir ışık ve öğüt olan Kitabı verdik."},{"n":49,"t":"Korunanlar görmeden Rablerinden korkarlar ve (Duruşma) sâ’at(in)den de titrerler."},{"n":50,"t":"Bu (Kur’ân) da ona (yani Muhammed’e) indirdiğimiz mübârek (çok faydalı) bir öğüttür. Şimdi siz onu inkâr mı ediyorsunuz? (Ne kadar gâfilsiniz siz)!"},{"n":51,"t":"Andolsun biz, daha önceden İbrâhim’e de doğru yolu bulma yeteneğini vermiştik. Zaten biz onu(n olgun insan olduğunu) biliyorduk."},{"n":52,"t":"Babasına ve kavmine demişti ki: \"Sizin şu karşısında durup taptığınız heykeller nedir?\""},{"n":53,"t":"\"Babalarımızı onlara tapar bulduk (da onun için biz de onlara tapıyoruz.)\" dediler."},{"n":54,"t":"\"Doğrusu siz de, babalarınız da açık bir sapıklık içine düşmüşsünüz!\" dedi."},{"n":55,"t":"Dediler ki: \"Sen bize gerçeği mi getirdin, yoksa şaka yapanlardan mısın?\""},{"n":56,"t":"\"Hayır, dedi, Rabbiniz, göklerin ve yerin Rabbidir ki, onları yaratmıştır. Ben de buna şâhidlik edenlerdenim.\""},{"n":57,"t":"\"Allah’a and olsun ki siz dönüp gittikten sonra putlarınıza bir tuzak kuracağım!\""},{"n":58,"t":"Nihâyet (İbrâhim) onları parça parça etti, yalnız onların büyüğünü bıraktı; belki ona müracaat ederler diye(!)"},{"n":59,"t":"(Döndükleri zaman): \"Bunu tanrılarımıza kim yaptı? Muhakkak o zâlimlerden biridir.\" dediler."},{"n":60,"t":"\"Onları diline dolayan bir genç işittik, kendisine İbrâhim deniliyormuş,\" dediler."},{"n":61,"t":"\"Onu insanların gözü önüne getirin de (nasıl cezâlandırılacağına) tanık olsunlar\" dediler."},{"n":62,"t":"(İbrâhim’i getirdiler), dediler ki: \"İbrâhim, tanrılarımıza sen mi bunu yaptın?\""},{"n":63,"t":"\"Hayır dedi, (büyük putu göstererek) işte şu büyükleri yapmış; onlara sorun, eğer konuşurlarsa (!)\""},{"n":64,"t":"Kendi vicdanlarına başvurup (içlerinden): \"Hakikaten sizler haksızsınız!\" dediler."},{"n":65,"t":"Sonra yine eski kafalarına döndürüldüler: \"Sen de bilirsin ki bunlar konuşmazlar,\" dediler."},{"n":66,"t":"\"Peki, dedi, siz Allâh’ı bırakıp da size hiçbir fayda ve zarar vermeyen şeylere mi tapıyorsunuz?\""},{"n":67,"t":"\"Yuh size ve Allah’tan başka taptıklarınıza. Aklınızı kullanmıyor musunuz siz?\""},{"n":68,"t":"Dediler: \"Onu yakın, tanrılarınıza yardım edin, eğer bir iş yapacaksanız.\""},{"n":69,"t":"Biz de: \"Ey ateş, İbrâhim’e serin ve esenlik ol!\" dedik."},{"n":70,"t":"Ona bir tuzak kurmak istediler. Biz de, asıl kendilerini hüsrâna uğrattık."},{"n":71,"t":"Onu ve Lût’u kurtarıp, âlemlere bereketli kıldığımız bir yere getirdik."},{"n":72,"t":"Ona İshak’ı hediye ettik, üstelik (torunu) Ya’kûb’u da (verdik). Hepsini de iyi insanlar yaptık."},{"n":73,"t":"Onları, emrimizle doğru yolu gösteren önderler yaptık ve onlara hayırlı işler yapmayı, namaz kılmayı ve zekât vermeyi vahyettik. Onlar bize kulluk eden(insan)lardı."},{"n":74,"t":"Lût’a da hüküm (hükümranlık, peygamberlik, hikmet) ve ilim verdik ve onu çirkin işler yapan bir kentten kurtardık. Gerçekten onlar yoldan çıkan kötü bir kavim idiler."},{"n":75,"t":"Ve onu rahmetimizin içine soktuk. Çünkü o, Sâlihlerden idi."},{"n":76,"t":"Nûh’u da (an), o da bunlardan önce bize yalvarmıştı. Biz de onun du’âsını kabul edip kendisini ve âilesini büyük sıkıntıdan kurtarmıştık."},{"n":77,"t":"Ve âyetlerimizi yalanlayan kavimden onun öcünü almıştık. Onlar, kötü bir kavim olmuşlardı, biz de onların hepsini boğmuştuk."},{"n":78,"t":"Dâvûd ile Süleymân’ı da (an); hani onlar, toplumun davarının yayıldığı bir ekin hakkında hükmediyorlardı, biz de onların hükümlerine tanık idik."},{"n":79,"t":"O hükmü Süleymân’a bellettik. Onların hepsine de hükümdarlık ve bilgi verdik. Dâvûd’a dağları ve kuşları boyun eğdirdik, onunla beraber tesbih ediyorlardı. Biz (bunları) yaparız."},{"n":80,"t":"Ona, sizi, savaşın şiddetinden korumak için zırh yapmayı öğretmiştik. Ama siz şükrediyor musunuz ki?"},{"n":81,"t":"Süleymân’a da fırtınayı (boyun eğdirmiştik). Onun emriyle, içinde bereketler yarattığımız yere akıp giderdi. Biz her şeyi biliriz."},{"n":82,"t":"Kendisi için denize dalan ve bundan başka işler yapan bazı şeytânları da emrine vermiştik. Biz onları onun emrinde tutuyorduk."},{"n":83,"t":"Eyyûb’u da an. O, Rabbine: \"Bu dert bana dokundu, sen merhametlilerin en merhametlisisin!\" diye du’â etmişti."},{"n":84,"t":"Biz de onun du’âsını kabul etmiş, kendisine bulaşan derdi kaldırmıştık; ona tarafımızdan bir rahmet ve ibâdet edenler için bir öğüt olarak âilesini ve onlarla beraber bir katını daha vermiştik."},{"n":85,"t":"İsmâ’il’i, İdris’i, Zu’l-Kifl’i de an; hepsi de sabredenlerdendi."},{"n":86,"t":"Onları rahmetimize soktuk, çünkü onlar Sâlihlerdendi."},{"n":87,"t":"Zünnûn’u (balık karnına girmiş olan Yûnus ibn Matta’yı) da an; zira (o, kavmine) kızarak gitmişti, bizim kendisine güç yetiremeyeceğimizi, (kavminin arasından çıkmakla kendisini kurtaracağını) sanmıştı. Nihâyet karanlıklar içinde (kalıp): \"Senden başka tanrı yoktur. Senin şânın yücedir, ben zâlimlerden oldum!\" diye yalvardı."},{"n":88,"t":"Biz de onun du’âsını kabul ettik ve onu tasadan kurtardık. İşte biz, inananları böyle kurtarırız."},{"n":89,"t":"Zekeriyyâ’yı da (an). Rabbine: \"Rabbim, beni tek bırakma! Sen, vârislerin en iyisisin (her şeyim sana kalacaktır)\" diye du’â etmişti."},{"n":90,"t":"Onun du’âsını da kabul buyurduk ve ona Yahyâ’yı armağan ettik. Eşini de kendisi için ıslah ettik (çocuk doğurmağa elverişli bir hale getirdik). Gerçekten onlar hayır işlere koşarlar, umarak ve korkarak bize du’â ederlerdi ve bize derin saygı gösterirlerdi."},{"n":91,"t":"O ırzını korumuş olan(Meryem)i de an; ona ruhumuzdan bir çocuk üflemiş, kendisini ve oğlunu âlemlere bir ibret yapmıştık."},{"n":92,"t":"İşte bu sizin ümmetiniz (olan tevhid ve İslâm milleti), bir tek ümmettir. Rabbiniz de benim. Yalnız bana kulluk edin."},{"n":93,"t":"İşlerini aralarında parçaladılar (Tanrıdan gelen dini parça parça ettiler, ayrılığa düştüler); hepsi (sonunda) bize döneceklerdir."},{"n":94,"t":"İmdi kim inanmış olarak iyi işlerden yaparsa onun çalışmasına nankörlük edilmez, biz (onun çalışmasını) yazanlarız."},{"n":95,"t":"Helâk ettiğimiz bir ülkeye artık (yaşamak) harâmdır: Onlar bir daha geri dönemezler."},{"n":96,"t":"Nihâyet Ye’cûc ve Me’cûc’un önü açıldığı ve onlar her tepeden akın etmeye başladıkları zaman,"},{"n":97,"t":"Gerçek va’d (yani kıyâmet) yaklaşmış olur. İnkâr edenlerin gözleri birden donup kalır. \"Vah bize, biz bundan gaflet içinde idik (bunun doğru olacağını hiç düşünmüyorduk). Meğer biz zulmediyormuşuz!\" (diye mırıldandılar)."},{"n":98,"t":"Siz ve Allah’tan başka taptıklarınız cehennemin odunusunuz. Siz, oraya gireceksiniz."},{"n":99,"t":"Eğer onlar tanrı olsalardı oraya girmezlerdi. Oysa hepsi orada sürekli kalacaklardır."},{"n":100,"t":"Onlar için bir inleme ve soluma vardır! Ve onlar orada (azâbın dehşeti içinde hiçbir şey) işitmezler."},{"n":101,"t":"Ama bizden kendilerine (ezelde) güzellik geçmiş (mutluluk takdir edilmiş) olanlar, işte onlar, ondan (cehennemden) uzaklaştırılmışlardır."},{"n":102,"t":"Onun uğultusunu duymazlar. Ve canlarının çektiği (ni’metler) içinde ebedi kalırlar."},{"n":103,"t":"O en büyük korku, onları asla tasalandırmaz. Melekler onları şöyle karşılar: \"İşte bu, size va’dedilen gününüzdür!\""},{"n":104,"t":"O gün göğü yazı tomarlarını dürer gibi toplarız. İlk yaratmaya başladığımız gibi onu iâde ederiz. Üzerimize sözdür; biz bunu mutlaka yapacağız."},{"n":105,"t":"Andolsun Tevrât’tan sonra Zebûr’da da: \"Arza mutlaka iyi kullarım vâris olacak (bu yer onların eline geçecek)\" diye yazmıştık."},{"n":106,"t":"Şüphesiz bunda kulluk eden kimseler için yeterli bir öğüt vardır."},{"n":107,"t":"(Ey Muhammed) Biz seni ancak âlemlere rahmet için gönderdik."},{"n":108,"t":"De ki: \"Bana, Tanrınız, ancak bir tek Tanrıdır; diye vahyolunur. O’na teslim ol(up putperestliği bırak)cak mısınız?"},{"n":109,"t":"Eğer yüz çevirirlerse de ki: \"Ben sizin hepinize eşit biçimde açıkladım. Artık tehdid edildiğiniz şeyin yakın mı, yoksa uzak mı olduğunu bilmem.\""},{"n":110,"t":"\"Şüphesiz O, sözün açığını da bilir, gizlediklerinizi de bilir.\""},{"n":111,"t":"\"Bilmem belki de o (azâbın ertelenmesi) sizi denemek ve bir süreye kadar yaşatmak içindir\""},{"n":112,"t":"(Allâh’ın Resulü) Dedi: \"Rabbim (aramızda) hak ile hükmet, Rabbimiz çok merhamet edendir. Sizin nitelendirdiğinize (iftirâlarınıza) karşı O’nun yardımına sığınılır (O, bizi her tehlikeden korur)!\""}],[{"n":1,"t":"Ey insanlar, Rabbinizden korkun, çünkü (Duruşma) sâ’ati(ni)n depremi, cidden korkunç bir şeydir."},{"n":2,"t":"Onu gördüğünüz gün, her emziren, emzirdiğinden geçer; her gebe yükünü bırakır; insanları sarhoş görürsün, oysa sarhoş değillerdir ama Allâh’ın azâbı şiddetlidir (bu dehşetli azâb, onların akıllarını başlarından almıştır.)"},{"n":3,"t":"İnsanlardan kimi, Allâh hakkında bilmeden tartışır ve her kaba (şarlatan) şeytâna uyar."},{"n":4,"t":"O (Şeytâ)nın hakkında: \"Kim bunu takibederse muhakkak bu, onu saşırtır ve onu alevli ateş azâbına götürür\" diye yazılmıştır."},{"n":5,"t":"Ey insanlar eğer öldükten sonra dirilmekten kuşkuda iseniz (bilin ki) biz sizi (önce) topraktan, sonra nutfe(sperm)den, sonra alaka(embriyo)dan, sonra biçimlenen ve biçimlenmeyen bir çiğnem et parçasından yarattık ki, size (kudretimizi) açıkça gösterelim. Dilediğimizi belirtilmiş bir süreye kadar rahimlerde tutarız, sonra sizi bir bebek olarak çıkarırız. Sonra güç(ve kabiliyetler)inize ermeniz için (sizi büyütürüz). İçinizden kimi (henüz çocukken) öldürülür, kimi de ömrün en kötü çağına(ihtiyarlığa) itilir ki, bilirken bir şey bilmez hale gelsin (çocukluğundaki gibi bedence ve akılca güçsüz bir duruma düşsün). Yeri de kurumuş, ölmüş görürsün. Fakat biz onun üzerine suyu indirdiğimiz zaman titreşir, kabarır ve her güzel çifti bitirir."},{"n":6,"t":"Bu böyledir. Çünkü Allâh, tek gerçektir. (Her şey O’nunla varlık kazanır) ve O, ölüleri diriltir ve O, her şeyi yapabilir."},{"n":7,"t":"Ve (çünkü) o (duruşma) sâ’at(i) mutlaka gelecektir, onda şüphe yoktur. Ve Allâh, kabirlerde olanları diriltecektir."},{"n":8,"t":"İnsanlardan kimi bilmeden, ne bir yol göstereni, ne de aydınlatıcı bir Kitabı olmadan, Allâh hakkında tartışır."},{"n":9,"t":"Allâh’ın yolundan şaşırtmak için boynunu öteye döndürerek (kabara kabara tartışmasını sürdürür), dünyâda onun için bir kepazelik vardır. Kıyâmet günü de ona yangın azâbını taddıracağız:"},{"n":10,"t":"(Ey insan), \"İşte bu, senin ellerinin yapıp öne sürdüğü işler yüzündendir. Allâh kullara zulmedici değildir!\""},{"n":11,"t":"İnsanlardan kimi de Allah’a bir kenardan, ibâdet eder. Eğer kendisine bir hayır gelirse onunla huzûra kavuşur (sevinir) ve eğer başına bir kötülük gelirse yüz üstü döner (dini kötüleyerek ondan vazgeçer). O, dünyâyı da, âhireti de kaybetmiştir. İşte apaçık ziyan budur."},{"n":12,"t":"Allah’tan ayrı olarak kendisine ne zarar, ne de yarar veremeyen şeylere yalvarır. İşte (doğru yoldan) uzak(lara) sapma budur!"},{"n":13,"t":"Zararı, faydasından daha yakın olana yalvarır. (O), Ne kötü bir yardımcı ve ne kötü bir arkadaştır!"},{"n":14,"t":"Allâh, inanan ve iyi işler yapanları, altlarından ırmaklar akan cennetlere sokacaktır. Şüphesiz Allâh istediğini yapar."},{"n":15,"t":"Kim Allâh’ın, dünyâda ve âhirette kendisine yardım etmeyeceğini sanıyorsa öfkesini gidermek için göğe bir sebep(ip)le uzansın, sonra (ayaklarını yerden) kessin de baksın, bu çaresi, öfkelendiği şeyi giderebilecek mi?"},{"n":16,"t":"Ve işte biz Kur’ân’ı böyle açık açık âyetler olarak indirdik. Şüphesiz Allâh, dilediğini doğru yola iletir."},{"n":17,"t":"İnananlar, yahûdiler, sâbiiler, hırıstiyanlar, mecûsiler ve (Allah’a) ortak koşanlar... Allâh, kıyâmet günü bunlar arasında hüküm verecek(haklıyı haksızı ortaya çıkaracak)tır. Şüphesiz Allâh, her şeye şâhidtir!"},{"n":18,"t":"Görmedin mi (baksana), göklerde, yerde bulunan kimseler, güneş, ay, yıldızlar, dağlar, ağaçlar, hayvanlar ve insanlardan birçoğu hep Allah’a secde ediyorlar! Ama birçoğuna da azâb hak olmuştur. Allâh kimi aşağılatırsa artık ona değer veren olmaz. Allâh, dilediğini yapar."},{"n":19,"t":"İşte şunlar, Rableri hakkında çekişen iki hasım taraf: Nankörler için ateşten giysi biçildi, başlarının üstünden de kaynar su dökülüyor!"},{"n":20,"t":"Onunla karınlarının içindekiler ve derileri eritiliyor."},{"n":21,"t":"(Ayrıca) onlar için demir kamçılar da var."},{"n":22,"t":"Oradan, (o) gamdan her çıkmak istediklerinde (demir kamçılarla vurularak) oraya geri çevrilirler ve: \"Yangın azâbını tadın!\" (denilir)."},{"n":23,"t":"Allâh, inanan ve iyi işler yapanları da altlarından ırmaklar akan cennetlere sokar. Orada altun bilezikler ve inci(ler) takınırlar. Orada giysileri de ipektir."},{"n":24,"t":"Sözün güzeline ve çok övülen(Allâh)ın yoluna iletilmişlerdir."},{"n":25,"t":"Nânkörlük edenler, Allâh’ın yolundan ve gerek yerli, gerek dışarıdan gelen bütün insanlar için ibâdet yeri yaptığımız Mescid-i Harâm’dan (insanları) geri çevirenler (bilsinler ki), kim orada (böyle) zulüm ile haktan sapmak isterse ona acı bir azâb taddırırız."},{"n":26,"t":"Bir zamanlar İbrâhim’i Beyt(Ka’be’n)in yerine kondurmuş(ve ona şöyle emretmiş)tik: \"Bana hiçbir şeyi ortak koşma ve tavâf edenler, ayakta duranlar, rükû’ ve secde edenler için Evimi temizle.\""},{"n":27,"t":"İnsanlar içinde haccı ilân et; yaya olarak veya uzak yollardan gelen yorgun develer üzerinde sana gelsinler."},{"n":28,"t":"Ki kendileri için birtakım faydalara tanık olsunlar ve (Allâh’ın) kendilerine rızık olarak verdiği hayvanlar üzerine belli günlerde (onları kurban ederken) Allâh’ın adını ansınlar. Onlardan yeyin, sıkıntı içinde bulunan fakire de yedirin."},{"n":29,"t":"Sonra (bıyıklarını, tırnaklarını kesmek, sair temizlik gereklerini yapmak sûretiyle) Kirlerini gidersinler, adaklarını yerine getirsinler ve Eski Ev(Ka’be’y)i tavâf etsinler."},{"n":30,"t":"İşte öyle. Kim Allâh’ın yasaklarına saygı gösterirse, o (hareketi), Rabbinin yanında kendisi için iyidir. Size (âyetlerle) oku(nup açıkla)nanlar dışındaki hayvanlar sizin için helâl kılınmıştır. Artık o pis putlardan ve yalan sözden kaçının."},{"n":31,"t":"Allah’a ortak koşmadan, halis olarak O’nu birleyenler olun. Kim Allah’a ortak koşarsa, o, sanki gökten düşmüş de kendisini kuş kapıyor veya rüzgâr onu, uzak bir yere sürüklüyor gibidir."},{"n":32,"t":"İşte böyle. Kim Allâh’ın nişanlarına (hac ibâdetlerine ve kurbanlara) saygı gösterirse, bu, kalblerin takvâsındandır (kalblerinde Allâh korkusu olanlar, O’nun dininin işâretlerine saygı gösterirler)."},{"n":33,"t":"O(hayva)nlarda belli bir süreye kadar sizin için menfaatler vardır. Sonra onların varacakları yer, Eski Ev(Ka’be)dir. (Orada kurban edilirler)."},{"n":34,"t":"Biz, her ümmet için bir kurban ibâdeti koyduk ki Allâh’ın kendilerine rızık olarak verdiği hayvanların üzerine O’nun adını ansınlar. Tanrınız bir tek Tanrıdır, yalnız O’na teslim olun. (Ey Muhammed) o alçak gönüllü, saygılı, samimi insanları müjdele;"},{"n":35,"t":"Onlar ki Allâh anıldığı zaman kalbleri titrer. Başlarına gelene sabrederler, namazı kılarlar ve kendilerine verdiğimiz rızıktan (Allâh yoluna) harcarlar."},{"n":36,"t":"Biz o kurbanlık develeri de size Allâh’ın (dininin) işâretlerinden yaptık. Onlarda sizin için hayır vardır. Onlar ön ayaklarını sıra halinde yere basmış durumda iken üzerlerine Allâh’ın adını anın (da boğazlayın) yanları yere düş(üp canları çık)ınca da onlardan yeyin, kanâat eden(fakir)e de; isteyen(fakir)e de yedirin. Allâh o(kocaman hayva)nları, size boyun eğdirdi ki şükredesiniz."},{"n":37,"t":"Onların etleri ve kanları Allah’a ulaşmaz. Fakat sizin takvânız O’na ulaşır. Allâh onları size böyle boyun eğdirdi ki, sizi doğru yola ilettiği için O’nun büyüklüğünü anasınız. (Ey Muhammed), güzel davrananları müjdele."},{"n":38,"t":"Allâh inananları savunur. Allâh hiçbir hâin, nankörü sevmez."},{"n":39,"t":"Kendileriyle savaşılan(mü’min)lere (karşı koyma) izn(i) verildi. Çünkü onlara zulmedilmiştir ve şüphesiz Allâh, onlara yardım etmeğe kâdirdir."},{"n":40,"t":"Onlar, sırf \"Rabbimiz Allah’tır\" dedikleri için haksız yere yurtlarından çıkarıldılar. Eğer Allâh’ın bazı insanları diğer bazılarıyle savunması olmasaydı, içlerinde Allâh’ın ismi çok anılan manastırlar, kiliseler, havralar ve mescidler yıkılırdı. Allâh, kendi(dini)ne yardım edene elbette yardım eder. Kuşkusuz Allâh, kuvvetlidir, gâlibdir."},{"n":41,"t":"O (Allâh’ın dinine yardım ede)nleri yer yüzünde iktidâra getirdiğimiz takdirde (zorbaların yoluna sapmazlar, bil’akis) namazı kılarlar, zekâtı verirler, iyiliği emrederler, kötülükten vazgeçirmeğe çalışırlar. Bütün işlerin sonu Allah’a âittir (her şey sonunda O’na varacaktır)."},{"n":42,"t":"(Ey Muhammed), eğer (bunlar) seni yalanlıyorlarsa (bil ki) bunlardan önce Nûh, ’Âd ve Semûd kavmi de yalanlamıştı."},{"n":43,"t":"İbrâhim kavmi ve Lût kavmi de (yalanlamıştı)."},{"n":44,"t":"Medyen halkı da (yalanlamıştı); Mûsâ da yalanlanmıştı. Ben de kâfirlere bir süre vermiş, sonra onları yakalamıştım. (Bak), benim (onları) inkârım (görülmemiş biçimde cezâlandırmam) nasıl oldu!"},{"n":45,"t":"(Halkı) zulmederken helâk ettiğimiz nice kent vardır ki duvarları (yıkılan) tavanlarının üstüne çökmüştür. Nice kullanılmaz olmuş kuyu ve nice (ıssız kalmış) sağlam köşk vardır!"},{"n":46,"t":"Hiç yeryüzünde gezmediler mi ki (kendilerinden önce mahvolanların yerlerini görsünler de) düşünecekleri kalbleri, işitecekleri kulakları olsun (akıllları başlarına gelsin, hak sözünü işitsinler). Zira gözler kör olmaz (çünkü gözlerin körlüğü, geçici bir görme yetersizliğidir); fakat (asıl) göğüslerdeki kalbler kör olur."},{"n":47,"t":"Senden azâbı çabuk istiyorlar. Allâh sözünden caymaz. (Ama herşeyin bir zamanı vardır. O, acele etmez. Zirâ) Rabbinin yanında bir gün, sizin saydıklarınızdan bin yıl gibidir."},{"n":48,"t":"Nice kent var ki zulmederken ona biraz süre vermişim, sonra onu yakalamışımdır. Sonunda dönüş ancak banadır."},{"n":49,"t":"De ki: \"Ey insanlar, ben sizin için ancak apaçık bir uyarıcıyım.\""},{"n":50,"t":"İnanıp iyi işler yapanlar için mağfiret ve bol rızık vardır."},{"n":51,"t":"Âyetlerimizi etkisiz bırakmak için çalışanlara gelince, onlar da cehennemin adamlarıdır."},{"n":52,"t":"Senden önce hiçbir resûl ve nebi göndermemiştik ki o, temenni ettiği zaman, şeytân onun temennisine (bir düşünce) atmış olmasın. Fakat Allâh, şeytânın attığını siler, sonra kendi âyetlerini sağlamlaştırır. Allâh, ’alim(bilen)dir, hakim (sağlamlaştıran)dır."},{"n":53,"t":"(Allâh, böyle yapar ki) Şeytânın attığını, kalblerinde hastalık olanlar ve kalbleri katılaşanlar için bir imtihan yapsın; zâlimler uzak bir ayrılık içindedirler."},{"n":54,"t":"Ve kendilerine ilim verilmiş olanlar da o(Kur’â)nın, Rabbinden (gelen) gerçek olduğunu bilsinler de ona inansınlar; böylece kalbleri ona saygı duysun. Şüphesiz Allâh, inananları mutlaka doğru yola iletir."},{"n":55,"t":"İnkâr edenler ise ansızın o sâ’at (kıyâmet veya ölüm) kendilerine gelinceye yahut o kısır (hayırsız) günün azâbı kendilerine gelinceye kadar o(Kur’â)ndan yana, kuşku içinde olacaklardır."},{"n":56,"t":"O gün mülk Allâh’ındır. (O) onların aralarında hükmeder. İnananlar ve iyi işler yapanlar ni’met cennetlerindedirler."},{"n":57,"t":"İnkâr edip âyetlerimizi yalanlayanlara da alçaltan bir azâb vardır."},{"n":58,"t":"Allâh yolunda göç edip sonra öldürülen veya ölenlere gelince, Allâh onları en güzel bir rızıkla besleyecektir. Doğrusu Allâh, rızık verenlerin en iyisidir."},{"n":59,"t":"Onları râzı olacakları bir yere sokacaktır. Doğrusu Allâh, bilendir, halimdir."},{"n":60,"t":"İşte böyle. Kim kendisine yapılan cezânın dengiyle cezâ verir de sonra kendisine tekrar saldırılırsa elbette, Allâh ona yardım eder. Şüphesiz Allâh, affeden, bağışlayandır."},{"n":61,"t":"İşte böyle. (Allâh), geceyi gündüzün içine sokar, gündüzü gecenin içine sokar. Doğrusu Allâh, işiten ve görendir."},{"n":62,"t":"İşte böyle. Çünkü Allâh, Hak’tır, O’ndan başka yalvardıkları ise bâtıldır (aslı olmayan yalan şeylerdir). İşte çok yüce, çok büyük olan, Allah’tır."},{"n":63,"t":"Görmedin mi Allâh gökten bir su indirdi de yer yeşeriyor. Doğrusu Allâh latiftir (bilgisi veya lutfu en ince ve nazik şeylere kadar varır), habirdir (her türlü tedbiri bilir, her şeyi haber alır)."},{"n":64,"t":"Göklerde ve yerde ne varsa hep O’nundur. Allâh; işte zengin O’dur, övülmeğe lâyık O’dur."},{"n":65,"t":"Görmedin mi Allâh, yerdekileri ve emriyle, (koyduğu kanunla) denizde akıp giden gemileri sizin buyruğunuza verdi. Yerin üstüne düşmesin diye göğü tutuyor. (Gök) ancak O’nun izniyle düşer. Çünkü Allâh, insanlara çok şefkatli, çok merhametlidir."},{"n":66,"t":"O’dur ki sizi diriltti, sonra sizi öldürür, sonra yine sizi diriltir. Gerçekten insan çok nankördür."},{"n":67,"t":"Biz her ümmete, uydukları bir mensek (ibâdet yöntemi) yaptık. Bu işte seninle asla çekişmesinler. Sen Rabbine çağır, kuşkusuz sen doğru bir yol üzerindesin."},{"n":68,"t":"Eğer seninle mücâdele ederlerse: \"Allâh yaptıklarınızı daha iyi bilir\" de."},{"n":69,"t":"\"Allâh kıyâmet günü, ayrılığa düştüğünüz hususlarda aranızda hükmedecek (haklıyı, haksızı ayıracak)tır.\""},{"n":70,"t":"Bilmez misin ki Allâh gökte ve yerde ne varsa hepsini bilir. Bunların hepsi, bir Kitaptadır (katında yazılıdır). Bu, Allah’a kolaydır."},{"n":71,"t":"Allah’tan ayrı olarak öyle şeylere tapıyorlar ki (Allâh), onlara hiçbir kudret indirmemiştir. Kendilerinin de onların tanrı olabileceği hakkında bir bilgileri yoktur. O zâlimlerin yardımcısı yoktur."},{"n":72,"t":"Kendilerine apaçık âyetlerimiz okunduğu zaman kâfirlerin yüzlerinde hoşnutsuzluk belirdiğini anlarsın. Neredeyse kendilerine âyetlerimizi okuyanların üzerine saldıracaklar. De ki: \"Size bundan (bu öfkeli durumunuzdan) daha kötü bir şey haber vereyim mi? Varacağınız ateş! Allâh onu kâfirlere va’detmiştir. Ne kötü sonuçtur (o)!\""},{"n":73,"t":"Ey insanlar, size bir temsil verildi, onu dinleyin: O Allah’tan başka yalvardıklarınız (var ya), onların hepsi bir araya toplansalar, bir sinek dahi yaratamazlar. Sinek onlardan bir şey kapsa, bunu ondan kurtaramazlar. İsteyen de âciz, istenen de."},{"n":74,"t":"Allâh’ı layikıyle takdir edemediler (O’nu gereği gibi bilemediler). Allâh kuvvetlidir, üstündür."},{"n":75,"t":"Allâh meleklerden de, insanlardan da elçiler seçer. Allâh, işitendir, görendir."},{"n":76,"t":"Onların önlerinde ve arkalarında olan (bütün olayları, yaptıkları bütün işler)i bilir. Bütün işler Allah’a döndürülür."},{"n":77,"t":"Ey inananlar, rükû’ edin, secde edin, Rabbinize ibâdet edin, hayır işleyin ki umduğunuza eresiniz."},{"n":78,"t":"Allâh uğrunda, O’na yaraşır biçimde cihâd edin. O, sizi seçti ve dinde size bir güçlük yüklemedi; babanız İbrâhim’in dini(ne uyun). O (Allâh) bu (Kur’â)ndan önce(ki Kitaplarda) da, bu(Kur’â)nda da size \"müslümanlar\" adını verdi ki, Elçi size şâhid olsun, siz de insanlara şâhid olasınız. Haydi namazı kılın, zekâtı verin ve Allah’a sarılın; sâhibiniz O’dur. Ne güzel sâhip ve ne güzel yardımcıdır (O)!"}],[{"n":1,"t":"Felâha ulaştı o mü’minler."},{"n":2,"t":"Ki onlar, namazlarında saygılıdırlar."},{"n":3,"t":"Onlar boş şeylerden yüz çevirirler."},{"n":4,"t":"Onlar zekâtı verirler."},{"n":5,"t":"Ve onlar ırzlarını korurlar."},{"n":6,"t":"Ancak eşleri, yahut ellerinin sâhip olduğu (câriyeler) hariç. (Bunlarla ilişkilerinden dolayı da) onlar kınanmazlar."},{"n":7,"t":"Ama bunun ötesine gitmek isteyen olursa, işte onlar haddi aşanlardır."},{"n":8,"t":"Ve o(mü’min)ler emânetlerine ve ahidlerine özen gösterirler."},{"n":9,"t":"Onlar namazlarını (vakitlerinde kılarak) korurlar."},{"n":10,"t":"İşte vâris olacaklar onlardır."},{"n":11,"t":"Onlar (en yüksek cennet olan) Firdevs’e vâris olacaklar, orada ebedi kalacaklardır."},{"n":12,"t":"Andolsun biz insanı çamurdan bir süzmeden yarattık."},{"n":13,"t":"Sonra onu bir nutfe (sperm) olarak sağlam bir karar yerine koyduk."},{"n":14,"t":"Sonra nutfeyi alaka(embriyo)ya çevirdik, alaka(embriyo)yı bir çiğnemlik ete çevirdik, bir çiğnemlik eti kemiklere çevirdik, kemiklere et giydirdik; sonra onu bambaşka bir yaratık yaptık. Yaratanların en güzeli Allâh, ne yücedir!"},{"n":15,"t":"Sonra siz, bunun ardından öleceksiniz."},{"n":16,"t":"Sonra, siz kıyâmet günü muhakkak diriltileceksiniz."},{"n":17,"t":"Üstünüzde de yedi tabaka (yedi gök) yarattık. Biz yaratmadan gâfil değiliz."},{"n":18,"t":"Gökten belli ölçü ve miktarda su indirip onu yerde durdurduk. Biz onu (indirmeğe kâdir olduğumuz gibi) gidermeğe de kâdiriz."},{"n":19,"t":"Onunla size, içlerinde sizin için birçok meyvalar bulunan hurma ve üzüm bahçeleri yetiştirdik, onlardan yiyorsunuz."},{"n":20,"t":"Yine onunla Tûr-i Sinâ’dan çıkan, (meyvası) yağlı olarak biten, yiyenlerin (yağına ekmeklerini) batıracakları bir (zeytin) ağac(ı) yetiştirdik."},{"n":21,"t":"Hayvanlarda da sizin için ibret vardır: Karınlarının içindekinden size içiriyoruz. Onlarda sizin için daha birçok faydalar var, aynı zamanda onlardan yersiniz."},{"n":22,"t":"O (hayva)nların üzerinde ve gemiler üzerinde taşınırsınız."},{"n":23,"t":"Andolsun biz, Nûh’u kavmine gönderdik: \"Ey kavmim, dedi, Allah’a kulluk edin, sizin O’ndan başka tanrınız yoktur, korunmaz mısınız?\""},{"n":24,"t":"Kavminin içinden ileri gelen inkârcı bir grup (şöyle) dedi: \"Bu da sizin gibi bir insandan başka bir şey değildir. Size üstün gelmek istiyor. Eğer Allâh (elçi göndermek) dileseydi, melekleri indirirdi. Biz ilk babalarımızdan böyle bir şey işitmedik.\""},{"n":25,"t":"\"O, kendisinde delilik bulunan bir adamdır, başka bir şey değildir. Hele bir süreye kadar onu gözetleyin."},{"n":26,"t":"(Nûh): \"Rabbim, beni yalanlamaları karşısında bana yardım et (bana verdiğin sözü yerine getir)!\" dedi."},{"n":27,"t":"Biz de ona vahyettik ki: \"Gözlerimizin önünde ve vahyimiz(öğretimimiz)le o gemiyi yap. Bizim buyruğumuz gelip de tandır kaynayınca her cinsten iki çift ve âileni de alıp ona sok. Yalnız onlar içinde alehylerine söz geçmiş (azâbımıza uğrama hükmü giymiş) olanları bırak. O zulmedenler hakkında bana yalvarma; onlar, mutlaka boğulacaklardır!"},{"n":28,"t":"Sen ve yanında bulunanlar gemiye yerleştiğiniz zaman: \"Bizi o zâlim kavimden kurtaran Allah’a hamdolsun.\" de."},{"n":29,"t":"Ve de ki: \"Rabbim, beni mübârek bir inişle indir; sen konuklayanların en hayırlısısın.\""},{"n":30,"t":"Gerçi biz, (onları) sınıyorduk ama, bu olayda (sizler için de) nice ibretler vardır."},{"n":31,"t":"Sonra onların ardından başka bir nesil yetiştirdik."},{"n":32,"t":"Onlara da kendi içlerinden: \"Allah’a kulluk edin, sizin O’ndan başka Tanrınız yoktur, (Allâh’ın azâbından) korunmaz mısınız?\" diyen bir elçi gönderdik."},{"n":33,"t":"Kavminden, kendilerine dünyâ hayâtında bol ni’met verdiğimiz o inkâr eden ve âhiret buluşmasını (hesap ve cezâsını) yalanlayan eşraf takımı dedi ki: \"Bu da sizin gibi bir insandan başka bir şey değildir. Sizin yediğinizden yiyor, içtiğinizden içiyor.\""},{"n":34,"t":"\"Eğer sizin gibi bir insana itâ’at ederseniz o takdirde siz, mutlaka ziyana uğrayanlarsınız demektir.\""},{"n":35,"t":"\"O size, siz öldüğünüz, toprak ve kemik haline geldiğiniz zaman yeniden hayâta çıkarılacağınızı mı va’dediyor?\""},{"n":36,"t":"\"Heyhât, o size va’dedilen şey ne kadar uzak!\""},{"n":37,"t":"\"Ne ise hep bu dünyâ hayâtımızdır; ölürüz ve yaşarız, biz öldükten sonra diriltilecek değiliz.\""},{"n":38,"t":"\"O, Allah’a yalan uydurandan başka bir adam değildir. Biz ona inanıcı(insan)lar değiliz.\""},{"n":39,"t":"(O peygamber): \"Rabbim, dedi, beni yalanlamaları karşısında bana yardım et.\""},{"n":40,"t":"(Allâh): \"Az sonra onlar pişman olacaklar!\" dedi."},{"n":41,"t":"Derken o korkunç ses, onları gerçekten yakaladı da onları sel süprüntüsü haline getirdik. Uzak olsun o zâlim kavim!."},{"n":42,"t":"Sonra onların ardından başka nesiller yetiştirdik."},{"n":43,"t":"Hiçbir ümmet, ne süresinden ileri geçebilir, ne de geri kalabilir."},{"n":44,"t":"Sonra biz, elçilerimizi ardı ardına gönderdik. Hangi ümmete elçisi geldiyse onlar onu yalanladılar, biz de onları birbiri ardınca devirdik ve hepsini birer efsâne yaptık. İnanmayan toplum uzak olsun."},{"n":45,"t":"Sonra Mûsâ’yı ve kardeşi Hârûn’u âyetlerimizle ve apaçık bir delille gönderdik;"},{"n":46,"t":"Fir’avn’e ve ileri gelen adamlarına. Onlar büyüklük tasladılar ve böbürlenen bir topluluk oldular."},{"n":47,"t":"\"Şu iki adamın kavmi bize kölelik ederken, şimdi biz kalkıp bizim gibi iki insana mı inanacağız?\" dediler."},{"n":48,"t":"Onları yalanladılar ve helâk edilenlerden oldular."},{"n":49,"t":"(Sonra Mûsâ, İsrâil oğullarını Mısır’dan çıkardı. İsrâil oğulları) Doğru yolu bulsunlar diye biz, Mûsâ’ya Kitabı (Tevrât’ı) verdik."},{"n":50,"t":"Meryem oğlunu ve annesini bir mu’cize kıldık ve onları oturmaya uygun, çeşmeli bir tepeye yerleştirdik."},{"n":51,"t":"\"Ey elçiler, güzel şeylerden yeyin ve yararlı iş yapın. Çünkü ben yaptıklarınızı bilmekteyim.\""},{"n":52,"t":"\"Ve işte sizin bu ümmetiniz bir tek ümmettir, ben de sizin Rabbinizim, benden korkun.\" (dedik)."},{"n":53,"t":"Fakat işlerini aralarında parçalayıp, çeşitli kitaplara ayırdılar. Her parti, kendi yanında bulunanla sevinmektedir."},{"n":54,"t":"Bir süreye kadar onları, (daldıkları) gafletleri içinde bırak."},{"n":55,"t":"Onlar sanıyorlar mı ki kendilerine verdiğimiz mal ve oğullar ile,"},{"n":56,"t":"Onların iyiliklerine koşuyoruz? Hayır, (bu verdiğimiz dünyâ ni’metleri, onlar için bir imtihandır, fakat onlar) farkında değiller."},{"n":57,"t":"Onlar ki Rablerine saygıdan titrerler."},{"n":58,"t":"Ve onlar ki Rablerinin âyetlerine inanırlar."},{"n":59,"t":"Ve onlar ki Rablerine ortak koşmazlar."},{"n":60,"t":"Verdiklerini, Rablerinin huzûruna dönecekleri düşüncesiyle kalbleri korkudan ürpererek verirler."},{"n":61,"t":"İşte onlar, hayır işlerine koşarlar ve onlar hayır için önde giderler."},{"n":62,"t":"Biz, hiç kimseye gücünün üstünde bir şey teklif etmeyiz. Katımızda gerçeği söyleyen bir Kitap vardır. (Herkesin eylemleri onda tesbit edilmiştir), onlara asla haksızlık edilmez."},{"n":63,"t":"Fakat onların kalbleri, bundan gaflet içindedir. Onların bundan başka (birtakım pis) işleri daha var ki, onlar hep o işler için çalışırlar."},{"n":64,"t":"Nihâyet varlıklılarını azâb ile yakaladığımız zaman, hemen feryâda başlarlar."},{"n":65,"t":"\"Bugün artık feryâd etmeyin, bize karşı size yardım olunmaz (kimse sizi bizim azâbımızdan kurtaramaz)."},{"n":66,"t":"\"Âyetlerim size okunuyordu da siz arkanıza dönüyordunuz."},{"n":67,"t":"\"Âyetlerime karşı kibirlenerek geceleyin (Ka’be’nin çevresinde toplanıp) saçmalıyordunuz.\""},{"n":68,"t":"Onlar o sözü (Kur’ân’ı) iyice düşünmediler mi, yoksa onlara, ilk atalarına gelmeyen bir şey (bir elçi ve Kitap) geldi diye mi (böyle davranıyorlar)?"},{"n":69,"t":"Yoksa elçilerini tanımadıkları (onun doğruluğunu, dürüstlüğünü bilmedikleri) için mi onu inkâr ediyorlar?"},{"n":70,"t":"Yoksa \"Onda bir delilik var\" mı diyorlar? Hayır, o kendilerine hakkı getirdi, fakat çokları haktan hoşlanmıyorlar."},{"n":71,"t":"Eğer hak, onların keyiflerine uysaydı, gökler, yer ve bunların içinde bulunan kimseler bozulur, giderdi. Biz onlara Zikir’lerini getirdik fakat onlar, Zikirlerinden yüz çeviriyorlar."},{"n":72,"t":"Yoksa sen onlardan bir vergi mi istiyorsun (da onun için mi hakkı kabul etmiyorlar)? Rabbinin vergisi daha hayırlıdır. O, rızık verenlerin en iyisidir."},{"n":73,"t":"Sen onları doğru bir yola çağırıyorsun."},{"n":74,"t":"Ama âhirete inanmayanlar yoldan sapıyorlar."},{"n":75,"t":"Biz onlara acıyıp da başlarındaki sıkıntıyı açsaydık, yine azgınlıklarında bocalamağa devam ederlerdi."},{"n":76,"t":"Andolsun biz onları azâb ile yakaladık, ama yine Rabblerine boyun eğmediler, O’na yalvarmıyorlar."},{"n":77,"t":"Nihâyet üzerlerine şiddetli bir azâb kapısı açtığımız zaman, derhal O’nun içinde şaşkın ve umutsuz kalırlar."},{"n":78,"t":"O’dur ki, sizin için o kulağı, o gözleri ve gönülleri inşâ etti. Ne kadar az şükrediyorsunuz!"},{"n":79,"t":"O’dur ki, sizi yeryüzünde yaratıp yaydı ve O’na götürüleceksiniz."},{"n":80,"t":"O’dur ki yaşatıyor, öldürüyor. Gecenin ve gündüzün değişmesi O’nun (eseri)dir. Aklınızı kullanmıyor musunuz?"},{"n":81,"t":"Hayır, onlar da evvelkilerin dedikleri gibi dediler:"},{"n":82,"t":"\"Öldüğümüz, toprak ve kemik haline geldiğimiz zaman mı, biz mi diriltileceğiz?\" dediler."},{"n":83,"t":"\"Andolsun bu tehdid bize de bizden önce atalarımıza da yapıldı. Bu, evvelkilerin masallarından başka bir şey değildir.\""},{"n":84,"t":"De ki: \"Biliyorsanız dünyâ ve içinde bulunanlar kimindir?\""},{"n":85,"t":"\"Allâh’ındır\" diyecekler. \"O halde düşün(üp, ilk kez yaratanın, ikinci defa yine yaratılabileceğini anla)mıyor musunuz?\" de."},{"n":86,"t":"\"Yedi göğün Rabbi ve büyük Arş’ın Rabbi kimdir?\" de."},{"n":87,"t":"\"Bunlar Allâh’ındır\" diyecekler. \"O halde korunmuyor musunuz?\" de."},{"n":88,"t":"\"Biliyorsanız (söyleyin) her şeyin melekûtu (mülkü ve yönetimi) elinde olan, koruyup kollayan, fakat kendisi korunup kollan(maya muhtaç ol)mayan kimdir?\" de."},{"n":89,"t":"\"(Her şeyin yönetimi) Allah’a âittir\" diyecekler. \"O halde nasıl büyüleniyorsunuz?\" de."},{"n":90,"t":"Doğrusu biz, onlara hakkı getirdik, (bizim söylediklerimiz gerçektir), onlarsa yalancıdırlar."},{"n":91,"t":"Allâh çocuk edinmemiştir. O’nunla beraber hiçbir tanrı yoktur. Öyle olsaydı her tanrı, kendi yarattığını götürürdü ve onlardan biri diğerine üstün gelmeğe çalışırdı. Allâh, onların tanımlamalarından uzaktır."},{"n":92,"t":"(O), görünmeyeni ve görüneni bilir; onların ortak koştukları şeylerden yücedir."},{"n":93,"t":"De ki: \"Rabbim, eğer onların tehdid edildikleri şeyi mutlaka bana göstereceksen (ben sağ iken onları cezâlandıracaksan),\""},{"n":94,"t":"\"Rabbim, beni şu zâlim kavmin içinde bırakma!\""},{"n":95,"t":"Biz, onları tehdid ettiğimiz şeyi sana göstermeğe elbette kâdiriz (onları cezâlandıracağız ve sen bunu göreceksin)."},{"n":96,"t":"Kötülüğü en güzel şeyle sav. Biz onların (seni) nasıl vasıflandıracaklarını biliyoruz."},{"n":97,"t":"Ve de ki: \"Rabbim, şeytânların dürtüklemelerinden sana sığınırım.\""},{"n":98,"t":"\"Ve onların yanıma uğramalarından sana sığınırım Rabbim.\""},{"n":99,"t":"Nihâyet onlardan birine ölüm geldiği zaman: \"Rabbim, der, beni geri döndürünüz!\""},{"n":100,"t":"\"Ki terk ettiğim dünyâda yararlı bir iş yapayım.\" Hayır, bu onun söylediği bir sözdür. Önlerinde tâ diriltilecekleri güne kadar bir berzah vardır."},{"n":101,"t":"Sûr’a üflendiği zaman, artık o gün aralarında soylar yoktur ve (insanlar, birbirlerine soylarını) sormazlar."},{"n":102,"t":"Kimlerin (eylemlerinin) tartıları ağır gelirse, işte onlar kurtuluşa erenlerdir."},{"n":103,"t":"Kimlerin tartıları hafif gelirse, işte onlar da kendilerini ziyana sokanlar, cehennemde sürekli kalanlardır."},{"n":104,"t":"(Orada onların) yüzlerini ateş yalar. Öyle ki (ateşin) içinde (dehşetten dudakları gerilir de) dişleri açıkta kalır."},{"n":105,"t":"\"Âyetlerim size okunurdu da siz onları yalanlardınız değil mi?\""},{"n":106,"t":"\"Rabbimiz, dediler, bahtsızlığımız bizi yendi. Biz sapık bir topluluk olduk.\""},{"n":107,"t":"\"Rabbimiz, bizi bundan çıkar. Eğer bir daha (yaptığımız kötü işlere) dönersek artık biz gerçekten zâlimleriz.\""},{"n":108,"t":"Buyurdu ki: \"Sinin orada, bana bir şey söylemeyin!\""},{"n":109,"t":"\"Zira kullarımdan bir zümre: ’Rabbimiz inandık, bizi bağışla, bize acı, sen acıyanların en hayırlısısın’ dedikleri için\""},{"n":110,"t":"\"Siz onlarla alay ettiniz, (sürekli onlarla uğraştığınız için onlar) size beni anmayı unutturdular. Siz dâimâ onlara gülüyordunuz.\""},{"n":111,"t":"\"Bugün ben, onlara sabretmelerinin karşılığını verdim; onlar (evet) işte kurtulup murâda erenler onlardır.\""},{"n":112,"t":"Ve buyurdu: \"Yeryüzünde yıllar sayısınca ne kadar kaldınız?\""},{"n":113,"t":"\"(Herhalde) Bir gün, yahut günün bir kısmı kadar kaldık; sayanlara sor\", dediler."},{"n":114,"t":"Buyurdu ki: \"Sadece az bir zaman kaldınız, keşke bilseydiniz!\""},{"n":115,"t":"\"Bizim sizi boş yere, bir oyun ve eğlence olarak yarattığımızı ve sizin bize döndürülüp getirilmeyeceğinizi mi sandınız?\""},{"n":116,"t":"Hak pâdişah olan Allâh, pek yücedir. O’ndan başka tanrı yoktur. O, Kerim Arş’ın sâhibidir."},{"n":117,"t":"Kim Allâh ile beraber, varlığını kanıtlayacak hiçbir delil bulunmayan bir tanrıya taparsa, onun hesabı, Rabbinin yanındadır (onu Allâh cezâlandırır) çünkü kâfirler iflâh olmazlar."},{"n":118,"t":"De ki: \"Rabbim, bağışla, acı, sen acıyanların en hayırlısısın.\""}],[{"n":1,"t":"Bu indirdiğimiz ve uygulanmasını farz kıldığımız bir sûredir. Düşünüp öğüt almanız için onda açık açık âyetler indirdik."},{"n":2,"t":"Zinâ eden kadın ve zinâ eden erkeğin her birine yüz değnek vurun; Allah’a ve âhiret gününe inananlar iseniz Allâh’ın cezâsını uygulamada sizi, onlara karşı acıma duygusu tut(up engelle)mesin. Mü’minlerden bir grup da onlara yapılan azâba şâhid olsun."},{"n":3,"t":"Zinâ eden erkek, zinâ eden veya ortak koşan kadından başkasıyla evlenmez; zinâ eden kadın da zinâ eden veya ortak koşan erkekten başkasıyla evlenmez. Böyleleriyle evlenmek mü’minlere harâm kılınmıştır."},{"n":4,"t":"Namuslu kadınları zinâ ile suçlayıp da sonra (bu suçlamalarını ispat için) dört şâhid getirmeyenlere seksen değnek vurun ve artık onların şâhidliğini asla kabul etmeyin. Onlar yoldan çıkmış kimselerdir."},{"n":5,"t":"Ancak bundan sonra tevbe edip uslananlar hariç. Çünkü Allâh çok bağışlayan, çok esirgeyendir."},{"n":6,"t":"Eşlerini zinâ ile suçlayıp kendilerinden başka şâhidleri bulunmayan kimselere gelince: Onlardan her birinin şâhidliği, kendisinin mutlaka doğru söyleyenlerden olduğuna, dört defa Allâh’ı şâhid tutmasıdır."},{"n":7,"t":"Beşinci defa da: Eğer yalan söyleyenlerden ise Allâh’ın la’netinin kendi üzerine olmasını diler."},{"n":8,"t":"Kadının da dört defa sözüne Allâh’ı şâhid tutup kocasının, mutlaka yalan söyleyenlerden olduğuna şâhidlik etmesi, kendisinden azâbı kaldırır."},{"n":9,"t":"Beşinci defa da: Eğer kocası doğrulardan ise Allâh’ın gazabının kendi üzerine olmasını diler."},{"n":10,"t":"Ya Allâh’ın size lutfu ve rahmeti olmasaydı ve Allâh, tevbeleri çok kabul eden ve hikmet sâhibi olmasaydı (ne yapardınız)?"},{"n":11,"t":"O yalan haberi getir(ip ortaya at) anlar, içinizden bir topluluktur. Siz, onu sizin için şer sanmayın. Tersine o, sizin için hayırdır. Onlardan her kişi işlediği günâh’ın cezâsını görecektir. Onlardan o(yala)nın en büyüğünü idâre edene de büyük bir azâb vardır."},{"n":12,"t":"Onu işittiğiniz zaman inanan erkek ve kadınların, kendiliklerinden güzel zanda bulunup: \"Bu, apaçık bir iftirâdır\" demeleri gerekmez miydi?"},{"n":13,"t":"Ona dört şâhid getirmeleri gerekmez miydi? Mâdem ki şâhidleri getirmediler, o halde onlar Allâh yanında yalancıların tâ kendileridir."},{"n":14,"t":"Eğer size dünyâda ve âhirette Allâh’ın lutfu ve rahmeti olmasaydı, içine daldığınız yaygarada size mutlaka büyük bir azâb dokunurdu."},{"n":15,"t":"Çünkü siz, onu dillerinizle alıveriyorsunuz ve hakkında hiç bilginiz olmayan bir şeyi, (düşünüp taşınmadan, hemen) ağızlarınızla söylüyorsunuz ve onu önemsiz bir iş sanıyorsunuz. Oysa o, Allâh yanında büyük(bir günâh)tır."},{"n":16,"t":"Onu işittiğiniz zaman, \"Bunu konuşmamız bize yakışmaz, hâşâ, bu, büyük bir iftirâdır.\" demeniz gerekmez miydi?"},{"n":17,"t":"Allâh size öğüt veriyor ki eğer inananlar iseniz böyle bir şeye bir daha asla dönmeyesiniz."},{"n":18,"t":"Allâh size âyetleri(ni) açıklıyor. Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":19,"t":"İnananlar içinde edepsizliğin yayılmasını isteyenler için dünyâda da, âhirette de acı bir azâb vardır. Allâh bilir, siz bilmezsiniz."},{"n":20,"t":"Eğer size Allâh’ın lutfu ve rahmeti olmasaydı ve Allâh çok şefkatli ve merhametli olmasaydı (bu iftirânızdan dolayı büyük bir azâba uğrardınız)!"},{"n":21,"t":"Ey inananlar, şeytânın adımlarını izlemeyin. Kim şeytânın adımlarını izlerse o, ona edepsizliği ve kötülüğü emreder. Eğer size, lutfu ve rahmeti olmasaydı Allâh, hiçbirinizi asla temizlemezdi. Fakat Allâh dilediğini arındırır. Allâh işitendir, bilendir."},{"n":22,"t":"Sizden fazilet ve servet sâhibi kimseler, yakınlığı bulunanlara, yoksullara, Allâh yolunda göç edenlere bir şey vermemeğe yemin etmesinler, affetsinler, hoşgörsünler. Allâh’ın sizi bağışlamasını sevmez misiniz? Allâh bağışlayandır, esirgeyendir."},{"n":23,"t":"O namuslu, bir şeyden habersiz, inanmış kadınlara zinâ iftirâ edenler, dünyâ’da da âhirette de la’netlenmişlerdir. Onlar için büyük bir azâb vardır."},{"n":24,"t":"O gün, dilleri, elleri ve ayakları yaptıklarına şâhidlik edecektir."},{"n":25,"t":"O gün Allâh, onlara hak ettikleri cezâlarını tam verir ve onlar da bilirler ki Allâh, apaçık Hak’tır."},{"n":26,"t":"Kötü kadınlar, kötü erkeklere; kötü erkekler kötü kadınlara; iyi kadınlar iyi erkeklere; iyi erkekler de iyi kadınlara mahsustur. Bunlar onların söyledikleri (çirkin şeyler)den uzaktırlar. Bunlara, (Allâh tarafından) bağışlama ve cömertçe bir rızık vardır."},{"n":27,"t":"Ey inananlar, kendi evlerinizden başka evlere, izin alıp halkına selâm vermeden girmeyin. Herhalde bunun, sizin için daha iyi olduğunu düşünüp anlarsınız."},{"n":28,"t":"Eğer orada kimseyi bulamazsanız, size izin verilinceye kadar oraya girmeyin. Ve eğer size: \"Dönün\" denirse dönün. Bu, sizin için daha temizdir. Allâh yaptıklarınızı bilendir."},{"n":29,"t":"Oturulmayan ve içinde eşyanız bulunan evlere (izinsiz) girmenizden dolayı size bir günâh yoktur. Allâh, açığa vurduğunuzu da, gizlediğinizi de bilir."},{"n":30,"t":"İnanan erkeklere söyle: \"Bazı bakışlarını kıssınlar, ırzlarını korusunlar. Bu, onlar için daha temizdir. Şüphesiz Allâh, onların her yaptıklarını haber almaktadır."},{"n":31,"t":"İnanan kadınlara da söyle: \"Bazı bakışlarını kıssınlar, ırzlarını korusunlar. Süslerini göstermesinler. Ancak kendiliğinden görünenler hariç. Baş örtülerini (göğüs) yırtmaçlarının üstüne koysunlar. Süslerini kimseye göstermesinler. Yalnız kocalarına, yahut babalarına, yahut kocalarının babalarına, yahut oğullarına, yahut kocalarının oğullarına, yahut kardeşlerine, yahut kardeşlerinin oğullarına, yahut kızkardeşlerinin oğullarına, yahut kadınlarına, yahut ellerinin altında bulunan(köle)lerine, yahut kadına ihtiyacı bulunmayan erkek tâbi’lerine, yahut henüz kadınların mahrem yerlerini anlamayan çocuklara gösterebilir. Gizledikleri süslerin bilinmesi için ayaklarını vurmasınlar. Ey mü’minler, topluca Allah’a tevbe edin ki felâha eresiniz."},{"n":32,"t":"İçinizden bekârları ve köle ve câriyelerinizden iyileri evlendirin. Eğer yoksul iseler, Allâh, lutfiyle onları zengin eder. Allâh(ın mülkü) geniştir, O, (her şeyi) bilendir."},{"n":33,"t":"Evlenme (imkânı) bulamayanlar, Allâh kendilerini lutfundan zengin edinceye kadar iffetlerini korusunlar. Ellerinizin altında bulunan (köle ve câriye)lerden, mükâtebe (akdi) yapmak isteyenlerle -eğer kendilerinde hayır görürseniz- mükâtebe yapın ve Allâh’ın size verdiği malından onlara da verin. Dünyâ hayâtının geçici menfaatini elde etmek için, namuslu kalmak isteyen câriyelerinizi fuhşa zorlamayın. Kim onları (fuhşa) zorlarsa, şüphesiz Allâh (fuhşa) zorlanmalarından sonra (o kadınlara karşı) bağışlayıcı, esirgeyicidir."},{"n":34,"t":"Andolsun ki size, açıklayıcı âyetler ve sizden önce gelip geçenlerden bir temsil ve korunanlar için bir öğüt indirdik."},{"n":35,"t":"Allâh, göklerin ve yerin nurudur. O’nun nuru, içinde lamba bulunan bir kandile benzer. Lamba cam içerisindedir. Cam, sanki inciden bir yıldız. Ne doğuya ve ne batıya mensub olmayan mübârek bir zeytin ağacı(nın yağı)ndan yakılır. (Öyle mübârek bir ağaç) Ki, neredeyse ateş değmese de yağı ışık verir. Işığı parıl, parıldır. Allâh, dilediği kimseyi nuruna iletir. Allâh insanlara misaller verir. Allâh her şeyi bilir."},{"n":36,"t":"(Bu kandil) Allâh’ın yükseltilmesine ve içlerinde adının anılmasına izin verdiği evlerdedir. Onların içinde sabah akşam O’nu tesbih eder(şânının yüceliğini anar)lar:"},{"n":37,"t":"Kendilerini ne ticaretin, ne de alışverişin Allâh’ı anmaktan, namaz kılmaktan, zekât vermekten alıkoymadığı erkekler. (Onlar), yüreklerin ve gözlerin (dehşetten) ters döneceği günden korkarlar."},{"n":38,"t":"Ki Allâh onlara yaptıklarının en güzel karşılığını versin ve lutfundan onlara daha fazlasını da ihsan etsin. Allâh dilediğini hesapsız rızıklandırır."},{"n":39,"t":"İnkâr edenler(e gelince): Onların işleri, düz arazideki serap gibidir. Susayan onu su sanır, fakat yanına gelince hiçbir şey olmadığını anlar ve yanında Allâh’ı bulur; Allâh onun hesabını tam görür, O, hesabı çabuk görendir."},{"n":40,"t":"Yahut (Onların işleri) engin bir denizdeki karanlıklar gibidir: (Bir deniz) Ki üstünü bir dalga, örtüyor, onun üstünden bir dalga onun üstünden de bir bulut (örtmektedir). Birbiri üstüne yığılmış karanlıklar. (İçinde bulunan kimse) Elini çıkarsa neredeyse onu dahi göremez. Allâh bir kimseye nur vermemişse artık onun nuru olmaz."},{"n":41,"t":"Görmedin mi göklerde ve yerde olan kimseler, kanatlarını çırparak uçan kuşlar Allâh’ı tesbih ederler? Her biri kendi du’âsını ve tesbihini bilmiştir. Allâh da onların ne yaptıklarını bilmektedir."},{"n":42,"t":"Göklerin ve yerin mülkü Allâh’ındır. Dönüş de Allah’adır."},{"n":43,"t":"Görmedin mi Allâh bulutları sürer, sonra onları birbirine geçirir, sonra onları birbiri üstüne yığar (sıkıştırır), arasından yağmurun çıktığını görürsün. Gökteki dağlar (gibi büyük bulut parçaların)dan bir dolu indirir de onunla dilediğini vurur, dilediğinden de onu öteye çevirir. Şimşeğinin parıltısı neredeyse gözleri alır."},{"n":44,"t":"Allâh gece ile gündüzü çevirir. Kuşkusuz gözleri olanlar için bunda bir ibret vardır."},{"n":45,"t":"Allâh her canlıyı sudan yarattı; onlardan kimi karnı üzerinde (sürünerek) yürür, kimi iki ayak üstünde yürür, kimi de dört (ayak) üstünde yürür. Allâh dilediğini yaratır. Çünkü Allâh her şeye kâdirdir."},{"n":46,"t":"Andolsun biz, (gerçekleri) açıklayan âyetler indirdik. Allâh dilediğini, doğru yola iletir."},{"n":47,"t":"\"Allah’a ve Elçiye inandık ve itâ’at ettik,\" diyorlar. Sonra onlardan bir grup, bunun ardından dönüyor. Bunlar inanmış değillerdir."},{"n":48,"t":"Elçinin, aralarında hükmetmesi için Allah’a ve Elçisine çağırıldıkları zaman hemen onlardan bir grup yüz çevirirler."},{"n":49,"t":"Eğer hüküm kendi lehlerine olursa itâ’at ederek, gelirler."},{"n":50,"t":"Kalblerinde bir hastalık mı var, yoksa şüphe mi ettiler? Yoksa Allâh’ın ve Elçisinin kendilerine haksızlık yapacağından mı korkuyorlar? Hayır, onlar zâlimlerdir."},{"n":51,"t":"Elçinin, aralarında hükmetmesi için Allah’a ve Elçisine çağırıldıkları zaman inananların sözü ancak: \"İşittik ve itâ’at ettik\" demeleridir. İşte umduklarına erenler bunlardır, bunlar."},{"n":52,"t":"Kim(ler) Allah’a ve Resulüne itâ’at eder, Allah’tan korkar, O’(nun azâbı)ndan korunursa işte kurtuluşa erenler onlardır."},{"n":53,"t":"Yeminlerinin var gücüyle Allah’a yemin ettiler: Eğer sen onlara emredersen (savaşa) çıkacaklar diye. De ki: \"Yemin etmeyin. (Sizden istenen, yalan yere yemin etmek değil), güzel itâ’at etmektir. Şüphesiz Allâh, yaptıklarınızı haber almaktadır\"."},{"n":54,"t":"De ki: \"Allah’a itâ’at edin, Elçiye itâ’at edin.\" Eğer dönerseniz, ona gereken, kendisine yükletilen (duyurma görevini yapmak), size gereken de size yükletilen (itâ’at görevini yapmak)dır. Eğer ona itâ’at ederseniz, doğru yolu bulursunuz. Elçiye düşen, sadece açık bir şekilde duyurmaktır."},{"n":55,"t":"Allâh sizden, inanıp iyi işler yapanlara va’detmiştir: Onlardan öncekileri nasıl hükümran kıldıysa, onları da yer yüzünde hükümran kılacak ve kendileri için seçip beğendiği dinlerini kendilerine sağlamlaştıracak ve korkularının ardından kendilerini (tam) bir güvene erdirecektir. Bana kulluk edecekler ve bana hiçbir şeyi ortak koşmayacaklar. Ama kim(ler) bundan sonra da nankörlük ederse işte onlar, yoldan çıkanlardır."},{"n":56,"t":"Namazı kılın, zekâtı verin, Elçiye itâ’at edin ki size acınsın."},{"n":57,"t":"Nankörlerin, yer yüzünde (Allâh’ı) âciz bırakacaklarını, (Allâh’ın azâbına engel olacaklarını) sanma. Onların varacağı yer ateştir. Ne kötü bir gidiş yeridir o!"},{"n":58,"t":"Ey inananlar, ellerinizin altında bulunan (köle ve hizmetçi)ler ve henüz erginliğe ermemiş çocuklarınız üç vakitte (odalarınıza girebilmek için) izin istesinler: Sabah namazından önce, öğle vakti elbisenizi çıkar(ıp yat)acağınız zaman ve yatsı namazından sonra. Bunlar sizin üstünüzün açılabileceği üç vakittir. Bunların dışında (hizmetçilerin ve çocukların, izin almadan içeri girmelerinden dolayı) ne size, ne de onlara bir günâh yoktur. (Onlar sizin) yanınızda dolaşırlar, birbirinizin yanına girip çıkarsınız. Allâh âyetleri size böyle açıklar. Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":59,"t":"Çocuklarınız erginlik çağına erdikleri zaman kendilerinden öncekilerin izin istedikleri gibi izin istesinler. İşte Allâh size âyetlerini böyle açıklıyor. Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":60,"t":"Evlenme arzusu kalmamış, oturan (ihtiyar) kadınların, kasden süs göstermeğe çalışmadan, dış örtülerini bırakmalarında kendileri için bir günâh yoktur. Ama sakınmaları, kendileri için daha hayırlıdır. Allâh işitendir, bilendir."},{"n":61,"t":"Köre güçlük yoktur, topala güçlük yoktur, hastaya güçlük yoktur. Size de kendi evlerinizden, yahut babalarınızın evlerinden, yahut annelerinizin evlerinden, yahut kardeşlerinizin evlerinden, yahut kızkardeşlerinizin evlerinden, yahut amcalarınızın evlerinden, yahut halalarınızın evlerinden, yahut dayılarınızın evlerinden, yahut teyzelerinizin evlerinden, yahut anahtarları ellerinizde bulunan evlerden, yahut arkadaşınızın evlerinden yemenizde bir güçlük yoktur. Toplu olarak yahut ayrı ayrı yemenizde de üzerinize bir günâh yoktur. Evlere girdiğiniz zaman Allâh tarafından kutlu, güzel bir yaşama dileği olarak kendinize (kendinizden olan ev halkına) selâm verin. İşte Allâh, âyetleri size böyle açıklıyor ki düşünüp anlayasınız."},{"n":62,"t":"Mü’minler o kimselerdir ki Allah’a ve Elçisine (gönülden) inanmışlardır. Toplumsal bir iş için Allâh’ın Elçisi ile beraber bulundukları zaman ondan izin almadan gitmezler. (Ey Muhammed), Senden izin alanlar, işte Allah’a ve Elçisine inananlar onlardır. Bazı işleri için senden izin istedikleri zaman onlardan dilediğine izin ver ve onlar için Allah’tan mağfiret dile. Şüphesiz Allâh çok bağışlayan, çok esirgeyendir."},{"n":63,"t":"Elçinin çağırmasını, aranızda herhangi birinizin diğerini çağırmasıyla bir tutmayın. Allâh içinizden, birbirinin arkasına gizlenerek sıvışıp gidenleri bilir. Elçinin emrine aykırı davrananlar, kendilerine bir belânın çarpmasından, yahut onlara acı bir azâbın uğramasından sakınsınlar."},{"n":64,"t":"İyi bilinki göklerde ve yerde olanlar hep Allâh’ındır. O, sizin ne iş üzerinde bulunduğunuzu, (ne yaptığınızı, içinizde nasıl bir niyet taşıdığınızı) bilir. O’na döndürülüp götürüldükleri gün, ne yaptıklarını onlara haber verir. Allâh, her şeyi bilendir."}],[{"n":1,"t":"Âlemlere uyarıcı olması için kuluna Furkanı (hakkı bâtıldan ayırma ölçüsünü) indiren (Allâh) pek kutludur!"},{"n":2,"t":"Göklerin ve yerin mülkü O’nundur, O, bir çocuk edinmemiştir, mülkünde ortağı yoktur. Her şeyi yaratmış, ona ölçü, biçim ve düzen vermiştir."},{"n":3,"t":"O’ndan ayrı olarak, hiçbir şey yaratmayan, kendileri yaratılan ve kendilerine dahi ne zarar ne de yarar veremeyen; öldüremeyen, yaşatamayan, (ölüleri diriltip) kaldıramayan birtakım tanrılar edindiler."},{"n":4,"t":"İnkâr edenler: \"Bu, yalandan başka bir şey değildir. (Muhammed) onu uydurdu, başka bir topluluk da kendisine yardım etti.\" dediler ve kesin bir haksızlığa ve iftirâya vardılar."},{"n":5,"t":"Dediler: \"Evvelkilerin masalları, onları yazmış, sabah akşam onlar kendisine yazdırılıyor.\""},{"n":6,"t":"De ki: \"Onu, göklerdeki ve yerdeki gizleri bilen indirdi. O, çok bağışlayan, çok esirgeyendir."},{"n":7,"t":"Dediler: \"Bu elçiye ne oluyor ki yemek yiyor, çarşılarda geziyor? Ona kendisiyle beraber uyarıcı olacak bir melek indirilmeli değil mi?\""},{"n":8,"t":"\"Yahut üstüne bir hazine atılmalı, yahut kendisinin ürününden yiyeceği bir bahçesi olmalı değil mi?\" Ve zâlimler: \"Siz başka değil, sadece büyülenmiş bir adama uyuyorsunuz\" dediler."},{"n":9,"t":"Bak, senin için nasıl benzetmeler yaptılar da saptılar. Artık bir daha yolu bulamazlar."},{"n":10,"t":"Yücedir O ki dilerse sana bundan daha hayırlısını, altlarından ırmaklar akan bahçeler verir ve senin için saraylar yapar."},{"n":11,"t":"Onlar (senin hakkında o yakışıksız sözleri söylemekle kalmadılar) bilakis, (Duruşma) sâ’ati(ni) de yalanladılar. Biz (Duruşma) sâ’ati(ni) yalanlayanlara alevli bir ateş hazırlamışızdır."},{"n":12,"t":"(Bu ateş) onları uzak bir yerden görünce onlar bunun öfkesini ve homurtusunu işitirler."},{"n":13,"t":"(Elleri boyunlarına zincirlerle) Bağlı olarak onun dar bir yerine atıldıkları zaman orada ölümü çağırırlar (yetiş ey ölüm, nerdesin, gel bizi bu azâbdan kurtar! derler)."},{"n":14,"t":"\"Bugün bir ölüm çağırmayın, birçok ölüm çağırın.\""},{"n":15,"t":"De ki: \"Bu mu iyi, yoksa korunanlara va’dedilen ebedi cennet mi? O da onların mükâfât ve sonucudur!\""},{"n":16,"t":"Orada istediklerini bulurlar ve sürekli kalırlar. Bu, Rabbinin, istenen, arzu edilen bir va’didir."},{"n":17,"t":"(Rabbin), onları ve Allah’tan başka taptıklarını biraraya toplayacağı gün, (tapılanlara) der ki: \"Bu kullarımı siz mi saptırdınız, yoksa kendileri mi yolu sapıttılar?\""},{"n":18,"t":"Derler ki: \"Senin şânın yücedir, senden başka veliler edinmek bize yaraşmaz. Fakat sen onları ve atalarını ni’met verip yaşattın, (bolluk içinde dünyaya daldılar da seni) anmayı unuttular ve helâki hak eden bir topluluk oldular."},{"n":19,"t":"(Bu kez hitap, bunlara tanrı diye tapanlara yönelir.) İşte (tanrı) dedikleriniz de sizi yalanladılar. Artık ne (azâbı geri) çevirmeğe gücünüz yeter, ne de (kendinize) bir yardım bulabilirsiniz! Sizden kim zulmederse ona büyük bir azâb taddırırız."},{"n":20,"t":"Senden önce gönderdiğimiz bütün elçiler de yemek yerler, çarşılarda gezerlerdi. Biz sizi birbiriniz için bir sınav yaptık. (Sizin bir kısmınızı, diğer bir kısmınızla denemekteyiz ki bakalım) sabrediyor musunuz? Rabbin, (herşeyi) görendir."},{"n":21,"t":"Bizimle karşılaşmayı ummayanlar: \"Bize melekler indirilmeliydi, yahut Rabbimizi görmeliydik değil mi?\" dedi(ler). Andolsun ki onlar kendi içlerinde büyüklük tasladılar ve büyük bir azgınlıkla haddi aştılar."},{"n":22,"t":"Melekleri gördükleri gün, işte o gün suçlulara müjde yoktur ve onlar; (Size sevinmek) yasaktır, yasak!\" derler."},{"n":23,"t":"Yaptıkları her işin önüne geçmişiz de onu (etrafa) saçılmış toz zerreleri haline getirmişizdir."},{"n":24,"t":"O gün cennet halkının kalacakları yer daha iyi, dinlenip safâ sürecekleri yer daha güzeldir."},{"n":25,"t":"Göğün bulutları parçalayıp meleklerin bölük bölük indirildiği gün;"},{"n":26,"t":"İşte o gün, gerçek mülk, Rahmânın’dır, (bütün hükümranlık yalnız O’na âittir) ve o (gün), kâfirler için çetin bir gündür."},{"n":27,"t":"O gün zâlim ellerini ısırıp: \"Nolaydı, keşke ben elçiyle beraber bir yol edineydim!\" der."},{"n":28,"t":"\"Vah bana, ne olurdu, ben falanı dost tutmasaydım!\""},{"n":29,"t":"O beni, bana gelen Zikirden saptırdı. Zaten şeytân, insanı yapayalnız ve yardımcısız bırakır.\""},{"n":30,"t":"Elçi de: \"Ya Rabbi, kavmim, bu Kur’an’ı terk edilmiş bıraktılar\" demiştir."},{"n":31,"t":"Biz böylece her elçiye suçlulardan bir düşman var ettik. Yol gösterici ve yardımcı olarak Rabbin yeter."},{"n":32,"t":"İnkâr edenler: \"Kur’ân, ona bir defada indirilmeli değil miydi?\" dediler. Biz onunla senin kalbini sağlamlaştırmak için onu böyle (parça parça indirdik) ve onu ağır ağır okuduk."},{"n":33,"t":"Onların sana getirdiği her misâle (her bâtıl soruya) karşı mutlaka biz sana, (o bâtılı yok edecek) gerçeği ve en güzel açıklamayı getiririz."},{"n":34,"t":"O yüzükoyun cehenneme toplanacak olanlar, işte onlar, yerce çok kötü ve yolca çok sapıktır."},{"n":35,"t":"Andolsun biz Mûsâ’ya Kitabı verdik ve kardeşi Hârûn’u kendisinin yanında vezir yaptık."},{"n":36,"t":"\"Âyetlerimizi yalanlayan kavme gidin,\" dedik. (Onlara gittiler. Onlar, kendilerine gelen bu elçilerimizi kabul etmeyince biz) de onları yıkıp yok ettik."},{"n":37,"t":"Nûh kavmi de peygamberleri yalanladıkları vakit onları da boğduk ve onları insanlara bir ibret yaptık. Zâlimlere acı bir azâb hazırladık."},{"n":38,"t":"Âd’ı, Semûd’u, Res halkını ve bu arada daha birçok nesilleri (inkârları yüzünden helâk ettik)."},{"n":39,"t":"Hepsine de (uyarmak için) misaller (geçmişlerden hikâyeler) anlattık. (Öğüt almayıp küfürlerinde ısrar edince biz de) hepsini helâk ettik."},{"n":40,"t":"(Şu Kureyş müşrikleri) belâ yağmuruna tutulan, (üstüne taş yağdırılan) kente vardılar. Onun durumunu görmüyorlar mıydı (ki ibret alsınlar)? Hayır, onlar (öldükten sonra) tekrar dirilip kalkmayı ummuyorlar."},{"n":41,"t":"Seni gördükleri zaman, mutlaka seni eğlence konusu yapıyorlar; \"Allâh bunu mu elçi göndermiş?\""},{"n":42,"t":"\"Eğer biz tanrılarımıza tapmakta ısrar etmeseydik, nerdeyse bizi tanrılarımızdan saptıracaktı.\" (diyorlar). Azâbı gördükleri zaman kimin yolunun sapık olduğunu bileceklerdir."},{"n":43,"t":"Arzusunu tanrı edinen kimseyi gördün mü? Onun üstüne sen mi bekçi olacaksın?"},{"n":44,"t":"Yoksa sen onların çoğunun işittiklerini, düşündüklerini mi sanıyorsun? Hayır, onlar hayvanlar gibidir, hattâ onlar, yolca (hayvanlardan) daha sapıktır."},{"n":45,"t":"Rabbini görmedin mi gölgeyi nasıl uzattı? Dileseydi, onu durgun yapardı. Sonra nasıl güneşi ona delil kıldık (gölgenin görünmesini, ışığa bağlı kıldık)?"},{"n":46,"t":"Sonra (güneş yükseldikçe) gölgeyi yavaş yavaş çekip aldık."},{"n":47,"t":"O, geceyi sizin için elbise, uykuyu dinlenme, gündüzü de kalkıp çalışma zamanı yaptı."},{"n":48,"t":"Ve O, rahmetinin önünde rüzgârları müjdeci gönderdi. Ve gökten tertemiz bir su indirdik."},{"n":49,"t":"Ki onunla ölü bir ülkeyi diriltelim ve onunla yarattığımız hayvanlardan ve insanlardan birçoğunu sulayalım."},{"n":50,"t":"Andolsun biz, bu sözü onların aralarında çevirip çevirip anlattık ki öğüt alsınlar. Ama insanların çoğu, nankörlükte direnmektedir."},{"n":51,"t":"Eğer biz dileseydik, her kente bir uyarıcı gönderirdik."},{"n":52,"t":"Kâfirlere boyun eğme ve bu Kur’ân ile onlara karşı büyük cihâd et."},{"n":53,"t":"O, iki denizi birbirine salmıştır. Bu tatlı, susuzluğu giderici; bu tuzlu ve acıdır. Ve ikisinin arasına birbirine kavuşmalarına engel olan bir perde koymuştur (hiç birbirine kavuşmazlar)."},{"n":54,"t":"Ve O, sudan bir insan yarattı da onu nesep ve sıhr kıldı. Rabbin, her şeye gücü yetendir."},{"n":55,"t":"Allah’tan başka kendilerine ne yarar, ne de zarar veremeyecek şeylere tapıyorlar. Kâfir, Rabbine karşı şeylere yardımcıdır."},{"n":56,"t":"Biz seni ancak müjdeleyici ve uyarıcı olarak gönderdik."},{"n":57,"t":"\"Buna karşı sizden bir ücret istemiyorum; ancak Rabbine varan yola girmek isteyene yol gösteriyorum\" de."},{"n":58,"t":"Ve ölmeyen (diriy)e tevekkül et ve O’nu överek tesbih et. Kullarının günâhlarını, O’nun bilmesi yeter."},{"n":59,"t":"O, gökleri, yeri ve ikisinin arasında bulunanları altı günde yarattı, sonra Arş’a kuruldu (böylece mülkünü yönetmektedir. O) Rahmân’dır. Bunu bir bilene sor."},{"n":60,"t":"Onlara: \"Rahmân’a secde edin!\" dendiği zaman: \"Rahmân nedir? Senin bize emrettiğine secde eder miyiz hiç?\" derler. Ve (bu söz), onların nefretini artırır."},{"n":61,"t":"Yücedir O ki, gökte burçlar yaptı ve orada bir kandil ve aydınlatıcı bir ay var etti."},{"n":62,"t":"Ve O, öğüt almak veya şükretmek isteyenler için gece ile gündüzü, birbirini izler yaptı."},{"n":63,"t":"Rahmân’ın kulları öyle kimselerdir ki, yeryüzünde mütevâzi olarak yürürler, câhiller kendilerine laf atarsa \"Selâm\" derler."},{"n":64,"t":"Gecelerini Rablerine secde ederek, Onun divânında durarak geçirirler:"},{"n":65,"t":"\"Rabbimiz, cehennemin azâbını bizden uzaklaştır, doğrusu onun azâbı sargındır\" derler."},{"n":66,"t":"\"Orası ne kötü bir karargâh ve ne kötü bir makâmdır!\""},{"n":67,"t":"Ve harcadıkları zaman, ne israf ederler ne de cimrilik ederler; harcamaları, bu ikisinin arasında dengeli olur."},{"n":68,"t":"Ve onlar Allâh ile beraber başka tanrıya yalvarmazlar. Allâh’ın harâm ettiği canı haksız yere öldürmezler ve zinâ etmezler. Kim bunları yaparsa cezâsını bulur."},{"n":69,"t":"Kıyâmet günü onun için azâb kat kat yapılır ve o azâb’ın içinde hor ve hakir olarak kalır."},{"n":70,"t":"Ancak tevbe edip inanan ve faydalı bir iş yapanlar, işte Allâh onların kötülüklerini iyiliklere değiştirecektir. Allâh çok bağışlayandır, çok esirgeyendir."},{"n":71,"t":"Kim tevbe eder ve faydalı iş yaparsa o, makbul bir kimse olarak Allah’a döner."},{"n":72,"t":"Onlar yalan ve boş sözün yanında bulunmazlar, boş söze rastladıklarında vekar ile (oradan) geçip giderler."},{"n":73,"t":"Ve kendilerine Rablerinin âyetleri hatırlatıldığı zaman onlara karşı sağır ve kör davranmazlar."},{"n":74,"t":"Ve: \"Rabbimiz, bize gözler sevinci (gönüller açan) eşler ve çocuklar lutfeyle ve bizi korunanlara önder yap!\" derler."},{"n":75,"t":"İşte onlar, sabretmelerine karşılık saraylarda ödüllendirelecekler ve orada bir sağlık dileği ve selâm ile karşılanacaklardır."},{"n":76,"t":"Orada ebedi kalacaklardır. Ne güzel karargâh ve ne güzel makamdır orası!"},{"n":77,"t":"De ki: \"Du’ânız (ibâdetiniz) olmadıktan sonra Rabbim sizi ne yapsın? (Size haber verdiklerimi) yalanladınız. Bu yüzden cezâlandırılmanız gerekecektir.\""}],[{"n":1,"t":"Tâ sin mim."},{"n":2,"t":"Şunlar o apaçık Kitabın âyetleridir."},{"n":3,"t":"Herhalde sen, inanmıyorlar diye neredeyse kendini helâk edeceksin!"},{"n":4,"t":"Dilesek onların üzerine gökten bir mu’cize indiririz de boyunları ona eğilir (inanırlar)."},{"n":5,"t":"Rahmân’dan onlara hiçbir yeni Zikir (uyarı) gelmez ki, mutlaka ondan yüz çevirici olmasınlar."},{"n":6,"t":"Yalanladılar ama, alay edip durdukları şeyin haberleri, yakında kendilerine gelecektir."},{"n":7,"t":"Yere bakmadılar mı orada her çeşit güzel çifti bitirmişiz?"},{"n":8,"t":"Şüphesiz bunda bir ibret vardır, ama yine çokları inanıcı değillerdir."},{"n":9,"t":"Şüphesiz Rabbin, işte üstün O’dur merhamet eden O’dur."},{"n":10,"t":"Rabbin Mûsâ’ya seslendi: \"O zâlim kavme git!\""},{"n":11,"t":"\"Fir’avn’ın kavmine. Onlar (kötülüklerden) korunmayacaklar mı?\""},{"n":12,"t":"(Mûsâ): \"Rabbim, dedi, ben, onların beni yalanlayacaklarından korkuyorum.\""},{"n":13,"t":"Göğsüm daralıyor, dilim açılmıyor (tutukluk yapıyor), onun için Hârûn’a da elçilik ver.\""},{"n":14,"t":"\"Hem benim üzerimde onlara karşı işlediğim bir günâh da var (onlardan bir adam öldürmüştüm); onların beni öldürmelerinden korkuyorum.\""},{"n":15,"t":"(Allâh): \"Hayır, dedi, ikiniz de âyetlerimizle gidin, biz sizinle beraberiz, (aranızda geçecekleri) dinliyoruz.\""},{"n":16,"t":"\"Fir’avn’e giderek deyin ki: \"Biz âlemlerin Rabbinin elçisiyiz.\""},{"n":17,"t":"\"İsrâil oğullarını bizimle beraber gönder.\""},{"n":18,"t":"(Gittiler, Allâh’ın emrini duyurdular. Fir’avn) Dedi ki: \"Biz seni, içimizden bir çocuk olarak yetiştirmedik mi? Ömründe nice yıllar aramızda kalmadın mı?\""},{"n":19,"t":"\"Ve sonunda o yaptığını da yaptın, sen nankörlerden birisin.\""},{"n":20,"t":"(Mûsâ): \"Onu yaptığım zaman sapıklardan idim\" dedi."},{"n":21,"t":"\"Sizden korkunca aranızdan kaçtım, sonra Rabbim bana hükümdarlık verdi ve beni elçilerden yaptı\""},{"n":22,"t":"\"O başıma kaktığın ni’met de İsrâil oğullarını köle yapman(yüzünden)dir. (Onları köle diye kullanıp erkek çocuklarını kesmeseydin, senin eline düşmezdim)\""},{"n":23,"t":"Fir’avn dedi ki: \"(Ey Mûsâ) âlemlerin Rabbi nedir?\""},{"n":24,"t":"(Mûsâ): \"Göklerin, yerin ve ikisi arasında bulunan her şeyin Rabbidir. Eğer gerçekten inanan kimseler iseniz (bunu anlarsınız),\" dedi."},{"n":25,"t":"(Fir’avn): Çevresinde bulunanlara: \"İşitiyor musunuz?\" dedi."},{"n":26,"t":"(Mûsâ): \"O sizin de Rabbiniz, önceki atalarınızın da Rabbidir\" dedi."},{"n":27,"t":"(Fir’avn): \"Size gönderilen bu elçiniz mutlaka delidir\" dedi."},{"n":28,"t":"(Mûsâ): \"Eğer düşünürseniz O, doğunun batının ve bunlar arasında bulunanların da Rabbidir\" dedi."},{"n":29,"t":"(Fir’avn ey Mûsâ): \"Andolsun ki benden başka tanrı edinirsen, seni mutlaka zindana atılanlardan yapacağım\" dedi."},{"n":30,"t":"(Mûsâ, peki): \"Sana (doğruluğumu) kanıtlayan apaçık bir şey getirmiş olsam da mı?\" dedi."},{"n":31,"t":"(Fir’avn): \"Eğer doğrulardansan onu getir (bakalım),\" dedi."},{"n":32,"t":"(Mûsâ), asâsını attı, bir de (baktılar ki) o apaçık bir ejderha!"},{"n":33,"t":"Elini (koltuğunun altından) çıkardı; o da, bakanlara parıl parıl parlayan bir şey oluverdi."},{"n":34,"t":"(Fir’avn), çevresindeki ileri gelenlere: \"Bu dedi, bilgin bir büyücüdür.\""},{"n":35,"t":"\"Büyüsüyle sizi toprağınızdan çıkarmak istiyor. Ne buyurursunuz?\""},{"n":36,"t":"Dediler ki: \"Onu ve kardeşini eğle, kentlere toplayıcılar gönder.\""},{"n":37,"t":"\"Bütün bilgin büyücüleri sana getirsinler.\""},{"n":38,"t":"Derken büyücüler belli bir günün belirlenen vaktinde bir araya getirildi."},{"n":39,"t":"Halka da: \"Siz de toplanır mısınız?\" denildi."},{"n":40,"t":"\"Umarız ki büyücüler üstün gelirse biz de onlara uyarız.\""},{"n":41,"t":"Büyücüler gelince Fir’avn’e: \"Eğer üstün gelenler biz olursak, bize mutlaka bir ücret var değil mi?\" dediler."},{"n":42,"t":"\"Evet dedi, hem o takdirde siz (bana) yakınlardan olacaksınız.\""},{"n":43,"t":"Mûsâ onlara: \"Atacağınızı atın!\" dedi."},{"n":44,"t":"İplerini ve değneklerini attılar ve \"Fir’avn’ın şerefine biz, elbette biz gâlib geleceğiz\" dediler."},{"n":45,"t":"Mûsâ da asâsını attı. Birden o, onların uydurduklarını yutmağa başladı."},{"n":46,"t":"Derhal büyücüler secdeye kapandılar:"},{"n":47,"t":"Dediler: \"Âlemlerin Rabbine inandık.\""},{"n":48,"t":"\"Mûsâ’nın ve Hârûn’un Rabbine.\""},{"n":49,"t":"(Fir’avn) dedi: \"Ben size izin vermeden mi ona inandınız? O, size büyü öğreten büyüğünüzdür. Öyleyse (size ne yapacağımı) yakında bileceksiniz: Ellerinizi ve ayaklarınızı çapraz olarak keseceğim ve hepinizi asacağım!\""},{"n":50,"t":"\"Zararı yok, dediler, (nasıl olsa) biz Rabbimize döneceğiz.\""},{"n":51,"t":"\"Biz ilk inananlar olduğumuz için Rabbimizin, hatâlarımızı bağışlayacağını umarız.\""},{"n":52,"t":"Mûsâ’ya: \"Kullarımı geceleyin (Mısır’dan çıkar), yürüt; siz takibedileceksiniz.\" diye vahyettik."},{"n":53,"t":"Fir’avn, (İsrâil oğullarının gittiğini duyunca) kentlere (asker) toplayıcılar gönderdi."},{"n":54,"t":"\"Şunlar, (şu İsrâil oğulları), az bir topluluktur\" dedi."},{"n":55,"t":"\"Bizi kızdırmaktadırlar.\""},{"n":56,"t":"\"Biz, ihtiyatlı, koca bir cemaatiz.\""},{"n":57,"t":"Böylece biz onları çıkardık: bahçeler(in)den, çeşmeler(in)den."},{"n":58,"t":"Hazineler(in)den ve o güzel yer(lerin)den."},{"n":59,"t":"Böylece bunları İsrâil oğullarına mirâs yaptık."},{"n":60,"t":"(Fir’avn ve adamları), güneş doğarken onların ardına düştüler."},{"n":61,"t":"İki topluluk (yaklaşıp) birbirini görünce Mûsâ’nın adamları: \"İşte yakalandık!\" dediler."},{"n":62,"t":"(Mûsâ): \"Hayır, dedi, Rabbim benimle beraberdir. Bana yol gösterecektir.\""},{"n":63,"t":"Mûsâ’ya: \"Değneğinle denize vur!\" diye vahyettik. (Vurunca deniz) yarıldı, (on iki yol açıldı). Her bölüm, kocaman bir dağ gibi oldu."},{"n":64,"t":"Ötekileri de buraya yaklaştırdık (Mûsâ ve adamlarının ardından, düşmanları da bu denizde açılan yollara girdiler)."},{"n":65,"t":"Mûsâ’yı ve beraberinde olanları tamamen kurtardık."},{"n":66,"t":"Sonra ötekilerini boğduk (Mûsâ ve adamları karaya çıkınca deniz kapandı, Fir’avn ve adamları boğuldu)."},{"n":67,"t":"Muhakkak ki bunda bir ibret vardır, ama çokları inanmazlar."},{"n":68,"t":"Şüphesiz Rabbin, işte üstün O’dur, merhamet eden O’dur."},{"n":69,"t":"Onlara İbrâhim’in haberini de oku:"},{"n":70,"t":"Babasına ve kavmine: \"Neye tapıyorsunuz?\" demişti."},{"n":71,"t":"\"Putlara tapıyoruz, onların önünde ibâdete duruyoruz.\" dediler."},{"n":72,"t":"\"Peki, dedi, siz du’â ettiğiniz zaman onlar sizi işitiyorlar mı?\""},{"n":73,"t":"\"Yahut size fayda veya zarar verebiliyorlar mı?\""},{"n":74,"t":"\"Hayır, ama babalarımızın böyle yaptıklarını gördük, (onun için biz de böyle yapıyoruz).\" dediler."},{"n":75,"t":"\"İşte gördünüz mü neye tapıyorsunuz?\" dedi."},{"n":76,"t":"\"Siz ve eski atalarınız?\""},{"n":77,"t":"\"Onlar benim düşmanımdır. Yalnız âlemlerin Rabbi (benim dostumdur).\""},{"n":78,"t":"\"Beni yaratan ve bana yol gösteren O’dur.\""},{"n":79,"t":"\"Bana yediren ve içiren O’dur.\""},{"n":80,"t":"\"Hastalandığım zaman bana şifâ veren O’dur.\""},{"n":81,"t":"\"Beni öldürecek, sonra diriltecek O’dur.\""},{"n":82,"t":"\"Cezâ günü hatâmı bağışlayacağını umduğum da O’dur.\""},{"n":83,"t":"\"Rabbim, bana hüküm (hükümdarlık, bilgi) ver ve beni Sâlihler arasına kat.\""},{"n":84,"t":"\"Sonra gelenler arasında bana, bir doğruluk dili nasib eyle (sonraki nesiller arasında hayır ile anılmamı sağla)!\""},{"n":85,"t":"\"Beni ni’met(i bol olan) cennetinin vârislerinden kıl.\""},{"n":86,"t":"\"Babamı da bağışla. Çünkü o, sapıklardandır."},{"n":87,"t":"\"(Kulların) diriltilecekleri gün, beni utandırma.\""},{"n":88,"t":"\"O gün ki, ne mal, ne de oğullar yarar vermez.\""},{"n":89,"t":"\"Ancak Allah’a sağlam ve temiz kalb getiren (yarar görür).\""},{"n":90,"t":"(O gün) cennet, korunanlara yaklaştırılır."},{"n":91,"t":"Cehennem de azgınların karşısına çıkarılır."},{"n":92,"t":"Onlara \"Hani taptıklarınız nerede?\" denilir."},{"n":93,"t":"\"O Allah’tan başka (taptıklarınız) size yardım ediyorlar mı, yahut kendilerine yardımları dokunuyor mu?\""},{"n":94,"t":"Onlar ve azgınlar, tepe taklak oraya atılırlar."},{"n":95,"t":"İblis’in bütün askerleri de."},{"n":96,"t":"Onlar orada (putlarıyle) çekişerek derler ki:"},{"n":97,"t":"\"Vallahi biz apaçık bir sapıklık içinde imişiz!\""},{"n":98,"t":"\"Çünkü sizi âlemlerin Rabbine eşit tutuyorduk.\""},{"n":99,"t":"\"Ama bizi saptıran o suçlulardır.\""},{"n":100,"t":"\"Şimdi artık bizim ne şefâ’atçilerimiz var\","},{"n":101,"t":"\"Ne de sıcak bir dostumuz.\""},{"n":102,"t":"\"Âh keşke bir dönüşümüz daha olsa da inananlardan olsak!\""},{"n":103,"t":"Muhakkak ki bunda bir ibret vardır, ama yine çokları inanmazlar.\""},{"n":104,"t":"Şüphesiz Rabbin, işte üstün O’dur, merhamet eden O’dur."},{"n":105,"t":"Nûh kavmi de gönderilen elçileri yalanladı."},{"n":106,"t":"Kardeşleri Nûh onlara: \"Korunmaz mısınız?\" demişti."},{"n":107,"t":"\"Ben size gönderilmiş güvenilir bir elçiyim.\""},{"n":108,"t":"\"Allah’tan korkun ve bana itâ’at edin.\""},{"n":109,"t":"\"Ben sizden, buna karşı bir ücret istemiyorum. Benim ücretim, yalnız âlemlerin Rabbine âittir.\""},{"n":110,"t":"\"Öyle ise Allah’tan korkun ve bana itâ’at edin.\""},{"n":111,"t":"Dediler ki: \"Sana bayağı kimseler uymuşken biz sana inanır mıyız?\""},{"n":112,"t":"Dedi ki: \"Ben onların yaptıklarını(n iç yüzünü) bilmem (ben ancak görünüşe göre hüküm veririm).\""},{"n":113,"t":"\"Anlayışınız olsa, onların hesabının Rabbime âit olduğunu bilirsiniz.\""},{"n":114,"t":"\"Ben inananları kovacak değilim.\""},{"n":115,"t":"\"Ben sadece apaçık bir uyarıcıyım.\""},{"n":116,"t":"Dediler: \"Ey Nûh, (bu dediğinden) vazgeçmezsen mutlaka taşlananlardan olacaksın.\""},{"n":117,"t":"(Nûh): \"Rabbim, dedi, kavmim beni yalanladı.\""},{"n":118,"t":"\"Benimle onların arasını aç (aramızda hükmet), beni ve benimle beraber bulunan mü’minleri kurtar!\""},{"n":119,"t":"Biz de onu ve onunla beraber bulunanları, dolu gemi içinde kurtardık."},{"n":120,"t":"Sonra bunun ardından, geride kalanları boğduk."},{"n":121,"t":"Muhakkak ki bunda bir ibret vardır, ama yine çokları inanmazlar."},{"n":122,"t":"Şüphesiz Rabbin, işte üstün O’dur, merhamet eden O’dur."},{"n":123,"t":"’Âd (kavmi) de, gönderilen elçileri yalanladı."},{"n":124,"t":"Kardeşleri Hûd onlara: \"Korunmaz mısınız?\" demişti."},{"n":125,"t":"\"Ben size gönderilmiş güvenilir bir elçiyim.\""},{"n":126,"t":"\"Allah’tan korkun ve bana itâ’at edin.\""},{"n":127,"t":"\"Ben sizden buna karşı bir ücret istemiyorum. Benim ücretim yalnız âlemlerin Rabbine âittir.\""},{"n":128,"t":"\"Siz her yol üzerine, (gelip geçenleri yanıltmak için) bir işâret yapıp da boş şeyle mi uğraşıyorsunuz?\""},{"n":129,"t":"\"Belki ebedi yaşarsınız diye köşkler (ve müstahkem kaleler) ediniyorsunuz?\""},{"n":130,"t":"\"(Bir kavmi) yakaladığınız zaman da zorbalar gibi yakalıyorsunuz.\""},{"n":131,"t":"\"Allah’tan korkun ve bana itâ’at edin.\""},{"n":132,"t":"\"Size bildiğiniz ni’metleri bol bol veren (Allâh)dan korkun.\""},{"n":133,"t":"\"O size verdi: davarlar, oğullar,\""},{"n":134,"t":"\"Bahçeler, çeşmeler.\""},{"n":135,"t":"\"Doğrusu ben size büyük bir günün azâbı(nın çarpması)ndan korkuyorum.\""},{"n":136,"t":"Dediler ki: \"Öğüt versen de, öğüt verenlerden olmasan da bizce birdir.\""},{"n":137,"t":"\"Bu (davranışımız), sadece evvelkilerin ahlâkı (ve geleneği)dir.\""},{"n":138,"t":"\"Biz azâba uğratılacak değiliz.\""},{"n":139,"t":"(Böylece) onu yalanladılar. Biz de onları helâk ettik. Muhakkak ki bunda bir ibret vardır, ama yine çokları inanmazlar."},{"n":140,"t":"Şüphesiz Rabbin, işte üstün O’dur, merhamet eden O’dur."},{"n":141,"t":"Semûd (kavmi) de gönderilen elçileri yalanladı:"},{"n":142,"t":"Kardeşleri Sâlih, onlara demişti ki: \"Korunmaz mısınız?\""},{"n":143,"t":"\"Ben sizin için güvenilir bir elçiyim.\""},{"n":144,"t":"\"Allah’tan korkun ve bana itâ’at edin.\""},{"n":145,"t":"\"Ben sizden buna karşı bir ücret istemiyorum. Benim ücretim yalnız âlemlerin Rabbine âittir.\""},{"n":146,"t":"\"Siz burada güven içinde bırakılacağınızı mı sanıyorsunuz?\""},{"n":147,"t":"\"Böyle bahçelerde, çeşme başlarında?\""},{"n":148,"t":"\"Ekinler ve yumuşak tomurcuklu güzel hurmalıklar arasında?\""},{"n":149,"t":"\"Dağlardan ustalıkla evler yontuyorsunuz.\""},{"n":150,"t":"\"Allah’tan korkun ve bana itâ’at edin.\""},{"n":151,"t":"\"O aşırıların emrine uymayın.\""},{"n":152,"t":"\"Yeryüzünde bozgunculuk yapan, ıslah etmeyen o kimseler(in sözüyle hareket etmeyin).\""},{"n":153,"t":"\"Dediler: \"Sen, iyice büyülenmişlerdensin.\""},{"n":154,"t":"\"Sen de bizim gibi bir insansın. Eğer doğrulardansan bize bir mu’cize getir.\""},{"n":155,"t":"Dedi: \"İşte bu dişi deve (mu’cize)dir. (Bir gün) onun su içme hakkı var, belli bir günün su içme hakkı da sizin.\""},{"n":156,"t":"\"Sakın, ona bir kötülük dokundurmayın, sonra büyük bir günün azâbı sizi yakalar.\""},{"n":157,"t":"Nihâyet onu kestiler, ama pişman oldular."},{"n":158,"t":"Ve azâb onları yakaladı. Muhakkak ki bunda bir ibret vardır, ama yine çokları inanmazlar."},{"n":159,"t":"Şüphesiz Rabbin, işte üstün O’dur, merhamet eden O’dur."},{"n":160,"t":"Lût (kavmi) de gönderilen elçileri yalanladı."},{"n":161,"t":"Kardeşleri Lût, onlara \"Korunmaz mısınız?\" demişti."},{"n":162,"t":"\"Ben sizin için güvenilir bir elçiyim.\""},{"n":163,"t":"\"Allah’tan korkun ve bana itâ’at edin.\""},{"n":164,"t":"\"Ben sizden buna karşı bir ücret istemiyorum. Benim ücretim yalnız âlemlerin Rabbine âittir."},{"n":165,"t":"\"Âlemlerin içinde erkeklere mi gidiyorsunuz?\""},{"n":166,"t":"\"Ve Rabbinizin sizin için yarattığı eşlerinizi bırakıyorsunuz? Siz sınırı aşan bir kavimsiniz.\""},{"n":167,"t":"Dediler: \"Ey Lût, andolsun, eğer (bundan) vazgeçmezsen, mutlaka sürülenlerden olacaksın.\""},{"n":168,"t":"(Lût) dedi: \"Ben sizin bu işinize, (kadınları bırakıp erkeklere gidişinize) kızanlardanım.\""},{"n":169,"t":"\"Rabbim, beni ve âilemi bunların yaptıklarından kurtar!\""},{"n":170,"t":"Biz de onu ve âilesini tamamen kurtardık."},{"n":171,"t":"Yalnız geride kalanlar arasında bulunan bir kocakarıyı (kurtarmadık)."},{"n":172,"t":"Sonra ötekilerini hep yıktık, helâk ettik."},{"n":173,"t":"Ve üzerlerine bir yağmur yağdırdık, uyarıl(ıp da yola gelmey)enlerin yağmuru hakikaten çok kötü oldu!"},{"n":174,"t":"Muhakkak ki bunda bir ibret vardır, ama yine çokları inanmazlar."},{"n":175,"t":"Şüphesiz Rabbin, işte üstün O’dur, merhamet eden O’dur."},{"n":176,"t":"Eyke halkı da gönderilen elçileri yalanladı."},{"n":177,"t":"Şu’ayb, onlara demişti ki: \"Korunmaz mısınız?\""},{"n":178,"t":"\"Ben sizin için güvenilir bir elçiyim.\""},{"n":179,"t":"\"Allah’tan korkun ve bana itâ’at edin.\""},{"n":180,"t":"\"Ben sizden, buna karşı bir ücret istemiyorum. Benim ücretim yalnız âlemlerin Rabbine âittir.\""},{"n":181,"t":"\"Ölçüyü tam yapın, eksiltenlerden olmayın.\""},{"n":182,"t":"\"Doğru terâzi ile tartın.\""},{"n":183,"t":"\"İnsanların haklarını kısmayın. Yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın.\""},{"n":184,"t":"\"Sizi ve önceki nesilleri yaratandan korkun."},{"n":185,"t":"Dediler: \"Sen iyice büyülenmişlerdensin.\""},{"n":186,"t":"\"Sen de bizim gibi bir insansın, biz seni mutlaka yalancılardan sanıyoruz.\""},{"n":187,"t":"\"Eğer doğrulardansan o halde üzerimize gökten parçalar düşür.\""},{"n":188,"t":"\"Rabbim yaptığınızı daha iyi bilir\" dedi."},{"n":189,"t":"Onu yalanladılar, nihâyet o gölge gününün azâbı, kendilerini yakaladı. Gerçekten o, büyük bir günün azâbı idi."},{"n":190,"t":"Muhakkak ki bunda bir ibret vardır ama yine çokları inanmazlar."},{"n":191,"t":"Şüphesiz Rabbin, işte üstün O’dur, merhamet eden O’dur."},{"n":192,"t":"Muhakkak ki o (Kur’ân), âlemlerin Rabbinin indirmesidir."},{"n":193,"t":"Onu, er-Rûhu’l-Emin (güvenilir ruh, Cebrâil) indirdi:"},{"n":194,"t":"Senin kalbine; uyarıcılardan olman için,"},{"n":195,"t":"Apaçık Arapça bir dille."},{"n":196,"t":"O(nun içeriği), evvelkilerin Kitaplarında da vardır."},{"n":197,"t":"İsrâiloğulları bilginlerinin onu bilmesi de onlar için (Kur’ân’ın Güvenilir Rûh tarafından vahyedildiğine) yeterli bir delil değil mi?"},{"n":198,"t":"Biz onu yabancılardan birine indirseydik de,"},{"n":199,"t":"Onu onlara okusaydı, ona inanmazlardı:"},{"n":200,"t":"Biz onu, suçluların kalblerine öyle soktuk."},{"n":201,"t":"Acı azâbı görünceye kadar da ona inanmazlar."},{"n":202,"t":"Azâb onlara öyle ansızın gelir ki, onlar hiç farkında olmazlar."},{"n":203,"t":"(Birden onu karşılarında bulunca) \"Acaba bize süre verilir mi?\" derler."},{"n":204,"t":"Hâlâ bizim azâbımızı mı acele istiyorlar (doğru söyleyenlerden isen bizi tehdid ettiğin azâbı getir mi diyorlar)?"},{"n":205,"t":"Baksana, biz onları yıllarca yaşatsak,"},{"n":206,"t":"Sonra tehdid edildikleri (azâb) kendilerine gelse,"},{"n":207,"t":"O yaşatıldıkları (zevk-u sefâ sürdükleri) şeyler, kendilerine ne yarar sağlardı?"},{"n":208,"t":"Biz, hiçbir kenti helâk etmedik ki onun uyarıcıları olmasın (helâk etmeden önce mutlaka uyarıcı gönderdik)."},{"n":209,"t":"(Uyarıcılar) uyarırlardı. Biz zulmediciler değildik."},{"n":210,"t":"O (Kur’â)n’ı şeytânlar (cinler) indirmedi."},{"n":211,"t":"Bu, onlara yaraşmaz ve zaten yapamazlar da."},{"n":212,"t":"Çünkü onlar, (meleklerin sözlerini) işitmekten uzaklaştırılmışlardır."},{"n":213,"t":"Allâh ile beraber başka bir tanrı çağırma, sonra azâb edilenlerden olursun."},{"n":214,"t":"En yakın akrabânı uyar."},{"n":215,"t":"Ve sana uyan mü’minlere kanadını indir (onlara karşı mütevâzi ve şefkatli davran)."},{"n":216,"t":"Şâyet sana (uymaz) karşı gelirlerse: \"Ben sizin yaptıklarınızdan uzağım,\" de."},{"n":217,"t":"Gâlib ve esirgeyen (Allâh)’a tevekkül et."},{"n":218,"t":"O, seni görür; Namaza durduğun zaman,"},{"n":219,"t":"Ve secde edenler arasında eğilip doğrulurken."},{"n":220,"t":"Çünkü O, işitendir, bilendir."},{"n":221,"t":"Şeytânların kime ineceğini size haber vereyim mi?"},{"n":222,"t":"Onlar, her günâhkâr yalancıya inerler."},{"n":223,"t":"O yalancılar, (şeytânlara) kulak verirler, çokları da yalan söylerler."},{"n":224,"t":"Şâ’irlere gelince onlara da azgınlar uyar."},{"n":225,"t":"Baksana onlar, her vâdide şaşkın şaşkın dolaşırlar?"},{"n":226,"t":"Ve onlar yapmayacakları şeyleri söylerler."},{"n":227,"t":"Ancak inananlar, iyi işler yapanlar, Allâh’ı çok ananlar ve kendilerine zulmedildikten sonra (rakiplerine) üstün gelmeğe çalışanlar böyle değildir. Zulmedenler, yakında nasıl bir devrime uğrayıp devrileceklerini bileceklerdir!"}],[{"n":1,"t":"Tâ sin. Şunlar Kur’ân’ın ve apaçık bir Kitabın âyetleridir."},{"n":2,"t":"İnananlara yol gösterici ve müjdedir."},{"n":3,"t":"Onlar ki namazı kılarlar, zekâtı verirler ve âhirete de kesin olarak inanırlar."},{"n":4,"t":"Âhirete inanmayanların işlerini kendilerine süslemişizdir, onlar körü körüne bocalarlar."},{"n":5,"t":"Onlar, öyle kimselerdir ki, en kötü azâb kendilerinindir. Ve onlar âhirette de en çok ziyana uğrayanlardır."},{"n":6,"t":"(Ey Muhammed) Sana bu Kur’ân, hüküm ve hikmet sâhibi, (herşeyi) bilen (Allâh) katından verilmektedir."},{"n":7,"t":"Mûsâ, âilesine: \"Ben bir ateş gördüm (gidip) size ondan bir haber getireyim, yâhut size bir ateş koru getireyim de ısınasınız.\" demişti."},{"n":8,"t":"Oraya gelince (kendisine) seslenildi: \"Ateşin içinde bulunan da, çevresinde olan da mübârek kılındı. Âlemlerin Rabbi Allâh, eksikliklerden münezzehtir.\""},{"n":9,"t":"\"Ey Mûsâ, gerçek şu ki ben, güçlü, hüküm ve hikmet sâhibi olan Allâh’ım!\""},{"n":10,"t":"\"Asânı at!\" (Mûsâ attığı) asâsının küçük bir yılan gibi titreştiğini görünce (korkudan) arkaya dön(üp kaç)dı, geri dön(üp bak)madı (bile). \"Ey Mûsâ korkma, çünkü ben (evet), benim huzûrumda elçiler korkmaz(lar).\""},{"n":11,"t":"\"Ancak zulmeden, sonra yaptığı kötülüğün yerine iyilik yapan olursa ona karşı da ben bağışlayıcı, esirgeyiciyim.\""},{"n":12,"t":"\"Elini koynuna sok, kusursuz olarak bembeyaz (parıl parıl) çıksın. (Bu da) Fir’avn’a ve onun kavmine (göstereceğin) dokuz mu’cize içindedir. Çünkü onlar yoldan çıkan bir kavimdir.\""},{"n":13,"t":"Onlara açıkça görünen âyetlerimiz gelince: \"Bu, apaçık bir büyüdür\" dediler."},{"n":14,"t":"Vicdanları, onlar(ın doğruluğun)a kanaat getirdiği halde, sırf haksızlık ve böbürlenme yüzünden onları inkâr ettiler. Bak işte o bozguncuların sonu nasıl oldu."},{"n":15,"t":"Andolsun biz, Dâvûd’a ve Süleyman’a bir ilim verdik de onlar: \"Bizi inanan kullarından birçoğuna üstün kılan Allah’a hamdolsun.\" dediler."},{"n":16,"t":"Süleymân, Dâvûd’a mirâsçı oldu ve dedi ki: \"Ey insanlar, bize kuşların dili öğretildi. Ve bize her şeyden (bolca) bir pay verildi. İşte bu, açık bir lutuftur.\""},{"n":17,"t":"Süleymân’a cinlerden insanlardan ve kuşlardan orduları toplandı, hepsi bir arada düzenli olarak sevk ediliyordu."},{"n":18,"t":"Karınca vâdisine geldikleri zaman bir karınca: \"Ey karıncalar\" dedi, \"yuvalarınıza girin ki Süleymân ve orduları farkında olmayarak sizi ezmesinler.\""},{"n":19,"t":"(Süleymân) Onun sözüne gülümseyerek dedi: \"Rabbim, bana ve anama, babama lutfettiğin ni’mete şükretmemi, senin beğeneceğin faydalı bir iş yapmamı gönlüme ilham eyle ve rahmetinle beni iyi kullarının arasına sok.\""},{"n":20,"t":"Kuşları teftiş etti, (içlerinde hüdhüdü bulamadı), dedi ki: \"Neden hüdhüdü göremiyorum, yoksa kayıplardan mı oldu?\""},{"n":21,"t":"\"Ona çetin bir azâbedeceğim, ya da onu keseceğim. Yahut da bana (mâzeretini belirten) açık bir delil getirecek.\""},{"n":22,"t":"Çok geçmeden (hüdhüd) geldi: \"Ben, dedi, senin görmediğin bir şey gördüm ve Sebâ’dan sana gerçek bir haber getirdim."},{"n":23,"t":"\"Ben onlara hükümdarlık eden bir kadın buldum, kendisine her şey verilmiş ve büyük bir tahtı var.\""},{"n":24,"t":"\"Onun ve kavminin, Allâh’ı bırakıp güneşe secde ettiklerini gördüm. Şeytân onlara işlerini süsleyip onları doğru yoldan çevirmiş, bu yüzden yola gelmiyorlar.\""},{"n":25,"t":"\"Göklerde ve yerde gizleneni açığa çıkaran ve gizlediklerini ve açığa vurduklarını bilen Allah’a secde etmeleri gerekmez mi?\""},{"n":26,"t":"\"Allâh ki, O’ndan başka Tanrı yoktur, büyük Arş’ın sâhibidir.\""},{"n":27,"t":"(Süleymân): \"Bakalım, dedi, doğru mu söyledin, yoksa yalancılardan mısın?\""},{"n":28,"t":"\"Bu mektubumu götür, onlara at, sonra onlardan biraz öteye çekil de bak, neye başvuruyorlar (ne yapacaklar).\""},{"n":29,"t":"(Hüdhüd’ün mektubu götürüp kendisine attığı Seba melikesi Belkis) Danışmanlarına dedi ki: \"Ey ileri gelenler, bana çok önemli bir mektup bırakıldı.\""},{"n":30,"t":"\"O Süleyman’dandır ve Rahmân ve Rahim Allâh’ın adiyle (başlamakta)dır."},{"n":31,"t":"\"Bana karşı büyüklük taslamayın ve bana teslim olarak gelin (diye yazıyor).\""},{"n":32,"t":"\"Ey ileri gelenler, dedi, bu işimde bana bir fikir verin; ben, siz olmadıkça hiçbir işi kesip atmam.\""},{"n":33,"t":"Dediler ki: \"Biz güçlüyüz, yaman savaşçılarız ama emir senindir. Bak, ne buyurursan öyle yaparız\""},{"n":34,"t":"Dedi: \"Hükümdarlar bir ülkeye girdiler mi, orayı bozarlar, halkının şereflilerini alçaltırlar, (evet) böyle yaparlar.\""},{"n":35,"t":"\"Ben onlara bir hediye göndereyim de bakayım elçiler ne ile dönecekler.\""},{"n":36,"t":"(Elçi, hediyelerle) Süleymân’a gelince (Süleymân) dedi ki: \"Siz bana mal ile yardım mı etmek istiyorsunuz? Allâh’ın bana verdiği, size verdiğinden daha iyidir. Hediyenizle ancak siz sevinirsiniz."},{"n":37,"t":"Sen, onlara dön (söyle): onlara, kendilerinin asla karşı koyamayacakları ordularla gelirim ve onları hor ve hakir bir durumda oradan sürüp çıkarırım.\""},{"n":38,"t":"(Elçi gittikten sonra Süleymân, danışmanlarını topladı): \"Ey ileri gelenler, dedi, onların bana teslim olarak gelmelerinden önce hanginiz onun tahtını bana getirebilir?\""},{"n":39,"t":"Cinlerden bir ifrit (kötü bir cin): \"Sen makamından kalkmadan önce ben onu sana getiririm, dedi, bunu yapmağa gücüm yeter ve bana güvenilir.\""},{"n":40,"t":"Yanında Kitaptan bir ilim bulunan kimse de: \"Sen gözünü açıp yummadan ben onu sana getirebilirim.\" dedi. (Süleymân) tahtı yanına yerleşmiş görünce dedi ki: \"Bu, Rabbimin lutfundandır. (Kendisine) şükür mü edeceğim, yoksa nankörlük mü edeceğim diye beni sınamak istiyor. Şükreden kendisi için şükretmiş olur; nankörlük edene gelince, Rabbim zengindir (onun şükrüne muhtaç değildir), kerimdir (çok ikrâm sâhibidir, yücedir).\""},{"n":41,"t":"(Ve) dedi ki: \"Onun tahtını tanınmaz hale getirin, bakalım tanıyabilecek mi, yoksa tanımayacak mı?\""},{"n":42,"t":"(Kraliçe) Gelince (ona): \"Senin tahtın da böyle mi?\" dendi, \"Tıpkı o, dedi, zaten bize daha önce bilgi verilmişti. (Allâh’ın kudretini ve senin peygamber olduğunu anlamış) ve biz müslüman olmuştuk.\""},{"n":43,"t":"Onu, Allah’tan başka taptığı şeyler, (bu zamana dek tevhid dinine girmekten) alıkoymuştu. Çünkü kendisi, inkâr eden bir kavimden idi."},{"n":44,"t":"Ona: \"Köşke gir!\" dendi. Köşkü görünce zemini su sandı ve bacaklarını sıvadı. (Süleymân) \"O, cilâlı, şeffaf sırçadandır\" dedi. (Kraliçe): \"Rabbim, ben kendime zulmetmişim. (Artık) Süleymân’la beraber âlemlerin Rabbi Allah’a teslim oldum,\" dedi."},{"n":45,"t":"Andolsun biz, Semûd (kavmin)e de kardeşleri Sâlih’i: \"Allah’a kulluk edin!\" demesi için gönderdik. Baktı ki onlar, birbiriyle çekişen iki bölük olmuşlar."},{"n":46,"t":"Dedi: \"Ey kavmim, iyilikten önce neden kötülüğe eviyorsunuz? Esirgenmeniz için Allah’tan mağfiret dilemeniz gerekmez mi?\""},{"n":47,"t":"Dediler: \"Senin ve seninle beraber bulunanların yüzünden uğursuzluğa uğradık.\" Dedi: \"Uğursuzluğunuz(un sebebi), Allâh’ın yanındadır (herşey O’nun takdiriyle olur). Doğrusu siz (bu olaylarla) sınanan bir toplumsunuz.\""},{"n":48,"t":"Şehirde dokuz kişi vardı ki yeryüzünde bozgunculuk yaparlar, düzeltmezlerdi."},{"n":49,"t":"Allah’a and içerek birbirlerini: \"Biz, gece ona ve âilesine baskın yap(ıp onları öldür) elim sonra velisine: ’Âilesinin öldürülüşünde bulunmadığımızı, bizim doğru olduğumuzu’ söyleyelim\" dediler."},{"n":50,"t":"Böyle bir tuzak kurdular, biz de onlar hiç farkında olmadan onlara bir tuzak kurduk."},{"n":51,"t":"Bak, işte tuzaklarının sonucu nasıl oldu, (nasıl) biz onları ve kavimlerini toptan yıktık, yok ettik."},{"n":52,"t":"İşte şunlar, zulümleri yüzünden çökmüş, ıssız kalmış evleridir. Şüphesiz bunda bilen bir kavim için ibret vardır."},{"n":53,"t":"İnananları ve korunanları kurtardık."},{"n":54,"t":"Lût’u da (gönderdik), kavmine dedi ki: \"Siz göre göre o aşırı kötülüğü yapıyorsunuz ha?!\""},{"n":55,"t":"\"Siz, kadınları bırakıp şehvetle erkeklere mi yaklaşıyorsunuz? Siz gerçekten câhil bir toplumsunuz.\""},{"n":56,"t":"Kavminin cevabı sadece şöyle demek oldu: \"Lût âilesini kentinizden çıkarın, çünkü onlar temiz kalmak isteyen kimselermiş(!)\""},{"n":57,"t":"Biz de onu ve âilesini kurtardık, yalnız karısının (azâbda) kalanlardan olmasını takdir ettik."},{"n":58,"t":"Üzerlerine (pişmiş çamurdan bir taş) yağmur(u) indirdik. Uyarıl(ıp da aldırmay)anların yağmuru gerçekten ne kötü oldu!"},{"n":59,"t":"De ki: \"Hamd olsun Allah’a, selâm O’nun seçtiği kullarına. Allâh mı hayırlı yoksa ortak koştukları şeyler mi?\""},{"n":60,"t":"Yahut gökleri ve yeri kim yarattı? Size gökten su indirdi de onunla sizin bir ağacını dahi bitiremeyeceğiniz gönül açan bahçeler bitirdik. Allâh ile beraber başka bir tanrı mı var? Hayır, onlar (haktan) sapan bir kavimdir."},{"n":61,"t":"Yahut şu dünyâyı durulacak yer yapan, arasından ırmaklar çıkaran, üstünde sağlam dağlar yaratan ve iki deniz arasına bir perde koyan kimdir? Allâh ile beraber başka bir tanrı mı var? Hayır çokları bilmiyorlar."},{"n":62,"t":"Yahut du’â ettiği zaman darda kalmışa kim yetişiyor da kötülüğü (onun üzerinden) kaldırıyor ve sizi (eskilerin yerine) yeryüzünün sâhipleri yapıyor? Allâh ile beraber başka bir tanrı mı var? Ne de az düşünüyorsunuz?"},{"n":63,"t":"Yahut karanın ve denizin karanlıkları içinde size yol gösteren kim ve rahmetinin önünde rüzgârları müjdeci gönderen kim? Allâh ile beraber başka bir tanrı mı var? Hâşâ, Allâh ortak koştukları şeylerden yücedir, münezzehtir (O, eksikliklerden uzaktır)."},{"n":64,"t":"Yahut yaratmağa kim başlıyor, sonra onu (kim) iâde ediyor (ölüp ortadan kalkan şeyleri yeniden yaratıyor)? Sizi gökten ve yerden kim rızıklandırıyor? Allâh ile beraber başka bir tanrı mı var? De ki: \"Eğer doğru iseniz delilinizi getirin.\""},{"n":65,"t":"De ki: \"Göklerde ve yerde Allah’tan başka kimse gaybı bilmez. Ne zaman dirileceklerini de bilmezler.\""},{"n":66,"t":"Doğrusu onların âhiret hakkındaki bilgileri, ardarda gelip bir araya toplandı. Fakat onlar (hâlâ) ondan bir kuşku içindedirler. Daha doğrusu, onlar ondan yana kördürler."},{"n":67,"t":"İnkâr edenler dediler ki: \"Biz de babalarımız da toprak olduktan sonra mı, biz mi (diriltilip) çıkarılacağız?\""},{"n":68,"t":"\"Bu tehdid, bize de; önceden atalarımıza da yapıldı. Bu, öncekilerin masallarından başka bir şey değildir.\""},{"n":69,"t":"De ki: \"Yeryüzünde yürüyün de suçluların sonunun nasıl olduğunu görün.\""},{"n":70,"t":"(Ey Muhammed) onlar(ın sözlerin)e üzülme, tuzak kurmalarından da sıkılma."},{"n":71,"t":"\"Doğru iseniz bu tehdid (ettiğiniz azâb) ne zaman (gelecek)?\" diyorlar."},{"n":72,"t":"De ki: \"Belki de acele ettiğiniz(azâb)ın bir kısmı ardınıza takılmıştır, bile.\""},{"n":73,"t":"Şüphesiz Rabbin, insanlara karşı lutuf sâhibidir, fakat çokları şükretmezler."},{"n":74,"t":"Ve Rabbin elbette onların göğüslerinin gizlediğini de, açığa vurduklarını da bilir."},{"n":75,"t":"Gökte ve yerde gizli hiçbir şey yoktur ki apaçık bir Kitapta olmasın."},{"n":76,"t":"Bu Kur’an, İsrâil oğullarına, kendilerinin ayrılığa düştükleri şeylerin birçoğunu anlatmaktadır."},{"n":77,"t":"Ve elbette o, mü’minlere bir yol gösterici ve rahmettir."},{"n":78,"t":"Şüphesiz, Rabbin onlar arasında hükmünü verecektir. O, azizdir, hakkiyle bilendir."},{"n":79,"t":"Allah’a tevekkül et, çünkü sen apaçık gerçek üzerindesin."},{"n":80,"t":"Sen ölülere duyuramazsın, arkalarını dönmüş kaçmakta olan sağırlara da çağrıyı işittiremezsin."},{"n":81,"t":"Ve sen kör(ler)i içine düştükleri sapıklıklardan çıkarıp yola getiremezsin. Sen, ancak âyetlerimize inananlara duyurabilirsin ve onlar derhal müslüman olurlar."},{"n":82,"t":"O söz, başlarına geldiği zaman, onlara yerden bir Dâbbe (canlı) çıkarırız; o, onlara insanların, âyetlerimize inanmadıklarını söyler."},{"n":83,"t":"O gün her ümmet içinde âyetlerimizi yalanlayanlardan bir cemâat toplarız. Onlar hep bir araya getirilip tutuklanarak (ilahi huzûra) sevk edilirler."},{"n":84,"t":"(Divânına) Geldiklerinde (Allâh onlara) der: \"Âyetlerimi anlamadığınız halde yalanladınız mı? Yoksa ne yaptınız?\""},{"n":85,"t":"Zulmetmeleri yüzünden o (azâb) karar(ı) başlarına gelmiştir, artık konuşmazlar."},{"n":86,"t":"Görmediler mi, biz geceyi, içinde istirahat etmeleri için yarattık, gündüzü de aydınlık yaptık. Şüphesiz bunda inanan bir kavim için âyetler vardır."},{"n":87,"t":"Sûr’a üfleneceği gün, Allâh’ın diledikleri dışında, göklerde ve yerde bulunan kimselerin hepsi, korku içinde kalır (bayılır). Hepsi boyun bükerek O’na gelirler."},{"n":88,"t":"Görüp de donuk sandığın dağlar, bulutun yürümesi gibi yürümektedir. (Bu,) Her şeyi gâyet iyi yapan Allâh’ın yapısıdır. Doğrusu O, yaptıklarınızı haber almaktadır."},{"n":89,"t":"Kim iyilik getirirse ona, ondan daha hayırlısı vardır. Ve onlar o gün korkudan uzak, güven içindedirler."},{"n":90,"t":"Ve kim kötülük getirirse onların da yüzleri cehenneme yıkılır: \"Yaptıklarınızdan başka bir şeyle mi cezâlandırılıyorsunuz?\" (denilir)."},{"n":91,"t":"(De ki): \"Ben sadece bu kentin Rabbine kulluk etmekle emrolundum. O, burayı saygıdeğer kıldı ve her şey O’nundur. Ve bana müslümanlardan olmam emredildi.\""},{"n":92,"t":"\"Ve Kur’ân okumam (emredildi).\" \"İmdi kim yola gelirse kendi yararına yola gelmiş olur ve kim saparsa, de ki: \"Ben ancak uyarıcılardanım.\""},{"n":93,"t":"Ve de ki: \"Allah’a hamdolsun, O size âyetlerini gösterecek, siz de onları tanıyacaksınız.\" Rabbin, yaptıklarınızdan gâfil değildir."}],[{"n":1,"t":"Tâ sin mim."},{"n":2,"t":"Şunlar, o apaçık Kitabın âyetleridir."},{"n":3,"t":"İnanan bir toplum için Mûsâ ile Fir’avn’ın haberinden bir parçayı, gerçek olarak sana okuyacağız:"},{"n":4,"t":"Fir’avn, orada ululandı (zorbalığa kalktı), halkını çeşitli gruplara böldü. Onlardan bir zümreyi (İsrâil oğullarını) eziyor, oğullarını kesiyor, kadınlarını sağ bırakıyordu. Çünkü o, bozgunculardan idi."},{"n":5,"t":"Biz de istiyorduk ki o yerde ezilenlere lutfedelim, onları önderler yapalım, onları (ötekilerin mülküne) mirâsçı kılalım."},{"n":6,"t":"Ve onları o yerde iktidâra getirelim de Fir’avn’a, Hâmân’a ve askerlerine, onlardan (ezdikleri zümreden) korktukları şeyi gösterelim."},{"n":7,"t":"Mûsâ’nın annesine, \"O (çocuğu)nu emzir, başına bir şey gelmesinden korkuyorsan (bir sandık içinde) onu suya bırak, korkma, üzülme biz onu tekrar sana geri vereceğiz ve onu elçilerden yapacağız.\" diye vahyettik."},{"n":8,"t":"Nihâyet onu Fir’avn âilesi aldı ki, kendilerine bir düşman ve başlarına derd olsun. Gerçekten Fir’avn, Hâmân ve askerleri yanılıyorlardı."},{"n":9,"t":"Fir’avn’ın karısı (çocuğu sandıktan çıkarınca): \"Bana da, sana da göz bebeği (olacak, çok sevimli bir çocuk). Onu öldürmeyin, belki bize yararı dokunur, ya da onu evlâd ediniriz.\" dedi. (Onu almakla hatâ ettiklerini) anlamıyorlardı."},{"n":10,"t":"Mûsâ’nın annesinin gönlü bomboş sabahladı (meraktan çıldıracak oldu). Eğer biz, (va’dimize) inananlardan olması için onun kalbini iyice pekiştirmemiş olsaydık, neredeyse işi açığa vuracaktı."},{"n":11,"t":"(Mûsâ’nın) kızkardeşine \"Onun izini takip et,\" dedi. O da onlar farkına varmadan onu uzaktan gözetledi."},{"n":12,"t":"Biz daha önce ona, süt verenler(in sütünü emmey)i harâm etmiştik. (Hiçbir kadının sütünü emmiyordu. Fir’avn ve âilesi, çocuğun emeceği bir dadı bulma telaşı içinde idiler. Kızkardeşi uzaktan durumu görünce sokuldu): \"Sizin için onun bakımını üstlenecek ve ona öğüt ver(ip onu güzelce eğit)ecek bir âileyi göstereyim mi?\" dedi."},{"n":13,"t":"Böylece biz onu, annesine geri verdik ki gözü aydın olsun, üzülmesin ve Allâh’ın va’dinin gerçek olduğunu bilsin. Fakat çokları bilmezler."},{"n":14,"t":"(Mûsâ), güçlü çağına erip, olgunlaşınca biz ona hüküm ve ilim verdik. İşte güzel davrananları böyle mükâfâtlandırırız."},{"n":15,"t":"Halkının (kendisinden) habersiz olduğu bir sırada şehre girdi, orada biri kendi taraftarlarından, öbürü de düşmanlarından olan iki adamın dövüştüklerini gördü. Kendi taraftarlarından olan, düşmanlarından olana karşı Mûsâ’dan yardım istedi. Mûsâ da ötekine bir yumruk indirip onun işini bitirdi. (Sonra): \"Bu dedi, şeytânın işindendir. O, gerçekten apaçık, şaşırtıcı bir düşmandır.\""},{"n":16,"t":"\"Rabbim, ben nefsime zulmettim, beni bağışla!\" dedi. (Allâh) onu bağışladı. Çünkü O, çok bağışlayan, çok esirgeyendir."},{"n":17,"t":"\"Rabbim, dedi, bana lutfettiğin ni’metler hakkı için artık bir daha suçlulara arka olmayacağım.\""},{"n":18,"t":"Şehirde korku içinde (sonucu) gözetleyerek sabahladı. Bir de baktı ki dün kendisinden yardım isteyen (İsrâil oğlu), yine kendisine feryâded(ip yardım ist)iyor. Mûsâ, ona: \"Belli ki sen bir azgınsın!\" dedi."},{"n":19,"t":"Nihâyet (Mûsâ) ikisinin de (kendisinin ve yardım isteyenin) düşmanı olan adamı yakalamak isteyince o dedi ki: \"Ey Mûsâ, dün bir canı öldürdüğün gibi şimdi de beni mi öldürmek istiyorsun? Sen yeryüzünde bir zorba olmak istiyorsun, arabuluculardan olmak istemiyorsun.\""},{"n":20,"t":"Şehrin öbür ucundan bir adam koşarak geldi. \"Ey Mûsâ, dedi, ileri gelenler seni öldürmek için aralarında konuşuyorlar. Sen çık (git), ben sana öğüt verenlerdenim.\""},{"n":21,"t":"(Mûsâ, etrafı) kollayarak, korka korka oradan çıktı: \"Rabbim, beni şu zâlim kavimden kurtar!\" dedi."},{"n":22,"t":"Medyen’e doğru yönelince: \"Umarım ki Rabbim beni doğru yola iletir\" dedi."},{"n":23,"t":"Medyen suyuna varınca onun başında birçok insanların, (hayvanlarını) suladıklarını gördü. Onların gerisinde de, (diğerlerinin hayvanlarına karışmasın diye hayvanlarını) sudan meneden iki kız buldu. (Mûsâ, onlara): \"İşiniz nedir, (niçin hayvanları suya bırakmıyorsunuz)?\" dedi. Dediler ki: \"Çobanlar sulayıp çekilmeden biz (onların içine sokulup hayvanlarımızı) sulamayız. Babamız da büyük bir ihtiyardır (O gelemez).\""},{"n":24,"t":"Hemen (Mûsâ) onlarınkini de suladı, sonra gölgeye çekildi: \"Rabbim, dedi, doğrusu bana indireceğin bir hayra muhtacım, (azıcık azık indir de şu karnımı doyur).\""},{"n":25,"t":"Derken o iki kızdan biri utana utana yürüyerek ona geldi: \"Babam seni çağırıyor, bizim için (hayvanları) sulamanın ücretini verecek,\" dedi. (Mûsâ), o (kızların babaları)na gelip (başından geçen) hikâyeyi anlatınca o: \"Korkma, o zâlim kavimden kurtuldun\" dedi."},{"n":26,"t":"O (kız)lardan biri: \"Babacağım, dedi, bunu (çoban) tut işte, çünkü ücretle tuttuklarının en hayırlısı, güçlü, güvenilirdir.\""},{"n":27,"t":"O zât, (Mûsâ’ya) dedi ki: \"(Bak), bana sekiz yıl hizmet etmen şartıyle şu iki kızımdan birini sana nikâhlamak istiyorum. Eğer (bu süreyi) on (yıl)a tamamlarsan artık o, senin tarafından (bir iyilik)dir. Ben sana zahmet vermek istemem. İnşallah beni iyilerden bulacaksın.\""},{"n":28,"t":"(Mûsâ) dedi: \"Bu, seninle benim aramızda (bir sözleşme)dir. Demek hangi süreyi yerine getirsem, bana düşmanlık yok. Allâh dediğimize vekildir.\""},{"n":29,"t":"Mûsâ, süreyi bitirip âilesiyle yola çıkınca Tûr’un (sağ) yanında bir ateş gördü. Âilesine dedi ki: \"Siz durun, ben bir ateş gördüm, belki ondan size bir haber getiririm, yahut bir ateş koru (getiririm) de ısınırsınız.\""},{"n":30,"t":"Oraya gelince o mübârek yerdeki vadinin sağ kıyısındaki ağaçtan kendisine şöyle seslenildi: \"Ey Mûsâ, âlemlerin Rabbi Allâh benim, ben!\""},{"n":31,"t":"\"Asânı at!\" (Mûsâ attığı kocaman) asâ’sının küçük bir yılan gibi titreş(ip hareket et)tiğini görünce (korkudan) öyle dönüp kaçtı (ki) arkasına bile bakmadı: \"Ey Mûsâ, dön, korkma, sen güvende olanlardansın.\""},{"n":32,"t":"\"Elini koynuna sok, kusursuz olarak bembeyaz çıksın. Ve kanadını korkudan kendine çek. İşte bunlar, Fir’avn’a ve onun adamlarına (göstermek için) Rabbinden sana verilen iki delildir. Çünkü onlar yoldan çıkan bir kavim olmuşlardır.\""},{"n":33,"t":"\"Rabbim, dedi, ben onlardan bir kişi öldürmüştüm, beni öldüreceklerinden korkuyorum.\""},{"n":34,"t":"\"Kardeşim Hârûn, o, dil bakımından benden daha güzel konuşur. Onu da benimle beraber, beni doğrulayan bir yardımcı olarak gönder. Zira ben, beni yalanlayacaklarından korkuyorum.\""},{"n":35,"t":"(Allâh) dedi: \"Senin pazunu kardeşinle kuvvetlendireceğiz ve size öyle bir yetki vereceğiz ki, âyetlerimiz sayesinde onlar size asla erişemeycekler. İkiniz ve size uyanlar üstün geleceksiniz!\""},{"n":36,"t":"Mûsâ, onlara açık açık âyetlerimizle gelince: \"Bu uydurulmuş bir büyüden başka bir şey değildir. İlk atalarımız arasında böyle bir şey (olduğunu) işitmedik.\" dediler."},{"n":37,"t":"Mûsâ, \"Rabbim, kimin kendisinin yanından hidâyet getirdiğini ve bu (dünyâ) evin(in) sonun(da güzel sonuc)un kime âidolacağını daha iyi biliyor. Muhakkak ki zâlimler iflah olmaz\" dedi."},{"n":38,"t":"Fir’avn dedi ki: \"Ey ileri gelenler, ben sizin için benden başka bir tanrı bilmiyorum, ey Hâmân, haydi benim için çamurun üzerinde ateş yak(arak tuğla imal et de) bana bir kule yap, belki Mûsâ’nın tanrısına çıkarım, çünkü ben onu (Mûsâ’yı) yalancılardan sanıyorum.\""},{"n":39,"t":"O (Fir’avn) ve askerleri yeryüzünde haksız yere büyüklük tasladılar ve kendilerinin bize döndürülmeyeceklerini sandılar."},{"n":40,"t":"Biz de onu ve askerlerini tuttuk, suya attık; bak, o zâlimlerin sonu nasıl oldu!"},{"n":41,"t":"Biz onları ateşe çağıran önderler yaptık. Kıyâmet günü asla yardım olunmazlar."},{"n":42,"t":"Bu dünyâ hayâtında biz onların ardına bir la’net taktık (dâimâ la’netle anılacaklardır). Kıyâmet günü ise onlar çirkinleştirilenlerdendir."},{"n":43,"t":"Andolsun biz, ilk nesilleri (Nûh, Hûd, Sâlih ve Lût kavimlerini) helâk ettikten sonra Mûsâ’ya, insanların gönül gözlerini aydınlatacak nur ve onlara yol gösterici olarak Kitabı verdik, belki düşünür, öğüt alırlar diye."},{"n":44,"t":"Mûsâ’ya o işi yaptığımız (yani kendisine bildirmek istediğimiz işi ona vahyettiğimiz) vakit sen (Mukaddes Vâdinin) batı tarafında değildin, (o hâdiseyi) görenlerden de değildin."},{"n":45,"t":"Fakat biz (Mûsâ’dan sonra) birçok nesiller yarattık da onların üzerinden uzun zamanlar geçti. Sen Medyen halkı arasında oturmuş değildin ki (orada olanları görüp öğrenesin de) âyetlerimizi bunlara okuyasın. (Bu, bir yerden görme, öğrenme ile değildir, fakat) Biz seni elçi olarak gönderdik (ve bu olayları sana vahyettik)."},{"n":46,"t":"(Mûsâ’ya) ünlediğimiz zaman sen Tûr’un yanında değildin. Fakat Rabbinden bir rahmet olarak (orada geçenleri sana bildirdik) ki senden önce kendilerine bir uyarıcı gelmemiş olan toplumu uyarasın; belki düşünüp öğüt alırlar."},{"n":47,"t":"Kendi elleriyle yaptıkları (günâhları) yüzünden başlarına bir felâket geldiği zaman: \"Ey Rabbimiz, bize bir elçi gönderseydin de âyetlerine uyup mü’minlerden olsaydık.\" diyecek olmasalardı (seni göndermezdik. Bu bahanelerine fırsat vermemek için seni gönderdik)."},{"n":48,"t":"Fakat onlara katımızdan hak gelince: \"Mûsâ’ya verilenin eşi, buna da verilmeli değil miydi?\" dediler. Daha önce Mûsâ’ya verileni de inkâr etmemişler miydi? \"Birbirine destek olan iki büyü\", dediler. \"Biz hepsini inkâr ederiz\", dediler."},{"n":49,"t":"De ki: \"Eğer doğru iseniz, Allâh katından bu ikisinden (yani Mûsâ’ya ve bana inen Kitaplardan) daha doğru bir Kitap getirin de ben ona uyayım.\""},{"n":50,"t":"Eğer sana cevap veremezlerse bil ki onlar, keyiflerine uyuyorlar. Allah’tan bir yol gösterici olmadan, yalnız kendi keyfine uyandan daha sapık kim olabilir? Muhakkak ki Allâh, zâlim kavmi doğru yola iletmez."},{"n":51,"t":"Andolsun biz, düşünüp öğüt alsınlar diye onlar için sözü(müzü) birbirine bitiştirdik (ardı ardına gerçeği kanıtlayan âyetler gönderdik)."},{"n":52,"t":"Bundan önce kendilerine Kitap verdiklerimiz, bu (Kur’â)n’a inanırlar."},{"n":53,"t":"Onlara (Kur’ân) okunduğu zaman: \"Ona inandık, o, Rabbimizden gelen gerçektir... Zaten biz ondan önce de müslümanlar idik.\" derler."},{"n":54,"t":"İşte onlara, sabretmelerinden ötürü mükâfâtları iki kez verilir; onlar kötülüğü iyilikle savarlar ve kendilerine verdiğimiz rızıktan (hayır yoluna) harcarlar."},{"n":55,"t":"Boş söz işittikleri zaman ondan yüz çevirirler ve: \"Bizim işlerimiz bize, sizin işleriniz size. Size selâm olsun (haydi hoşça kalın), biz câhiller(le sohbet etmey)i istemeyiz\" derler."},{"n":56,"t":"(Ey Muhammed), sen, sevdiğini doğru yola iletemezsin, fakat Allâh, dilediğini doğru yola iletir. O, yola gelecek olanları daha iyi bilir."},{"n":57,"t":"Dediler ki: \"Biz seninle beraber doğru yola gelirsek yurdumuzdan atılırız.\" Biz onlara kendi katımızdan bir rızık olarak, her şeyin ürünlerinin toplanıp getirildiği, güvenli, dokunulmaz bir mekân vermedik mi? Fakat çokları bilmezler."},{"n":58,"t":"Biz refah içinde şımarmış nice kenti helâk ettik. İşte şunlar, onların meskenleri, onlardan sonra oralarda pek az oturuldu. Onlara hep biz vâris olduk (hepsi bize kaldı)."},{"n":59,"t":"Rabbin, Anakent (olan Mekke)de onlara âyetlerimizi okuyan bir elçi göndermedikçe ülkeleri helâk edici değildir. Ve biz, halkı zâlim olmadan ülkeleri helâk ediciler değiliz."},{"n":60,"t":"Size verilen her şey, dünyâ hayâtının geçimi ve süsüdür. Allâh’ın yanında olan ise daha hayırlı ve daha kalıcıdır. Aklınızı kullanmıyor musunuz?"},{"n":61,"t":"İmdi kendisine güzel bir söz verdiğimiz ve muhakkak o (söz verile)ne kavuşacak olan kimse; sırf kendisine dünyâ hayâtının geçici zevkini yaşattığımız ve sonra kıyâmet günü (yakalanıp) getirileceklerden olan insan gibi midir?"},{"n":62,"t":"O gün (Allâh) onlara seslenerek: \"Benim ortaklarım (olduklarını) sandığınız şeyler nerede?\" der."},{"n":63,"t":"(Azâb) söz(ü) üzerlerine hak olanlar: \"Rabbimiz, azdırdıklarımız şunlar. Kendimiz azdığımız gibi onları da azdırdık. (Biz azdık, onlar da bize uydular. Onların yaptıklarından) uzak olduğumuzu, (bu hususta bizim suçumuz olmadığını) sana arz ederiz. Zaten onlar bize tapmıyorlardı (kendi arzularına tapıyorlardı).\" derler."},{"n":64,"t":"(Allâh tarafından) onlara: \"(Bana), koştuğunuz ortakları çağırın!\" denir. Onları çağırırlar. Fakat (çağırılanlar), bunların çağrısına cevap vermezler ve (bunlar), karşılarında azâbı görürler (sanki çağırdıkları şey, azâbın kendisi olmuştur). Ne olurdu (sanki dünyâda) yola gelselerdi!"},{"n":65,"t":"(Allâh) Onlara seslenerek: \"Elçilere ne cevap verdiniz?\" dediği gün,"},{"n":66,"t":"O gün haberler, onlara kör olmuştur (yani sözler sanki kör olmuştur, hiçbir söz gelip onların ağızlarını bulamaz, yanıt verecek bir tek kelime bulamazlar) onlar, birbirlerine de soramazlar."},{"n":67,"t":"Ama kim tevbe eder, inanır ve iyi iş yaparsa, o kurtuluşa erenlerden olabilir."},{"n":68,"t":"Rabbin, dilediğini yaratır ve seçer. Seçim, onlara âit değildir. Allâh, onların ortak koştukları şeylerden uzaktır, yücedir."},{"n":69,"t":"Rabbin, onların göğüslerinin neyi gizleyip neyi açığa vurduğunu bilir."},{"n":70,"t":"O, kendisinden başka tanrı olmayan Allah’tır. İlkte de, sonda da (dünyâda da, âhirette de) hamd O’na mahsustur. Hüküm de O’nundur ve O’na döndürüleceksiniz."},{"n":71,"t":"De ki: \"Baksanıza, eğer Allâh, üzerinize geceyi kıyâmet gününe kadar sürekli kılsa Allah’tan başka size ışık getirecek tanrı kimdir? (Söyleyin), işitmiyor musunuz?\""},{"n":72,"t":"De ki: \"Baksanıza, eğer Allâh, üzerinize gündüzü, kıyâmet gününe kadar sürekli kılsa, Allah’tan başka, size dinleneceğiniz geceyi getirecek tanrı kimdir? Görmüyor musunuz?\""},{"n":73,"t":"Rahmetinden dolayı sizin için geceyi ve gündüzü var etti ki, geceleyin dinlenesiniz ve (gündüzün) Allâh’ın lutfunu arayasınız ve (Allâh’ın ni’metine) şükredesiniz."},{"n":74,"t":"O gün onlara seslenerek: \"Ortaklarım sandığınız şeyler nerede?\" der."},{"n":75,"t":"Her ümmetten bir şâhid çıkarırız: \"Delilinizi getirin!\" deriz. Gerçeğin Allah’a âidolduğunu bilirler ve uydurdukları şeyler kendilerinden sapıp gider."},{"n":76,"t":"Kârûn, Mûsâ’nın kavminden idi. Onlara karşı azgınlık etti. Biz kendisine öyle hazineler vermiştik ki onun (hazinelerinin) anahtarlarını (taşımak), güçlü bir topluluğa ağır geliyordu. Kavmi ona demişti ki: \"Şımarma, Allâh, şımarıkları sevmez.\""},{"n":77,"t":"\"Allâh’ın sana verdiği (bu servet) içinde âhiret yurdunu ara, dünyâdan da nasibini unutma, Allâh sana nasıl iyilik ettiyse sen de öyle iyilik et, yeryüzünde bozgunculuk (etmeyi) isteme, çünkü Allâh bozguncuları sevmez.\""},{"n":78,"t":"\"Bu (servet) bende bulunan bir bilgi sayesinde bana verildi\" dedi. Bilmedi mi ki Allâh, kendisinden önceki kuşaklar arasında kendisinden daha güçlü ve daha çok cemaati bulunan nice kimseleri helâk etmiştir? Suçlulara günâhlarından sorulmaz."},{"n":79,"t":"(Kârûn) süsü, (debdebesi) içinde kavminin karşısına çıktı. dünyâ hayâtını isteyenler: \"Keşke Kârûn’a verilenin bir benzeri de bize verilseydi, dediler, gerçekten onun büyük şansı var!\""},{"n":80,"t":"Kendilerine bilgi verilmiş olanlar ise: \"Yazık size, dediler, inanan ve iyi iş yapan kimse için Allâh’ın sevâbı daha hayırlıdır. Buna ancak sabredenler kavuşturulur.\""},{"n":81,"t":"Nihâyet onu da, evini barkını da yere batırdık. Allah’a karşı ona yardım edecek bir topluluğu olmadı. Kendi kendini (savunup) kurtaranlardan da değildi."},{"n":82,"t":"Dün onun yerinde olmayı isteyenler: \"Vay, demek Allâh kullarından dilediğine rızkı açar ve kısar. Allâh bize lutfetmiş olmasaydı, bizi de yere batırırdı. Demek gerçekten kâfirler iflâh olmaz!\" demeğe başladılar."},{"n":83,"t":"İşte âhiret yurdu: Onu yeryüzünde böbürlenmek ve bozgunculuk yapmak istemeyenlere veririz. (Güzel) sonuç, (günâhlardan) sakınanlarındır."},{"n":84,"t":"Kim bir iyilik getirirse ona ondan daha güzeli vardır. Kim kötülük getirirse, kötülükleri yapanlar, ancak yaptıkları (kötülük) kadar cezâlanırlar."},{"n":85,"t":"Kur’ân’ı sana (indiren ve) gerekli kılan (Allâh), elbette seni varılacak yere döndürecektir. De ki: \"Rabbim kimin hidâyet getirdiğini ve kimin apaçık bir sapıklık içinde bulunduğunu bilir.\""},{"n":86,"t":"Sen, o Kitabın, senin kalbine bırakılacağını ummazdın. Ancak Rabbinden bir rahmet olarak (Kitap senin kalbine bırakıldı). O halde kâfirlere arka olma."},{"n":87,"t":"Ve Allâh’ın, âyetleri sana indirildikten sonra sakın seni onlardan alıkoymasınlar. Rabbine da’vet et, ortak koşanlardan olma."},{"n":88,"t":"Allâh ile beraber başka bir tanrıya yalvarma. O’ndan başka tanrı yoktur. O’nun yüzü (zatı)ndan başka herşey helâk olacaktır. Hüküm O’nundur ve O’na döndürüleceksiniz."}],[{"n":1,"t":"Elif lâm mim."},{"n":2,"t":"İnsanlar yalnız \"inandık\" demekle, hiç sınanmadan bırakılacaklarını mı sandılar?"},{"n":3,"t":"Andolsun biz, onlardan öncekilerini sınadık. Elbette Allâh (sınayıp) doğruları bilecek, yalancıları bilecektir."},{"n":4,"t":"Yoksa kötülükleri yapanlar, bizi geçeceklerini (bizim, kendilerine yetişip onları cezâlandıramayacağımızı) mı sandılar? Ne kötü hüküm veriyorlar."},{"n":5,"t":"Kim Allâh ile buluşmayı umarsa; Allâh’ın (buluşma) süresi gelmektedir. O, işitendir, bilendir."},{"n":6,"t":"Kim cihâd ederse ancak kendi yararına cihâd eder. Allâh, âlemlerden zengindir. (Kimsenin cihâdına muhtaç değildir. İnsanların cihâd ve ibâdetleri kendi menfaatleri içindir)."},{"n":7,"t":"İnanıp iyi işler yapanların, mutlaka kötülüklerini örteceğiz ve onları, yaptıklarının en güzeliyle mükâfâtlandıracağız."},{"n":8,"t":"Biz insana ana babasına iyilik etmeyi tavsiye ettik. Eğer onlar seni, (gerçekliği) hakkında hiçbir bilgin olmayan bir şeyi bana ortak koşman için zorlarlarsa (bu hususta) onlara itâ’at etme. Dönüşünüz banadır. O zaman size yaptıklarınızı haber veririm."},{"n":9,"t":"İnanıp iyi işler yapanları, sâlihler arasına sokarız."},{"n":10,"t":"İnsanlardan kimi vardır ki \"Allah’a inandık.\" der, fakat Allâh uğrunda kendisine eziyet edilince insanların işkencesini, Allâh’ın azâbı gibi sayar. Ama Rabbinden (sana) bir yardım gelse, andolsun: \"Biz de sizinle beraberdik,\" derler. Allâh, âlemlerin göğüslerinde bulunan (düşünceler)i daha iyi bilmez mi?"},{"n":11,"t":"Allâh, elbette inananları da bilir ve elbette iki yüzlüleri de bilir."},{"n":12,"t":"İnkâr edenler, inananlara: \"Siz bizim yolumuza uyun. Sizin hatâlarınızı biz taşırız\" dediler. Oysa kendileri, onların hatâlarından hiçbir şey taşıyacak değillerdir. Onlar tamamen yalancıdırlar."},{"n":13,"t":"Onlar, hem kendi yüklerini, hem de kendi yükleriyle beraber başka yükleri (başkalarını kandırıp saptırmalarının vebâlini) taşıyacaklar ve elbette uydurdukları şeylerden kıyâmet gününde sorguya çekileceklerdir."},{"n":14,"t":"Andolsun biz, Nûh’u kavmine gönderdik, onların arasında bin seneden elli yıl eksik kaldı (öğüt verdi, dinlemediler), sonunda haksızlık etmekte olan insanları Tûfân yakaladı."},{"n":15,"t":"Onu ve gemi halkını kurtardık ve o gemiyi âlemlere bir ibret yaptık."},{"n":16,"t":"İbrâhim’i de (gönderdik). Kavmine dedi ki: \"Allah’a kulluk edin, O’ndan korkun, bilirseniz bu, sizin için daha hayırlıdır.\""},{"n":17,"t":"\"Siz Allah’tan başka bir takım putlara tapıyorsunuz, yalan şeyler uyduruyorsunuz. Sizin Allah’tan başka taptıklarınız, size rızık vermezler. Siz rızkı Allâh’ın yanında arayın, O’na tapın ve O’na şükredin. O’na döndürüleceksiniz.\""},{"n":18,"t":"\"Eğer yalanlarsanız, sizden önceki ümmetler de yalanlamışlardı. Elçiye düşen, yalnız açıkça duyurmaktıır.\""},{"n":19,"t":"Görmediler mi Allâh nasıl yaratmayı başlatıyor, sonra onu iâde ediyor (dönüp yeniden yaratıyor). Bu, Allah’a göre kolaydır."},{"n":20,"t":"De ki: \"Yeryüzünde gezin, bakın yaratmağa nasıl başladı, sonra Allâh, son yaratmayı da yapacaktır. Çünkü Allâh, her şeyi yapabilendir."},{"n":21,"t":"Dilediğine azâbeder, dilediğine acır ve hepiniz O’na çevrilirsiniz."},{"n":22,"t":"Siz, ne yerde, ne de gökte Allâh’(ın yapacağı iş)i engelleyemezsiniz. Sizin Allah’tan başka ne bir koruyucunuz, ne de bir yardımcınız vardır."},{"n":23,"t":"Allâh’ın âyetlerini ve O’nunla buluşmayı inkâr edenler, işte onlar benim rahmetimden ümidi kesmişlerdir ve onlar için acı bir azâb vardır."},{"n":24,"t":"Kavminin (İbrâhim’e) cevabı, sâdece: \"Onu öldürün, yahut yakın!\" demeleri oldu. Allâh onu ateşten kurtardı. Şüphesiz bunda inanan bir toplum için ibretler vardır."},{"n":25,"t":"(İbrâhim kavmine) dedi ki: \"Siz dünyâ hayâtında birbirinizi sevmek için Allâh’ı bırakıp birtakım putlar edindiniz. (O putlara tapmanız, dünyâda aranızda bir sevgi meydana gelmesine sebep olsa bile) daha sonra kıyâmet gününde birbirinizi inkâr eder ve birbirinizi la’netlersiniz. Varacağınız yer de ateştir ve hiçbir yardımcınız da yoktur."},{"n":26,"t":"Bunun üzerine Lût ona inandı ve (İbrâhim, kavmine) dedi ki: \"Rabbim(e ibadet edeceğim yer)e göç edeceğim. Kuşkusuz O, gâlibdir, hüküm ve hikmet sâhibidir.\""},{"n":27,"t":"Biz ona İshak’ı ve (torunu) Ya’kûb’u armağan ettik. Onun nesli içine peygamberlik ve Kitap koyduk. Ona dünyâda (yaptığı güzel işin) karşılığını verdik. Şüphesiz o, âhirette de iyilerdendir."},{"n":28,"t":"Lût’u da (gönderdik). Kavmine dedi ki: \"Siz, sizden önce âlemlerden hiç kimsenin yapmadığı bir fuhşa gidiyorsunuz.\""},{"n":29,"t":"\"Siz (kadınları bırakıp) erkeklere gidiyorsunuz, yol kesiyorsunuz ve toplantılarınızda edepsizce şeyler yapıyorsunuz ha?..\" Kavmi’nin cevabı, sadece: \"Eğer doğrulardan isen, haydi Allâh’ın azâbını getir!\" demeleri oldu."},{"n":30,"t":"(Lût): \"Rabbim, şu bozguncu kavme karşı bana yardım et,\" dedi."},{"n":31,"t":"Elçilerimiz İbrâhim’e (oğlu olacağına dâir) müjdeyi getirdikleri zaman dediler ki: \"Biz şu (Sodom) kenti(ni)n halkını helâk edeceğiz. Çünkü oranın halkı zâlim oldular.\""},{"n":32,"t":"(İbrâhim) dedi: \"Ama orada Lût var?\" Dediler: \"Biz orada kimin bulunduğunu daha iyi biliriz. Onu ve âilesini kurtaracağız. Yalnız karısı (azâbda) kalacaklardandır.\""},{"n":33,"t":"Elçilerimiz Lût’a gelince (Lût) onlar yüzünden fenalaştı ve onlar hakkında arşını daraldı. (Melekler): \"Korkma üzülme dediler, biz seni ve âileni kurtaracağız, yalnız karın kalacaklardan olmuştur.\""},{"n":34,"t":"\"Biz yoldan çıkan şu ülke halkının üstüne gökten bir azâb indireceğiz.\""},{"n":35,"t":"Andolsun biz, aklını kullanan bir toplum için ondan, (harâb ettiğimiz o ülkeden) açık bir işâret bırakmışızdır."},{"n":36,"t":"Medyen’e de kardeşleri Şuayb’i (gönderdik): \"Ey kavmim, dedi, Allah’a kuluk edin, âhiret gününü umun, yeryüzünde karışıklık çıkarıp bozgunculuk yapmayın!\""},{"n":37,"t":"Onu yalanladılar, bu yüzden onları (o müthiş) deprem yakaladı, yurtlarında diz üstü çöküp kaldılar."},{"n":38,"t":"Âd ve Semûd’u da (helâk ettik). Bu, oturdukları yerlerden size belli olmaktadır. Şeytân onlara yaptıkları işleri süsleyip onları yoldan çıkardı. Oysa bakıp ibret alabilirlerdi (ama almadılar)."},{"n":39,"t":"Kaarûn’u, Fir’avn’ı, Hâmân’ı da (helâk ettik). Andolsun, Mûsâ onlara açık kanıtlar getirdi, fakat onlar o yerde büyüklük tasla(yıp âyetlerimizi kabule tenezzül etme) diler. Ama geçip gidecek, (elimizden kurtulacak) değillerdi."},{"n":40,"t":"Nitekim hepsini günâhiyle yakaladık. Onlardan kiminin üstüne taş yağdıran bir fırtına gönderdik, kimini korkunç ses yakaladı, kimini yere batırdık, kimini de boğduk. Allâh onlara zulmedecek değildi; fakat onlar, kendi kendilerine zulmediyorlardı."},{"n":41,"t":"Allah’tan başka veliler edinenler, bir ev edinen örümceğe benzerler. Evlerin en gevşeği örümcek evidir, keşke bilselerdi."},{"n":42,"t":"Allâh, onların kendisinden başka ne gibi şeylere yalvardıklarını bilir, O üstündür, hüküm ve hikmet sâhibidir."},{"n":43,"t":"Biz bu misalleri insanlara anlatıyoruz ama onları, bilenlerden başkası düşünüp anlamaz."},{"n":44,"t":"Allâh, gökleri ve yeri hak ile yarattı. Şüphesiz bunda inananlar için bir ibret vardır."},{"n":45,"t":"Kitaptan sana vahyedileni oku ve namazı da kıl. Çünkü namaz kötü ve iğrenç şeylerden meneder. Elbette Allâh’ı anmak, en büyük (ibâdet)tir. Allâh, ne yaptığınızı bilir."},{"n":46,"t":"Kitâp ehliyle, -haksızlık edenleri dışında- en güzel tarzda tartışın ve deyin ki: \"Bize indirilene de size indirilene de inandık. Tanrımız ve tanrınız birdir, biz de O’na teslim olanlarız.\""},{"n":47,"t":"İşte böylece Kitabı sana da indirdik. Kendilerine Kitabı verdiklerimiz, ona inanırlar: Şunlardan (şu Araplardan) da ona inananlar vardır. Âyetlerimizi, kâfirlerden başkası inkâr etmez."},{"n":48,"t":"(Ey Muhammed) Sen bundan önce bir Kitap okumuyordun, elinle de onu yazmıyorsun. Öyle olsaydı o zaman (Allâh’ın sözlerini boşa çıkarmaya çalışan) iptalciler, kuşkulanırlardı."},{"n":49,"t":"Hayır, o (sana vahyedilenler) kendilerine bilgi verilmiş olanların göğüslerinde bulunan açık açık âyetlerdir. Bizim âyetlerimizi, zâlimlerden başkası inkâr etmez."},{"n":50,"t":"Dediler ki: \"Ona Rabbinden âyetler indirilmeli değil miydi?\" De ki: \"Âyetler (mu’cizeler) Allâh’ın yanındadır. Ben ancak apaçık bir uyarıcıyım.\""},{"n":51,"t":"Kendilerine okunan Kitabı sana indirmemiz, onlara yetmedi mi? Şüphesiz inanan bir toplum için bunda bir rahmet ve öğüt vardır."},{"n":52,"t":"De ki: \"Benimle sizin aranızda şâhid olarak Allâh yeter. O, göklerde ve yerde olanları bilir. Bâtıla inanıp Allah’a karşı nankörlük edenler, işte ziyana uğrayacaklar onlardır.\""},{"n":53,"t":"Senden azâbı çabuk istiyorlar. Eğer (azâb için) belirtilmiş bir süre olmasaydı, onlara hemen azâb gelirdi. Fakat hiç farkına varmadıkları bir sırada o, kendilerine ansızın gelecektir."},{"n":54,"t":"Cehennem o nankörleri kuşatmış iken, onlar hâlâ senden azâbı çabuk istiyorlar."},{"n":55,"t":"O gün azâb, onları üstlerinden, ayaklarının altından örter ve (Allâh onlara): \"Yaptığınız işleri tadın!\" der."},{"n":56,"t":"Ey inanan kullarım, benim arzım geniştir, bana kulluk edin."},{"n":57,"t":"Her can, ölümü tadacaktır. Sonra bize döndürüleceksiniz."},{"n":58,"t":"İnanıp iyi işler yapanları, cennette, altlarından ırmaklar akan yüksek odalara yerleştiririz. Orada ebedi kalırlar. Çalışanların ücreti ne güzeldir!"},{"n":59,"t":"Onlar ki sabrettiler ve Rabblerine dayanmaktadırlar"},{"n":60,"t":"Nice canlı var ki rızkını taşıyamaz, onları da sizi de Allâh besler. O, işitendir, bilendir."},{"n":61,"t":"Andolsun, onlara: \"Gökleri ve yeri kim yarattı, güneşi ve ayı kim (sizin yararınıza) boyun eğdirdi?\" desen; \"Allâh\", derler. O halde nasıl Allâh’ın (birliğinden) döndürülüyorsunuz?"},{"n":62,"t":"Allâh kullarından dilediğine rızkı açar da, kısar da. Şüphesiz Allâh, her şeyi bilendir."},{"n":63,"t":"Onlara: \"Kim gökten suyu indirip de ölmüş olan yeri onunla diriltti?\" diye sorsan; \"Allâh\", derler. De ki: \"Hamd (övgü), Allah’a lâyıktır.\" Doğrusu çokları düşünmezler."},{"n":64,"t":"Bu dünyâ hayâtı eğlence ve oyundan başka bir şey değildir. Âhiret yurdu, işte asıl hayât odur (asıl yaşanacak yer orasıdır), keşke bilselerdi!"},{"n":65,"t":"Gemiye bindikleri zaman, dini yalnız Allah’a hâlis kılarak O’na yalvarırlar. Fakat (Allâh) onları salimen karaya çıkarınca hemen (O’na) ortak koşarlar."},{"n":66,"t":"Ki kendilerine verdiğimiz (ni’metler)e nankörlük etsinler ve (şu geçici hayâtta) zevk içinde yaşasınlar. Ama yakında (gerçeği) bileceklerdir."},{"n":67,"t":"Görmediler mi çevrelerinde insanlar kaçırılırken biz (kendi şehirleri Mekke’yi), güvenli, dokunulmaz bir bölge yaptık? Hâlâ bâtıla inanıp Allâh’ın ni’metine nankörlük mü ediyorlar?"},{"n":68,"t":"Uydurduğu yalanı Allâh’ın üzerine atan veya kendisine gelen gerçeği yalanlayandan daha zâlim kimdir? Kâfirlerin durağı cehennemde değil midir?"},{"n":69,"t":"Ama biz(im uğrumuz)da cihâd edenleri biz, elbette yollarımıza iletiriz. Muhakkak ki Allâh, iyilik edenlerle beraberdir."}],[{"n":1,"t":"Elif lâm mim."},{"n":2,"t":"Rum(lar), yenildi:"},{"n":3,"t":"(Bölgeye) En yakın bir yerde. Onlar (bu) yenilgilerinden sonra yeneceklerdir;"},{"n":4,"t":"Birkaç yıl içinde. (Onların) Bu (yenilgileri)nden önce de, sonra da emir Allâh’ındır (ferman O’nundur). O gün mü’minler sevinir(ler)."},{"n":5,"t":"Allâh’ın yardımıyle. (Allâh) Dilediğine yardım eder. O, gâliptir, esirgeyendir."},{"n":6,"t":"(Bu,) Allâh’ın va’didir. Allâh va’dinden caymaz; fakat insanların çoğu bilmezler."},{"n":7,"t":"Onlar, sadece şu yakın hayâtın dış yüzünü bilirler; âhiretten ise onlar tamamen gâfildirler."},{"n":8,"t":"Kendi içlerinde hiç düşünmediler mi ki Allâh, göklerde, yerde ve bu ikisi arasında bulunan her şeyi ancak hak olarak ve belirtilmiş bir süre ile yaratmıştır? İnsanlardan çoğu, Rabblerine kavuşmayı inkâr etmektedirler."},{"n":9,"t":"Yeryüzünde gezmediler mi ki, kendilerinden öncekilerin sonunun nasıl olduğuna baksınlar. Onlar, kendilerinden daha güçlü idiler; (sular, madenler çıkarmak, ekin ekmek, ağaç dikmek için) toprağı (kazmış), alt üst etmişler ve onu, bunların imar ettiklerinden daha çok imar etmişlerdi. Onlara da elçileri, deliller getirmişti. Allâh onlara zulmedecek değildi. Fakat onlar, kendi kendilerine zulmediyorlardı."},{"n":10,"t":"Sonra kötülük edenlerin sonu çok kötü oldu. Çünkü Allâh’ın âyetlerini yalanladılar. Ve onlarla alay ediyorlardı."},{"n":11,"t":"Allâh, yaratmağa başlar, sonra onu çevirip yeniden yapar; sonra O’na döndürülürsünüz."},{"n":12,"t":"(Duruşma) Sâat(i) başladığı gün, suçlular (umutsuzluk içinde) susarlar."},{"n":13,"t":"(Allah’a) ortak (koştukları put)larından da kendilerine hiçbir şefâ’atçi çıkmaz. O zaman ortaklarını inkâr ederler."},{"n":14,"t":"O sâat başladığı gün, o gün (inananlar ve inanmayanlar) ayrılırlar:"},{"n":15,"t":"İnanıp iyi işler yapanlar, onlar (çiçekli, ırmaklı) bir bahçe içinde neş’elendirilirler."},{"n":16,"t":"Fakat inkâr edip âyetlerimizi ve âhiret buluşmasını yalanlayanlara gelince, onlar da (tutuklanıp) azâbın içine getirilirler."},{"n":17,"t":"Öyle ise akşama girdiğiniz zaman da, sabaha erdiğiniz zaman da tesbih Allâh’ındır (O’nun şanının yüceliği anılır)."},{"n":18,"t":"Göklerde ve yerde, günün sonunda da, öğleye erdiğiniz zaman da hamd, O’na mahsustur."},{"n":19,"t":"(Allâh), ölüden diri çıkarır, diriden ölü çıkarır; yeri ölümünden sonra diriltir. İşte siz de (bedensel hayâta) öyle çıkarılacaksınız."},{"n":20,"t":"O’nun âyetlerinden (gücünün işâretlerinden) biri sizi topraktan yaratmasıdır. Sonra siz, (yeryüzüne) yayılan insan(lar) oluverdiniz."},{"n":21,"t":"O’nun âyetlerinden biri de, size nefislerinizden, sâkinleşeceğiniz eşler yaratması ve aranıza sevgi ve acıma koymasıdır. Şüphesiz bunda, düşünen bir toplum için ibretler vardır."},{"n":22,"t":"O’nun âyetlerinden biri de göklerin ve yerin yaratılması, dillerinizin ve renklerinizin değişik olmasıdır. Şüphesiz bunda, bilenler için ibretler vardır."},{"n":23,"t":"O’nun âyetlerinden biri de, geceleyin ve gündüzün uyumanız ve O’nun lutfundan (nasibinizi) aramanızdır. Şüphesiz bunda, işiten bir toplum için ibretler vardır."},{"n":24,"t":"O’nun âyetlerinden biri de, size, korku ve umut vermek için şimşeği göstermesi, gökten bir su indirip onunla ölümünden sonra yeri diriltmesidir. Şüphesiz bunda, aklını kullanan bir toplum için ibretler vardır."},{"n":25,"t":"O’nun âyetlerinden biri de göğün ve yerin, kendisinin buyruğuyla durmasıdır. Sonra sizi yerden bir tek da’vetle çağırdığı zaman bir de bakarsınız ki çıkıyorsunuz."},{"n":26,"t":"Göklerde ve yerde bulunan kimseler hep O’nundur, hepsi O’na itâ’at etmektedirler."},{"n":27,"t":"Yaratmağa başlayan O’dur. Sonra onu çevirip yeniden yapar. Bu, O’na daha kolaydır. Göklerde ve yerde en yüce durum O’nundur (En büyük kudret ve şeref misali O’dur). O, üstündür, hüküm ve hikmet sâhibidir."},{"n":28,"t":"Size kendinizden bir misal verdi: (Bakın) size verdiğimiz rızıklarda; sizin ellerinizin altında bulunan(köleler, hizmetçi)lerden sizinle eşit derecede (yönetim hakkına sâhip) olan, birbiriniz(in hakkına dokunmak)dan çekindiğiniz gibi onlar(ın hakkına dokunmak)dan da çekindiğiniz ortaklar var mı (ki tutup kendi mülkümüzde, saltanatımızda bize ortaklar atfediyorsunuz, kendi kullarımızı, yaratıklarımızı bize eş koşuyorsunuz)? İşte biz, aklını kullanan bir toplum için âyetleri böyle açıklıyoruz."},{"n":29,"t":"Hayır, zulmedenler, bilgisizce keyiflerine uydular. Allâh’ın şaşırttığını (Allâh’ın gönderdiği hidâyete uymadığı için düştüğü sapıklığında terk ettiği kimseyi) kim yola getirebilir? Onların hiçbir yardımcıları yoktur."},{"n":30,"t":"Sen yüzünü, Allâh’ı birleyici olarak doğruca dine çevir: Allâh’ın yaratma yasasına (uygun olan dine dön) ki, insanları ona göre yaratmıştır. Allâh’ın yaratması değiştirilemez. İşte doğru din odur. Fakat insanların çoğu bilmezler."},{"n":31,"t":"Yalnız O’na yönelin ve O’ndan korkun; namazı kılın ve (Allah’a) ortak koşanlardan olmayın."},{"n":32,"t":"(O ortak koşanlardan olmayın ki onlar) Dinlerini parçaladılar ve bölük bölük oldular. Her parti kendi yanındakiyle sevin(ip övün)mektedir."},{"n":33,"t":"İnsanlara bir zarar dokundu mu, Rablerine yönelerek O’na yalvarırlar. Sonra (Rableri), onlara kendinden bir rahmet taddırınca, hemen onlardan bir grup, Rablerine ortak koşarlar."},{"n":34,"t":"(Böyle yaparlar) ki kendilerine verdiğimiz (ni’met)e karşı nankörlük etsinler. Şimdi zevk içinde yaşayın bakalım, yakında (sonunuzun ne olduğunu) bileceksiniz."},{"n":35,"t":"Yoksa onlara bir delil indirmişiz de o mu (Allah’a) ortak koşmalarını söylüyor?"},{"n":36,"t":"Biz insanlara bir rahmet taddırdığımız zaman onunla sevinirler. Elleriyle yapıp öne sürdükleri(işleri)nden dolayı onlara bir kötülük erişince de, derhal umutsuzluğa düşerler."},{"n":37,"t":"Görmediler mi, Allâh dilediğine rızkı genişletiyor da, daraltıyor da. Şüphesiz inanan bir toplum için bunda ibretler vardır."},{"n":38,"t":"Akrabâya, yoksula, yolcuya (zekât ve sadakadan) hakkını ver. Allâh’ın yüzünü (rızâsını) isteyenler için bu, daha hayırlıdır ve onlar başarıya erenlerdir."},{"n":39,"t":"İnsanların malları içinde, artması için verdiğiniz ribâ, Allâh katında artmaz. Ama Allâh’ın yüzünü (O’nun rızâsını) isteyerek verdiğiniz zekât(a gelince); işte (onu verenler sevâplarını ve mallarını) kat kat artıranlardır."},{"n":40,"t":"Allâh sizi yarattı, sonra besledi, sonra öldürüyor, sonra diriltiyor. Ortaklarınız içinde bunlardan birini yapan var mı? O, onların ortak koştukları şeylerden uzak ve yücedir."},{"n":41,"t":"İnsanların elleriyle kazandıkları (günâhları) yüzünden, karada ve denizde fesat çıktı. Belki dönerler diye, (Allâh) onlara, yaptıklarının bir kısmını taddırıyor."},{"n":42,"t":"De ki: \"Yeryüzünde gezin, öncekilerin sonunun nasıl olduğuna bakın.\" Onların da çoğu ortak koşanlardan idi."},{"n":43,"t":"Allah’tan, geri çevirilmesi mümkün olmayan gün gelmezden önce, yüzünü dosdoğru dine yönelt. O gün (insanlar) bölük bölük ayrılırlar (bir bölük cennete, öbür bölük ateşe gider)."},{"n":44,"t":"Kim inkâr ederse, inkârı kendi aleyhinedir. İyi bir iş yapanlar da (cennette) kendileri için yer hazırlamaktadırlar."},{"n":45,"t":"Tâ ki Allâh, inanıp iyi işler yapanları lutfundan mükâfâtlandırsın. Doğrusu O, kâfirleri sevmez."},{"n":46,"t":"O’nun âyetlerinden biri de (şudur): Rüzgârları (yağmurun) müjdeleri olarak gönderir ki size rahmetinden biraz taddırsın, gemiler buyruğuyla yürüsün ve siz O’nun lutfundan arayasınız da (verdiği ni’metlere) şükredesiniz."},{"n":47,"t":"Andolsun ki, biz senden önce de elçileri kavimlerine gönderdik; onlara deliller getirdiler ve biz, (onları dinlemeyip) suç işleyenlerden öc aldık. (Elbette alırız, çünkü) mü’minlere yardım etmek, üzerimize borç idi."},{"n":48,"t":"Allâh, rüzgârları gönderir, bulutu kaldırır; sonra onu gökte dilediği gibi yayar ve parça parça eder; arasından yağmurun çıktığını görürsün. Derken, onu kullarından dilediğine uğratınca hemen sevinirler."},{"n":49,"t":"Halbuki onlar, yağmurun kendilerine indirilmesinden önce umutsuz idiler."},{"n":50,"t":"Allâh’ın rahmetinin eserlerine bak ki, nasıl yeri ölümünden sonra diriltiyor? Şüphe yok ki, O, ölüleri de diriltecektir, O her şeye kâdirdir."},{"n":51,"t":"Andolsun bir rüzgâr, göndersek de o (eki)ni sararmış görseler, ondan sonra nankörlük etmeğe başlarlar."},{"n":52,"t":"Sen de ölülere söz dinletemezsin; arkalarını dönüp giden sağırlara çağrıyı işittiremezsin."},{"n":53,"t":"Ve sen, körleri de sapıklıklarından çıkarıp yola getiremezsin. Sen ancak, âyetlerimize inananlara işittirirsin de onlar müslüman olurlar."},{"n":54,"t":"Allah’tır ki sizi zayıflıktan yarattı. Sonra zayıflığın ardından (size) bir kuvvet verdi. Sonra kuvvetin ardından da zayıflık ve ihtiyarlık verdi. Allâh, dilediğini yaratır, O, bilendir, gücü yetendir."},{"n":55,"t":"(Duruşma) Sâ’at(i) başladığı gün, suçlular, (dünyâda veya Berzahta) bir sâ’atten fazla kalmadıklarına yemin ederler. İşte onlar, (dünyâda da haktan) böyle çevriliyorlardı."},{"n":56,"t":"Kendilerine bilgi ve iman verilenler dediler ki: \"Andolsun siz, Allâh’ın yazgısınca tâ yeniden dirilme gününe kadar kaldınız. İşte bu da dirilme günüdür. Fakat siz bilmiyordunuz."},{"n":57,"t":"Artık zulmetmiş olanlara o gün, ne mazeretleri fayda verir ve ne de onlardan rızâ taleb etmeleri istenir."},{"n":58,"t":"Andolsun biz bu Kur’ân’da insanlara her çeşit misali getirip anlattık. Onlara bir âyet getirdiğin zaman inkâr edenler: \"Siz (geleneklerimizi) iptal edenlerden başka bir şey değilsiniz.\" derler."},{"n":59,"t":"İşte Allâh, bilmeyenlerin kalblerini böyle mühürler."},{"n":60,"t":"Sabret, Allâh’ın va’di haktır (o mutlaka yerine gelecektir). İnanmayanlar seni telâşa düşürmesin."}],[{"n":1,"t":"Elif lâm mim"},{"n":2,"t":"Şunlar, hikmetli Kitabın âyetleridir."},{"n":3,"t":"Güzel davrananlara yol gösterici ve rahmet olarak (indirilmiştir)."},{"n":4,"t":"Onlar ki namazı kılarlar, zekâtı verirler ve onlar âhirete de kesin olarak inanırlar."},{"n":5,"t":"İşte onlar, Rableri tarafından (gösterilen) doğru bir yol üzerindedirler ve onlar, umduklarına ereceklerdir."},{"n":6,"t":"İnsanlardan kimi var ki; bilgisizce (insanları) Allâh’ın yolundan saptırmak ve onunla alay etmek için boş hadisi (eğlence sözünü) satın alır. İşte onlara küçük düşürücü bir azâb vardır."},{"n":7,"t":"Ona âyetlerimiz okunduğu zaman sanki onları hiç işitmemiş, sanki kulaklarında ağırlık varmış gibi büyüklük taslayarak döner. Ona acı bir azâbı müjdele."},{"n":8,"t":"İnanan ve iyi işler yapanlara ni’meti bol cennetler vardır."},{"n":9,"t":"Orada ebedi kalacaklardır. (Bu,) Allâh’ın gerçek va’didir. O üstündür, hüküm ve hikmet sâhibidir."},{"n":10,"t":"(Allâh), gökleri görebildiğiniz bir direk olmadan yarattı, sizi sarsar diye yere de sağlam ve yüksek dağlar attı ve orada her çeşit canlıyı yaydı. Gökten bir su indirdik de orada her güzel çifti bitirdik."},{"n":11,"t":"İşte bunlar, Allâh’ın yarattıklarıdır. Gösterin bana, O’ndan başka (tanrı dedik)leri(niz) ne yarattı? Doğrusu o zâlimler, açık bir sapıklık içindedirler."},{"n":12,"t":"Andolsun biz Lokman’a, \"Allah’a şükret!\" diye hikmet verdik, kim şükrederse kendisi için şükreder; kim nankörlük ederse Allâh zengindir, (onun şükrüne muhtaç değildir), övülmüştür (hamde lâyıktır)."},{"n":13,"t":"Lokman oğluna öğüt vererek demişti ki: \"Yavrum, Allah’a ortak koşma, çünkü ortak koşmak, büyük bir zulümdür.\""},{"n":14,"t":"Biz insana, ana babasını tavsiye ettik. Anası onu zayıflık üstüne zayıflık çekerek (karnında) taşımıştır. (Ona gebe kaldığından itibaren tâ doğuruncaya kadar günden güne güçsüzleşmiş, ağırlaşmıştır). Onun sütten kesilmesi de iki yıl içinde olmuştur. (Bunların hepsi, güç şeylerdir. Onun için biz insana): \"Bana ve anana babana şükret, dönüş banadır.\""},{"n":15,"t":"\"Eğer onlar seni, hakkında bilgin olmayan bir şeyi bana ortak koşman için zorlarlarsa, onlara itâ’at etme. Onlarla dünyâ (işlerin)de iyi geçin ve bana yönelen kimsenin yoluna uy. Sonra dönüşünüz banadır; (o zaman ben) size yaptıklarınızı haber vereceğim\" (diye öğüt verdik)."},{"n":16,"t":"(Lokman öğütlerine devam ederek dedi ki): \"Yavrum, (yaptığın iyilik veya kötülük), hardal dânesi ağırlığınca bir şey de olsa, bir kayanın içinde, göklerde veya yerde bulunsa Allâh mutlaka onu getirir. Çünkü Allâh latiftir (O’nun bilgisi her gizli ve ince şeye ulaşır. O, her şeyi) haber alır.\""},{"n":17,"t":"\"Yavrum namazı kıl, iyiliği emret, kötülükten vazgeçir ve başına gelene sabret. Çünkü bunlar yapılması gereken işlerdendir.\""},{"n":18,"t":"\"İnsanlara yanağını bükme (kibirlenerek boynunu bir yana büküp yüzünü insanlardan öte çevirme) ve yeryüzünde böbürlenerek yürüme. Zira Allâh, kendini beğenip övünen kimseyi sevmez.\""},{"n":19,"t":"\"Yürüyüşünde tutumlu ol, (orta yürü, ne çabuk ne de çok yavaş git, ölçülü hareket et), sesini de kıs. Çünkü seslerin en çirkini eşeklerin sesidir.\""},{"n":20,"t":"Görmediniz mi Allâh, göklerde ve yerde bulunan şeyleri size boyun eğdirdi ve size zâhir ve bâtın (dış ve iç; görülen, görülmeyen; bildiğiniz ve bilmediğiniz) ni’metlerini bol bol verdi? Yine de insanlardan kimi var ki ne bilgisi, ne yol göstereni ve ne de aydınlatıcı bir Kitabı olmadan Allâh hakkında tartışır (durur)."},{"n":21,"t":"Onlara: \"Allâh’ın indirdiğine uyun!\" dense: \"Hayır, biz babalarımızı üzerinde bulduğumuz şeye uyarız (onların yolundan gideriz)\" derler. Şeytân onları alevli ateşin azâbına çağırmış olsa da mı (babalarının izinde gidecekler)?"},{"n":22,"t":"Kim güzel davranarak özünü Allah’a teslim ederse o, en sağlam kulpa yapışmıştır. İşlerin sonu Allah’a döner."},{"n":23,"t":"Kim de inkâr ederse, onun inkârı seni üzmesin. Sonunda onların dönüşleri bizedir. O zaman yaptıklarını kendilerine haber veririz. Şüphesiz Allâh göğüslerin özünü (kalblerden ne düşünceler geçtiğini) bilir."},{"n":24,"t":"Onları biraz yaşatırız, sonra kaba bir azâba süreriz."},{"n":25,"t":"Andolsun onlara: \"Gökleri ve yeri kim yarattı? diye sorsan, mutlaka: \"Allâh\" derler. \"Hamd Allah’a lâyıktır\" de. Hayır, çokları bilmezler."},{"n":26,"t":"Göklerde ve yerde ne varsa hepsi Allâh’ındır. Allâh, işte ğani (zengin) O, övülen O’dur."},{"n":27,"t":"Yeryüzünde bulunan ağaçlar kalem olsa, deniz(ler) de (mürekkep olsa), arkasından yedi deniz (daha gelip) ona yardım etse de (Allâh’ın kelimeleri yazılsa), yine (bunlar tükenir), Allâh’ın kelimeleri tükenmez. Allâh öyle üstündür, öyle hikmet sâhibidir."},{"n":28,"t":"Sizin yaratılmanız ve diriltilmeniz, bir tek kişi(nin yaratılıp diriltilmesi) gibidir. Şüphesiz Allâh, işitendir, görendir."},{"n":29,"t":"Görmedin mi Allâh, geceyi gündüzün içine sokuyor; gündüzü gecenin içine sokuyor. Güneşi ve ayı, emrine boyun eğdirmiştir. Her biri belli bir süreye kadar akıp gider. Ve Allâh yaptıklarınızı haber almaktadır."},{"n":30,"t":"Böyledir, çünkü Allâh haktır, O’ndan başka yalvardıkları bâtıldır. Gerçekten ulu ve büyük olan, yalnız Allah’tır."},{"n":31,"t":"(Allâh) size, bir kısım âyetlerini göstersin diye, Allâh’ın ni’metiyle gemilerin denizde gittiğini görmedin mi? Şüphesiz bunda sabreden, şükreden herkes için ibretler vardır."},{"n":32,"t":"(Denizde) onları, gölgeler gibi dalga(lar) sardığı zaman, dini yalnız kendisine has kılarak Allah’a yalvarırlar. Fakat O, onları kurtarıp karaya çıkarınca içlerinden bir kısmı iktisâd eder (Allah’a yönelmeyi kısar, gevşetir); zaten bizim âyetlerimizi (öyle) nankör gaddarlardan başkası inkâr etmez."},{"n":33,"t":"Ey insanlar, Rabbinizden korkun ve babanın, çocuğunun cezâsını çekmeyeceği, çocuğun da babasının cezâsını çekmeyeceği (hiç kimse, kimsenin borcunu ödemeyeceği) günden çekinin. Allâh’ın va’di gerçektir. Dünyâ hayâtı sizi aldatmasın. O aldatıcı (şeytân), sizi Allâh hakkında (O’nun yumuşak davranmasına, mühlet vermesine güvendirerek) aldatmasın."},{"n":34,"t":"Allâh, (işte kıyâmet) sâ’atin(in ne zaman geleceği) hakkındaki bilgi, O’nun yanındadır. Yağmuru O yağdırır, rahimlerde olanı bilir. Hiç kimse yarın ne kazanacağını bilmez ve hiç kimse hangi yerde öleceğini bilmez. (Her şeyi) bilen, (her şeyden) haberi olan yalnız Allah’tır."}],[{"n":1,"t":"Elif lâm mim."},{"n":2,"t":"Şüphe yok ki Kitabın indirilişi, âlemlerin Rabbi tarafındandır."},{"n":3,"t":"Yoksa \"Onu uydurdu\" mu diyorlar? Hayır, o senden önce kendilerine hiçbir uyarıcı gelmemiş olan bir kavmi, doğru yola gelirler umuduyla uyarman için Rabbin tarafından (sana indirilen) gerçektir."},{"n":4,"t":"O (Allâh) ki gökleri, yeri ve bunlar arasında bulunanları altı günde yarattı; sonra Arş’a istivâ etti. Sizin, O’ndan başka bir dostunuz, şefâ’atçiniz yoktur. Düşünüp öğüt almıyor musunuz?"},{"n":5,"t":"(Allâh) Emri gökten yere tedbir eder (buyruğunu indirir). Sonra emir, sizin hesabınızca bin yıl süren bir gün içinde O’na çıkar."},{"n":6,"t":"İşte görünmeyeni de, görüneni de bilen, güçlü ve esirgeyici olan O’dur."},{"n":7,"t":"O’dur ki, yarattığı herşeyi güzel yaptı ve insanı yaratmağa çamurdan başladı."},{"n":8,"t":"Sonra onun neslini bir özden, hakir bir su(yun özü)nden yaptı."},{"n":9,"t":"Sonra ona biçim verdi, ona kendi ruhundan üfledi. Ve sizin için kulak(lar), gözler ve gönüller yarattı. Ne kadar az şükrediyorsunuz!"},{"n":10,"t":"\"Biz toprakta kaybolduktan sonra, yeni bir yaratılış içinde mi olacağız?\" dediler. Doğrusu onlar, Rablerine kavuşmayı inkâr edenlerdir."},{"n":11,"t":"De ki: \"Üzerinize vekil edilen ölüm meleği, canınızı alır, sonra Rabbinize döndürülürsünüz.\""},{"n":12,"t":"Rablerinin huzûrunda (utançtan) başlarını öne eğmiş; \"Rabbimiz, gördük, işittik, bizi geri döndür, iyi iş yapalım; artık kesin olarak inandık!\" demekte olan suçluları bir görsen!"},{"n":13,"t":"Dileseydik, herkese hidâyetini verirdik, (herkesi doğru yola iletirdik). Fakat benden \"Mutlaka cehennemi, cinlerden ve insanlardan bir kısmiyle tamamen dolduracağım!\" kararı çıkmıştır."},{"n":14,"t":"\"Bu gününüzle karşılaşmayı unutmanızın cezâsını tadın! (Şimdi) Biz de sizi unuttuk. Yaptıklarınızdan ötürü ebedi azâbı tadın!\""},{"n":15,"t":"Bizim âyetlerimize o kimseler inanırlar ki onlar, kendilerine öğüt verildiği zaman derhal secdeye kapanırlar; Rablerini överek tesbih ederler, büyüklük taslamazlar."},{"n":16,"t":"Yanları yataklardan uzaklaşır, (gece teheccüd namazı kılmak için yanlarını yataklardan ayırıp kalkarlar), korkarak ve umarak Rablerine du’â ederler ve kendilerine verdiğimiz rızıktan hayır için harcarlar."},{"n":17,"t":"Yaptıklarına karşılık olarak onlar için ne gözler aydınlatıcı (ni’metleri)in saklandığını hiç kimse bilmez!"},{"n":18,"t":"Hiç inanan kimse, (yoldan çıkan) fâsık gibi olur mu? Elbette bunlar bir olmazlar."},{"n":19,"t":"İnanan ve iyi işler yapanlara gelince, onlar, yaptıklarına karşılık, durulmağa değer cennetlerde ağırlanırlar."},{"n":20,"t":"Yoldan çıkanların barınacakları yer de ateştir. Ne zaman oradan çıkmak isteseler, yine oraya geri çevrilirler ve onlara: \"Yalanlamakta olduğunuz ateş azâbını tadın\" denilir."},{"n":21,"t":"Belki dön(üp yola gel)irler diye, mutlaka onlara o büyük azâbdan ayrı olarak, daha yakın azâbı da taddıracağız."},{"n":22,"t":"Kendisine Rabbinin âyetleriyle öğüt verildikten sonra onlardan yüz çevirenlerden daha zâlim kim olabilir? Muhakkak ki biz, suçlulardan öç alıcıyız."},{"n":23,"t":"Andolsun biz Mûsâ’ya Kitabı verdik. Sakın onun (Mûsâ’ya) ulaşmasından kuşkuya düşme. Onu İsrâil oğullarına yol gösterici yaptık."},{"n":24,"t":"Sabrettikleri ve âyetlerimize kesinlikle inandıkları zaman, onların içinden, buyruğumuzla doğru yola ileten önderler yetiştirmiştik."},{"n":25,"t":"Şüphesiz Rabbin, kıyâmet günü, ayrılığa düştükleri konularda onların aralarında hükmedecektir."},{"n":26,"t":"Bugün yurtlarında dolaştıkları nice kuşakları daha önce helâk etmiş olmamız, hâlâ onları yola getirmedi mi? Şüphesiz bunda ibretler vardır. (Öğüt alma kulağıyle) İşitmiyorlar mı?"},{"n":27,"t":"Görmüyorlar mı biz nasıl suyu, kuru, otsuz yere sürüyoruz da onunla ekin bitiriyoruz; ondan hayvanları da, kendileri de yiyor? Görmüyorlar mı?"},{"n":28,"t":"\"Doğru iseniz bu fetih ne zaman?\" diyorlar."},{"n":29,"t":"De ki: \"Fetih günü (gelince, şimdi) inkâr edenlere (o zaman) inanmaları fayda vermez ve kendilerine mühlet de verilmez."},{"n":30,"t":"Sen onlardan yüz çevir ve bekle, zaten onlar da beklemektedirler."}],[{"n":1,"t":"Ey peygamber, Allah’tan kork; kâfirlere ve münâfıklara itâ’at etme. Şüphesiz Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":2,"t":"Rabbinden sana vahyedilene uy; muhakkak ki Allâh yaptıklarınızı haber almaktadır."},{"n":3,"t":"Allah’a dayan; vekil olarak Allâh yeter."},{"n":4,"t":"Allâh, bir adamın (göğüs) boşluğunda iki kalb yaratmadı ve zıhâr yaptığınız (sen bana, annemin sırtı gibisin dediğiniz) eşlerinizi, sizin anneleriniz yapmadı; evlatlıklarınızı da sizin öz oğullarınız kılmadı. Bunlar sizin ağızlarınıza gelen sözlerinizdir. Allâh gerçeği söyler ve O, doğru yola iletir."},{"n":5,"t":"Onları babalarının adına bağlayarak çağırın; bu, Allâh yanında daha adâletlidir. Eğer babalarını bilmiyorsanız, onlar sizin din kardeşleriniz ve dostlarınızdır. Yanılarak yaptığınızda size bir günâh yok, fakat kalblerinizin bile bile yaptığında günâh vardır. Allâh çok bağışlayan, çok esirgeyendir."},{"n":6,"t":"Peygamber, mü’minlere canlarından ileridir. Onun eşleri de onların anneleridir. Rahim sâhipleri (anne tarafından akrabâlar) da Allâh’ın Kitabında birbirlerine öteki mü’minlerden ve Muhâcirlerden daha yakındırlar. Ancak dostlarınıza bir iyilik yapmanız (bir vasiyyet etmeniz) hariç (yaptığınız o vasiyyet yerine getirilir). Bunlar Kitapta yazılmıştır."},{"n":7,"t":"Biz peygamberlerden, (verdiğimiz elçilik görevini yapmak ve hak dine da’vet etmek hususunda) kuvvetle ahidlerini almıştık, senden, Nûh’dan, İbrâhim’den, Mûsâ’dan ve Meryem oğlu Îsâ’dan, (evet) onlardan sapasağlam söz almıştık."},{"n":8,"t":"(Böyle yaptık) Ki (Allâh), o doğrulara doğruluklarından sorsun. Kâfirlere de acı bir azâb hazırlamıştır."},{"n":9,"t":"Ey inananlar, Allâh’ın size olan ni’metini hatırlayın, hani bir zaman size ordular gelmişti de biz onların üzerine bir rüzgâr ve sizin görmediğiniz ordular göndermiştik. Allâh, yaptıklarınızı görmekteydi."},{"n":10,"t":"Hani onlar üstünüzden ve alt tarafınızdan gelmişlerdi, gözler (şaşkınlıktan ötürü) kaymış, yürekler (korkudan) hançerelere dayanmıştı. Allâh hakında türlü zanlarda bulunuyordunuz."},{"n":11,"t":"İşte orada mü’minler denenmiş, şiddetli bir sarsıntı ile sarsılmışlardı."},{"n":12,"t":"Münâfıklar ve kalblerinde hastalık bulunan kimseler: \"Allâh ve Resulü bize sadece boş vaadlerde bulundu.\" diyordu."},{"n":13,"t":"Onlardan bir grup da demişti ki: \"Ey Yesrib (Medine) halkı, artık size duracak yer yok, (haydi durmayın, evlerinize) dönün (Yahut: Artık bu dinde durmanız doğru değil, dönün)\". Onlardan bir topluluk da. \"Evlerimiz (sağlam değil), açıktır\" diyerek peygamberden izin istiyordu. Oysa onlar(ın evleri) açık değildi. Sadece kaçmak istiyorlardı."},{"n":14,"t":"Eğer (Medine’nin) her yanından onların üzerine giril(ip saldırıl)saydı da kendilerinden (halka) baskı ve işkence yapmaları istenseydi bunu yaparlardı; bunu yapmakta fazla gecikmezlerdi."},{"n":15,"t":"Oysa arkalarına dön(üp kaç)mayacaklarına dair Allah’a söz vermişlerdi. Allah’a verilen sözden sorumlu idiler."},{"n":16,"t":"De ki: \"Eğer ölümden veya öldürülmekten kaçıyorsanız, kaçmak size fayda vermez. Kaçsanız bile pek az bir zaman yaşatılırsınız (sonunda yine ölürsünüz).\""},{"n":17,"t":"De ki: \"Allâh size kötülük istese veya size rahmet dilese, sizi O’ndan kim korur? (Allâh’ın azâbından sizi kim kurtarır, O’nun rahmetine kim engel olur?) Kendilerine Allah’tan başka ne bir dost ne de bir yardımcı bulurlar.\""},{"n":18,"t":"Allâh içinizden (savaştan) alıkoyanları ve kardeşlerine: \"Bize gelin!\" diyenleri biliyor. Onlar savaşa pek az gelirler."},{"n":19,"t":"(Geldikleri zaman da) Size karşı cimriler olarak (gelirler). Ama korkulu bir durum olunca onların, üstüne ölüm baygınlığı çökmüş insan gibi, gözleri dönerek sana baktıklarını görürsün. Korku gid(ip de sıra ganimetleri paylaşmağa gel) ince mala düşkünlük göstererek sizi sivri dillerle incitirler. Onlar, (içtenlikle) inanmamışlar, bu yüzden Allâh onların işlerini boşa çıkarmıştır. Bu, Allah’a göre kolaydır."},{"n":20,"t":"(Korkaklıklarından ötürü düşman) Orduların(ın Medine’den) gitmediklerini sanıyorlardı. Eğer o ordular (ikinci kez) gelseler, bunlar çölde bedevi Araplar arasında bulunmayı, sizin haberlerinizi (başınıza gelecek olayları) oradan sorup öğrenmeyi arzu ederlerdi. İçinizde bulunsalardı dahi pek az dövüşürlerdi."},{"n":21,"t":"Andolsun Allâh’ın Elçisinde sizin için Allah’a ve âhiret gününe kavuşmaya inanan ve Allâh’ı çok anan kimseler için, (uyulacak) en güzel bir örnek vardır."},{"n":22,"t":"Mü’minler (düşman) orduları(nı) gördükleri zaman (korkmadılar): \"Bu Allâh’ın ve Resulünün, bize va’dettiği (zafer)dir. Allâh ve Resulü doğru söylemiştir.\" dediler. Ve bu, onların sadece imanlarını ve teslimiyetlerini artırdı."},{"n":23,"t":"Mü’minlerden öyle erkekler var ki, Allah’a verdikleri sözde durdular. Onlardan kimi adağını yerine getirdi, (şehid oluncaya kadar çarpışacaklarını adamışlardı, çarpıştılar ve şehid düştüler), kimi de (şehidlik) beklemektedir; sözlerini asla değiştirmemişlerdir."},{"n":24,"t":"Ki Allâh doğruları, doğruluklarıyle mükâfâtladırsın, iki yüzlülere de dilerse azâbetsin; yahut tevbelerini kabul buyursun. Şüphesiz Allâh çok bağışlayandır, çok esirgeyendir."},{"n":25,"t":"Allâh, inkâr edenleri öfkeleriyle geri çevirdi; hiçbir hayra eremediler. Allâh savaşta (rüzgâr ve meleklerin yardımıyle) mü’minlere yetti. Allâh güçlüdür, üstündür."},{"n":26,"t":"Kitap ehlinden onlara yardım eden (Kurayza yahûdi)lerini de kalelerinden indirdi ve kalblerine korku düşürdü. (Onlardan) Bir kısmını öldürüyordunuz, bir kısmını da esir alıyordunuz."},{"n":27,"t":"Onların topraklarını, evlerini, mallarını ve henüz ayak basmadığınız bir toprağı size mirâs verdi. Allâh, her şeye kâdirdir."},{"n":28,"t":"Ey peygamber! Eşlerine söyle: \"Eğer siz, dünyâ hayâtını ve süsünü istiyorsanız, gelin size müt’a (boşanma bedeli) vereyim ve sizi güzellikle salayım.\""},{"n":29,"t":"\"Eğer siz, Allâh’ı, Elçisini ve âhiret yurdunu istiyorsanız, (biliniz ki) Allâh, sizden güzel hareket edenlere büyük bir mükâfât hazırlamıştır.\""},{"n":30,"t":"Ey peygamber kadınları! Sizden kim açık bir fuhuş (edepsizlik) yaparsa onun için azâb iki kat yapılır. Bu, Allah’a göre kolaydır."},{"n":31,"t":"Fakat sizden kim Allah’a ve Resulüne itâ’ate devam eder ve yararlı iş yaparsa ona da mükâfâtını iki kez veririz ve onun için bol bir rızık hazırlamışızdır."},{"n":32,"t":"Ey peygamber kadınları, siz, kadınlardan herhangi biri gibi değilsiniz. Eğer (Allâh’ın buyruğuna karşı gelmekten) korunuyorsanız, sözü yumuşak (kıvrak) bir edâ ile söylemeyin ki, kalbinde hastalık bulunan kimse tamah etmesin; güzel, (kuşkudan uzak bir biçimde) söz söyleyin."},{"n":33,"t":"Evlerinizde oturun, ilk câhiliye (çağı kadınları)nın açılıp kırıtması gibi açılıp kırıtmayın. Namazı kılın, zekâtı verin, Allah’a ve Resûlüne itâ’at edin. Ey Ehl-i Beyt (ey peygamberin ev halkı), Allâh sizden, kiri gidermek ve sizi tertemiz yapmak istiyor."},{"n":34,"t":"Evlerinizde okunan Allâh âyetlerini ve hikmeti hatırlayın. Şüphesiz Allâh latiftir, haber alandır."},{"n":35,"t":"Müslüman erkekler ve müslüman kadınlar, mü’min erkekler ve mü’min kadınlar, tâ’ate devam eden erkekler ve tâ’ate devam eden kadınlar, doğru erkekler ve doğru kadınlar; sabreden erkekler ve sabreden kadınlar, (Allah’a) saygılı erkekler ve saygılı kadınlar, sadaka veren erkekler ve sadaka veren kadınlar, oruç tutan erkekler ve oruç tutan kadınlar, ırzlarını koruyan erkekler ve (ırzlarını) koruyan kadınlar, Allâh’ı çok zikreden erkekler ve zikreden kadınlar; (İşte) Allâh bunlar için bağış ve büyük bir mükâfât hazırlamıştır."},{"n":36,"t":"Allâh ve Resulü, bir işte hüküm verdiği zaman, artık inanmış bir erkek ve kadının, o işi kendi isteklerine göre seçme hakkı yoktur. Kim Allah’a ve Resulüne karşı gelirse, apaçık bir sapıklığa düşmüş olur."},{"n":37,"t":"Allâh’ın ni’met verdiği; senin de kendisine ni’met ver(ip hürriyete kavuştur)duğun kimseye: \"Eşini yanında tut, Allah’tan kork\" diyordun, fakat Allâh’ın açığa vuracağı şeyi içinde gizliyordun, insanlardan çekiniyordun; oysa asıl çekinmene lâyık olan, Allâh idi. Zeyd, o kadından ilişiğini kesince biz onu sana nikâhladık ki (bundan böyle) evlatlıkları, kadınlarıyle ilişkilerini kestikleri zaman o kadınlarla evlenmek hususunda mü’minlere bir güçlük olmasın. Allâh’ın buyruğu (her zaman) yerine getirilmiştir."},{"n":38,"t":"Allah’ın kendisine takdir ettiği bir şeyi yerine getirmekte, Peygambere herhangi bir güçlük yoktur. Sizden önce geçenler arasında da Allâh’ın yasası böyle idi. Allâh’ın emri, olup bitmiş bir şeydir."},{"n":39,"t":"(O peygamberler), Allâh’ın mesajlarını duyururlar, Allah’tan korkarlar ve O’ndan başka kimseden korkmazlardı. Hesap görücü olarak Allâh yeter."},{"n":40,"t":"Muhammed, sizin erkeklerinizden birinin babası değil fakat Allâh’ın Elçisi ve peygamberlerin hâtemidir. Allâh her şeyi bilendir."},{"n":41,"t":"Ey inananlar, Allâh’ı çok anın."},{"n":42,"t":"Ve O’nu sabah akşam tesbih edin."},{"n":43,"t":"O (Allâh)dır ki, sizi karanlıklardan aydınlığa çıkarmak için üzerinize rahmet eder, melekleri de (size acıyıp mağfiret dilerler. Allâh) inananlara karşı çok esirgeyendir."},{"n":44,"t":"Kendisine kavuştukları gün, selâm ile karşılanırlar. (Allâh) Onlara güzel bir mükâfât hazırlamıştır."},{"n":45,"t":"Ey peygamber, biz seni şâhid, müjdeci ve uyarıcı olarak gönderdik."},{"n":46,"t":"Ve izniyle, Allah’a da’vetçi ve aydınlatıcı bir lamba olarak (gönderdik)."},{"n":47,"t":"Mü’minlere, Allah’tan büyük bir lutuf bulunduğunu müjdele!"},{"n":48,"t":"Kâfirlere ve münâfıklara itâ’at etme. Onların eziyetlerine aldırma, Allah’a dayan; vekil (koruyucu) olarak Allâh yeter."},{"n":49,"t":"Ey inananlar, inanan kadınları nikâhlayıp da henüz onlara dokunmadan boşarsanız, onların üzerinde sayacağınız bir iddet hakkınız yoktur. Hemen müt’alarını verin (biraz geçimlik verip memnun edin) ve onları güzellike serbest bırakın."},{"n":50,"t":"Ey peygamber, biz, ücretlerini (mehirlerini) verdiğin eşlerini; Allâh’ın sana ganimet olarak verdiğ(i savaş esir)lerinden elinin altında bulunan (câriye)leri; amcanın, halalarının, dayının ve teyzelerinin seninle beraber göç eden kızlarını sana helâl kaldık. Bir de kendisini (mehirsiz olarak) peygambere hibe eden ve peygamberin de kendisini almak dilediği inanmış kadını, diğer mü’minlere değil, sırf sana mahsus olmak üzere (helâl kıldık). Biz, eşleri ve ellerinin altında bulunan (câriye)leri hakkında mü’minlere yapmalarını gerekli kıldığımız şeyi bil(dir)dik. (Onların bu hususta ne yapması lâzım geldiğini de daha önce açıkladık) ki, sana bir zorluk olmasın, (sen bir sıkıntıya, güç bir duruma düşmeyesin). Allâh çok bağışlayan, çok esirgeyendir."},{"n":51,"t":"Onlardan dilediğini geri bırakır, dilediğini yanına alırsın. (Geçici olarak) Ayrıldıklarından (tekrar birleşmeyi) arzu ettiğine (dönmekte) senin üzerine bir günâh yoktur. Onların gözlerinin aydınlanıp tasalanmamalarına ve hepsinin, senin verdiklerine râzı olmalarına en elverişli olan budur. Allâh sizin kalblerinizde olanı bilir. Allâh bilendir, halimdir (birden öfkeye kapılıp cezâ vermez)."},{"n":52,"t":"Bundan sonra artık sana (başka) kadınlar(la evlenmek), güzellikleri çok hoşuna giden kadınlar olsa da, bunları başka eşlerle değiştirmek helâl değildir. Yalnız elinin altında bulunan (cariye)ler bunun dışındadır. Allâh, her şeyi gözetleyicidir."},{"n":53,"t":"Ey inananlar, (rastgele) Peygamber’in evlerine girmeyin. Ancak yemek için size izin verilir de girerseniz (erkenden gelip) yemeğin pişmesini beklemeyin. Çağrıldığınız zaman girin; yemeği yeyince dağılın, söze dalmayın. Çünkü bu (davranışınız) Peygamberi incitiyor, fakat o, (size bunu söylemekten) utanıyordu. Ama Allâh, gerçek(i söylemek)ten utanmaz. Onlardan (yani peygamberin hanımlarından) bir şey istediğiniz zaman perde arkasından isteyin. Bu, hem sizin kalbleriniz, hem de onların kalbleri için daha temizdir. Sizin, Allâh’ın Elçisini incitmeniz ve kendisinden sonra onun eşlerini nikâhlamanız asla olamaz. Çünkü bu, Allâh katında büyük (bir günâh)tır."},{"n":54,"t":"Bir şeyi açığa vursanız da, yahut onu gizleseniz de (fark etmez), Allâh her şeyi gâyet iyi bilmektedir."},{"n":55,"t":"Onlara (yani Peygamberin hanımlarına) ne babaları, ne oğulları, ne kardeşleri, ne kardeşlerinin oğulları, ne kızkardeşlerinin oğulları, ne kadınları ve ne de ellerinin altında bulunan (köle)leri hakkında bir günâh yoktur, (bunlara karşı örtünmeleri gerekmez. Ey Peygamberin hanımları) Allah’tan korkun; şüphesiz Allâh, her şeyi görmektedir."},{"n":56,"t":"Allâh’ı ve melekleri, Peygambere salât etmekte (onun şerefini gözetmeğe, şânını yüceltmeğe özen göstermekte)dir. Ey inananlar, siz de ona salât edin, (onun şânını yüceltmeğe özen gösterin); içtenlikle selâm edin (ona esenlik dileyin)."},{"n":57,"t":"Allâh’ı ve Elçisini incitenler var ya, işte Allâh onlara dünyâda ve âhirette la’net etmiş ve onlar için alçaltıcı bir azâb hazırlamıştır."},{"n":58,"t":"Mü’min erkekleri ve mü’min kadınları yapmadıkları bir şeyle (suçlayıp) incitenler bir iftirâ ve açık bir günâh yüklenmişlerdir."},{"n":59,"t":"Ey Peygamber, eşlerine, kızlarına ve inananların kadınlarına söyle! (Bir ihtiyaç için dışarı çıktıkları zaman) örtülerini üstlerine salsınlar; onların tanınıp incitilmemesi için en elverişli olan budur. Allâh çok bağışlayan, çok esirgeyendir."},{"n":60,"t":"Andolsun, iki yüzlüler, kalblerinde hastalık bulunanlar, şehirde kötü haberler yayanlar (bu yaptıklarından) vazgeçmezlerse seni onların üstüne süreriz (onlarla savaşmanı ve onları şehirden sürüp çıkarmanı sana emrederiz); sonra orada, senin yanında ancak az bir zaman kalabilirler."},{"n":61,"t":"La’netlenirler; nerede rastlansalar yakalanıp; öldürülürler."},{"n":62,"t":"Allâh’ın önceden geçen (millet)ler arasında (uygulanan) yasası budur. (Peygamberlere karşı iki yüzlülük edenler öldürülürler). Allâh’ın yasasını değiştirme(ğe imkân) bulamazsın."},{"n":63,"t":"İnsanlar sana O sâ’atten soruyorlar. De ki: \"Onun bilgisi Allâh’ın yanındadır.\" Ne bilirsin belki o sâ’at yakın olur?"},{"n":64,"t":"Allâh kâfirlere la’net etmiş ve onlar için çılgın bir ateş hazırlamıştır."},{"n":65,"t":"Orada ebedi olarak kalacaklar; (kendilerini koruyacak) bir dost ve yardımcı bulamayacaklardır."},{"n":66,"t":"Yüzleri ateşin içinde çevrildiği gün: \"Eyvah bize! Keşke Allah’a itâ’at etseydik, Elçiye itâ’at etseydik!\" derler."},{"n":67,"t":"Ve dediler ki: \"Rabbimiz, biz beylerimize ve büyüklerimize uyduk da bizi yoldan saptırdılar.\""},{"n":68,"t":"\"Rabbimiz, onlara iki kat azâb ver ve onlara büyük bir la’net eyle!\""},{"n":69,"t":"Ey inananlar, şu kimseler gibi olmayın ki, Mûsâ’ya eziyet ettiler de Allâh onu onların dediklerinden berâat ettirdi; o, Allâh yanında vecih (gözde, itibârlı bir kul) idi."},{"n":70,"t":"Ey inananlar, Allah’tan korkun ve doğru söz söyleyin."},{"n":71,"t":"Ki (Allâh) işlerinizi düzeltsin ve günâhlarınızı bağışlasın. Kim Allah’a ve Resulüne itâ’at ederse, büyük bir başarıya ermiş olur."},{"n":72,"t":"Biz emâneti, göklere, yere ve dağlara sunduk; onu yüklenmekten kaçındılar, on(un sorumluluğun)dan korktular; onu insan yüklendi; (fakat onun ağır sorumluluğunu tam kavrayamadı) doğrusu o, çok zâlim, çok câhildir."},{"n":73,"t":"(Allâh bu emâneti insana vermiştir) Ki iki yüzlü erkeklere ve iki yüzlü kadınlara, ortak koşan erkeklere ve ortak koşan kadınlara azâb etsin; inanan erkekleri ve inanan kadınları da bağışlasın. Allâh çok bağışlayan, çok esirgeyendir."}],[{"n":1,"t":"Hamd, göklerde ve yerde bulunanların hepsi kendisinin olan Allah’a mahsustur. Âhirette de hamd O’na mahsustur. O, hüküm ve hikmet sâhibidir; (her şeyi) haber alandır."},{"n":2,"t":"Yerin içine gireni ve ondan çıkanı, gökten ineni ve oraya çıkanı bilir. O, çok esirgeyen, çok bağışlayandır."},{"n":3,"t":"İnkâr edenler: \"O Sâ’at bize gelmez,\" dediler. De ki: \"Hayır, gaybı bilen Rabbim hakkı için o, mutlaka size gelecektir. Göklerde ve yerde zerre ağırlığınca bir şey, O’ndan gizli kalmaz. Ne bundan küçük, ne de bundan büyük hiçbir şey yoktur ki apaçık bir Kitapta bulunmasın."},{"n":4,"t":"(Her şeyi apaçık bir Kitapta tesbit etmiştir) Ki, inanıp iyi işler yapanları mükâfâtlandırsın. Onlar için mağfiret ve güzel rızık vardır."},{"n":5,"t":"Âyetlerimiz hakkında (bizi) âciz bırakmağa çalışanlara gelince; onlar içinde pislikten acı bir azâb vardır."},{"n":6,"t":"Kendilerine bilgi verilenler, Rabbinden sana indirilenin, gerçek olduğunu, mutlak gâlib ve hamde lâyık olan (Allâh)ın yoluna ilettiğini görürler."},{"n":7,"t":"İnkâr edenler, dediler ki: \"Siz tamamen dağılıp parçalandıktan sonra, mutlaka yeni bir yaratılış içinde olacağınızı size haber veren bir adam gösterelim mi size?\""},{"n":8,"t":"\"Allah’a yalan mı uydurdu, yoksa kendisinde delilik mi var?\" Hayır, âhirete inanmayanlar, azâb ve uzak bir sapıklık içindedirler."},{"n":9,"t":"Onlar gökten ve yerden önlerinde ve arkalarında bulunanı, (kendilerini her yandan kuşatan göğü ve yeri) görmüyorlar mı? Dilesek onları yere batırırız ya da üzerlerine gökten parçalar düşürürüz. Şüphesiz bunda (Rabbine) yönelen her kul için bir ibret vardır."},{"n":10,"t":"Andolsun, Dâvûd’a tarafımızdan bir üstünlük verdik: \"Ey dağlar, onunla beraber tesbih edin. Ve ey kuşlar (siz de onun tesbihine katılın)!\" (dedik) ve ona demiri yumuşattık:"},{"n":11,"t":"\"Geniş zırhlar yap, dokumasını ölçülü yap ve (hepiniz) iyi işler yapın. Çünkü ben yaptıklarınızı görmekteyim.\" diye (vahyettik)."},{"n":12,"t":"Süleymân’a da, sabah gidişi bir ay(lık mesafe), akşam dönüşü bir ay(lık mesafe) olan rüzgârı boyun eğdirdik ve onun için katran (petrol) kaynağını da akıttık. Rabbinin izniyle cinlerin bir kısmı, onun önünde çalışırdı. Onlardan kim buyruğumuzdan sapsa, ona alevli azâbı taddırırdık."},{"n":13,"t":"Ona dilediği gibi kaleler, heykeller, havuzlar kadar (geniş) leğenler, sabit kazanlar yaparlardı. \"Ey Dâvûd âilesi, şükredin!\" kullarımdan şükreden azdır."},{"n":14,"t":"(Süleymân’ın) Ölümüne hükmettiğimiz zaman, onun öldüğünü, ancak değneğini yiyen bir ağaç kurdu gösterdi. (Kurdun yemesiyle değnek çürüyüp de ona dayalı duran Süleymân) Yıkılınca (onun öldüğü anlaşıldı ve) anlaşıldı ki eğer cinler gaybı bilselerdi, o küçük düşürücü azâb içinde kalmazlardı."},{"n":15,"t":"Andolsun (Kahtan oğlu, Ya’rub oğlu...) Sebe (oğulların)ın oturdukları yerlerde de bir ibret vardır: (O meskenler) Sağdan, soldan iki bahçe (ile çevrili idi. Onlara): \"Rabbinizin rızkından yeyin de O’na şükredin! Hoş (bir) ülke, çok bağışlayan Rab!\" (denilmişti)."},{"n":16,"t":"Ama (şükürden) yüz çevirdiler; bu yüzden üzerlerine Arim selini gönderdik; onların iki bahçesini buruk yemişli, acı meyvalı ve içinde biraz da sedir ağacı bulunan iki bahçeye çevirdik."},{"n":17,"t":"Nankörlük ettiklerinden ötürü onları böyle cezâlandırdık; biz nankörden başkasını cezâlandırır mıyız?"},{"n":18,"t":"Onlarla, içinde bereketler yarattığımız kentler arasında, açıkça görünen kentler var ettik ve bunlar arasında yürümeyi takdir ettik: \"Oralarda geceleri ve gündüzleri güven içinde yürüyün\" (dedik)."},{"n":19,"t":"\"Rabbimiz, seferlerimizin arasını uzaklaştır (şehirlerimiz birbirine çok yakın, bunlarını arasını uzat da daha uzun mesafelere gidelim)\" dediler ve kendilerine zulmettiler. Biz de onları efsânelere çevirdik, onları darmadağın ettik. Şüphesiz bunda, sabreden, şükreden herkes için ibretler vardır."},{"n":20,"t":"Andolsun İblis, onlar hakkındaki zannını doğru çıkardı, inanan bir bölükten başka (hepsi) ona uydular."},{"n":21,"t":"Onun onlar üzerinde zorlayıcı bir gücü yoktu. Ancak âhirete inananı, ondan kuşkulanandan (ayırd edip) bilelim diye (ona bu fırsatı verdik). Rabbin her şeyi korumaktadır."},{"n":22,"t":"De ki: \"Allah’tan başka (tanrı) sandığınız şeyleri çağırın, onlar ne göklerde ve ne de yerde zerre ağırlığınca bir şeye sâhip değillerdir. Bu ikisi(nin yaratılmasında ve mülkü)nde bir ortaklıkları yoktur. Ve Allâh’ın onlardan bir yardımcısı da yoktur.\""},{"n":23,"t":"O’nun huzûrunda, O’nun izin verdiği kimselerden başkasının şefâ’ati fayda vermez. Nihâyet onların yüreklerinden korku giderilince (birbirlerine): \"Rabbiniz ne buyurdu?\" derler. \"Hakkı (buyurdu)\" derler. O, yücedir, büyüktür."},{"n":24,"t":"De ki: \"Size göklerden ve yerden kim rızık veriyor?\" De ki: \"Allâh, O halde ya biz veya siz, (ikimizden biri), doğru yol üzerinde veya açık bir sapıklık içindeyiz.\""},{"n":25,"t":"De ki: \"Bizim işlediğimiz suçtan siz sorulacak değilsiniz; biz de sizin işlediğinizden sorumlu değiliz.\""},{"n":26,"t":"De ki: \"Rabbimiz (kıyâmet günü), hepimizi bir araya toplayacak, sonra aramızdaki sorunu çözecektir. O sorunları en güzel çözümleyendir, bilendir.\""},{"n":27,"t":"De ki: \"O’na kattığınız ortakları bana gösterin (bakayım, onlar tanrı olabilirler mi?). Hayır (böyle şey olamaz.) Doğrusu O, gâlib, hüküm ve hikmet sâhibi olan Allah’tır.\""},{"n":28,"t":"Biz seni ancak bütün insanlara müjdeleyici ve uyarıcı olarak gönderdik; fakat insanların çoğu bilmezler."},{"n":29,"t":"Diyorlar ki: \"Doğru iseniz bu tehdid (ettiğiniz azâp) ne zaman (olacak)?\""},{"n":30,"t":"De ki: \"Sizin için belirtilmiş bir gün vardır. Ondan ne bir sâ’at geri kalırsınız, ne de ileri geçebilirsiniz.\""},{"n":31,"t":"İnkâr edenler dediler ki: \"Biz ne bu Kur’ân’a, ne de bundan öncekilere inanırız.\" Sen o zâlimleri, Rablerinin huzûrunda tutuklanmış, birbirlerine söz atarlarken bir görsen: Zayıf düşürülenler, büyüklük taslayanlara: \"Siz olmasaydınız, elbette biz inanan insanlar olurduk.\" diyorlar."},{"n":32,"t":"Büyüklük taslayanlar da zayıf düşürülenlere dediler ki: \"Size hidâyet geldiği zaman sizi ondan biz mi engelledik? Hayır, zaten siz kendiniz suç işliyordunuz.\""},{"n":33,"t":"Zayıf düşürülenler büyüklük taslayanlara: \"Hayır, gece gündüz dolap (kurar, kötülük aşılardınız) Allah’a nankörlük etmemizi, O’na eşler koşmamızı bize emrederdiniz.\" dediler. Ve azâbı gördüklerinde, içlerinde pişmanlıklarını gizlediler. Biz de o nankörlerin boyunlarına demir halkalar geçirdik. Yalnız yaptıklarıyle cezâlanmıyorlar mı?"},{"n":34,"t":"Biz hangi ülkeye bir uyarıcı gönderdiysek mutlaka oranın varlıkla şımarmış kimseleri: \"Biz, sizin gönderildiğiniz şeyi inkâr ediyoruz\" dediler."},{"n":35,"t":"Ve dediler ki: \"Biz malca ve evlatça daha çoğuz, biz azâba uğratılacak değiliz.\""},{"n":36,"t":"De ki: \"Rabbim dilediğine rızkı yayar ve (dilediğine) kısar; fakat insanların çoğu bilmezler, (sanırlar ki mal ve evlâd çokluğu şeref ve büyüklük sebebidir.)\""},{"n":37,"t":"Ne mallarınız, ne de evlâdlarınız size katımızda bir yakınlık sağlar. Ancak inanıp faydalı iş yapanlar başka. Onlara yaptıklarının kat kat fazlası mükâfât vardır ve onlar saraylarda güven (ve huzûr) içindedirler."},{"n":38,"t":"Âyetlerimizi etkisiz kılmağa çalışanlara gelince, onlar da azâbın içine getirileceklerdir."},{"n":39,"t":"De ki: \"Rabbim kullarından dilediğine rızkı yayar ve ona (tekrar rızkı) kısar. Siz Allâh için ne verseniz, Allâh onun yerine başkasını verir. O, rızık verenlerin en hayırlısıdır.\""},{"n":40,"t":"O gün, onların hepsini bir araya toplar, sonra meleklere: \"Bunlar size mi tapıyorlardı?\" der."},{"n":41,"t":"(Melekler) derler ki: \"Sen yücesin, bizim velimiz (koruyucumuz) onlar değil, sensin. Hayır, onlar cinlere tapıyorlardı. Çokları onlara inanıyorlardı.\""},{"n":42,"t":"O gün birinizin, diğerine ne bir fayda, ne de zarar vermeğe gücü yeter. Biz zulmedenlere: \"Yalanlamakta olduğunuz ateş azâbını tadın!\" deriz."},{"n":43,"t":"Onlara açık açık âyetlerimiz okunduğu zaman dediler ki: \"Bu, sadece sizi babalarınızın taptığı(tanrılar)dan çevirmek isteyen bir adamdan başka bir şey değildir.\" Ve o nankörler dediler ki: \"Bu, uydurulmuş bir yalandan başka bir şey değildir.\" Ve kendilerine gelen hakkı inkâr edenler: \"Bu, apaçak bir büyüdür, başka bir şey değildir\" dediler."},{"n":44,"t":"Halbuki biz onlara okuyacakları bir Kitap vermemiştik ve senden önce onlara bir uyarıcı göndermemiştik."},{"n":45,"t":"Bunlardan önceki (millet)ler de yalanlanmışlardı. Bunlar, onlara verdiklerimizin onda birine bile erişmemişlerdir. (Onlara o kadar ni’met verdiğim halde yine) elçilerimi yalanladılar. Ama benim de (onları) inkârım nasıl oldu, (onları nasıl mahvettim)!?"},{"n":46,"t":"De ki: \"Size bir şeyi öğütleyeyim: ’Allâh için, ikişer ikişer ve teker teker durup düşününüz! Arkadaşınızda delilikten eser yoktur. O, çetin bir azâbın arefesinde sizin için bir uyarıcıdır.\""},{"n":47,"t":"De ki: \"Ben sizden bir ücret istemişsem, o sizin olsun. Benim ücretim yalnız Allah’a âittir. O her şeye şâhiddir.\""},{"n":48,"t":"De ki: \"Rabbim gerçeği, (dilediği kulunun kalbine) atar. (O) gaybleri bilendir.\""},{"n":49,"t":"De ki: \"Hak geldi, artık bâtıl ne bir şey ortaya çıkarabilir, ne de geri getirebilir. (O tamamen yok olup gitmiştir).\""},{"n":50,"t":"De ki: \"Eğer saparsam, kendi zararıma sapmış olurum. Eğer yolu bulursam, bu da Rabbimin bana vahyettiği (Kur’ân) sayesindedir. Şüphesiz O, işitendir, yakındır.\""},{"n":51,"t":"Telâşa düştükleri zaman (onları) bir görsen: Hiçbiri kurtulamaz, yakın yerden yakalanmışlardır."},{"n":52,"t":"\"Ona inandık\" demektedirler, ama uzak yerden (tâ dünyâdan imanı) nasıl alabilsinler?"},{"n":53,"t":"Oysa daha önce onu inkâr etmişlerdi. Uzak yerden görülmeyene taş atıyorlardı."},{"n":54,"t":"Tıpkı bundan önce benzerlerine yapıldığı gibi, kendileriyle arzu ettikleri şey arasına perde çekildi. Doğrusu, onlar katmerli bir kuşku içindedirler."}],[{"n":1,"t":"Gökleri ve yeri yoktan var eden; melekleri, ikişer, üçer, dörder kanatlı elçiler yapan Allah’a hamd olsun. O, yaratmada (dilediği kadar) artırır: (Kimine daha fazla kanat verir, kiminin bünyesini daha sağlam, daha büyük, kimini daha güzel yapar). Şüphesiz Allâh, her şeyi yapabilendir."},{"n":2,"t":"Allâh, insanlara bir rahmet açtı mı onu tutan olamaz, O’nun tuttuğunu da O’ndan sonra salacak yoktur. O, üstündür, hüküm ve hikmet sâhibidir."},{"n":3,"t":"Ey insanlar, Allâh’ın size olan ni’metini hatırlayın: Allah’tan başka size gökten ve yerden rızık verecek bir yaratıcı var mı? O’ndan başka tanrı yoktur. Nasıl oluyor da gerçekten çevriliyorsunuz?"},{"n":4,"t":"Eğer seni yalanlıyorlarsa, senden önceki elçiler de yalanlanmıştır. Bütün işler Allah’a döndürülecek(ve Allâh, herkesi yaptığıyle cezâlandıracak)tır."},{"n":5,"t":"Ey insanlar, Allâh’ın va’di gerçektir; sakın dünyâ hayâtı sizi aldatmasın, o aldatıcı, sizi Allâh(ın affına güvendirmek sûreti) ile aldatmasın."},{"n":6,"t":"Şeytân, sizin düşmanınızdır, siz de onu düşman tutun. O, partisini alevli ateşin halkından olmağa çağırır."},{"n":7,"t":"İnkâr edenler için çetin bir azâb var; inanıp iyi işler yapanlara da mağfiret ve büyük bir mükâfât vardır."},{"n":8,"t":"Kötü işi, kendisine süslendirilip de onu güzel gören kimse (vehmine aldanmayarak kötü amelini güzel görmeyen, aklıyle gerçeği gören kimse gibi olur) mu? Allâh dilediğini sapıklık içinde bırakır, dilediğini yola iletir. Bundan dolayı canın, onlar için hasretlere (üzüntülere) gitmesin, Allâh onların ne yaptıklarını biliyor."},{"n":9,"t":"Allah’tır ki, gönderdiği rüzgârlar bir bulut kaldırır, onu ölü bir ülkeye süreriz, ölmüş olan yeri onunla diriltiriz. İşte diriltme de böyledir."},{"n":10,"t":"Kim şeref istiyorsa (bilsin ki) şeref tamamen Allâh’ındır, (onu başkasından değil, Allah’tan istesin). Güzel söz O’na çıkar, iyi amel onu yükseltir. Kötü şeyleri kuranlara gelince, onlar için çetin bir azâb vardır. Ve onların tuzağı bozulacaktır."},{"n":11,"t":"Allâh sizi önce topraktan, sonra nutfe (sperm)den yarattı, sonra sizi çift çift yaptı. Bir dişinin gebe kalması ve doğurması hep O’nun bilgisiyledir. Bir canlıya ömür verilmesi de, onun ömründen azaltılması da mutlaka bir kitapta (yazılı)dır. Şüphesiz bu, Allah’a göre kolaydır."},{"n":12,"t":"İki deniz bir olmaz: Şu tatlıdır, susuzluğu keser, içimi (boğazdan) kayar; şu da tuzlu, acıdır. Hepsinden de taze et yersiniz ve takındığınız (inci, sedef gibi) süs (eşyası) çıkarırsınız. (Allâh’ın) Lutfundan payınızı arayıp şükretmeniz için gemilerin, denizi yarıp gittiğini görürsün."},{"n":13,"t":"(Allâh) Geceyi gündüzün içine sokar, gündüzü de gecenin içine sokar; güneşi ve ayı buyruğu altına almıştır. Her biri belirtilmiş bir süreye kadar akıp gider. İşte Rabbiniz Allâh budur, mülk O’nundur. O’ndan başka yalvardığınız şeyler ise bir çekirdek zarına bile sâhip değillerdir."},{"n":14,"t":"Onları çağırsanız sizin çağırmanızı işitmezler. İşitseler bile size cevap veremezler. Kıyâmet günü de, sizin (onları Allah’a) ortak koşmanızı tanımazlar. Hiç kimse sana, herşeyi bilen (Allâh) gibi gerçekleri haber veremez."},{"n":15,"t":"Ey insanlar, siz Allah’a muhtaçsınız, Allâh ise, işte zengin ve hamde lâyık olan O’dur."},{"n":16,"t":"Dilese sizi götürür ve yeni bir halk getirir."},{"n":17,"t":"Bu, Allah’a zor değildir."},{"n":18,"t":"Hiçbir günâhkâr başkasının günâhını çekmez. Eğer yükü ağır gelen kimse onu taşımak için (başkalarını çağırsa) onun yükünden hiçbir şey, taşınmaz; akrabâsı dahi olsa (kimse onun yükünü taşımaz). Sen ancak görmeden Rablerinden korkanları ve namazı kılanları uyarırsın. Ma’nen arınıp yücelen, kendi yararına arınmış olur. Dönüş Allah’adır, (Allâh, herkese yaptığının karşılığını verir)."},{"n":19,"t":"Körle, gören bir olmaz."},{"n":20,"t":"Karanlıklarla, aydınlık da bir olmaz."},{"n":21,"t":"Gölge ile sıcaklık da bir olmaz."},{"n":22,"t":"Dirilerle, ölüler de bir olmaz. Allâh dilediğine işittirir; yoksa sen kabirlerde bulunanlara işittirecek değilsin."},{"n":23,"t":"Sen sadece bir uyarıcısın."},{"n":24,"t":"Biz seni gerçek ile birlikte müjdeleyici ve uyarıcı olarak gönderdik. Her millet içinde mutlaka bir uyarıcı (peygamber gelip) geçmiştir."},{"n":25,"t":"Eğer (bunlar) seni yalanlıyorlarsa (üzülme çünkü) bunlardan öncekiler de yalanlamışlardı. Elçileri onlara açık kanıtlar, sahifeler ve aydınlatıcı Kitap getirmişlerdi (yine de onları yalanladılar)."},{"n":26,"t":"Sonra ben de o inkâr edenleri yakaladım. Benim (onları) inkârım (cezâlandırmam) nasıl oldu?"},{"n":27,"t":"Görmedin mi Allâh gökten su indirdi de, onunla renkleri çeşit çeşit meyvalar çıkardık. Dağlardan (geçen) beyaz, kırmızı, değişik renklerde ve simsiyah yollar (yarattık)."},{"n":28,"t":"İnsanlardan, hayvanlardan ve davarlardan da yine böyle türlü renkte olanlar var. Kulları içinden ancak bilginler, Allah’tan (gereğince) korkar. Şüphesiz Allâh dâimâ üstündür, çok bağışlayandır."},{"n":29,"t":"Allâh’ın Kitabını okuyanlar, namazı kılanlar ve kendilerine verdiğimiz rızıktan hayır için gizli ve açık harcayanlar, asla batmayacak bir ticaret umarlar."},{"n":30,"t":"Ki (Allâh), onlara ücretlerini tam ödesin ve lutfundan onlara fazlasını da versin. Çünkü O, çok bağışlayan, çok karşılık verendir."},{"n":31,"t":"Kitaptan sana vahyettiğimiz, kendinden öncekini doğrulayan gerçektir. Allâh kulların(ın her halini) haber alandır, görendir."},{"n":32,"t":"Sonra Kitabı kullarımız arasından seçtiklerimize mirâs verdik. Onlardan kimi nefsine zulmedendir, kimi orta gidendir, kimi de Allâh’ın izniyle hayırlarda öne geçendir. İşte büyük lutuf budur."},{"n":33,"t":"Adn cennetleri... Oraya girerler; orada altın bilezikler ve inci(ler) takınırlar. Orada giysileri de ipektir."},{"n":34,"t":"Dediler ki: \"Bizden tasayı gideren Allah’a hamdolsun, doğrusu Rabbimiz çok bağışlayan, çok karşılık verendir.\""},{"n":35,"t":"\"O (Rab) ki lutfuyla bizi durulacak yurda kondurdu. Orada bize ne bir yorgunluk dokunur ve ne de orada bize bir usanç dokunur.\""},{"n":36,"t":"Nankörlere de cehennem ateşi vardır. (Orada) Onlara ne (ölümle) hükmedilir ki, ölsünler ve ne de onlardan cehennem azâbı biraz hafifletilir. İşte biz her nankörü böyle cezâlandırırız."},{"n":37,"t":"Onlar orada: \"Rabbimiz, bizi çıkar, (önce) yaptığımızdan başkasını yapalım?\" diye feryâd ederler. \"Sizi, öğüt alacak olanın, öğüt alacağı kadar bir süre yaşatmadık mı? Size uyarıcı da geldi (fakat inanmadınız). Öyle ise (azâbı) tadın artık. Zâlimlerin yardımcısı yoktur.\""},{"n":38,"t":"Allâh göklerin ve yerin gaybını bilendir. O, göğüslerin özünü bilir."},{"n":39,"t":"Sizi yeryüzünde halifeler (yöneticiler) yapan O’dur. Artık kim nankörlük ederse nankörlüğü kendi zararınadır. Kâfirlerin küfrü, Rableri yanında (kendilerine) gazabdan başka bir şey artırmaz; kâfirlerin küfrü, (kendilerine) ziyandan başka bir şey artırmaz."},{"n":40,"t":"De ki: \"Siz, Allah’tan başka yalvardığınız şu tanrılarınızı gördünüz mü? Bana gösterin (bakayım), onlar yerden hangi şeyi yarattılar?\" Yoksa onların, gökler(in yaratılmasın)da (Allah’a) ortaklıkları mı var? Yoksa biz onlara (taptıkları putları bize ortak koşmalarını söyleyen) bir Kitap vermişiz de onlar o Kitaptan bir delil üzerinde mi bulunuyorlar? Hayır, o zâlimler birbirlerine, aldatmadan başka bir şey va’detmiyorlar."},{"n":41,"t":"Allâh yıkılmamaları için gökleri ve yeri tutmaktadır. Andolsun, gökler ve yer yıkılsa, onları, Kendisinden başka hiç kimse tutamaz. Şüphesiz O, halimdir, çok bağışlayandır."},{"n":42,"t":"\"Andolsun eğer kendilerine bir uyarıcı (peygamber) gelirse, her milletten daha çok doğru yolda olacaklar\" diye, yeminlerinin bütün gücüyle Allah’a yemin ettiler. Fakat kendilerine uyarıcı gelince, onlara Hak’tan uzaklaşmaktan başka bir katkı sağlamadı."},{"n":43,"t":"Yeryüzünde büyüklük taslama(larını) ve kötü tuzak(lar) kurma(larını artırdı.) Kötü tuzak, ancak sâhibine dolanır. Onlar öncekilerin yasasından başkasını mı bekliyorlar? Allâh’ın yasasında bir değişme bulamazsın; Allâh’ın yasasında bir sapma bulamazsın."},{"n":44,"t":"(Bunlar,) Yeryüzünde hiç gez(ip dolaş)madılar mı ki kendilerinden öncekilerin sonunun nasıl olduğunu görsünler? Onlar, (bunlardan) daha güçlü idiler. Ne göklerde ne de yerde Allâh’ı engelleyecek bir şey var. O, bilendir, güçlüdür."},{"n":45,"t":"Eğer Allâh, insanları yaptıkları işler yüzünden (hemen) cezâlandıracak olsaydı, yeryüzünde hiçbir canlı bırakmazdı. Fakat Allâh, onları belirtilmiş bir süreye kadar erteliyor. Süreleri geldiği zaman, kuşkusuz Allâh kullarını görmektedir (onları yaptıkları işlere göre cezâlandıracaktır)."}],[{"n":1,"t":"Yâsin"},{"n":2,"t":"Hikmetli Kur’ân’a andolsun."},{"n":3,"t":"Kuşkusuz sen gönderilmiş elçilerdensin."},{"n":4,"t":"Dosdoğru bir yol üzerinde,"},{"n":5,"t":"Yani üstün ve çok esirgeyen Allâh’ın indirdiği (Kur’ân yolu) üzerindesin."},{"n":6,"t":"Babaları uyarılmamış, bu yüzden kendileri de gaflet içinde kalmış bir toplumu uyarman için (seni gönderdik)."},{"n":7,"t":"Andolsun onların çoğuna o söz (cinlerden ve insanlardan bir kısmını cehenneme dolduracağım, sözü) hak oldu; artık onlar inanmazlar."},{"n":8,"t":"Biz onların boyunlarına halkalar geçirdik. Çenelere kadar dayanan o halkalar yüzünden kafaları kalkıktır."},{"n":9,"t":"Önlerinden bir sed ve arkalarından bir sed çektik de onları kapattık; artık görmezler."},{"n":10,"t":"Onları uyarsan da uyarmasan da onlar için birdir, inanmazlar."},{"n":11,"t":"Sen ancak zikre uyan ve görmeden Rahmân’dan korkan kimseyi uyarabilirsin. İşte öylesini bir mağfiret ve güzel bir mükâfâtla müjdele."},{"n":12,"t":"Biziz, biz ki, ölüleri diriltiriz ve öne sürdükleri işleri ve bıraktıkları eserleri yazarız. Zaten biz, her şeyi apaçık bir kütüğe ayrıntılı olarak kaydetmişizdir."},{"n":13,"t":"Onlara elçilerin geldiği şu kent halkını misâl olarak anlat:"},{"n":14,"t":"Biz onlara iki elçi gönderdik, onları yalanladılar, biz de (elçileri) üçüncü biriyle destekledik. Dediler ki: \"Biz size gönderilen elçileriz.\""},{"n":15,"t":"(Kentliler) Dediler ki: \"Siz de bizim gibi insandan başka bir şey değilsiniz. Rahmân bir şey indirmemiştir. Siz sadece yalan söylüyorsunuz.\""},{"n":16,"t":"(Elçiler) Dediler ki: \"Rabbimiz bilir ki biz size gönderilmiş elçileriz.\""},{"n":17,"t":"\"Bizim üzerimize düşen, yalnız açıkça duyurmaktır.\""},{"n":18,"t":"(Kentliler) Dediler ki: \"Doğrusu biz sizin yüzünüzden uğursuzluğa uğradık. Eğer bu işten vazgeçmezseniz sizi mutlaka taşlarız ve bizden size acı bir azâb dokunur.\""},{"n":19,"t":"(Elçiler) Dediler ki: \"Uğursuzluğunuz sizin kendinizdedir. Size öğüt verildiği için mi (uğursuzluğa uğruyorsunuz)? Hayır siz aşırı giden bir kavimsiniz.\""},{"n":20,"t":"Kentin en uzak yerinden bir adam koşarak geldi: \"Ey kavmim, elçilere uyun.\" dedi."},{"n":21,"t":"\"Sizden bir ücret istemeyenlere uyun, onlar doğru yoldadırlar.\""},{"n":22,"t":"\"Ben niçin beni yaratana kulluk etmeyeyim? Siz de hep O’na döndürüleceksiniz.\""},{"n":23,"t":"\"O’ndan başka tanrılar edinir miyim hiç? Eğer O çok esirgeyen, bana bir zarar vermek dilese, onların şefâ’ati bana hiçbir yarar sağlamaz ve onlar beni kurtaramazlar.\""},{"n":24,"t":"\"O takdirde ben, apaçık bir sapıklık içinde olurum.\""},{"n":25,"t":"\"Ben sizin Rabbinize inandım, (gelin) beni dinleyin.\""},{"n":26,"t":"Ona: \"Cennete gir\" denilince: \"Keşke, dedi, kavmim bilseydi."},{"n":27,"t":"Rabbimin beni bağışladığını ve beni ağırlananlardan kıldığını!\""},{"n":28,"t":"Ondan sonra biz, kavminin üzerine gökten bir ordu indirmedik, indirici de değildik, (buna gerek yoktu)."},{"n":29,"t":"Sâdece korkunç bir gürültü oldu, hemen sönüverdiler."},{"n":30,"t":"Yazık şu kullara! Kendilerine gelen her elçi ile mutlaka alay ederlerdi."},{"n":31,"t":"Görmediler mi kendilerinden önce nice nesilleri yok ettik; onlar bir daha kendilerine dönüp gelmezler?"},{"n":32,"t":"Ancak hepsi toplandığı zaman huzûrumuza getirileceklerdir."},{"n":33,"t":"Ölü toprak, onlar için bir âyettir, (ölüleri nasıl dirilteceğimize işârettir): Biz onu dirilttik, ondan dâne çıkardık da ondan yiyorlar."},{"n":34,"t":"Orada hurma ve üzüm bahçeleri yarattık; orada çeşmeler akıttık."},{"n":35,"t":"Ki o(suyun, yâhut bahçe)nin ürününden ve ellerinin emeğinden yesinler. Hâlâ şükretmiyorlar mı?"},{"n":36,"t":"Ne yücedir O (Allâh) ki toprağın bitirdiklerinden, kendilerinden ve daha bilmedikleri nice şeylerden olan bütün çiftleri yaratmıştır."},{"n":37,"t":"Gece de onlar için bir âyettir. Gündüzü ondan soyup, alırız, birden onlar karanlıkta kalıverirler."},{"n":38,"t":"Güneş de kendi müstekarrı (istikrârı veya istikrâr bulacağı yer) için akıp gider. Bu, üstün ve bilen(Allâh)ın takdiridir."},{"n":39,"t":"Aya da konaklar tâyin ettik. Nihâyet o, eski urcun(hurma salkımının sapın)a benzer bir hâle geldi."},{"n":40,"t":"Ne güneş aya erişebilir, ne de gece, gündüzün önüne geçebilir. Hepsi bir felekte (yörüngede) yüzmektedirler."},{"n":41,"t":"Onlar için bir âyet de, onların çoçuklarını dolu gemide taşımamız,"},{"n":42,"t":"Ve kendilerine onun gibi binecekleri nice şeyler yaratmamızdır."},{"n":43,"t":"Dilesek onları (suda) boğarız, ne kendilerine imdad (eden) olur, ne de kurtarılırlar."},{"n":44,"t":"Ancak bizden bir rahmet ve bir süreye kadar yaşatma vardır (acıyarak onları bir süre yaşatırız)."},{"n":45,"t":"Onlara: \"Önünüzdeki ve arkanızdaki (yani sizden önce geçen ve ileride sizi bekleyen) olaylardan sakının ki, esirgenesiniz,\" dendiği zaman (aldırmazlar)."},{"n":46,"t":"Zaten, onlara Rabblerinin âyetlerinden hiçbir âyet gelmez ki ondan yüz çevirmiş olmasınlar."},{"n":47,"t":"Onlara: \"Allâh’ın size verdiği rızıktan (Allâh için) verin!\" dendiği zaman, nankörler, inananlara: \"Allâh’ın dilediği takdirde yedireceği bir kimseye biz mi yedirelim? Doğrusu siz, apaçık bir sapıklık içindesiniz.\" derler."},{"n":48,"t":"Ve: \"Eğer doğru söylüyorsanız bu tehdid (ettiğiniz azâb) ne zaman (gelecek)?\" diyorlar."},{"n":49,"t":"Onların işi sadece korkunç bir sese bakar. Çekişip dururlarken ansızın o, kendilerini yakalar."},{"n":50,"t":"Artık ne bir tavsiye yapabilirler, ne de âilelerine dönebilirler."},{"n":51,"t":"Sûr’a üflendi. İşte onlar kabirlerden Rablerine koşuyorlar."},{"n":52,"t":"Dediler: \"Vah bize, bizi yattığımız yerden kim kaldırdı? İşte Rahmân’ın va’dettiği şey budur. Demek peygamberler doğru söylemiş!\""},{"n":53,"t":"Sâdece bir tek gürültü olur, hemen onların hepsi huzûrumuza getirilirler."},{"n":54,"t":"O gün, hiç kimseye bir haksızlık yapılmaz ve siz ancak yaptığınızın cezâsını çekersiniz."},{"n":55,"t":"O gün cennet halkı, bir iş içinde eğlenirler."},{"n":56,"t":"Kendileri ve eşleri, gölgelerde, koltuklara yaslanmışlardır."},{"n":57,"t":"Orada onlar için meyvalar ve istedikleri her şey vardır."},{"n":58,"t":"Çok esirgeyen Rabden (onlara) sözle selâm (vardır)."},{"n":59,"t":"\"Ey suçlular, bugün şöyle ayrılın!\""},{"n":60,"t":"\"Ey Âdem oğulları, ben size and vermedim mi: Şeytâna tapmayın o sizin apaçık düşmanınızdır."},{"n":61,"t":"Bana tapın doğru yol budur diye?\""},{"n":62,"t":"\"O, sizden birçok kuşağı saptırmıştı. Düşünmüyor muydunuz?\""},{"n":63,"t":"\"İşte size söylenen cehennem!\""},{"n":64,"t":"\"İnkârınızdan dolayı bugün oraya girin!\""},{"n":65,"t":"O gün ağızlarını mühürleriz, elleri bize söyler, ayakları yaptıklarına şâhidlik eder."},{"n":66,"t":"Dilesek gözlerini silerdik de yola dökülürlerdi, ama nasıl görecekler?"},{"n":67,"t":"Dilesek kılıklarını değiştirip onları oldukları yerde dondururduk, ne ileri gidebilir, ne geri dönebilirlerdi."},{"n":68,"t":"Kime uzun ömür versek, onun yaratılışını baş aşağı çevirir (gücünü azaltır)ız, (sonunda zayıflar, ihtiyarlar). Akıllarını kullanmıyorlar mı?"},{"n":69,"t":"Biz ona (Muhammed’e) şiir öğretmedik, (şiir) ona yakışmaz da. O(na vahyedilen) sadece bir öğüt ve apaçık bir Kur’ân’dır."},{"n":70,"t":"(Bu Kur’ân Muhammed’e vahyedilmiştir) ki, diri olanları uyarsın ve inkâr edenlere de (azâb) söz(ü) hak olsun."},{"n":71,"t":"Görmediler mi ellerimizin yaptıklarından kendilerine nice hayvanlar yarattık da kendileri onlara mâlik olmaktadırlar?"},{"n":72,"t":"Onları kendilerine boyun eğdirdik, onlardan bazıları binekleridir ve onlardan bazılarını da yerler."},{"n":73,"t":"Kendileri için onlarda daha birçok yararlar ve içecekler var. Hâlâ şükretmiyorlar mı?"},{"n":74,"t":"Belki kendilerine yardım edilir diye Allah’tan başka tanrılar edindiler."},{"n":75,"t":"(O tanrılar) Kendilerine yardım edemezler. Tersine kendileri onlar için hazırlanmış askerlerdir (Onları korumaktadırlar)."},{"n":76,"t":"Onların sözü seni üzmesin. Biz onların gizlediklerini de açığa vurduklarını da biliyoruz."},{"n":77,"t":"İnsan, bizim kendisini nasıl bir nutfe (sperm)den yarattığımızı görmedi mi ki, şimdi apaçık bir hasım kesildi?"},{"n":78,"t":"Kendi yaratılışını unutarak bize bir mesel verdi: \"Şu çürümüş kemikleri kim diriltecek?\" dedi."},{"n":79,"t":"De ki: \"Onları ilk defa yaratan diriltecek. O, her yaratmayı bilir.\""},{"n":80,"t":"O size yeşil ağaçtan ateş yaptı da siz ondan yakıyorsunuz."},{"n":81,"t":"Gökleri ve yeri yaratan, onların benzerlerini yaratamaz mı? Elbette yaratır. O, çok bilen yaratıcıdır."},{"n":82,"t":"O’nun işi, bir şeyi(n olmasını) istedi mi ona, sadece \"ol!\" demektir, hemen oluverir."},{"n":83,"t":"Yücedir O ki, her şeyin hükümranlığı O’nun elindedir ve siz O’na döndürüleceksiniz."}],[{"n":1,"t":"Andolsun o sıra sıra dizilenlere,"},{"n":2,"t":"Bağırıp sürenlere,"},{"n":3,"t":"Zikir okuyanlara,"},{"n":4,"t":"Ki Tanrınız, birdir."},{"n":5,"t":"Göklerin, yerin ve bunlar arasında bulunanların Rabbi, doğuların da Rabbidir."},{"n":6,"t":"Biz en yakın göğü bir zinetle, yıldızlarla süsledik."},{"n":7,"t":"Ve (onu) itâ’at dışına çıkan her türlü şeytândan koruduk."},{"n":8,"t":"O (şeyta)nlar mele-i A’lâyı (yüce melekler topluluğunu) dinleyemezler; her yandan kendilerine (ışınlar) atılır."},{"n":9,"t":"Kovulurlar. Onlar için sürekli bir azâb vardır."},{"n":10,"t":"Yalnız (yüce topluluktan) bir söz kapan olursa, onu da delici bir şihâb (ışın) izler."},{"n":11,"t":"Şimdi onlara sor: Yaratılış bakımından kendileri mi daha çetin, yoksa bizim yarattıklarımız mı? Biz kendilerini yapışkan bir çamurdan yarattık."},{"n":12,"t":"Hayır sen (bu muhteşem kudrete) hayran kaldın; onlarsa (seninle) alay ediyorlar."},{"n":13,"t":"Kendilerine öğüt verilse öğüt almıyorlar."},{"n":14,"t":"Bir mu’cize görseler, alay ediyorlar."},{"n":15,"t":"\"Bu apaçık bir büyüden başka bir şey değildir.\" diyorlar."},{"n":16,"t":"\"Yani biz öldüğümüz, toprak ve kemik olduğumuz zaman mı, biz mi diriltilecek mişiz?\""},{"n":17,"t":"\"Evvelki atalarımız da mı?\""},{"n":18,"t":"De ki: \"Evet siz aşağılanarak (diriltileceksiniz)!\""},{"n":19,"t":"O (iş) sadece korkunç bir sesten ibârettir. Hemen onlar (diriltilmiş olarak) bakıyorlardır."},{"n":20,"t":"\"Vah bize, bu cezâ günüdür!\" dediler."},{"n":21,"t":"\"Bu, yalanlamakta olduğunuz hüküm günüdür!\""},{"n":22,"t":"(Yüce Allâh meleklerine emreder): \"Toplayın o zâlimleri, onların eşlerini ve taptıklarını.\""},{"n":23,"t":"\"Allah’tan başka. Onları cehennemin yoluna götürün!\""},{"n":24,"t":"\"Durdurun onları, çünkü onlar sorguya çekileceklerdir.\""},{"n":25,"t":"\"Size ne oldu ki birbirinize yardım etmiyorsunuz?\""},{"n":26,"t":"(Başları öne eğik, utançtan yüzleri kızarmış. Cevap verecek durumda değillerdir). Hayır, onlar o gün teslim olmuşlardır."},{"n":27,"t":"Birbirlerine döndüler, soruyorlar."},{"n":28,"t":"(Uyanlar, uydukları adamlara) Dediler ki: \"Siz bize sağdan gelir (güvendiğimiz yandan bize sokulup vesvese verir)diniz.\""},{"n":29,"t":"(Ötekiler de): \"Hayır, dediler, zaten siz kendiniz inanan insanlar değildiniz.\""},{"n":30,"t":"\"Bizim sizi zorlayacak bir gücümüz yoktu. Siz kendiniz azgın bir toplum idiniz.\""},{"n":31,"t":"\"Artık Rabbimizin sözü bize hak oldu. Biz (hak ettiğimiz cezâyı mutlaka) tadacağız!\""},{"n":32,"t":"\"Sizi azdırdık, çünkü biz kendimiz azmıştık (siz de bize uyunca azmış oldunuz).\""},{"n":33,"t":"O gün onlar azâb (çekme)de ortaktırlar."},{"n":34,"t":"İşte biz, suçlulara böyle yaparız."},{"n":35,"t":"Çünkü onlara: \"Allah’tan başka tanrı yoktur!\" dendiği zaman büyüklük taslarlardı."},{"n":36,"t":"\"Cinlenmiş bir şâir için biz tanrılarımızı mı terk edeceğiz?\" derlerdi."},{"n":37,"t":"\"Hayır, o (ne şâirdi, ne mecnun. O) gerçeği getirmiş ve elçileri de doğrulamıştı.\""},{"n":38,"t":"\"Siz acı azâbı tadacaksınız!\""},{"n":39,"t":"\"Sadece yaptığınız (işler)le cezâlanıyorsunuz!\""},{"n":40,"t":"Ancak Allâh’ın hâlis kulları bu cezânın dışındadır."},{"n":41,"t":"Onlar için bilinen bir rızık vardır."},{"n":42,"t":"(Türlü türlü) Meyvalar. Ve onlar ağırlanırlar."},{"n":43,"t":"Ni’met cennetlerinde."},{"n":44,"t":"Tahtlar üzerinde, karşılıklı otururlar."},{"n":45,"t":"Önlerinde akan kaynaktan (doldurulmuş) kadehler dolaştırılır."},{"n":46,"t":"Berrak, içenlere lezzet veren bir içki."},{"n":47,"t":"Onda ne sersemletme var, ne onunla sarhoş olurlar."},{"n":48,"t":"Yanlarında da, yalnız kendilerine göz dikmiş iri gözlü eşler vardır."},{"n":49,"t":"Saklı yumurta gibi bembeyaz eşler."},{"n":50,"t":"Bunlar birbirine dönmüş soruyorlar:"},{"n":51,"t":"Onlardan bir sözcü: \"Benim, dedi, bir arkadaşım vardı.\""},{"n":52,"t":"Derdi ki: \"Sen doğrulayanlardan mısın?"},{"n":53,"t":"Biz ölüp toprak ve kemik olduğumuz zaman mı, biz mi (diriltilip yaptığımız işlere göre) cezâlanacağız?\""},{"n":54,"t":"(Sonra yanındakilere): \"Bakar mısınız?\" dedi."},{"n":55,"t":"Baktı onu cehennemin ortasında gördü."},{"n":56,"t":"\"Tallâhi, dedi, sen az daha beni de alçaltacaktın.\""},{"n":57,"t":"\"Rabbimin ni’meti olmasaydı, şimdi ben de (oraya) getirilenlerden olurdum.\""},{"n":58,"t":"\"Biz bir daha ölmeyecek miyiz\" der."},{"n":59,"t":"\"Yalnız ilk ölümümüz, başka ölüm yok ve biz azâba da uğratılmayacağız ha?!\""},{"n":60,"t":"Gerçekten büyük başarı ve mutluluk budur!"},{"n":61,"t":"Çalışanlar bunun için çalışsınlar."},{"n":62,"t":"(Nasıl) Ağırlanmak için bu mu hayırlı, yoksa zakkum ağacı mı?"},{"n":63,"t":"Biz onu zâlimler için bir fitne (sınav) yaptık."},{"n":64,"t":"O, cehennemin dibinde çıkan bir ağaçtır."},{"n":65,"t":"Tomurcukları, şeytânların başları gibidir."},{"n":66,"t":"Onlar ondan yiyecekler ve karınlarını onunla dolduracaklardır."},{"n":67,"t":"Sonra onların, bunun üzerine kaynar su karıştırılmış bir içkileri vardır."},{"n":68,"t":"Sonra dönecekleri yer, elbette cehennemdir."},{"n":69,"t":"Çünkü onlar babalarını sapık kimseler buldular."},{"n":70,"t":"Kendileri de onların izlerinde koşturuyorlar."},{"n":71,"t":"Andolsun, onlardan önce, evvelkilerin çoğu da sapmıştı."},{"n":72,"t":"Biz onların içine de uyarıcılar göndermiştik."},{"n":73,"t":"Bak, o uyarılanların sonu nice oldu."},{"n":74,"t":"Ancak Allâh’ın halis kulları o azâbın dışında kaldılar."},{"n":75,"t":"Andolsun Nûh bize yalvarmıştı da ne güzel kabul buyurmuştuk!"},{"n":76,"t":"Onu ve âilesini büyük sıkıntıdan kurtarmıştık."},{"n":77,"t":"Yalnız onun zürriyetini kalıcılar yaptık (onlardan başka hepsini helâk ettik)."},{"n":78,"t":"Sonra gelenler arasında ona (iyi bir ün) bıraktık:"},{"n":79,"t":"Âlemler içinde Nûh’a selâm olsun (bütün insanlar onu esenlikle anarlar)."},{"n":80,"t":"İşte biz güzel davrananları böyle mükâfâtlandırırız."},{"n":81,"t":"Çünkü o bizim, inanan kullarımızdandı."},{"n":82,"t":"Sonra ötekilerini suda boğduk."},{"n":83,"t":"İbrâhim de onun kolundan idi."},{"n":84,"t":"Zirâ Rabbine tertemiz bir kalb getirmişti."},{"n":85,"t":"Babasına ve kavmine: \"Neye tapıyorsunuz?\" demişti."},{"n":86,"t":"\"Allah’tan başka uydurma tanrılar mı istiyorsunuz?\""},{"n":87,"t":"Âlemlerin Rabbi hakkında zannınız nedir (ki O’na böyle ortaklar koştunuz)?"},{"n":88,"t":"Yıldızlara bir göz attı:"},{"n":89,"t":"\"Ben hastayım\", dedi."},{"n":90,"t":"Bunun üzerine arkalarını dönüp ondan kaçtılar."},{"n":91,"t":"O da gizlice onların tanrılarına sokuldu: \"Yemez misiniz?\" dedi."},{"n":92,"t":"\"Neyiniz var ki konuşmuyorsunuz?\""},{"n":93,"t":"Ve gizlice üzerlerine yürüyüp sağ eliyle onlara kuvvetli bir darbe indirdi."},{"n":94,"t":"(Puta, tapanlar, döndüklerinde putlarını kırılmış görünce) Hemen koşarak ona gittiler."},{"n":95,"t":"\"(Elinizle) Yonttuğunuz şeylere mi tapıyorsunuz?\" dedi."},{"n":96,"t":"\"Oysa sizi de, yaptığınız (bu şeyler)i de Allâh yaratmıştır.\""},{"n":97,"t":"\"Onun için bir bina yapın da onu (o binâda) ateşe atın\" dediler."},{"n":98,"t":"Ona bir tuzak kurmak istediler, biz de (onların tuzaklarını boşa çıkardık), onları alçak düşürdük."},{"n":99,"t":"(İbrâhim) Dedi ki: \"Ben Rabbime gideceğim, O, beni doğru yola iletecek.\""},{"n":100,"t":"\"Rabbim, bana iyilerden (bir çocuk) lutfet!\""},{"n":101,"t":"Ona halim bir erkek çocuk müjdeledik."},{"n":102,"t":"(Çocuk) Onun yanında koşma çağına erişince (İbrâhim ona): \"Yavrum, dedi, ben uykuda görüyorum ki ben seni kesiyorum; (düşün) bak, ne dersin?\" (Çocuk): \"Babacığım, sana emredileni yap, inşallah beni sabredenlerden bulacaksın.\" dedi."},{"n":103,"t":"İkisi de böylece (Allâh’ın emrine) teslim olup (İbrâhim, kurban etmek için) çocuğu alnı üzerine yıkınca,"},{"n":104,"t":"Biz ona: \"İbrâhim!\" diye ünledik."},{"n":105,"t":"\"Sen rüyâyı doğruladın, işte biz, güzel davrananları böyle mükâfâtlandırırız!\""},{"n":106,"t":"Gerçekten bu, apaçık bir sınav idi."},{"n":107,"t":"Ve fidye olarak ona büyük bir kurbanlık verdik."},{"n":108,"t":"Sonra gelenler arasında ona (iyi bir ün) bıraktık."},{"n":109,"t":"(İleride gelecek nesiller): \"İbrâhim’e selâm olsun!\" (diyeceklerdi.)"},{"n":110,"t":"İşte biz güzel davrananları böyle mükâfâtlandırırız."},{"n":111,"t":"Çünkü o bizim mü’min kullarımızdandı."},{"n":112,"t":"Biz ona İshâk’ı, iyilerden bir peygamber olarak müjdeledik."},{"n":113,"t":"Kendisine de, İshâk’a da bereketler verdik. Onların neslinden (gelenler arasında) iyi hareket eden de var, açıkça kendisine zulmeden de."},{"n":114,"t":"Andolsun Mûsâ’ya ve Hârûn’a da lutuflarda bulunduk."},{"n":115,"t":"Onları ve kavimlerini büyük sıkıntıdan kurtardık."},{"n":116,"t":"Onlara yardım ettik de üstün gelenler kendileri oldular."},{"n":117,"t":"Onlara açık ifâdeli Kitabı verdik."},{"n":118,"t":"Ve onları doğru yola ilettik."},{"n":119,"t":"Ve sonra gelenler arasında onlara (iyi bir ün) bıraktık."},{"n":120,"t":"(Hep): \"Mûsâ’ya ve Hârûn’a selâm olsun!\" (diyeceklerdi)."},{"n":121,"t":"İşte biz güzel davrananları böyle mükâfâtlandırırız."},{"n":122,"t":"Çünkü ikisi de bizim inanan kullarımızdandı."},{"n":123,"t":"İlyâs da elçilerdendi."},{"n":124,"t":"Kavmine demişti ki: \"(Allâh’ın azâbından) Korunmaz mısınız?\""},{"n":125,"t":"\"Ba’l’e yalvarıyorsunuz da, bırakıyor musunuz, yaratıcıların en güzelini?\""},{"n":126,"t":"\"Sizin Rabbiniz ve önceki atalarınızın Rabbi olan Allâh’ı?\""},{"n":127,"t":"Onu yalanladılar, bundan dolayı onlar (azâba) getirileceklerdir."},{"n":128,"t":"Yalnız Allâh’ın hâlis kulları azâb dışındadırlar."},{"n":129,"t":"Biz, sonra gelenler arasında ona (İlyâs’a da iyi bir ün) bıraktık:"},{"n":130,"t":"\"İlyâs’a selâm olsun.\""},{"n":131,"t":"İşte biz güzel davrananları böyle mükâfâtlandırırız."},{"n":132,"t":"Çünkü o bizim mü’min kullarımızdandı."},{"n":133,"t":"Lût da gönderilen elçilerdendi."},{"n":134,"t":"Onu ve âilesini kurtardık."},{"n":135,"t":"Yalnız (azâbda) kalacaklar arasında bulunan acûze bir kadın hâriç."},{"n":136,"t":"Sonra ötekileri kırdık (geçirdik)."},{"n":137,"t":"Siz onların yanlarından geçip gidiyorsunuz; sabahleyin,"},{"n":138,"t":"Ve geceleyin. Düşünmüyor musunuz?"},{"n":139,"t":"Yûnus da gönderilen elçilerdendi."},{"n":140,"t":"Dolu gemiye kaçmıştı."},{"n":141,"t":"(Yükü fazla oluğundan gemi taşıyamamış, yolculardan birini denize atmak gerekmişti. Birini atmak üzere gemidekilerle) Kur’a çekti. (Yûnus) Yenilenlerden oldu. (Kur’a kendisine isâbet etti)."},{"n":142,"t":"(Yûnus, Rabbinden izinsiz olarak kavminden ayrıldığı için) Kendi kendisini kınarken (denize attılar) balık onu yuttu."},{"n":143,"t":"Eğer tesbih edenlerden olmasaydı,"},{"n":144,"t":"(İnsanların) Yeniden diriltilecekleri güne kadar balığın karnında kalırdı."},{"n":145,"t":"(Ama balığın karnında bizi andı, tesbih etti, biz de) Onu hasta bir halde ağaçsız, çıplak bir yere attık."},{"n":146,"t":"Ve üzerine (gölge yapması için) Bir asma kabak ağacı bitirdik."},{"n":147,"t":"Ve onu yüz bin insana ya da daha fazla olanlara elçi gönderdik."},{"n":148,"t":"İnandılar, biz de onları bir süreye kadar geçindirdik."},{"n":149,"t":"Şimdi onlara sor: Rabbine kızlar, onlara da oğlanlar mı?"},{"n":150,"t":"Yoksa biz melekleri, onların gözleri önünde dişi mi yarattık (ki meleklerin dişi olduğunu söylüyorlar)?"},{"n":151,"t":"İyi bilin, onlar iftirâları yüzünden diyorlar ki:"},{"n":152,"t":"\"Allâh doğurdu.\" Onlar elbette yalancıdırlar."},{"n":153,"t":"(Allâh) Kızları seçip oğlanlara tercih mi etmiş?"},{"n":154,"t":"Size ne oldu, nasıl hüküm veriyorsunuz?"},{"n":155,"t":"Hiç mi düşünmüyorsunuz?"},{"n":156,"t":"Yoksa sizin, (meleklerin, Allâh’ın kızları oldukları hakkında) açık bir deliliniz mi var?"},{"n":157,"t":"Eğer doğru iseniz Kitabınızı getirin."},{"n":158,"t":"Allâh ile cinler arasında bir nesep, (bir soy bağlantısı) uydurdular. Oysa cinler de kendilerinin (yüce divâna) getirileceklerini bilmişlerdir."},{"n":159,"t":"Hâşâ Allâh, onların taktıkları sıfatlardan (münezzehtir), yücedir."},{"n":160,"t":"Fakat Allâh’ın temiz kulları hâriç (onlar azâba sokulmayacaklardır)."},{"n":161,"t":"(Ey inkârcılar) Ne siz, ne de taptıklarınız,"},{"n":162,"t":"Kandırıp Allâh’ın yolundan çıkaramazsınız;"},{"n":163,"t":"Cehenneme girecek olandan başkasını."},{"n":164,"t":"\"Bizden herkesin belli bir makâmı vardır.\""},{"n":165,"t":"\"Biziz, o saf saf dizilenler, biz.\""},{"n":166,"t":"\"Biziz, o tesbih edenler, biz.\""},{"n":167,"t":"Gerçi o(ortak koşa)nlar şöyle diyorlardı:"},{"n":168,"t":"\"Eğer yanımızda öncekiler(e gelen Kitap’lar)dan bir uyarı olsaydı.\""},{"n":169,"t":"\"Elbette biz, Allâh’ın hâlis kulları olurduk!\""},{"n":170,"t":"Ama o uyarıyı inkâr ettiler, yakında (inkâr etmelerinin sonunun nasıl olacağını) bileceklerdir."},{"n":171,"t":"Gönderilen elçi kullarımıza şu sözümüz geçmişti:"},{"n":172,"t":"\"Mutlaka zafere ulaştırılanlar kendileri olacaktır.\""},{"n":173,"t":"\"Ve gâlip gelenler, mutlaka bizim ordumuz olacaktır!\""},{"n":174,"t":"Bir süreye kadar onlardan dön (onların sözlerine aldırış etme)."},{"n":175,"t":"Onları gözetle. Yakında (başlarına neler geleceğini) göreceklerdir."},{"n":176,"t":"Bizim azâbımızı mı acele istiyorlar?"},{"n":177,"t":"Fakat o azâb yurtlarına indiği zaman uyarılmış olanların sabahı ne kötü olur!"},{"n":178,"t":"Bir süreye kadar onları kendi hallerine bırak."},{"n":179,"t":"Ve (bekle de) gör, onlar da göreceklerdir."},{"n":180,"t":"Kudret ve şeref sâhibi Rabbin, onların nitelendirmelerinden yücedir."},{"n":181,"t":"Selâm, gönderilen elçilere,"},{"n":182,"t":"Hamd, âlemlerin Rabbi Allah’a!"}],[{"n":1,"t":"Sâd, (uyarıcı) ve şanlı Kur’ân’a andolsun ki,"},{"n":2,"t":"İnkâr edenler bir gurur ve ayrılık içindedirler."},{"n":3,"t":"Onlardan önce nice nesilleri helâk ettik de feryâd ettiler; fakat artık kurtuluş zamanı geçmişti."},{"n":4,"t":"Onlara kendilerinden bir uyarıcı (peygamber) gelmesine hayret ettiler de o kâfirler dediler ki: \"Bu yalancı bir sihirbazdır.\""},{"n":5,"t":"\"Tanrıları bir tek tanrı mı yaptı? Bu, cidden tuhaf bir şeydir.\""},{"n":6,"t":"Onlardan bir grup fırladı: \"Yürüyün tanrılarınıza bağlı kalın. Çünkü bu, arzû edilen bir şeydir.\""},{"n":7,"t":"\"Biz bu(nun söylediği)ni (babalarımızın bağlı olduğu) öteki dinde işitmedik. Bu uydurmadan başka bir şey değildir.!\""},{"n":8,"t":"\"O Zikr (uyarı, başka kimse kalmadı da) aramızdan ona mı indirildi?\" Doğrusu, onlar benim Zikr’imden yana şüphe içindedirler. Hayır, onlar henüz azâbımı tadmadılar!.."},{"n":9,"t":"Yoksa dâimâ üstün olan, çok lütufta bulunan Rabbinin rahmet hazineleri onların yanında mı?"},{"n":10,"t":"Yoksa göklerin, yerin ve ikisi arasında bulunanların mülkü onların mı? Öyleyse sebepler (vâsıtalar) içinde yükselsinler (vâsıtalara binip göklere çıksınlar da oradan âlemi yönetsinler, vahyi de kendi isteklerine göre indirsinler)."},{"n":11,"t":"(Onlar) Şurada bozguna uğratılacak derme çatma bir ordudur."},{"n":12,"t":"Onlardan önce de Nûh kavmi, Âd (kavmi) ve kazıklar sâhibi (temelleri kazık gibi yere çakılmış, yüksek pramitler yaptıran) Fir’avn da yalanlamıştı."},{"n":13,"t":"Semûd (kavmi), Lût kavmi ve Eyke halkı da (böyle yapmıştı). İşte onlar da (peygamberlere karşı birleşik) kabilelerdi."},{"n":14,"t":"Hepsi de elçileri yalanladılar, benim cezâmı hak ettiler."},{"n":15,"t":"Bunlar(ın işi) de sadece geri dönmesi olmayan bir na’raya bakıyor."},{"n":16,"t":"(Alay ederek) Dediler ki: \"Rabbimiz, bizim (azâb) payımızı hesap gününden önce, hemen ver.\""},{"n":17,"t":"Onların dediklerine sabret de güçlü kulumuz Dâvûd’u an; çünkü o (bize) çok başvururdu."},{"n":18,"t":"Biz dağları onunla beraber (tesbih etmeleri için) boyun eğdirmiştik; akşam sabah onunla tesbih ederler (onun yaptığı tesbihle çınlarlar)dı."},{"n":19,"t":"Toplanıp gelen kuşları da (ona râm etmiştik). Hepsi onun nağmesine katılır (beraber tesbih ederler)di."},{"n":20,"t":"Onun mülkünü güçlendirmiştik, kendisine hikmet (peygamberlik, yüksek bilgi, hakkı bâtıldan ayırma, dâvâları çözme) ve açık, güzel konuşma (yeteneği) vermiştik."},{"n":21,"t":"Sana dâvâcıların haberi geldi mi? Hani odasının duvarına tırmanmışlardı,"},{"n":22,"t":"Dâvûd’un yanına girmişlerdi de (Dâvûd) onlardan korkmuştu: \"Korkma, dediler, biz iki dâvâcıyız. Birimiz, ötekinin hakkına saldırdı. Şimdi sen aramızda hak ile hükmet, (adâletten ayrılıp bize) zulmetme. Bizi yolun ortasına (adâlete) götür.\""},{"n":23,"t":"\"Bu kardeşimin doksan dokuz koyunu var. Benimse bir tek koyunum var. Böyle iken \"Onu da bana ver\" dedi ve konuşmada bana ağır bastı (onunla baş edemedim.)\""},{"n":24,"t":"(Dâvûd) dedi ki: \"And olsun (o) senin, koyununu kendi koyunlarına katmayı istemekle sana zulmetmiştir. Zâten (mallarını birbirine) karıştıran(ortak)ların çoğu birbirine zulmederler. Yalnız inanıp iyi işler yapanlar bunun dışındadır ki, onlar da ne kadar azdır!\" Dâvûd, (bu hükümle) kendisini denediğimizi (kendisine bir belâ vereceğimizi) sandı da Rabbinden mağfiret diledi, eğilerek secdeye kapandı ve tevbe edip (bize) döndü."},{"n":25,"t":"Biz de ondan bunu affettik. Yanımızda onun bir yakınlığı ve güzel bir geleceği vardır."},{"n":26,"t":"\"Ey Dâvûd, biz seni yeryüzünde (senden öncekilerin yerine) hükümdar yaptık. İnsanlar arasında adâletle hükmet; keyf(in)e uyma, sonra seni Allâh’ın yolundan saptırır. Allâh’ın yolundan sapanlar ise, hesap gününü unuttuklarından dolayı, çetin azâba uğrayacaklardır."},{"n":27,"t":"Göğü, yeri ve ikisi arasındakileri boş yere yaratmadık (bunlar bir tesâdüf eseri değildir) bu, inkâr edenlerin zannıdır, (onlar kâinâtın boş bir tesadüf eseri olduğunu söylerler). Ateşten vay hallerine o nankörlerin!"},{"n":28,"t":"Yoksa biz, inanıp iyi işler yapanları, yeryüzünde bozgunculuk yapanlar gibi mi tutacağız? Yoksa korunanları yoldan çıkanlar gibi mi tutacağız?"},{"n":29,"t":"Sana (bu) mübarek Kitabı indirdik ki âyetlerini düşünsünler ve sâğduyu sâhipleri öğüt alsınlar."},{"n":30,"t":"Biz Dâvûd’a Süleymân’ı armağan ettik, (Süleymân) ne güzel kuldu! Hep Allâh’a başvururdu."},{"n":31,"t":"Akşam üstü kendisine sâfin (görkemli) hızlı koşan (sâf kan Arap) atları gösterilmişti."},{"n":32,"t":"\"Ben, dedi, mal sevgisini, Rabbimi anmaktan (ötürü) tercih ettim.\" Nihâyet bu atlar perde ile gizlendi (koşup dağın arkasına düşmekle gözden kayboldu)."},{"n":33,"t":"\"Onları bana getirin\" (dedi), bacaklarını ve boyunlarını okşamağa başladı."},{"n":34,"t":"Andolsun Süleymân’ı denedik. Tahtının üstüne bir ceset bıraktık, sonra (bize) yöneldi."},{"n":35,"t":"\"Rabbim,\" dedi, \"beni affet, bana, benden sonra hiç kimseye nasib olmayan bir mülk (hükümdarlık) ver. Çünkü Sensin o çok lutfeden, Sen!\""},{"n":36,"t":"Biz, rüzgârı ona boyun eğdirdik. Onun buyruğuyla, onun istediği yere tatlı tatlı eserdi."},{"n":37,"t":"Ve şeytânları; her binâ ustasını ve dalgıcı,"},{"n":38,"t":"Ve zincirlerle birbirine bağlanmış başka (şeytân)ları."},{"n":39,"t":"\"Bu bizim ihsânımızdır. Artık dilediğine ver veya verme, hesapsızdır.\" (dedik)."},{"n":40,"t":"Onun için, bizim yanımızda bir yakınlık ve güzel bir gelecek de vardır."},{"n":41,"t":"Kulumuz Eyyûb’u da an: (O) Rabbine \"Şeytân, bana bir yorgunluk ve azâb dokundurdu\" diye seslenmişti."},{"n":42,"t":"\"Ayağını (yere) vur, işte yıkanacak ve içilecek serin (bir su)\" (dedik)."},{"n":43,"t":"Ona bizden bir rahmet ve sağduyu sâhiplerine bir ibret olarak âilesini ve onlarla beraber bir eşini daha armağan ettik."},{"n":44,"t":"(Dedik ki): \"Eline bir demet sap al, onunla vur da yeminini bozma.\" Gerçekten biz onu sabreden (bir kul) bulmuştuk. Ne güzel kuldu, o dâimâ (bize) başvururdu."},{"n":45,"t":"Kuvvetli ve bâsiretli kullarımız İbrâhim’i, İshak’ı ve Ya’kûb’u da an."},{"n":46,"t":"Biz onları âhiret yurdunu düşünme özelliğiyle temizleyip, kendimize hâlis (kul) yaptık."},{"n":47,"t":"Onlar bizim yanımızda seçkinlerden, hayırlılardandır."},{"n":48,"t":"İsmâ’il’i, Elyesa’ı, Zülkifl’i de an. Hepsi de iyilerdendir."},{"n":49,"t":"Bu, bir hatırlatmadır. Korunanlar için güzel bir gelecek vardır:"},{"n":50,"t":"Kapıları kendilerine açılmış Adn cennetleri."},{"n":51,"t":"Orada (koltuklara) yaslanarak bir çok meyva ve içki isterler."},{"n":52,"t":"Yanlarında da bakışlarını yalnız (kocalarına) diken (kendileriyle) yaşıt dilberler vardır."},{"n":53,"t":"İşte, hesap günü için size söz verilen budur!"},{"n":54,"t":"Doğrusu bizim bu rızkımızın bitip tükenmesi yoktur!"},{"n":55,"t":"Bu böyledir; fakat azgınlara da en kötü bir gelecek vardır:"},{"n":56,"t":"Cehennem! Oraya girerler. Ne kötü bir döşektir o!"},{"n":57,"t":"İşte onu tadsınlar: Kaynar ve kokuşmuş sudur!"},{"n":58,"t":"Ve daha başka çeşit çeşit (azâb) vardır."},{"n":59,"t":"İşte şunlar da sizinle beraber (cehenneme) girecek olanlardır: \"Onlara merhaba yok, (yerleri geniş olmasın, rahat yüzü görmesinler)! Onlar ateşe gireceklerdir.\""},{"n":60,"t":"(Uyanlar, uyulanlara) Dediler ki: \"Hayır, asıl size merhaba yok, (asıl siz rahat yüzü görmeyin), siz bunu bizim önümüze getirdiniz. Ne kötü durak (bu)!\""},{"n":61,"t":"(Ve hepsi birbiri aleyhine du’â ederek): \"Rabbimiz, bunu bizim önümüze kim getirdiyse onun ateşteki azâbını bir kat daha artır!\" dediler."},{"n":62,"t":"\"Bize ne oldu ki, (dünyâda) kötülerden saydığımız adamları (burada) görmüyoruz?\" dediler."},{"n":63,"t":"\"Hani onlarla alay ederdik. Yoksa gözler(imiz) mi onlardan kaydı, (onları gözden mi kaçırdık)?\""},{"n":64,"t":"Bu, mutlaka gerçektir, ateş halkının tartışmasıdır (bunun olacağından aslâ şüphe yoktur)."},{"n":65,"t":"De ki: \"Ben ancak bir uyarıcıyım. Tek ve (her şeyi) kahreden Allah’tan başka tanrı yoktur.\""},{"n":66,"t":"\"O, göklerin, yerin ve ikisi arasındakilerin Rabbidir, dâimâ üstündür, çok bağışlayandır.\""},{"n":67,"t":"De ki: \"O, büyük bir haberdir.\""},{"n":68,"t":"\"(Ama gafletinizden dolayı) Siz ondan yüz çeviriyorsunuz.\""},{"n":69,"t":"\"Yüce topluluk tartışırlarken (aralarında) neler geçtiği hakkında bir bilgim yoktu.\""},{"n":70,"t":"\"Ben ancak apaçık bir uyarıcı olduğum için (bu bilgi) bana vahyediliyor.\""},{"n":71,"t":"Rabbin meleklere demişti ki: \"Ben çamurdan bir insan yaratacağım.\""},{"n":72,"t":"\"Onu biçimlendirip ona ruhumdan üflediğim zaman derhal ona secdeye kapanın!\""},{"n":73,"t":"Meleklerin hepsi tüm olarak secde ettiler."},{"n":74,"t":"Yalnız İblis etmedi, büyüklük tasladı ve kâfirlerden oldu."},{"n":75,"t":"(Rabbin ona) Dedi ki: \"Ey İblis, iki elimle yarattığıma secde etmekten seni alıkoyan nedir? Büyüklük mü tasladın, yoksa yücelerden mi oldun?\""},{"n":76,"t":"Dedi: \"Ben ondan iyiyim. Beni ateşten, onu çamurdan yarattın.\""},{"n":77,"t":"Buyurdu ki: \"Haydi çık oradan, sen kovuldun!\""},{"n":78,"t":"\"Tâ cezâ gününe kadar lânetim üzerinedir!\""},{"n":79,"t":"\"Rabbim, dedi, öyleyse yeniden dirilecekleri güne kadar bana süre ver.\""},{"n":80,"t":"Buyurdu: \"Haydi sen süre verilenlerdensin.\""},{"n":81,"t":"\"O belli vaktin gününe kadar.\""},{"n":82,"t":"(İblis) Dedi: \"Senin izzet ve şerefine and olsun ki, onların tümünü azdıracağım.\""},{"n":83,"t":"\"Yalnız onlardan ihlâslı kulların(a dokunmayacağım).\""},{"n":84,"t":"Buyurdu ki: \"Gerçektir (sen benim hâlis kullarımı kandıramazsın) ve ben gerçek olarak diyorum ki:"},{"n":85,"t":"Senden ve onlar içinde sana uyan kimselerden (gelenler ile) cehennemi dolduracağım!\""},{"n":86,"t":"De ki: \"Ben sizden buna karşı bir ücret istemiyorum. Ve ben yapmacık yapanlardan, (uydurma şeylerle peygamberlik taslayanlardan) değilim.\""},{"n":87,"t":"\"O (Kur’ân), ancak bütün âlemlere öğüttür.\""},{"n":88,"t":"Bir süre sonra \"Onun haberi(nin doğruluğu)nu gâyet iyi bileceksiniz!\""}],[{"n":1,"t":"Kitabın indirilmesi, aziz hüküm ve hikmet sâhibi Allâh tarafındandır."},{"n":2,"t":"Biz bu Kitabı sana hak ile indirdik; sen dini yalnız Allâh’a halis kılarak O’na kulluk et."},{"n":3,"t":"İyi bil ki, hâlis din yalnız Allâh’ındır. O’ndan başka veliler edinerek: \"Biz bunlara, sırf bizi Allâh’a yaklaştırmaları için tapıyoruz,\" diyenler(e gelince): Şüphesiz ki Allâh, onlar arasında, ayrılığa düştükleri konuda hükmünü verecektir. Allâh, yalancı, nankör insanı doğru yola iletmez."},{"n":4,"t":"Eğer Allâh çocuk edinmek isteseydi, yarattıklarından dilediğini seçerdi. O (bundan münezzehtir) yücedir. O tek ve kahredici Allâh’tır."},{"n":5,"t":"Gökleri ve yeri hak ile yarattı. Geceyi gündüzün üzerine dolar, gündüzü de gecenin üzerine dolar. Güneşi ve ayı buyruğu altına almıştır. Her biri belli bir süreye kadar akıp gitmektedir. İyi bil ki O, aziz ve çok bağışlayandır."},{"n":6,"t":"Sizi bir tek candan yarattı, sonra ondan eşini meydana getirdi ve sizin için davarlardan sekiz çift indirdi: (Deve, öküz, koyun, keçi.) Sizi annelerinizin karınlarında üç karanlık içinde yaratmadan yaratmaya (aşamadan aşamaya) geçirerek yaratmaktadır. İşte Rabbiniz Allâh budur. Mülk O’nundur. O’ndan başka tanrı yoktur. Nasıl (O’na kulluktan şirke) çevriliyorsunuz?"},{"n":7,"t":"Eğer nankörlük ederseniz, şüphesiz Allâh, siz(in imanınız)a muhtaç değildir. Fakat kulları için küfre râzı olmaz. Ve eğer şükrederseniz sizin için ona râzı olur. Hiçbir günâhkâr, diğerinin günâhını çekmez. Sonra dönüşünüz Rabbinizedir, (O), size yaptıklarınızı haber verir. Çünkü O, göğüslerin özünü bilir."},{"n":8,"t":"İnsana bir zarar dokundu mu, hemen içtenlikle Rabbine yönelerek O’na du’â eder. Sonra (Rabbi) ona kendisinden bir ni’met verdi mi; önceden O’na yalvarmakta olduğunu unutur da, O’nun yolundan saptırmak için Allah’a eşler koşmağa başlar. De ki: \"Küfrünle azıcık yaşa, sen ateş halkındansın!\""},{"n":9,"t":"Yoksa o, gece sâ’atlerinde secde ederek, ayakta durarak ibâdet eden, âhiretten korkan ve Rabbinin rahmetini uman gibi midir? De ki: \"Bilenlerle bilmeyenler bir olur mu?\" Doğrusu ancak sağduyu sâhipleri öğüt alır."},{"n":10,"t":"(Tarafımdan) De ki: \"Ey inanan kullarım, Rabbinizden korkun. Bu dünyâ hayâtında güzel davrananlara güzellik vardır. Allâh’ın yeri geniştir. Ancak sabredenlere, ödülleri hesapsız ödenecektir.\""},{"n":11,"t":"De ki: \"Bana dini yalnız Allah’a hâlis kılarak, O’na kulluk etmem emredildi.\""},{"n":12,"t":"\"Ve bana müslümanların ilki olmam emredildi.\""},{"n":13,"t":"De ki: \"Ben, Rabbime isyân edersem, büyük bir günün azâbından korkarım.\""},{"n":14,"t":"De ki: \"Ben, dinimi yalnız Allah’a hâlis kılarak O’na kulluk ediyorum.\""},{"n":15,"t":"\"Siz de O’ndan başka dilediğinize kulluk edin.\" De ki: \"Ziyana uğrayanlar kıyâmet günü hem kendilerini, hem de âilelerini ziyan edenlerdir. Dikkat edin, işte bu, apaçık bir ziyandır!\""},{"n":16,"t":"Onların üstlerinden ateşten gölgeler, altlarından da (ateşten) gölgeler var. İşte Allâh kullarını bu durumdan korkutur. Ey kullarım, benden korkun!"},{"n":17,"t":"Tâğût’a kulluk etmekten kaçınan ve Allah’a yönelenlere müjde var. Müjdele kullarımı:"},{"n":18,"t":"Onlar ki, sözü dinlerler ve onun en güzeline uyarlar. İşte onlar Allâh’ın kendilerini doğru yola ilettiği kimselerdir ve onlar sağduyu sâhipleridir."},{"n":19,"t":"Üzerine azâb kararı hak olanı mı, sen ateşte bulunanı mı kurtaracaksın?"},{"n":20,"t":"Fakat Rablerinden korkanlar için üstüste yapılmış odalar var. Odaların altından da ırmaklar akmaktadır. Bu, Allâh’ın va’didir. Allâh va’dinden caymaz."},{"n":21,"t":"Görmedin mi Allâh gökten bir su indirdi, onu yerin içindeki kaynaklara geçirdi, Sonra onunla çeşitli renklerde ekin çıkarıyor. Sonra (ekin) kurur, onu sararmış görürsün. Sonra Allâh onu bir çöp yapar. Şüphesiz bunda sağduyu sâhipleri için bir ibret vardır."},{"n":22,"t":"Allâh’ın, göğsünü İslâm’a açtığı kimse, Rabbinden bir nur üzerinde değil midir? Allâh’ı anmağa karşı yürekleri katılaşmış olanlara yazıklar olsun. Onlar apaçık bir sapıklık içindedirler."},{"n":23,"t":"Allâh, sözün en güzelini, (Kur’ân’ın âyetlerini güzellikte) birbirine benzer, ikişerli bir Kitap halinde indirdi. Rablerinden korkanların, ondan derileri ürperir, sonra derileri ve kalbleri Allâh’ın zikrine yumuşar. İşte bu (Kitap) Allâh’ın rehberidir. Dilediğini bununla doğru yola iletir. Ama Allâh kimi sapıklığında bırakırsa artık ona yol gösteren olmaz."},{"n":24,"t":"Kıyâmet günü, (elleri bağlı olduğu için) yüzüyle o en kötü azâbdan korunmağa çalışan (ile güven içinde bulunan bir olur) mu? (O gün) Zâlimlere: \"Kazandığınız(ın tadın)ı tadın!\" denmiştir."},{"n":25,"t":"Onlardan öncekiler de yalanladılar, bundan dolayı hiç farkına varmadıkları bir yönden onlara azâb geldi."},{"n":26,"t":"Allâh, dünyâ hayâtında onlara rezillik taddırdı. Âhiret azâbı ise daha büyüktür, keşke bilselerdi!"},{"n":27,"t":"Andolsun biz, bu Kur’ân’da insanlara, öğüt almaları için her temsili anlattık."},{"n":28,"t":"Korunanlar için bunu, pürüzsüz Arapça bir Kur’an olarak (indirdik)."},{"n":29,"t":"Allâh, (ortak koşanla tek Allah’a inananın durumunu anlatmak için) şöyle bir misâl verdi: Birbiriyle çekişen ortaklara bağlı olan bir adam (yani köle) ile yalnız bir kişiye bağlı olan bir adam. Şimdi bu ikisinin durumu bir olur mu? Hamd yalnız Allah’a mahsustur, fakat çokları (yalnız Allah’a tapılacağını) bilmiyorlar."},{"n":30,"t":"Sen de öleceksin, onlar da ölecekler."},{"n":31,"t":"Sonra siz, kıyâmet günü, Rabbinizin divânında dâvâlaşacaksınız."},{"n":32,"t":"Allâh hakkında yalan uydurandan ve kendisine gelen doğruyu yalanlayandan daha zâlim kim olabilir? Cehennemde kâfirler için bir yer yok mudur?"},{"n":33,"t":"Doğruyu getirene ve onu doğrulayanlara gelince: İşte korunanlar onlardır."},{"n":34,"t":"Rablerinin yanında onlara, diledikleri her şey var. İşte güzel davrananların mükâfâtı budur."},{"n":35,"t":"(Böyle olur) Ki Allâh onların yaptıklarının en kötülerini onlardan örtsün ve onları, yaptıklarının en güzeliyle mükâfâtlandırsın."},{"n":36,"t":"Allâh kuluna kâfi değil mi? Seni O’ndan başkalarıyle korkutuyorlar. Allâh kimi şaşırtırsa artık onu yola getiren olmaz."},{"n":37,"t":"Allâh kime de yol gösterirse; artık onu şaşırtan olmaz. Allâh gâlib ve öç alan değil midir?"},{"n":38,"t":"Andolsun onlara: \"Gökleri ve yeri kim yarattı?\" diye sorsan, elbette \"Allâh\" derler. De ki: \"O halde Allah’tan başka yalvardıklarınızı gördünüz mü, şimdi Allâh, bana bir zarar vermek istese, onlar O’nun vereceği zararı kaldırabilirler mi? Yahut (Allâh) bana bir rahmet (fayda) vermek dilese onlar O’nun rahmetini durdurabilirler mi?\" De ki: \"Allâh bana yeter. Tevekkül edenler O’na dayanırlar.\""},{"n":39,"t":"De ki: \"Ey kavmim, durumunuza göre bildiğinizi yapın, ben de (bildiğimi) yapıyorum; yakında bileceksiniz;\""},{"n":40,"t":"\"Kendisini rezil edecek azâb kime geliyor ve sürekli azâb kimin üzerine konuyor?\""},{"n":41,"t":"Biz Kitabı, insanlar için, sana hak ile indirdik. Artık kim doğru yola gelirse kendi yararınadır, kim de saparsa kendi zararına sapmış olur. Sen onların üzerinde vekil değilsin."},{"n":42,"t":"Allâh, ölmekte olan canları alır, ölmeyenleri de uykularında (bedenlerinden alıp kendilerinden geçirir); sonra ölümüne hükmettiğini yanında tutar, ötekilerini de belli bir süreye kadar salıverir. Şüphesiz bunda düşünen bir toplum için ibretler vardır."},{"n":43,"t":"Yoksa Allâh’tan başka şefâ’atçiler mi edindiler? De ki: \"Onlar, hiçbir şeye malik olmayan, düşünmeyen şeyler olsalar da mı (onları şefâ’atçi edineceksiniz?)\""},{"n":44,"t":"De ki: \"Şefâ’at tamamen Allâh’ındır (yardım ve destek yalnız O’ndandır). Göklerin ve yerin mülkü O’nundur. Sonra O’na döndürüleceksiniz.\""},{"n":45,"t":"Allâh, tek olarak anıldığı zaman; âhirete inanmayanların kalbleri ürker. Ama O’ndan başka (tanrı)ları da anıldığı zaman, hemen sevinirler."},{"n":46,"t":"De ki: \"Allâh’ım, ey gökleri ve yeri yoktan var eden, görülmeyeni ve görüleni bilen! Ancak Sen, ayrılığa düştükleri şeylerde kullarının arasında hükmedersin.\""},{"n":47,"t":"Eğer yeryüzünde bulunanların tümü ve onun bir misli daha zulmedenlerin olsaydı, kıyâmet günü o kötü azâbdan (kurtulmak için) onu mutlaka fidye verirlerdi. (Çünkü) hiç hesab etmedikleri şeyler, Allah’tan karşılarına çıkmıştır."},{"n":48,"t":"Yaptıkları işlerin kötülükleri kendilerine görünmüş ve alay edegeldikleri şey onları kuşatmıştır."},{"n":49,"t":"İnsana bir zarar dokunduğu zaman bize du’â eder. Sonra, ona bizden bir ni’met verdiğimiz vakit; \"Bu, (benim) bilgi(m) sayesinde bana verildi\" der. Hayır, o bir imtihandır, fakat çokları bilmiyorlar."},{"n":50,"t":"Onlardan öncekiler de bunu demişlerdi. Ama kazandıkları şeyler, kendilerine hiçbir yarar sağlamadı."},{"n":51,"t":"Kazandıklarının kötülükleri, sonunda başlarına geldi. Bunlardan zulmedenlere de yaptıklarının kötülükleri erişecektir. Onlar, buna engel olacak değillerdir."},{"n":52,"t":"Bilmediler mi ki Allâh dilediğine rızkı açar ve kısar. Şüphesiz bunda inanan bir toplum için ibretler vardır."},{"n":53,"t":"(Tarafımdan onlara) De ki: \"Ey nefislerine karşı aşırı giden kullarım, Allâh’ın rahmetinden umut kesmeyin. Allâh bütün günâhları bağışlar. Çünkü O, çok bağışlayan, çok esirgeyendir.\""},{"n":54,"t":"\"Size azâb gelip çatmadan Rabbinize dönün, O’na teslim olun. Sonra size yardım edilmez.\""},{"n":55,"t":"\"Ansızın ve hiç farkına varmadığınız bir sırada, size azâb gelmezden önce Rabbinizden size indirilenin en güzeline uyun.\""},{"n":56,"t":"(O gün günâhkâr) nefsin şöyle demesinden sakının: \"Allâh’ın yanında (O’na kullukta) kusur edişimden dolayı vah (bana). Gerçekten ben alay edenlerdendim.\""},{"n":57,"t":"Yahut şöyle demesinden: \"Allâh bana hidâyet etseydi, elbet ben de (Allâh’ın azâbından) korunanlardan olurdum.\""},{"n":58,"t":"Yahut azâbı gördüğü zaman: \"Keşke benim için bir kez daha (dünyâya dönüş) olsaydı da güzel hareket edenlerden olsaydım!\" demesinden."},{"n":59,"t":"(Allâh şöyle buyurur): \"Hayır, sana âyetlerim geldi de sen onları yalanladın, büyüklük tasladın ve nankörlerden oldun!\""},{"n":60,"t":"Allah’a yalan uyduranların kıyâmet günü yüzlerinin kapkara kesildiğini görürsün. Kibirlenenler için cehennemde bir yer yok mudur?"},{"n":61,"t":"Allâh, korunanları başarılarıyla kurtarır, onlara kötülük dokunmaz ve onlar üzülmezler."},{"n":62,"t":"Allâh her şeyin yaratıcısıdır, O, her şeyin yöneticisidir."},{"n":63,"t":"Göklerin ve yerin anahtarları O’nundur. Allâh’ın âyetlerini inkâr edenler, işte ziyana uğrayacaklar onlardır."},{"n":64,"t":"De ki: \"Allah’tan başkasına kulluk etmemi mi bana emrediyorsunuz ey câhiller?\""},{"n":65,"t":"Sana ve senden öncekilere şöyle vahyedildi: \"Andolsun, eğer (Allah’a) ortak koşarsan amelin boşa çıkar ve kaybedenlerden olursun!\""},{"n":66,"t":"Hayır, yalnız Allah’a kulluk et ve şükredenlerden ol."},{"n":67,"t":"Allâh’ı gereği gibi bilemediler. Halbuki kıyâmet günü yer, tamamen O’nun avucu içindedir, gökler de sağ elinde dürülmüştür. O, onların ortak koştuklarından uzak ve yücedir."},{"n":68,"t":"Sûr’a üflenmiş, göklerde ve yerde olanlar (korkudan) bayılmışlar, ancak Allâh’ın dilediği sarsılmamıştır. Sonra ona bir daha üflenmiştir, birden onlar kalkmış, bakıyorlardır."},{"n":69,"t":"Yer, Rabbinin nuru ile parlamış, Kitâp (ortaya) konmuş, peygamberler ve şâhidler getirilmiş ve aralarında adâletle hükmedilmiştir. Onlara asla haksızlık edilmez"},{"n":70,"t":"Herkese yaptığının karşılığı tam verilmiştir. O, onların ne yaptıklarını en iyi bilendir."},{"n":71,"t":"Nankörler, bölük bölük cehenneme sürülmüşlerdir. Oraya geldikleri zaman, kapıları açılan cehennemin bekçileri onlara şöyle demiştir: \"Kendi aranızdan, Rabbinizin âyetlerini size okuyan ve sizi bu gününüzle karşılaşacağınız hakkında uyaran elçiler gelmedi mi?\" \"Evet geldi, demişlerdir; ama kâfirlere azâb sözü hak olmuştur (kâfirler azâb hükmünü giymeyi hak etmişlerdir).\""},{"n":72,"t":"\"O halde içinde ebedi kalmak üzere cehennemin kapılarından girin. Kibirlenenlerin yeri ne kötüymüş!\" denilmiştir."},{"n":73,"t":"Rablerinin (azâbından) korunanlar da bölük bölük cennete sevk edilmişlerdir. Kapıları daha önce açılmış bulunan cennete vardıklarında onun bekçileri onlara: \"Selâm size,(ne) hoşsunuz, ebedi kalmak üzere buraya girin!\" demişlerdir."},{"n":74,"t":"(Cennettekiler de:) \"Bize verdiği sözü yerine getiren ve bizi dilediğimiz yerinde oturacağımız bu cennet yurduna vâris kılan Allah’a hamdolsun. (Allâh için) çalışanların ücreti ne güzeldir!\" demişlerdir."},{"n":75,"t":"Meleklerin de Arşın çevresinde dönerek Rablerini övgü ile andıklarını görürsün. İnsanlar arasında hak ile hükmedilmiş ve: \"Hamd âlemlerin Rabbine mahsustur\" denilmiştir."}],[{"n":1,"t":"Hâ mim."},{"n":2,"t":"Bu Kitabın indirilişi, aziz (dâimâ gâlib) ve alim (herşeyi en iyi bilen) Allâh tarafındandır;"},{"n":3,"t":"Günâhı bağışlayan, tevbeyi kabul eden, azâbı çetin olan, lutuf sâhibi (Allâh tarafından). O’ndan başka tanrı yoktur, dönüş O’nadır."},{"n":4,"t":"İnkâr edenlerden başkası, Allâh’ın âyetleri hakkında mücâdele etmez. Onların (öyle) şehirlerde dolaşmaları, seni aldatmasın."},{"n":5,"t":"Onlardan önce Nûh kavmi ve onlardan sonra gelen kollar da yalanladı. Her millet, elçisini yakalamağa yeltendi; hakkı gidermek için boş şeyler ileri sürerek tartıştılar. Bu yüzden onları yakaladım. (Bak işte) Azâbım nasıl oldu?!"},{"n":6,"t":"Böylece Rabbinin inkâr edenler hakkındaki \"Onlar ateş halkıdır\" sözü yerini bulmuş oldu."},{"n":7,"t":"Arş’ı taşıyanlar ve onun çevresinde bulunanlar, Rablerini överek tesbih ederler. O’na inanırlar ve mü’minler için (şöyle) mağfiret dilerler: \"Rabbimiz, Sen rahmet ve bilgi bakımından her şeyi kapladın. Tevbe edip senin yoluna uyanları bağışla, onları cehennem azâbından koru!\""},{"n":8,"t":"\"Rabbimiz, onları ve babalarından, eşlerinden, çocuklarından iyi olan kimseleri onlara söz verdiğin Adn cennetlerine sok. Şüphesiz, üstün olan, hüküm ve hikmet sâhibi olan sensin sen!\""},{"n":9,"t":"\"Onları kötülüklerden koru. O gün Sen, kimi kötülüklerden korursan ona acımışsındır. İşte o büyük başarı budur!\""},{"n":10,"t":"İnkâr edenlere de bağırılır: \"Allâh’ın (size) kızması, sizin kendi kendinize kızmanızdan daha büyüktür. Zira siz imânâ çağrılırdınız da inkâr ederdiniz!\""},{"n":11,"t":"Dediler ki: \"Rabbimiz, bizi iki kez öldürdün ve iki kez dirilttin. Günâhlarımızı itiraf ettik. Şimdi (şu ateşten) çıkmak için (bize) bir yol var mı (acaba)?\""},{"n":12,"t":"(Şöyle cevap verilir): Bu (duruma düşmeniz)in sebebi şudur: Tek Allah’a çağrıldığınız zaman inkâr ederdiniz. O’na ortak koşulunca inanırdınız. Artık hüküm yüce ve büyük Allâh’a âittir."},{"n":13,"t":"O’dur ki, size âyetlerini gösteriyor ve sizin için gökten rızık indiriyor, (rızkın sebebi olan yağmur, güneş ve hava veriyor). Ancak (O’na) yönelen öğüt alır."},{"n":14,"t":"Kâfirlerin hoşuna gitmesede siz, dini yalnız Allah’a hâlis kılarak O’na çağırın."},{"n":15,"t":"(O,) Dereceleri yükselten; Arş’ın sâhibi (Allâh), buluşma gününe karşı uyarmak için, emrinden olan ruhu, kullarından dilediğine indirir."},{"n":16,"t":"O gün onlar, ortaya çıkarlar. Onlardan hiçbir şey Allah’a gizli kalmaz. (Ve sorulur onlara): \"Bugün mülk kimindir? O tek ve kahhâr olan Allâh’ın!\""},{"n":17,"t":"Bugün her can, kazandığıyla cezâlanır. Bugün zulüm yoktur. Allâh, hesabı çabuk görendir."},{"n":18,"t":"Onları yaklaşan güne karşı uyar. Zira (o gün) yürekler, (korkudan âdetâ yerinden sökülüp) gırtlaklara dayanmıştır; (kederlerini) yutkunur dururlar. Zâlimlerin ne bir dostu, ne de sözü tutulur bir aracıları yoktur."},{"n":19,"t":"(Allâh) gözlerin hâin (bakışlar)ını ve göğüslerin gizlediği düşünceleri bilir."},{"n":20,"t":"Allâh, hak ile hükmeder. O’ndan başka yalvardıkları (tanrılar) ise hiçbir hüküm veremezler. Çünkü işiten, gören yalnız Allah’tır."},{"n":21,"t":"(Onlar) Yeryüzünde gezip dolaşmadılar mı ki, kendilerinden önce gelenlerin sonunun nasıl olduğunu görsünler. Onlar kuvvet ve yeryüzündeki eserleri bakımından kendilerinden daha üstün idiler. Fakat Allâh, onları günâhları yüzünden yakaladı. Onları Allâh’a karşı koruyan olmadı."},{"n":22,"t":"Çünkü onlar (öyle kimselerdi ki) elçileri onlara açık kanıtlar getirirdi ama kabul etmezlerdi. Bu yüzden Allâh onları yakaladı. Zira O güçlüdür, cezâsı çetin olandır."},{"n":23,"t":"Andolsun biz Mûsâ’yı âyetlerimizle ve apaçık bir yetki ile gönderdik:"},{"n":24,"t":"Fir’avn’e, Hâmân’a ve Kârûn’a. \"(Bu,) Yalancı bir büyücüdür.\" dediler."},{"n":25,"t":"(Mûsâ,) Onlara katımızdan hakkı getirince: \"Onunla beraber inananların oğullarını öldürün, kadınlarını sağ bırakın!\" dediler. Fakat kâfirlerin tuzağı hep boşa çıkar."},{"n":26,"t":"Fir’avn dedi: \"Bırakın Mûsâ’yı öldüreyim de, Rabbine yalvarsın (bakalım O, Mûsâ’yı kurtaracak mı?) Çünkü ben onun, dininizi değiştireceğinden yahut yeryüzünde fesâd çıkaracağından korkuyorum\""},{"n":27,"t":"Mûsâ dedi: \"Ben, hesap gününe inanmayan her kibirliden, benim de Rabbim sizin de Rabbiniz(olan Allâh)a sığındım.\""},{"n":28,"t":"Fir’avn âilesinden imanını gizleyen mü’min bir adam (şöyle) dedi: \"Rabbim Allah’tır dediği için bir adamı öldürüyor musunuz? Oysa o size Rabbinizden kanıtlar getirmiştir. Eğer yalancı ise yalanı kendi zararınadır. Ve eğer doğru söylüyorsa, size va’dettiklerinin bir kısmı başınıza gelir. Şüphesiz Allâh aşırı giden, yalancı kimseyi doğru yola iletmez.\""},{"n":29,"t":"\"Ey kavmim, bugün mülk sizindir; buraya siz hâkimsiniz. Eğer bize (Allâh’ın hışmı) gelirse kim bizi ondan kurtarır?\" Fir’avn dedi: \"Ben size yalnız (doğru) gördüğümü gösteriyorum ve ben sizi ancak doğru yola götürüyorum.\""},{"n":30,"t":"İnanan adam dedi ki: \"Ey kavmim, ben üzerinize önceki toplulukların günü gibi bir günün gelmesinden korkuyorum."},{"n":31,"t":"Nûh kavminin, ’Âd ve Semûd’un ve onlardan sonrakilerin durumu gibi (bir durumla karşılaşmanızdan kaygı duyuyorum). Allâh kullara zulmetmek istemez, (günâhsız kimselere cezâ vermez)."},{"n":32,"t":"Ey kavmim, sizin için o (Yüce Divâna) çağırma (yahut feryâd etme) gününden korkuyorum."},{"n":33,"t":"O gün arkanızı dönüp kaç(mak ist)ersiniz ama sizi Allâh(ın azâbın)dan kurtaracak kimse yoktur. Allâh kimi şaşırtırsa artık ona yol gösteren olmaz."},{"n":34,"t":"Daha önce Yûsuf da size açık kanıtlar getirmişti. Onun getirdiklerinden de kuşkulanıp duruyordunuz. Nihâyet o ölünce: ’Allâh ondan sonra elçi göndermez,’ dediniz. İşte Allâh, aşırı giden, şüpheci kimseleri böyle saptırır.\""},{"n":35,"t":"Onlar ki kendilerine gelmiş bir delil olmadan Allâh’ın âyetleri hakkında tartışırlar. (Bu hareketleri) Gerek Allâh yanında, gerek inananlar yanında (onlara karşı) ne büyük bir kızgınlık (doğurur)! İşte Allâh, her kibirli zorbanın kalbini böyle mühürler.\""},{"n":36,"t":"Fir’avn dedi: \"Ey Hâmân, bana yüksek bir kule yap da o sebeplere (yollara) erişeyim:\""},{"n":37,"t":"\"(Yani) Göklerin yollarına (erişeyim) de çıkıp Mûsâ’nın tanrısına bakayım. Çünkü ben Mûsâ’yı, yalancı sanıyorum.\" Böylece yaptığı kötü iş, Fir’avn’a süslü gösterildi ve (o), yoldan çıkarıldı. Fir’avn’ın tuzağı, tamamen boşa çıktı."},{"n":38,"t":"İnanan (adam) dedi ki: \"Ey kavmim, bana uyun, sizi doğru yola götüreyim.\""},{"n":39,"t":"\"Ey kavmim, bu dünyâ hayâtı (kısa) bir geçinmedir. Âhiret ise ebedi olarak durulacak yerdir.\""},{"n":40,"t":"\"Kim bir kötülük yaparsa sadece onun (yaptığı kötülük) kadar cezâlanır, ama erkek ve kadından her kim inanarak faydalı bir iş yaparsa onlar cennete girerler ve orada kendilerine hesapsız rızık verilir.\""},{"n":41,"t":"\"Ey kavmim, neden ben sizi kurtuluşa çağırdığım halde siz beni ateşe çağırıyorsunuz?\""},{"n":42,"t":"\"Siz beni, Allah’a nankörlük etmeğe ve bilmediğim şeyleri O’na ortak koşmağa çağırıyorsunuz; bense sizi O aziz ve çok bağışlayana çağırıyorum.\""},{"n":43,"t":"\"Sizin beni çağırdığınız şeye kesinlikle ne dünyâda, ne de âhirette du’â edilemez (onlar kendilerine yapılan du’âyı duymazlar ve ona cevap veremezler). Bizim dönüşümüz Allah’adır. Aşırı gidenler, işte onlar ateş halkıdır.\""},{"n":44,"t":"\"Benim size söylediklerimi yakında hatırlayacaksınız. Ben işimi Allah’a bırakıyorum. Şüphesiz Allâh, kulları görür.\""},{"n":45,"t":"Allâh onu, onların kurdukları tuzakların kötülüklerinden korudu ve Fir’avn âilesini, azâbın en kötüsü kuşattı:"},{"n":46,"t":"Ateş! Sabah akşam ona sunulurlar. Kıyâmet koptuğu gün de: \"Fir’avn âilesini azâbın en çetinine sokun!\" (denilir)."},{"n":47,"t":"Ateşin içinde birbirleriyle tartışırlarken, zayıf olanlar, büyüklük taslayanlara dediler ki: \"Biz size uymuştuk. Şimdi siz, şu ateşin ufak bir parçasını bizden savabilir misiniz?\""},{"n":48,"t":"Büyüklük taslayanlar da dediler ki: \"Hepimiz de onun içindeyiz. Allâh kulları arasında (böyle) hüküm verdi!\""},{"n":49,"t":"Ateştekiler, cehennemin bekçilerine dediler ki: \"Rabbinize du’â edin de hiç değilse bir gün, bizden azâbı biraz hafifletsin!\""},{"n":50,"t":"(Bekçiler) Dediler: \"Elçileriniz size açık kanıtlar getirmezler miydi?\" \"Evet (getirirlerdi) dediler. (Bekçiler:) \"Öyle ise yalvar(ıp dur)un. Nankörlerin yalvarması hep çıkmazdadır.\" dediler."},{"n":51,"t":"Elbette biz elçilerimize ve inananlara hem dünyâ hayâtında hem, şâhidlerin (şâhidliğe) duracakları günde yardım ederiz."},{"n":52,"t":"O gün zâlimlere, ma’zeretleri fayda vermez. Onlar için la’net ve yurt(lar)ın en kötüsü vardır."},{"n":53,"t":"Andolsun biz Mûsâ’ya hidâyet verdik ve İsrâiloğullarına o Kitabı mirâs kıldık."},{"n":54,"t":"(O,) sağduyu sâhiplerine bir yol gösterici ve öğüttür."},{"n":55,"t":"Sabret, Allâh’ın va’di mutlaka gerçektir. Günâhına da istiğfar et ve akşam sabah Rabbini övgü ile an."},{"n":56,"t":"Kendilerine gelmiş hiçbir delil olmadan Allâh’ın âyetleri hakkında tartışanlar var ya, onların göğüslerinde, (hiçbir zaman) erişemeyecekleri bir büyüklük taslamaktan başka bir şey yoktur. Sen Allah’a sığın, çünkü işiten, gören O’dur."},{"n":57,"t":"Gökleri ve yeri yaratmak, insanları yaratmaktan çok daha zordur. Fakat insanların çoğu bilmezler."},{"n":58,"t":"Körle gören bir olmaz. İnanan ve iyi işler yapanlarla kötülük yapan bir olmaz. Ne kadar az düşünüyorsunuz!"},{"n":59,"t":"(Duruşma) sâ’at(i) mutlaka gelecektir. Bunda asla şüphe yoktur. Fakat insanların çoğu inanmazlar."},{"n":60,"t":"Rabbiniz buyurdu ki: \"Bana du’â edin, du’ânızı kabul edeyim. Bana kulluk etmeğe tenezzül etmeyenler, aşağılık olarak cehenneme gireceklerdir.\""},{"n":61,"t":"Allâh O’dur ki size geceyi, içinde istirahat etmeniz için (serin ve karanlık); gündüzü de (işinizi) görmeniz için aydınlık yaptı. Şüphesiz Allâh, insanlara lutufkârdır; fakat insanların çoğu şükretmezler."},{"n":62,"t":"İşte herşeyin yaratıcısı olan Rabbiniz Allâh budur. O’ndan başka tanrı yoktur. Nasıl da (O’nu birlemekten) çevriliyorsunuz?"},{"n":63,"t":"İşte Allâh’ın âyetlerini kasden inkâr edenler de (haktan) böyle çevriliyorlardı."},{"n":64,"t":"Allâh O’dur ki arzı size durulacak yer, göğü de binâ yaptı; sizi şekillendirdi, şekillerinizi de güzel yaptı. Ve sizi güzel rızıklarla besledi. İşte Rabbiniz Allâh budur. Bütün âlemleri yaratan Allâh, ne yücedir!"},{"n":65,"t":"O diridir, O’ndan başka tanrı yoktur. Dini yalnız kendisine hâlis kılarak O’na yalvarın. Hamd, âlemlerin Rabbine mahsustur."},{"n":66,"t":"De ki: \"Ben, Rabbimden bana açık deliller gelince, sizin Allah’tan başka yalvardıklarınıza tapmaktan men olundum ve âlemlerin Rabbine teslim olmakla emrolundum.\""},{"n":67,"t":"O’dur ki (önce) sizi topraktan, sonra nutfe (sperm)den, sonra alaka (embriyo)dan yarattı. Sonra sizi çocuk olarak (annelerinizin karnından) çıkarıyor. Sonra güçlü çağınıza eresiniz, sonra da ihtiyarlar olasınız diye sizi yaşatıyor. İçinizden kimi de daha önce öldürülüyor. Belli süreye erişmeniz ve aklınızı kullan(ıp Allâh’ın bundaki hikmetlerini anla)manız için (böyle yapıyor)."},{"n":68,"t":"Yaşatan ve öldüren O’dur. Bir işin olmasını istedi mi, ona sadece \"ol!\" der, o da olur."},{"n":69,"t":"Baksana, Allâh’ın âyetleri hakkında tartışanlar, nasıl (Hak’tan) çevriliyorlar?"},{"n":70,"t":"O, Kitabı ve elçilerimizi gönderdiğimiz mesajı yalanlayanlar, yakında bileceklerdir!"},{"n":71,"t":"Boyunlarında demir halkalar ve zincirler olduğu halde sürüklenceklerdir."},{"n":72,"t":"Kaynar su içinde. Sonra da ateşte yakılacaklardır."},{"n":73,"t":"Sonra onlara denilecektir: \"Ortak koştuklarınız nerede?"},{"n":74,"t":"Allah’tan başka (taptıklarınız)?\" Diyecekler ki: \"Bizden (uzaklaşıp) kayboldular; hayır, meğer biz önceden hiçbir şeye tapmıyormuşuz, (taptıklarımız hiçbir şey değilmiş)!\" İşte Allâh, kâfirleri böyle şaşırtır."},{"n":75,"t":"\"Bu durum, sizin yeryüzünde haksız olarak şımarmanızdan ve bölürlenmenizden ötürüdür.\""},{"n":76,"t":"\"Cehennemin kapılarından girin, orada ebedi kalacaksınız. Kibirlenenlerin yeri ne kötüdür!\""},{"n":77,"t":"Sabret, Allâh’ın sözü gerçektir. Onları tehdit ettiğimiz şeylerin bir kısmını ya sana gösteririz yahut seni daha önce vefat ettiririz. (Sonunda) onlar bize döndürüleceklerdir."},{"n":78,"t":"Andolsun biz, senden önce de elçiler gönderdik. Onlardan kimini sana anlattık, kimini de anlatmadık. Hiçbir elçi, Allâh’ın izni olmadan bir mu’cize getiremez. Allâh’ın emri geldiği zaman hak yerine getirilir ve işte o zaman (Allâh’ın âyetlerini) boşa çıkarmağa uğraşanlar, hüsrana uğrarlar."},{"n":79,"t":"Allah’tır ki kimine binmeniz, kiminden yemeniz için size hayvanları yarattı."},{"n":80,"t":"Onlarda sizin için (sütleri, derileri, tüyleri gibi daha birçok) faydalar var. Onların üstünde gönüllerinizdeki arzuya erersiniz; onların ve gemilerin üstünde taşınırsınız."},{"n":81,"t":"(Allâh) Size âyetlerini gösteriyor. Allâh’ın âyetlerinden hangisini inkâr ediyorsunuz?"},{"n":82,"t":"Yeryüzünde gezip dolaşmadılar mı ki kendilerinden öncekilerin sonunun nasıl olduğunu görsünler? Onlar, bunlardan daha çok, daha kuvvetli ve yeryüzündeki eserleri bakımından daha sağlam idiler. Ama kazandıkları, kendilerine hiçbir yarar sağlamadı."},{"n":83,"t":"Elçileri onlara açık kanıtlar getirince, yanlarında bulunan bilgi ile sevin(ip övün)düler (peygamberlerin getirdikleri bilgiye değer vermediler, onlarla alay ettiler). Sonunda alay edegeldikleri şey, kendilerini kuşatıverdi."},{"n":84,"t":"Ne zaman ki hışmımızı gördüler: \"Tek Allah’a inandık ve O’na ortak koştuğumuz şeyleri inkâr ettik.\" dediler."},{"n":85,"t":"Fakat hışmımızı gördükleri zaman inanmaları, kendilerine bir fayda sağlamadı. Allâh’ın kulları hakkında eskiden beri yürürlükte olan yasası budur. İşte o zaman kâfirler ziyana uğramışlardır."}],[{"n":1,"t":"Hâ mim."},{"n":2,"t":"(Bu,) Rahmân, Rahim’den indirilmiştir."},{"n":3,"t":"Bilen bir toplum için âyetleri açıklanmış, Arapça okunan bir Kitaptır."},{"n":4,"t":"Müjdeleyici ve uyarıcı olarak (gönderilmiştir). Fakat çokları yüz çevirmiştir; onlar işitmezler."},{"n":5,"t":"Dediler ki: \"Bizi çağırdığın şeye karşı kalblerimiz kılıflar içinde, kulaklarımızda bir ağırlık ve seninle bizim aramızda bir perde var. Sen (istediğini) yap, biz de (istediğimizi) yapıyoruz.\""},{"n":6,"t":"De ki: \"Ben de ancak sizin gibi bir insanım. Bana, tanrınızın bir tek Tanrı olduğu vahyediliyor. O’na doğrulun (O’na yönelerek işlerinizi düzeltin), O’ndan mağfiret dileyin. (O’na) Ortak koşanların vay haline!\""},{"n":7,"t":"Onlar ki zekât vermezler ve onlar âhireti de inkâr ederler."},{"n":8,"t":"İnanıp iyi işler yapanlara gelince; onlar için kesintisiz bir mükâfât vardır."},{"n":9,"t":"De ki: \"Siz mi arzı iki günde Yaratan’a nankörlük ediyor ve O’na eşler koşuyorsunuz? O, âlemlerin Rabbidir.\""},{"n":10,"t":"Arza, üstünden ağır baskılar (sağlam dağlar) yaptı. Onda bereketler yarattı ve onda arayıp soranlar için gıdalarını (bitkilerini ve ağaçlarını) tam dört günde takdir etti (düzene koydu)."},{"n":11,"t":"Sonra duman (gaz) halinde bulunan göğe yöneldi, ona ve arza: \"İsteyerek veya istemeyerek (buyruğuma) gelin\" dedi. \"İsteyerek (buyruğuna) geldik.\" dediler."},{"n":12,"t":"Böylece onları, iki günde yedi gök yaptı ve her göğe emrini (kanunlarını) vahyetti. Biz, en yakın göğü lambalarla ve koruma ile (koruyucu güçlerle) donattık. İşte bu, o güçlü, bilen (Allâh)ın takdiridir."},{"n":13,"t":"Eğer yüz çevirirlerse, de ki: \"Ben sizi ’Âd ve Semûd’un başına düşen yıldırım gibi bir yıldırıma karşı uyardım.\""},{"n":14,"t":"Onlara: \"Yalnız Allah’a kulluk edin!\" diye önlerinden ve arkalarından elçiler gelmişti. \"Rabbimiz dileseydi, melekler indirirdi. Biz sizinle gönderilen mesajı tanımıyoruz.\" dediler."},{"n":15,"t":"’Âd (kavmi), yeryüzünde haksız olarak büyüklük tasladılar ve: \"Bizden daha kuvvetli kim var?\" dediler. Onları yaratan Allâh’ın kendilerinden daha güçlü olduğunu görmediler mi? Bizim âyetlerimizi de inkâr ediyorlardı."},{"n":16,"t":"Biz de onlara dünyâ hayâtında rezillik azâbını taddırmak için o uğursuz günlerde, üzerlerine dondurucu bir rüzgâr gönderdik. Âhiret azâbı ise daha da kepaze edicidir. Onlara hiç yardım edilmeyecektir."},{"n":17,"t":"Semûd (kavmin)e gelince onlara yol gösterdik fakat onlar, körlüğü doğru yolu bulmağa yeğlediler. Böylece yaptıkları yüzünden alçaltıcı azâb yıldırımı onları yakaladı."},{"n":18,"t":"İnananları ve korunanları kurtardık."},{"n":19,"t":"Allâh’ın düşmanları ateşe sürüldükleri gün toplanıp bir araya getirilirler."},{"n":20,"t":"Nihâyet oraya vardıklarında kulakları, gözleri ve derileri, yaptıkları işler hakkında aleyhlerine şâhidlik ettiler."},{"n":21,"t":"Derilerine: \"Niçin aleyhimize şâhidlik ettiniz?\" dediler. (Derileri): \"Her şeyi konuşturan Allâh bizi konuşturdu. İlk defa sizi O yaratmıştı, işte O’na döndürülüyorsunuz.\" dediler."},{"n":22,"t":"\"Siz (günâh işlerken) kulaklarınızın, gözlerinizin ve derilerinizin, aleyhinize şâhidlik etmesinden gizlenmiyordunuz, yaptıklarınızın çoğunu Allâh’ın bilmeyeceğini sanıyordunuz.\""},{"n":23,"t":"\"İşte Rabbinize karşı beslediğiniz bu zannınız, sizi helâk etti, ziyana uğrayanlardan oldunuz!\""},{"n":24,"t":"Şimdi eğer dayanabilirlerse, ateştir onların yeri. Ve eğer özür dileyip Rablerini râzı etmek isterlerse özürleri kabul edilmeyecektir (çünkü özür dileme vakti geçmiştir artık)."},{"n":25,"t":"Biz onlara birtakım (kötü) arkadaşlar sardırdık. Onların önlerinde ve arkalarında bulunan herşeyi onlara süslü gösterdiler (yaptıkları işlerin güzel olduğunu söylediler). Kendilerinden önce gelip geçmiş olan cin ve insan topluluklarına (uygulanan) söz, kendilerine de gerekli oldu (bunlar da azâbı hak ettiler), çünkü hep ziyanda idiler."},{"n":26,"t":"İnkâr edenler dediler ki: \"Bu Kur’ân’ı dinlemeyin, o (okunduğu)nda gürültü edin, (böylece onun anlaşılmasına engel olun), belki ona gâlib gelirsiniz (başka türlü onunla başa çıkmanıza imkân yoktur).\""},{"n":27,"t":"İnkâr edenlere şiddetli bir azâb taddıracağız ve onları, yaptıklarının en kötüsüyle cezâlandıracağız."},{"n":28,"t":"O Allâh düşmanlarının cezâsı: Ateştir. Âyetlerimizi inkâr etmelerinin cezâsı olarak onlara, orada sürekli kalma yurdu vardır."},{"n":29,"t":"(Ateşe giren) Kâfirler dediler ki: \"Rabbimiz, bizi saptıran cin ve insanları bize göster, onları ayaklarımızın altına alalım da alçaklardan olsunlar!\""},{"n":30,"t":"\"Rabbimiz Allah’tır\" deyip, sonra doğru olanların üzerine melekler iner: \"Korkmayın, üzülmeyin, size söz verilen cennetle sevinin! (derler).\""},{"n":31,"t":"\"Biz dünyâ hayâtında da, âhirette de sizin dostlarınızız. Orada size canlarınızın çektiği her şey var. Orada size istediğiniz her şey var.\""},{"n":32,"t":"(Bütün bunlar) Çok bağışlayan, çok esirgeyen (Allâh)ın ağırlaması olarak (size lutfedilir)."},{"n":33,"t":"(İnsanları) Allah’a çağıran, iyi iş yapan ve \"Ben müslümanlardanım\" diyenden daha güzel sözlü kim olabilir?"},{"n":34,"t":"İyilikle kötülük bir olmaz. (Sen kötülüğü) En güzel olan şeyle sav. O zaman bir de bakarsın ki, seninle arasında düşmanlık bulunan kimse, sanki sıcak bir dosttur."},{"n":35,"t":"Bu (kötülüğü iyilikle savma olgunluğu)na ancak sabredenler kavuşturulur. Buna ancak büyük şansı olan kavuşturulur."},{"n":36,"t":"Eğer şeytândan kötü bir düşünce, seni dürtecek olursa hemen Allâh’a sığın. Çünkü O, işitendir, bilendir."},{"n":37,"t":"Gece, gündüz, güneş ve ay O’nun âyetlerindendir. Eğer Allah’a tapıyorsanız, güneşe ve aya secde etmeyin; onları yaratan Allah’a secde edin."},{"n":38,"t":"Eğer büyüklük taslarlarsa (bilsinler ki) Rabbinin yanında bulunan (melek)ler, gece gündüz O’nu tesbih ederler ve onlar hiç usanmazlar."},{"n":39,"t":"O’nun âyetlerinden biri de (şudur): Sen, toprağı, boynu bükük görürsün. Onun üzerine suyu döktüğümüz zaman titreşir ve kabarır. Onu dirilten, elbette ölüleri de diriltir. O, her şeye kâdirdir."},{"n":40,"t":"Âyetlerimiz hususunda doğruluktan sapanlar bize gizli kalmazlar. Şimdi, ateşin içine atılan mı daha iyidir, yoksa kıyâmet günü güvenle gelen mi? Dilediğinizi yapın, O, yaptıklarınızı görmektedir."},{"n":41,"t":"Onlar, kendilerine gelen Kur’ân’ı inkâr ettiler. Halbuki o, öyle eşsiz bir Kitaptır,"},{"n":42,"t":"Ki ne önünden, ne de arkasından onu boşa çıkaracak bir söz gelmez. (O) Hüküm ve hikmet sâhibi, çok övülen (Allâh)dan indirilmiştir."},{"n":43,"t":"Sana söylenen, senden önceki elçilere söylenmiş olandan başka bir şey değildir. Kuşkusuz Rabbin, hem bağışlama sâhibi, hem de acı azâb sâhibidir."},{"n":44,"t":"Eğer biz onu, yabancı (dilde) bir Kur’ân yapsaydık derlerdi ki: \"Âyetleri (anlayacağımız) bir dille açıklanmalı değil miydi? Araba yabancı söz mü (geliyor)?\" De ki: \"O, inananlar için bir yol gösterici ve (gönüllere) şifâdır. İnanmayanlara gelince, onların kulaklarında bir ağırlık vardır ve o, onlara bir körlüktür. (Sanki) Onlar, uzak bir yerden çağırılıyorlar (da duymuyorlar)."},{"n":45,"t":"Andolsun biz Mûsâ’ya Kitabı vermiştik, onda da ayrılığa düşülmüştü. Eğer Rabbinden bir söz geçmiş olmasaydı, aralarında derhal hüküm verilir (işleri bitirilir)di. Onlar ondan işkilli bir kuşku içindedirler."},{"n":46,"t":"Kim iyi iş yaparsa yararı kendisinedir ve kim kötülük yaparsa zararı kendisinedir. Rabbin kullara zulmedici değildir."},{"n":47,"t":"(Duruşma) Sâ’ati(ni) bilmek, Allah’a havale edilir. O’nun bilgisi olmadan ne meyvalar kabuklarından çıkar, ne bir dişi gebe kalır ve ne de doğurur. (Alah) Onlara: \"Ortaklarım nerede?\" diye ünlediği gün: \"Sana arz ederiz ki bizden hiçbir gören yok.\" demişlerdir."},{"n":48,"t":"Önceden yalvarıp durdukları şeyler, onlardan sapıp gitmiş ve onlar, kendileri için kaçacak bir yer olmadığını anlamışlardır."},{"n":49,"t":"İnsan hayır istemekten usanmaz (dâimâ malının artmasını diler). Ama kendisine bir şer dokundu mu hemen üzülür, ümitsiz olur."},{"n":50,"t":"Eğer kendisine dokunan bir zarardan sonra biz ona bir rahmet taddırırsak: \"Bu benim hakkımdır; kıyâmetin kopacağını sanmıyorum; (kıyâmet kopsa da) Rabbime götürülmüş olsam bile muhakkak O’nun yanında benim için daha güzel şeyler vardır\" der. Biz, o nankörlere, yaptıklarını mutlaka haber vereceğiz ve mutlaka onlara kaba azâbdan taddıracağız."},{"n":51,"t":"İnsana bir ni’met verdik mi yüz çevirir; yan çizer. Ona bir şer dokundu mu yalvarıp durur."},{"n":52,"t":"De ki: \"Gördünüz mü, ya o (Kur’an) Allâh tarafından ise ve siz de onu inkâr etmişseniz, o zaman uzak bir ayrılığa düşenden daha sapık kim olabilir?\""},{"n":53,"t":"Biz onlara, ufuklarda ve kendi canlarında âyetlerimizi göstereceğiz ki o(Kur’â)n’ın gerçek olduğu, onlara iyice belli olsun. Rabbinin her şeye tanık olması yetmez mi?"},{"n":54,"t":"İyi bil ki onlar, Rablerine kavuşmaktan kuşku içindedirler. İyi bil ki O, her şeyi kuşatmıştır (her şey Allâh’ın bilgisi içindedir)."}],[{"n":1,"t":"Hâ mim"},{"n":2,"t":"’Ayın sin kâf."},{"n":3,"t":"O aziz ve hakim olan Allâh, sana ve senden öncekilere böyle vahyeder:"},{"n":4,"t":"Göklerde ve yerde bulunan herşey O’nundur. O, yücedir, uludur."},{"n":5,"t":"Neredeyse gökler üstlerinden çatlayacaklar. Melekler Rablerini hamd ile tesbih ederler; yerdekiler için de mağfiret dilerler. İyi bil ki Allâh, işte çok bağışlayan, çok esirgeyen O’dur."},{"n":6,"t":"O’ndan başka veliler edinenleri Allâh kollamaktadır. Sen onların üzerinde vekil değilsin."},{"n":7,"t":"Biz sana böyle Arapça bir Kur’ân vahyettik ki Anakent (Mekke’y)i ve çevresinde bulunanları ikaz edip; (vukuunda) asla kuşku bulunmayan toplanma gününe karşı uyarasın. (O gün), bir bölük cennette, bir bölük ateştedir."},{"n":8,"t":"Allâh dileseydi, onları bir tek millet yapardı. Fakat O, dilediğini rahmetine sokar. Zâlimlere gelince: Onların ne velisi ne de yardımcısı vardır."},{"n":9,"t":"Yoksa Allah’tan başka veliler mi edindiler? Veli yalnız Allah’tır. Ölüleri O diriltir. O her şeye kâdirdir."},{"n":10,"t":"Ayrılığa düştüğünüz herhangi bir şeyde hüküm vermek, Allah’a âittir. İşte Rabbim Allâh budur. O’na dayandım, O’na yöneldim."},{"n":11,"t":"(O) Gökleri ve yeri yoktan var edendir. Size kendinizden çiftler, hayvanlardan da çiftler yaratmıştır. Bu (düzen içi)nde sizi üretiyor. O’na benzer hiçbir şey yoktur. O işitendir, görendir."},{"n":12,"t":"Göklerin ve yerin anahtarları O’nundur. Dilediğine rızkı açar ve kısar. O, her şeyi bilendir."},{"n":13,"t":"O size, dinden Nûh’a tavsiye ettiğini, sana vahyettiğimizi, İbrâhim’e, Mûsâ’ya ve Îsâ’ya tavsiye ettiğimizi şeri’at (hukuk düzeni) yaptı. Şöyle ki: Dini doğru tutun ve onda ayrılığa düşmeyin. Fakat kendilerini çağırdığın (bu) esas, Allah’a ortak koşanlara ağır geldi. Allâh dilediğini kendisine seçer ve iyi niyyetle yöneleni kendisine iletir."},{"n":14,"t":"Onlar, kendilerine ilim geldikten sonra sadece aralarındaki çekememezlik yüzünden ayrılığa düştüler. Eğer Rabbinden belli bir süreye kadar yaşatma sözü geçmiş olmasaydı, aralarında hüküm verilir (işleri bitirilir)di. Onlardan sonra Kitaba vâris kılınanlar ondan, kuşku veren bir şüphe içindedirler."},{"n":15,"t":"Bundan dolayı sen (Hakka) çağır ve emrolunduğun gibi doğru ol; onların keyiflerine uyma ve de ki: \"Ben Allâh’ın indirdiği her Kitaba inandım ve aranızda adâlet yapmakla emrolundum. Allâh bizim de Rabbimiz, sizin de Rabbinizdir. Bizim eylemlerimiz bize, sizin eylemleriniz size âittir. Bizimle sizin aranızda bir tartışma nedeni yoktur. Allâh aramızı bulur, (yahut: Allâh bizi bir araya toplar), dönüş O’nadır."},{"n":16,"t":"(Kamu tarafından) Kabul edildikten sonra, hâlâ Allâh(ın dini hakkın)da tartışanların delilleri, Rableri yanında bâtıldır. Üzerlerine bir gazab ve onlara şiddetli bir azâb vardır."},{"n":17,"t":"Allâh’tır ki gerçeği içeren Kitabı ve (adâlet) ölçü(sün)ü indirdi. Ne bilirsin, belki o sâ’at yakındır?"},{"n":18,"t":"Ona inanmayanlar, onun çabuk gelmesini isterler. İnananlar ise ondan korkarlar ve onun gerçek olduğunu bilirler. İyi bil ki, o sâ’at hakkında tartışanlar, uzak bir sapıklık içine düşmüşlerdir."},{"n":19,"t":"Allâh kullarına lutufkârdır, dilediğini rızıklandırır. O kuvvetlidir, gâliptir."},{"n":20,"t":"Kim âhiret ekinini istiyorsa onun ekinini artırırız; kim dünyâ ekinini istiyorsa ona da dünyâdan bir şey veririz. Fakat onun âhirette bir nasibi olmaz."},{"n":21,"t":"Yoksa onların, kendilerine, Allâh’ın izin vermediği dini koyan ortaklar mı var? Eğer (bir süre fırsat verilmesi hakkında) karar olmasaydı derhal aralarında hüküm verilir (işleri bitirilir)di. Kuşkusuz zâlimler için acı bir azâb vardır."},{"n":22,"t":"Yaptıkları işler başlarına inerken zâlimlerin, korkudan titrediklerini görürsün. Fakat inanıp iyi işler yapanlar cennet bahçelerindedirler. Rablerinin yanında onlara diledikleri her şey vardır. İşte büyük lutuf budur."},{"n":23,"t":"Allâh’ın, inanan ve iyi işler yapan kullarını müjdelediği (büyük lutuf). De ki: \"Ben buna karşılık sizden bir ücret istemiyorum. Ancak (Allah’a) yaklaşmayı arzu ediyorum.\" Kim bir iyilik yaparsa onun iyiliğini artırırız. Şüphesiz Allâh bağışlayan, (iyiliğe) karşılık verendir."},{"n":24,"t":"Yoksa: \"Allah’a yalan uydurdu\" mu diyorlar? Öyle bir durumda Allâh, dilese senin kalbine mühür basar; bâtılı mahveder, hakkı sözleriyle yerleştirir. Şüphesiz O, göğüslerin özünü bilir."},{"n":25,"t":"O’dur ki kullarından tevbeyi kabul eder, kötülüklerden geçer ve yaptıklarınızı bilir."},{"n":26,"t":"İnanan ve iyi işler yapanların dileklerini kabul eder; lutuf ve kereminden onlara, daha fazlasını da verir. Kâfirlere gelince, onlara da çetin bir azâb vardır."},{"n":27,"t":"Allâh kullarına rızkı bollaştırsaydı, yeryüzünde azarlardı. Fakat (O rızkı) dilediği ölçüde indiriyor. Çünkü O, kullarını(n her halini) haber alandır, görendir."},{"n":28,"t":"O’dur ki (kulları) umutlarını kestikten sonra yağmuru indirir, rahmetini yayar. O velidir, övülmüştür."},{"n":29,"t":"Gökleri, yeri ve bunların içine yaydığı canlıları yaratması da O’nun âyetlerinden (birliğinin ve kudretinin işâretlerinden)dir. O, dilediği zaman onları toplamağa da kâdirdir."},{"n":30,"t":"Başınıza gelen herhangi bir musibet kendi ellerinizin yaptığı (işler) yüzündendir. (Allâh, hatâlarınızın) Birçoğunu da affeder."},{"n":31,"t":"Siz, yeryüzünde O(nun cezâsı)na engel olamazsınız. Sizin Allah’tan başka ne bir veliniz, ne de bir yardımcınız vardır."},{"n":32,"t":"Denizde dağlar gibi akıp giden (gemi)ler O’nun âyetlerindendir."},{"n":33,"t":"Dilerse rüzgârı durdurur, (gemiler denizin) sırtında durakalır. Kuşkusuz bunda sabreden, şükreden herkes için ibretler vardır."},{"n":34,"t":"Yahut yaptıkları (işler) yüzünden gemileri(n içindekileri) helâk eder. Birçoğunu da affeder (kurtarır)."},{"n":35,"t":"Ki âyetlerimiz hakkında tartışanlar, kendileri için kaçacak bir yer olmadığını bilsinler."},{"n":36,"t":"Size verilen şeyler, dünyâ hayâtının geçimidir. İnanıp Rablerine dayananlar için Allâh’ın yanında bulunan ödül ise daha hayırlı ve daha kalıcıdır."},{"n":37,"t":"Onlar büyük günâhlardan ve çirkin işlerden kaçınırlar; kızdıkları zaman da onlar, affederler."},{"n":38,"t":"Rablerinin çağrısına gelirler, namazı kılarlar. İşleri, aralarında danışma iledir. Kendilerine verdiğimiz rızıktan hayır için harcarlar."},{"n":39,"t":"Bir zulüm ve saldırıya uğradıkları zaman kendilerini savunurlar."},{"n":40,"t":"Kötülüğün cezâsı, yine onun gibi bir kötülüktür. Kim affeder, barışırsa onun mükâfâtı Allah’a âittir. Doğrusu O, zâlimleri sevmez."},{"n":41,"t":"Kim zulme uğradıktan sonra kendini savunursa öylelerinin aleyhine bir yol yoktur (onlar kınanmaz ve cezâlandırılmazlar)."},{"n":42,"t":"Ancak şunlar aleyhine yol vardır ki, insanlara zulmederler ve yeryüzünde haksız yere saldırırlar. İşte böylelerine acı bir azâb vardır."},{"n":43,"t":"Fakat kim sabreder, affederse, şüphesiz bu, çok önemli işlerdendir!"},{"n":44,"t":"Allâh kimi sapıklıkta bırakırsa artık onun, Allah’tan sonra bir velisi yoktur. Zâlimlerin, azâbı gördükleri zaman: \"Geri dönecek bir yol var mı?\" dediklerini görürsün."},{"n":45,"t":"Yine onları görürsün: Aşağılıktan başlarını öne eğmiş vaziyette ateşe sunulurlarken göz ucuyla gizli gizli bakarlar. İnananlar da: \"İşte asıl ziyana uğrayanlar, kıyâmet günü hem kendilerini, hem âilelerini ziyan edenlerdir. Bakın, gerçekten zâlimler sürekli bir azâb içindedirler\" demişlerdir."},{"n":46,"t":"Onların, Allah’tan başka kendilerine yardım edecek velileri yoktur. Allâh kimi sapıklıkta bırakırsa artık onun için bir (kurtuluş) yol(u) yoktur."},{"n":47,"t":"Allah’tan, geri çevrilmesi mümkün olmayan bir gün gelmezden önce, Rabbiniz(in çağrısı)na uyun. Çünkü o gün ne sığınacak bir yeriniz var; ne de (yaptıklarınızı) inkâra çâre."},{"n":48,"t":"Eğer yüz çevirirlerse (üzülme); biz seni onların üzerine bekçi göndermedik. Sana düşen, yalnız duyurmaktır. Biz insana, bizden bir rahmet taddırdığımız zaman ona sevinir. Ama ellerinin (yapıp) öne sürdüğü işlerden dolayı başlarına bir kötülük gelirse, insan hemen nankör olur."},{"n":49,"t":"Göklerin ve yerin mülkü Allâh’ındır. (O) Dilediğini yaratır. Dilediğine dişiler bahşeder, dilediğine de erkekler bahşeder."},{"n":50,"t":"Yahut onları çift yapar: Hem dişi, hem erkek (verir). Dilediğini de kısır yapar. O (herşeyi) bilendir, (herşeye) gücü yetendir."},{"n":51,"t":"Allâh bir insanla (karşılıklı) konuşmaz. Ancak vahiyle (kulunun kalbine dilediği düşünceyi doğurarak), yahut perde arkasından konuşur; yahut izniyle dilediğini vahyedecek bir elçi gönderir. O, yücedir, hüküm ve hikmet sâhibidir."},{"n":52,"t":"İşte sana da böyle emrimizden bir ruh (gönüllere can veren bir söz) vahyettik. Sen Kitap nedir, iman nedir bilmezdin. Fakat biz onu, kullarımızdan dilediğimizi, doğru yola ilettiğimiz bir nur yaptık. Şüphesiz sen, doğru yola götürüyorsun:"},{"n":53,"t":"Göklerde ve yerde bulunan herşeyin sâhibi Allâh’ın yoluna. İyi bilin ki bütün işler sonunda Allah’a varır."}],[{"n":1,"t":"Hâ mim."},{"n":2,"t":"Apaçık Kitaba andolsun ki"},{"n":3,"t":"Biz, düşünüp anlamanız için onu Arapça bir Kur’ân yaptık."},{"n":4,"t":"O, katımızda bulunan ana Kitaptadır. Yücedir, hikmetlidir."},{"n":5,"t":"Siz, aşırı giden bir kavim oldunuz diye, sizi uyarmaktan vaz mı geçelim?"},{"n":6,"t":"Biz önce gelenlere nice peygamber gönderdik."},{"n":7,"t":"Onlara hiçbir peygamber gelmezdi ki mutlaka onunla alay etmesinler."},{"n":8,"t":"Biz de bunlardan daha güçlü olan (o kavimler)i helâk ettik. Öncekilerin örneği geçti."},{"n":9,"t":"Andolsun onlara: \"Gökleri ve yeri kim yarattı?\" diye sorsan elbette diyecekler ki: \"Onları, çok üstün, çok bilen (Allâh) yarattı.\""},{"n":10,"t":"O yeri sizin için beşik kıldı ve varacağınız yere gitmeniz için yeryüzünde size yollar yaptı."},{"n":11,"t":"Gökten bir ölçü ile su indirdi de, onunla ölü bir ülkeyi canlandırdık. İşte siz de öyle (canlandırılıp) çıkarılacaksınız."},{"n":12,"t":"O bütün çiftleri yarattı ve size bineceğiniz gemiler ve hayvanlar var etti,"},{"n":13,"t":"Ki onların sırtlarına binesiniz, sonra onlara bindiğiniz zaman Rabbinizin ni’metini anasınız ve (şöyle) diyesiniz: \"Bunu bizim hizmetimize veren (Allâh)ın şânı yücedir, yoksa biz bunu (hizmetimize) yanaştıramazdık.\""},{"n":14,"t":"\"Biz elbette Rabbimize döneceğiz.\""},{"n":15,"t":"Tuttular, O’na kullarından bir parça tasarladılar. Gerçekten insan apaçık bir nankördür."},{"n":16,"t":"Yoksa (Allâh), yarattıklarından kızları kendisine aldı da oğullar için sizi mi yeğledi?"},{"n":17,"t":"Onlardan birine Rahmân’a benzer olarak anlattığı (kız çocuğu) müjdelense yüzü kapkara kesilir, öfkesinden yutkunup durur."},{"n":18,"t":"Süs içinde yetiştirilip, mücâdelede açık olmayanı (tartışmayı ve kavgayı beceremeyeni) mi (Allâh’ın çocuğu yaptılar)?"},{"n":19,"t":"Rahmân’ın kulları olan melekleri dişi saydılar. Onların yaratılışlarına mı şâhid oldular ki (böyle hüküm veriyorlar)? Şâhidlikleri yazılacak ve (bundan) sorulacaklardır."},{"n":20,"t":"Ve dediler ki: \"Rahmân dileseydi, biz onlara tapmazdık.\" Onların bu hususta bir bilgileri yoktur. Onlar sadece saçmalıyorlar."},{"n":21,"t":"Yoksa bundan önce onlara bir Kitap vermişiz de ona mı sarılıyorlar?"},{"n":22,"t":"Hayır, (ne bilgileri var, ne de Kitâpları). Sadece: \"Biz babalarımızı bir din üzerinde bulduk, biz de onların izlerinde gidiyoruz\" dediler."},{"n":23,"t":"İşte böyle, senden önce de hangi kente uyarıcı gönderdiysek mutlaka oranın varlıklıları: \"Biz babalarımızı bir din üzerinde bulduk, biz de onların izlerine uyarız.\" dediler."},{"n":24,"t":"\"Ben size, babalarınızı, üzerinde bulduğunuz(din)den daha doğrusunu getirmiş olsam da (yine babalarınızın yolunu)mu (tutacaksınız)?\" dedi. \"Doğrusu biz sizinle gönderilen mesajı tanımıyoruz.\" dediler."},{"n":25,"t":"Biz de onlardan öç aldık. Bak, yalanlayanların sonu nasıl oldu?"},{"n":26,"t":"Bir zaman İbrâhim babasına ve kavmine demişti ki: \"Ben sizin taptıklarınızdan uzağım.\""},{"n":27,"t":"\"Ben yalnız beni yaratana (taparım). Çünkü O, bana doğru yolu gösterecektir.\""},{"n":28,"t":"Ve bu sözü ardında kalıcı bir söz yaptı ki (insanlar Allah’a kulluğa) dönsünler."},{"n":29,"t":"Doğrusu bunları da, babalarını da kendilerine gerçek söz ve (onu) açıklayan elçi gelinceye dek yaşattım."},{"n":30,"t":"Fakat kendilerine gerçek gelince: \"Bu, büyüdür, biz onu tanımayız\" dediler."},{"n":31,"t":"Ve dediler ki: \"Bu Kur’ân iki kentten, büyük bir adama indirilmeli değil miydi?\""},{"n":32,"t":"Rabbinin rahmetini onlar mı bölüştürüyorlar? Dünyâ hayâtında onların geçimliklerini aralarında biz taksim ettik ve onlardan kimini ötekine derecelerle üstün kıldık ki biri, diğerine iş gördürebilsin. Rabbinin rahmeti, onların toplayıp yığdıklarından daha hayırlıdır."},{"n":33,"t":"İnsanlar (küfürde birleşen) bir tek ümmet olacak olmasaydı. Rahmân’ı inkâr edenlerin evlerine gümüşten tavanlar ve üzerine binip çıkacakları merdivenler yapardık."},{"n":34,"t":"Ve evlerine kapılar ve üzerine yaslanacakları koltuklar, divânlar."},{"n":35,"t":"Ve (nice) süs(ler verirdik). Bütün bunlar, sâdece dünyâ hayâtının geçiminden ibarettir. Rabbinin katında âhiret ise, (günâhlardan) korunanlar içindir."},{"n":36,"t":"Kim Rahmân’ın zikrine karşı kör olursa ona bir şeytânı sardırırız; artık o, onun (yanından ayrılmaz, ona sürekli olarak kötülükleri telkin eden) arkadaşı olur."},{"n":37,"t":"O (şeyta)nlar onları yoldan çıkardıkları halde bunlar doğru yolda olduklarını sanırlar."},{"n":38,"t":"Nihâyet (Zikr’imize karşı körlük edip yoldan çıkan o adam) bize geldiği zaman (kötü arkadaşına) der ki: \"Keşke benimle senin aranda iki doğu (doğu ile batı) arası kadar uzaklık olsaydı (seni hiç görmeseydim); meğer ne kötü arkadaş(mışsın sen)!\""},{"n":39,"t":"(Böyle söylemeniz) Bugün size bir yarar sağlamaz; çünkü zulmettiniz. Siz, azâb (çekme)de ortaksınız."},{"n":40,"t":"(Ey Muhammed), sen mi sağıra işittireceksin, yâhut körü ve apaçık sapıklıkta olanı yola ileteceksin?"},{"n":41,"t":"Ya biz seni alıp götürdükten sonra onlardan öc alırız."},{"n":42,"t":"Yahut onları uyardığımız şeyi sana gösteririz (senin gözlerinin önünde onları azâba uğratırız); bizim onlara gücümüz yeter."},{"n":43,"t":"Sen, sana vahyedilene sımsıkı sarıl, çünkü sen doğru yoldasın."},{"n":44,"t":"O (Kur’ân) sana ve kavmine bir Zikir (uyarı, şan ve şeref)dir ve yakında (ona uyup uymadığınızdan) sorulacaksınız."},{"n":45,"t":"Senden önce gönderdiğimiz elçilerimizden sor: Rahmân’dan başka tapılacak tanrılar yapmış mıyız?"},{"n":46,"t":"Andolsun biz Mûsâ’yı da âyetlerimizle Fir’avn’a ve ileri gelen adamlarına gönderdik: \"Ben âlemlerin Rabbinin elçisiyim\" dedi."},{"n":47,"t":"Onlara âyetlerimizi getirince onlar o âyetlerle alay edip gülmeğe başladılar."},{"n":48,"t":"Onlara gösterdiğimiz her mu’cize, mutlaka kızkardeşinden (ötekinden) büyüktü. Belki dönerler diye onları (kıtlık, tûfân, çekirge gibi türlü) azâb(lar) ile cezâlandırdık."},{"n":49,"t":"Bunun üzerine dediler ki: \"Ey büyücü, bizim için Rabbine du’â et, sana verdiği söz hakkı için (bizi bağışlasın) artık biz yola geleceğiz!\""},{"n":50,"t":"Fakat biz onlardan azâbı kaldırınca sözlerinden dönmeğe başladılar."},{"n":51,"t":"Fir’avn kavminin içinde bağırıp dedi: \"Ey kavmim, Mısır mülkü ve şu altımdan akıp giden ırmaklar benim değil mi? Görmüyor musunuz?\""},{"n":52,"t":"\"Yahut ben, şu aşağılık, nerdeyse söz anlatamayacak durumda olan adamdan daha iyi değil miyim?\""},{"n":53,"t":"(Eğer o, doğru söylüyorsa) Üzerine altın bilezikler atılmalı, yâhut yanında (kendisine yardım eden, onu doğrulayan) melekler de gelmeli değil miydi?\""},{"n":54,"t":"Kavmini küçümsedi, onlar da ona boyun eğdiler. Çünkü onlar yoldan çıkmış bir kavim idiler."},{"n":55,"t":"Onlar bizi kızdırınca biz de onlardan öç aldık, hepsini boğduk."},{"n":56,"t":"Onları sonradan gelen (inkârcı)ların geçmiş ataları ve örneği yaptık (bunlar da onların izinden gittiler)."},{"n":57,"t":"Meryem oğlu, bir misâl olarak anlatılınca hemen kavmin, ondan ötürü yaygarayı bastılar:"},{"n":58,"t":"\"Bizim tanrılarımız mı hayırlı, yoksa o mu? dediler. Bunu sâdece tartışma için sana misâl verdiler. Doğrusu onlar, kavgacı bir toplumdur."},{"n":59,"t":"O, sadece kendisine ni’met verdiğimiz ve İsrâil oğullarına örnek kıldığımız bir kuldur."},{"n":60,"t":"Eğer dileseydik, sizden şu dünyâda yerinize geçen melekler yapardık."},{"n":61,"t":"O, kıyâmetin kopacağını gösterir bir ilimdir. O sâ’atin geleceğinden hiç şüphe etmeyin, bana uyun, doğru yol budur."},{"n":62,"t":"Şeytân sizi (bundan) alıkoymasın. Çünkü o, sizin için açık bir düşmandır."},{"n":63,"t":"Îsâ açık kanıtlar getirince dedi ki: \"Ben size hikmet getirdim ve ayrılığa düştüğünüz şeylerden bir kısmını size açıklamak için (geldim), Allah’tan korkun ve bana itâ’at edin.\""},{"n":64,"t":"\"Allâh, işte benim de Rabbim, sizin de Rabbiniz O’dur. O’na tapın, doğru yol budur.\""},{"n":65,"t":"Aralarından çıkan partiler, birbirleriyle ihtilâfa düşmüşlerdir. Acı bir günün azâbından vay o zulmedenlerin haline!"},{"n":66,"t":"Onlar ille o sâ’atin, kendilerinin hiç farkında olmadıkları bir sırada, ansızın başlarına gelmesini mi bekliyorlar?"},{"n":67,"t":"O gün, korunanlar dışında, dostlar birbirine düşmandır. (Onlara âlemlerin Rabbi şöyle hitabeder):"},{"n":68,"t":"\"Ey kullarım, bugün size korku yoktur ve siz üzülmeyeceksiniz.\""},{"n":69,"t":"Onlar, âyetlerimize inanmış ve müslüman olmuş (kullarım) idiler."},{"n":70,"t":"\"Haydi, siz cennete girin. Siz ve eşleriniz ağırlanıp sevindirileceksiniz!\""},{"n":71,"t":"Onların önünde altın tepsiler ve kadehler dolaştırılır. Orada canların çektiği, gözlerin hoşlandığı her şey var! Ve siz orada ebedi kalacaksınız."},{"n":72,"t":"\"İşte yaptıklarınıza karşılık size mirâs verilen cennet budur.\""},{"n":73,"t":"Orada sizin için çok meyva var. Onlardan yersiniz."},{"n":74,"t":"Suçlular, cehennem azâbında sürekli kalacaklardır."},{"n":75,"t":"(Azâb) Kendilerinden hiç hafifletilmeyecektir. Onlar azâb içinde umutsuzdurlar!"},{"n":76,"t":"Biz onlara zulmetmedik; fakat onlar kendileri zâlim idiler."},{"n":77,"t":"(Cehennemin muhafızına): \"Ey Mâlik, Rabbin bizim işimizi bitirsin, (bizi yok etsin, böyle yaşamaktansa ölmek daha iyidir)!\" diye seslendiler. (Mâlik) \"Siz kalacaksınız (hiçbir sûretle buradan kurtuluş yok).\" dedi."},{"n":78,"t":"Andolsun biz size hakkı getirdik; fakat sizin çoğunuz haktan hoşlanmıyorsunuz."},{"n":79,"t":"Yoksa (hakka engel olma hususunda) bir iş mi kararlaştırdılar? Biz de (onları cezâlandırmağa ve hakkı yerleştirmeğe) kararlıyız."},{"n":80,"t":"Yoksa biz, onların sırlarını ve gizli konuşmalarını işitmez miyiz sanıyorlar? Hayır, işitiriz ve yanlarında bulunan elçilerimiz de (her yaptıklarını) yazarlar."},{"n":81,"t":"De ki: \"Eğer Rahmân’ın çocuğu olsaydı (O’na) tapanların ilki ben olurdum.\""},{"n":82,"t":"Göklerin ve yerin Rabbi, Arş’ın Rabbi onların nitelendirmelerinden yücedir, münezzehtir."},{"n":83,"t":"Bırak onları, kendilerine söylenen günlerine kavuşuncaya kadar dalsın, oynasınlar."},{"n":84,"t":"O’dur ki gökte de Tanrı’dır, yerde de Tanrı’dır. O, hakimdir, bilendir."},{"n":85,"t":"Göklerin, yerin ve ikisi arasında bulunan her şeyin mülkü kendisine âidolan (Allâh) ne yücedir! (Kıyâmetin kopacağı) Sâ’ati bilmek de O’nun yanındadır ve siz O’na döndürülüp götürüleceksiniz."},{"n":86,"t":"O’ndan başka (tanrı diye) yalvardıkları şeyler şefâ’at (yetkisin)e sâhip değillerdir. Ancak bilerek hakka şâhidlik edenler (bildiklerini doğru anlatanlar) bunun dışındadır."},{"n":87,"t":"Andolsun onlara, \"Kendilerini kim yarattı?\" diye sorsan, elbette: \"Allâh,\" derler. O halde nasıl (haktan) çevriliyorlar?"},{"n":88,"t":"Ve Elçinin: \"Ya Rab, bunlar inanmayan bir kavimdir,\" demesini de (Allâh biliyor)."},{"n":89,"t":"Şimdi sen onlardan geç ve: \"Size esenlik (dilerim)\" de. Yakında bileceklerdir."}],[{"n":1,"t":"Hâ mim."},{"n":2,"t":"Apaçık Kitaba andolsun ki,"},{"n":3,"t":"Biz onu mübârek bir gecede indirdik. Çünkü biz, uyarıcıyız."},{"n":4,"t":"Her hikmetli emir, o gecede ayırdedilir;"},{"n":5,"t":"Katımızdan (verilen her) emir. Çünkü biz elçi göndericiyiz."},{"n":6,"t":"Senin Rabbinin acıması gereği olarak (gönderdiğimiz elçilere o gece emirlerimizi açıklar, vahiylerimizi bildiririz). Doğrusu O, işitendir, bilendir."},{"n":7,"t":"Eğer kesin olarak inanıyorsanız (bilin ki Allâh), göklerin, yerin ve ikisi arasında bulunanların Rabbidir."},{"n":8,"t":"O’ndan başka tanrı yoktur, yaşatır, öldürür. Sizin de Rabbiniz, önceki atalarınızın da Rabbidir."},{"n":9,"t":"Ama onlar, şüphe içinde oynuyorlar."},{"n":10,"t":"Göğün, açık bir duman getireceği günü gözetle."},{"n":11,"t":"(Duman) İnsanları sarar. Bu, acı bir azâbdır."},{"n":12,"t":"\"Rabbimiz, bizden azâbı kaldır, çünkü biz artık inanıyoruz\" derler."},{"n":13,"t":"Artık onlar nasıl düşünüp öğüt alacaklar (öğüt alma zamanı geçti)? Oysa kendilerine apaçık bir elçi gelmişti."},{"n":14,"t":"Ondan yüz çevirdiler: \"Bu, öğretilmiştir, cinlenmiştir\" dediler."},{"n":15,"t":"Biz sizden azâbı birazcık kaldırırız ama siz yine (inkârınıza) dönersiniz."},{"n":16,"t":"O gün büyük vuruşla vururuz; zira biz öç alıcıyız!"},{"n":17,"t":"Andolsun, onlardan önce Fir’avn toplumunu da (imkânlar vererek) sınadık. Onlara değerli bir elçi geldi, (şöyle diyerek):"},{"n":18,"t":"\"Allâh’ın kullarını bana teslim edin; çünkü ben sizin için güvenilir bir elçiyim.\""},{"n":19,"t":"\"Allah’a karşı ululanmayın. Ben size apaçık bir delil getiriyorum.\""},{"n":20,"t":"\"Ben, beni taşla(yıp öldür)menizden, benim de Rabbim, sizin de Rabbiniz olan (Allâh)’a sığındım.\""},{"n":21,"t":"\"Eğer bana inanmadınızsa bari ben(im yolum)dan çekilin.\""},{"n":22,"t":"Sonra (Mûsâ): \"Bunlar, suç işleyen bir toplumdur!\" diye Rabbine du’â etti."},{"n":23,"t":"(Allâh): \"O halde kullarımı geceleyin yürüt. Çünkü takibedileceksiniz\" (dedi)."},{"n":24,"t":"\"Denizi (yarıp toplumunu geçirdikten sonra olduğu gibi) açık bırak. Çünkü onlar boğulacak bir ordudur.\""},{"n":25,"t":"Onlar geride nice şeyler bıraktılar: Bahçeler, çeşmeler."},{"n":26,"t":"Ekinler, güzel makamlar!"},{"n":27,"t":"Ve zevkü sefa sürdükleri nice ni’metler!"},{"n":28,"t":"İşte böyle oldu ve biz onları başka bir topluma mirâs verdik."},{"n":29,"t":"Onlara gök ve yer ağlamadı. Ve kendilerine fırsat da verilmedi."},{"n":30,"t":"Andolsun biz, İsrâil oğullarını o küçültücü azâbdan kurtardık:"},{"n":31,"t":"Fir’avn’dan. Çünkü o, (insanları ezip) ululanan, sınırı aşanlardan biri idi."},{"n":32,"t":"Andolsun biz, onları bir bilgiye göre âlemlere üstün kıldık."},{"n":33,"t":"Onlara, içinde açık bir sınav bulunan âyetler verdik."},{"n":34,"t":"Şunlar (Kureyş kâfirleri) de diyorlar ki:"},{"n":35,"t":"\"İlk ölümümüzden sonra bir şey yoktur. Biz diriltilecek değiliz.\""},{"n":36,"t":"\"Doğru söylüyorsanız, babalarımızı getirin.\""},{"n":37,"t":"Onlar mı hayırlı, yoksa Tubba’ kavmi ve onlardan önce gelen (kavim)ler mi? Suç işledikleri için biz onların hepsini helâk ettik."},{"n":38,"t":"Biz gökleri, yeri ve bunlar arasında bulunanları eğlenmek için yaratmadık!"},{"n":39,"t":"Onları sadece gerçek bir sebeple, (hikmetli bir gâye ile) yarattık. Fakat onların çoğu bilmiyorlar."},{"n":40,"t":"(Hakkın bâtıldan ayrılacağı) Hüküm günü, hepsinin varacağı gündür."},{"n":41,"t":"O gün dost, dostundan bir şey savamaz. Ve onlara yardım da edilmez."},{"n":42,"t":"Ancak Allâh’ın acıdığı kimseler (kurtulur). Şüphesiz O, üstündür esirgeyendir."},{"n":43,"t":"Zakkum ağacı,"},{"n":44,"t":"Günâhkârların yemeğidir."},{"n":45,"t":"Pota gibi karınlarda kaynar."},{"n":46,"t":"Sıcak suyun kaynaması gibi."},{"n":47,"t":"(Allâh, zebânilere emreder): \"Tutun onu, cehennemin ortasına sürükleyin.\""},{"n":48,"t":"\"Sonra başının üstüne kaynar su azâbından dökün!\""},{"n":49,"t":"\"Tad, zira sen kendince üstündün, şerefliydin.\""},{"n":50,"t":"İşte o kuşkulanıp durduğunuz şey budur!\""},{"n":51,"t":"Korunanlar ise güvenli bir makamdadır."},{"n":52,"t":"Bahçelerde ve çeşme başlarında."},{"n":53,"t":"İnce ipekten ve parlak atlastan giysiler giyerek karşılıklı otururlar."},{"n":54,"t":"Ayrıca onları, iri gözlü hûrilerle de evlendirmişizdir."},{"n":55,"t":"Orada, güven içinde, her meyveyi isterler."},{"n":56,"t":"Orada ilk ölümden başka ölüm tadmazlar (sürekli yaşarlar). Ve (Allâh) onları cehennem azâbından korumuştur."},{"n":57,"t":"Rabbinden bir lutuf olarak (bu ni’metler kendilerine verilmiştir). İşte, o büyük başarı budur."},{"n":58,"t":"Biz o (Kur’â)n’ı senin diline kolaylaştırdık ki, düşünüp öğüt alsınlar."},{"n":59,"t":"Biraz bekle, onlar da beklemektedirler (yakında başlarına neler geleceğini göreceklerdir)."}],[{"n":1,"t":"Hâ mim."},{"n":2,"t":"Kitabın indirilmesi, o üstün, hüküm ve hikmet sâhibi Allâh tarafındandır."},{"n":3,"t":"Şüphesiz göklerde ve yerde, inananlar için ibretler vardır."},{"n":4,"t":"Sizin yaratılışınızda ve (yeryüzünde) yaymakta olduğu canlılarda, kesin olarak inananlar için ibretler vardır."},{"n":5,"t":"Gecenin ve gündüzün değişmesinde, Allâh’ın gökten rızık (sebebi) indirip onunla ölümünden sonra yeri diriltmesinde, rüzgârları estirmesinde düşünen bir toplum için ibretler vardır."},{"n":6,"t":"İşte şunlar, Allâh’ın âyetleridir, onları sana gerçek ile okuyoruz. Allah’tan ve O’nun âyetlerinden sonra hangi hadise (söze) inanacaklar?"},{"n":7,"t":"Her yalancı, günâh yüklü kimseye yuh olsun!"},{"n":8,"t":"O, Allâh’ın âyetlerinin kendisine okunduğunu işitir de sonra büyüklük taslayarak sanki hiç onları işitmemiş gibi (küfründe) direnir. Onu, acı bir azâb ile müjdele."},{"n":9,"t":"O, bizim âyetlerimizden bir şey öğrendiği zaman onunla alay eder. İşte öyleleri için alçaltıcı bir azâb vardır."},{"n":10,"t":"Ötelerinden de cehennem (onları beklemektedir). Ne kazandıkları ve ne de Allah’tan başka edindikleri veliler kendilerine bir yarar sağlayabilir. Onlar için büyük bir azâb vardır."},{"n":11,"t":"İşte yol gösterici, bu (Kur’ân)dır. Rablerinin âyetlerini tanımayanlar için çok çetin bir azâb vardır!"},{"n":12,"t":"Allah’tır ki denizi size boyun eğdirdi, tâ ki gemiler buyruğuyla denizin içinde akıp gitsin de, siz bu sayede O’nun lutfundan payınızı arayasınız ve şükredesiniz."},{"n":13,"t":"Göklerde ve yerde bulunan şeyleri kendisinden (bir lutuf olarak) size boyun eğdirdi. Elbette bunda, düşünen bir toplum için ibretler vardır."},{"n":14,"t":"İnananlara söyle: Allâh’ın (cezâ) günlerinin geleceğini ummayanları affetsinler ki (Allâh), bir toplumu, yaptıklarıyle cezâlandırsın."},{"n":15,"t":"Kim iyi bir iş yaparsa yararı kendisinedir, kim de kötülük yaparsa zararı kendisinedir. Sonunda Rabbinize döndürüleceksiniz."},{"n":16,"t":"Andolsun biz, İsrâil oğullarına Kitap, hüküm (hikmet, hükümranlık) ve peygamberlik verdik, onları güzel rızıklarla besledik ve onları âlemlere üstün kıldık."},{"n":17,"t":"Ve onlara bu (din) iş(in)de açık deliller verdik. Onlar kendilerine bilgi geldikten sonra sadece aralarındaki çekememezlik yüzünden ayrılığa düştüler. Şüphesiz, Rabbin kıyâmet günü, ayrılığa düştükleri şeylerde onlar arasında hüküm verecektir."},{"n":18,"t":"Sonra seni de buyruk(umuz)dan bir şeriate (bir hukuk düzenine) koyduk. Sen ona uy, bilmeyenlerin keyiflerine uyma."},{"n":19,"t":"Çünkü onlar, Allah’tan (gelecek) hiçbir şeyi senden savamazlar. Zâlimler birbirlerinin velisidirler. Allâh ise korunanların velisidir."},{"n":20,"t":"Bu (Kur’ân), insanlara kanıtlar (sunmakta)dır; kesin olarak inananlara yol gösterici ve rahmettir."},{"n":21,"t":"Yoksa kötülükleri işleyen kimseler, kendilerini, inanıp iyi ameller işleyen kimseler gibi yapacağımızı mı sandılar? Yaşamaları ve ölümleri onlarla bir olacak öyle mi? Ne kötü hüküm veriyorlar!"},{"n":22,"t":"Allâh, gökleri ve yeri gerçek olarak yaratmıştır ki her can, kazandığıyle cezâlandırılsın, kimseye haksızlık edilmez."},{"n":23,"t":"Keyfini tanrı edinen ve Allâh’ın bir bilgiye göre saptırdığı, kulağını ve kalbini mühürlediği, gözünün üstüne de perde çektiği kimseyi gördün mü? Şimdi ona Allah’tan sonra kim doğru yolu gösterecek? Düşünmüyor musunuz?"},{"n":24,"t":"Dediler ki: \"Ne varsa dünyâ hayâtımızdır, başka bir şey yoktur. Ölürüz, yaşarız. Bizi zamandan başkası helâk etmiyor.\" Fakat onların bu hususta hiçbir bilgileri yoktur. Onlar sadece zannediyorlar."},{"n":25,"t":"Onlara açık açık âyetlerimiz okunduğu zaman: \"Doğru iseniz, babalarımızı getirin\" demelerinden başka bir delilleri olmamıştır."},{"n":26,"t":"De ki: \"Allâh sizi yaşatıyor, sonra sizi öldürüyor. Sonra sizi, toplayıp duruşma gününe getirecektir. Bunda asla şüphe yoktur, ama insanların çoğu bilmezler.\""},{"n":27,"t":"Göklerin ve yerin mülkü Allâh’ındır. O sâ’at başladığı gün, işte o gün (Allâh’ın âyetlerini etkisiz bırakmağa çalışan) iptalciler hüsrana uğrayacaktır."},{"n":28,"t":"(O gün) Her ümmeti (Allâh’ın huzûrunda) toplanmış görürsün. Her ümmet, kendi Kitabına (yaptığı işlerin tutanağı olan amel defterine) çağırılır: \"Bugün yaptıklarınızla cezâlandırılacaksınız!\""},{"n":29,"t":"\"İşte Kitabımız, aleyhinize gerçeği söylüyor. Çünkü biz, yaptıklarınızı yazıyorduk.\""},{"n":30,"t":"İnanıp iyi işler yapanlar; Rableri onları rahmetine sokar. İşte apaçık başarı budur."},{"n":31,"t":"Ama inkâr edenlere gelince (onlara da şöyle denir): \"Âyetlerim size okunurdu, fakat siz büyüklük tasladınız ve suçlu bir toplum oldunuz değil mi?\""},{"n":32,"t":"\"Allâh’ın va’di gerçektir, (Duruşma) sâ’at(inin geleceğin)de şüphe yoktur\" dendiği zaman: \"Sâ’at nedir, bilmiyoruz, (onu) sadece (bir kuruntu) sanıyoruz biz ona inanmıyoruz\" demiştiniz ha?!\""},{"n":33,"t":"Yaptıklarının kötülükleri onlara göründü ve alay edip durdukları şey onları kuşattı."},{"n":34,"t":"Ve (kendilerine şöyle) denildi: \"Siz, bu gününüzle karşılaşmayı nasıl unuttunuzsa biz de bugün sizi unuttuk. Yeriniz ateştir. Hiçbir yardımcınız da yoktur!\""},{"n":35,"t":"Böyledir, çünkü siz Allâh’ın âyetlerini eğlence yaptınız; dünyâ hayâtı sizi aldattı. Artık bugün onlar ne ateşten çıkarılırlar ve ne de kendilerinden Allâh’ı memnun etmeğe çalışmaları istenir."},{"n":36,"t":"Hamd, göklerin Rabbi, yerin Rabbi ve bütün âlemlerin Rabbi olan Allah’a mahsustur."},{"n":37,"t":"Göklerde ve yerde ululuk, yalnız O’na aittir. O, azizdir, hakimdir."}],[{"n":1,"t":"Hâ mim."},{"n":2,"t":"Kitabın indirilişi aziz, hakim olan Allâh tarafındandır."},{"n":3,"t":"Biz gökleri, yeri ve ikisi arasında bulunanları (boş yere değil), ancak gerçek ile ve belli bir süreye göre yarattık. İnkâr edenler, uyarıldıkları şeyden yüz çevirmektedirler."},{"n":4,"t":"De ki: \"Allah’tan başka yalvardıklarınızı gördünüz mü? Bana gösterin, onlar yerden neyi yarattılar? Yoksa gökler(in yaratılışın)da onların bir ortaklığı mı var? Eğer doğru iseniz bundan önce (inmiş olan) bir Kitâp, yahut bir bilgi kalıntısı getirin.\""},{"n":5,"t":"Allâh’ı bırakıp da kıyâmet gününe kadar kendisine cevap veremeyecek şeylere yalvarandan daha sapık kim olabilir? Oysa onlar, bunların yalvardıklarından habersizdirler."},{"n":6,"t":"İnsanlar (Yüce Divâna) toplandıkları gün, (taptıkları tanrılar) onlara düşman olurlar ve onların, kendilerine tapmalarını tanımazlar."},{"n":7,"t":"Onlara açık açık âyetlerimiz okunduğu zaman kendilerine gelen hakkı inkâr edenler: \"Bu, apaçık bir büyüdür\" dediler."},{"n":8,"t":"Yoksa \"Onu uydurdu\" mu diyorlar? De ki: \"Eğer ben onu uydurmuşsam, Allah’tan gelecek cezâya karşı sizin bana hiçbir yararınız olmaz. O, sizin yaptığınız taşkınlığı daha iyi bilir. Benimle sizin aranızda O’nun şâhid olması yeter. O, bağışlayan, esirgeyendir."},{"n":9,"t":"De ki: \"Ben türedi bir elçi değilim. Bana ve size ne yapılacağını da bilmem. Ben sadece bana vahyedilene uyuyorum ve ben apaçık bir uyarıcıdan başka bir şey değilim.\""},{"n":10,"t":"De ki: \"Hiç düşündünüz mü: Eğer bu (Kur’ân) Allâh katından olduğu halde siz onu tanımamışsanız; İsrâil oğullarından bir şâhid de bunun benzerini (Tevrât’ta) görüp inandığı halde siz (inanmağa) tenezzül etmemişseniz (durumunuz nice olur)? Allâh, zâlim bir toplumu doğru yola iletmez."},{"n":11,"t":"İnkâr edenler, inananlar için \"(Muhammed’in getirdiği) iyi bir şey olsaydı (şu zavallı kişiler) ona inanmada bizi geçemezlerdi, (biz onlardan önce inanırdık)\" dediler. Onlar, onun gösterdiği doğru yola eremediklerinden: \"Bu eski bir yalandır,\" diyeceklerdir."},{"n":12,"t":"Ondan önce de önder ve rahmet olarak Mûsâ’nın Kitabı vardır. Bu da (şirk ile) kendilerine yazık edenleri uyarmak, güzel davrananları müjdelemek için Arap diliyle indirilmiş (kendinden önceki Kitabı) doğrulayan Kitaptır."},{"n":13,"t":"\"Rabbimiz Allah’tır\" deyip sonra doğru olanlar, onlara korku yoktur ve onlar üzülmeyeceklerdir."},{"n":14,"t":"Onlar cennet halkıdır, yaptıklarına karşılık orada ebedi kalacaklardır."},{"n":15,"t":"Biz insana, ana babasına iyilik etmesini tavsiye ettik. Anası onu zahmetle taşıdı ve zahmetle doğurdu. (Ana karnında) Taşınması ile sütten kesilmesi otuz ay sürdü. Nihâyet (insan) güçlü çağına erip kırk yaşına varınca: \"Ya Rabbi dedi, beni, bana ve anama, babama verdiğin ni’mete şükretmeğe, râzı olacağın yararlı işler yapmağa sevk eyle. Benim için zürriyetim içinde de salâhı devam ettir (benden gelecek olanları da iyi insanlar yap). Ben sana yüz tuttum ve ben (sana) teslim olanlardanım.\""},{"n":16,"t":"Onlar öyle kişilerdir ki, yaptıklarının en iyisini onlardan kabul ederiz ve onların kötülüklerinden geçeriz, cennet halkı arasındadırlar. Bu, (dünyâda) kendilerine söylenen doğru söz(ün gerçekleşmesi)dir."},{"n":17,"t":"Fakat o kimse ki anasına, babasına: \"Öf size, benden önce nice nesiller gelip geçmiş, (kimse geri gelmemiş) iken siz benim (diriltilip) çıkarılacağımı mı bana va’dediyor (beni bununla mı tehdidediyor)sunuz?\" dedi. Onlarsa Allah’a sığınarak: \"Yazık sana, (etme, gel) inan; Allâh’ın sözü gerçektir\" derken o: \"Bu, eskilerin masallarından başka bir şey değildir.\" der."},{"n":18,"t":"İşte onlar da kendilerine (azâb) söz(ü) gerekli olmuş kimselerdir. Kendilerinden önce geçen cin ve insan toplulukları arasında (azâbın içinde) bulunacaklardır. Gerçekten onlar, ziyana uğrayanlardır."},{"n":19,"t":"Her birinin (inananların ve inanmayanların) yaptıkları işlerden dereceleri vardır. Allâh, onlara yaptıklarının karşılığını tam verir; kendilerine hiç haksızlık edilmez."},{"n":20,"t":"İnkâr edenler ateşe sunulacakları gün, (kendilerine denir ki): \"Dünyâ hayâtınızda bütün güzel şeylerinizi zayi ettiniz; (orada) bunlarla sefâ sürüp bunları tükettiniz (burası için hiçbir şey bırakmadınız). Yeryüzünde haksız yere büyüklük taslamanızdan ve yoldan çıkmanızdan ötürü bugün, alçaltıcı bir azâb ile cezâlandırılacaksınız.\""},{"n":21,"t":"Âd’ın kardeşini (Hûd’u) an: Ahkâf’taki kavmini uyarmıştı. Onun önünden ve ardından nice uyarıcılar da gelip geçti (demişti ki): \"Allah’tan başkasına kulluk etmeyin; ben sizin, büyük bir günün azâbına uğramanızdan korkuyorum.\""},{"n":22,"t":"Dediler: \"Sen bizi tanrılarımızdan çevirmek için mi geldin? Doğrulardan isen bizi tehdit ettiğin şeyi bize getir.\""},{"n":23,"t":"Dedi: \"(Azâbın ne zaman geleceğine dair) Bilgi, ancak Allâh katındadır. Ben, (tebliğ) görevlendirildiğim mesajı size duyuruyorum; fakat sizi câhillik eden bir kavim görüyorum.\""},{"n":24,"t":"Nihâyet azâbın (ufukta) geniş bir bulut halinde vâdilerine doğru geldiğini görünce: \"Bu, bize yağmur yağdıracak bir buluttur\" dediler. Hayır, o sizin acele gelmesini istediğiniz şey, içinde acı azâb bulunan bir rüzgârdır."},{"n":25,"t":"Rabbinin emriyle her şeyi yıkar, mahveder. Derken onlar o hale geldiler ki konutlarından başka bir şey görülmez oldu. İşte biz, suç işleyen toplumu böyle cezâlandırırız."},{"n":26,"t":"Onlara size vermediğimiz servet ve kuvveti vermiştik, onlara kulaklar, gözler ve gönüller yaratmıştık. Fakat ne kulakları, ne gözleri ne de gönülleri kendilerine bir yarar sağladı. Zira (düşünüp ibret almıyorlar, tersine) bile bile Allâh’ın âyetlerini inkâr ediyorlardı. Ve alay edip durdukları şey, kendilerini kuşatıverdi."},{"n":27,"t":"Andolsun, biz çevrenizdeki kentleri de yok ettik ve belki (küfürlerinden) dönerler diye âyetleri tekrar tekrar açıkladık."},{"n":28,"t":"Allah’tan başka, kendilerine (Allâh yanında) yakınlık sağlamak için tanrı edindikleri şeyler, kendilerine yardım etselerdi ya! Hayır, (tanrıları), onlardan kaybolup gittiler. İşte onların yalanları ve uydurmaları budur."},{"n":29,"t":"Bir zaman, cinlerden bir topluluğu Kur’an dinlemek üzere sana yöneltmiştik. Ona geldiklerinde (birbirlerine): \"Susun, (dinleyin)\" dediler. (Okuma) Bitirilince de uyarıcılar olarak kavimlerine döndüler:"},{"n":30,"t":"\"Ey kavmimiz, dediler, biz Mûsâ’dan sonra indirilen, kendinden öncekini doğrulayan, gerçeğe ve doğru yola götüren bir Kitap dinledik.\""},{"n":31,"t":"\"Ey kavmimiz, Allâh’ın da’vetçisine uyun ve O’na inanın ki (Allâh) günâhlarınızdan bir kısmını bağışlasın ve sizi, acı azâbdan korusun.\""},{"n":32,"t":"Kim Allâh’ın da’vetçisine uymazsa, yeryüzünde (başına inecek belâya) engel olamaz. Kendisinin O’ndan başka velileri de olmaz. Onlar, apaçık bir sapıklık içindedirler."},{"n":33,"t":"Gökleri ve yeri yaratan, bunları yaratmakla yorulmayan Allâh’ın, ölüleri diriltmeğe de kâdir olduğunu görmediler mi? Evet O, her şeye kâdirdir."},{"n":34,"t":"İnkâr edenler ateşe sunulacakları gün (Allâh onlara): \"(Nasıl), Bu gerçek değil miymiş?\" (der); \"Evet Rabbimiz hakkı için (gerçekmiş)\" derler. \"Öyleyse inkâr etmenizden dolayı azâbı tadın\" der."},{"n":35,"t":"O halde sen de, azim (ve irâde) sâhibi elçilerin sabrettikleri gibi sabret. O (nankör)ler için acele etme. Onlar, tehdidedildikleri azâbı gördükleri gün, sanki gündüzün sadece bir sâ’ati kadar yaşamış gibi olurlar. (Bu) Bir duyurudur. Yoldan çıkmış topluluktan başkası mı helâk edilecektir?"}],[{"n":1,"t":"Allâh, inkâr edip kendisinin yoluna engel olanların işlerini boşa çıkarmıştır."},{"n":2,"t":"İnanıp iyi işler yapanların, Rableri tarafından Muhammed’e indirilen gerçeğe inananların da günâhlarını örtmüş ve hallerini düzeltmiştir."},{"n":3,"t":"Bu, böyledir: Çünkü inkâr edenler bâtıla uymuşlar; inananlar ise Rablerinden gelen hakka uymuşlardır. İşte Allâh, onların durumlarını, insanlara böyle anlatır."},{"n":4,"t":"(Savaşta) İnkâr edenlerle karşılaştığınız zaman boyunlarını vurun. Nihâyet onları iyice vurup sindirince bağı sıkıca bağlayın (onları esir alın). Ondan sonra artık ya lutfen bırakır veya karşılığında fidye alırsınız. Harb, ağırlıklarını bırakıncaya (savaş sona erinceye) kadar (böyle yaparsınız). Allâh dileseydi (kendisi) onlardan öç alırdı, fakat sizi birbirinizle denemek için (size savaşı emrediyor). Allâh, kendi yolunda öldürülenlerin yaptıkları işleri zayi etmeyecektir."},{"n":5,"t":"Onları doğru yola iletecek ve durumlarını düzeltecektir."},{"n":6,"t":"Onları, kendilerine tanımladığı cennete sokacaktır."},{"n":7,"t":"Ey inananlar, eğer siz Allâh(ın dinin)e yardım ederseniz (Allâh da) size yardım eder; ayaklarınızı (hakkı koruma yolunda) sağlam tutar."},{"n":8,"t":"İnkâr edenler(e gelince): Yıkım onlara! (Allâh) Onların işlerini boşa çıkarmıştır."},{"n":9,"t":"Böyledir, çünkü onlar, Allâh’ın indirdiğinden hoşlanmamışlar, Allâh da onların amellerini heder etmiştir."},{"n":10,"t":"(Onlar) Yeryüzünde gezip dolaşmadılar mı ki kendilerinden öncekilerin sonunun nasıl olduğunu görsünler? Allâh onları(n evlerini, barklarını) yıkıp başlarına geçirmiştir. Bu kâfirlere de, onun benzeri sonuçlar vardır."},{"n":11,"t":"Bu böyledir, çünkü Allâh inananların koruyucusudur. Kâfirlerin ise koruyucuları yoktur."},{"n":12,"t":"Allâh, inanıp iyi işler yapanları, altlarından ırmaklar akan cennetlere sokar. İnkâr edenler ise dünyâda biraz yaşarlar, hayvanların yediği gibi yerler, (sonunda) yerleri ateştir."},{"n":13,"t":"Seni (içinden) çıkarmış olan kentten daha kuvvetli nice kent var ki biz onları yok ettik de onlara yardım eden çıkmadı."},{"n":14,"t":"Rabbinden bir delil üzerinde bulunan insan, kötü işi kendilerine süslendirilen ve keyiflerine uyan kimseler gibi olur mu? (Olmaz elbet)."},{"n":15,"t":"(Şirkten, günâhlardan) korunanlara söz verilen cennetin durumu şudur: İçinde bozulmayan su ırmakları, tadı değişmeyen süt ırmakları, içenlere lezzet veren şarap ırmakları ve süzme bal ırmakları vardır ve onlar için orada her çeşit meyva, Rablerinden de bağışlama vardır. (Şimdi bu ni’metler içinde yaşayanlar) ateşte ebedi kalan ve barsaklarını parça parça kesen sıcak suyun içirildiği kimseler gibi olur mu?"},{"n":16,"t":"Onlardan kimi de gelip seni dinler. Fakat senin yanından çıktıkları zaman kendilerine bilgi verilmiş olanlara: \"Demin ne söyledi?\" derler. Onlar Allâh’ın kalblerini mühürlediği, keyiflerinin ardına düşmüş kimselerdir."},{"n":17,"t":"Hidâyet bulanlara gelince, Allâh onların hidâyetlerini artırmış ve onlara korunmalarını (kendilerini kötü sonuçtan koruma çareleri) vermiştir."},{"n":18,"t":"(İnanmayanlar) İlle (helâk edilecekleri) sâ’atin ansızın kendilerine gelmesini mi bekliyorlar? İşte onun belirtileri geldi. O uyarıldıkları sâ’at kendilerine geldikten sonra artık öğüt almaları nereden mümkün olsun?"},{"n":19,"t":"Allah’tan başka tanrı olmadığını bil ve kendi günâhın, inanan erkeklerin ve inanan kadınların günâhı için (Allah’tan) mağfiret dile. Allâh, dönüp dolaşacağınız yeri ve varıp duracağınız yeri bilir."},{"n":20,"t":"İnananlar: \"(Savaş hakkında) Bir sûre indirilmeli değil miydi?\" derler. Fakat hükmü açık bir sûre indirilip de onda savaştan söz edilince, kalblerinde hastalık bulunanların sana ölümden bayılıp düşen kimsenin bakışı gibi baktıklarını görürsün. Onlara ölüm gerektir."},{"n":21,"t":"Onlara düşen, itâ’at etmek ve güzel söz söylemektir. İş ciddiye bindiği zaman Allah’a verdikleri söze sadık kalsalardı, elbette kendileri için daha iyi olurdu."},{"n":22,"t":"Demek işbaşına gelecek olursanız, yeryüzünde bozgunculuk yapacak, rahimleri (akrabâlık bağlarını) koparacaksınız öyle mi?\""},{"n":23,"t":"Onlar, Allâh’ın la’netleyip sağır yaptığı ve gözlerini kör ettiği kimselerdir."},{"n":24,"t":"Kur’ân’ı(n anlamını) düşünmüyorlar mı? Yoksa kalbler (inin) üzerinde kilitleri mi var (ki hiçbir hakikat, gönüllerine girmiyor)?"},{"n":25,"t":"Kendilerine doğru yol belli olduktan sonra arkalarına (yine eski küfürlerine) dönenlere, şeytân hatâlarını süslemiş ve (günâh işlemelerini) kolaylaştırmış ve onları uzun emellere, umutlara düşürmüştür."},{"n":26,"t":"Bu böyledir. Çünkü onlar, Allâh’ın indirdiğinden hoşlanmayanlara: \"Bazı hususlarda size itâ’at edeceğiz\" dediler. Oysa Allâh, onların gizlediklerini biliyor."},{"n":27,"t":"Ya melekler, canlarını alırken yüzlerine ve kıçlarına vurarak dövünecekleri zaman durumları nice olur?"},{"n":28,"t":"Bu böyledir. Çünkü onlar, Allâh’ı kızdıran şeylerin ardınca gittiler. O’nu râzı edecek şeylerden hoşlanmadılar. Allâh da onların amellerini boşa çıkardı."},{"n":29,"t":"Yoksa kalblerinde hastalık bulunanlar, Allâh’ın, kendilerinin kinlerini ortaya çıkarmayacak mı sandılar?"},{"n":30,"t":"Biz dileseydik onları sana gösterirdik, sen onları simâlarından tanırdın ve onları sözlerinin üslûbundan tanırdın. Allâh yaptığınız işleri bilir."},{"n":31,"t":"Andolsun biz sizi deneyeceğiz ki içinizden cihâd edenleri (güçlüklere) sabredenleri bilelim ve söylediğiniz sözlerin (doğru olup olmadığını) sınayalım."},{"n":32,"t":"Nankörlük edip Allâh yoluna engel olanlar ve kendilerine doğru yol belli olduktan sonra Elçiyi incitenler Allah’a hiçbir zarar veremezler. Allâh onların işlerini boşa çıkaracaktır."},{"n":33,"t":"Ey inananlar, Allah’a itâ’at edin, Elçi’ye itâ’at edin, işlerinizi boşa çıkarmayın."},{"n":34,"t":"Nankörlük edip Allâh yoluna engel olan, sonra kâfir olarak ölenleri Allâh affetmeyecektir."},{"n":35,"t":"Siz gâlip durumda iken gevşeyip barış istemeyin. Allâh sizinle beraberdir, O sizin amellerinizi zayi etmeyecektir."},{"n":36,"t":"Dünyâ hayâtı, bir oyun ve eğlenceden ibarettir. Eğer inanır, (günâhlardan) korunursanız (Allâh) size mükâfâtlarınızı verir ve sizden (bütün) mallarınızı istemez."},{"n":37,"t":"Eğer onları isteseydi de sizi sıkıştırsaydı, cimrilik ederdiniz ve kinlerinizi ortaya çıkarırdı (Allâh’ın Elçisine kin beslemeğe başlardınız)."},{"n":38,"t":"İşte sizler, Allâh yolunda harcamağa çağrılıyorsunuz; ama içinizden kimisi cimrilik ediyor. Cimrilik eden, kendi nefsine karşı cimrilik etmiş olur. Allâh zengindir, sizler fakirsiniz. Eğer yüz çevirecek olursanız, Allah, yerinize başka bir toplum getirir de onlar sizin gibi olmazlar."}],[{"n":1,"t":"Biz sana apaçık bir fetih verdik."},{"n":2,"t":"Ki Allâh, senin geçmiş ve gelecek günâhını bağışlasın (bütün tasalarını gidersin) ve sana olan ni’metini tamamlasın ve seni doğru bir yola iletsin."},{"n":3,"t":"Ve Allâh sana şanlı bir zafer versin."},{"n":4,"t":"O, imanlarına iman katsınlar diye mü’minlerin kalblerine huzûr indirdi. Göklerin ve yerin askerleri Allâh’ındır. Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":5,"t":"(Allâh işini böyle hikmetle çevirir, mü’minlerin gönüllerine huzûr verir, onlara görünmez askerleriyle yardım eder) Ki inanan erkekleri ve inanan kadınları, altlarından ırmaklar akan, içinde ebedi kalacakları cennetlere soksun, onların kötülüklerini de örtsün. Gerçekten bu, Allâh katında büyük bir başarıdır."},{"n":6,"t":"Allâh hakkında kötü zanda bulunan münâfık erkeklere ve münâfık kadınlara; (Allah’a) ortak koşan erkeklere ve ortak koşan kadınlara da azâbetsin. (Onların, müslümanlar için istedikleri) Kötü olaylar, kendi başlarına gelsin. Allâh, onlara gazabetmiş, onları la’netlemiş ve onlara cehennemi hazırlamıştır. Orası da ne kötü bir yerdir!"},{"n":7,"t":"Göklerin ve yerin askerleri Allâh’ındır. Allâh azizdir, hakimdir."},{"n":8,"t":"Biz seni, şâhid, müjdeleyici ve uyarıcı olarak gönderdik."},{"n":9,"t":"Ki Allah’a ve Resulüne inanasınız, O’nu(n dinini) destekleyesiniz. Ona saygı gösteresiniz ve sabah akşam O’nu tesbih ed(ip şânını yücelt)esiniz..."},{"n":10,"t":"Sana bi’at edenler (İslâm uğrunda ölünceye kadar savaşmak üzere sana söz verenler), gerçekte Allah’a bi’at etmektedirler. Allâh’ın eli, onların ellerinin üzerindedir. Kim ahdini bozarsa, kendi aleyhine bozmuş olur. Ve kim Allah’a verdiği sözü tutarsa Allâh ona büyük bir mükâfât verecektir."},{"n":11,"t":"Göçebe Araplardan geri bırakılanlar, sana diyecekler ki: \"Mallarımız ve çocuklarımız bizi, (seninle beraber gelmekten) alıkoydu. Bizim için mağfiret dile.\" Onlar, dilleriyle kalblerinde olmayan bir şeyi söylüyorlar. De ki: \"Allâh size bir zarar vermek istemiş, yahut size bir yarar vermek istemiş olsa Allâh’ın, sizin için dilediğine kim engel olabilir? Hayır, Allâh yaptıklarınızı haber almaktadır.\""},{"n":12,"t":"Herhalde siz sandınız ki Elçi ve mü’minler, bir daha âilelerine dönmeyecekler. Bu (düşünce) gönüllerinizde süslendirildi, (size güzel gösterildi,) kötü zanda bulundunuz ve helâki hak etmiş bir topluluk oldunuz."},{"n":13,"t":"Kim Allah’a ve Elçisine inanmazsa bilsin ki, biz, kâfirler için alevli bir ateş hazırlamışızdır."},{"n":14,"t":"Göklerin ve yerin mülkü Allâh’ındır. O, dilediğini bağışlar, dilediğine azâb eder. Allâh bağışlayandır, esirgeyendir."},{"n":15,"t":"O geri bırakılanlar, ganimetleri almak için gittiğiniz zaman: \"Bizi bırakın, sizinle beraber gelelim,\" diyecekler. Onlar, Allâh’ın sözünü değiştirmek istiyorlar. De ki: \"Siz, bizimle gelemezsiniz. Allâh, önceden böyle buyurdu.\" Onlar: \"Bizi çekemiyorsunuz\" diyecekler. Hayır, onlar, pek az anlarlar."},{"n":16,"t":"O geride kalan göçebe Araplara de ki: \"Siz yakında çok kuvvetli bir kavme karşı savaşmaya davet edileceksiniz, onlarla (ya) dövüşürsünüz, yahut (onlar) müslüman olurlar. Eğer itâat ederseniz, Allâh size güzel bir mükâfât verir; (yok) eğer önceden döndüğünüz gibi yine dönerseniz, size acı bir şekilde azâb eder."},{"n":17,"t":"Köre güçlük yoktur, topala güçlük yoktur, hastaya güçlük yoktur. (Bunlar savaşa katılmak zorunda değillerdir.) Kim Allah’a ve Elçisine itâ’at ederse (Allâh) onu, altından ırmaklar akan cennetlere sokar. Kim de yüz çevirirse onu da acı bir azâba uğratır."},{"n":18,"t":"Allâh şu mü’minlerden râzı olmuştur ki onlar, ağacın altında sana bi’at ediyorlardı, Allâh onların gönüllerinden geçeni bildiği için onların üzerine huzûr ve güven indirdi ve onlara yakın bir fetih verdi."},{"n":19,"t":"Yine onlara alacakları birçok ganimetler bahş eyledi. Allâh üstündür, hüküm ve hikmet sâhibidir."},{"n":20,"t":"Allâh size elde edeceğiniz birçok ganimetler va’detti. Şimdilik size bu (Hudeybiye Barışı)nı verdi. İnsanların ellerini sizden çekti ki bu, inananlara bir ibret olsun ve (Allah) sizi dosdoğru yola iletsin."},{"n":21,"t":"(Size) başka (ganimetler) de söz vermiştir ki henüz onları ele geçiremediniz fakat Allâh onları kuşatmış (sizin için ayırmış)tır. Allâh her şeyi yapabilir."},{"n":22,"t":"Eğer kâfirler sizinle savaşsalardı, arkalarına dön(üp kaç)arlardı, sonra ne bir koruyucu, ne de bir yardımcı bulabilirlerdi."},{"n":23,"t":"Bu, Allâh’ın öteden beri süregelen yasasadır. Allâh’ın yasasında bir değişme bulamazsın."},{"n":24,"t":"Mekke’nin göbeğinde, sizi onlara gâlip getirdikten sonra onların ellerini sizden, sizin ellerinizi onlardan çeken O’dur. Allâh, yaptıklarınızı görmektedir."},{"n":25,"t":"Onlar öyle kimselerdir ki inkâr ettiler, sizin Mescid-i Harâm’ı ziyaret etmenize ve bekletilen kurbanların yerlerine varmasına engel oldular. Eğer orada, kendilerini bilmediğiniz için tepeleyeceğiniz ve bilmeyerek tepelemenizden ötürü, kınanacağınız inanmış erkekler ve inanmış kadınlar olmasaydı (Allâh sizin savaşmanıza engel olmazdı. Böyle yaptı) ki Allâh, dilediğini rahmetine soksun. Şâyet (inananlar ve inanmayanlar) birbirinden ayrılmış olsalardı elbette onlardan inkâr edenleri, acı bir azâba çarptırırdık."},{"n":26,"t":"O zaman inkâr edenler, kalblerine öfke ve gayreti, o câhiliyye (çağının) öfke ve gayretini koymuşlardı, Allâh da Elçisine ve mü’minlere huzûr ve güvenini indirdi; onları takvâ kelimesine (sebâta ve ahde vefâya) bağladı. Zeten onlar, buna lâyık ve ehil idiler. Allâh, her şeyi bilendir."},{"n":27,"t":"Andolsun, Allâh, Elçisinin rüyâsını doğru çıkardı. Allâh dilerse, başlarınızı (kökten) traş ederek ve(ya) saçlarınızı kısaltarak, korkmadan, güven içinde Mescid-i Harâm’a gireceksiniz. Allâh sizin bilmediğinizi bildi, bundan önce size yakın bir fetih verdi."},{"n":28,"t":"O, Elçisini hidâyet ve hak dinle gönderdi ki, o (hak di)ni, bütün dinlere üstün kılsın. Şâhid olarak Allah yeter."},{"n":29,"t":"Muhammed Allâh’ın elçisidir. Onun yanında bulunanlar, kâfirlere karşı katı, birbirlerine karşı merhametlidirler. Onların, rükû’ ve secde ederek Allâh’ın lutuf ve rızâsını aradıklarını görürsün. Yüzlerinde secde izinden nişanları vardır. Onların Tevrât’taki vasıfları ve İncildeki vasıfları da şöyle bir ekin gibidir ki, filizini çıkardı, onu güçlendirdi, kalınlaştı, derken gövdesinin üstüne dikildi, ekincilerin hoşuna gider, onlara karşı kâfirleri de öfkelendirir bir duruma geldi. Allâh onlardan inanıp iyi işler yapanlara mağfiret ve büyük mükâfât va’detmiştir."}],[{"n":1,"t":"Ey inananlar, Allâh’ın ve Elçisinin önüne geçmeyin. Allah’tan korkun. Şüphesiz Allâh, işitendir, bilendir."},{"n":2,"t":"Ey inananlar, seslerinizi, Peygamberin sesinin üstüne çıkarmayın, birbirinizle yüksek sesle konuştuğunuz gibi, onunla da öyle yüksek sesle konuşmayın; yoksa siz farkında olmadan amelleriniz boşa gider."},{"n":3,"t":"Allâh’ın Elçisinin huzûrunda seslerini kısanlar, öyle kimselerdir ki Allâh, onların kalblerini, takvâ için imtihan etmiş (onların takvâya ehil olduklarını anlamış)tır. Onlar için mağfiret ve büyük bir mükâfât vardır."},{"n":4,"t":"Odaların arkasından sana bağıranların çoğu, düşüncesiz kimselerdir."},{"n":5,"t":"Onlar, sen kendilerinin yanına çıkıncaya kadar bekleselerdi, elbette kendileri için daha iyi olurdu. Allâh bağışlayandır, esirgeyendir."},{"n":6,"t":"Ey inananlar, size fâsık (yoldan çıkmış) bir adam bir haber getirirse onun doğruluğunu araştırın. Yoksa bilmeyerek bir topluluğa karşı kötülük edersiniz de sonra yaptığınıza pişman olursunuz."},{"n":7,"t":"Bilin ki, Allâh’ın Elçisi içinizdedir. Şâyet o, birçok işte size uysaydı, sıkıntıya düşerdiniz. Fakat Allâh size imanı sevdirdi ve onu sizin kalblerinizde süsledi ve size küfrü, fıskı ve isyânı çirkin gösterdi. İşte doğru yolda olanlar bunlardır."},{"n":8,"t":"(Bu) Allâh’ın bir lutuf ve ni’metidir. Allâh bilendir, hakimdir."},{"n":9,"t":"Eğer inananlardan iki grup vuruşurlarsa onların arasını düzeltin; şâyet biri ötekine saldırırsa Allâh’ın buyruğuna dönünceye kadar saldıran tarafla vuruşun. (Allâh’ın buyruğuna) Dönerse artık adâletle onların arasını düzeltin ve dâimâ âdil olun. Çünkü Allâh, adâlet yapanları sever."},{"n":10,"t":"Muhakkak mü’minler kardeştirler. Kardeşlerinizin arasını düzeltin ve Allah’tan korkun ki size rahmet edilsin."},{"n":11,"t":"Ey inananlar, bir topluluk, başka bir toplulukla alay etmesin. Belki (alay ettikleri kimseler), kendilerinden iyidirler. Kadınlar da başka kadınlarla alay etmesinler. Belki onlar, kendilerinden iyidirler. Birbirinizde kusur aramayın; birbirinizi kötü lakaplarla çağırmayın. İnandıktan sonra fısk adı, ne kötü bir şeydir! Kim tevbe etmezse, işte onlar, zâlimdirler."},{"n":12,"t":"Ey inananlar, zandan çok sakının. Zira zannın bir kısmı günâhtır. Birbirinizin gizli şeylerini araştırmayın; biriniz diğerinizi arkasından çekiştirmesin. Biriniz, ölmüş kardeşinin etini yemeği sever mi? İşte bundan iğrendiniz. O halde Allah’tan korkun, şüphesiz Allâh, tevbeyi çok kabul eden, çok esirgeyendir."},{"n":13,"t":"Ey insanlar, biz sizi bir erkek ve bir kadından yarattık ve birbirinizi tanımanız için sizi milletlere ve kabilelere ayırdık. Allâh yanında en üstün olanınız, (günâhlardan) en çok korunanınızdır. Allâh bilendir, haber alandır."},{"n":14,"t":"Göçebe Araplar: \"İnandık\" dediler. De ki: \"İnanmadınız, fakat ’İslâm olduk’ deyin. Henüz iman kalblerinize girmedi. Eğer Allah’a ve Elçisine itâ’at ederseniz (Allâh), yaptığınız güzel işlerden hiçbirinin sevâbını size eksik vermez. Allâh çok bağışlayan, çok esirgeyendir.\""},{"n":15,"t":"Mü’minler onlardır ki Allâh’a ve Elçisine inandılar, sonra şüphe etmediler; Allâh yolunda mallarıyle, canlarıyle cihâd ettiler. İşte (iman sözlerinde) doğru olanlar onlardır."},{"n":16,"t":"De ki: \"Siz mi Allah’a din(darlığ)ınızı öğreteceksiniz? Allâh, göklerde ve yerde olanları bilir. Allâh, her şeyi bilendir.\""},{"n":17,"t":"İslâm olmalarını senin başına kakıyorlar. De ki: \"Müslüman olmanızı benim başıma kakmayın. Tersine, eğer gerçekten inanmışsanız, sizi imâna ilettiği için Allah, sizin başınıza kaksa yeridir.\""},{"n":18,"t":"Şüphesiz Allâh, göklerin ve yerin gizlisini bilir. Allâh yaptıklarınızı görmektedir."}],[{"n":1,"t":"Kâf. Zikir’li (uyarıcı, şerefli) Kur’ân’a andolsun,"},{"n":2,"t":"İçlerinden bir uyarıcı gelmesine şaştılar da, o kâfirler: \"Bu tuhaf bir şeydir\" dediler."},{"n":3,"t":"\"Biz öldüğümüz ve toprak olduğumuz zaman mı (tekrar bedene döneceğiz)? Bu, uzak bir dönüştür.\""},{"n":4,"t":"Biz yerin, onlar(ın cesetlerin)den ne eksilttiğini bilmişizdir. Yanımızda (her şeyi) zapteden bir Kitâp vardır."},{"n":5,"t":"Doğrusu onlar, hak kendilerine gelince onu yalanladılar. Şimdi onlar çalkantılı bir durumun içindedirler."},{"n":6,"t":"Üstlerindeki göğe bakmadılar mı, onu nasıl yaptık, süsledik, hiçbir çatlağı yoktur?"},{"n":7,"t":"Arzı nasıl yaydık, ona sağlam dağlar attık, onda her güzel çifti bitirdik!"},{"n":8,"t":"(Bütün bunları) Allah’a yönelen her kulun, gönül gözünü açmak için ve (ona) ibret vermek için (yaptık)."},{"n":9,"t":"Gökten bereketli bir su indirdik, onunla bahçeler ve biçilecek dâne(li ekin)ler bitirdik."},{"n":10,"t":"Birbirine girmiş kat kat tomurcukları olan yüksek hurma ağaçları yetiştirdik;"},{"n":11,"t":"Kullara rızık olması için. Ve o su ile, ölü bir ülkeye can verdik. İşte çıkış da öyledir."},{"n":12,"t":"Onlardan önce Nûh kavmi, Resliler ve Semûd (kavmi) de yalanlamıştı."},{"n":13,"t":"’Âd, Fir’avn ve Lût’un kardeşleri (durumundaki kavmi),"},{"n":14,"t":"Eyke halkı ve Tubba’ kavmi. Bunların hepsi elçileri yalanlayıp, uyardığım (azâb)ı hak ettiler."},{"n":15,"t":"İlk yaratmadan âciz mi kaldık ki (yeniden yaratamayalım)? Doğrusu onlar yeni bir yaratmadan kuşku içindedirler."},{"n":16,"t":"Andolsun insanı biz yarattık ve nefsinin ona ne fısıldadığını biliriz, çünkü biz ona şah damarından daha yakınız."},{"n":17,"t":"Onun sağında ve solunda oturan iki alıcı (melek, onun sözlerini ve işlerini) kaydetmektedir."},{"n":18,"t":"(İnsan,) Hiçbir söz söylemez ki yanında kendisini gözetleyen, dediklerini zapteden (bir melek) hazır bulunmasın."},{"n":19,"t":"Ölüm sarhoşluğu gerçekten geldi. İşte (ey insan) bu, senin öteden beri kaçtığın şeydir."},{"n":20,"t":"Sûr’a üflendi. İşte bu, kendisine karşı uyarılan gündür."},{"n":21,"t":"Her can, yanında bir sürücü ve şâhidle geldi."},{"n":22,"t":"(Allâh ona): \"Andolsun, sen bundan gaflet içinde idin. Biz sen(in gözün)den perdeni açtık; bugün artık gözün keskindir\" (dedi)."},{"n":23,"t":"Yanındaki arkadaşı: \"İşte yanımdaki hazır\" dedi."},{"n":24,"t":"(Allâh sürücü ve şâhide buyurdu ki): \"Haydi ikiniz, atın cehenneme her inatçı nankörü!\""},{"n":25,"t":"\"Hayra engel olan, saldırgan, şüpheciyi.\""},{"n":26,"t":"\"O ki Allâh ile beraber başka tanrılar edindi, bundan dolayı onu çetin bir azâba atın.\""},{"n":27,"t":"Yanındaki arkadaşı dedi ki: \"Rabbimiz, ben onu azdırmadım, zaten o kendisi derin bir sapıklık içinde idi.\""},{"n":28,"t":"(Allâh) Buyurdu ki: \"Huzûrumda çekişmeyin. Ben size daha önce uyarı göndermiştim.\""},{"n":29,"t":"\"Benim huzûrumda söz değiştirilmez ve ben kullara zulmedici değilim.\""},{"n":30,"t":"O gün cehenneme: \"Doldun mu?\" deriz. \"Daha yok mu\" der."},{"n":31,"t":"Cennet de korunanlara yaklaştırılmıştır, uzak değildir."},{"n":32,"t":"\"İşte size va’dedilen budur. Dâimâ Allah’a yüz tutan (O’nun buyruklarını) koruyan,"},{"n":33,"t":"Görmeden Rahmân’a saygı gösteren ve (Hakka) dönük bir yürek getiren herkesin (mükâfâtı budur)!\""},{"n":34,"t":"\"Ona selâm (esenlik) ile girin. Bu, süreklilik günüdür!\""},{"n":35,"t":"Orada onlara istedikleri herşey vardır. Katımızda daha fazlası da vardır."},{"n":36,"t":"Bunlardan önce nice kuşakları helâk etmiştik ki onların tutuşu, bunlardan daha kuvvetli idi, yakalaması daha güçlü idi. Ülkelerde gezip dolaşmışlardı, ama bir kurtuluş buldular mı?"},{"n":37,"t":"Muhakkak ki bunda, kalbi olan, yahut şâhid olarak (zihnini toplayarak dikkatle) kulak veren kimse için bir öğüt vardır."},{"n":38,"t":"Andolsun, biz gökleri, yeri ve ikisi arasında bulunanları altı günde yarattık, bize hiçbir yorgunluk dokunmadı."},{"n":39,"t":"Onların dediklerine sabret ve Rabbini övgü ile an! Güneş doğmadan önce, batmadan önce,"},{"n":40,"t":"Gecenin bir kısmında ve secde arkalarında O’nu tesbih et."},{"n":41,"t":"Dinle, o gün o ünleyici, yakın bir yerden çağırır."},{"n":42,"t":"O gün o çağrıyı gerçek olarak duyarlar. İşte bu, (dirilip) çıkış günüdür."},{"n":43,"t":"Yaşatan ve öldüren ancak biziz, biz. Dönüş de bizedir."},{"n":44,"t":"O gün yer onlar(ın üstün)den yarıl(ıp açıl)ır, (çağırana doğru) sür’atle koşarlar. İşte bu, toplamadır; bize göre kolaydır."},{"n":45,"t":"Biz onların ne dediklerini biliyoruz. Sen onların üstünde bir zorlayıcı değilsin, sadece tehdidimden korkanlara Kur’ân ile öğüt ver."}],[{"n":1,"t":"Savurup kaldıranlara,"},{"n":2,"t":"(Yağmur) Yüklü (bulut)lara,"},{"n":3,"t":"Kolayca akıp gidenlere,"},{"n":4,"t":"İş(ler)i taksim edenlere (rızıkları, yağmurları dağıtan güçlere) andolsun ki,"},{"n":5,"t":"Size va’dedilen, mutlaka doğrudur."},{"n":6,"t":"Cezâ muhakkak olacaktır."},{"n":7,"t":"(Çeşitli) yolları (yörüngeleri) bulunan göğe andolsun ki,"},{"n":8,"t":"Siz, çeşitli söz(ler) içindesiniz."},{"n":9,"t":"Çevrilen, ondan çevriliyor."},{"n":10,"t":"O (çeşitli sözleri) atan yalancılar kahrolsun!"},{"n":11,"t":"Onlar aptallık içinde yanılıp durmaktadırlar."},{"n":12,"t":"\"Cezâ günü ne zaman?\" diye sorarlar."},{"n":13,"t":"O gün onlar ateş üzerinde yakılacaklardır."},{"n":14,"t":"(Kendilerine): \"Fitnenizi (fesâdınızın cezâsını) tadın! Acele isteyip durduğunuz şey budur işte!\" (denilecek)."},{"n":15,"t":"Korunanlar, cennetlerde, çeşme başlarındadırlar;"},{"n":16,"t":"Rablerinin, kendilerine verdiğini alırlar. Çünkü onlar bundan önce güzel davranırlardı."},{"n":17,"t":"Geceleri pek az uyurlardı,"},{"n":18,"t":"Seherlerde onlar istiğfar ederlerdi,"},{"n":19,"t":"Mallarında dilenci ve yoksul için hak vardı."},{"n":20,"t":"Kesin inanacaklar için yerde nice ibretler vardır."},{"n":21,"t":"Kendi canlarınızda da öyle. Görmüyor musunuz?"},{"n":22,"t":"Gökte rızkınız da var, uyarıldığınız (azâb)da var!"},{"n":23,"t":"Göğün ve yerin Rabbine andolsun ki o, sizin konuştuğunuz gibi gerçektir."},{"n":24,"t":"İbrâhim’in ağırlanan konuklarının haberi sana geldi mi?"},{"n":25,"t":"Bir zaman onun yanına girmişler: \"Selâm\" demişlerdi. \"Selâm, dedi, (siz) tanınmamış bir topluluk(sunuz).\""},{"n":26,"t":"(Konuklarına yemek hazırlamak için) gizlice âilesinin yanına gitti, semiz bir buzağı getirdi."},{"n":27,"t":"Onu, önlerine yaklaştırdı, \"Yemez misiniz?\" dedi."},{"n":28,"t":"(Yemediklerini görünce) Onlardan içine bir korku düşürdü. \"Korkma\" dediler ve ona bilgin bir oğlan çocuğu müjdelediler."},{"n":29,"t":"Karısı (Sare) çığlık içinde geldi (hayretten elini) yüzüne vurarak: \"(Ben) Kısır bir kocakarı(yım, benden nasıl çocuk olur)?\" dedi."},{"n":30,"t":"Dediler ki: \"Rabbin böyle dedi. O, hüküm ve hikmet sâhibidir, bilendir.\""},{"n":31,"t":"(İbrâhim): \"O halde göreviniz nedir ey elçiler?\" dedi."},{"n":32,"t":"Dediler: \"Biz suçlu bir kavme gönderildik.\""},{"n":33,"t":"\"Ki onların üzerine çamurdan taş(lar) salalım.\""},{"n":34,"t":"\"Rabbinin katında, haddi aşanlar için işâretlenmiş (taşlar).\""},{"n":35,"t":"Orada bulunan mü’minleri çıkardık."},{"n":36,"t":"Zaten orada bir ev (halkın)dan başka müslüman da bulmadık."},{"n":37,"t":"Acı azâbdan korkanlar için orada bir ibret bıraktık."},{"n":38,"t":"Mûsâ’da da (ibret alınacak şeyler vardır). Onu açık bir delil ile Fir’avn’e göndermiştik."},{"n":39,"t":"(Fir’avn ona) Yanını çevirdi ve: \"Bu, ya büyücü veya cinlidir\" dedi."},{"n":40,"t":"Biz de onu ve askerlerini yakaladık, onları denize attık. (O boğulurken pişmanlıkla) Kendi kendini kınıyordu."},{"n":41,"t":"’Âd (kavmin)de de (ibret alınacak şeyler vardır). Onlara, köklerini kesen bir rüzgâr gönderdik."},{"n":42,"t":"Üzerinden geçtiği hiçbir şeyi bırakmıyor, onu kül gibi ediyordu."},{"n":43,"t":"Semûd (kavmin)de de (ibret alınacak şeyler vardır). Onlara: \"Bir süreye kadar sefâ sürün\" denmişti."},{"n":44,"t":"Rablerinin buyruğuna başkaldırdılar, bu yüzden onlar bakıp dururlarken, onları yıldırım yakaladı."},{"n":45,"t":"(Yurtlarında çöküverdiler) Ne kalkabildiler, ne de (bu duruma) engel olabildiler."},{"n":46,"t":"Daha önce de Nûh kavmini helâk etmiştik. Çünkü onlar da yoldan çıkmış bir toplum idiler."},{"n":47,"t":"Göğü sağlam yaptık, biz genişleticiyiz (kudretimiz geniştir, göğü öyle genişleten biziz)."},{"n":48,"t":"Yeri biz döşedik, (biz) ne güzel döşeyiciyiz."},{"n":49,"t":"Her şeyden iki çift (erkek dişi) yarattık ki düşünüp öğüt alasınız."},{"n":50,"t":"\"O halde Allâh’a kaçın, ben size O’nun tarafından görevlendirilmiş apaçık bir uyarıcıyım.\""},{"n":51,"t":"\"Allâh ile beraber başka tanrılar uydurmayın. Ben size O’nun tarafından görevlendirilmiş apaçık bir uyarıcıyım.\""},{"n":52,"t":"İşte böyle, onlardan önce de ne kadar elçi geldiyse mutlaka: \"Büyücü veya cinlenmiş\" dediler."},{"n":53,"t":"Bunu birbirlerine tavsiye mi ettiler (ki hep aynı şeyi söylüyorlar)? Doğrusu, onlar azgın bir topluluktur."},{"n":54,"t":"Onlardan yüz çevir, sen kınanacak değilsin."},{"n":55,"t":"Ama yine de hatırlat, çünkü hatırlatmak inananlara yararlıdır."},{"n":56,"t":"Ben cinleri ve insanları, ancak bana kulluk etsinler diye yarattım."},{"n":57,"t":"Ben onlardan rızık istemiyorum, beni beslemelerini de istemiyorum."},{"n":58,"t":"Şüphesiz rızık veren, sağlam kuvvet sâhibi olan ancak Allah’tır."},{"n":59,"t":"Muhakkak ki, bu zulmedenlerin de (geçmiş) arkadaşlarının payı gibi bir azâb payı vardır, (ötekilerin başına gelen azâb gibi bir azâb bunların da başına gelecektir), acele etmesinler."},{"n":60,"t":"Uyarıldıkları günlerinden dolayı vay o kâfirlerin haline!"}],[{"n":1,"t":"Andolsun Tûr’a (Mûsâ’nın vahiy aldığı Sinâ Dağı’na)."},{"n":2,"t":"Satır satır yazılmış Kitaba;"},{"n":3,"t":"Yayılmış ince deri üzerine,"},{"n":4,"t":"Ma’mur (bakımlı, şen) Ev (Ka’be’y)e,"},{"n":5,"t":"Yükseltilmiş tavana (göğe),"},{"n":6,"t":"Kaynatılmış denize (bunlara andolsun ki),"},{"n":7,"t":"Rabbinin azâbı mutlaka vuku bulacaktır;"},{"n":8,"t":"Ona engel olacak bir şey yoktur."},{"n":9,"t":"O gün gök, bir çalkalanış çalkanır,"},{"n":10,"t":"Dağlar bir yürüyüş yürür ki!.."},{"n":11,"t":"Yalanlayanların vay haline o gün!"},{"n":12,"t":"O daldıkları bâtıl içinde oynayıp duranlar,"},{"n":13,"t":"O gün (şöyle denilerek) cehennem ateşine kakılırlar:"},{"n":14,"t":"\"İşte yalanlayıp durduğunuz ateş budur!\""},{"n":15,"t":"\"(Nasıl) Şimdi bu, büyümüymüş, yoksa siz mi görmüyor musunuz?\""},{"n":16,"t":"\"Girin ona, ister dayanın, ister dayanmayın, sizin için birdir. Ancak yaptıklarınıza göre cezâlandırılacaksınız.\""},{"n":17,"t":"Korunanlar da cennetlerde, ni’met içindedirler."},{"n":18,"t":"Rablerinin kendilerine verdikleriyle sefâ sürerler. Rableri onları, cehennem azâbından korumuştur."},{"n":19,"t":"\"Yaptıklarınıza karşılık âfiyetle yeyin, için;\""},{"n":20,"t":"\"Sıra sıra dizilmiş koltuklara yaslanarak.\" Onları, iri gözlü hûrilerle evlendirmişizdir."},{"n":21,"t":"Kendileri inanmış, zürriyetleri de imânda kendilerine uymuş olan kimselerin zürriyetlerini de kendilerine katmışızdır; kendi ameller(inin sevâb)ından da hiçbir şey eksiltmemişizdir. Herkes kendi kazandığına bağlıdır."},{"n":22,"t":"Ve onlara canlarının istediği meyvadan ve etten bol bol vermişizdir."},{"n":23,"t":"Orada bir kadeh kapışırlar ki içinde ne saçmalama var, ne de günâha sokma."},{"n":24,"t":"Çevrelerinde de kendilerine mahsus, sedef içinde saklı inci gibi civanlar dolaşır (hizmet eder)."},{"n":25,"t":"Birbirlerine dönmüş soruyorlar:"},{"n":26,"t":"\"Daha önce biz âilemiz içinde (iken sonumuzdan) korkardık.\" dediler."},{"n":27,"t":"\"Allâh bize lutfetti de bizi o delikçiklere işleyen azâbdan korudu.\""},{"n":28,"t":"\"Biz bundan önce yalnız O’na yalvarır (bizi korumasını O’ndan niyaz eder)dik. Çünkü iyilik eden, esirgeyen O’dur, O.\""},{"n":29,"t":"(Ey Muhammed), Sen hatırlat, öğüt ver. Rabbinin ni’meti sayesinde sen ne kâhinsin, ne de mecnun."},{"n":30,"t":"Yoksa onlar (senin hakkında): \"Bir şâ’irdir, zamanın felâketlerine çarpılmasını gözetliyoruz\" mu diyorlar?"},{"n":31,"t":"De ki: \"Gözetleyin, ben de sizinle beraber gözetleyenlerdenim. (Bakalım hangimiz felâketlere çarpılacağız?)\""},{"n":32,"t":"Akılları mı bunu kendilerine emrediyor, yoksa onlar azgın bir topluluk mudur?"},{"n":33,"t":"Yoksa \"Onu uydurdu\" mu diyorlar? Hayır, onlar inanmıyorlar."},{"n":34,"t":"Doğru iseler haydi onun gibi bir söz getirsinler."},{"n":35,"t":"Yoksa kendileri, hiçbir şey olmadan (raslantı sonucu olarak) mı yaratıldılar? Yoksa yaratanlar kendileri midir?"},{"n":36,"t":"Yoksa gökleri ve yeri mi yarattılar? Hayır, onlar düşünüp de inanmazlar."},{"n":37,"t":"Yoksa Rabbinin hazineleri onların yanında mıdır? Yahut hâkim olan (her şeyi istedikleri gibi yöneten) kendileri midir?"},{"n":38,"t":"Yoksa onların, (göğe çıkıp meleklerin sözlerini ve onlara vahyedileni) dinleyecekleri bir merdivenleri mi var? Öyleyse dinleyenleri, (meleklerin sözlerini dinlediklerine) açık bir delil getirsin."},{"n":39,"t":"Yoksa kızlar O’na, oğullar size mi?"},{"n":40,"t":"Yoksa sen onlardan (vahiyleri duyurmana karşı) bir ücret istiyorsun da onlar, ağır bir borç yükü altında mı kalmışlardır?"},{"n":41,"t":"Yoksa gayb (görülmeyen bilgi) kendilerinin yanındadır da kendileri mi (oradan istediklerini) yazıyorlar?"},{"n":42,"t":"Yoksa bir tuzak mı kurmak istiyorlar? Asıl tuzağa düşecek olanlar, o inkâr edenlerin kendileridir."},{"n":43,"t":"Yoksa onların Allah’tan başka bir tanrısı mı var? Allâh’ın şânı onların ortak koştuklarından yücedir."},{"n":44,"t":"Gökten bir parçanın düştüğünü görseler, (yine inatlarından): \"Üst üste yığılmış bulutlardır\" derler."},{"n":45,"t":"Korkudan bayılacakları günlerine kavuşuncaya kadar bırak onları."},{"n":46,"t":"O gün, tuzakları kendilerine hiçbir yarar sağlamaz ve onlara yardım da edilmez."},{"n":47,"t":"Zulmedenlere, bundan başka bir azâb da vardır. Fakat çokları bilmezler."},{"n":48,"t":"Rabbinin hükmüne sabret, çünkü sen, gözlerimizin önündesin (korumamız altındasın), Kalktığın zaman Rabbini övgü ile an."},{"n":49,"t":"Gecenin bir kısmında ve yıldızların ardından da O’nu tesbih et."}],[{"n":1,"t":"Aşağı kayan yıldıza andolsun ki:"},{"n":2,"t":"Arkadaşınız sapmadı, azmadı."},{"n":3,"t":"O hevâ’dan konuşmaz."},{"n":4,"t":"O(nun okuduğu Kur’ân) kendisine vahyedilen vahiyden başka bir şey değildir."},{"n":5,"t":"Onu, mühtiş kuvvetleri olan biri öğretti;"},{"n":6,"t":"Üstün akıl sâhibi (melek). Doğruldu;"},{"n":7,"t":"Kendisi yüksek ufukta iken."},{"n":8,"t":"Sonra yaklaştı, (yere doğru) sarktı."},{"n":9,"t":"(Muhammed ile arasındaki mesafe) İki yay uzunluğu kadar, yahut daha az kaldı."},{"n":10,"t":"Kuluna, vahyettiğini vahyetti."},{"n":11,"t":"Gönül gördüğünde yanılmadı (yalan söylemedi, gerçeği gördü)."},{"n":12,"t":"Onun gördüğünden kuşku mu duyuyorsunuz?"},{"n":13,"t":"Andolsun, onu bir inişinde daha görmüştü;"},{"n":14,"t":"Sidretü’l-Müntehâ (uzak ağaç)ın yanında,"},{"n":15,"t":"Ki onun yanında oturulacak bahçe vardır."},{"n":16,"t":"Sidre’yi kaplayan kaplıyordu."},{"n":17,"t":"(Muhammed’in) Göz(ü) şaşmadı ve azmadı."},{"n":18,"t":"Andolsun, Rabbinin büyük âyetlerinden bazılarını gördü."},{"n":19,"t":"Gördünüz mü o Lât ve ’Uzzâ’yı?"},{"n":20,"t":"Ve üçüncü(leri olan) öteki (put) Menat’ı?"},{"n":21,"t":"Demek erkek size, kadın Allah’a mı?"},{"n":22,"t":"O halde bu insafsızca bir taksim!"},{"n":23,"t":"Onlar, sizin ve babalarınızın, (tanrı) diye isimlendirdiğiniz (boş, kavramsız) isimlerden başka bir şey değildir. Allâh, onlara hiçbir güç (tanrı oldukları hakkında hiçbir delil) indirmemiştir. O(putlara tapa)nlar zanna ve nefislerin hevesine uyuyorlar. Oysa kendilerine, Rableri tarafından yol gösterici gelmiştir."},{"n":24,"t":"Yoksa insan, her arzu ettiğine sâhip mi olacaktır?"},{"n":25,"t":"Son da ilk de (âhiret de, dünyâ da) Allâh’ındır."},{"n":26,"t":"Göklerde nice melek var ki onların şefâ’ati hiçbir işe yaramaz. Meğer Allâh’ın dilediği ve râzı olduğu kimseye izin verdikten sonra olsun (ancak o zaman şefâ’atin faydası olur)."},{"n":27,"t":"Âhirete inanmayanlar, meleklere dişilerin adlarını takıyorlar."},{"n":28,"t":"Onların bu hususta bir bilgileri yoktur. Sadece zanna uyuyorlar. Zan ise haktan hiçbir gerçek kazandırmaz. (Zan ile gerçeğe ulaşılmaz.)"},{"n":29,"t":"Bizi anmaktan yüz çeviren ve dünyâ hayâtından başka bir şey istemeyen kimseden yüz çevir."},{"n":30,"t":"İşte onların erişebilecekleri bilgi (sınırı) budur. (Bundan ötesine akılları ermez). Şüphesiz Rabbin, yolundan sapanı da iyi bilir ve O, yola geleni de iyi bilir."},{"n":31,"t":"Göklerde ve yerde bulunan herşey Allâh’ındır. (Bunları yaratmıştır) Ki kötülük edenleri, yaptıklarıyle cezâlandırsın, güzel davrananları da güzellikle mükâfâtlandırsın."},{"n":32,"t":"Onlar, günâhın büyüklerinden ve çirkin işlerden kaçınırlar, yalnız bazı küçük hatâlar işleyebilirler. Şüphesiz Rabbinin affı geniştir (O kendisine yönelen kulunu affeder). O sizi daha iyi bilir: Gerek sizi topraktan inşâ ettiği, gerek annelerinizin karınlarında bulunduğunuz zaman biçim verdiği sırada (sizin her hâlinizi bilmiştir), artık kendinizi övüp yüceltmeyin, çünkü O, korunanı daha iyi bilir."},{"n":33,"t":"Gördün mü şu adamı ki arkasını döndü?"},{"n":34,"t":"Azıcık verdi, gerisini elinde sıkı sıkı tuttu?"},{"n":35,"t":"Gayb’ın bilgisi kendi yanında da o mu (âlemin esrarını) görüyor?"},{"n":36,"t":"Yoksa kendisine haber mi verilmedi: Mûsâ’nın sahifelerinde bulunan,"},{"n":37,"t":"Ve çok vefâlı İbrâhim’in (sahifelerinde bulunan şu gerçekler):"},{"n":38,"t":"Ki hiçbir günâhkâr, başkasının günâh yükünü yüklenmez."},{"n":39,"t":"İnsana çalışmasından başka bir şey yoktur."},{"n":40,"t":"Ve çalışması da yakında görülecektir."},{"n":41,"t":"Sonra ona tastamam karşılığı verilecektir."},{"n":42,"t":"Ve sonunda senin Rabbine varılacaktır."},{"n":43,"t":"Güldüren de O’dur, ağlatan da O’dur."},{"n":44,"t":"Öldüren de O’dur, yaşatan da O’dur."},{"n":45,"t":"O yarattı iki çifti: erkeği ve dişiyi,"},{"n":46,"t":"Atıldığı zaman nutfe (sperm)den."},{"n":47,"t":"Şüphesiz tekrar yaratmak da O’nun işidir."},{"n":48,"t":"Zengin eden O’dur, bol verip memnun eden O."},{"n":49,"t":"(Taptıkları) Şi’râ (yıldızı)nın Rabbi O’dur."},{"n":50,"t":"O helâk etti, önce gelen ’Âd’ı,"},{"n":51,"t":"Semûd’u, komadı (onları)."},{"n":52,"t":"Önceden de Nûh kavmini (helâk etmişti). Çünkü onlar daha zâlim ve azgın idiler."},{"n":53,"t":"Altı üstüne getirilen kentleri (Lût kavminin oturduğu bölgeleri) devirip yıktı."},{"n":54,"t":"Onların üstüne neler çöktü, neler!"},{"n":55,"t":"O halde Rabbinin hangi ni’metinden kuşku duyuyorsun?"},{"n":56,"t":"Bu (Kur’ân veya peygamber) de ilk uyarıcılar gibi bir uyarıcıdır."},{"n":57,"t":"O yaklaşıcı, yaklaştı."},{"n":58,"t":"Onu Allah’tan başka açacak (geldiği zaman kaldıracak, vaktini erteleyecek veya onun ne zaman geleceğini belirleyecek) kimse yoktur."},{"n":59,"t":"Şimdi siz bu söze mi hayret ediyorsunuz?"},{"n":60,"t":"Ve gülüyorsunuz da ağlamıyorsunuz?"},{"n":61,"t":"Ve siz baş kaldırıyorsunuz?"},{"n":62,"t":"Haydi Allah’a secde edin ve kulluk edin!"}],[{"n":1,"t":"O sâ’at yaklaştı, ay yarıldı."},{"n":2,"t":"Bir mu’cize görecek olsalar yüz çevirirler ve \"Süregelen bir büyüdür\" derler."},{"n":3,"t":"Yalanladılar, nefislerinin heveslerine uydular. Halbuki her iş, yerini bulacaktır (Allâh’ın kararına kimse engel olamaz)."},{"n":4,"t":"Andolsun, onlara, (bâtılda kalmalarını) önleyecek (ibret verici olayları anlatan) haberler geldi."},{"n":5,"t":"Bunlar üstün hikmettir! Ama uyarılar fayda vermiyor."},{"n":6,"t":"Öyleyse sen de onlardan yüz çevir; o çağırıcının görülmemiş, tanınmamış bir şeye çağıracağı gün,"},{"n":7,"t":"Gözleri düşkün düşkün (zillet ve dehşet içinde) kabirlerden çıkarlar; tıpkı yayılan çekirgeler gibidirler."},{"n":8,"t":"Boyunlarını, çağırana doğru uzatmış koşarlarken, kâfirler: \"Bu çetin bir gündür!\" derler."},{"n":9,"t":"Onlardan önce Nûh’un kavmi de yalanlamıştı. Kulumuzu yalanladılar ve: \"Cinlenmiştir\" dediler. Ve o(na çeşitli eziyetler yapılarak tebliğden) menedildi."},{"n":10,"t":"Bunun üzerine Rabbine: \"Ben yenik düştüm, yardım et!\" diye yalvardı."},{"n":11,"t":"Biz de boşalan bir su ile göğün kapılarını açtık."},{"n":12,"t":"Yeri kaynaklar halinde fışkırttık, (göğün ve yerin) su(ları) takdir edilmiş bir işin olması için birleşti."},{"n":13,"t":"Nûh’u da tahtalar ve çiviler(le yapılmış gemi) üzerinde taşıdık."},{"n":14,"t":"(Kendisine karşı) Nankörlük edilen (kulumuz)a (bizden) bir mükâfât olmak üzere (gemi), gözlerimizin önünde akıp gidiyordu."},{"n":15,"t":"Bunu bir ibret olarak bıraktık, ibret alan yok mudur?"},{"n":16,"t":"Benim azâbım ve uyarılarım nasılmış (görsünler diye)."},{"n":17,"t":"Andolsun biz, Kur’ân’ı öğüt almak için kolaylaştırdık. Öğüt alan yok mudur?"},{"n":18,"t":"’Âd da yalanladı, ama azâbım ve uyarılarım nasıl oldu?"},{"n":19,"t":"Biz onların üstüne uğursuz mu uğursuz bir günde uğultulu bir kasırga saldık."},{"n":20,"t":"İnsanları sanki köklerinden sökülmüş hurma kütükleri imişler gibi koparıp deviriyordu."},{"n":21,"t":"Benim azâbım ve uyarılarım nasıl oldu?"},{"n":22,"t":"Andolsun biz Kur’ân’ı öğüt almak için kolaylaştırdık. Öğüt alan yok mudur?"},{"n":23,"t":"Semûd da uyarıları yalandı:"},{"n":24,"t":"\"Bizden bir insana mı uyacağız? O takdirde biz apaçık bir sapıklık ve çılgınlık içine düşmüş oluruz\" dediler."},{"n":25,"t":"\"Zikir, aramızdan ona mı bırakıldı? Hayır o, yalancı küstahın biridir!\""},{"n":26,"t":"(Sâlih’e dedik ki): Yarın onlar, yalancı, küstahın kim olduğunu bilecekler."},{"n":27,"t":"Biz onlara, kendilerini sınamak için dişi deveyi göndereceğiz. Hele sen onları gözetle, sabret."},{"n":28,"t":"Onlara, suyun aralarında paylaştırılacağını, (bir gün devenin, bir gün de kendilerinin su içme nöbeti olacağını) haber ver; içme sırası kiminse o gelip suyunu alsın."},{"n":29,"t":"Bir arkadaşlarını çağırdılar, o da bıçağı çekip (deveyi) kesti."},{"n":30,"t":"Ama azâbım ve uyarılarım nasıl oldu?"},{"n":31,"t":"Biz onların üzerine tek sayha (korkunç bir ses) gönderdik; ağılcının topladığı kuru ot gibi kırılıp döküldüler."},{"n":32,"t":"Andolsun Biz Kur’ân’ı öğüt almak için kolaylaştırdık. Öğüt alan yok mudur?"},{"n":33,"t":"Lût’un kavmi de uyarıları yalanladı."},{"n":34,"t":"Biz de üstlerine (taşlar savuran) bir fırtına gönderdik, yalnız Lût âilesini seher vakti kurtardık;"},{"n":35,"t":"Katımızdan bir ni’met olarak. Biz şükredeni böyle mükâfâtlandırırız."},{"n":36,"t":"Lût, onları bizim yakalamamıza karşı uyarmıştı, fakat uyarılara karşı kuşku duydular."},{"n":37,"t":"Onun (güzel delikanlılar şeklinde görünen melek) konuklarından murâd almağa kalkıştılar. Biz de gözlerini siliverdik: \"Haydi azâbımı ve uyarılarımı tadın!\""},{"n":38,"t":"Sabah erken, onları kararlı bir azâb yakaladı."},{"n":39,"t":"\"Azâbımı ve uyarılarımı(n âkıbetini) tadın!\""},{"n":40,"t":"Andolsun biz Kur’an’ı öğüt almak için kolaylaştırdık. Öğüt alan yok mudur?"},{"n":41,"t":"Fir’avn’ın kavmine de uyarılar gelmiştir."},{"n":42,"t":"Bütün âyetlerimizi yalanladılar. Biz de onları, gâlib ve güçlü (pâdişah)ın yakalaması gibi yakaladık."},{"n":43,"t":"Şimdi sizin kâfirleriniz, ötekilerinizden hayırlı mı? Yoksa Kitaplarda sizin için bir berâet (inkârınızdan dolayı size sorumsuzluk) mu var?"},{"n":44,"t":"Yoksa \"Biz muzaffer (yenilmez) bir topluluğuz\" mu diyorlar?"},{"n":45,"t":"O topluluk bozulacak ve geriye dönüp kaçacaklardır."},{"n":46,"t":"Hayır, buluşma zamanları o (uyarıldıkları) sâ’attir. O sâ’at cidden çok feci ve acıdır;"},{"n":47,"t":"Suçlular bir sapıklık ve çılgınlık içindedir."},{"n":48,"t":"O gün yüzükoyun ateşe sürüklenecekler: \"Cehennemin dokunuşunu tadın!\" diye."},{"n":49,"t":"Biz her şeyi bir kadere (bir düzene, ölçüye, plana) göre yarattık."},{"n":50,"t":"Bizim buyruğumuz yalnız bir tektir, göz açıp yumma gibidir."},{"n":51,"t":"Andolsun biz sizin benzerlerinizi hep helâk ettik. Öğüt alan yok mudur?"},{"n":52,"t":"İşledikleri her şey, Kitâplarda mevcuttur."},{"n":53,"t":"Küçük, büyük hepsi satır satır yazılmıştır."},{"n":54,"t":"Korunanlar cennetlerde ırmaklar(ın kenarın)dadırlar."},{"n":55,"t":"Güçlü pâdişâhın huzûrunda doğruluk koltuklarında (memnunluk içinde)dirler."}],[{"n":1,"t":"Çok merhametli (Allâh),"},{"n":2,"t":"Kur’ân’ı öğretti."},{"n":3,"t":"İnsanı yarattı."},{"n":4,"t":"Ona beyânı (konuşup, düşüncelerini açıklamayı) öğretti."},{"n":5,"t":"Güneş de, Ay da bir hesap ile (cereyan etmekte)dir."},{"n":6,"t":"Necm (bitkiler, yıldızlar) ve ağaçlar (Allah’a) secde etmektedirler."},{"n":7,"t":"Göğü yükseltti ve mizânı koydu."},{"n":8,"t":"Tartıda taşkınlık edip dengeyi bozmayın."},{"n":9,"t":"Tartıyı adâletle yapın, terazide eksiklik yapmayın."},{"n":10,"t":"(Allâh) Yeri halk için koydu."},{"n":11,"t":"Onda meyva(lar) ve salkımlı hurmalar var."},{"n":12,"t":"Saplı ve yapraklı dâne(ler) ve hoş kokulu bitkiler var."},{"n":13,"t":"(Ey cinler ve insanlar topluluğu) Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":14,"t":"İnsanı kiremit gibi pişmiş çamurdan yarattı."},{"n":15,"t":"Cin’i de hâlis ateşten yarattı."},{"n":16,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":17,"t":"İki doğunun ve iki batının Rabbidir."},{"n":18,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":19,"t":"İki denizi salıverdi, birbirine kavuşuyorlar,"},{"n":20,"t":"Aralarında bir engel vardır, birbirine geçip karışmıyorlar."},{"n":21,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":22,"t":"İkisinden de inci ve mercan çıkar."},{"n":23,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":24,"t":"Denizde koca dağlar gibi akıp giden kocaman gemiler de O’nundur."},{"n":25,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":26,"t":"(Yer) Üzerinde bulunan her şey yok olacaktır."},{"n":27,"t":"Yalnız Rabbinin celâl ve ikrâm sâhibi yüzü bâki kalacaktır."},{"n":28,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":29,"t":"Göklerde ve yerde bulunanlar (her şeyi) O’ndan isterler. O, her gün (her ân) yeni bir iştedir."},{"n":30,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":31,"t":"Ey iki sekal, sizin için de boş vaktimiz olacak (sizin de hesabınızı göreceğiz)."},{"n":32,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":33,"t":"Ey cinler ve insanlar topluluğu, göklerin ve yerin bucaklarından geçip gitmeğe gücünüz yeterse geçin gidin. Ancak kudretle geçebilirsiniz."},{"n":34,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":35,"t":"İkinizin de üzerine, ateşten yalın alev ve kıpkızıl bir duman (yahut erimiş bakır) gönderilir, başaramazsınız."},{"n":36,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":37,"t":"Gök yarılıp da erimiş yağ gibi kıpkırmızı bir gül olduğu zaman..."},{"n":38,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":39,"t":"O gün ne insana, ne de cin’e günâhından sorulur."},{"n":40,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":41,"t":"Suçlular, simâlarından tanınır, alınlar(ın)dan ve ayaklar(ın)dan tutulur."},{"n":42,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":43,"t":"\"İşte bu, suçluların yalanladığı cehennemdir!\""},{"n":44,"t":"Onunla kaynar su arasında dolaşırlar."},{"n":45,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":46,"t":"Rabbinin divânında dur(up hesap ver)mekten korkan kimseye iki cennet var."},{"n":47,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":48,"t":"İkisinin de çeşitli ağaçları, meyvaları var."},{"n":49,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":50,"t":"İkisinde de akıp giden iki kaynak var."},{"n":51,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":52,"t":"İkisinde de her meyvadan iki çift var."},{"n":53,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":54,"t":"(Orada) Astarları kalın atlastan yataklara yaslanırlar. İki cennetin de devşirmesi yakındır."},{"n":55,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":56,"t":"Onlarda bakışları kısa (yalnız kocalarına bakan) öyle dilberler de var ki, bunlardan önce onları ne insan, ne de cin kanatmamıştır."},{"n":57,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":58,"t":"Sanki onlar yâkut ve mercandırlar."},{"n":59,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":60,"t":"İyiliğin karşılığı, yalnız iyilik değil midir?"},{"n":61,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":62,"t":"Bu ikisinin ötesinde iki cennet daha var."},{"n":63,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":64,"t":"Yemyeşildirler."},{"n":65,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":66,"t":"İkisinde de fışkıran iki kaynak var."},{"n":67,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":68,"t":"İkisinde de meyva, hurma ve nar var."},{"n":69,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":70,"t":"Onlarda da iyi huylu, güzel kadınlar var."},{"n":71,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":72,"t":"Çadırlara kapanmış hûriler."},{"n":73,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":74,"t":"Bunlardan önce onları ne insan, ne de cin kanatmamıştır."},{"n":75,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":76,"t":"(Cennettekiler) Yeşil yastıklara ve hârikulâde güzel işlemeli döşeklere yaslanırlar."},{"n":77,"t":"Şimdi Rabbinizin hangi ni’metlerini yalanlıyorsunuz?"},{"n":78,"t":"Büyüklük ve ikrâm sâhibi Rabbinin adı ne yücedir!"}],[{"n":1,"t":"Olacak vak’a olduğu (kıyâmet koptuğu) zaman,"},{"n":2,"t":"Onun oluşunu yalanlayacak yoktur."},{"n":3,"t":"O alçaltıcı, yükselticidir (yerleri alt üst eder),"},{"n":4,"t":"Yer şiddetlice sarsıldığı,"},{"n":5,"t":"Dağlar serpildikçe serpildiği,"},{"n":6,"t":"Dağılan toz duman haline geldiği"},{"n":7,"t":"Ve sizler üç sınıf olduğunuz zaman;"},{"n":8,"t":"Sağın adamları (amel defterleri sağ tarafından verilenler), ne uğurlulardır onlar!"},{"n":9,"t":"Solun adamları (amel defterleri sol tarafından verilenler), ne uğursuzlardır onlar!"},{"n":10,"t":"Ve o sâbıklar, sâbıklar!"},{"n":11,"t":"İşte, onlardır (Allâh’a) yaklaştırılanlar,"},{"n":12,"t":"Ni’met cennetlerinde."},{"n":13,"t":"Çoğu öncekilerden,"},{"n":14,"t":"Birâzı da sonrakilerden (olan bu insanlar),"},{"n":15,"t":"Altın ve cevahirle işlenmiş tahtlar üzerindedirler."},{"n":16,"t":"Onların üzerinde karşılıklı yaslanırlar."},{"n":17,"t":"Çevrelerinde, ebedi yaşamağa erdirilmiş gençler dolaşır;"},{"n":18,"t":"Akıp giden şarap kaynağından doldurulmuş testiler, ibrikler ve kadehlerle."},{"n":19,"t":"(Bir şarap ki) Ondan ne başları ağrıtılır, ne de akılları giderilir."},{"n":20,"t":"Beğendikleri meyva(lar),"},{"n":21,"t":"Canlarının çektiği kuş et(ler)i,"},{"n":22,"t":"İri gözlü hûriler,"},{"n":23,"t":"Saklı inciler gibi;"},{"n":24,"t":"Yaptıklarına karşılık olarak."},{"n":25,"t":"Orada ne boş bir söz ve ne de günâha sokan bir laf işitirler."},{"n":26,"t":"Duydukları söz, yalnız \"Selâm, selâm\" dır."},{"n":27,"t":"Sağın adamları, nedir o sağın adamları!"},{"n":28,"t":"(Onlar) Dikensiz kirazlar,"},{"n":29,"t":"(Kökünden tepesine kadar) meyva dizili muzlar,"},{"n":30,"t":"Uzamış gölge(ler),"},{"n":31,"t":"Fışkıran sular,"},{"n":32,"t":"Pek çok mevya arasında;"},{"n":33,"t":"Tükenmeyen ve yasaklanmayan!"},{"n":34,"t":"Ve yükseltilmiş döşekler üstündedirler."},{"n":35,"t":"Biz (oradaki) kadınları da yeniden bir güzel inşâ’ etmişiz,"},{"n":36,"t":"Onları bâkireler yapmışızdır."},{"n":37,"t":"Hep yaşıt sevgililer;"},{"n":38,"t":"Sağın adamları için."},{"n":39,"t":"(Bu sağcıların) Bir bölümü öncekilerdendir,"},{"n":40,"t":"Bir bölümü de sonrakilerdendir."},{"n":41,"t":"Solun adamları (amel defterleri, sol tarafından verilenler), nedir o solcular!"},{"n":42,"t":"(Onlar) Delikçiklere işleyen bir ateş ve kaynar su içinde,"},{"n":43,"t":"Kara dumandan bir gölge altında,"},{"n":44,"t":"Ki ne serindir, ne faydalı."},{"n":45,"t":"Çünkü onlar bundan önce varlık içinde şımartılmışlardı."},{"n":46,"t":"Büyük günâhı işlemekte ısrar ediyorlardı."},{"n":47,"t":"Ve diyorlardı ki: \"Biz öldükten, toprak ve kemik yığını olduktan sonra, biz mi bir daha diriltileceğiz?\""},{"n":48,"t":"\"Önceki atalarımız da mı?\""},{"n":49,"t":"De ki: \"Öncekiler de sonrakiler de.\""},{"n":50,"t":"\"Belli bir günün buluşma vakti için mutlaka toplanacaklardır.\""},{"n":51,"t":"Sonra siz de, ey sapık yalanlayıcılar (o zaman toplanacaksınız)."},{"n":52,"t":"(Suçlular) Mutlaka bir Zakkum ağacından yiyecekler,"},{"n":53,"t":"Onunla karınları(nı) dolduracaklar,"},{"n":54,"t":"Üzerine de kaynar su içeceklerdir."},{"n":55,"t":"Susuzluk hastalığına tutulmuş develerin içişi gibi içeceklerdir!"},{"n":56,"t":"İşte cezâ gününde onların ağırlanışı böyledir."},{"n":57,"t":"Biz sizi yarattık; doğrulamanız gerekmez mi?"},{"n":58,"t":"Akıttığınız meniyi gördünüz mü?"},{"n":59,"t":"Siz mi onu yaratıyorsunuz, yoksa yaratıcılar biz miyiz?"},{"n":60,"t":"Aranızda ölümü takdir eden biziz ve bizim önümüze geçilmiş değildir (kimse ölüme engel olamaz)."},{"n":61,"t":"(Size böyle ölümü takdir ettik) Ki sizin yerinize benzerlerinizi getirelim ve sizi, bilmediğiniz bir biçimde yeniden inşâ’ edelim."},{"n":62,"t":"Andolsun, ilk yaratmayı bildiniz, (bunu) düşünüp ibret almanız gerekmez mi?"},{"n":63,"t":"Ektiğinizi gördünüz mü?"},{"n":64,"t":"Siz mi onu bitiyorsunuz, yoksa bitirenler biz miyiz?"},{"n":65,"t":"Dileseydik, onu kuru bir çöp yapardık, sızlanıp dururdunuz:"},{"n":66,"t":"\"Biz borçlandık, (yaptığmız masraflar boşa gitti)!\""},{"n":67,"t":"\"Doğrusu, biz yoksun bırakıldık!\" (derdiniz)."},{"n":68,"t":"İçtiğiniz suya baktınız mı?"},{"n":69,"t":"Siz mi onu buluttan indirdiniz, yoksa indirenler biz miyiz?"},{"n":70,"t":"Dileseydik onu tuzlu yapardık. Şüketmeniz gerekmez mi?"},{"n":71,"t":"(İki dalı birbirine sürterek) Çıkardığınız ateşi gördünüz mü?"},{"n":72,"t":"Onun ağacını siz mi yarattınız, yoksa yaratanlar biz miyiz?"},{"n":73,"t":"Biz onu bir ibret ve çölden gelip geçenlere bir fayda yaptık."},{"n":74,"t":"Öyleyse büyük Rabbinin adını yücelt."},{"n":75,"t":"Yoo, yıldızların yerlerine yemin ederim,"},{"n":76,"t":"Bilirseniz, bu büyük bir yemindir."},{"n":77,"t":"O, elbette değerli bir Kur’ân’dır,"},{"n":78,"t":"Saklı bir Kitâptadır."},{"n":79,"t":"Ki ona temizlerden başkası dokunmaz."},{"n":80,"t":"(O), Âlemlerin Rabbinden indirilmiştir."},{"n":81,"t":"Şimdi siz, bu sözü mü küçümsüyorsunuz?"},{"n":82,"t":"(Kur’ân’dan istifade edeceğiniz yerde) Rızkınızı, yalanlamanızdan ibaret mi kılıyorsunuz (sizin ondan elde ettiğiniz nasib, sadece onu yalanlamanız mıdır)?"},{"n":83,"t":"Ya can boğaza dayandığı zaman?"},{"n":84,"t":"Ki siz de o zaman (can çekişen kimseye) bakıp durursunuz."},{"n":85,"t":"Biz ona sizden daha yakınız, fakat siz görmezsiniz."},{"n":86,"t":"Eğer (öldükten sonra) cezâlandırılmayacaksanız"},{"n":87,"t":"(Bu sözünüzde doğru iseniz) o (çıkmakta olan ca)nı geri döndürsenize!"},{"n":88,"t":"(O can, Allah’a) Yaklaştırılanlardan ise,"},{"n":89,"t":"O’na rahatlık, güzel rızık ve ni’met cenneti var."},{"n":90,"t":"Eğer sağcılardan (amel defteri sağ tarafından verilenlerden) ise,"},{"n":91,"t":"\"(Ey sağcı) Sana sağcılardan selâm var!\""},{"n":92,"t":"Ama yalanlayıcı sapıklardan ise;"},{"n":93,"t":"Kaynar sudan bir ziyafet,"},{"n":94,"t":"Ve cehenneme atılma var."},{"n":95,"t":"Kesin gerçek budur işte."},{"n":96,"t":"Öyleyse büyük Rabbinin adını tesbih et (O’nu, kendisine lâyık olmayan sıfatlardan tenzih eyle)."}],[{"n":1,"t":"Göklerde ve yerde bulunan her şey Allâh’ı tesbih etmiştir. O, azizdir, hakimdir."},{"n":2,"t":"Göklerin ve yerin mülkü O’nundur. Yaşatır, öldürür, O her şeyi yapabilir."},{"n":3,"t":"O, ilktir (kendisinden önce hiçbir varlık yoktur,) sondur (kendisinden sonra hiçbir varlık yoktur. Her şey yok olurken O kalacaktır,) zâhirdir (delilleriyle varlığı gün gibi açıktır,) bâtındır (zâtının hakikati gizlidir, akıllar O’nun özünü idrak edemez,) O, her şeyi bilendir."},{"n":4,"t":"O’dur ki gökleri ve yeri altı günde yarattı, sonra Arş’a oturdu. Yere gireni, ondan çıkanı, gökten ineni, ona çıkanı bilir. Nerede olsanız, O sizinle beraberdir, Allâh yaptıklarınızı görmektedir."},{"n":5,"t":"Göklerin ve yerin mülkü O’nundur. Bütün işler Allâh’a döndürülecektir."},{"n":6,"t":"Geceyi gündüzün içine sokar, gündüzü gecenin içine sokar. O, göğüslerin özünü bilir."},{"n":7,"t":"Allah’a ve Elçisine inanın ve (O’nun) sizi hâkim kıldığı, sizin yönetiminize verdiği şeylerden (Allâh için) harcayın. Sizden, inanan ve (hak rızâsına) harcayanlar için büyük mükâfât vardır."},{"n":8,"t":"Elçi sizi Rabbinize inanmağa (güvenmeğe) çağırdığı ve (bu konuda) sizden sağlam söz almış olduğu halde inananlar iseniz neden Allah’a güvenmiyorsunuz?"},{"n":9,"t":"Sizi karanlıklardan aydınlığa çıkarmak için kuluna açık açık âyetler indiren O’dur. Şüphesiz Allâh, size karşı çok şefkatli, çok merhametlidir."},{"n":10,"t":"Neden siz Allâh yolunda harcamayasınız ki? Göklerin ve yerin mirâsı zaten Allâh’ındır. Elbette içinizden (Mekke’nin) feth(in)den önce (Hak yolunda) harcayan ve savaşan(lar, ötekilerle) bir olmaz. Onların derecesi, sonradan infâk eden ve savaşanlardan daha büyüktür. Bununla beraber Allâh hepsine de (gerek fetihten önce, gerek fetihten sonra infâk eden ve savaşan müslümanlara) en güzel sonucu va’detmiştir. Allâh, yaptıklarınızı haber almaktadır."},{"n":11,"t":"Kimdir o, Allah’a güzel bir borç verecek olan ki, Allâh da onun verdiğini kat kat artırsın ve onun için değerli bir mükâfât da versin?"},{"n":12,"t":"O gün inanan erkekleri ve inanan kadınları; ışıkları, önlerinde ve sağlarında koşar durumda görürsün. (Kendilerine): \"Bugün müjdeniz, altlarından ırmaklar akan, içinde ebedi kalacağınız cennetlerdir.\" (denilir). İşte büyük başarı budur!"},{"n":13,"t":"O gün münâfık erkekler ve münâfık kadınlar (cennete gitmekte olan) mü’minlere derler ki: \"Bize bakın da sizin nurunuzdan yararlanalım.\" Onlara: \"Arkanıza dönün de nur arayın!\" denilir. Aralarına kapılı bir sur çekilir ki, onun içinde rahmet vardır, dış yönünde de azâb."},{"n":14,"t":"(Münâfıklar) onlara seslenirler: \"Biz de sizinle beraber değil miydik?\" (Mü’minler) derler ki: \"Evet ama, siz kendi canlarınıza kötülük ettiniz, beklediniz (hemen tevbe etmediniz) kuşkulandınız, kuruntular sizi aldattı. Allâh’ın emri (ölüm) gelinceye kadar (böyle hareket ettiniz,) o çok aldatıcı (şeytân,) sizi Allâh(ın affı) ile aldattı.\""},{"n":15,"t":"Bugün artık ne sizden, ne de inkâr edenlerden fidye alınmaz, varacağınız yer ateştir. Sizin layığınız odur. Ne kötü gidilecek yerdir orası!"},{"n":16,"t":"İnananlar için hâlâ vakit gelmedi mi ki kalbleri Allâh’ın Zikrine ve inen hakka saygı duysun ve bundan önce kendilerine Kitap verilmiş, sonra üzerlerinden uzun zaman geçmekle kalbleri katılaşmış, çoğu da yoldan çıkmış kimseler gibi olmasınlar?"},{"n":17,"t":"Biliniz ki Allâh yeri, ölümünden sonra diriltir. Belki aklınızı kullanırsınız diye size âyetleri açıkladık."},{"n":18,"t":"Sadaka veren erkekler ve sadaka veren kadınlar ve Allah’a güzel borç verenler, işte onlara, (verdikleri), kat kat yapılır ve onlar için değerli bir mükâfât da vardır."},{"n":19,"t":"Allah’a ve elçilerine inananlar (yok mu) işte Rableri yanında, sıddikler (çok doğru olanlar) ve şehidler onlardır. Onların mükâfâtları ve nurları vardır. İnkâr edenler ve âyetlerimizi yalanlayanlar(a gelince), onlar da cehennem halkıdır."},{"n":20,"t":"Bilin ki dünyâ hayâtı bir oyun, eğlence, süs, kendi aranızda övünme mal ve evlâd çoğaltma yarışıdır. Tıpkı bir yağmura benzer ki; bitirdiği ot, ekincilerin hoşuna gider, sonra kurur, onu sapsarı görürsün, sonra çerçöp olur. Âhirette ise çetin bir azâb; Allah’tan mağfiret ve rızâ vardır. Dünyâ hayâtı aldatıcı bir zevkten başka bir şey değildir."},{"n":21,"t":"(O halde siz), Rabbinizden bir mağfirete ve genişliği, gökle yerin genişliği gibi olup Allah’a ve elçilerine inananlar için hazırlanmış bulunan bir cennete koşun. İşte bu, Allâh’ın dilediğine vereceği lutfudur. Allâh, büyük lutuf sâhibidir."},{"n":22,"t":"Ne yerde ne de kendi canlarınızda meydana gelen hiçbir musibet (âfet, hastalık) yoktur ki biz onu yaratmadan önce, bir Kitâpta (yazılmış ezeli bilgimizde tesbit edilmiş) olmasın. Doğrusu bu, Allâh’a kolaydır."},{"n":23,"t":"(Başınıza gelecek olayları, önceden bir Kitaba yazdık) Ki elinizden çıkana üzülmeyesiniz ve (Allâh’ın) size verdiğiyle sevinip şımarmayasınız. Çünkü Allâh, kendini beğenip övünen kimseleri sevmez."},{"n":24,"t":"Onlar cimrilik edip insanlara da cimriliği emrederler. Kim (Allâh yolunda harcamaktan) yüz çevirirse (bilsin ki) Allâh, zengindir, övgüye lâyıktır."},{"n":25,"t":"Andolsun biz elçilerimizi açık kanıtlarla gönderdik ve onlarla beraber Kitabı ve (adâlet) ölçü(sün)ü indirdik ki insanlar adâleti yerine getirsinler. Ve kendisinde büyük bir kuvvet ve insanlara birçok yararlar bulunan demiri indirdik ki Allâh, kimin (ondan yararlanarak) gaybda (görmediği halde) kendisine ve elçilerine yardım edeceğini bilsin, (ortaya çıkarsın). Şüphesiz Allâh kuvvetlidir, dâimâ üstündür."},{"n":26,"t":"Andolsun, Nûh’u ve İbrâhim’i elçi gönderdik, peygamberliği ve Kitabı bunların zürriyetleri arasına koyduk. Onlardan doğru yolda olanlar da vardır, ama onlardan çoğu yoldan çıkmıştır."},{"n":27,"t":"Sonra bunların peşinden ardarda elçilerimizi gönderdik. Meryem oğlu Îsâ’yı da onların ardına kattık; ona İncil’i verdik ve ona uyanların kalblerine şefkat ve merhamet koyduk. İcâdettikleri ruhbanlığı, biz onlara yazmamıştık, yalnız Allâh’ın rızâsını kazanmak için kendiliklerinden uyguladılar ama ona gereği gibi uymadılar. Biz de onlardan imân edenlere mükâfâtlarını verdik. Fakat onlardan birçoğu da yoldan çıkmıştır."},{"n":28,"t":"Ey inananlar, Allâh’tan korkun, O’nun Elçisine inanın ki size rahmetinden iki pay versin, sizin için ışığında yürüyeceğiniz bir nur yaratsın ve sizi bağışlasın. Allâh çok bağışlayan, çok esirgeyendir."},{"n":29,"t":"Böylece Kitap ehli, kendilerinin, Allâh’ın lutfundan hiçbir şeye mâlik olmadıklarını, bütün lutfun, Allâh’ın elinde olduğunu, onu dilediğine vereceğini bilmezlik etmesinler. Allâh, büyük lutuf sâhibidir."}],[{"n":1,"t":"Allâh, kocası hakkında seninle tartışan ve Allâh’a şikâyette bulunan kadının sözünü işitti. Allâh, ikinizin birbirinizle konuşmanızı işitir. Çünkü Allâh işitendir, görendir."},{"n":2,"t":"Sizden kadınlara zıhar edenler (sen bana, anamın sırtı gibisin diyenler), bilmelidirler ki o kadınlar, onların anaları değillerdir. Onların anaları, ancak kendilerini doğuran kadınlardır. Onlar, çirkin ve yalan olan bir söz söylüyorlar. Bununla beraber Allâh, affedicidir bağışlayıcıdır."},{"n":3,"t":"Kadınlarına zıhar edip sonra söylediklerinden dönenler, karılarıyle temaslarından önce bir köleyi hürriyete kavuşturmalıdırlar. Size öğütlenen budur. Allâh, yaptıklarınızı haber almaktadır."},{"n":4,"t":"Buna imkân bulamayan, temaslarından önce aralıksız olarak iki ay oruç tutmalıdır. Buna da gücü yetmeyen, altmış fakiri doyurmalıdır. Allah’a ve Elçisine inanmanız (onların sözlerini doğrulamanız) için bu hükümler konmuştur. Bunlar, Allâh’ın sınırlarıdır (bu sınırları tanımayan) kâfirler için acı bir azâb vardır."},{"n":5,"t":"Allah’a ve Elçisine karşı gelen (onların koyduğu sınırlardan başka sınırlar koymağa kalkan)lar kendilerinden öncekilerin tepelendikleri gibi tepeleneceklerdir! Biz açık açık âyetler indirdik. kâfirler için küçük düşürücü bir azâb vardır."},{"n":6,"t":"Allâh onların hepsini tekrar dirilteceği gün ne yaptıklarını kendilerine haber verecektir! Allâh on(ların yaptıkları işler)i hep saymış (zaptetmiş)tir. Onlar ise onu unutmuşlardır. Allâh her şeye şâhiddir."},{"n":7,"t":"Göklerde ve yerde olanları, Allâh’ın bildiğini görmedin mi? Üç kişi gizli konuşsa mutlaka dördüncüleri O’dur. Beş kişi gizli konuşsa mutlaka altıncıları O’dur. Bundan az da, bundan çok da olsalar, nerede bulunsalar mutlaka O, onlarla beraberdir. Sonra kıyâmet günü, onlara yaptıklarını haber verir. Çünkü Allâh, her şeyi bilendir."},{"n":8,"t":"Görmedin mi şu adamları ki gizli gizli konuşmaktan menedildikleri halde yine o menedildikleri işe dönüyorlar; günâh, düşmanlık, Elçiye isyân hususunda gizli gizli konuşuyorlar. Sana geldikleri zaman seni, Allâh’ın selâmlamadığı bir tarzda selâmlıyorlar ve kendi içlerinde de: \"Bu dediğimizden ötürü Allâh bize azâb etse ya\" diyorlar. Cehennem onlara yeter. Oraya gireceklerdir, ne kötü gidilecek yerdir orası!"},{"n":9,"t":"Ey inananlar, aranızda gizli konuştuğunuz zaman günâh, düşmanlık ve Elçiye karşı gelme üzerinde konuşmayın; iyilik ve takvâ üzerinde konuşun ve huzûruna toplanacağınız Allah’tan korkun."},{"n":10,"t":"Gizli konuşma (fiskos) şeytândandır. (Şeytân insanları bu yola iletir ki) inananlar üzülsünler. Oysa o, Allâh’ın izni olmadıkça mü’minlere hiçbir zarar veremez. Mü’minler Allâh’a dayansınlar."},{"n":11,"t":"Ey inananlar, size: \"Meclislerde yer açın\" dendiği zaman yer açın ki Allâh da size genişlik versin. Size: \"Kalkın\" dendiği zaman da, kalkın ki Allâh sizden inananları ve kendilerine ilim verilenleri derecelerle yükseltsin. Allâh yaptıklarınızı haber almaktadır."},{"n":12,"t":"Ey inananlar, siz Elçi ile gizli konuşacağınız zaman bu gizli konuşmanızdan önce bir sadaka verin. Bu sizin için daha hayırlı ve daha temizdir. Şâyet (sadaka verecek bir şey) bulamazsınız, Allâh bağışlayandır, esirgeyendir."},{"n":13,"t":"Gizli konuşmanızdan önce sadaka vermenizden korktunuz mu? Çünkü yapmadınız. Allâh da sizi (bundan) affetti. Artık namazı kılın, zekâtı verin, Allah’a ve Elçisine itâ’at edin. Allâh yaptıklarınızı bilmektedir."},{"n":14,"t":"Allâh’ın kendilerine gazab ettiği bir topluluğu dost edinenleri görmedin mi? Onlar ne sizdendirler, ne de onlardan. Bilerek yalan yere yemin ediyorlar."},{"n":15,"t":"Allâh onlar için çetin bir azâb hazırlamıştır. Onlar ne kötü işler yapıyorlar."},{"n":16,"t":"Yeminlerini kalkan yapıp Allâh’ın yoluna engel oldular. Onlar için küçük düşürücü bir azâb vardır."},{"n":17,"t":"Onların ne malları, ne de çocukları kendilerini Allah’a karşı koruyabilir. Onlar ateş halkıdır. Orada sürekli kalacaklardır."},{"n":18,"t":"Allâh onların hepsini tekrar dirilttiği gün, dünyâda size yemin ettikleri gibi O’na da yemin edecekler ve kendilerinin bir şey üzerinde bulunduklarını, (doğru yolda olduklarını) sanacaklardır. İyi bilin ki onlar yalancılardır."},{"n":19,"t":"Şeytân onları kuşatmış (ruhlarına hâkim olmuş) onlara Allâh’ı anmayı unutturmuştur. Onlar şeytânın hizbi (partisi)dir. Muhakkak ki şeytânın hizbi kaybedecektir."},{"n":20,"t":"Allah’a ve Elçisine düşman olanlar, onlar en alçaklar arasındadırlar."},{"n":21,"t":"Allâh: \"Elbette ben ve elçilerim gâlib geleceğiz\" diye yazmıştır. Şüphesiz Allâh güçlüdür, gâliptir."},{"n":22,"t":"Allah’a ve âhiret gününe inanan bir milletin babaları, oğulları, kardeşleri, yahut akrabâları da olsa Allah’a ve Elçisine düşman olanlarla dostluk ettiğini görmezsin. Allâh onların kalblerine iman yazmış ve onları kendinden bir ruh ile (kalb nuru veya Kur’ân ile) desteklemiştir. Onları altlarından ırmaklar akan cennetlere sokacak, orada ebedi kalacaklardır. Allâh onlardan râzı olmuş, onlar da O’ndan râzı olmuşlardır. İşte onlar Allâh’ın hizbi (partisi)dir. Muhakkak ki başarıya ulaşacak olanlar, Allâh’ın hizbidir."}],[{"n":1,"t":"Göklerde ve yerde bulunan herşey Allâh’ı tesbih etmiş (O’nun şânının eksikliklerden uzak, zâtının yüce olduğunu anmışlar)dır. O, üstündür, hüküm ve hikmet sâhibidir."},{"n":2,"t":"Kitap sâhiplerinden inkâr edenleri, hemen ilk haşirde (müslümanların, kaleleri önünde toplanmalarında) yurtlarından O çıkardı. Siz onların çıkacaklarını sanmamıştınız. Onlar da kalelerinin, kendilerini Allah’tan koruyacağını sanmışlardı. Allâh onlara ummadıkları yerden geldi, yüreklerine korku saldı; öyle ki evlerini kendi elleriyle ve mü’minlerin elleriyle harap ediyorlardı. Ey akıl sâhipleri ibret alın."},{"n":3,"t":"Eğer Allâh onlara sürgünü yazmamış olsaydı, mutlaka onlara dünyâda azâb ederdi. Âhirette de onlar için ateş azâbı vardır."},{"n":4,"t":"Bunun sebebi şudur: Onlar Allah’a ve Elçisine karşı geldiler; kim Allah’a karşı gelirse (bilsin ki) Allâh’ın azâbı çetindir."},{"n":5,"t":"Herhangi bir hurma ağacını kesmeniz yahut onu kökleri üzerinde bırakmanız hep Allâh’ın izniyle ve (O’nun) yoldan çıkanları cezâlandırması için olmuştur."},{"n":6,"t":"Allâh’ın, onlardan Elçisine verdiği ganimetlere gelince, siz (onu elde etmek için) onun üzerine ne at ne de deve sürdünüz. Fakat Allâh, elçilerini, dilediği kimselerin üzerine salar (onlara üstün getirir). Allâh her şeyi yapabilir."},{"n":7,"t":"Allâh’ın, o kent halkından, Elçisine verdiği ganimetler, Allah’a, Elçiye, (ona) akrabâ olanlara, yetimlere, yoksullara (yolda kalan) yolcuya âittir. Tâ ki (o mallar), içinizden yalnız zenginler arasında dolaşan bir şey olmasın. Elçi size ne verdiyse onu alın, size neyi yasakladıysa ondan sakının ve Allah’tan korkun. Çünkü Allâh’ın azâbı şiddetlidir."},{"n":8,"t":"(O mallar) Şu göçmen fakirlere âittir ki (onlar) yurtlarından ve mallarından (sürülüp) çıkarılmışlardır; Allâh’ın lutuf ve rızâsını ararlar; Allah’a ve Elçisine yardım ederler. İşte doğru olanlar onlardır."},{"n":9,"t":"Ve onlardan önce o yurda (Medine’ye) yerleşen, imânâ sarılanlar kendilerine göç edip gelenleri severler ve onlara verilen (ganimet)lerden ötürü göğüslerinde bir ihtiyaç (eğilimi) duymazlar. Kendilerinin ihtiyaçları olsa dahi, (göç eden yoksul kardeşlerini) öz canlarına tercih ederler. Kim nefsinin cimriliğinden korunursa, işte onlar başarıya erenlerdir."},{"n":10,"t":"Onlardan sonra gelenler derler ki: \"Rabbimiz, bizi ve bizden önce inanmış olan kardeşlerimizi bağışla, kalblerimizde inananlara karşı bir kin bırakma! Rabbimiz, Sen çok şefkatli çok merhametlisin!\""},{"n":11,"t":"İki yüzlülük edenleri görmedin mi? Kitap ehlinden inkâr eden kardeşlerine: \"Eğer siz (yurdunuzdan) çıkarılırsanız, mutlaka biz de sizinle beraber çıkarız, sizin aleyhinize hiç kimseye itâ’at etmeyiz. Şâyet sizinle savaşılırsa mutlaka size yardım ederiz.\" derler. Allâh, onların yalancı olduklarına şâhidlik eder."},{"n":12,"t":"Andolsun eğer onlar, çıkarılsalar, (bunlar) onlarla beraber çıkmazlar; eğer onlarla savaşılsa onlara yardım etmezler; yardım etseler bile arkalar(ın)a dönüp kaçarlar, sonra kendilerine de yardım edilmez."},{"n":13,"t":"Onların kalblerinde sizin korkunuz, Allâh’ınkinden fazladır. (Allah’tan çok sizden korkarlar). Böyledir, çünkü onlar anlamaz bir topluluktur."},{"n":14,"t":"Onlar toplu olarak sizinle savaşamazlar, ancak müstahkem kaleler içinde, yahut duvarların ardından (savaşırlar). Kendi aralarında şiddetli ayrılık vardır. Sen onları toplu sanırsın, ama kalbleri dağınıktır. Öyledir, çünkü onlar düşünmez bir topluluktur."},{"n":15,"t":"(Onların durumu), kendilerinden az önce, yaptıklarının vebâlini tatmış olan, âhirette de kendileri için acı bir azâb bulunan kimselerin durumu gibidir."},{"n":16,"t":"(Onların durumu) tıpkı şeytânın durumuna benzer ki insana \"İnkâr et\" dedi. (İnsan) inkâr edince de: \"Ben seden uzağım, ben âlemlerin Rabbi Allah’tan korkarım!\" dedi."},{"n":17,"t":"Nihâyet ikisinin de sonu, ebedi olarak ateşte kalmaları oldu. Zâlimlerin cezâsı budur."},{"n":18,"t":"Ey inananlar, Allah’tan korkun ve kişi yarın için ne (yapıp) gönderdiğine baksın. Allah’tan korkun; çünkü Allâh, yaptıklarınızı bilmektedir."},{"n":19,"t":"Şu, Allâh’ı unuttuklarından dolayı (Allâh’ın da) onlara kendi canlarını unutturduğu kimseler gibi olmayın. Onlar, yoldan çıkan insanlardır."},{"n":20,"t":"Ateş halkıyle cennet halkı bir olmaz. Kurtulanlar, ancak cennet halkıdır."},{"n":21,"t":"Biz bu Kur’ân’ı bir dağa indirseydik, Allâh korkusundan onu, baş eğmiş, çatlamış, yarılmış görürdün. Bu misâlleri, düşünmeleri için insanlara anlatıyoruz."},{"n":22,"t":"O, öyle Allah’tır ki O’ndan başka tanrı yoktur. Görülmeyeni ve görüleni bilir. O çok esirgeyen, çok acıyandır."},{"n":23,"t":"O, öyle Allah’tır ki O’ndan başka tanrı yoktur. Pâdişâhtır, mukaddestir, selâm (esenlik veren) mü’min (güvenlik veren), müheymin (kollayıp koruyan), aziz (üstün, gâlib), cebbâr (istediğini zorla yaptıran), mütekebbir (çok ulu)dur! Allâh (puta tapanların) ortak koşmalarından yücedir."},{"n":24,"t":"O, yaratan, var eden, (varlığa getirdiklerine) biçim veren Allah’tır. En güzel isimler O’nundur. Göklerde ve yerde bulunanların hepsi O’nun ululuğunu anarlar. O, aziz (mutlak gâlip), hakim (hükümdar, herşeyi hikmetle yapan)dır."}],[{"n":1,"t":"Ey inananlar! Benim de düşmanım, sizin de düşmanınız olan kimseleri dost edinmeyin. Onlar size gelen gerçeği inkâr ettikleri, Rabbiniz Allah’a inandığınızdan dolayı Elçiyi ve sizi (yurdunuzdan) çıkardıkları halde siz onlara sevgi iletiyorsunuz. Benim yolumda cihâd etmek ve benim rızâmı kazanmak için (yurdunuzdan) çıktığınız halde içinizde onlara sevgi (mi) gizliyorsunuz? Oysa ben sizin gizlediğiniz ve açığa vurduğunuz her şeyi bilirim. Sizden kim bunu yaparsa doğru yoldan sapmış olur."},{"n":2,"t":"Onlar sizi ele geçirseler, size düşman olurlar, size ellerini, dillerini kötülükle uzatırlar ve inkâr etmenizi isterler."},{"n":3,"t":"Kıyâmet günü akrabânız ve çocuklarınız size fayda vermez. (Allâh) Aranızı ayırır. Allâh yaptıklarınızı görmektedir."},{"n":4,"t":"İbrâhim’de ve onunla beraber bulunanlarda sizin için güzel bir örnek vardır; onlar kavimlerine \"Biz sizden ve sizin Allah’tan başka taptıklarınızdan uzağız. Sizi(n taptıklarınızı) tanımıyoruz. Siz, bir tek Allah’a inanıncaya kadar sizinle bizim aramızda sürekli bir düşmanlık ve nefret belirmiştir\" demişlerdi. Yalnız İbrâhim’in babasına: \"Senin için mağfiret dileyeceğim, fakat Allah’tan gelecek bir şeyi senden savamam\" demesi hariç. \"Rabbimiz, sana dayandık, sana yöneldik. Dönüş(ümüz) sanadır!\""},{"n":5,"t":"\"Rabbimiz, bizi inkâr edenler için bir sınav yapma (bizi onların baskı ve işkencesi altına düşürme), bizi bağışla. Rabbimiz, yegâne gâlib, hüküm ve hikmet sâhibi, ancak Sensin, Sen!\""},{"n":6,"t":"Andolsun, onlarda sizin için, Allâh’ı ve \"Son Günü\" arzu edenler için güzel bir örnek vardır. Kim yüz çevirirse (bilsin ki) Allâh işte zengin, övgüye lâyık olan O’dur."},{"n":7,"t":"Belki de Allâh sizinle, onlardan düşman olduklarınız arasına bir sevgi koyar. Allâh kâdirdir. Allâh çok bağışlayan, çok esirgeyendir."},{"n":8,"t":"Allâh sizi, din hakkında sizinle savaşmayan ve sizi yurtlarınızdan çıkarmayan kimselere iyilik etmekten, onlara adâletli davranmaktan men’etmez. Çünkü Allâh, adâlet yapanları sever."},{"n":9,"t":"Allâh sizi, ancak sizinle din hakkında savaşan, sizi yurtlarınızdan çıkaran ve çıkarılmanıza yardım eden kimselerle dost olmaktan men eder. Kim onlarla dost olursa, işte zâlimler onlardır."},{"n":10,"t":"Ey inananlar! Mü’min kadınlar göç ederek size geldiği zaman, onları imtihan edin. Allâh onların imanlarını daha iyi bilir. Eğer onların (gerçekten) inanmış olduklarını anlarsanız, onları kâfirlere geri döndürmeyin. Ne bu(kadı)nlar onlara helâldir ne de onlar bunlara helâl olurlar. Onların (bu kadınlara) harcadıkları (mehirleri)ni onlara verin. Ücretlerini kendilerine verdiğiniz takdirde bu(kadı)nlarla evlenmenizde sizin için bir günâh yoktur. Kâfir kadınların ismetlerini (nikâh bağlarını) tutmayın (onları salıverin ve kâfirlere katılan kadınlara) harcadığınız (mehri) isteyin. Onlar da (size katılan kadınlarına) harcadıklarını istesinler. Bu size Allâh’ın hükmüdür. Aranızda (böyle) hükmediyor. Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":11,"t":"Eğer eşleriniz(e sarfettiğiniz mehirler)den herhangi bir şey kâfirlere gider de, sonra (onlardan da size kaçan kadınlar çıkar ve bu kez mehir ödeme) sıra(sı) size gelirse eşleri giden (mü’minlere) harcadıklarının mislini verin. İnandığınız Allah’a karşı gelmekten sakının."},{"n":12,"t":"Ey peygamber, inanmış kadınlar sana gelip Allah’a hiçbir şeyi ortak koşmamaları, hırsızlık etmemeleri, zinâ etmemeleri, çocuklarını öldürmemeleri, elleriyle ayakları arasında bir iftirâ uydurup getirmemeleri, iyi bir işte sana karşı gelmemeleri hususunda sana bi’at ederlerse onların bi’atlerini ve onlar için Allah’tan mağfiret dile! Şüphesiz Allâh, çok bağışlayan, çok esirgeyendir."},{"n":13,"t":"Ey inananlar, Allâh’ın kendilerine gazabettiği; kâfirlerin mezarlık halkından umudu kestiği gibi âhiretten umudu kesmiş olan bir topluluk ile dostluk etmeyin!"}],[{"n":1,"t":"Göklerde ve yerde bulunanların hepsi Allâh’ı tesbih etmiştir. O üstündür, hüküm ve hikmet sâhibidir."},{"n":2,"t":"Ey inananlar niçin yapmayacağınız şeyi söylüyorsunuz?"},{"n":3,"t":"Yapmayacağınız şeyi söylemek, Allâh katında en sevilmeyen bir şeydir."},{"n":4,"t":"Allâh, kendi yolunda kenetlenmiş binâlar gibi saf bağlayarak çarpışanları sever."},{"n":5,"t":"Bir zaman Mûsâ, kavmine: \"Ey kavmim, benim, Allâh’ın size gönderdiği elçisi olduğumu bildiğiniz halde niçin beni incitiyorsunuz?\" demişti. Onlar eğrilince Allâh da kalblerini eğriltti. Allâh, yoldan çıkanları doğru yola iletmez."},{"n":6,"t":"Meryem oğlu Îsâ da: \"Ey İsrâil oğulları, ben size Allâh’ın elçisiyim, benden önce gelen Tevrât’ı doğrulayıcı ve benden sonra gelecek, Ahmed adında bir elçiyi müjdeleyici olarak gönderildim\" demişti. Fakat (Îsâ’nın müjdelediği elçi) onlara apaçık deliller getirince: \"Bu, apaçık bir büyüdür\" dediler."},{"n":7,"t":"İslâma çağırıldığı halde, Allâh’ın üstüne yalan atandan daha zâlim kim olabilir? Allâh zâlimler topluluğunu doğru yola iletmez."},{"n":8,"t":"Ağızlarıyle Allâh’ın nurunu söndürmek istiyorlar. Oysa kâfirler hoşlanmasa da Allâh, nurunu tamamlayacaktır."},{"n":9,"t":"O, Elçisini, hidâyet ve hak din ile gönderdi ki müşrikler hoşlanmasa da onu, bütün dinlere üstün getirsin."},{"n":10,"t":"Ey inananlar, size, sizi acı azâbdan kurtaracak bir ticaret göstereyim mi?"},{"n":11,"t":"Allah’a ve Elçisine inanırsınız, Allah yolunda mallarınızla ve canlarınızla cihâd edersiniz. İşte bilirseniz, sizin için en iyisi budur."},{"n":12,"t":"(Böyle yapınız ki Allâh) sizin günâhlarınızı bağışlasın ve sizi altlarından ırmaklar akan cennetlere ve durulmağa değer bahçeler içinde güzel konutlara koysun. İşte büyük başarı budur."},{"n":13,"t":"Seveceğiniz bir şey daha var: Allah’tan bir zafer ve yakın bir fetih... Mü’minleri müjdele."},{"n":14,"t":"Ey inananlar, Allâh’ın yardımcıları olun! Nitekim Meryem oğlu Îsâ da havârilere: \"Allâh yolunda benim yardımcılarım kimdir?\" demişti. Havâriler: \"Allâh (yolun)un yardımcıları biziz\" dediler. İsrâil oğullarından bir zümre inandı, bir zümre inkâr etti. Biz de inananları, düşmanlarına karşı destekledik, onlar üstün geldiler."}],[{"n":1,"t":"Göklerde ve yerde bulunanların hepsi pâdişâh, mukaddes, aziz, hakim olan Allâh’ı tesbih etmektedir."},{"n":2,"t":"O’dur ki ümmiler içinde, kendilerinden olan ve onlara Allâh’ın âyetlerini okuyan, onları yücelten, onlara Kitabı ve hikmeti öğreten bir elçi gönderdi. Oysa onlar, önceden, açık bir sapıklık içinde idiler."},{"n":3,"t":"(O Elçiyi) yine onlardan olup henüz kendilerine katılmamış bulunan başka kimselere de (gönderdi). O azizdir, hakimdir."},{"n":4,"t":"Bu, Allâh’ın, dilediğine vereceği lutfudur. Allâh, büyük lutuf sâhibidir."},{"n":5,"t":"Kendilerine Tevrât yükletilip de sonra onu taşımayan(onun buyruklarını tutmayan)ların durumu, Kitaplar taşıyan eşeğin durumu gibidir. Allâh’ın âyetlerini yalanlayanların durumu ne kötüdür. Allâh zâlimler topluluğunu doğru yola iletmez."},{"n":6,"t":"De ki: \"Ey yahûdi olanlar, eğer insanlar arasında yalnız sizin, Allâh’ın dostları olduğunuzu sanıyorsanız, (bu inancınızda) samimi iseniz ölümü temenni edin.\""},{"n":7,"t":"Ama onlar, ellerinin (yapıp) öne sürdüğü (işler) yüzünden asla ölümü temenni etmezler. Allâh zâlimleri bilir."},{"n":8,"t":"De ki: \"Sizin, kendisinden kaçtığınız ölüm, sizi mutlaka bulacaktır. Sonra görünmeyeni ve görüneni Bilen’e döndürüleceksiniz, O size yaptıklarınızı haber verecektir."},{"n":9,"t":"Ey inananlar, Cuma günü namaz için çağrıldığı(nız) zaman, Allâh’ı anmağa koşun, alışverişi bırakın. Eğer bilirseniz bu, sizin için daha hayırlıdır."},{"n":10,"t":"Namaz kılındıktan sonra yeryüzüne dağılın ve Allâh’ın lutfundan (nasibinizi) arayın. Allâh’ı çok anın ki başarıya eresiniz."},{"n":11,"t":"Bir ticaret veya eğlence gördükleri zaman hep dağılıp ona giderler ve seni ayakta bırakırlar. De ki: \"Allâh’ın yanında bulunan, eğlenceden de ticaretten de hayırlıdır. Allâh, rızık verenlerin en hayırlısıdır.\""}],[{"n":1,"t":"Münâfıklar sana geldikleri zaman: \"Senin muhakkak Allâh’ın elçisi olduğuna tanıklık ederiz\" derler. Senin muhakkak kendisinin elçisi olduğunu Allâh bilir ve Allâh münafıkların yalancı olduklarına tanıklık eder."},{"n":2,"t":"Yeminlerini kalkan yapıp Allâh’ın yoluna engel oldular. Onların yaptıkları ne kötüdür!"},{"n":3,"t":"(Bu davranışlarının) Sebebi şudur: İnandılar, sonra inkâr ettiler, bu yüzden kalblerinin üzeri mühürlendi, artık onlar anlamazlar."},{"n":4,"t":"Onları gördüğün zaman cisimleri hoşuna gider (çünkü gösterişli adamlardır,) konuşsalar sözlerini dinlersin, onlar dayatılmış odunlar gibidirler. Her bağırtıyı kendi aleyhlerinde sanırlar. Onlar düşmandır, onlardan sakın. Allâh onları kahretsin, nasıl da (haktan) döndürülüyorlar?"},{"n":5,"t":"Onlara: \"Gelin, Allâh’ın Elçisi sizin için mağfiret dilesin\" dendiği zaman başlarını çevirirler ve onların, büyüklük taslayarak yüz çevirdiklerini görürsün."},{"n":6,"t":"Onlar için mağfiret dilesen de, mağfiret dilemesen de onlar için birdir. Allâh onları bağışlamayacaktır. Çünkü Allâh, yoldan çıkan topluluğu yola iletmez."},{"n":7,"t":"Onlar öyle kimselerdir ki: \"Allâh’ın Elçisinin yanında bulunanları beslemeyin ki dağılıp gitsinler\" diyorlar. Oysa göklerin ve yerin hazineleri Allâh’ındır, fakat münâfıklar anlamazlar."},{"n":8,"t":"Diyorlar ki: \"Andolsun, eğer Medine’ye dönersek üstün olan, alçak olanı oradan mutlaka çıkaracaktır.\" Üstünlük, ancak Allâh’a, Elçisine ve mü’minlere mahsustur. Fakat münâfıklar bilmezler."},{"n":9,"t":"Ey inananlar, mallarınız ve çocuklarınız sizi Allâh’ı anmaktan alıkoymasın. Kim bunu yaparsa işte onlar ziyana uğrayanlardır."},{"n":10,"t":"Biriniz kendisine ölüm gelip de: \"Rabbim beni yakın bir süreye kadar erteleseydin de sadaka verip iyilerden olsaydım!\" demeden önce, size verdiğimiz rızıktan sadaka verin."},{"n":11,"t":"Allâh, süresi dolan hiçbir canı ertelemez. Allâh, yaptıklarınızı haber alandır."}],[{"n":1,"t":"Göklerde ve yerde bulunanların hepsi Allâh’ın şânının yüceliğini anmaktadır. Mülk O’nundur, hamd O’nundur. O, herşeye kâdirdir."},{"n":2,"t":"Sizi yaratan O’dur. Kiminiz kâfirdir, kiminiz mü’min. Allâh yaptıklarınızı görmektedir."},{"n":3,"t":"Gökleri ve yeri hak (hikmet) ile yarattı, sizi biçimlendirdi, biçimlerinizi güzel yaptı. Dönüş O’nadır."},{"n":4,"t":"Göklerde ve yerde bulunanları bilir, gizlediğiniz ve açığa vurduğunuz şeyleri de bilir. Allâh, göğüslerin özünü bilendir."},{"n":5,"t":"Daha önce inkâr etmiş olanların haberi size gelmedi mi? (Onlar), işlerinin vebâlini taddılar ve onlar için acı bir azâb da vardır."},{"n":6,"t":"Çünkü onlara elçileri, açık deliller getirirlerdi, fakat onlar, \"Bir insan mı bize yol gösterecek\" deyip inkâr ettiler ve yüz çevirdiler. Allâh da (hiçbir şeye) muhtaç olmadığını gösterdi. Allâh zengindir, övülmüştür."},{"n":7,"t":"İnkâr edenler, kesinlikle diriltilmeyeceklerini sandılar. De ki: \"Hayır, Rabbim hakkı için mutlaka diriltileceksiniz, sonra yaptıklarınız size haber verilecektir. Bu, Allah’a göre kolaydır.\""},{"n":8,"t":"Artık Allah’a, Elçisine ve indirdiğimiz ışığa inanın. Allâh, yaptıklarınızı haber almaktadır."},{"n":9,"t":"Toplantı günü için sizi topladığı gün, işte o aldanma günüdür. Kim Allah’a inanır ve yararlı iş yaparsa (Allâh) onun kötülüklerini örter ve onu, altlarından ırmaklar akan cennetlere sokar, orada ebedi kalırlar. İşte büyük başarı budur."},{"n":10,"t":"Nankörlük eden ve âyetlerimizi yalanlayanlar ise ateş halkıdır. Orada sürekli kalacaklardır. Ne kötü gidilecek yerdir orası!"},{"n":11,"t":"Başa gelen her musibet Allâh’ın izniyledir. Kim Allah’a inanırsa (Allâh) onun kalbini doğru (düşünce)ye iletir. Allâh, herşeyi bilendir."},{"n":12,"t":"Allah’a itâ’at edin, Elçiye itâ’at edin. Eğer dönerseniz (bilin ki) Elçimize düşen, açıkça duyurmaktır."},{"n":13,"t":"Allâh ki O’ndan başka tanrı yoktur. Mü’minler Allah’a dayansınlar."},{"n":14,"t":"Ey inananlar, eşlerinizden ve çocuklarınızdan bazıları size düşmandır. Onlardan sakının. Ama affeder, hoşgörür, bağışlarsanız muhakkak ki Allâh da bağışlayandır, esirgeyendir (O da sizi bağışlar)."},{"n":15,"t":"Mallarınız ve evlâdlarınız bir fitne (sınav)dır, (Allâh, onlarla sizi imtihan etmektedir). Allâh ise, işte büyük ödül O’nun yanındadır."},{"n":16,"t":"Öyle ise gücünüz yettiği kadar Allâh’tan korkun, (O’nun öğütlerini) dinleyin, (O’na) itâ’at edin ve kendi iyiliğinize olarak (mallarınızı Allâh uğrunda) harcayın. Kim nefsinin cimriliğinden korunursa işte onlar, başarıya erenlerdir."},{"n":17,"t":"Eğer Allâh’a güzel borç verirseniz, Allâh onu sizin için kat kat yapar ve sizi bağışlar. Allâh karşılık verendir, halimdir (hoşgörülüdür)."},{"n":18,"t":"Görünmeyeni ve görüneni bilendir. (O’na hiçbir şey gizli kalmaz, O,) Azizdir, hakimdir (üstündür, hüküm ve hikmet sâhibidir)."}],[{"n":1,"t":"Ey peygamber! Kadınları boşa(mak iste)diğiniz zaman onları iddetleri içinde (âdetten temiz oldukları sırada) boşayın ve iddeti sayın (üç defa âdet görüp temizlenmelerini hesabedin). Rabbiniz Allah’tan korkun (bekleme süresi içinde) onları evlerinden çıkarmayın. Kendileri de çıkmasınlar. Ancak apaçık bir edepsizlik yapmaları durumu, bu hükmün dışındadır (o zaman evden çıkarabilirsiniz). Bunlar Allâh’ın sınırlarıdır. Kim Allâh’ın sınırlarını geçerse, kendisine yazık etmiş olur. Bilmezsin belki Allâh, bundan sonra (iddet süresi içinde) yeni bir iş ortaya çıkarır (gönülleri uzlaştırıp birleşme ortamı yaratır)."},{"n":2,"t":"Sürelerinin sonuna vardıklarında ya onları güzelce (yanınızda) tutun, yahut, güzellikle onlardan ayrılın. (Eşinizi yanınızda tutmak veya ondan ayrılmak için) içinizden adâletli iki kişiyi de şâhid tutun. Şâhidliği Allâh için yapın. İşte içinizden Allah’a ve Son Güne inanan kimseye öğütlenen budur. Kim Allah(ın yasakların)dan sakınırsa (Allâh) ona bir çıkış (yolu) yaratır."},{"n":3,"t":"Ve onu ummadığı yerden rızıklandırır. Kim Allah’a dayanırsa O, ona yeter. Allâh, buyruğunu yerine getirendir. Allâh herşey için bir ölçü koymuştur."},{"n":4,"t":"(Yaşlılıklarından ötürü) Âdetten kesilen kadınlarınızın (bekleme süresinden) şüphe ederseniz, (bilin ki) onların bekleme süresi üç aydır. Henüz âdet görmeyenler de böyledir. Gebe olanların bekleme süresi, yüklerini bırakmalarına kadardır. Kim Allah’tan korkarsa (Allâh) ona işinde bir kolaylık yaratır."},{"n":5,"t":"Bu, Allah’ın size indirdiği buyruğudur. Kim Allah’tan korkarsa (Allâh) onun kötülüklerini örter ve onun mükâfâtını büyütür."},{"n":6,"t":"(Boşadığınız) O kadınları, gücünüz ölçüsünde oturduğunuz yerin bir bölümünde oturtun ve onları sıkıştır(ıp evden çıkmağa zorla)mak için kendilerine zarar vermeğe kalkışmayın. Şâyet gebe iseler, yüklerini bırakıncaya kadar onların geçimini sağlayın. Sonra sizin için (çocuğunuzu) emzirirlerse onlara ücretlerini verin ve aranızda güzellikle konuşup anlaşın. Eğer (anlaşmakta) güçlük çekerseniz (o zaman) çocuğu, başka bir kadın emzirecektir."},{"n":7,"t":"Eli geniş olan, genişliğine göre nafaka versin. Rızkı kısılmış bulunan da Allâh’ın kendisine verdiğinden versin. Allâh, bir kişiye ne vermişse ancak onu yükler, (kimseye gücünün üstünde bir şey yüklemez). Allâh, bir güçlükten sonra bir kolaylık yaratacaktır."},{"n":8,"t":"Nice kent var ki Rabbinin ve elçilerinin buyruğuna baş kaldırdı, biz de onu çetin bir hesaba çektik ve ona görülmemiş biçimde azâbettik."},{"n":9,"t":"İşinin vebâlini taddı. İşinin sonucu da tüm bir ziyan idi."},{"n":10,"t":"Allâh o(insa)nlara şiddetli bir azâb da hazırlamıştır. Ey inanmış olan, sağduyu sâhipleri, Allah’tan korkun, Allâh size bir uyarı indirdi."},{"n":11,"t":"Yani size Allâh’ın açık açık âyetlerini okuyan bir elçi (gönderdi) ki, inanıp yararlı işler yapanları, karanlıklardan aydınlığa çıkarsın. Kim Allah’a inanır ve yararlı iş yaparsa (Allâh) onu, altlarından ırmaklar akan, içinde ebedi kalacakları cennetlere sokar. Allâh ona gerçekten güzel rızık vermiştir."},{"n":12,"t":"Allâh O’dur ki yedi göğü ve yerden de onların benzerini yarattı. (Allâh’ın) Buyruğu, bunlar arasında iner ki Allâh’ın herşeye kâdir olduğunu ve Allâh’ın bilgice her şeyi kuşatmış bulunduğunu bilesiniz."}],[{"n":1,"t":"Ey peygamber! Niçin, Allâh’ın sana helâl kıldığı şeyi, eşlerinin, hatırı için harâm kılıyorsun? Allâh bağışlayandır, esirgeyendir."},{"n":2,"t":"Allâh size, yeminlerinizi (keffâretle) çözmeyi meşrû’ kılmıştır. Allâh sizin sâhibinizdir. O bilendir, hüküm ve hikmet sâhibidir."},{"n":3,"t":"Peygamber, eşlerinden birine gizli bir söz söylemişti. Fakat eşi, o sözü (başkasına) haber verip, Allâh da peygamberi, eşinin bu davranışına muttali kılınca (Peygamber, eşine) o(söylediği)nin bir kısmını bildirmiş (şunları şunları filana söyledin demiş), bir kısmından da vazgeçmişti. (Peygamber) Bunu eşine haber verince eşi: \"Bunu sana kim söyledi?\" dedi (Peygamber): \"(Herşeyi) Bilen, haber alan (Allâh) bana söyledi\" dedi."},{"n":4,"t":"Eğer ikiniz, kalblerinizin sapmış olmasından dolayı Allah’a tevbe ederseniz (ne a’lâ). Ve eğer peygambere karşı birbirinize arka olursanız (bilin ki) onun koruyucusu ve yardımcısı Allâh, Cibril ve mü’minlerin iyileridir. Ayrıca melekler de ona arkadır."},{"n":5,"t":"O sizi boşarsa belki de Rabbi ona, sizden daha hayırlı, kendisini Allah’a teslim eden, inanan, gönülden itâ’at eden, tevbe eden, ibâdet eden seyâhat eden dul ve bâkire eşler verir."},{"n":6,"t":"Ey inananlar, kendinizi ve âilenizi bir ateşten koruyun ki onun yakıtı insanlar ve taşlardır. Onun başında gâyet katı, şiddetli, Allâh’ın kendilerine buyurduğuna karşı gelmeyen ve emredildikleri şeyi yapan melekler vardır."},{"n":7,"t":"(Oraya girenlere derler ki:) \"Ey nankörlük edenler, bugün özür dilemeyin. Çünkü siz, ancak yaptığınız şeylerle cezâlandırılıyorsunuz.!\""},{"n":8,"t":"Ey inananlar, Allah’a yürekten tevbe edin. Umulur ki Rabbiniz sizin kötülüklerinizi örter; Allâh’ın, peygamberi ve onunla beraber inanmış olanları utandırmayacağı günde, sizi altlarından ırmaklar akan cennetlere sokar. (O gün) onların nuru, önlerinden ve sağ yanlarından koşar. Derler ki: \"Rabbimiz, nurumuzu tamamla, bizi bağışla. Doğrusu, senin herşeye gücün yeter!\""},{"n":9,"t":"Ey Peygamber! kâfirlerle ve iki yüzlülerle uğraş, onlara karşı katı davran. Onların varacağı yer cehennemdir. Ne kötü varılacak yerdir o!"},{"n":10,"t":"Allâh inkâr edenler hakkında Nûh’un karısı ile Lût’un karısını misâl verdi. Bu ikisi, kullarımızdan iki Sâlih kulun (nikâhı) altında idiler, onlara hiyânet ettiler. Kocaları Allah’tan (gelen) hiçbir şeyi onlardan savamadı. (Onlara): \"Haydi, girenlerle beraber siz de ateşe girin\" denildi."},{"n":11,"t":"Allâh inananlar hakkında da Fir’avn’ın karısını misâl verdi. O şöyle demişti: \"Rabbim, bana katında, cennetin içinde bir ev yap, beni Fir’avn’dan ve onun (kötü) işinden kurtar. Ve beni şu zâlimler topluluğundan kurtar!\""},{"n":12,"t":"(Yine Allâh) İmran’ın kızı Meryem’i de (misâl verdi). O ırzını korumuştu, biz de on(un rahmin)e ruhumuzdan üflemiştik. O, Rabbinin kelimelerini ve Kitaplarını doğrulamış ve gönülden itâ’at edenlerden olmuştu."}],[{"n":1,"t":"Mülk (mutlak hükümranlık ve yönetim), elinde bulunan yüce Allâh, kutludur. O’nun herşeye gücü yeter."},{"n":2,"t":"O, hanginizin daha güzel iş yapacağınızı denemek için ölümü ve hayâtı yarattı. O, üstündür, bağışlayandır."},{"n":3,"t":"O, yedi göğü, birbiri üzerinde tabaka, tabaka yarattı, Rahmân’ın yaratmasında bir aykırılık, uygunsuzluk görmezsin. Gözü(nü) döndür de bak, bir bozukluk görüyor musun?"},{"n":4,"t":"Sonra gözü(nü) iki kez daha döndür (bak). Göz (aradığı bozukluğu bulmaktan) umudu keserek hor ve bitkin bir halde sana döner."},{"n":5,"t":"Andolsun biz, en yakın göğü lambalarla donattık ve onları, şeytânlar için taşlamalar yaptık. Ve o(şeytâ)nlara da çılgın ateş azâbını hazırladık."},{"n":6,"t":"Rablerine nânkörlük edenler için cehennem azâbı vardır. Ne kötü gidilecek sonuçtur o!"},{"n":7,"t":"Oraya atıldıkları zaman onun öfkeli homurtusunu işitirler, kaynıyor:"},{"n":8,"t":"Neredeyse öfkeden çatlayacak. Her topluluk onun içine atıldıkça onun bekçileri, onlara: \"Size bir uyarıcı gelmedi mi?\" diye sordu(lar)."},{"n":9,"t":"Dediler: \"Evet, bize uyarıcı geldi ama biz yalanladık ve: ’Allâh hiçbir şey indirmedi, siz ancak büyük bir sapıklık içindesiniz’ dedik.\""},{"n":10,"t":"Ve dediler ki: \"Eğer söz dinleseydik, yahut düşünseydik, şu çılgın ateşin halkı arasında bulunmazdık!\""},{"n":11,"t":"Günâhlarını itirâf ettiler. O çılgın ateş halkına (Allâh’ın acımasından) uzak olup ezilmek yaraşır!"},{"n":12,"t":"Fakat gizlide Rablerine saygılı olanlara gelince, onlar için bağış(lama) ve büyük mükâfât vardır."},{"n":13,"t":"Sözünüzü ister gizleyin, ister onu açığa vurun (farketmez) çünkü O, göğüslerin özünü bilir."},{"n":14,"t":"Yaratan bilmez mi? O latiftir (bilgisi herşeyin içine geçen, her şeyi) haber alandır."},{"n":15,"t":"O size yeri boyun eğer yaptı. Haydi onun omuzlarında yürüyün ve Allâh’ın rızkından yeyin. (Sonunda) Dönüş O’nadır (size verdiği ni’metlere karşı şükredip etmediğinizi sizden soracak, sizi hesaba çekecektir)."},{"n":16,"t":"Gökte olanın, sizi yere batırmayacağından emin misiniz? O zaman yer, birden sallanmağa başlar (ve siz yerin dibine geçersiniz)."},{"n":17,"t":"Yoksa siz, gökte olanın, üzerine taş yağdıran (bir fırtına) göndermeyeceğinden emin misiniz? (O zaman) tehdidimin nasıl olduğunu bileceksiniz."},{"n":18,"t":"Andolsun, onlardan öncekiler de yalanladılar. Ama benim (onların yaptıklarını) inkârım nasıl oldu?"},{"n":19,"t":"Üstlerinde (kanatlarını) açıp yumarak uçan kuşları görmüyorlar mı? Onları (havada) Rahmân’dan başkası tutmuyor. Doğrusu O, herşeyi görmektedir."},{"n":20,"t":"Yahut Rahmân’dan başka size yardım ed(ip sizi O’nun azâbından kurtar)acak askeriniz kimdir? Kâfirler derin bir gaflet ve aldanma içindedirler."},{"n":21,"t":"Yahut Allâh, rızkını tutacak olursa size rızık verecek kimdir? Doğrusu onlar, azgınlık ve nefret içinde direnmektedirler."},{"n":22,"t":"Şimdi, yüzüstü kapanarak yürüyen mi doğru gider, yoksa yolda düzgün yürüyen mi?"},{"n":23,"t":"De ki: \"Sizi yaratan, size işitme (duyusu), gözler ve gönüller veren O’dur. Ne kadar az şükrediyorsunuz?"},{"n":24,"t":"De ki: \"Sizi yerde üreten O’dur ve toplanıp O’na götürüleceksiniz.\""},{"n":25,"t":"\"Doğru (söylüyor) iseniz bu tehdid (ettiğiniz azâb) ne zaman gelecek?\" diyorlar."},{"n":26,"t":"De ki: (Ona âit) Bilgi, Allâh’ın yanındadır. Ben ancak apaçık bir uyarıcıyım.\""},{"n":27,"t":"Onu yakın görünce inkâr edenlerin yüzleri kötüleşti. Ve: \"İşte çağırıp durduğunuz şey budur!\" dendi."},{"n":28,"t":"De ki: \"Baksanıza, eğer Allâh beni ve benimle beraber olanları öldürse de yahut bize acısa da (fark etmez,) kâfirleri acı azâbdan kim kurtarabilir?\""},{"n":29,"t":"De ki: \"O, çok merhametlidir. O’na inanmış, O’na dayanmışızdır. Yakında kimin apaçık bir sapıklık içinde olduğunu bileceksiniz.\""},{"n":30,"t":"De ki: \"Baksanıza, eğer suyunuz çekilse, size kim bir akar su getirebilir?\""}],[{"n":1,"t":"Nûn. Kaleme ve (kalemle) yazdıklarına andolsun."},{"n":2,"t":"Sen, Rabbinin ni’metiyle cinlenmiş (deli) değilsin."},{"n":3,"t":"Senin için kesintisiz bir mükâfât vardır."},{"n":4,"t":"Ve sen, büyük bir ahlâk üzerindesin."},{"n":5,"t":"(Sen de) Göreceksin, onlar da görecekler;"},{"n":6,"t":"Hanginizin fitnelenmiş (cin çarpmış delirmiş) olduğunu."},{"n":7,"t":"Şüphesiz Rabbin, kim(ler)in kendi yolundan saptığını ve kimlerin yolda olduğunu en iyi bilen O’dur."},{"n":8,"t":"Öyleyse yalanlayanlara itâ’at etme."},{"n":9,"t":"İstediler ki, sen yağcılık yapasın da onlar da yağcılık yapsınlar (sana yumuşak davransınlar)."},{"n":10,"t":"Şunların hiçbirine itâ’at etme: Yemin edip duran aşağılık,"},{"n":11,"t":"Kötüleyip duran, söz götürüp getiren,"},{"n":12,"t":"Hayra engel olan, saldırgan, günâhkâr,"},{"n":13,"t":"Kaba, sonra da kötülükle damgalı,"},{"n":14,"t":"Mal ve oğullar sâhibi olmuş diye (yolunu şaşırmış)."},{"n":15,"t":"Kendisine âyetlerimiz okunduğu zaman: \"Eskilerin masalları\" der."},{"n":16,"t":"Biz onu burnunun üzerine damga vurup işâretleyeceğiz."},{"n":17,"t":"Biz bunlara da belâ verdik, şu bahçe sâhiplerine belâ verdiğimiz gibi: Hani onlar, sabah olunca bahçeyi mutlaka devşireceklerine yemin etmişlerdi."},{"n":18,"t":"İstisnâ da etmiyorlar (Allâh dilerse biçeriz demiyorlar)dı."},{"n":19,"t":"Fakat onlar uyurlarken hemen (gönderilen) dolaşıcı bir belâ, onu sardı da,"},{"n":20,"t":"Bahçe simsiyah kesiliverdi."},{"n":21,"t":"Sabahleyin birbirlerine seslendiler:"},{"n":22,"t":"\"Haydi devşirecekseniz erkenden ekininize gidin\" diye."},{"n":23,"t":"Derken yürüdüler; fısıldaşıyorlardı:"},{"n":24,"t":"\"Sakın, bugün hiçbir yoksul bahçeye girip yanınıza sokulmasın\" diye."},{"n":25,"t":"Devşirebileceklerini umarak erkenden gittiler."},{"n":26,"t":"Fakat bahçeyi görünce: \"Herhalde biz yolu şaşırdık.\" dediler."},{"n":27,"t":"\"Hayır, doğrusu biz mahrum bırakıldık!\""},{"n":28,"t":"Orta (yolda giden iyi)leri: \"Ben size demedim mi? Rabbinizi tesbih etmeniz gerekmez miydi?\" dedi."},{"n":29,"t":"\"Rabbimizi tesbih ederiz, doğrusu biz zulmedenlermişiz!\" dediler."},{"n":30,"t":"Dönüp birbirlerini kınamağa başladılar:"},{"n":31,"t":"\"Yazık bize, dediler, biz azgınlarmışız!\""},{"n":32,"t":"\"Belki Rabbimiz, bize onun yerine ondan daha iyisini verir. Biz Rabbimize yönelir, O’ndan umarız.\""},{"n":33,"t":"İşte azâb böyledir. Âhiret azâbı ise daha büyüktür, keşke bilselerdi."},{"n":34,"t":"Korunanlar için de Rableri katında ni’met bahçeleri vardır."},{"n":35,"t":"Biz müslümanları suçlular gibi yapar mıyız hiç?"},{"n":36,"t":"Neyiniz var, nasıl hüküm veriyorsunuz?"},{"n":37,"t":"Yoksa sizin bir Kitabınız var da onda mı (bu hükümleri) okuyorsunuz?"},{"n":38,"t":"Onda istediğiniz her şeyi buluyorsunuz?"},{"n":39,"t":"Yoksa sizin istediğiniz hükmü verebileceğinize dair, kıyâmete kadar sürecek andlarınız mı var üzerimizde?"},{"n":40,"t":"Sor onlara: Onların hangisi buna kefil olacak?"},{"n":41,"t":"Yoksa kendilerinin ortakları mı var? Doğru iseler ortaklarını çağırsınlar."},{"n":42,"t":"Bacaktan açılacağı (paçanın sıvanacağı, işlerin güçleşeceği) ve secdeye da’vet edilecekleri gün (secde) edemezler."},{"n":43,"t":"Gözleri düşük olarak yüzlerini bir zillet kaplar. Onlar sağlam iken de secdeye da’vet edilirler (fakat secde etmezler)di."},{"n":44,"t":"Bu sözü yalanlayanı bana bırak; onları bilmedikleri yerden derece derece (azâba) yaklaştıracağız."},{"n":45,"t":"Onlara mühlet veriyorum. Doğrusu benim tuzağım sağlamdır (onu kimse bozamaz)."},{"n":46,"t":"Yoksa sen onlardan bir ücret istiyorsun da onlar ağır borç altında mı kalıyorlar?"},{"n":47,"t":"Yoksa gayb (görünmez bilgi hazinesi), kendi yanlarında da onlar mı (istedikleri gibi) yazıyorlar?"},{"n":48,"t":"Sen Rabbinin hükmüne sabret, balık sâhibi (Yûnus) gibi olma. Hani o, sıkıntıdan yutkunarak (Allah’a) seslenmişti."},{"n":49,"t":"Eğer Rabbinden ona bir ni’met yetişmeseydi, yerilerek çıplak bir yere atılırdı."},{"n":50,"t":"Fakat Rabbi onun du’âsını kabul etti de onu Sâlih (iyi insan)lardan yaptı."},{"n":51,"t":"O inkâr edenler Zikr (Kur’ân)’ı işittikleri zaman, neredeyse seni gözleriyle devireceklerdi. \"O mecnundur\" diyorlardı."},{"n":52,"t":"Halbuki o, âlemler için uyarıdan başka bir şey değildir!"}],[{"n":1,"t":"Gerçekleşen,"},{"n":2,"t":"Nedir o gerçekleşen?"},{"n":3,"t":"Gerçekleşenin ne olduğunu nerden bileceksin?"},{"n":4,"t":"Semûd ve ’Âd (kavimleri), başa çarpan olayı yalanladılar."},{"n":5,"t":"Bu yüzden Semûd (kavmi) azgın bir vak’a ile helâk edildiler."},{"n":6,"t":"’Âd (kavmi) ise uğultulu, azgın bir kasırga ile helâk edildiler."},{"n":7,"t":"(Allâh) Onu, yedi gece, sekiz gün ardı ardına onların üzerine saldı. O kavmi orada, içi boş hurma kütükleri gibi serilmiş görürsün."},{"n":8,"t":"Onlardan hiç geri kalan görüyor musun?"},{"n":9,"t":"Fir’avn ve ondan öncekiler ve altüst olmuş kentler(in halkı olan Lût kavmi) de hatâlı iş yaptılar."},{"n":10,"t":"Rablerinin elçisine karşı geldiler. O da onları şiddeti gittikçe artan bir yakalayışla yakaladı."},{"n":11,"t":"Su(lar) kabarınca biz sizi, akıp giden (gemi)de taşıdık."},{"n":12,"t":"Ki onu size bir ibret yapalım ve belleyen kulak(lar) onu bellesin."},{"n":13,"t":"Sûr’a bir tek üfleme üflendiği,"},{"n":14,"t":"Arz ve dağlar yerlerinden kaldırılıp şiddetle birbirine çarpılarak darmadağın olduğu zaman,"},{"n":15,"t":"İşte o gün, olan olmuştur."},{"n":16,"t":"Gök yarılmıştır; o gün o, zayıf, sarkıktır."},{"n":17,"t":"Melekler de onun kenarlarındadır. O gün Rabbinin tahtını, üstlerinde sekiz (melek) taşır."},{"n":18,"t":"O gün (Allah’a) arz olunursunuz. Sizden hiçbir giz, (Allah’a) gizli kalmaz."},{"n":19,"t":"Kitabı sağından verilen: \"Alın Kitabımı okuyun\" der."},{"n":20,"t":"\"Ben hesabımla karşılaşacağımı sezmiştim zaten.\""},{"n":21,"t":"Artık o, memmun eden bir yaşam içindedir."},{"n":22,"t":"Yüksek bir bahçede."},{"n":23,"t":"Ki devşirmesi kolay (meyvaları yakın. Oturan, elini uzatıp alabilir)."},{"n":24,"t":"\"Geçmiş günlerde yaptığınız işlerden ötürü âfiyetle yeyin, için!\""},{"n":25,"t":"Kitabı sol tarafından verilen ise der ki: \"Keşke bana Kitabım verilmeseydi!\""},{"n":26,"t":"\"Şu hesabımı hiç bilmemiş olsaydım!\""},{"n":27,"t":"\"Keşke (ölüm) işimi bitirmiş olsaydı!\""},{"n":28,"t":"\"Malım bana hiçbir yarar sağlamadı.\""},{"n":29,"t":"\"Gücüm (saltanatım) benden yok olup gitti\""},{"n":30,"t":"(Allâh, cehennemin muhafızlarına buyurur:) \"Tutun onu, bağlayın onu.\""},{"n":31,"t":"\"Sonra cehenneme sallayın onu!\""},{"n":32,"t":"\"Sonra uzunluğu yetmiş arşın olan zincire vurun onu!\""},{"n":33,"t":"\"Çünkü o büyük Allah’a inanmıyordu.\""},{"n":34,"t":"\"Yoksulu doyurmaya ön ayak olmuyurdu!\""},{"n":35,"t":"Bugün burada onun için candan bir dost yoktur."},{"n":36,"t":"İrinden başka yiyecek de yoktur."},{"n":37,"t":"Onu, (bile bile) hatâ işleyenlerden başkası yemez."},{"n":38,"t":"Yoo, yemin ederim; gördüklerinize,"},{"n":39,"t":"Ve görmediklerinize,"},{"n":40,"t":"Ki, o (Kur’ân) elbette değerli bir elçinin sözüdür."},{"n":41,"t":"O, bir şâ’irin sözü değildir. Ne de az inanıyorsunuz!"},{"n":42,"t":"Bir kâhinin sözü de değildir. Ne de az düşünüyorsunuz!"},{"n":43,"t":"Âlemlerin Rabbi tarafından indirilmiştir."},{"n":44,"t":"Eğer o, (Muhammed), bazı laflar uydurup bize iftirâ etseydi,"},{"n":45,"t":"Elbette onun sağ (elini veya kuvvet)ini alırdık."},{"n":46,"t":"Sonra onun can damarını keserdik."},{"n":47,"t":"Sizden hiç kimse buna engel olamazdı."},{"n":48,"t":"O (Kur’ân), korunanlar için bir öğüttür."},{"n":49,"t":"Biz, içinizde yalanlayanlar bulunduğunu elbette biliyoruz."},{"n":50,"t":"Doğrusu o, kâfirler için hasrettir."},{"n":51,"t":"O, kesin gerçektir."},{"n":52,"t":"Öyleyse ulu Rabbinin adını tesbih et (O’nun eksikliklerinden uzak, yücelerden yüce olduğunu an)."}],[{"n":1,"t":"Bir soran, inecek azâbı sordu:"},{"n":2,"t":"Kâfirler için, ki onu savacak yoktur,"},{"n":3,"t":"Yükselme derecelerinin sâhibi Allah’tan."},{"n":4,"t":"Melekler ve Rûh, miktarı elli bin yıl süren bir gün içinde O’na çıkar."},{"n":5,"t":"Şimdi sen güzelce sabret."},{"n":6,"t":"Onlar onu uzak görüyor(lar)."},{"n":7,"t":"Biz ise onu yakın görüyoruz."},{"n":8,"t":"O gün gök, erimiş maden gibi olur."},{"n":9,"t":"Dağlar, renkli yün gibi olur."},{"n":10,"t":"Dost dostun halini sormaz."},{"n":11,"t":"Birbirlerine gösterilirler (fakat herkes kendi derdine düştüğünden, başkasıyle ilgilenemez). Suçlu ister ki o günün azâbından (kurtulmak için) fidye versin: Oğullarını,"},{"n":12,"t":"Eşini ve kardeşini,"},{"n":13,"t":"Kendisini barındıran, içinde yetiştiği tüm âilesini,"},{"n":14,"t":"Ve yeryüzünde bulunanların hepsini (versin) de tek kendisini kurtarsın."},{"n":15,"t":"Hayır! O (ateş), alevlenen bir ateştir."},{"n":16,"t":"Derileri kavurur, soyar."},{"n":17,"t":"(Kendine) Çağırır; sırtını dönüp gideni,"},{"n":18,"t":"(Mal) Toplayıp kasada yığanı!"},{"n":19,"t":"Doğrusu insan hırslı (ve huysuz) yaratılmıştır."},{"n":20,"t":"Kendisine kötülük dokundu mu sızlanır,"},{"n":21,"t":"Kendisine hayır dokundu mu yardım etmez (sıkı sıkı tutar)."},{"n":22,"t":"Ancak namaz kılanlar bunun dışındadır."},{"n":23,"t":"Onlar ki: Namazlarını sürekli kılarlar (aksatmazlar)."},{"n":24,"t":"Onların mallarında belli bir hisse vardır:"},{"n":25,"t":"Sâile ve mahruma (isteyene ve utancından dolayı istemeyip mahrum kalana)."},{"n":26,"t":"Cezâ gününü tasdik ederler,"},{"n":27,"t":"Rablerinin azâbından korkarlar."},{"n":28,"t":"Çünkü Rablerinin azâbına güven olmaz."},{"n":29,"t":"Irzlarını korurlar."},{"n":30,"t":"Yalnız eşlerine ya da ellerinin altında bulunan (câriyelerin)e karşı (korumazlar. Bundan ötürü de) onlar kınanmazlar."},{"n":31,"t":"Ama kim bundan ötesini ararsa, onlar (sınırı) aşanlardır."},{"n":32,"t":"Emânetlerini ve ahidlerini gözetirler."},{"n":33,"t":"Şâhidliklerini yaparlar."},{"n":34,"t":"Namazlarını korurlar."},{"n":35,"t":"İşte onlar cennetlerde ağırlanırlar."},{"n":36,"t":"Nânkörlere ne oluyur ki sana doğru koşuyorlar?"},{"n":37,"t":"Sağdan, soldan, ayrı ayrı gruplar halinde (gelip etrafını sarıyorlar)?"},{"n":38,"t":"Onlardan her biri, ni’met cennetine sokulacağını mı umuyor?"},{"n":39,"t":"Hayır! Öyle şey yok! Biz onları bildikleri şeyden yarattık."},{"n":40,"t":"Yoo, doğuların ve bâtıların Rabbine yemin ederim ki bizim gücümüz yeter:"},{"n":41,"t":"Onları, kendilerinden daha hayırlı olanlarla değiştirmeğe. Bizim önümüze geçilmez (bize engel olunamaz)."},{"n":42,"t":"Bırak onları kendilerine va’dedilen günlerine kavuşuncaya kadar dalsın, oynasınlar."},{"n":43,"t":"O gün kabirlerden hızlı hızlı çıkarlar. Onlar dikilen (putlara yahut hedef)lere doğru koşar gibi (koşarlar)."},{"n":44,"t":"Gözleri düşük, yüzlerini alçaklık bürümüş bir durumda. İşte onlara va’dedilen gün, bugündür."}],[{"n":1,"t":"Biz Nûh’u kavmine gönderdik: \"Onlara acı bir azâb gelmezden önce kavmini uyar,\" diye."},{"n":2,"t":"\"Ey kavmim, dedi, ben sizin için açık bir uyarıcıyım.\""},{"n":3,"t":"\"Allah’a kulluk edin, O’ndan korkun, bana da itâ’at edin.\""},{"n":4,"t":"\"Ki (Allâh) günâhlarınızdan bir kısmını bağışlasın ve sizi belli bir süreye kadar ertelesin. Zira Allâh’ın süresi geldiği zaman ertelenmez. Bilir (kişiler) olsaydınız (bunu anlardınız).\""},{"n":5,"t":"(Nûh:) \"Rabbim, dedi, ben kavmimi gece gündüz da’vet ettim.\""},{"n":6,"t":"\"Benim da’vetim, onlara kaçışlarını artırmaktan başka bir katkıda bulunmadı.\""},{"n":7,"t":"\"Günâhlarını bağışlaman için onları (sana) ne kadar da’vet ettimse parmaklarını kulaklarına tıkadılar, örtülerini başlarına çektiler, direttiler, çok böbürlendiler.\""},{"n":8,"t":"\"Sonra ben onları açıkça da’vet ettim.\""},{"n":9,"t":"\"Sonra onlara açıktan söyledim, gizli gizli söyledim:"},{"n":10,"t":"’Rabbinizden mağfiret dileyin, çünkü O çok bağışlayandır’ dedim.\""},{"n":11,"t":"’(O’ndan mağfiret dileyin) Ki üzerinize gökten bol yağmur göndersin’"},{"n":12,"t":"’Ve size mallarla, oğullarla yardım etsin, size bahçeler versin, ırmaklar versin’"},{"n":13,"t":"’Size ne oluyor ki, Allâh için saygı ummuyorsunuz?’"},{"n":14,"t":"’Oysa O, sizi aşama, aşama yarattı.’"},{"n":15,"t":"’Görmediniz mi Allâh nasıl yedi göğü birbiri üstünde tabaka tabaka yarattı?’"},{"n":16,"t":"’Ve Ayı bunların içinde nur yaptı. Güneşi de bir lamba yaptı.’"},{"n":17,"t":"’Allâh sizi yerden bir bitki olarak bitirdi.’"},{"n":18,"t":"’Sonra yine oraya geri çevirecek ve tekrar çıkaracaktır.’"},{"n":19,"t":"’Allâh, yeri sizin için bir sergi yaptı.’"},{"n":20,"t":"’Ki onda açılan geniş geniş yollarda gidesiniz’.\""},{"n":21,"t":"(Bu öğütlerin hiçbirinin fayda vermediğini gören) Nûh, (Rabbine dönerek): \"Rabbim, dedi, onlar bana karşı geldiler de malı ve çocuğu kendisinin ziyanını artırmaktan başka işe yaramayan (şımarık, gururlu) bir adama uydular.\""},{"n":22,"t":"\"Büyük büyük tuzaklar kurdular.\""},{"n":23,"t":"Dediler ki: \"Tanrılarınızı bırakmayın: Vedd’i, Suva’ı, Yeğûs’u, Ye’ûk’u ve Nesr’i bırakmayın!\""},{"n":24,"t":"\"(Böylece) Onlar, çok kimseyi yoldan çıkardılar. Sen de o zâlimlere şaşkınlıktan başka bir şey artırma.\""},{"n":25,"t":"Hatâlarından dolayı boğuldular, ateşe sokuldular, kendilerine Allah’tan başka yardımcılar da bulamadılar."},{"n":26,"t":"Nûh dedi ki: \"Rabbim, yeryüzünde kâfirlerden tek kişi bırakma.\""},{"n":27,"t":"\"Çünkü sen onları bırakırsan, kullarını şaşırtırlar ve sadece ahlâksız, nânkör (insanlar) doğururlar.\""},{"n":28,"t":"Rabbim beni, babamı, anamı, inanarak evime gireni, inanan erkek ve kadınları bağışla; zâlimlerin de sadece helâkini artır (onların köklerini kurut)!\""}],[{"n":1,"t":"De ki: Cinlerden bir topluluğun Kur’ân dinleyip şöyle dedikleri bana vahyolundu: \"Biz harikulâde güzel bir Kur’ân dinledik."},{"n":2,"t":"Doğru yola iletiyor, ona inandık. Artık Rabbimize hiç kimseyi ortak koşmayacağız."},{"n":3,"t":"Doğrusu Rabbimizin şanı yücedir. O, eş ve çocuk edinmemiştir."},{"n":4,"t":"Meğer bizim beyinsiz (İblis veya cinlerin kâfirleri) Allâh hakkında saçma şeyler söylüyormuş."},{"n":5,"t":"Biz insanların ve cinlerin, Allah’a karşı yalan söylemeyeceklerini sanmıştık (onun için o beyinsizin sözüne uymuştuk),"},{"n":6,"t":"Doğrusu insanlardan bazı erkekler, cinlerden bazı erkeklere sığınırlardı da onların şımarıklığını artırırlardı."},{"n":7,"t":"Onlar da sizin sandığınız gibi Allâh’ın hiç kimseyi diriltmeyeceğini sanmışlardı."},{"n":8,"t":"Biz göğe dokunduk, onu kuvvetli bekçilerle ve ışınlarla doldurulmuş bulduk."},{"n":9,"t":"Ve biz onun dinlemeğe mahsus olan oturma yerlerinde oturur (gayb haberlerini dinlemeğe çalışır)dık. Artık şimdi kim dinlemek istese, kendisini gözetleyen bir ışın bulur."},{"n":10,"t":"Bilmiyoruz bununla yeryüzündekilere kötülük mü (yapılmak) istendi, yoksa Rabbleri onları doğruya mı iletmek diledi."},{"n":11,"t":"Bize gelince, bizden iyiler de var ve bizden başka türlü olan da var. Biz çeşitli yollara ayrıldık."},{"n":12,"t":"Biz yeryüzünde Allâh’ı âciz bırakamayacağımızı (yerden) kaçmakla da O’nu âciz bırak(ıp O’ndan kurtul)amayacağımızı anladık."},{"n":13,"t":"Biz, yol gösteren (Kur’ân)ı işitince ona inandık. Kim Rabbine inanırsa (ne hakkının) eksik verilmesinden, ne de kendisine kötülük edilmesinden korkar."},{"n":14,"t":"Ve biz, bizden müslümanlar da var ve bizden doğru yoldan sapanlar da var. Kimler müslüman olursa işte onlar doğru yolu aramışlardır."},{"n":15,"t":"Hak yoldan sapanlar ise cehenneme odun olmuşlardır.\""},{"n":16,"t":"Şâyet yolda doğru gitselerdi onlara bol su verirdik (rızıklarını bollaştırırdık)."},{"n":17,"t":"Ki onları, onunla sınayalım. Kim Rabbini anmaktan yüz çevirirse (Rabbi) onu, alt eden bir azâba sokar."},{"n":18,"t":"Mescidler, Allâh’a mahsustur. Allâh ile beraber hiç kimseye yalvarmayın."},{"n":19,"t":"Allâh’ın kulu kalkıp O’na yalvarınca (hayretten, hepsi) onun üzerine üşüşüp nerdeyse keçe gibi birbirlerine geçeceklerdi."},{"n":20,"t":"De ki: \"Ben ancak Rabbime yalvarırım ve hiç kimseyi O’na ortak koşmam.\""},{"n":21,"t":"De ki: \"Ben size ne zarar, ne de akıl verme gücüne sâhip değilim.\""},{"n":22,"t":"De ki: \"Beni Allâh’(ın azâbın)dan hiç kimse kurtaramaz ve ondan başka sığınacak kimse bulamam.\""},{"n":23,"t":"Benim yapabileceğim sadece Allah’tan (bana vahyedilenleri) size duyurmak ve O’nun elçilik görevlerini yerine getirmektir. Artık kim Allah’a ve Elçisine baş kaldırırsa, ona içinde sürekli kalacağı cehennem ateşi vardır."},{"n":24,"t":"Kendilerine va’dedilen şeyi (ya azâbı veya kıyâmet sâ’atini) gördükleri zaman, kimin yardımcı bakımından daha zayıf ve sayıca daha az olduğunu bileceklerdir."},{"n":25,"t":"De ki: \"Size söylenen şey yakın mıdır, yoksa Rabbim onun için uzun bir süre mi koyacaktır, bilmem.\""},{"n":26,"t":"Gaybı bilen O’dur. Gizli bilgisini kimseye göstermez."},{"n":27,"t":"Ancak râzı olduğu elçiye gösterir. Çünkü O, elçisinin önüne ve arkasına gözetleyiciler (koruyucular) koyar."},{"n":28,"t":"(Böyle yapar) Ki onların, Rablerinin kendilerine verdiği mesajları duyurduklarını bilsin. Allâh, onlarda bulunan herşeyi (bilgisiyle) kuşatmıştır ve herşeyi bir bir saymış (hesab etmiş)tir."}],[{"n":1,"t":"Ey örtüsüne bürünen,"},{"n":2,"t":"Geceleyin kalk (namaz kıl); yalnız gecenin birazında (uyu)."},{"n":3,"t":"Gecenin yarısında (kalk) yahut bundan biraz eksilt."},{"n":4,"t":"Veya bunu artır ve ağır ağır Kur’ân oku."},{"n":5,"t":"Doğrusu biz, senin üzerine ağır bir söz bırakacağız."},{"n":6,"t":"Gerçekten gece kalk(ıp ibâdet et)mek daha oturaklı ve (geceleyin) söz (du’â) daha etkilidir."},{"n":7,"t":"Çünkü gündüz, senin uzun süre uğraşacağın şeyler vardır."},{"n":8,"t":"Rabbinin adını an ve bütün gönlünle O’na yönel."},{"n":9,"t":"(O) Doğunun ve batının Rabbidir. O’ndan başka tanrı yoktur. Yalnız O’nu vekil tut."},{"n":10,"t":"Onların dediklerine sabret ve güzelce onlardan ayrıl."},{"n":11,"t":"Beni ve o ni’met sâhibi yalanlayıcıları yalnız bırak ve onlara biraz mühlet ver."},{"n":12,"t":"Doğrusu, bizim yanımızda bukağılar ve cehennem var."},{"n":13,"t":"(Dikenli) Boğazı tırmalayan bir yiyecek ve acı veren bir azâb var."},{"n":14,"t":"O gün yer ve dağlar sarsılır ve dağlar, dağılan kum yığınları olur."},{"n":15,"t":"(Ey insanlar,) Doğrusu biz size, aleyhinize tanıklık edecek bir elçi gönderdik; nasıl ki Fir’avn’a da bir elçi göndermiştik."},{"n":16,"t":"Fir’avn, elçiye karşı geldi. Biz de onu ağır bir yakalayışla yakaladık."},{"n":17,"t":"Peki inkâr ederseniz, çocukları ihtiyarlatan o günden kendinizi nasıl kurtaracaksınız?"},{"n":18,"t":"Gök (bile) onun dehşetinden yarılır. Allâh’ın va’di mutlaka yapılmıştır."},{"n":19,"t":"Bu bir öğüttür. Dileyen, Rabbine varan bir yol tutar."},{"n":20,"t":"Rabbin senin gecenin üçte ikisinden daha azında, yarısında ve üçte birinde kalktığını; Seninle beraber bulunanlardan bir topluluğun da böyle yaptığını biliyor. Geceyi ve gündüzü takdir eden Allâh, sizin onu sayamayacağınızı (zamanı hesab edip gecenin belli sâ’atlerinde kalkamayacağınızı) bildiği için sizi affetti. Artık (belli bir sâ’at gözetmeden) Kur’ân’dan kolayınıza geleni okuyun (ne miktar kolayınıza gelirse o kadar gece namazı kılın, kendinizi zorlamayın.) Allâh, içinizden hastalar, yeryüzünde gezip Allâh’ın lutfunu arayan başka kimseler ve Allâh yolunda savaşan daha başka insanlar bulunacağını bilmiştir. Onun için Kur’ân’dan kolayınıza geldiği kadar okuyun. Namazı kılın, zekâtı verin ve Allah’a güzel bir borç verin. Kendiniz için verdiğiniz hayırları, Allâh katında verdiğinizden daha hayırlı ve mükâfâtça daha büyük bulacaksınız. Allah’tan mağfiret dileyin. Şüphesiz Allâh, çok bağışlayan, çok esirgeyendir."}],[{"n":1,"t":"Ey örtüsüne bürünen,"},{"n":2,"t":"Kalk, uyar."},{"n":3,"t":"Rabbini tekbir et (O’nun büyüklüğünü an),"},{"n":4,"t":"Elbiseni temizle,"},{"n":5,"t":"Pislikten kaçın."},{"n":6,"t":"Verdiğini çok bularak başa kakma."},{"n":7,"t":"Rabbin için sabret."},{"n":8,"t":"Sûr’a üflendiği zaman"},{"n":9,"t":"İşte o gün, çetin bir gündür!"},{"n":10,"t":"Kâfirler için kolay değildir."},{"n":11,"t":"Benimle şu adamı yalnız bırak ki ben onu tek olarak yarattım."},{"n":12,"t":"Ona uzun boylu mal verdim."},{"n":13,"t":"Göz önünde oğullar (verdim)."},{"n":14,"t":"Kendisine bir döşeyiş döşedim."},{"n":15,"t":"Hâlâ daha da artırmama göz dikiyor."},{"n":16,"t":"Hayır, çünkü o bizim âyetlerimize karşı bir inatçı kesildi."},{"n":17,"t":"Onu dimdik bir yokuşa sardıracağım."},{"n":18,"t":"Zirâ o düşündü, ölçtü, biçti."},{"n":19,"t":"Kahrolası nasıl da ölçtü, biçti."},{"n":20,"t":"Yine kahrolası nasıl ölçtü, biçti."},{"n":21,"t":"Sonra baktı,"},{"n":22,"t":"Sonra surat astı, kaşlarını çattı,"},{"n":23,"t":"Sonra arkasını döndü, böbürlendi:"},{"n":24,"t":"\"Bu dedi, rivâyet edilip öğretilen bir büyüden başka bir şey değildir.\""},{"n":25,"t":"\"Bu, sadece, bir insan sözüdür.\""},{"n":26,"t":"Onu Sekar’a sokacağım."},{"n":27,"t":"Sekar’ın ne olduğunu sen nereden bileceksin?"},{"n":28,"t":"(Geride bir şey) Komaz, bırakmaz (her şeyi yakıp yok eder)."},{"n":29,"t":"Durmadan deriler kavurur."},{"n":30,"t":"Üzerinde ondokuz (muhafız) vardır."},{"n":31,"t":"Biz cehennemin muhafızlarını hep melekler yaptık. Onların sayısını da inkâr edenler için bir sınav yaptık ki, kendilerine Kitap verilmiş olanlar iyice inansın, inananların da imanı artsın. Kitap verilmiş olanlar ve inananlar kuşkulanmasınlar. Kalblerinde hastalık bulunanlar ve kâfirler de: \"Allâh bu misâlle ne demek istedi?\" desinler. Böylece Allâh, dilediğini şaşırtır, dilediğini doğru yola iletir. Rabbinin ordularını ancak kendisi bilir. Bu, insanlara bir uyarıdır."},{"n":32,"t":"Hayır, andolsun Aya,"},{"n":33,"t":"Dönüp gitmekte olan geceye,"},{"n":34,"t":"Ağaran sabaha,"},{"n":35,"t":"Ki o (Sekar), büyük (belâ)lardan biridir."},{"n":36,"t":"İnsanlar için uyarıcıdır;"},{"n":37,"t":"Sizden (iman yolunda) ileri gitmek veya geri kalmak dileyen kimseler için (uyarıcıdır)."},{"n":38,"t":"Her can, kazandığıyle (Allâh katında) rehin alınmıştır."},{"n":39,"t":"Yalnız sağın adamları (Kitapları sağdan verilenler) hariç."},{"n":40,"t":"Onlar cennetler içinde soruyorlar;"},{"n":41,"t":"Suçluların durumunu:"},{"n":42,"t":"\"Sizi şu yakıcı ateşe ne sürükledi?\""},{"n":43,"t":"(Onlar da) Dediler ki: \"Biz namaz kılanlardan olmadık.\""},{"n":44,"t":"\"Yoksula da yedirmezdik.\""},{"n":45,"t":"Boş şeylere dalanlarla birlikte dalardık.\""},{"n":46,"t":"\"Cezâ gününü yalanlardık.\""},{"n":47,"t":"\"İşte böyle iken ölüm bize gelip çattı.\""},{"n":48,"t":"Artık onlara şefâ’atçilerin şefâ’ati fayda vermez."},{"n":49,"t":"Böyle iken onlara ne oluyur ki öğütten yüz çeviriyorlar?"},{"n":50,"t":"Yaban eşekleri gibi;"},{"n":51,"t":"Aslandan ürkmüş."},{"n":52,"t":"Hayır, onlardan her kişi kendisine açılan sahifeler verilmesini istiyor."},{"n":53,"t":"Yok yok onlar âhiretten korkmuyorlar."},{"n":54,"t":"Hayır (iyi bilsinler ki) o (Kur’ân) bir ikazdır."},{"n":55,"t":"Dileyen onu düşünür, öğüt alır."},{"n":56,"t":"Allâh dilemedikçe onlar öğüt almazlar. Takvâ ve mağfiret ehli O’dur (kendisinden korunmağa, cezâsından kaçınmağa lâyık olan ve günâhları bağışlayan yalnız O’dur)."}],[{"n":1,"t":"Yoo, kıyâmet gününe and içerim,"},{"n":2,"t":"Yoo, dâimâ, kendini kınayan nefse and içerim."},{"n":3,"t":"İnsan kendisinin kemiklerini bir araya toplamayacağımızı mı sanıyor?"},{"n":4,"t":"Evet, toplarız, onun parmak uçlarını düzenlemeğe gücümüz yeter."},{"n":5,"t":"Fakat insan, devamlı suç işleyerek ilerisini berbâd etmek ister."},{"n":6,"t":"\"Kıyâmet günü nerede?\" diye sorup durur."},{"n":7,"t":"Ama göz (güneş gibi ortaya çıkan gerçeğin karşısında) kamaştığı,"},{"n":8,"t":"Ay tutulduğu,"},{"n":9,"t":"Güneş ve Ay bir araya toplandığı zaman!"},{"n":10,"t":"(Evet) O gün insan: \"Kaçacak yer neresi?\" der."},{"n":11,"t":"Hayır, sığınacak yer yoktur."},{"n":12,"t":"O gün varıp durulacak yer, ancak Rabbinin huzûrudur (ey insan)."},{"n":13,"t":"(O zaman) İnsanın yapıp öne sürdüğü, (yapmayıp) geri bıraktığı herşey kendisine haber verilir."},{"n":14,"t":"Doğrusu insan kendi nefsini görür,"},{"n":15,"t":"Birtakım özürler ortaya atsa da."},{"n":16,"t":"(Ey Muhammed,) Onu hemen okumak için diline depretme."},{"n":17,"t":"Onu (senin kalbinde) toplamak ve (sana) okumak bize düşer."},{"n":18,"t":"O halde sana Kur’ân’ı okuduğumuz zaman onun okunuşunu izle."},{"n":19,"t":"Sonra onu açıklamak da bize düşer."},{"n":20,"t":"Hayır, siz çabuk (geçen şu dünyây)ı seviyorsunuz da,"},{"n":21,"t":"Âhireti bırakıyorsunuz."},{"n":22,"t":"Yüzler var ki o gün ışıl ışıl parlar,"},{"n":23,"t":"Rabbine bakar."},{"n":24,"t":"Yüzler de var ki o gün asıktır."},{"n":25,"t":"Kendisine bel kemiklerini kıran (belâ)nın yapılacağını anlar."},{"n":26,"t":"Hayır, ne zaman ki can, köprücük kemiklerine dayanır,"},{"n":27,"t":"Ve (başında bulunanlar tarafından): \"Kim afsun yapar acaba? denir,"},{"n":28,"t":"Ve kendisi artık bunun, ayrılık zamanı olduğunu anlar,"},{"n":29,"t":"Ve bacak bacağa dolaşır."},{"n":30,"t":"İşte o gün, sevk Rabbinedir (can, Allâh’ın huzûruna sevk edilir)."},{"n":31,"t":"Ne sadaka verdi, ne de namaz kıldı."},{"n":32,"t":"Fakat yalanladı, döndü."},{"n":33,"t":"Sonra çalım satarak âilesine gitti."},{"n":34,"t":"Yazık sana yazık!"},{"n":35,"t":"Yine yazık sana yazık!"},{"n":36,"t":"İnsan, başı boş bırakılacağını mı sanır?"},{"n":37,"t":"Kendisi dökülen meniden bir nutfe (sperm) değil miydi?"},{"n":38,"t":"Sonra alaka (rahme asılan embriyo) oldu da (Rabbi onu) yarattı, düzenledi."},{"n":39,"t":"O (meni)den iki çifti: Erkeği ve dişiyi var etti."},{"n":40,"t":"Şimdi bun(ları yapan Allâh)ın ölüleri diriltmeğe gücü yetmez mi?"}],[{"n":1,"t":"İnsanın üzerinden, henüz kendisinin anılan bir şey olmadığı uzun bir süre geçmedi mi?"},{"n":2,"t":"Doğrusu biz insanı, imtihan etmek için karışık bir nutfeden yarattık da onu işitici, görücü yaptık."},{"n":3,"t":"Biz ona yolu gösterdik: Ya şükredici veya nânkör olur."},{"n":4,"t":"Biz, kâfirler için zincirler, demir halkalar ve alevli bir ateş hazırlamışızdır."},{"n":5,"t":"İyiler de, karışımı kâfûr olan bir kadehten içerler."},{"n":6,"t":"Bir kaynak ki Allâh’ın kulları ondan içerler, (istedikleri yere de) fışkırtarak akıtırlar."},{"n":7,"t":"Adaklarını yerine getirirler ve şerri salgın olan bir günden korkarlar."},{"n":8,"t":"Yoksula, yetime ve esire sevdikleri yemeği yedirirler:"},{"n":9,"t":"\"Biz size sırf Allâh rızâsı için yediriyoruz, sizden bir karşılık ve teşekkür beklemiyoruz.\""},{"n":10,"t":"\"Çünkü biz suratsız, çok katı bir gün(ün azâbın)dan ötürü Rabbimizden korkarız.\" (derler)."},{"n":11,"t":"Allâh da onları, o günün şerrinden korumuş, onlar(ın yüzlerin)e parlaklık ve (gönüllerine) sevinç vermiştir."},{"n":12,"t":"Sabrettiklerinden dolayı onları cennet ve ipekle ödüllendirmiştir!"},{"n":13,"t":"Orada divanlar üzerinde yastıklara dayanırlar. Orada ne (yakıcı) güneş görürler, ne de dondurucu soğuk."},{"n":14,"t":"Cennetin gölgeleri, üzerlerine yaklaşmış, meyvaları da aşağı eğdirildikçe eğdirilmiştir."},{"n":15,"t":"Yanlarında gümüş kablar, billûr kupalar dolaştırılır."},{"n":16,"t":"Öyle gümüş kadehler ki onları istedikleri ölçüde takdir etmişlerdir (istedikleri kadar içki alırlar)."},{"n":17,"t":"Onlara orada, karışımı zencefil olan kadehten içirilir."},{"n":18,"t":"Bir çeşme ki adına Selsebil denir."},{"n":19,"t":"Çevrelerinde de (öyle) ölümsüz gençler dolaşır ki, onları görsen, kendilerini saçılmış inci sanırsın."},{"n":20,"t":"Orada nereye baksan, bir ni’met ve büyük bir mülk görürsün."},{"n":21,"t":"(Cennet ehlinin) Üstlerinde yeşil ipekten ince ve kalın giysiler var. Gümüş bilezikler takınmışlardır. Rableri onlara tertemiz bir içki içirmiş (ve şöyle demiş)tir:"},{"n":22,"t":"\"Bu, sizin ödülünüzdür. Çalışmanızın karşılığı verilmiştir!\""},{"n":23,"t":"Muhakkak Biziz, Biz ki sana Kur’ân’ı parça parça indirdik."},{"n":24,"t":"O halde Rabbinin hükmüne sabret ve onlardan hiçbir günâhkâra, yahut nânköre itâ’at etme."},{"n":25,"t":"Sabah akşam Rabbinin adını an."},{"n":26,"t":"Gecenin bir bölümünde O’na secde et ve geceleyin uzun zaman O’nu tesbih eyle (şânının yüceliğini an)!"},{"n":27,"t":"Bunlar, şu çabuk (geçen dünyây)ı seviyorlar da ötelerindeki ağır bir günü bırakıyorlar."},{"n":28,"t":"Biz onları yarattık, yapılarını sıkıca bağladık. Dilediğimiz zaman onları benzerleriyle değiştiririz."},{"n":29,"t":"Bu bir öğüttür. Dileyen, Rabbine varan yolu tutar."},{"n":30,"t":"Allâh dilemedikçe siz dileyemezsiniz. Şüphesiz Allâh bilendir, hüküm ve hikmet sâhibidir."},{"n":31,"t":"Dilediğini rahmetine sokar. Zâlimlere gelince, onlar için acı bir azâb hazırlamıştır."}],[{"n":1,"t":"Andolsun; birbiri ardınca gönderilenlere,"},{"n":2,"t":"Esip savuranlara,"},{"n":3,"t":"Yaydıkça yayanlara,"},{"n":4,"t":"Ayırdıkça ayıranlara,"},{"n":5,"t":"Öğüt bırakanlara:"},{"n":6,"t":"Özür yahut uyarmak için."},{"n":7,"t":"(Bunlara andolsun) Ki size va’dedilen, mutlaka olacaktır."},{"n":8,"t":"Yıldızlar(ın ışığı) silindiği zaman,"},{"n":9,"t":"Gök yarıldığı zaman,"},{"n":10,"t":"Dağlar ufalanıp savrulduğu zaman,"},{"n":11,"t":"Elçilere vakit belirlendiği zaman:"},{"n":12,"t":"Ertelenmiş oldukları gün için,"},{"n":13,"t":"Yani hüküm günü için."},{"n":14,"t":"Hüküm gününün ne olduğunu sen nereden bileceksin?"},{"n":15,"t":"Yalanlayanların vay haline o gün!"},{"n":16,"t":"Öncekileri helâk etmedik mi?"},{"n":17,"t":"Sonra geridekileri de onların ardına takarız."},{"n":18,"t":"Suçlulara böyle yaparız."},{"n":19,"t":"(Hakkı) yalanlayanların vay haline o gün!"},{"n":20,"t":"Sizi âdi bir sudan yaratmadık mı?"},{"n":21,"t":"Onu sağlam bir karar yerine koyduk."},{"n":22,"t":"Belli bir süreye kadar."},{"n":23,"t":"Biçimlendirdik. Ne güzel biçim vereniz Biz."},{"n":24,"t":"Yalanlayanların vay haline o gün!"},{"n":25,"t":"Arz’ı toplanma yeri yapmadık mı?"},{"n":26,"t":"Diriler ve ölüler için."},{"n":27,"t":"Orada yüksek yüksek dağlar meydana getirmedik mi? Ve size tatlı su(lar) içirmedik mi?"},{"n":28,"t":"Yalanlayanların vay haline o gün!"},{"n":29,"t":"\"Haydi yalanladığınız (azâb)a gidin!"},{"n":30,"t":"Üç dallı bir gölgeye gidin.\""},{"n":31,"t":"Ki ne gölgelendirir, ne de alevden korur."},{"n":32,"t":"O, kütük gibi kıvılcım(lar) saçar."},{"n":33,"t":"(Saçtığı) kıvılcım, sanki sarı bir halattır."},{"n":34,"t":"Yalanlayanların vay haline o gün!"},{"n":35,"t":"Bu, konuşamayacakları gündür."},{"n":36,"t":"Kendilerine izin de verilmez ki özür dilesinler."},{"n":37,"t":"Yalanlayanların vay haline o gün!"},{"n":38,"t":"İşte bu, hüküm günüdür. Sizi ve öncekileri bir araya topladık."},{"n":39,"t":"Eğer (kurtulmak için yapacağınız) bir hileniz varsa bana hile yapın (da beni atlatın)."},{"n":40,"t":"Yalanlayanların vay haline o gün!"},{"n":41,"t":"Korunanlar ise gölgeler altında, çeşme başındadırlar."},{"n":42,"t":"Gönüllerinin çektiği meyvalar içindedirler."},{"n":43,"t":"\"Yaptıklarınıza karşılık âfiyetle yeyin, için!\""},{"n":44,"t":"\"Biz, güzel davrananları böyle mükâfâtlandırırız.\""},{"n":45,"t":"Yalanlayanların vay haline o gün!"},{"n":46,"t":"\"Yeyin, azıcık sefâ sürün, siz suçlularsınız!\""},{"n":47,"t":"Yalanlayanların vay haline o gün!"},{"n":48,"t":"Onlara: \"Rükû’ edin\" dendiği zaman rükû’ etmezler."},{"n":49,"t":"Yalanlayanların vay haline o gün!"},{"n":50,"t":"Onlar bun(a inanmadık)dan sonra hangi hadise (söze) inanacaklar?"}],[{"n":1,"t":"Birbirlerine hangi şeyden soruyorlar?"},{"n":2,"t":"O büyük haberden mi?"},{"n":3,"t":"Ki onlar onda ayrılığa düşmektedirler."},{"n":4,"t":"Hayır (dedikleri gibi değil), yakında bilecekler."},{"n":5,"t":"Sonra hayır (dedikleri gibi değil), yakında bilecekler."},{"n":6,"t":"Yapmadık mı biz, Arzı bir beşik,"},{"n":7,"t":"Dağları birer kazık?"},{"n":8,"t":"Ve sizi çift çift yarattık."},{"n":9,"t":"Uykunuzu dinlenme yaptık."},{"n":10,"t":"Geceyi (sizi sarıp örten) bir giysi yaptık."},{"n":11,"t":"Gündüzü de geçim zamanı yaptık."},{"n":12,"t":"Üstünüzde yedi sağlam (gök) binâ ettik."},{"n":13,"t":"Ve (orada) parıl parıl parlayan bir lamba yarattık."},{"n":14,"t":"Sıkışan (bulut)lardan şarıl şarıl su indirdik,"},{"n":15,"t":"Ki onunla çıkaralım: Dâne(ler), bitki(ler),"},{"n":16,"t":"Ve (ağaçları) birbirine sarmaş dolaş bahçeler."},{"n":17,"t":"Muhakkak ki (haklının, haksızın ayırdedileceği) hüküm günü, belirlenmiş bir vakittir."},{"n":18,"t":"O gün Sûr’a üflenir, bölük bölük gelirsiniz."},{"n":19,"t":"Gök açılmış, kapı kapı olmuştur."},{"n":20,"t":"Dağlar yürütülmüş, bir serab olmuştur."},{"n":21,"t":"Cehennem de gözetleme yeri olmuş (suçluları gözetleyip durmakta)dır."},{"n":22,"t":"Azgınların varacağı yerdir."},{"n":23,"t":"Orada çağlar boyu kalacalardır."},{"n":24,"t":"Orada ne bir serinlik, ne de içilecek bir şey tadarlar,"},{"n":25,"t":"Yalnız kaynar su ve irin (içerler);"},{"n":26,"t":"Yaptıklarına uygun bir cezâ olarak."},{"n":27,"t":"Çünkü onlar bir hesap (görüleceğini) ummuyorlardı."},{"n":28,"t":"Âyetlerimizi de tamamen yalanlamışlardı."},{"n":29,"t":"Biz de her şeyi sayıp yazmıştık."},{"n":30,"t":"\"Şimdi tadın (yaptıklarınızın tadını), artık size azâbdan başka bir şey artırmayacağız!"},{"n":31,"t":"Korunanlar için de başarı ödülü vardır."},{"n":32,"t":"Bahçeler, bağlar,"},{"n":33,"t":"Göğüsleri tomurcuklanmış yaşıt kızlar."},{"n":34,"t":"Ve dolu kadeh(ler)."},{"n":35,"t":"Orada ne boş söz ne de yalan işitirler;"},{"n":36,"t":"Rabbinden bir karşılık, yeterli bir bağış olarak."},{"n":37,"t":"Göklerin, yerin ve ikisi arasında bulunanların Rabbi, çok merhametli (Rab). O’nun (izni olmadan) huzurunda konuşamazlar."},{"n":38,"t":"O gün Rûh ve melekler, sıra sıra dururlar. Ancak Rahmân’ın izin verdiği konuşabilir, o da doğruyu söyler."},{"n":39,"t":"İşte bu, hak günüdür. Artık dileyen, Rabbine varan bir yol tutar."},{"n":40,"t":"Biz sizi yakın bir azâb ile uyardık. O gün kişi, ellerinin (yapıp) öne sürdüğü işlere bakar ve kâfir: \"Keşke ben, toprak olsaydım!\" der."}],[{"n":1,"t":"Andolsun söküp çıkaranlara,"},{"n":2,"t":"Hemen çekip alanlara,"},{"n":3,"t":"Yüzüp gidenlere,"},{"n":4,"t":"Yarışıp, geçenlere,"},{"n":5,"t":"Derken işi düzenleyenlere!"},{"n":6,"t":"O gün o gürültü sarsar."},{"n":7,"t":"Ardından başka bir gürültü gelir."},{"n":8,"t":"O gün bazı yürekler çarpar."},{"n":9,"t":"Gözleri (korkudan) aşağı kayar."},{"n":10,"t":"Diyorlar ki: \"Biz yine eski halimize döndürülecek miyiz?\""},{"n":11,"t":"\"Biz çürümüş kemikler olduktan sonra ha?\""},{"n":12,"t":"\"Öyle ise bu, ziyanlı bir dönüştür!\" dediler."},{"n":13,"t":"O (olay zor değil) bir tek haykırış(a bakmakta)dır."},{"n":14,"t":"Hemen onlar uyanıklık alanındadırlar."},{"n":15,"t":"Mûsâ’nın haberi sana geldi mi?"},{"n":16,"t":"Hani Rabbi ona Kutsal Vâdi’de, \"Tuvâ\"’da ünlemişti:"},{"n":17,"t":"\"Fir’avn’a git, çünkü o azdı.\""},{"n":18,"t":"\"De ki: Arınmağa gönlün var mı?\""},{"n":19,"t":"\"Seni Rabbin(in yolun)a ileteyim de O’ndan korkasın.\""},{"n":20,"t":"Ona büyük mu’cizeyi gösterdi."},{"n":21,"t":"Fakat o yalanladı, karşı geldi."},{"n":22,"t":"Sonra sırtını döndü; (Mûsâ’nın getirdiklerini iptal etmek için) çalışmağa koyuldu."},{"n":23,"t":"(Adamlarını) Topladı, (onlara) bağırdı:"},{"n":24,"t":"\"Ben sizin en yüce Rabbinizim!\" dedi."},{"n":25,"t":"Allâh da onu, sonun ve ilkin (âhiretin ve dünyânın) azâbıyle cezâlandırdı."},{"n":26,"t":"Şüphesiz bunda (Allah’tan) korkacak kimse için ibret vardır."},{"n":27,"t":"Yaratılışça siz mi daha çetinsiniz, yoksa gök mü? (Allâh) onu yaptı."},{"n":28,"t":"Kalınlığını (tavanını) yükseltti, onu düzenledi."},{"n":29,"t":"Gecesini örtüp kararttı, kuşluğunu (güneşinin ışığını) açığa çıkardı."},{"n":30,"t":"Bundan sonra da yeri yayıp yuvarlattı."},{"n":31,"t":"Ondan suyunu ve otlağını çıkardı,"},{"n":32,"t":"Dağları oturttu,"},{"n":33,"t":"Sizin ve hayvanlarınızın geçimi için."},{"n":34,"t":"Herşeyi bastıran o büyük felâket geldiği zaman,"},{"n":35,"t":"O gün insan, neyin peşinde koşmuş olduğunu hatırlar."},{"n":36,"t":"Gören kimseler için cehennem ortaya çıkarılmıştır."},{"n":37,"t":"Artık kim azmışsa,"},{"n":38,"t":"Ve şu yakın hayâtı yeğlemişse,"},{"n":39,"t":"Onun barınağı cehennemdir."},{"n":40,"t":"Ama kim Rabbinin divânında dur(up hesap ver)mekten korkmuş ve nefsi(ni) kötü heves(ler)den men etmişse"},{"n":41,"t":"Onun barınağı da cennettir."},{"n":42,"t":"Sana sâ’atden soruyorlar: Demir atması (gelip çatması) ne zaman diye."},{"n":43,"t":"Sen nerede, onun vaktini söylemek nerede?!"},{"n":44,"t":"Onun bilgisi Rabbine âittir."},{"n":45,"t":"Sen ancak, ondan korkacak olanları uyarıcısın."},{"n":46,"t":"Onlar onu gördükleri zaman sanki (dünyâda) bir akşam veya onun kuşluk vaktinden fazla kalmamış gibi olurlar."}],[{"n":1,"t":"Surat astı ve döndü;"},{"n":2,"t":"Kör geldi diye."},{"n":3,"t":"Ne bilirsin belki o arınacak?"},{"n":4,"t":"Yahut öğüt dinleyecek de öğüt, kendisine yarayacak."},{"n":5,"t":"Kendisini zengin görüp tenezzül etmeyene gelince;"},{"n":6,"t":"Sen ona yöneliyorsun."},{"n":7,"t":"Onun arınmamasından sana ne?"},{"n":8,"t":"Fakat koşarak sana gelen,"},{"n":9,"t":"Saygılı olarak gelmişken,"},{"n":10,"t":"Sen onunla ilgilenmiyorsun."},{"n":11,"t":"Hayır (olmaz böyle şey); o (âyetler), bir hatırlatmadır."},{"n":12,"t":"Dileyen onu düşünüp öğüt alır."},{"n":13,"t":"(O öğüt) Sahifeler içindedir: Değer verilen,"},{"n":14,"t":"Saygı ile yükseltilen, tertemiz (sayfalar)"},{"n":15,"t":"Yazıcıların ellerinde:"},{"n":16,"t":"Değerli, iyi (yazıcıların)."},{"n":17,"t":"Kahrolası insan, ne kadar da nânkördür!"},{"n":18,"t":"(Allâh) Onu hangi şeyden yarattı?"},{"n":19,"t":"Nutfe (sperm)den. Onu yarattı, ona biçim verdi."},{"n":20,"t":"Sonra ona yolu kolaylaştırdı."},{"n":21,"t":"Sonra onu öldürdü, kabre koydurdu."},{"n":22,"t":"Sonra dilediği zaman onu diriltip kaldırdı."},{"n":23,"t":"Hayır, insan, O’nun kendisine emrettiğini yapmadı."},{"n":24,"t":"İnsan şu yiyeceğine baksın."},{"n":25,"t":"Biz suyu iyice döktük."},{"n":26,"t":"Sonra toprağı güzelce yardık da,"},{"n":27,"t":"Orada bitirdik: Dâne,"},{"n":28,"t":"Üzüm, yonca,"},{"n":29,"t":"Zeytin, hurma,"},{"n":30,"t":"İri ve gür bahçeler,"},{"n":31,"t":"Meyva ve çayır;"},{"n":32,"t":"Sizin ve hayvanlarınızın geçimi için."},{"n":33,"t":"Çarpınca kulakları sağır eden o gürültü geldiği zaman,"},{"n":34,"t":"İşte o gün kişi kaçar: kardeşinden,"},{"n":35,"t":"Anasından, babasından,"},{"n":36,"t":"Eşinden ve oğullarından."},{"n":37,"t":"O gün, onlardan her kişinin, kendisine yeter derecede işi vardır."},{"n":38,"t":"Yüzler var ki o gün parıl parıl,"},{"n":39,"t":"Güleç, sevinçli."},{"n":40,"t":"Yüzler de var ki o gün tozlanmış."},{"n":41,"t":"Onları karanlık bürümüş (öylesine üzgün, öylesine dertli)."},{"n":42,"t":"İşte onlar kâfirler, Hak’tan sapanlardır."}],[{"n":1,"t":"Güneş büzüldüğü zaman,"},{"n":2,"t":"Yıldızlar kararıp döküldüğü zaman,"},{"n":3,"t":"Dağlar yürütüldüğü zaman,"},{"n":4,"t":"On aylık gebe develer başı boş bırakıldığı zaman,"},{"n":5,"t":"Vahşi hayvanlar bir araya toplandığı zaman,"},{"n":6,"t":"Denizler kaynatıldığı zaman,"},{"n":7,"t":"Nefisler çiftleştirildiği zaman."},{"n":8,"t":"Ve sorulduğu zaman o diri diri toprağa gömülen kıza:"},{"n":9,"t":"\"Hangi günâh(ı) yüzünden öldürüldü?\" diye."},{"n":10,"t":"(Amel) defterler(i) açılıp yayıldığı zaman,"},{"n":11,"t":"Gök sıyrılıp açıldığı zaman,"},{"n":12,"t":"Cehennem alevlendirildiği zaman,"},{"n":13,"t":"Cennet yaklaştırıldığı zaman,"},{"n":14,"t":"Her can, ne yapıp getirdiğini bilir."},{"n":15,"t":"Yoo, yemin ederim o geri kalıp gizlenenlere;"},{"n":16,"t":"Akıp gidenlere, dönüp saklananlara,"},{"n":17,"t":"Sırtını dönen geceye,"},{"n":18,"t":"Soluk almağa başlayan sabaha,"},{"n":19,"t":"(Andolsun bunlara) Ki o, değerli bir elçinin (Cebrâil’in) sözüdür."},{"n":20,"t":"(O elçi,) Güçlüdür, Arşın sâhibi (Allâh) katında yücedir."},{"n":21,"t":"Orada (kendisine) itâ’at edilen, güvenilendir."},{"n":22,"t":"Arkadaşınız cinli değildir."},{"n":23,"t":"Andolsun (Muhammed) onu apaçık ufukta görmüştür."},{"n":24,"t":"O, gayb hakkında (verdiği haberlerden dolayı) suçlanamaz."},{"n":25,"t":"O (Kur’ân) kovulmuş şeytânın sözü değildir."},{"n":26,"t":"O halde nereye gidiyorsunuz?"},{"n":27,"t":"O, âlemlere öğüttür."},{"n":28,"t":"Aranızdan doğru hareket etmek isteyen için;"},{"n":29,"t":"Âlemlerin Rabbi Allâh dilemedikçe siz dileyemezsiniz."}],[{"n":1,"t":"Gök yarıldığı zaman,"},{"n":2,"t":"Yıldızlar saçıldığı zaman,"},{"n":3,"t":"Denizler fışkırtıldığı zaman,"},{"n":4,"t":"Kabirlerin içi dışına getirildiği zaman,"},{"n":5,"t":"Her can, ne (yapıp) öne sürdüğünü ve ne (yapmayıp) geride bıraktığını bilir."},{"n":6,"t":"Ey insan, seni engin kerem sâhibi Rabbine karşı ne aldatıp isyâna sürükledi?"},{"n":7,"t":"O (Rab) ki seni yarattı, seni düzenledi, sana ölçülü bir biçim verdi."},{"n":8,"t":"Seni(n organlarını) dilediği şekilde birbirine ekledi."},{"n":9,"t":"Hayır, (bu gururunuzun sebebi şudur) siz cezâ (görme)yi yalanlıyorsunuz."},{"n":10,"t":"Oysa üzerinizde koruyucu (yaptıklarınızı zabtedici melek)ler vardır;"},{"n":11,"t":"Değerli yazıcılar,"},{"n":12,"t":"Yaptığınız herşeyi bilirler."},{"n":13,"t":"İyiler ni’met içindedirler."},{"n":14,"t":"Kötüler de yakıcı ateş içindedirler."},{"n":15,"t":"Cezâ günü oraya girerler."},{"n":16,"t":"Onlar ondan (hiçbir yere kaçıp) kaybolacak değillerdir."},{"n":17,"t":"Cezâ gününün ne olduğunu sen nereden bileceksin?"},{"n":18,"t":"Ve yine cezâ gününün ne olduğunu sen nereden bileceksin?"},{"n":19,"t":"O, kimsenin kimseye yardım edemeyeceği bir gündür! O gün buyruk, yalnız Allah’ındır."}],[{"n":1,"t":"Ölçü ve tartıda hile yapanların vay haline!"},{"n":2,"t":"Onlar insanlardan bir şey ölçüp aldıkları zaman ölçüyü tam yaparlar."},{"n":3,"t":"Kendileri onlara bir şey ölçtükleri veya tarttıkları zaman (ölçü ve tartıyı) eksik yaparlar."},{"n":4,"t":"Onlar, tekrar diriltileceklerini sanmıyorlar mı?"},{"n":5,"t":"Büyük bir gün için,"},{"n":6,"t":"Ki o gün insanlar, âlemlerin Rabbinin divânında dururlar."},{"n":7,"t":"Hayır, (ölçü ve tartıda hile yapılamaz), doğrusu sapanların yazıcısı Siccin (aşağı zindan)dadır."},{"n":8,"t":"Siccin’in ne olduğunu sen nereden bileceksin?"},{"n":9,"t":"Yazılmış bir Kitâptır."},{"n":10,"t":"Yalanlayanların vay haline o gün!"},{"n":11,"t":"Onlar cezâ gününü yalanlamaktadırlar."},{"n":12,"t":"Onu, saldırgan, günâhkârdan başkası yalanlamaz."},{"n":13,"t":"Ona âyetlerimiz okunduğu zaman: \"Eskilerin masalları\" der."},{"n":14,"t":"Hayır, doğrusu, onların işleyip kazandıkları şeyler, kalblerinin üzerine pas olmuştur."},{"n":15,"t":"Hayır, doğrusu onlar, o gün Rablerinden perdelenmişlerdir."},{"n":16,"t":"Sonra onlar, elbette cehenneme gireceklerdir."},{"n":17,"t":"Sonra da: \"İşte yalanlamakta olduğunuz şey budur!\" denilecektir."},{"n":18,"t":"Hayır, iyilerin yazısı İlliyyin (yüceler)dedir."},{"n":19,"t":"İlliyyin (yüceler)in ne olduğunu sen nereden bileceksin?"},{"n":20,"t":"Yazılmış bir Kitâptır."},{"n":21,"t":"(Allah’a) Yaklaştırılmış olanlar, ona tanık olurlar."},{"n":22,"t":"İyiler elbette ni’met içindedirler."},{"n":23,"t":"Divânlar üzerinde oturup bakarlar."},{"n":24,"t":"Yüzlerinde ni’metin sevinç ve parıltısını sezersin."},{"n":25,"t":"Onlara, mühürlü, hâlis bir şaraptan içirilir,"},{"n":26,"t":"Ki sonu misktir (içildikten sonra misk gibi kokar). İşte yarışanlar, bunun için yarışsınlar."},{"n":27,"t":"Karışımı tesnimdendir."},{"n":28,"t":"Bir çeşme ki (Allah’a) yaklaştırılanlar ondan içerler."},{"n":29,"t":"Suç işleyenler, inananların üstüne gülerlerdi."},{"n":30,"t":"Onların yanından geçtikleri zaman birbirlerine kaş göz eder(ek onları küçümser)lerdi."},{"n":31,"t":"Âilelerine döndükleri zaman da (yaptıklarıyle övünüp) eğlenmeye başlarlardı."},{"n":32,"t":"İnananları gördüklerinde: \"Şunlar sapık insanlar\" derlerdi."},{"n":33,"t":"Oysa kendileri, onların üzerine bekçi gönderilmemişlerdi."},{"n":34,"t":"İşte bugün de inananlar kâfirlerin üstüne gülerler."},{"n":35,"t":"Divânlar üzerinde (oturup) bakarlar:"},{"n":36,"t":"\"Kâfirler, yaptıklarıyle cezâlandılar mı?\" diye."}],[{"n":1,"t":"Gök yarıldığı,"},{"n":2,"t":"Kendisine yaraştığı üzere Rabbini(n buyruğunu) dinlediği zaman!"},{"n":3,"t":"Yer uzatıl(ıp dümdüz yapıl)dığı,"},{"n":4,"t":"İçindekileri dışarı atıp boşaldığı,"},{"n":5,"t":"Ve kendisine yaraştığı üzere Rabbini(n buyruğunu) dinlediği zaman!"},{"n":6,"t":"Ey insan, sen, Rabbine varan yolda çabalayıp durmaktasın, nihâyet O’na varacaksın."},{"n":7,"t":"(O zaman) Kimin Kitabı sağından verilirse:"},{"n":8,"t":"O, kolay bir hesaba çekilecek,"},{"n":9,"t":"Ve sevinçli olarak âilesine dönecektir."},{"n":10,"t":"Kimin Kitabı arka tarafından verilirse."},{"n":11,"t":"O, ölümü çağıracak,"},{"n":12,"t":"Ve alevli ateşe girecektir."},{"n":13,"t":"Çünkü o, (dünyâda) âilesi arasında (şımarık ve) sevinçli idi."},{"n":14,"t":"O, hiç (Rabbine) dönmeyeceğini sanmıştı."},{"n":15,"t":"Hayır, Rabbi O’nu görmekte idi."},{"n":16,"t":"Yoo, and içerim; akşamın alaca karanlığına,"},{"n":17,"t":"Geceye ve (gecenin bağrında) topladığı şeylere,"},{"n":18,"t":"Değirmileşen aya,"},{"n":19,"t":"Ki, siz, mutlaka tabakadan tabakaya bineceksiniz!"},{"n":20,"t":"Onların nesi var ki inanmıyorlar?"},{"n":21,"t":"Kendilerine Kur’ân okunduğu zaman secde etmiyorlar?"},{"n":22,"t":"Tersine o nânkörler yalanlıyorlar."},{"n":23,"t":"Allâh onların, içlerinde gizledikleri (düşünceleri) biliyor."},{"n":24,"t":"Onlara acı bir azâbı müjdele."},{"n":25,"t":"Ancak inanıp yararlı işler yapan kimseler için kesintisiz bir mükâfât vardır."}],[{"n":1,"t":"Burçlar sâhibi göğe andolsun,"},{"n":2,"t":"Va’dedilen güne andolsun,"},{"n":3,"t":"(O gün) Şâhide ve şâhidlik edilene andolsun,"},{"n":4,"t":"Ki kahroldu o hendeğin adamları"},{"n":5,"t":"O yakıt doldurulup tutuşturulmuş ateş (hendeğinin adamları)!"},{"n":6,"t":"Onlar, o (ateş hendeği)nin başında oturmuşlardı."},{"n":7,"t":"Ve onlar, mü’minlere yaptıklarını seyrediyorlardı."},{"n":8,"t":"Mü’minler sırf aziz, övgüye lâyık Allah’a inandıkları için o (zâlim)ler onlardan öç aldılar."},{"n":9,"t":"O (Allah) ki göklerin ve yerin hükümranlığı O’nundur. Allâh, her şeye tanıktır."},{"n":10,"t":"İnanmış erkek ve kadınlara işkence edip sonra (yaptıklarına) tevbe etmeyenler (yok mu), onlar için cehennem azâbı vardır ve onlar için yangın azâbı vardır."},{"n":11,"t":"İnanan ve iyi işler yapan kimseler için de altlarından ırmaklar akan cennetler vardır. İşte büyük başarı budur."},{"n":12,"t":"Şüphesiz Rabbinin tutuşu şiddetlidir."},{"n":13,"t":"İlkin var eden, sonra geri çevirip yeniden yaratan O’dur."},{"n":14,"t":"O bağışlayandır, sevendir."},{"n":15,"t":"Arş’ın sâhibidir, yücedir."},{"n":16,"t":"İstediğini yapandır."},{"n":17,"t":"O orduların haberi sana geldi mi?"},{"n":18,"t":"(Yani) Fir’avn ve Semûd (kavimlerin)in?"},{"n":19,"t":"Doğrusu, nânkörler bir yalanlama içindedirler."},{"n":20,"t":"Allâh ise onları arkalarından kuşatmıştır."},{"n":21,"t":"Hayır, (Kur’ân, onların dedikleri gibi bir söz değil), o şerefli bir Kur’ân’dır."},{"n":22,"t":"Korunan bir levhada (yazılı)dır."}],[{"n":1,"t":"Göğe ve târık’a andolsun."},{"n":2,"t":"Târık’ın ne olduğunu sen nereden bileceksin?"},{"n":3,"t":"Parlayan yıldızdır."},{"n":4,"t":"Hiçbir can yoktur ki başında bir koruyucu (bekçi) olmasın."},{"n":5,"t":"İnsan neden yaratıldığına bir baksın:"},{"n":6,"t":"Atılan bir sudan yaratıldı."},{"n":7,"t":"Bel ile kaburga kemikleri arasından çıkan (bir sudan)."},{"n":8,"t":"O (Allâh), onu tekrar döndür(üp yarat)mağa kâdirdir."},{"n":9,"t":"Gizlilerin (ortaya dökülüp) yoklanacağı gün,"},{"n":10,"t":"İnsanın ne bir gücü, ne de bir yardımcısı vardır."},{"n":11,"t":"Dönüşlü göğe andolsun,"},{"n":12,"t":"(Bitkilerin çıkması için) Çatlayan yere andolsun ki,"},{"n":13,"t":"O (Kur’ân), elbette (hak ile bâtılı) ayırdedici bir sözdür."},{"n":14,"t":"O, şaka değildir."},{"n":15,"t":"Onlar (onu iptal etmek için) bir tuzak kuruyorlar."},{"n":16,"t":"Ben de (onları yakalamak için) bir tuzak kuruyorum."},{"n":17,"t":"Hele sen o kâfirlere mühlet ver, biraz bırak onları (bildiklerine gitsinler)."}],[{"n":1,"t":"Rabbinin yüce adını tesbih et (O’nun eksikliklerden uzak olduğunu an)."},{"n":2,"t":"O ki (her şeyi) yarattı, düzenledi."},{"n":3,"t":"Ve O ki herşeyin miktarını, biçimini belirleyip hedefini gösterdi."},{"n":4,"t":"Ve O ki otlağı çıkardı,"},{"n":5,"t":"Sonra da onu kupkuru, siyah bir çöpe çevirdi."},{"n":6,"t":"Sana (Kur’ân’ı), okutacağız, unutmayacaksın."},{"n":7,"t":"Yalnız Allâh’ın dilediğini unutursun. O, açığı da bilir, gizli olanı da."},{"n":8,"t":"Seni en kolay yola muvaffak edeceğiz."},{"n":9,"t":"O halde eğer hatırlatmak yarar verirse hatırlat, öğüt ver."},{"n":10,"t":"(Allah’a) Saygılı olan hatırlar (öğüt alır)."},{"n":11,"t":"Bahtsız olan da ondan kaçınır."},{"n":12,"t":"O da en büyük ateşe girer."},{"n":13,"t":"Sonra orada ne ölür, ne de yaşar."},{"n":14,"t":"Doğrusu, mutluluğa ermiştir zekât veren;"},{"n":15,"t":"Rabbinin adını anıp namaz kılan."},{"n":16,"t":"Ama siz, şu yakın hayâtı yeğliyorsunuz."},{"n":17,"t":"Oysa âhiret daha iyi ve daha kalıcıdır."},{"n":18,"t":"Bu (hükümler), elbette ilk sahifelerde de vardı:"},{"n":19,"t":"İbrâhim’in ve Mûsâ’nn sayfalarında."}],[{"n":1,"t":"(Şiddet ve dehşetiyle her şeyi) Sarıp kaplayacak olan(o felâket)in haberi sana geldi mi?"},{"n":2,"t":"Yüzler var ki o gün öne düşüktür,"},{"n":3,"t":"Çalışır, yorulur."},{"n":4,"t":"Kızgın ateşe girerler."},{"n":5,"t":"Kendilerine kaynamış bir gözeden (su) içirilir."},{"n":6,"t":"Onlar için kuru dikenden başka yiyecek de yoktur."},{"n":7,"t":"O da ne semirtir, ne de açlığı giderir."},{"n":8,"t":"Yüzler de var ki o gün ni’met içinde mutlu,"},{"n":9,"t":"İşinden memnun,"},{"n":10,"t":"Yüksek bir bahçededir."},{"n":11,"t":"Orada boş söz işitmezler."},{"n":12,"t":"Orada akan bir kaynak vardır."},{"n":13,"t":"Orada yükseltilmiş tahtlar,"},{"n":14,"t":"Konulmuş kadehler,"},{"n":15,"t":"Dizilmiş yastıklar,"},{"n":16,"t":"Serilmiş halılar vardır."},{"n":17,"t":"Bakmıyorlar mı develere, nasıl yaratılmış?"},{"n":18,"t":"Göğe, nasıl yükseltilmiş?"},{"n":19,"t":"Dağlara, nasıl dikilmiş?"},{"n":20,"t":"Yere, nasıl yayılıp döşenmiş?"},{"n":21,"t":"Öğüt ver, çünkü sen ancak öğüt verensin."},{"n":22,"t":"Onların üzerinde zorlayıcı değilsin."},{"n":23,"t":"Ancak kim yüz çevirir ve inanmazsa,"},{"n":24,"t":"Allâh ona en büyük azâbı eder,"},{"n":25,"t":"Dönüşleri Bizedir."},{"n":26,"t":"Sonra onların hesabını görmek Bize düşer."}],[{"n":1,"t":"Andolsun fecre (tan yeri ağarmasına),"},{"n":2,"t":"On geceye,"},{"n":3,"t":"Çift’e ve tek’e,"},{"n":4,"t":"Gitmekte olan geceye."},{"n":5,"t":"Bu (anıla)n (şeyler)de akıl sâhibi için bir yemin var, değil mi? (İşte bunlara andolsun ki kâfirler mutlaka azâba uğrayacaklardır!)"},{"n":6,"t":"Görmedin mi Rabbin ne yaptı Âd (kavmin)e?"},{"n":7,"t":"Sütunlu İrem’e?"},{"n":8,"t":"Ki ülkeler arasında onun eşi yaratılmamıştı."},{"n":9,"t":"Vâdi(’l-Kurâ)da kayaları oya(rak evler yapa)n Semûd (kavmin)e?"},{"n":10,"t":"Ve kazıklar sâhibi Fir’avn’a?"},{"n":11,"t":"Bunlar ülkelerde azmışlardı."},{"n":12,"t":"Oralarda çok kötülük etmişlerdi."},{"n":13,"t":"Bu yüzden Rabbin onların üzerine azâb kırbacını çarptı."},{"n":14,"t":"Elbette Rabbin gözetleme yerindedir (her an kullarının fiillerini gözetlemektedir)."},{"n":15,"t":"Fakat insan öyledir; Rabbi ne zaman kendisini sınayıp ona ikrâmda bulunur, ona ni’met verirse: \"Rabbim bana ikrâm etti\" der."},{"n":16,"t":"Ama Rabbi onu sınayıp rızkını daraltırsa: \"Rabbim beni alçalttı (perişan etti)\" der."},{"n":17,"t":"Hayır, doğrusu siz (Allah’tan ikrâm bekliyorsunuz ama kendiniz) yetime ikrâm etmiyorsunuz."},{"n":18,"t":"Yoksula yedirmeğe teşvik etmiyorsunuz."},{"n":19,"t":"Mirâsı hırsla yutuyorsunuz."},{"n":20,"t":"Malı pek çok seviyorsunuz."},{"n":21,"t":"Hayır, yer birbiri ardınca sarsılıp dümdüz edildiği zaman,"},{"n":22,"t":"Melekler sıra sıra dizili durumda Rabbin geldiği zaman."},{"n":23,"t":"Ve cehennem de getirildiği zaman. İşte o gün insan anlar, ama artık anlamanın kendisine ne yararı var?"},{"n":24,"t":"(O zaman insan): \"Âh, keşke ben bu hayâtım için (iyi işler yapıp) gönderseydim!\" der."},{"n":25,"t":"O gün O’nun yapacağı azâbı kimse yapamaz."},{"n":26,"t":"Ve O’nun vuracağı bağı kimse vuramaz!"},{"n":27,"t":"Ey huzûra eren nefis!"},{"n":28,"t":"Râzı edici ve râzı edilmiş olarak Rabbine dön!"},{"n":29,"t":"(İyi) Kullarım arasına gir!"},{"n":30,"t":"Cennetime gir!"}],[{"n":1,"t":"Yoo, and içerim bu kente,"},{"n":2,"t":"Ki sen bu şehire girmekte (burada yaşamakta)sın."},{"n":3,"t":"Ve (and içerim) doğurucuya ve doğurduğuna ki,"},{"n":4,"t":"Biz insanı zorluk arasında yarattık."},{"n":5,"t":"İnsan, hiç kimsenin kendisine güç yetiremeyeceğini mi sanıyor?"},{"n":6,"t":"(Gösteriş ve övünme için) \"Ben birçok mal telef ettim\" diyor."},{"n":7,"t":"Kimsenin kendisini görmediğini mi sanıyor?"},{"n":8,"t":"Biz ona vermedik mi: İki göz"},{"n":9,"t":"Bir dil, iki dudak?"},{"n":10,"t":"Ona iki tepeyi (anasının iki memesini emmenin veya hayır ve şerrin yolunu) gösterdik."},{"n":11,"t":"Fakat o, sarp yokuşa atılamadı."},{"n":12,"t":"Sarp yokuşun ne olduğunu sen nereden bileceksin?"},{"n":13,"t":"Bir boynu (kölelik zincirinden) çözmek,"},{"n":14,"t":"Yahut açlık gününde doyurmaktır:"},{"n":15,"t":"Akrabâ olan yetimi,"},{"n":16,"t":"Yahut hiçbir şeyi olmayan yoksulu."},{"n":17,"t":"Sonra inanıp birbirlerine sabır tavsiye eden ve merhamet tavsiye edenlerden olmak."},{"n":18,"t":"İşte onlar sağın adamlarıdır (Kitabı sağından verilen uğurlu kişilerdir)."},{"n":19,"t":"Âyetlerimizi tanımayanlar ise solun adamlarıdır (Kitabı solundan verilen uğursuz kişilerdir)."},{"n":20,"t":"Onlara (kapıları) üzerlerine kilitlenecek bir ateş vardır!"}],[{"n":1,"t":"Güneşe ve onun aydın sabahına andolsun,"},{"n":2,"t":"Onu izleyen aya andolsun,"},{"n":3,"t":"Güneşi ortaya çıkaran gündüze andolsun."},{"n":4,"t":"Onu örten geceye andolsun."},{"n":5,"t":"Göğe ve onu yapana andolsun."},{"n":6,"t":"Yere ve onu yuvarlayıp döşeyene andolsun."},{"n":7,"t":"Nefse ve onu biçimlendirene,"},{"n":8,"t":"Ona bozukluğunu ve korunmasını (isyânını ve itâ’atini) ilhâm edene andolsun ki:"},{"n":9,"t":"(Allâh’tan başkasına tapmayarak) Nefsini yücelten kazanmış,"},{"n":10,"t":"(Yaratıklara taparak) Onu alçaltan da ziyana uğramıştır."},{"n":11,"t":"Semûd (kavmi), azgınlığı yüzünden (Hakk’ı) yalanladı."},{"n":12,"t":"En haydutları ayaklandığı zaman,"},{"n":13,"t":"Allâh’ın elçisi onlara: \"Allâh’ın devesine ve onun su içme hakkına dokunmayın!\" demişti."},{"n":14,"t":"Onu yalanladılar, deveyi kestiler. Rableri de, günâhları yüzünden azâbı başlarına geçirip, orayı dümdüz etti."},{"n":15,"t":"(Rab) Bu işin sonundan korkmaz."}],[{"n":1,"t":"Örttüğü zaman geceye andolsun,"},{"n":2,"t":"Göründüğü zaman gündüze andolsun,"},{"n":3,"t":"Erkeği ve dişiyi yaratana andolsun ki,"},{"n":4,"t":"Sizin işiniz çeşit çeşittir:"},{"n":5,"t":"Kim (hayır için) verir, korunursa,"},{"n":6,"t":"Ve en güzel (söz)ü doğrularsa,"},{"n":7,"t":"Ona en kolay (yolda gitmey)i kolaylaştırırız."},{"n":8,"t":"Kim de cimrilik eder, kendini zengin (ve kendine yeterli) görürse,"},{"n":9,"t":"Ve en güzel (söz)ü de yalanlarsa,"},{"n":10,"t":"Ona da en güç (yolda gitmey)i kolaylaştırırız."},{"n":11,"t":"Çukura düştüğü zaman malı ona hiçbir fayda sağlamaz."},{"n":12,"t":"Doğru yola iletmek bize âittir."},{"n":13,"t":"Son da ilk de (âhiret de dünyâ da) bizimdir."},{"n":14,"t":"Ben sizi alev saçan bir ateşe karşı uyardım."},{"n":15,"t":"Ona ancak haydut olan girer."},{"n":16,"t":"O ki, yalanlandı ve sırtını döndü."},{"n":17,"t":"En çok korunan da ondan uzak tutulur."},{"n":18,"t":"O ki malını hayra vererek arınır, yücelir."},{"n":19,"t":"Ve onun yanında, hiç kimsenin karşılık verilecek bir ni’meti yoktur (o, verdiğini kendisine yapılan bir iyiliğin karşılığı olarak değil),"},{"n":20,"t":"Yalnız yüce Rabbinin rızâsı için verir."},{"n":21,"t":"Yakında kendisi de (Allâh’ın verceği ni’metle) râzı olacaktır."}],[{"n":1,"t":"Kuşluk vaktine andolsun,"},{"n":2,"t":"Sâkinleşen geceye andolsun ki,"},{"n":3,"t":"Rabbin, seni bırakmadı ve sana darılmadı."},{"n":4,"t":"Senin sonun, ilkinden iyi olacaktır."},{"n":5,"t":"Rabbin, sana verecek ve sen râzı olacaksın."},{"n":6,"t":"O, seni yetim bulup barındırmadı mı?"},{"n":7,"t":"Seni şaşırmış bulup yola iletmedi mi?"},{"n":8,"t":"Seni fakir bulup zengin etmedi mi?"},{"n":9,"t":"Öyleyse sakın öksüzü ezme,"},{"n":10,"t":"Dilenciyi azarlama."},{"n":11,"t":"Ve Rabbinin ni’metini anlat."}],[{"n":1,"t":"Biz senin (bunalan) göğsünü açmadık mı (ondaki bunalımları, sıkıntıları giderip, onu ilim, hikmet ve huzur ile genişletmedik mi)?"},{"n":2,"t":"Ve atmadık mı senin üzerinden yükünü?"},{"n":3,"t":"Ki (o, ağırlığından) sırtını çatırdatmıştı!"},{"n":4,"t":"Senin şânını yükseltmedik mi?"},{"n":5,"t":"Muhakkak her güçlükle beraber bir kolaylık vardır."},{"n":6,"t":"Evet, her güçlükle beraber bir kolaylık vardır."},{"n":7,"t":"O halde (işlerinden) boşaldığın zaman (ibâdete) dur."},{"n":8,"t":"Rabb’ine niyaz et, yalvar."}],[{"n":1,"t":"Tin’e ve Zeytûn’a andolsun."},{"n":2,"t":"Sinâ Dağına andolsun."},{"n":3,"t":"Ve bu güvenli Şehre andolsun ki,"},{"n":4,"t":"Biz insanı en güzel biçimde yarattık."},{"n":5,"t":"Sonra onu aşağıların aşağısına çevirdik."},{"n":6,"t":"Yalnız inanıp iyi işler yapanlar hariç. Onlar için kesintisiz bir mükâfât vardır."},{"n":7,"t":"Böyle iken sana âhiret cezâsını yalanlatan nedir?"},{"n":8,"t":"Allâh, hüküm verenlerin en iyisi değil midir?"}],[{"n":1,"t":"Yaratan Rabbinin adıyle oku."},{"n":2,"t":"O, insanı alaktan (embriyodan) yarattı."},{"n":3,"t":"Oku, Rabbin en büyük kerem sâhibidir."},{"n":4,"t":"O ki kalemle (yazmayı) öğretti."},{"n":5,"t":"İnsana bilmediğini öğretti."},{"n":6,"t":"Hayır, (Rabbinin bu kadar iyiliğine rağmen yine) insan azar;"},{"n":7,"t":"Kendini zengin (kendine yeterli) gördüğü için,"},{"n":8,"t":"Ama dönüş Rabbinedir (O’nun huzurunda bu azgınlığının hesabını verecektir)."},{"n":9,"t":"Gördün mü şu men edeni?"},{"n":10,"t":"Namaz kılarken bir kulu (namazdan)?"},{"n":11,"t":"Gördün mü, ya o (kul) doğru yolda olur,"},{"n":12,"t":"Yahut kötülüklerden korunmayı emrederse?"},{"n":13,"t":"Gördün mü, ya bu (adam, hakkı) yalanlar yüz çevirirse? (O zaman bu yaptığı kendisi için iyi mi olur?)"},{"n":14,"t":"Allâh’ın (dâimâ kendisini) gördüğünü bilmedi mi (o)?"},{"n":15,"t":"Hayır, (olmaz böyle şey), eğer bundan vazgeçmezse (onu) perçem(in)den yakalar (ateşe sürükler)iz,"},{"n":16,"t":"O yalancı, günâhkâr perçem(den)!"},{"n":17,"t":"O zaman (o gitsin) de meclisini (adamlarını) çağırsın."},{"n":18,"t":"Biz de zebânileri çağıracağız."},{"n":19,"t":"Hayır, ona boyun eğme; (Rabbine) secde et ve yaklaş!"}],[{"n":1,"t":"Biz o(Kur’â)n’ı Kadir gecesinde indirdik."},{"n":2,"t":"Kadir gecesinin ne olduğunu sen nereden bileceksin?"},{"n":3,"t":"Kadir gecesi bin aydan hayırlıdır."},{"n":4,"t":"Melekler ve Rûh, o gece Rab’lerinin izniyle her iş için iner de iner."},{"n":5,"t":"Esenliktir o, tâ tan yeri ağarıncaya kadar!"}],[{"n":1,"t":"Kitap ehlinden ve müşriklerden (hakk’ı) tanımayanlar, kendilerine açık kanıt gelinceye dek (halleri üzere) bırakılacak değillerdi (mutlaka kendilerine açıklama gelecekti)."},{"n":2,"t":"(Yani) Allâh tarafından gönderilen ve tertemiz sahifeler okuyan bir elçi."},{"n":3,"t":"O sahifelerde doğru, değerli Kitaplar vardır."},{"n":4,"t":"Kitap verilmiş olanlar, ancak kendilerine açık kanıt geldikten sonra ayrılığa düştüler."},{"n":5,"t":"Oysa kendilerine, dini yalnız Allah’a hâlis kılıp O’nu birleyerek Allah’a kulluk etmeleri, namazı kılmaları, zekâtı vermeleri emredilmişti. İşte doğru din oydu."},{"n":6,"t":"Kitap ehlinden ve (Allah’a) ortak koşanlardan olan nânkörler, sürekli olarak cehennem ateşindedirler. Onlar, halkın en şerlisidir."},{"n":7,"t":"İnanıp iyi işler yapanlar da halkın en hayırlısıdır."},{"n":8,"t":"Rableri katında onların mükâfâtı altlarından ırmaklar akan, içinde ebedi kalacakları, Adn cennetleridir. Allâh onlardan râzı olmuş, onlar da O’ndan râzı olmuşlardır. Bu, Rabbine saygı gösterene mahsustur."}],[{"n":1,"t":"Yer o yaman sarsıntı ile sarsıldığı,"},{"n":2,"t":"Yer (bağrındaki) ağırlıklarını çıkardığı,"},{"n":3,"t":"Ve insan: \"Ona ne oluyor?\" dediği zaman!"},{"n":4,"t":"İşte o gün (yer), haberlerini söyler."},{"n":5,"t":"Çünkü Rabbin ona vahyetmiştir (onun için başından geçenleri anlatır)."},{"n":6,"t":"O gün insanlar, ayrı ayrı gruplar halinde (Yüce Divâna) çıkarlar ki, yaptıkları işler kendilerine gösterilsin."},{"n":7,"t":"Artık kim zerre ağırlığınca hayır yapmışsa onu görür."},{"n":8,"t":"Ve kim zerre ağırlığınca şer yapmışsa onu görür."}],[{"n":1,"t":"Andolsun nefesleriyle (güp güp) ses çıkararak koşan (at)lara,"},{"n":2,"t":"(Tırnaklariyle yerden) Ateş çıkaranlara,"},{"n":3,"t":"Sabahleyin akın edenlere,"},{"n":4,"t":"(Koşarak) Toz koparanlara,"},{"n":5,"t":"Derken bir topluluğun ortasına dalanlara."},{"n":6,"t":"(Bunlara andolsun) Ki insan, Rabbine karşı çok nânkördür."},{"n":7,"t":"Ve o da buna şâhiddir."},{"n":8,"t":"Doğrusu o, malı çok sever."},{"n":9,"t":"Bilmez mi o, kabirlerde olanlar dışarı atıldığı,"},{"n":10,"t":"Göğüslerde bulunanlar devşirildiği zaman,"},{"n":11,"t":"O gün Rabbleri onların her halini haber almış (gizli ve açık bütün yaptıklarını bilmiş)tir."}],[{"n":1,"t":"Çarpan olay!"},{"n":2,"t":"Nedir o çarpan olay?"},{"n":3,"t":"O çarpan olayın ne olduğunu sen nereden bileceksin?"},{"n":4,"t":"O gün insanlar, yayılmış pervâneler gibi olur(lar)."},{"n":5,"t":"Dağlar atılmış renkli yün gibi olur."},{"n":6,"t":"Kimin tartıları ağır gelirse,"},{"n":7,"t":"O, memmun edici bir hayât içindedir."},{"n":8,"t":"Kimin tartıları hafif gelirse,"},{"n":9,"t":"Onun anası (bağrına atılacağı) hâviye (uçurum)dur."},{"n":10,"t":"Onun ne olduğunu sen nereden bileceksin?"},{"n":11,"t":"Kızgın bir ateştir!"}],[{"n":1,"t":"Çokluk yarışı, sizi oyaladı,"},{"n":2,"t":"Nihâyet kabirleri ziyaret ettiniz (kabre girinceye kadar mal artırmağa çalıştınız)."},{"n":3,"t":"Hayır (olmaz bu), yakında bileceksiniz (hatânızı)!"},{"n":4,"t":"Yine hayır, yakında bileceksiniz (hatânızı)!"},{"n":5,"t":"Hayır, (gerçeği) kesin bilgi ile bilseydiniz;"},{"n":6,"t":"Mutlaka cehennemi görür (onun varlığını gözle görmüş gibi kabul eder)diniz."},{"n":7,"t":"Sonra onu kesin olarak gözle göreceksiniz."},{"n":8,"t":"Sonra o gün, (size verilen) ni’metten sorulacaksınız."}],[{"n":1,"t":"Asr’a andolsun ki,"},{"n":2,"t":"İnsan ziyandadır."},{"n":3,"t":"Ancak inanıp iyi işler yapanlar, birbirlerine hakkı tavsiye edenler ve birbirlerine sabrı tavsiye edenler ziyânda değillerdir."}],[{"n":1,"t":"(İnsanları) Diliyle çekiştiren, kaş ve gözüyle işâretler yapıp alay eden her fesâd kişinin vay haline!"},{"n":2,"t":"O ki mal yığdı, onu saydı durdu."},{"n":3,"t":"Malının, kendisini ebedi yaşatacağını sanıyor."},{"n":4,"t":"Hayır, andolsun ki o, Hutame’ye atılacaktır."},{"n":5,"t":"Hutame’nin ne olduğunu sen nereden bileceksin?"},{"n":6,"t":"Allâh’ın tutuşturulmuş ateşidir."},{"n":7,"t":"(Bir ateş) Ki gönüllere işler."},{"n":8,"t":"O, onların üzerine kapatılıp kilitlenecektir."},{"n":9,"t":"(Kendileri,) Uzatılmış direkler arasında (bağlı) olarak (kalacaklardır)."}],[{"n":1,"t":"Rabbinin, Fil sâhiplerine ne yaptığını görmedin m?"},{"n":2,"t":"Onların tuzaklarını boşa çıkarmadı mı?"},{"n":3,"t":"Üzerlerine sürü sürü kuşlar gönderdi,"},{"n":4,"t":"Onlara çamurdan sertleşmiş taşlar atan (kuşlar)."},{"n":5,"t":"Nihâyet onları, kurt yeniği ekin yaprağı gibi yaptı."}],[{"n":1,"t":"Kureyşi alıştırdığı için,"},{"n":2,"t":"Onları kış ve yaz yolculuğuna alıştırdığı için,"},{"n":3,"t":"Bu Ev (Ka’be’n)in Rabbine kulluk etsinler."},{"n":4,"t":"O ki onları yedirip açlıktan kurtardı ve onları korkudan güvene kavuşturdu."}],[{"n":1,"t":"Din (âhiret cezâsın)ı yalanlayan(adam)ı gördün mü?"},{"n":2,"t":"İşte o, öksüzü iter, kakar;"},{"n":3,"t":"Yoksulu doyurmağa önayak olmaz."},{"n":4,"t":"Şu namaz kılanların vay haline,"},{"n":5,"t":"Ki, onlar namazlarından gaflet ederler (kıldıkları namazın değerini bilmez, ona önem vermezler)."},{"n":6,"t":"Onlar gösteriş (için ibâdet) yaparlar."},{"n":7,"t":"En ufak bir yardımı esirgerler."}],[{"n":1,"t":"Biz sana Kevser’i (bol ni’met, ilim ve büyük şeref) verdik."},{"n":2,"t":"Öyleyse Rabbin için namaz kıl ve nahret (kurban kes veya ellerini boğazına kadar kaldırıp tekbir al)."},{"n":3,"t":"Asıl sonu kesik olan, sana buğzedendir."}],[{"n":1,"t":"De ki: Ey nânkörler,"},{"n":2,"t":"Ben sizin yaptığınız ibâdeti yapmam;"},{"n":3,"t":"Siz de benim yaptığım ibâdeti yapmazsınız."},{"n":4,"t":"Ben asla sizin yapmakta olduğunuz ibâdeti yapıcı değilim."},{"n":5,"t":"Siz de benim yapmakta olduğum ibâdeti yapıcı değilsiniz."},{"n":6,"t":"Sizin dininiz size, benim dinim banadır."}],[{"n":1,"t":"Allâh’ın yardımı ve fetih geldiği,"},{"n":2,"t":"Ve insanların dalga dalga Allâh’ın dinine girdiklerini gördüğün zaman,"},{"n":3,"t":"Rabbini överek tesbih et, O’ndan mağfiret dile. Çünkü O, tevbeyi kabul edendir."}],[{"n":1,"t":"Ebu Leheb’in iki eli kurusun (yok olsun o); zaten yok oldu ya."},{"n":2,"t":"Ne malı, ne de kazandığı onu (Allâh’ın kahrından) kurtaramadı."},{"n":3,"t":"Alevli bir ateşe girecektir (o)."},{"n":4,"t":"Karısı da, odun hamalı olarak."},{"n":5,"t":"Boynunda hurma lifinden bir ip olacaktır."}],[{"n":1,"t":"De ki: O Allâh birdir."},{"n":2,"t":"Allâh Samed’dir."},{"n":3,"t":"Kendisi doğurmamıştır ve doğurulmamıştır."},{"n":4,"t":"Hiçbir şey O’nun dengi olmamıştır."}],[{"n":1,"t":"De ki: Sığınırım ben, karanlığı yarıp sabahı ortaya çıkaran Rabbe;"},{"n":2,"t":"Yarattığı şeylerin şerrinden,"},{"n":3,"t":"Karanlığı çöktüğü zaman gecenin şerrinden,"},{"n":4,"t":"Düğümlere üfleyip tüküren büyücü kadınların şerrinden,"},{"n":5,"t":"Ve hased ettiği zaman hasedcinin şerrinden."}],[{"n":1,"t":"De ki: \"Sığınırım ben, insanların Rabbine."},{"n":2,"t":"İnsanların pâdişâhına,"},{"n":3,"t":"İnsanların Tanrısına:"},{"n":4,"t":"O sinsi vesvesecinin şerrinden."},{"n":5,"t":"O ki insanların göğüslerine (kötü düşünceler) fısıldar."},{"n":6,"t":"Gerek cinlerden, gerek insanlardan (olan bütün vesvesecilerin şerrinden Allah’a sığınırım)."}]];
